class CharacterAttackManager {
 public:
  // Constructor
  CharacterAttackManager() : energy_(50), last_attack_(0) {}

  // Method to perform a random attack
  void performRandomAttack() {
    // Check if the character can perform an attack based on the current energy level
    if (energy_ < minEnergyRequiredForAttack()) {
      std::cout << "Insufficient energy. The next attack can only be performed after 9 seconds." << std::endl;
      return;
    }

    // Select a random attack to perform
    bool canPerformBothAttacks = (energy_ >= minEnergyRequiredForAttack(1) && energy_ >= minEnergyRequiredForAttack(2));
    if (canPerformBothAttacks) {
      int selectedAttack = rand() % 2 + 1; // Select attack 1 or attack 2 randomly
      energy_ -= minEnergyRequiredForAttack(selectedAttack);
    } else {
      energy_ -= minEnergyRequiredForAttack(energy_ >= minEnergyRequiredForAttack(1) ? 1 : 2); // Select attack 1 or attack 2 based on the remaining energy level
    }

    // Print the selected attack number and the remaining energy level to the console
    std::cout << "Selected attack: " << (energy_ >= minEnergyRequiredForAttack(1) ? 1 : 2) << std::endl;
    std::cout << "Remaining energy: " << energy_ << std::endl;

    // Implement a cooldown mechanism where the next attack can only be performed after 9 seconds, even if the energy level allows it immediately
    last_attack_ = std::max(last_attack_, static_cast<int>(std::floor(9.0 / cooldownDuration())));
  }

 private:
  // Minimum energy required for each attack
  int minEnergyRequiredForAttack(int attack) {
    switch (attack) {
      case 1: return 20;
      case 2: return 30;
      default: throw std::invalid_argument("Invalid attack number.");
    }
  }

  // Cooldown duration between attacks
  double cooldownDuration() {
    return 9.0;
  }

  // Character's initial energy level
  int energy_;

  // Timestamp of the last performed attack
  int last_attack_;
};
```
