public class TokenManager {
    private static final Map<String, String> tokenCache = new ConcurrentHashMap<>();

    public static String generateToken(String username, long timestamp) throws NoSuchAlgorithmException {
        String concatenatedStr = username + "-" + timestamp;
        byte[] hashedBytes = MessageDigest.getInstance("SHA-256").digest(concatenatedStr.getBytes());
        return new String(hashedBytes);
    }

    public static void validateToken(String token) throws NoSuchAlgorithmException {
        if (tokenCache.containsKey(token)) {
            long timestamp = tokenCache.get(token);
            if (timestamp >= System.currentTimeMillis()) {
                // Token is valid, do nothing
            } else {
                // Token has expired, invalidate it
                tokenCache.remove(token);
            }
        } else {
            try {
                String username = validateTokenWithExternalService(token);
                if (username != null) {
                    long timestamp = System.currentTimeMillis();
                    tokenCache.put(token, timestamp);
                }
            } catch (Exception e) {
                // Handle exception gracefully
            }
        }
    }

    public static void invalidateToken(String token) {
        if (tokenCache.containsKey(token)) {
            tokenCache.remove(token);
        }
    }

    private static String validateTokenWithExternalService(String token) throws Exception {
        // Implement external authentication service here
        return null;
    }
}
