using System;
using UnityEngine;

public class ValueGenerator
{
    private readonly float minValue;
    private readonly float maxValue;
    private readonly bool useNormalDistribution;
    private readonly int seed;

    public ValueGenerator(float minValue, float maxValue, bool useNormalDistribution = false, int seed = 0)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Minimum value must be less than maximum value");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.useNormalDistribution = useNormalDistribution;
        this.seed = seed;
    }

    public float GetRandomFloat()
    {
        if (useNormalDistribution)
            return UnityEngine.Random.Range(minValue, maxValue);
        else
            return UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public int GetRandomInteger()
    {
        if (useNormalDistribution)
            return (int)UnityEngine.Random.Range(minValue, maxValue);
        else
            return (int)(UnityEngine.Random.Range(minValue, maxValue + 1f));
    }

    public void Seed(int value)
    {
        UnityEngine.Random.InitState(value);
    }

    public override string ToString()
    {
        return $"ValueGenerator({minValue}, {maxValue}, normalDistribution={useNormalDistribution})";
    }

    public static ValueGenerator Default()
    {
        return new ValueGenerator(0f, 1f);
    }
}
