// modules/http_client.rs
use std::{collections::HashMap, error::Error};
use reqwest::{header::CONTENT_TYPE, Client, header::HeaderMap};
use serde::{Deserialize, Serialize};
use crate::logging::LoggingService;

// Struct to hold request and response data
#[derive(Serialize, Deserialize)]
struct RequestData {
    url: String,
    method: Method,
    headers: HeaderMap,
    body: Option<String>,
}

#[derive(Serialize, Deserialize)]
struct ResponseData {
    status: u16,
    headers: HashMap<String, String>,
    body: Option<String>,
}

// Implement a logging service to track requests and responses
#[derive(Clone)]
pub struct LoggingService {
    client: Client,
    enabled: bool,
}

impl LoggingService {
    pub fn new(enabled: bool) -> Self {
        Self {
            client: Client::new(),
            enabled: enabled,
        }
    }

    pub async fn log_request(&self, request: &RequestData) -> Result<(), Error> {
        if self.enabled {
            let mut headers = HeaderMap::new();
            for (key, value) in request.headers.iter() {
                headers.append(key, value.to_owned());
            }

            let body = request.body.clone().unwrap_or_default();
            self.client
                .post("https://example.com/api/log")
                .json(&LogRequest {
                    url: &request.url,
                    method: &request.method,
                    headers: &headers,
                    body: &body,
                })
                .send()
                .await?;
        }

        Ok(())
    }

    pub async fn log_response(&self, response: &ResponseData) -> Result<(), Error> {
        if self.enabled {
            let mut headers = HeaderMap::new();
            for (key, value) in response.headers.iter() {
                headers.append(key, value.to_owned());
            }

            let body = response.body.clone().unwrap_or_default();
            self.client
                .post("https://example.com/api/log")
                .json(&LogResponse {
                    status: response.status,
                    headers: &headers,
                    body: &body,
                })
                .send()
                .await?;
        }

        Ok(())
    }
}

// Implement the HTTP client module with logging and resource management
#[derive(Clone)]
pub struct HttpClient {
    client: Client,
    logging_service: LoggingService,
}

impl HttpClient {
    pub fn new(logging_enabled: bool) -> Self {
        Self {
            client: Client::new(),
            logging_service: LoggingService::new(logging_enabled),
        }
    }

    pub async fn execute(&self, request: &RequestData) -> Result<ResponseData, Error> {
        // Log the request data
        self.logging_service.log_request(request).await?;

        // Make the HTTP request
        let mut headers = HeaderMap::new();
        for (key, value) in request.headers.iter() {
            headers.append(key, value.to_owned());
        }

        let response = self.client
            .execute(request.method, &request.url, Some(&headers), None)
            .await?;

        // Log the response data
        let body = response.text().await?.unwrap_or_default();
        let status = response.status().as_u16();
        self.logging_service.log_response(&ResponseData { status, headers, body }).await?;

        // Return the response data
        Ok(ResponseData { status, headers, body })
    }
}
