public static CustomDataStructure LoadCompressedBinaryFile(string filePath) {
    if (!File.Exists(filePath)) {
      throw new FileNotFoundException($"File '{filePath}' not found");
    }

    var extension = Path.GetExtension(filePath);
    CompressionAlgorithm compressionAlgorithm;
    switch (extension) {
      case ".bin":
        compressionAlgorithm = CompressionAlgorithm.None;
        break;
      case ".dat":
        compressionAlgorithm = CompressionAlgorithm.Deflate;
        break;
      default:
        throw new ArgumentException($"Unsupported file format '{extension}'");
    }

    byte[] compressedData;
    using (var stream = File.OpenRead(filePath)) {
      var buffer = new byte[stream.Length];
      stream.Read(buffer, 0, (int)stream.Length);
      compressedData = buffer;
    }

    CustomDataStructure data;
    try {
      using (var decompressionStream = CompressionAlgorithm.CreateDecompressionStream(compressedData)) {
        var serializer = new DataContractSerializer(typeof(CustomDataStructure));
        data = (CustomDataStructure)serializer.ReadObject(decompressionStream);
      }
    } catch (SerializationException e) {
      LoggingService.Error($"Failed to deserialize file '{filePath}': {e.Message}");
      throw;
    }

    return data;
  }

  public static void SaveCompressedBinaryFile(string filePath, CustomDataStructure data) {
    if (data == null) {
      throw new ArgumentNullException(nameof(data));
    }

    var extension = Path.GetExtension(filePath);
    CompressionAlgorithm compressionAlgorithm;
    switch (extension) {
      case ".bin":
        compressionAlgorithm = CompressionAlgorithm.None;
        break;
      case ".dat":
        compressionAlgorithm = CompressionAlgorithm.Deflate;
        break;
      default:
        throw new ArgumentException($"Unsupported file format '{extension}'");
    }

    byte[] serializedData;
    using (var stream = new MemoryStream()) {
      var serializer = new DataContractSerializer(typeof(CustomDataStructure));
      serializer.WriteObject(stream, data);
      serializedData = stream.ToArray();
    }

    byte[] compressedData;
    using (var compressionStream = CompressionAlgorithm.CreateCompressionStream(compressionAlgorithm)) {
      compressionStream.Write(serializedData, 0, serializedData.Length);
      compressedData = compressionStream.ToArray();
    }

    File.WriteAllBytes(filePath, compressedData);
  }
}

