using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Azure.Storage;
using Microsoft.Azure.Storage.Blobs;
using Newtonsoft.Json;

public class FileUploadController : ControllerBase
{
    private readonly CloudStorageAccount _storageAccount;
    private readonly string _connectionString;
    private readonly string _containerName;

    public FileUploadController(CloudStorageAccount storageAccount, string connectionString, string containerName)
    {
        _storageAccount = storageAccount;
        _connectionString = connectionString;
        _containerName = containerName;
    }

    [HttpPost]
    public async Task<IActionResult> UploadFilesAsync(int userId, List<string> fileIds, Dictionary<string, string> metadata)
    {
        // Validate input data
        if (userId <= 0 || fileIds == null || !fileIds.Any())
            return BadRequest("Invalid input");

        try
        {
            var blobContainer = GetBlobContainer();
            var filesToUpload = new List<CloudBlockBlob>();

            // Upload files to cloud storage
            foreach (var fileId in fileIds)
            {
                var blobReference = blobContainer.GetBlockBlobReference(fileId);
                if (!await blobReference.ExistsAsync())
                {
                    return NotFound($"File with ID {fileId} does not exist");
                }
                filesToUpload.Add(blobReference);
            }

            // Associate files with user and update metadata in database
            var updateTasks = new List<Task>();
            foreach (var file in filesToUpload)
            {
                var blob = await file.DownloadTextAsync();
                var jsonData = JsonConvert.DeserializeObject<dynamic>(blob);
                jsonData.userId = userId;
                jsonData.metadata = metadata;
                var updatedBlob = JsonConvert.SerializeObject(jsonData);
                updateTasks.Add(file.UploadTextAsync(updatedBlob));
            }

            // Wait for all updates to complete
            await Task.WhenAll(updateTasks);

            return Ok("Files uploaded successfully");
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Error uploading files: {ex.Message}");
        }
    }

    private CloudBlobContainer GetBlobContainer()
    {
        var blobClient = _storageAccount.CreateCloudBlobClient();
        var container = blobClient.GetContainerReference(_containerName);
        if (!await container.ExistsAsync())
            throw new Exception($"Container '{_containerName}' does not exist");

        return container;
    }
}
```
This code uses the `Microsoft.AspNetCore.Mvc` and `Microsoft.Azure.Storage` libraries to handle HTTP POST requests and upload files to a cloud storage service. The function validates input data, uploads the files to the cloud storage service, associates them with the user, and updates the metadata in a database. The code also handles concurrent updates gracefully and returns a response indicating whether the operation was successful and if any files were skipped due to existing duplicates.

The function uses the `CloudStorageAccount` class from the `Microsoft.Azure.Storage` library to create a cloud storage account object, which is used to connect to the cloud storage service. The `GetBlobContainer` method retrieves a reference to the blob container where the files will be uploaded. If the container does not exist, an exception is thrown.

The function then loops through each file ID in the list of input parameters and creates a reference to the corresponding block blob using the `CloudBlobContainer.GetBlockBlobReference` method. It then checks if the file exists in the cloud storage service by calling the `CloudBlockBlob.ExistsAsync` method. If the file does not exist, a 404 Not Found response is returned.

Next, the function adds each block blob to a list of files to upload and creates a task for each file using the `CloudBlockBlob.UploadTextAsync` method. The tasks are added to a list of update tasks that will be executed concurrently.

Finally, the function waits for all update tasks to complete using the `Task.WhenAll` method. If any errors occur during the upload process, an exception is thrown and a 500 Internal Server Error response is returned with a detailed error message. Otherwise, the function returns a successful response indicating that the files were uploaded successfully.

#include <openssl/des.h>
#include <openssl/evp.h>
#include <string>
#include <unordered_map>

using namespace std;

struct CipherContext {
    EVP_CIPHER_CTX* ctx;
    string mode;
    int key_len, iv_len;
};

class CryptoManager {
private:
    unordered_map<string, CipherContext> contexts_;
public:
    static CryptoManager& getInstance() {
        static CryptoManager instance;
        return instance;
    }

    EVP_CIPHER* getCipher(const string& mode, int key_len, int iv_len) {
        string key = mode + to_string(key_len) + to_string(iv_len);
        if (contexts_.find(key) != contexts_.end()) {
            return contexts_[key].ctx;
        } else {
            EVP_CIPHER* cipher = NULL;
            switch (mode) {
                case "ECB":
                    cipher = EVP_des_ecb();
                    break;
                case "EDE":
                    cipher = EVP_des_ede();
                    break;
                case "EDE3":
                    cipher = EVP_des_ede3();
                    break;
                case "CFB":
                    cipher = EVP_des_cfb();
                    break;
            }

            if (cipher != NULL) {
                contexts_.insert({key, CipherContext{cipher, mode, key_len, iv_len}});
                return cipher;
            } else {
                // Invalid configuration
                return NULL;
            }
        }
    }
};

EVP_CIPHER* getCipher(const string& mode, int key_len, int iv_len) {
    return CryptoManager::getInstance().getCipher(mode, key_len, iv_len);
}

void initCipherContext(EVP_CIPHER_CTX* ctx, const string& mode, int key_len, int iv_len) {
    EVP_CIPHER* cipher = getCipher(mode, key_len, iv_len);
    if (cipher != NULL) {
        EVP_CIPHER_CTX_init(ctx);
        EVP_CIPHER_CTX_set_key_length(ctx, key_len);
        EVP_CIPHER_CTX_set_iv_length(ctx, iv_len);
        EVP_CipherInit_ex(ctx, cipher, NULL, NULL, NULL, -1);
    } else {
        // Invalid configuration
        return;
    }
}

void freeCipherContext(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_cleanup(ctx);
    EVP_CIPHER_CTX_free(ctx);
}

string generateIV(int iv_len) {
    string iv;
    for (int i = 0; i < iv_len; i++) {
        iv += to_string(rand() % 256);
    }
    return iv;
}

void encrypt(const string& plaintext, const string& key, const string& mode, int key_len, int iv_len, string& ciphertext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    initCipherContext(ctx, mode, key_len, iv_len);
    EVP_EncryptUpdate(ctx, NULL, &ciphertext.size(), plaintext.data(), plaintext.size());
    ciphertext.resize(ciphertext.size() + 1);
    EVP_EncryptFinal_ex(ctx, &ciphertext[0], &ciphertext.size());
    freeCipherContext(ctx);
}

void decrypt(const string& ciphertext, const string& key, const string& mode, int key_len, int iv_len, string& plaintext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    initCipherContext(ctx, mode, key_len, iv_len);
    EVP_DecryptUpdate(ctx, NULL, &plaintext.size(), ciphertext.data(), ciphertext.size());
    plaintext.resize(plaintext.size() + 1);
    EVP_DecryptFinal_ex(ctx, &plaintext[0], &plaintext.size());
    freeCipherContext(ctx);
}

int main() {
    // Testing ECB mode with key length of 64 bits and no IV provided
    string plaintext = "Hello World!";
    string ciphertext;
    encrypt(plaintext, "12345678", "ECB", 64, 0, ciphertext);
    cout << "Encrypted text: " << ciphertext << endl;
    decrypt(ciphertext, "12345678", "ECB", 64, 0, plaintext);
    cout << "Decrypted text: " << plaintext << endl;

    // Testing EDE mode with key length of 128 bits and IV generated automatically
    string iv = generateIV(8);
    encrypt(plaintext, "abcdefghijklmnopqrstuvwxyz", "EDE", 128, iv.size(), ciphertext);
    cout << "Encrypted text: " << ciphertext << endl;
    decrypt(ciphertext, "abcdefghijklmnopqrstuvwxyz", "EDE", 128, iv.size(), plaintext);
    cout << "Decrypted text: " << plaintext << endl;

    return 0;
}

