        }

        // Read the file metadata asynchronously using the specified format
        private async Task<string> ReadMetadataFromFileAsync(string filePath, string metadataFormat)
        {
            var fileStream = File.OpenRead(filePath);
            var reader = new StreamReader(fileStream);
            var metadata = await reader.ReadToEndAsync();
            return metadata;
        }

        // Read the file metadata synchronously using the specified format
