using System;

public class CustomRandomGenerator : IRandomNumberGen
{
    // Default seed value used when none is provided
    private const long DEFAULT_SEED = 0L;

    // Minimum and maximum values allowed for random number generation
    private readonly float _minValue;
    private readonly float _maxValue;

    // Inclusive or exclusive flags for minimum and maximum values
    private readonly bool _inclusiveMin;
    private readonly bool _inclusiveMax;

    // Seed used for random number generation
    private long _seed = DEFAULT_SEED;

    public CustomRandomGenerator(float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax)
        : this(minValue, maxValue, inclusiveMin, inclusiveMax, DEFAULT_SEED)
    {
    }

    public CustomRandomGenerator(float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax, long seed)
    {
        // Validate input parameters and set default values
        if (minValue > maxValue)
        {
            throw new ArgumentException("Invalid range", nameof(maxValue));
        }

        _minValue = minValue;
        _maxValue = maxValue;
        _inclusiveMin = inclusiveMin;
        _inclusiveMax = inclusiveMax;
        _seed = seed;
    }

    // Generate a random float within the specified range, considering whether the minimum and maximum values are inclusive or exclusive
    public float GenerateRandomFloat()
    {
        var rand = new Random(_seed);
        return GetNextFloat(rand, _minValue, _maxValue, _inclusiveMin, _inclusiveMax);
    }

    // Generate a random integer within the specified range, considering whether the minimum and maximum values are inclusive or exclusive
    public int GenerateRandomInt()
    {
        var rand = new Random(_seed);
        return GetNextInt(rand, _minValue, _maxValue, _inclusiveMin, _inclusiveMax);
    }

    // Generate a random float with the given seed, supporting both inclusive and exclusive ranges
    public static float GenerateSeededRandomFloat(float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax, long seed)
    {
        var rand = new Random(seed);
        return GetNextFloat(rand, minValue, maxValue, inclusiveMin, inclusiveMax);
    }

    // Generate a random integer with the given seed within the specified range, supporting both inclusive and exclusive ranges
    public static int GenerateSeededRandomInt(int minValue, int maxValue, bool inclusiveMin, bool inclusiveMax, long seed)
    {
        var rand = new Random(seed);
        return GetNextInt(rand, minValue, maxValue, inclusiveMin, inclusiveMax);
    }

    // Helper method to generate a random float within the specified range, considering whether the minimum and maximum values are inclusive or exclusive
    private static float GetNextFloat(Random rand, float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax)
    {
        var range = maxValue - minValue;
        if (inclusiveMin && inclusiveMax)
        {
            // Inclusive of minimum and maximum values
            return rand.Next(1, (int)(range * 100)) / 100f + minValue;
        }
        else if (!inclusiveMin && !inclusiveMax)
        {
            // Exclusive of minimum and maximum values
            return rand.Next((int)(minValue * 100), (int)(maxValue * 100)) / 100f;
        }
        else if (!inclusiveMin && inclusiveMax)
        {
            // Exclusive of minimum value and inclusive of maximum value
            return rand.Next((int)(minValue * 100), (int)(maxValue * 100 + 1)) / 100f;
        }
        else if (inclusiveMin && !inclusiveMax)
        {
            // Inclusive of minimum value and exclusive of maximum value
            return rand.Next((int)(minValue * 100), (int)(maxValue * 100)) / 100f;
        }

        throw new ArgumentException("Invalid range", nameof(inclusiveMin));
    }

    // Helper method to generate a random integer within the specified range, considering whether the minimum and maximum values are inclusive or exclusive
    private static int GetNextInt(Random rand, float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax)
    {
        var range = (int)(maxValue - minValue);
        if (inclusiveMin && inclusiveMax)
        {
            // Inclusive of minimum and maximum values
            return rand.Next(range + 1);
        }
        else if (!inclusiveMin && !inclusiveMax)
        {
            // Exclusive of minimum and maximum values
            return rand.Next(range);
        }
        else if (!inclusiveMin && inclusiveMax)
        {
            // Exclusive of minimum value and inclusive of maximum value
            return rand.Next(range + 1);
        }
        else if (inclusiveMin && !inclusiveMax)
        {
            // Inclusive of minimum value and exclusive of maximum value
            return rand.Next(range + 1);
        }

        throw new ArgumentException("Invalid range", nameof(inclusiveMin));
    }

    public override string ToString()
    {
        var inclusiveMin = _inclusiveMin ? "inclusive" : "exclusive";
        var inclusiveMax = _inclusiveMax ? "inclusive" : "exclusive";
        return $"{_minValue}..{_maxValue} ({inclusiveMin}, {inclusiveMax}) seed={_seed}";
    }
}
```
