import java.io.*;
import java.util.List;

public class DeserializeObjects {
  private static final int HEADER_SIZE = 8; // size of the header for each object

  public static <T> T deserializeObject(byte[] bytes) {
    try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
         ObjectInputStream ois = new ObjectInputStream(bais)) {
      List<Class<?>> classes = getClassesFromMetadata(); // fetch metadata from external API
      while (ois.available() > HEADER_SIZE) {
        Class<?> clazz = null;
        try {
          byte[] headerBytes = new byte[HEADER_SIZE];
          ois.read(headerBytes);
          int version = readInt(headerBytes, 0);
          String className = readString(headerBytes, 4);
          clazz = Class.forName(className);
        } catch (IOException | ClassNotFoundException e) {
          // handle exception
        }
        if (clazz == null) {
          throw new RuntimeException("Class not found");
        }
        T obj = (T) ois.readObject();
        if (obj != null && !classes.contains(obj.getClass())) {
          classes.add(obj.getClass());
        }
        return obj;
      }
    } catch (IOException e) {
      // handle exception
    }
  }

  private static int readInt(byte[] bytes, int offset) {
    return (bytes[offset] & 0xFF) << 24 |
           (bytes[offset + 1] & 0xFF) << 16 |
           (bytes[offset + 2] & 0xFF) << 8 |
           bytes[offset + 3] & 0xFF;
  }

  private static String readString(byte[] bytes, int offset) {
    int length = readInt(bytes, offset);
    return new String(bytes, offset + HEADER_SIZE, length, "UTF-8");
  }

  private static List<Class<?>> getClassesFromMetadata() {
    // fetch metadata from external API and convert to list of classes
    return null;
  }
}
```
