using System;
using UnityEngine;

public class DynamicRandomValueGenerator : MonoBehaviour
{
    // Encryption keys and initialization vectors (IVs) fetched from external web API
    private string[] encryptionKeys = null;
    private string[] encryptionIVs = null;

    // Cache of latest encryption keys and IVs, used to minimize API calls and reduce latency
    private Dictionary<string, string> keyCache = new Dictionary<string, string>();
    private Dictionary<string, string> ivCache = new Dictionary<string, string>();

    // Current range of random values, inclusive and exclusive
    private int currentMinValue = 0;
    private int currentMaxValue = 10;

    // Whether the external data source has been successfully fetched and cached
    private bool isExternalDataCached = false;

    // Method for generating random values within the current range
    public int GenerateRandomValue()
    {
        return UnityEngine.Random.Range(currentMinValue, currentMaxValue);
    }

    // Method for decrypting Base64-encoded, encrypted messages using fetched encryption keys and IVs
    public string DecryptMessage(string base64EncodedMessage)
    {
        try
        {
            // Check if the message is already decrypted or can be easily decrypted without fetching new keys and IVs
            if (base64EncodedMessage.Length % 2 == 0 && base64EncodedMessage.LastIndexOf('=') == base64EncodedMessage.Length - 1)
            {
                return base64EncodedMessage;
            }

            // Check if the message is encrypted with a known encryption mode and fetch the corresponding key and IV
            string[] parts = base64EncodedMessage.Split('-');
            if (parts.Length == 2)
            {
                string encryptionMode = parts[0];
                string encryptedPayload = parts[1];
                string key = encryptionKeys[encryptionMode];
                string iv = encryptionIVs[encryptionMode];

                // Decrypt the message using the fetched key and IV
                return AesCryptoServiceProvider.Decrypt(key, iv, encryptedPayload);
            }
        }
        catch (Exception ex)
        {
            Debug.LogError("Failed to decrypt message: " + ex.Message);
        }

        // If the message cannot be easily decrypted or is not encrypted with a known encryption mode, return null
        return null;
    }

    // Method for fetching and caching new encryption keys and IVs from the external web API
    public void UpdateEncryptionKeysAndIVs()
    {
        try
        {
            // Fetch new encryption keys and IVs from the external web API
            EncryptionKeyAndIVResponse response = ExternalApi.GetEncryptionKeysAndIVs();

            // Add the new keys and IVs to the cache, replacing any existing values
            foreach (var keyValuePair in response.Keys)
            {
                encryptionKeys[keyValuePair.Key] = keyValuePair.Value;
            }

            foreach (var keyValuePair in response.IVs)
            {
                encryptionIVs[keyValuePair.Key] = keyValuePair.Value;
            }

            // Set the flag indicating that the external data has been successfully fetched and cached
            isExternalDataCached = true;
        }
        catch (Exception ex)
        {
            Debug.LogError("Failed to update encryption keys and IVs: " + ex.Message);
        }
    }

    // Method for refreshing the current range of random values, inclusive and exclusive
    public void UpdateRandomValueRange(int minValue, int maxValue)
    {
        try
        {
            // Validate the new range of values
            if (minValue < 0 || maxValue > 100)
            {
                throw new ArgumentException("Invalid random value range");
            }

            // Update the current range of values
            currentMinValue = minValue;
            currentMaxValue = maxValue;
        }
        catch (Exception ex)
        {
            Debug.LogError("Failed to update random value range: " + ex.Message);
        }
    }

    // Method for displaying the current status of the external data source integration and the current range of random values
    public override string ToString()
    {
        return $"External data cached: {isExternalDataCached}\nCurrent range of values: {currentMinValue}-{currentMaxValue}";
    }
}
