using namespace std;

class NetworkServer {
public:
    NetworkServer(const string& configFile) {
        this->configFile = configFile;
        readConfig();
    }

    ~NetworkServer() {
        // Clean up resources here
    }

    void start() {
        if (debugMode) {
            cout << "Starting network server in debug mode" << endl;
        } else {
            cout << "Starting network server with configuration from " << configFile << endl;
        }

        // Set up the network server here
    }

private:
    string configFile;
    int port = 0;
    int maxConnections = 0;
    string listenAddress;
    bool debugMode = false;
    map<string, string> options;

    void readConfig() {
        ifstream configStream(configFile);
        if (!configStream.is_open()) {
            throw runtime_error("Failed to open configuration file");
        }

        string line;
        while (getline(configStream, line)) {
            // Split the line into key and value using '=' as the delimiter
            size_t pos = line.find('=');
            if (pos == string::npos) {
                continue;
            }
            string key = line.substr(0, pos);
            string value = line.substr(pos + 1);

            // Parse the key and value
            if (key == "port") {
                port = stoi(value);
            } else if (key == "max_connections") {
                maxConnections = stoi(value);
            } else if (key == "listen_address") {
                listenAddress = value;
            } else if (key == "debug") {
                debugMode = stoi(value) > 0;
            } else {
                options[key] = value;
            }
        }
    }
};
```
