```
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class DatabaseConnection {
    private static readonly string connectionString = "Server=<server_name>;Database=<database_name>;User Id=<username>;Password=<password>";

    public static DataTableReader ExecuteQuery(byte[] input) {
        // Create a new SQL command with the query to execute
        var sqlCommand = new SqlCommand("SELECT * FROM <table_name> WHERE <column_name> LIKE @input", connectionString);

        // Set the parameter value for the query
        sqlCommand.Parameters.AddWithValue("@input", input);

        // Execute the query and return the results as a DataTableReader object
        var dataTable = new DataTable();
        using (var reader = sqlCommand.ExecuteReader()) {
            dataTable.Load(reader, LoadOption.OverwriteChanges);
        }
        return dataTable.CreateDataReader();
    }
}
