```java
import java.io.*;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLSocketFactory;

public class HTTPClient {
    private URL url;
    private boolean disableCertificateValidation = false;

    public HTTPClient(String url) throws MalformedURLException {
        this.url = new URL(url);
    }

    public void setDisableCertificateValidation(boolean disableCertificateValidation) {
        this.disableCertificateValidation = disableCertificateValidation;
    }

    public String sendGETRequest() throws IOException {
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        if (disableCertificateValidation) {
            // Disable certificate validation for HTTPS connections
            ((HttpsURLConnection) connection).setHostnameVerifier((hostname, session) -> true);
            ((HttpsURLConnection) connection).setSSLSocketFactory(new SSLSocketFactory() {
                @Override
                public String[] getDefaultCipherSuites() {
                    return new String[0];
                }

                @Override
                public String[] getSupportedCipherSuites() {
                    return new String[0];
                }
            });
        }

        connection.setRequestMethod("GET");
        connection.connect();

        try (InputStream inputStream = connection.getInputStream()) {
            BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.UTF_8));
            StringBuilder responseBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                responseBuilder.append(line).append("\n");
            }
            return responseBuilder.toString();
        } finally {
            connection.disconnect();
        }
    }

    public void executeCommand(String command, File workingDir) throws IOException {
        Runtime runtime = Runtime.getRuntime();
        Process process = runtime.exec(command, null, workingDir);
        try (BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
            String line;
            while ((line = outputReader.readLine()) != null) {
                System.out.println(line);
            }
            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }
        } finally {
            process.waitFor();
            process.destroy();
        }
    }
}
```
