    /// <summary>
    /// Provides a simple yet flexible API for generating random values within dynamically configured ranges.
    /// </summary>
    public class DynamicRandomValueGenerator
    {
        private readonly object _lock = new object();
        private RangeLimit _rangeLimit;

        /// <summary>
        /// Initializes a new instance of the <see cref="DynamicRandomValueGenerator"/> class.
        /// </summary>
        public DynamicRandomValueGenerator()
        {
            // Initialize with default range limits.
            _rangeLimit = new RangeLimit(0, 1);
        }

        /// <summary>
        /// Gets or sets the current range limits.
        /// </summary>
        public RangeLimit RangeLimit
        {
            get => _rangeLimit;
            set
            {
                // Validate the new range limit before updating.
                if (value == null || value.Minimum > value.Maximum)
                {
                    throw new ArgumentException("Invalid range limits provided.");
                }

                lock (_lock)
                {
                    _rangeLimit = value;
                }
            }
        }

        /// <summary>
        /// Generates a random integer within the configured range.
        /// </summary>
        /// <returns>A random integer within the configured range.</returns>
        public int NextInt()
        {
            lock (_lock)
            {
                return _rangeLimit.Minimum + (int)(_rangeLimit.Maximum - _rangeLimit.Minimum) * new Random().NextDouble();
            }
        }

        /// <summary>
        /// Generates a random float within the configured range.
        /// </summary>
        /// <returns>A random float within the configured range.</returns>
        public float NextFloat()
        {
            lock (_lock)
            {
                return (float)(_rangeLimit.Minimum + (double)(_rangeLimit.Maximum - _rangeLimit.Minimum) * new Random().NextDouble());
            }
        }

        /// <summary>
        /// Overridden ToString method to display the current range of values.
        /// </summary>
        /// <returns>A string representation of the current range limits.</returns>
        public override string ToString()
        {
            return $"Range: [{_rangeLimit.Minimum} - {_rangeLimit.Maximum}]";
        }
    }

    /// <summary>
    /// Represents a range of values for the DynamicRandomValueGenerator class.
    /// </summary>
    public class RangeLimit
    {
        /// <summary>
        /// Initializes a new instance of the <see cref="RangeLimit"/> class.
        /// </summary>
        /// <param name="minimum">The minimum value in the range.</param>
        /// <param name="maximum">The maximum value in the range.</param>
        public RangeLimit(int minimum, int maximum)
        {
            Minimum = minimum;
            Maximum = maximum;
        }

        /// <summary>
        /// Gets or sets the minimum value in the range.
        /// </summary>
        public int Minimum { get; set; }

        /// <summary>
        /// Gets or sets the maximum value in the range.
        /// </summary>
        public int Maximum { get; set; }
    }
}
