using System;
using System.IO;
using System.Net;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicRandomValueGenerator
{
    /// <summary>
    /// A class for generating random values within a dynamically configured range.
    /// </summary>
    public class RandomValueGenerator
    {
        // Private field for storing the current range limits
        private readonly Range Limits;

        // Constructor to initialize the range limits from a JSON configuration file
        public RandomValueGenerator(string configFilePath)
        {
            // Load the range limits from the specified file path
            var jsonString = File.ReadAllText(configFilePath);
            var jsonDocument = JsonSerializer.Deserialize<JsonDocument>(jsonString);
            Limits = new Range(jsonDocument.Min, jsonDocument.Max);
        }

        // Method for generating random integers within the specified range
        public int GenerateRandomInt()
        {
            return new Random().Next(Limits.Min, Limits.Max + 1);
        }

        // Method for generating random floats within the specified range
        public float GenerateRandomFloat()
        {
            return (float)(new Random().NextDouble() * (Limits.Max - Limits.Min) + Limits.Min);
        }

        // Overridden ToString method to display the current range of values
        public override string ToString()
        {
            return $"Random Value Generator: Range [{Limits.Min}, {Limits.Max}]";
        }

        // Method to load range limits from a local or remote JSON configuration file
        public async Task LoadConfigurationAsync(string configFilePath, CancellationToken cancellationToken = default)
        {
            try
            {
                var jsonString = await GetJsonFromConfigFileAsync(configFilePath, cancellationToken);
                var jsonDocument = JsonSerializer.Deserialize<JsonDocument>(jsonString);
                Limits = new Range(jsonDocument.Min, jsonDocument.Max);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading configuration file: {ex.Message}");
            }
        }

        // Method to save the current range limits to a local or remote JSON configuration file
        public async Task SaveConfigurationAsync(string configFilePath, CancellationToken cancellationToken = default)
        {
            try
            {
                var jsonString = JsonSerializer.Serialize<JsonDocument>(Limits);
                await File.WriteAllTextAsync(configFilePath, jsonString, cancellationToken);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error saving configuration file: {ex.Message}");
            }
        }

        // Private method to fetch JSON data from a local or remote file path
        private async Task<string> GetJsonFromConfigFileAsync(string configFilePath, CancellationToken cancellationToken)
        {
            try
            {
                if (File.Exists(configFilePath))
                {
                    return await File.ReadAllTextAsync(configFilePath, cancellationToken);
                }
                else if (Uri.TryCreate(configFilePath, UriKind.Absolute, out var uri) && !uri.IsLoopback)
                {
                    using var client = new WebClient();
                    return await client.DownloadStringTaskAsync(uri);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error fetching JSON data: {ex.Message}");
            }

            return null;
        }
    }

    /// <summary>
    /// A class for storing the minimum and maximum values of a range.
    /// </summary>
    public class Range
    {
        // Constructor to initialize the range limits with the specified minimum and maximum values
        public Range(int min, int max)
        {
            Min = min;
            Max = max;
        }

        // Public properties for accessing the minimum and maximum values of the range
        public int Min { get; set; }
        public int Max { get; set; }
    }
}
