    private class UnionFind {
        private Map<Integer, Set<Integer>> elementToNeighborsMap = new HashMap<>();
        private Map<Integer, Integer> parentMap = new HashMap<>();
        private int size;

        public void add(int element) {
            if (element < MINIMUM_ATTACK_OPTIONS || element > MAXIMUM_ATTACK_OPTIONS) {
                throw new IllegalArgumentException("Attack option must be an integer between " + MINIMUM_ATTACK_OPTIONS + " and " + MAXIMUM_ATTACK_OPTIONS + ".");
            }
            this.size++;
            this.elementToNeighborsMap.put(element, new HashSet<>());
            this.parentMap.put(element, element);
        }

        public void union(int element1, int element2) {
            if (element1 == element2) {
                return;
            }
            int parentElement1 = find(element1);
            int parentElement2 = find(element2);
            if (parentElement1 != parentElement2) {
                this.parentMap.put(parentElement1, parentElement2);
                this.size--;
            }
        }

        public boolean isDisjoint(int element) {
            return find(element) == element;
        }

        private int find(int element) {
            if (!this.elementToNeighborsMap.containsKey(element)) {
                throw new IllegalArgumentException("Attack option " + element + " does not exist.");
            }
            while (this.parentMap.get(element) != element) {
                element = this.parentMap.get(element);
            }
            return element;
        }

        public int getSize() {
            return this.size;
        }
    }
}
