```
using System;
using UnityEngine;

public class RandomValueGenerator : IRandomValueGenerator
{
    private readonly int _minValue;
    private readonly int _maxValue;

    public RandomValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GetRandomFloatValue()
    {
        return UnityEngine.Random.Range(_minValue, _maxValue);
    }

    public int GetRandomIntegerValue()
    {
        return UnityEngine.Random.Range(_minValue, _maxValue).Round();
    }

    public override string ToString()
    {
        return $"{_minValue} - {_maxValue}";
    }

    private class UnionFind
    {
        private readonly int[] _parents;
        private readonly int[] _ranks;
        private readonly int[] _sizes;

        public UnionFind(int size)
        {
            _parents = new int[size];
            _ranks = new int[size];
            _sizes = new int[size];

            for (int i = 0; i < size; i++)
            {
                _parents[i] = i;
                _ranks[i] = 1;
                _sizes[i] = 1;
            }
        }

        public int Find(int x)
        {
            if (_parents[x] == x)
            {
                return x;
            }

            return Find(_parents[x]);
        }

        public void Union(int x, int y)
        {
            var rootX = Find(x);
            var rootY = Find(y);

            if (rootX == rootY)
            {
                return;
            }

            if (_ranks[rootX] < _ranks[rootY])
            {
                _parents[rootX] = rootY;
            }
            else if (_ranks[rootX] > _ranks[rootY])
            {
                _parents[rootY] = rootX;
            }
            else
            {
                _parents[rootY] = rootX;
                _ranks[rootX]++;
            }
        }
    }

    public bool AreDisjoint(int[] array)
    {
        if (array == null)
        {
            throw new ArgumentNullException(nameof(array));
        }

        var unionFind = new UnionFind(array.Length);

        for (int i = 0; i < array.Length - 1; i++)
        {
            for (int j = i + 1; j < array.Length; j++)
            {
                if (array[i] == array[j])
                {
                    return false;
                }

                var rootI = unionFind.Find(i);
                var rootJ = unionFind.Find(j);

                if (rootI == rootJ)
                {
                    continue;
                }

                unionFind.Union(rootI, rootJ);
            }
        }

        return true;
    }
}

public interface IRandomValueGenerator
{
    float GetRandomFloatValue();
    int GetRandomIntegerValue();
}
