bool insertStringAfter(forward_list<string> &strList, const string& str1, const string& str2) {
    // Find the first occurrence of str1 in the list
    auto iter = find(strList.begin(), strList.end(), str1);
    if (iter == strList.end()) {
        // If str1 is not found, append str2 to the end of the list
        strList.push_back(str2);
        return true;
    } else {
        // Otherwise, insert str2 after the first occurrence of str1
        iter = next(iter);
        strList.insert_after(iter, str2);
        return true;
    }
}
