class BackgroundExecutor {
public:
    // Constructor
    BackgroundExecutor() : commands(), lock(), condition(), threadRunning(false) {}

    // Add a new command to the queue for execution
    void addCommand(const std::string& command) {
        std::unique_lock<std::mutex> lock(this->lock);
        this->commands.push_back(command);
        lock.unlock();
        condition.notify_one();
    }

    // Execute the next command in the queue
    void executeNext() {
        std::unique_lock<std::mutex> lock(this->lock);
        if (commands.size() > 0) {
            std::thread([&]() {
                std::string cmd = commands.front();
                commands.pop_front();
                int status = system(cmd.c_str());
                if (status != 0) {
                    std::cerr << "Command failed: " << cmd << std::endl;
                }
                lock.unlock();
                condition.notify_one();
            }).detach();
        } else {
            lock.unlock();
            condition.wait(lock);
        }
    }

    // Return the status of a specific command (running, completed, failed)
    bool getStatus(size_t index) {
        std::unique_lock<std::mutex> lock(this->lock);
        if (index >= commands.size()) {
            return false;
        } else {
            return true;
        }
    }

    // Retrieve the output of a specific command if it has completed successfully
    std::string getOutput(size_t index) {
        std::unique_lock<std::mutex> lock(this->lock);
        if (index >= commands.size()) {
            return "";
        } else {
            std::vector<char> buffer;
            FILE *fp = popen(commands[index].c_str(), "r");
            while (!feof(fp)) {
                char c = fgetc(fp);
                if (c != EOF) {
                    buffer.push_back(c);
                }
            }
            pclose(fp);
            return std::string(buffer.begin(), buffer.end());
        }
    }

    // Retrieve the error message of a specific command if it has failed
    std::string getError(size_t index) {
        std::unique_lock<std::mutex> lock(this->lock);
        if (index >= commands.size()) {
            return "";
        } else {
            std::vector<char> buffer;
            FILE *fp = popen(commands[index].c_str(), "r");
            while (!feof(fp)) {
                char c = fgetc(fp);
                if (c != EOF) {
                    buffer.push_back(c);
                }
            }
            pclose(fp);
            return std::string(buffer.begin(), buffer.end());
        }
    }

private:
    // Vector to store the commands in the queue
    std::vector<std::string> commands;

    // Mutex for thread safety
    std::mutex lock;

    // Condition variable to signal when a command is ready to be executed
    std::condition_variable condition;

    // Flag indicating whether a thread is currently running
    bool threadRunning;
};
```
Here's a simple test harness to demonstrate the usage of the `BackgroundExecutor` class:
```cpp
int main() {
    BackgroundExecutor executor;

    // Add some commands to the queue for execution
    executor.addCommand("echo hello");
    executor.addCommand("echo world");
    executor.addCommand("echo goodbye");

    // Execute the next command in the queue
    executor.executeNext();

    // Wait for the first command to complete and retrieve its output
    std::cout << "Output of first command: " << executor.getOutput(0) << std::endl;

    // Check if a specific command has failed and print its error message if it has
    size_t index = 1;
    if (executor.getStatus(index)) {
        std::cerr << "Error message of second command: " << executor.getError(index) << std::endl;
    }

    // Wait for all commands to complete and print their outputs
    while (executor.commands.size() > 0) {
        executor.executeNext();
        std::cout << "Output of command " << index++ << ": " << executor.getOutput(index) << std::endl;
    }

    return 0;
}
```
This test harness will add three commands to the queue for execution, then execute the first command and retrieve its output. It will also check if a specific command has failed and print its error message if it has. Finally, it will wait for all commands to complete and print their outputs.

