<?php
function updateUserPassword($userId, $newPassword) {
    // Validate the new password according to predefined security policies
    if (!validatePasswordStrength($newPassword)) {
        throw new \Exception('The provided password does not meet the security policies.');
    }

    // Acquire a database connection and lock the user's record for updates
    $db = getDbConnection();
    $userRecord = $db->query("SELECT * FROM users WHERE id = ?", [$userId]);
    if (!$userRecord) {
        throw new \Exception('Unable to acquire database connection.');
    }
    $db->lock($userRecord, 'UPDATE');

    // Update the user's password in the external authentication service
    try {
        $authService = new OAuth2\Client(getOAuthConfig());
        $response = $authService->requestAccessToken('password', [
            'username' => $userRecord['email'],
            'password' => $newPassword,
        ]);
        if (!$response || !isset($response['access_token'])) {
            throw new \Exception('Unable to update password in external authentication service.');
        }
    } catch (\Exception $e) {
        // Handle network interruptions and other error conditions gracefully
        logError("Error updating user's password: " . $e->getMessage());
        $db->unlock($userRecord);
        throw $e;
    }

    // Update the user's password in the local database
    try {
        $db->update('users', [
            'password' => $newPassword,
        ], [
            'id' => $userId,
        ]);
    } catch (\Exception $e) {
        logError("Error updating user's password in local database: " . $e->getMessage());
        $db->unlock($userRecord);
        throw $e;
    }

    // Release the lock on the user's record and commit any changes
    $db->unlock($userRecord, 'UPDATE');

    return true;
}
