function generateSecureRandomString($length, $charset) {
    // Validate input parameters
    if (!is_int($length) || $length < 1) {
        throw new InvalidArgumentException("Invalid length specified for random string generation");
    }
    if (strlen($charset) < 8) {
        throw new InvalidArgumentException("Character set must be at least 8 characters long");
    }

    // Generate a secure random string
    $randomString = openssl_random_pseudo_bytes($length);
    if ($randomString === false) {
        throw new RuntimeException("Failed to generate secure random string");
    }

    // Hash the password using bcrypt
    $hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => 12]);
    if ($hashedPassword === false) {
        throw new RuntimeException("Failed to hash password");
    }

    // Return the generated random string and hashed password
    return [$randomString, $hashedPassword];
}
