    }

    // Derive a key from the password using the chosen KDF algorithm
    unsigned char key[32];
    int ret = kdf_derive(password, strlen(password), key, 32, kdf);
    if (ret != 1) {
        fprintf(stderr, "Failed to derive key using KDF %d\n", kdf);
        free(ctx);
        return;
