    // Initialize the AES-CBC cipher context with the derived key and IV
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        fprintf(stderr, "Failed to initialize AES-CBC cipher context\n");
        free(ctx);
        return;
    }
    ret = EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (ret != 1) {
        fprintf(stderr, "Failed to initialize AES-CBC encryption\n");
        free(ctx);
        return;
    }

    // Record the derived key and IV in the encryption context for later use
    memcpy(ctx->key, key, 32);
    memcpy(ctx->iv, iv, 16);
}

// Function to encrypt a plaintext message using the initialized encryption service
void encrypt_message(const unsigned char *plaintext, size_t length, const char *password) {
    // Validate input parameters
    if (!plaintext || !length || !password || strlen(password) == 0) {
