    if (!ctx) {
        fprintf(stderr, "Failed to retrieve encryption context\n");
        return;
    }

    // Initialize the cipher for encryption using the derived key and IV
    EVP_CIPHER_CTX *encrypt_ctx = EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, NULL);
    if (!encrypt_ctx) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        return;
    }
    int ret = EVP_EncryptUpdate(encrypt_ctx, (unsigned char *)plaintext, length);
    if (ret != 1) {
        fprintf(stderr, "Failed to encrypt plaintext\n");
        free(encrypt_ctx);
        return;
    }
    ret = EVP_EncryptFinal_ex(encrypt_ctx, NULL, NULL);
    if (ret != 1) {
        fprintf(stderr, "Failed to finalize encryption\n");
        free(encrypt_ctx);
        return;
    }
    free(encrypt_ctx);
}

