use std::error::Error;
use std::io::prelude::*;
use std::net::TcpStream;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
use reqwest::blocking::get;
use log::{info, warn, error};
use serde_json::Value;
use rusqlite::Connection;

struct HttpClient {
    client: reqwest::blocking::Client,
}

impl HttpClient {
    fn new() -> Self {
        Self {
            client: reqwest::blocking::Client::new(),
        }
    }

    fn get(&self, url: &str) -> Result<Value, Box<dyn Error>> {
        let res = self.client.get(url)?;
        Ok(res?.json()?)
    }
}

struct ClinicService {
    db_conn: Connection,
    client: Arc<Mutex<HttpClient>>,
}

impl ClinicService {
    fn new(db_conn: Connection) -> Self {
        let client = Arc::new(Mutex::new(HttpClient::new()));
        Self { db_conn, client }
    }

    async fn update_clinic(&self, clinic_id: i32, ip_address: String, last_modified: String) -> Result<String, Box<dyn Error>> {
        let client = self.client.lock().unwrap();
        let url = format!("https://example.com/api/clinics/{}/update", clinic_id);
        let body = json!({ "ipAddress": ip_address, "lastModified": last_modified });
        let res = client.get(&url)?;
        if res.status().is_success() {
            info!("Clinic {} updated successfully", clinic_id);
            self.db_conn.execute(
                r#"UPDATE clinics SET lastModifiedIP = ?, lastModifiedDate = CURRENT_TIMESTAMP WHERE id = ?"#,
                &[&ip_address, &clinic_id],
            )?;
            Ok("Clinic updated successfully".to_string())
        } else {
            error!("Failed to update clinic {}", clinic_id);
            Err(Box::new(res.status().as_str()))
        }
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let db_conn = Connection::open("path/to/db.sqlite")?;
    let clinic_service = ClinicService::new(db_conn);
    loop {
        let clinic_id: i32 = 10;
        let ip_address = "192.168.0.1".to_string();
        let last_modified = "2022-01-01T12:00:00Z".to_string();
        clinic_service.update_clinic(clinic_id, ip_address, last_modified).await?;
    }
}
