const express = require('express');
const router = express.Router();
const axios = require('axios');
const cache = require('memory-cache');
const moment = require('moment');
const { MongoClient } = require('mongodb');

// OpenWeatherMap API endpoint
const apiEndpoint = 'https://api.openweathermap.org/data/2.5';
// Token bucket algorithm parameters
const tokenBucketSize = 10; // Maximum number of requests per minute
const tokenFillRate = 1; // Number of tokens to fill in a given time interval (seconds)
const tokenRefillInterval = 60; // Interval for refilling the token bucket (seconds)

// MongoDB connection details
const dbName = 'weather_data';
const collectionName = 'city_weather';

// Cached weather data
let cachedWeatherData = {};

router.get('/', async (req, res) => {
  // Get the list of cities and their coordinates from the request params
  const cities = req.query.cities;

  // Validate the input
  if (!Array.isArray(cities)) {
    return res.status(400).send('Invalid input');
  }

  // Create an array of API endpoints for fetching weather data
  const apiEndpoints = cities.map((city) => `${apiEndpoint}/weather?q=${city}&appid=YOUR_API_KEY`);

  // Fetch the weather data from the OpenWeatherMap API
  try {
    const responses = await axios.all(apiEndpoints);
    const weatherData = responses.map((response) => response.data);

    // Handle invalid inputs and rate limiting
    if (weatherData.some((data) => data.cod !== '200')) {
      return res.status(400).send('Invalid input');
    } else if (responses[0].headers['x-ratelimit-remaining'] < tokenBucketSize / 2) {
      return res.status(429).send('Rate limit exceeded');
    }

    // Cache the weather data for a set period
    const cacheKey = JSON.stringify(cities);
    cachedWeatherData[cacheKey] = weatherData;
    setTimeout(() => { delete cachedWeatherData[cacheKey]; }, 1000 * 60 * 60); // Cache for 1 hour

    // Store the fetched weather data into MongoDB
    const mongoClient = await MongoClient.connect(MONGO_URI, { useNewUrlParser: true });
    const db = mongoClient.db(dbName);
    const collection = db.collection(collectionName);
    await collection.insertMany(weatherData.map((data) => ({ city: data.name, weather: data.weather[0].main })));

    // Retrieve historical weather data for a specific city
    if (req.query.city) {
      const city = req.query.city;
      const historicalWeatherData = await collection.find({ city }).sort({ _id: -1 }).limit(7);
      return res.json(historicalWeatherData);
    } else {
      return res.json(weatherData);
    }
  } catch (error) {
    console.log(error);
    return res.status(500).send('Internal server error');
  }
});

router.get('/historical', async (req, res) => {
  // Retrieve historical weather data for a specific city
  if (!req.query.city) {
    return res.status(400).send('Invalid input');
  }
  const city = req.query.city;
  const collection = db.collection(collectionName);
  const historicalWeatherData = await collection.find({ city }).sort({ _id: -1 }).limit(7);
  return res.json(historicalWeatherData);
});
```

