const { MongoClient } = require('mongodb');

const app = express();

// Define constants for API endpoints and rate limiting thresholds
const OPENWEATHERMAP_API_URL = 'https://api.openweathermap.org/data/2.5/weather';
const HISTORICAL_WEATHER_API_URL = 'https://some-historical-weather-api.com/data';
const RATE_LIMIT_THRESHOLD = 10; // API requests per minute
const CACHE_EXPIRATION_TIME = 60 * 60 * 1000; // 1 hour in milliseconds

// Define an error handling function for reporting and logging errors
function handleError(error) {
  console.error(error);
  return res.status(500).json({ message: 'An unexpected error occurred.' });
}

// Define a function to validate coordinates and handle invalid inputs gracefully
function validateCoordinates(coordinates) {
  // Check if the input is an array of at least two elements
  if (!Array.isArray(coordinates) || coordinates.length < 2) {
    return false;
  }

  // Check if the latitude and longitude values are valid numbers
  const [latitude, longitude] = coordinates;
  if (typeof latitude !== 'number' || typeof longitude !== 'number') {
    return false;
  }

  // Check if the latitude value is within the allowed range (-90 to 90) and longitude value is within the allowed range (-180 to 180)
  if (latitude < -90 || latitude > 90 || longitude < -180 || longitude > 180) {
    return false;
  }

  return true;
}

// Define a function to construct API endpoints for fetching weather data from OpenWeatherMap using the provided coordinates
function getOpenWeatherMapEndpoint(coordinates) {
  const [latitude, longitude] = coordinates;
  const endpoint = `${OPENWEATHERMAP_API_URL}?lat=${latitude}&lon=${longitude}&appid=YOUR_APP_ID`;
  return endpoint;
}

// Define a function to construct API endpoints for fetching historical weather data from the second API using the provided coordinates
function getHistoricalWeatherEndpoint(coordinates) {
  const [latitude, longitude] = coordinates;
  const endpoint = `${HISTORICAL_WEATHER_API_URL}?lat=${latitude}&lon=${longitude}`;
  return endpoint;
}

// Define a function to fetch weather data from the OpenWeatherMap API and handle rate limiting using token bucket algorithm
async function getOpenWeatherMapData(coordinates) {
  // Construct an API endpoint for fetching weather data from OpenWeatherMap
  const endpoint = getOpenWeatherMapEndpoint(coordinates);

  // Create a new instance of the TokenBucket class to handle rate limiting
  const tokenBucket = new tokenBucket({
    capacity: RATE_LIMIT_THRESHOLD,
    fillRate: 10, // API requests per minute
    emptyRate: 60, // Empty the bucket every minute
  });

  try {
    // Fetch weather data from OpenWeatherMap using the constructed endpoint and handle rate limiting
    const response = await axios.get(endpoint);
    tokenBucket.addTokens(response.data.length || 1);
    return response.data;
  } catch (error) {
    // Handle API errors and rate limit exceeded errors
    if (error.code === 'ETIMEDOUT' || error.code === 'ECONNRESET') {
      console.log('API request timed out or connection reset, retrying...');
      return getOpenWeatherMapData(coordinates);
    } else if (error.response && error.response.status === 429) {
      // Rate limit exceeded, wait for a few seconds and try again
      console.log('Rate limit exceeded, waiting...');
      await sleep(5000);
      return getOpenWeatherMapData(coordinates);
    } else {
      throw error;
    }
  }
}

// Define a function to fetch historical weather data from the second API and handle rate limiting using token bucket algorithm
async function getHistoricalWeatherData(coordinates) {
  // Construct an API endpoint for fetching historical weather data
  const endpoint = getHistoricalWeatherEndpoint(coordinates);

  try {
    // Fetch historical weather data from the second API using the constructed endpoint and handle rate limiting
    const response = await axios.get(endpoint);
    return response.data;
  } catch (error) {
    if (error.code === 'ETIMEDOUT' || error.code === 'ECONNRESET') {
      console.log('API request timed out or connection reset, retrying...');
      return getHistoricalWeatherData(coordinates);
    } else {
      throw error;
    }
  }
}

// Define a function to fetch weather data from both OpenWeatherMap and the second API using cache eviction policies
async function getWeatherData(coordinates) {
  // Check if the coordinates are valid and handle invalid inputs gracefully
  if (!validateCoordinates(coordinates)) {
    return res.status(400).json({ message: 'Invalid coordinates.' });
  }

  // Construct API endpoints for fetching weather data from OpenWeatherMap and the second API
  const openWeatherMapEndpoint = getOpenWeatherMapEndpoint(coordinates);
  const historicalWeatherEndpoint = getHistoricalWeatherEndpoint(coordinates);

  try {
    // Fetch weather data from both APIs using cache eviction policies
    const cachedData = await Cache.get(openWeatherMapEndpoint);
    if (cachedData) {
      return cachedData;
    } else {
      const openWeatherMapResponse = await getOpenWeatherMapData(coordinates);
      const historicalWeatherResponse = await getHistoricalWeatherData(coordinates);
      Cache.set(openWeatherMapEndpoint, openWeatherMapResponse, CACHE_TIMEOUT);
      return { ...openWeatherMapResponse, ...historicalWeatherResponse };
    }
  } catch (error) {
    // Handle API errors and rate limit exceeded errors
    if (error.code === 'ETIMEDOUT' || error.code === 'ECONNRESET') {
      console.log('API request timed out or connection reset, retrying...');
      return getWeatherData(coordinates);
    } else {
      throw error;
    }
  }
}

// Define a function to store weather data in the database and update cache
async function storeWeatherData(weatherData) {
  // Store weather data in the database
  const db = await Database.getDatabaseInstance();
  await db.storeWeatherData(coordinates, weatherData);

  // Update cache
  Cache.set(openWeatherMapEndpoint, weatherData, CACHE_TIMEOUT);
}

// Define a function to fetch weather data from the database and cache
async function getDatabaseData(coordinates) {
  // Fetch weather data from the database
  const db = await Database.getDatabaseInstance();
  const cachedData = await Cache.get(openWeatherMapEndpoint);
  if (cachedData) {
    return cachedData;
  } else {
    const weatherData = await db.getWeatherData(coordinates);
    if (!weatherData) {
      // Fetch weather data from both APIs and store in the database
      const openWeatherMapResponse = await getOpenWeatherMapData(coordinates);
      const historicalWeatherResponse = await getHistoricalWeatherData(coordinates);
      await db.storeWeatherData(coordinates, { ...openWeatherMapResponse, ...historicalWeatherResponse });
      return openWeatherMapResponse;
    } else {
      return weatherData;
    }
  }
}

// Define a function to handle API requests and cache eviction policies
async function handleRequest(req, res) {
  const coordinates = req.query.coordinates.split(',');

  try {
    // Fetch weather data from the database using cache eviction policies
    const cachedData = await getDatabaseData(coordinates);
    if (cachedData) {
      return res.status(200).json(cachedData);
    } else {
      // Fetch weather data from both APIs and store in the database
      const openWeatherMapResponse = await getOpenWeatherMapData(coordinates);
      const historicalWeatherResponse = await getHistoricalWeatherData(coordinates);
      await storeWeatherData({ ...openWeatherMapResponse, ...historicalWeatherResponse });
      return res.status(201).json({ ...openWeatherMapResponse, ...historicalWeatherResponse });
    }
  } catch (error) {
    // Handle API errors and rate limit exceeded errors
    if (error.code === 'ETIMEDOUT' || error.code === 'ECONNRESET') {
      console.log('API request timed out or connection reset, retrying...');
      return handleRequest(req, res);
    } else {
      throw error;
    }
  }
}

// Define a function to sleep for a few seconds
async function sleep(seconds) {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve();
    }, seconds);
  });
}
