class GameConfig:
    def __init__(self, config_file):
        self.config = {}
        try:
            with open(config_file) as f:
                self.config = json.load(f)
        except FileNotFoundError:
            print("Configuration file not found.")
            self.config = {
                "resolution": (800, 600),
                "frame_rate_limit": 60,
                "players": [
                    {"position": (400, 300), "velocity": (100, 50)},
                    {"position": (600, 400), "velocity": (-50, 20)}
                ],
                "enemies": [
                    {"position": (200, 200), "velocity": (100, -50)},
                    {"position": (800, 600), "velocity": (-20, 30)}
                ],
                "power_ups": [
                    {"position": (400, 500), "type": "health"},
                    {"position": (600, 700), "type": "ammo"}
                ]
            }

        self.resolution = self.config["resolution"]
        self.frame_rate_limit = self.config["frame_rate_limit"]
        self.players = [Player(position=p["position"], velocity=p["velocity"]) for p in self.config["players"]]
        self.enemies = [Enemy(position=e["position"], velocity=e["velocity"]) for e in self.config["enemies"]]
        self.power_ups = [PowerUp(position=pu["position"], type=pu["type"]) for pu in self.config["power_ups"]]

    def log_error(self, message):
        print("Error:", message)

    def log_warning(self, message):
        print("Warning:", message)

class Game:
    def __init__(self, config):
        self.config = config
        self.running = True

    def run(self):
        while self.running:
            # Handle events
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    self.running = False

            # Update game state
            for player in self.config.players:
                player.update()
            for enemy in self.config.enemies:
                enemy.update()
            for power_up in self.config.power_ups:
                power_up.update()

            # Render game state
            screen = pygame.display.set_mode(self.config.resolution)
            screen.fill((0, 0, 0))
            for player in self.config.players:
                player.render(screen)
            for enemy in self.config.enemies:
                enemy.render(screen)
            for power_up in self.config.power_ups:
                power_up.render(screen)
            pygame.display.flip()

            # Limit frame rate
            clock = pygame.time.Clock()
            clock.tick(self.config.frame_rate_limit)

if __name__ == "__main__":
    config = GameConfig("game_config.json")
    game = Game(config)
    game.run()
```
