#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <pthread.h>

#define MAX_PRIMITIVES 10

struct primitive {
    const char *name;
    const EVP_CIPHER *cipher;
    const EVP_MD *digest;
};

struct primitives {
    struct primitive primitives[MAX_PRIMITIVES];
    int num_primitives;
};

struct thread_data {
    struct primitives *primitives;
    bool success;
};

static const struct primitive aes_cbc = {"AES-CBC", EVP_aes_128_cbc(), NULL};
static const struct primitive camellia_cbc = {"CAMELLIA-CBC", EVP_camellia_128_cbc(), NULL};
static const struct primitive md5 = {"MD5", NULL, EVP_md5()};
static const struct primitive sha1 = {"SHA1", NULL, EVP_sha1()};
static const struct primitive rsa_sha1 = {"RSA-SHA1", NULL, EVP_sha1()};

void add_cryptographic_primitives(struct primitives *primitives) {
    for (int i = 0; i < primitives->num_primitives; ++i) {
        const struct primitive *p = &primitives->primitives[i];
        if (EVP_add_cipher(p->cipher)) {
            EVP_add_digest_alias(p->name, p->digest);
            printf("Successfully added %s\n", p->name);
            primitives->success = true;
        } else {
            printf("Failed to add %s: %s\n", p->name, ERR_error_string(ERR_get_error(), NULL));
            primitives->success = false;
        }
    }
}

void *add_cryptographic_primitives_thread(void *data) {
    struct thread_data *td = (struct thread_data *)data;
    add_cryptographic_primitives(td->primitives);
    return NULL;
}

void cleanup_cryptographic_primitives(struct primitives *primitives) {
    for (int i = 0; i < primitives->num_primitives; ++i) {
        const struct primitive *p = &primitives->primitives[i];
        EVP_cleanup();
    }
}

void main() {
    // Perform a compatibility check for OpenSSL version 1.1.0 or higher
    if (OPENSSL_VERSION_NUMBER < 0x1010100fL) {
        printf("OpenSSL version must be at least 1.1.0, aborting\n");
        return;
    }

    // Set up a structure to hold the cryptographic primitives and their associated functions
    struct primitives primitives = {};

    // Add AES-CBC, CAMELLIA-CBC, MD5, SHA1, and RSA-SHA1 using the EVP_add_cipher and EVP_add_digest functions
    primitives.primitives[0] = aes_cbc;
    primitives.primitives[1] = camellia_cbc;
    primitives.primitives[2] = md5;
    primitives.primitives[3] = sha1;
    primitives.primitives[4] = rsa_sha1;
    primitives.num_primitives = 5;

    // Add the cryptographic primitives in a multi-threaded environment to ensure thread safety
    pthread_t threads[MAX_PRIMITIVES];
    struct thread_data thread_data[MAX_PRIMITIVES];
    for (int i = 0; i < MAX_PRIMITIVES; ++i) {
        thread_data[i].primitives = &primitives;
        pthread_create(&threads[i], NULL, add_cryptographic_primitives_thread, (void *)&thread_data[i]);
    }

    // Wait for all threads to complete before continuing with the rest of the program
    for (int i = 0; i < MAX_PRIMITIVES; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Handle potential race conditions when multiple threads attempt to add the same primitive simultaneously
    if (!primitives.success) {
        printf("One or more primitives failed to add, attempting to fall back\n");
        // Implement a fallback mechanism if a requested primitive is not available, suggesting alternatives based on user preferences
        for (int i = 0; i < MAX_PRIMITIVES; ++i) {
            const struct primitive *p = &primitives.primitives[i];
            if (!EVP_get_cipherbyname(p->name)) {
                printf("Failed to add %s, trying alternative %s\n", p->name, p->digest ? "digest" : "cipher");
                // If the user has specified a preferred digest or cipher, attempt to add that instead
                if (p->digest) {
                    if (EVP_add_digest(p->digest)) {
                        printf("Successfully added %s\n", p->name);
                    } else {
                        printf("Failed to add %s: %s\n", p->name, ERR_error_string(ERR_get_error(), NULL));
                    }
                } else {
                    if (EVP_add_cipher(p->cipher)) {
                        EVP_add_digest_alias(p->name, p->digest);
                        printf("Successfully added %s\n", p->name);
                    } else {
                        printf("Failed to add %s: %s\n", p->name, ERR_error_string(ERR_get_error(), NULL));
                    }
                }
            }
        }
    }

    // Ensure thread safety when adding cryptographic primitives in a multi-threaded environment
    if (!primitives.success) {
        printf("One or more primitives failed to add, attempting to fall back\n");
        // Implement a fallback mechanism if a requested primitive is not available, suggesting alternatives based on user preferences
        for (int i = 0; i < MAX_PRIMITIVES; ++i) {
            const struct primitive *p = &primitives.primitives[i];
            if (!EVP_get_cipherbyname(p->name)) {
                printf("Failed to add %s, trying alternative %s\n", p->name, p->digest ? "digest" : "cipher");
                // If the user has specified a preferred digest or cipher, attempt to add that instead
                if (p->digest) {
                    if (EVP_add_digest(p->digest)) {
                        printf("Successfully added %s\n", p->name);
                    } else {
                        printf("Failed to add %s: %s\n", p->name, ERR_error_string(ERR_get_error(), NULL));
                    }
                } else {
                    if (EVP_add_cipher(p->cipher)) {
                        EVP_add_digest_alias(p->name, p->digest);
                        printf("Successfully added %s\n", p->name);
                    } else {
                        printf("Failed to add %s: %s\n", p->name, ERR_error_string(ERR_get_error(), NULL));
                    }
                }
            }
        }
    }

    // Clean up the cryptographic primitives after use using EVP_cleanup
    cleanup_cryptographic_primitives(&primitives);
}
