<?php

// DAO class for interacting with the database
class UserDAO {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    // Function to update a user's password in the database
    public function updateUserPassword($userId, $newPassword, $recentPasswords) {
        // Validate the new password based on the given criteria
        if (!$this->validateNewPassword($newPassword)) {
            return false;
        }

        // Check if the user exists in the database
        $user = $this->getUserById($userId);
        if ($user === null) {
            return false;
        }

        // Update the password in the database
        try {
            $this->db->query("UPDATE users SET password=? WHERE id=?", [$newPassword, $userId]);
        } catch (Exception $e) {
            return false;
        }

        // Check if the new password is in the history of recent passwords
        foreach ($recentPasswords as $recentPassword) {
            if ($recentPassword === $newPassword) {
                return false;
            }
        }

        // Return true if the password was successfully updated
        return true;
    }

    // Function to validate a new password based on the given criteria
    private function validateNewPassword($password) {
        // Check if the password is at least 8 characters long
        if (strlen($password) < 8) {
            return false;
        }

        // Check if the password contains at least one uppercase letter, one lowercase letter, one digit, and one special character
        if (!preg_match('/[A-Z]+/', $password)) {
            return false;
        } elseif (!preg_match('/[a-z]+/', $password)) {
            return false;
        } elseif (!preg_match('/\d+/', $password)) {
            return false;
        } elseif (!preg_match('/[^A-Za-z\d]/', $password)) {
            return false;
        }

        // Check if the password is not a common weak password
        if (in_array($password, array("password", "12345678"))) {
            return false;
        }

        // Return true if the password passes all validation checks
        return true;
    }

    // Function to get a user by their ID from the database
    private function getUserById($userId) {
        try {
            $result = $this->db->query("SELECT * FROM users WHERE id=?", [$userId]);
            if ($result === false) {
                return null;
            } elseif (empty($result)) {
                return null;
            }
            return $result[0];
        } catch (Exception $e) {
            return null;
        }
    }
}
