using System;
using UnityEngine;

public class DynamicRandomValueGenerator
{
    // Private field for storing the range limits and distribution metadata
    private (int min, int max) _rangeLimits;
    private DistributionType _distributionType;
    private float _uniformDistributionParameterA;
    private float _uniformDistributionParameterB;

    public DynamicRandomValueGenerator(int min, int max, DistributionType distributionType = DistributionType.Uniform, float uniformDistributionParameterA = 0f, float uniformDistributionParameterB = 1f)
    {
        // Initialize the range limits and distribution metadata
        _rangeLimits = (min, max);
        _distributionType = distributionType;
        _uniformDistributionParameterA = uniformDistributionParameterA;
        _uniformDistributionParameterB = uniformDistributionParameterB;
    }

    // Method for generating random integers within the specified range
    public int GetRandomInteger()
    {
        // Handle edge cases where the range is very small or close to zero
        if (_rangeLimits.min == _rangeLimits.max)
        {
            return _rangeLimits.min;
        }

        // Use UnityEngine.Random.Range to generate a random integer within the specified range
        int value = Random.Range(_rangeLimits.min, _rangeLimits.max);

        // Handle potential errors such as invalid range limits or missing or malformed JSON files
        if (value < _rangeLimits.min || value > _rangeLimits.max)
        {
            throw new Exception("Invalid range limits");
        }

        return value;
    }

    // Method for generating random floats within the specified range
    public float GetRandomFloat()
    {
        // Handle edge cases where the range is very small or close to zero
        if (_rangeLimits.min == _rangeLimits.max)
        {
            return (float)_rangeLimits.min;
        }

        // Use UnityEngine.Random.Range to generate a random float within the specified range
        float value = Random.Range((float)_rangeLimits.min, (float)_rangeLimits.max);

        // Handle potential errors such as invalid range limits or missing or malformed JSON files
        if (value < _rangeLimits.min || value > _rangeLimits.max)
        {
            throw new Exception("Invalid range limits");
        }

        return value;
    }

    // Overridden ToString method to display the current range, distribution type, and any relevant parameters
    public override string ToString()
    {
        string distributionTypeName = _distributionType switch
        {
            DistributionType.Uniform => "Uniform",
            DistributionType.Normal => "Normal",
            _ => throw new ArgumentException("Invalid distribution type"),
        };

        return $"Current range: [{_rangeLimits.min}, {_rangeLimits.max}]\n" +
               $"Distribution type: {distributionTypeName}\n" +
               $"Uniform distribution parameters: ({_uniformDistributionParameterA}, {_uniformDistributionParameterB})";
    }
}
```
