void insertStringAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    // Find the first occurrence of the target string in the list
    auto it = std::find(list.begin(), list.end(), target);

    // If the target string is found, insert the insertion string immediately after it
    if (it != list.end()) {
        list.insert_after(it, insertion);
    } else {
        // If the target string is not found, append the insertion string to the end of the list
        list.push_back(insertion);
    }
}
