        // Initialize the TCP client and network stream
        _client = new TcpClient(host, port);
        _stream = _client.GetStream();
    }

    public DataTableReader ExecuteQueryAndReturnDataTableReader(byte[] queryBytes) {
        try {
            // Send the query to the database server over the network connection
            _stream.Write(queryBytes, 0, queryBytes.Length);

            // Read the response from the database server and parse it as a DataTableReader object
            byte[] response = new byte[1024];
            int bytesRead = _stream.Read(response, 0, response.Length);
            DataTableReader reader = new DataTableReader(response, bytesRead);

            // Return the DataTableReader object
            return reader;
        } catch (Exception ex) {
            Console.WriteLine("Error executing query: " + ex.Message);
            return null;
        } finally {
            _stream.Dispose();
            _client.Close();
        }
    }
}
