public class DynamicRandomValueGenerator
{
    // Private field to store the range limits and distribution metadata
    private (int min, int max) rangeLimits;
    private string distributionType = "uniform";
    private float stddev = 1f;
    private float mean = 0.5f;

    // Methods for generating random integers and floats within the specified range, supporting different types of distributions
    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range(rangeLimits.min, rangeLimits.max + 1);
    }

    public float GenerateRandomFloat()
    {
        if (distributionType == "uniform")
            return UnityEngine.Random.Range(rangeLimits.min, rangeLimits.max + 1) / 2f;
        else if (distributionType == "normal")
            return mean + stddev * UnityEngine.Random.Range(-1f, 1f);
        else
            throw new NotImplementedException("Distribution type not supported");
    }

    // Overridden ToString method to display the current range, distribution type, and any relevant parameters
    public override string ToString()
    {
        return $"Range: [{rangeLimits.min}, {rangeLimits.max}]\nDistribution Type: {distributionType}\nStandard Deviation: {stddev}\nMean: {mean}";
    }

    // Load a state object from a file using an ObjectInputStream and return the object if it is an instance of the MoSTState class; otherwise, return null
    public static DynamicRandomValueGenerator LoadFromFile(string fileName)
    {
        try
        {
            using (ObjectInputStream stream = new ObjectInputStream(new FileStream(fileName, FileMode.Open)))
            {
                object obj = stream.ReadObject();
                if (obj is MoSTState state)
                    return state;
            }
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error loading state from file: {e.Message}");
        }
        return null;
    }

    // Implement thread-safe mechanisms to ensure that the class can handle multiple threads or processes efficiently without causing race conditions or other concurrency issues
    private static readonly object _lockObject = new object();

    public void SetRangeLimits(int min, int max)
    {
        lock (_lockObject)
        {
            rangeLimits.min = min;
            rangeLimits.max = max;
        }
    }

    public void SetDistributionType(string distributionType)
    {
        lock (_lockObject)
        {
            this.distributionType = distributionType;
        }
    }

    public void SetStandardDeviation(float stddev)
    {
        lock (_lockObject)
        {
            this.stddev = stddev;
        }
    }

    public void SetMean(float mean)
    {
        lock (_lockObject)
        {
            this.mean = mean;
        }
    }
}
