#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <math.h>

// Macros for TIFF image format constants
#define TIFF_BYTE 1
#define TIFF_SHORT 2
#define TIFF_LONG 3
#define TIFF_RATIONAL 4
#define TIFF_SBYTE 5
#define TIFF_UNDEFINED 6
#define TIFF_SSHORT 7
#define TIFF_SLONG 8
#define TIFF_SRATIONAL 9
#define TIFF_FLOAT 10
#define TIFF_DOUBLE 11

// Structure to hold parsed TIFF information
typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} tiffInfo_t;

// Function to parse TIFF file and extract information
int parseTIFF(char* fileName, tiffInfo_t* info) {
    // Open the TIFF file
    FILE* fp = fopen(fileName, "r");
    if (fp == NULL) {
        perror("Error opening TIFF file");
        return -1;
    }

    // Read the TIFF header and check for validity
    char buffer[256];
    int bytesRead = fread(buffer, 1, sizeof(buffer), fp);
    if (bytesRead < 0) {
        perror("Error reading TIFF file");
        return -1;
    }
    if (!checkTIFFHeader(buffer)) {
        printf("Error: Invalid TIFF header\n");
        return -1;
    }

    // Parse the TIFF image information
    int bitsPerSample = parseBitsPerSample(buffer);
    int samplesPerPixel = parseSamplesPerPixel(buffer);
    int extraSamples = parseExtraSamples(buffer);

    // Check for unsupported bit depths and return error message
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        printf("Error: Unsupported TIFF bit depth (%d)\n", bitsPerSample);
        return -1;
    }

    // Fill in the tiffInfo_t structure with the parsed information
    info->bitsPerSample = bitsPerSample;
    info->samplesPerPixel = samplesPerPixel;
    info->extraSamples = extraSamples;

    // Close the TIFF file and return success
    fclose(fp);
    return 0;
}

// Function to check the validity of the TIFF header
int checkTIFFHeader(char* buffer) {
    // Check for the "II" or "MM" identifier in the first two bytes
    if (buffer[0] == 'I' && buffer[1] == 'I') return 1;
    else if (buffer[0] == 'M' && buffer[1] == 'M') return 1;
    return 0;
}

// Function to parse the bits per sample from the TIFF header
int parseBitsPerSample(char* buffer) {
    // Read the "BitsPerSample" field in the TIFF header
    int bytesRead = fread(&buffer[12], 1, sizeof(buffer), fp);
    if (bytesRead < 0) return -1;

    // Check for the "BitsPerSample" tag and parse its value
    char* tagName = "BitsPerSample";
    int tagLength = strlen(tagName);
    if (memcmp(&buffer[2], tagName, tagLength)) {
        printf("Error: Invalid TIFF header (missing BitsPerSample tag)\n");
        return -1;
    }
    int bitsPerSample = buffer[4];

    // Return the parsed value
    return bitsPerSample;
}

// Function to parse the samples per pixel from the TIFF header
int parseSamplesPerPixel(char* buffer) {
    // Read the "SamplesPerPixel" field in the TIFF header
    int bytesRead = fread(&buffer[12], 1, sizeof(buffer), fp);
    if (bytesRead < 0) return -1;

    // Check for the "SamplesPerPixel" tag and parse its value
    char* tagName = "SamplesPerPixel";
    int tagLength = strlen(tagName);
    if (memcmp(&buffer[2], tagName, tagLength)) {
        printf("Error: Invalid TIFF header (missing SamplesPerPixel tag)\n");
        return -1;
    }
    int samplesPerPixel = buffer[4];

    // Return the parsed value
    return samplesPerPixel;
}

// Function to parse the extra samples from the TIFF header
int parseExtraSamples(char* buffer) {
    // Read the "ExtraSamples" field in the TIFF header
    int bytesRead = fread(&buffer[12], 1, sizeof(buffer), fp);
    if (bytesRead < 0) return -1;

    // Check for the "ExtraSamples" tag and parse its value
    char* tagName = "ExtraSamples";
    int tagLength = strlen(tagName);
    if (memcmp(&buffer[2], tagName, tagLength)) {
        printf("Error: Invalid TIFF header (missing ExtraSamples tag)\n");
        return -1;
    }
    int extraSamples = buffer[4];

    // Return the parsed value
    return extraSamples;
}
