import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.JSONObject;
import org.json.JSONException;

@SuppressWarnings("serial")
public class UserProfileAPI extends HttpServlet {
    private static final Logger logger = LogManager.getLogger(UserProfileAPI.class);

    // Configuration properties
    private Properties configProps = new Properties();

    @Override
    public void init() throws ServletException {
        String configFilePath = getInitParameter("configFile");
        try (InputStream is = new FileInputStream(configFilePath)) {
            configProps.load(is);
        } catch (IOException e) {
            logger.error("Error loading configuration file: {}", e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userId = request.getParameter("userId");
        JSONObject jsonObj = new JSONObject(request.getReader());
        String operation = jsonObj.getString("operation");

        // Perform action based on the requested operation
        if (operation.equalsIgnoreCase("update")) {
            updateUserProfile(userId, jsonObj);
        } else if (operation.equalsIgnoreCase("delete")) {
            deleteUserProfile(userId);
        } else {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid operation requested");
        }
    }

    private void updateUserProfile(String userId, JSONObject jsonObj) throws IOException {
        // Get the updated profile information from the JSON object
        String name = jsonObj.getString("name");
        int age = jsonObj.getInt("age");
        String address = jsonObj.getString("address");

        // Validate user input to prevent malicious commands
        if (userId == null || name == null || age < 0 || address == null) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid request parameters");
            return;
        }

        // Execute the command to update the user profile
        String command = "bash -c \"sed -i 's/Name: .*/Name: " + name + "/g' /path/to/profile.txt && sed -i 's/Age: .*/Age: " + age + "/g' /path/to/profile.txt && sed -i 's/Address: .*/Address: " + address + "/g' /path/to/profile.txt\"";
        try {
            execCommand(command);
            logger.info("Updated user profile for {}", userId);
        } catch (IOException e) {
            logger.error("Error executing command: {}", e.getMessage());
        }
    }

    private void deleteUserProfile(String userId) throws IOException {
        // Validate the user input to prevent malicious commands
        if (userId == null) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid request parameters");
            return;
        }

        // Execute the command to delete the user profile
        String command = "bash -c \"rm /path/to/profile.txt\"";
        try {
            execCommand(command);
            logger.info("Deleted user profile for {}", userId);
        } catch (IOException e) {
            logger.error("Error executing command: {}", e.getMessage());
        }
    }

    private void execCommand(String command) throws IOException {
        // Set the working directory and disable SSL certificate validation if necessary
        File workingDir = new File("/path/to/working/dir");
        boolean validateCerts = configProps.getProperty("validateCerts", "true").equalsIgnoreCase("false");

        // Execute the command using Runtime.exec()
        Process process = Runtime.getRuntime().exec(command, null, workingDir);
        BufferedReader stdOut = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        // Handle the input/output streams of the process asynchronously using PipedWriter and BufferedReader
        String line;
        while ((line = stdOut.readLine()) != null) {
            logger.info("Standard output: {}", line);
        }
        while ((line = stdError.readLine()) != null) {
            logger.error("Standard error: {}", line);
        }
    }
}
