using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace FinancialTradingSystem
{
    class TransactionProcessor
    {
        private const int MAX_TRANSACTIONS_PER_SECOND = 10000;
        private const int METRICS_UPDATE_FREQUENCY_MS = 60000; // 1 minute

        private static readonly List<Transaction> _transactions = new List<Transaction>();
        private static readonly object _lock = new object();
        private static DateTime _lastMetricsUpdateTime = DateTime.UtcNow;
        private static double _averageWeightedValue = 0;
        private static long _totalVolume = 0;

        public static async Task<(double, string)> ProcessTransaction(Transaction transaction)
        {
            lock (_lock)
            {
                _transactions.Add(transaction);
            }

            if (_transactions.Count > MAX_TRANSACTIONS_PER_SECOND / 10) // rate limiting
            {
                await Task.Delay(10);
            }

            DateTime now = DateTime.UtcNow;
            TimeSpan elapsed = now - _lastMetricsUpdateTime;
            if (elapsed.TotalMilliseconds >= METRICS_UPDATE_FREQUENCY_MS)
            {
                lock (_lock)
                {
                    _averageWeightedValue = CalculateAverageWeightedValue();
                    _totalVolume = CalculateTotalVolume();
                }
                _lastMetricsUpdateTime = now;
            }

            return (Math.Max(_averageWeightedValue, transaction.WeightedValue), transaction.TransactionId);
        }

        private static double CalculateAverageWeightedValue()
        {
            List<int> weights = new List<int>();
            foreach (var transaction in _transactions)
            {
                weights.Add(transaction.WeightedValue);
            }
            return weights.Sum() / weights.Count;
        }

        private static long CalculateTotalVolume()
        {
            return _transactions.Sum(t => t.WeightedValue);
        }
    }

    class Transaction
    {
        public string TransactionId { get; set; }
        public DateTime Timestamp { get; set; }
        public int WeightedValue { get; set; }
    }
}
