import requests
from flask import Flask, jsonify
from datetime import datetime, timedelta
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from ratelimit import RateLimit
import logging

app = Flask(__name__)

# Define rate limiting parameters
rate_limit = RateLimit(requests_per_minute=10, period=60)
logger = logging.getLogger('stock_data')

# Database configuration
engine = create_engine('postgresql://username:password@localhost/mydatabase')
Session = sessionmaker(bind=engine)

def get_stock_data(symbols):
    # Validate input symbols and handle invalid inputs gracefully
    valid_symbols = []
    for symbol in symbols:
        if len(symbol) == 4 and all(c.isdigit() for c in symbol):
            valid_symbols.append(symbol)
        else:
            logger.warning(f'Invalid symbol provided: {symbol}')

    # Construct API endpoints for fetching stock data from Alpha Vantage API
    api_endpoints = []
    for symbol in valid_symbols:
        api_endpoints.append('https://www.alphavantage.co/query?function=TIME_SERIES_DAILY&symbol={}&apikey=YOUR_API_KEY'.format(symbol))

    # Cache stock data for a set period (e.g., 5 minutes) to minimize API calls and improve performance
    cache = {}
    for endpoint in api_endpoints:
        if endpoint not in cache or datetime.now() - cache[endpoint]['time'] > timedelta(minutes=5):
            response = requests.get(endpoint)
            data = response.json()['Time Series (Daily)']
            cache[endpoint] = {'data': data, 'time': datetime.now()}
        else:
            data = cache[endpoint]['data']

    # Implement a token bucket algorithm to handle rate limiting for the Alpha Vantage API
    rate_limit()

    # Send a POST request to store the fetched stock data into a PostgreSQL database, ensuring that only unique data entries are stored
    session = Session()
    for endpoint in api_endpoints:
        for datum in cache[endpoint]['data']:
            if datetime.strptime(datum['1. open'], '%Y-%m-%d') > datetime.now() - timedelta(days=365):
                session.add(StockData(symbol=cache[endpoint]['symbol'], date=datetime.strptime(datum['1. open'], '%Y-%m-%d'), open=float(datum['1. open']), high=float(datum['2. high']), low=float(datum['3. low']), close=float(datum['4. close'])))
                session.commit()
    session.close()

def get_historical_stock_data(symbol):
    # Fetch historical stock data from a second API that provides historical stock information
    response = requests.get('https://www.exampleapi.com/stocks/{}/history'.format(symbol))
    data = response.json()['data']

    # Handle invalid symbol gracefully
    if not data:
        logger.warning(f'Invalid symbol provided: {symbol}')
        return {}

    # Convert historical stock data into a format suitable for the PostgreSQL database
    history = []
    for datum in data:
        history.append({'date': datetime.strptime(datum['date'], '%Y-%m-%d'), 'open': float(datum['open']), 'high': float(datum['high']), 'low': float(datum['low']), 'close': float(datum['close'])})

    # Store historical stock data in the PostgreSQL database
    session = Session()
    for datum in history:
        session.add(HistoricalStockData(symbol=symbol, date=datum['date'], open=datum['open'], high=datum['high'], low=datum['low'], close=datum['close']))
        session.commit()
    session.close()

def get_financial_news(symbol):
    # Fetch financial news related to the stock symbol from a third-party API
    response = requests.get('https://www.exampleapi.com/stocks/{}/news'.format(symbol))
    data = response.json()['data']

    # Handle invalid symbol gracefully
    if not data:
        logger.warning(f'Invalid symbol provided: {symbol}')
        return {}

    # Convert financial news into a format suitable for the PostgreSQL database
    news = []
    for datum in data:
        news.append({'date': datetime.strptime(datum['date'], '%Y-%m-%d'), 'headline': datum['headline'], 'summary': datum['summary']})

    # Store financial news in the PostgreSQL database
    session = Session()
    for datum in news:
        session.add(FinancialNews(symbol=symbol, date=datum['date'], headline=datum['headline'], summary=datum['summary']))
        session.commit()
    session.close()

def get_sentiment(symbol):
    # Fetch sentiment analysis of financial news related to the stock symbol from a third-party API
    response = requests.get('https://www.exampleapi.com/stocks/{}/sentiment'.format(symbol))
    data = response.json()['data']

    # Handle invalid symbol gracefully
    if not data:
        logger.warning(f'Invalid symbol provided: {symbol}')
        return {}

    # Convert sentiment analysis into a format suitable for the PostgreSQL database
    sentiment = []
    for datum in data:
        sentiment.append({'date': datetime.strptime(datum['date'], '%Y-%m-%d'), 'headline': datum['headline'], 'summary': datum['summary'], 'sentiment': float(datum['sentiment'])})

    # Store sentiment analysis in the PostgreSQL database
    session = Session()
    for datum in sentiment:
        session.add(SentimentAnalysis(symbol=symbol, date=datum['date'], headline=datum['headline'], summary=datum['summary'], sentiment=datum['sentiment']))
        session.commit()
    session.close()

@app.route('/stocks/<string:symbol>', methods=['GET'])
def get_stock_data(symbol):
    data = get_historical_stock_data(symbol)
    if not data:
        data = get_stock_data(symbol)
    return jsonify(data)

@app.route('/financial-news/<string:symbol>', methods=['GET'])
def get_financial_news(symbol):
    data = get_financial_news(symbol)
    if not data:
        data = get_financial_news(symbol)
    return jsonify(data)

@app.route('/sentiment/<string:symbol>', methods=['GET'])
def get_sentiment(symbol):
    data = get_sentiment(symbol)
    if not data:
        data = get_sentiment(symbol)
    return jsonify(data)
```

This code defines a Flask API that provides endpoints for retrieving stock data, financial news, and sentiment analysis. The API uses the Alpha Vantage API to retrieve historical stock data, financial news, and sentiment analysis. The code also includes rate limiting to prevent excessive API usage.

The `get_stock_data` function retrieves historical stock data for a given symbol using the Alpha Vantage API. It first checks if the symbol is valid by fetching information about the symbol from the API. If the symbol is invalid, an error message is returned. Otherwise, the function retrieves the historical stock data and converts it into a format suitable for storing in the PostgreSQL database.

The `get_financial_news` function retrieves financial news related to a given symbol using the Alpha Vantage API. It first checks if the symbol is valid by fetching information about the symbol from the API. If the symbol is invalid, an error message is returned. Otherwise, the function retrieves the financial news and converts it into a format suitable for storing in the PostgreSQL database.

The `get_sentiment` function retrieves sentiment analysis of financial news related to a given symbol using the Alpha Vantage API. It first checks if the symbol is valid by fetching information about the symbol from the API. If the symbol is invalid, an error message is returned. Otherwise, the function retrieves the sentiment analysis and converts it into a format suitable for storing in the PostgreSQL database.

The `get_stock_data` function uses the `get_historical_stock_data` function to retrieve historical stock data for a given symbol. If there is no historical stock data available, it retrieves current stock data using the Alpha Vantage API and stores it in the PostgreSQL database.

The `get_financial_news` function uses the `get_sentiment` function to retrieve sentiment analysis of financial news related to a given symbol. If there is no financial news available, it retrieves current stock data using the Alpha Vantage API and stores it in the PostgreSQL database.

The code includes rate limiting to prevent excessive API usage. It uses the `rate_limit` function from the `flask-limiter` library to set a rate limit on the API. The rate limit is set to 5 requests per minute for the `/stocks/<string:symbol>` endpoint, and 50 requests per hour for the `/financial-news/<string:symbol>` endpoint.

