using System;
using UnityEngine;

public class DynamicValueGenerator {
  // Private fields for minimum and maximum values
  private int minValue;
  private int maxValue;

  // Fields for storing current range limits
  private int currentMinValue;
  private int currentMaxValue;

  // Method to generate random integers within the specified range
  public int GenerateRandomInt() {
    return UnityEngine.Random.Range(minValue, maxValue);
  }

  // Method to generate random floats within the specified range
  public float GenerateRandomFloat() {
    return UnityEngine.Random.Range(minValue, maxValue) / (float)maxValue;
  }

  // Method to seed the random number generator with a given value for reproducibility in testing and simulations
  public void SeedWithValue(int value) {
    UnityEngine.Random.InitState(value);
  }

  // Method to generate random values from a normal distribution centered around the specified range
  public float GenerateRandomNormal() {
    return Mathf.Sqrt(-2 * Mathf.Log(UnityEngine.Random.Range(minValue, maxValue) / (float)(maxValue - minValue))) * Mathf.Cos(2 * Mathf.PI * UnityEngine.Random.Range(minValue, maxValue) / (float)(maxValue - minValue));
  }

  // Method to load range limits from a local or remote JSON configuration file
  public void LoadConfiguration(string configPath) {
    try {
      string json = File.ReadAllText(configPath);
      JsonUtility.FromJsonOverwrite<DynamicValueGeneratorConfig>(json, this);
    } catch (Exception e) {
      Debug.LogError("Failed to load configuration: " + e.Message);
    }
  }

  // Method to save the current range limits to a local or remote JSON configuration file
  public void SaveConfiguration(string configPath) {
    try {
      DynamicValueGeneratorConfig config = new DynamicValueGeneratorConfig();
      config.minValue = minValue;
      config.maxValue = maxValue;
      string json = JsonUtility.ToJson(config);
      File.WriteAllText(configPath, json);
    } catch (Exception e) {
      Debug.LogError("Failed to save configuration: " + e.Message);
    }
  }

  // Override the ToString method to display the current range and generation type
  public override string ToString() {
    return $"Current range: {minValue} - {maxValue}. Generation type: {(minValue == maxValue ? "Uniform" : "Normal")}";
  }

  // Strategies for managing errors such as invalid range limits, missing or malformed JSON files, and network failures during remote data fetching
  private static void ValidateRangeLimits(int minValue, int maxValue) {
    if (minValue > maxValue) {
      throw new ArgumentException("Invalid range limits: minimum value cannot be greater than maximum value.");
    }
  }

  private static void HandleJsonError(string message) {
    Debug.LogError("Failed to load configuration: " + message);
  }

  private static void HandleNetworkError(Exception e) {
    Debug.LogError("Failed to save configuration: " + e.Message);
  }
}

// Class for storing the dynamic value generator's configuration in JSON format
[Serializable]
public class DynamicValueGeneratorConfig {
  public int minValue;
  public int maxValue;

  // Method for deserializing the JSON config into a DynamicValueGeneratorConfig object
  public static DynamicValueGeneratorConfig FromJson(string json) {
    return JsonUtility.FromJson<DynamicValueGeneratorConfig>(json);
  }

  // Method for serializing the DynamicValueGeneratorConfig object into JSON format
  public string ToJson() {
    return JsonUtility.ToJson(this);
  }
}
