using namespace std;

// Define the structure to hold the configuration parameters
struct Configuration {
    int port;
    int max_connections;
    string listen_address;
    vector<string> allowed_client_ips;
};

// Function to read the configuration file and populate the Configuration struct
void readConfig(const string& configFile, Configuration& config) {
    ifstream file(configFile);
    if (!file.is_open()) {
        throw runtime_error("Could not open configuration file");
    }

    // Read the port number
    int port;
    file >> port;
    if (port <= 0) {
        throw runtime_error("Invalid port number");
    }

    // Read the maximum number of connections
    int maxConnections;
    file >> maxConnections;
    if (maxConnections <= 0) {
        throw runtime_error("Invalid maximum number of connections");
    }

    // Read the listen address
    string listenAddress;
    getline(file, listenAddress);
    if (listenAddress.empty()) {
        throw runtime_error("Invalid listen address");
    }

    // Read the list of allowed client IP addresses
    vector<string> allowedClientIPs;
    while (!file.eof()) {
        string ip;
        getline(file, ip);
        if (ip.empty()) {
            break;
        }
        allowedClientIPs.push_back(ip);
    }

    // Validate the configuration parameters
    if (port <= 0 || maxConnections <= 0 || listenAddress.empty() || allowedClientIPs.empty()) {
        throw runtime_error("Invalid configuration parameters");
    }

    config.port = port;
    config.max_connections = maxConnections;
    config.listen_address = listenAddress;
    config.allowed_client_ips = allowedClientIPs;
}

