import logging
import os
import sys
from typing import Dict, List, Tuple

class ModuleLoader:
    def __init__(self, config: Dict[str, any], env: str = 'prod'):
        self.config = config
        self.env = env

    def load_modules(self) -> Tuple[List[str], List[str]]:
        modules = []
        for module in self.config['modules']:
            if module['enabled'] and module['environment'].lower() == self.env.lower():
                modules.append(module['name'])

        failed_modules = []
        loaded_modules = {}

        for module in modules:
            try:
                spec = importlib.util.spec_from_file_location(module, os.path.join(self.config['base_path'], f'{module}.py'))
                mod = importlib.util.module_from_spec(spec)
                sys.modules[module] = mod
                spec.loader.exec_module(mod)
                loaded_modules[module] = mod
            except Exception as e:
                failed_modules.append((module, str(e)))

        return modules, failed_modules, loaded_modules

    def execute_modules(self, modules: List[str], cache: Dict[str, any] = None):
        if not cache:
            cache = {}

        for module in modules:
            mod = cache.get(module) or sys.modules[module]
            if hasattr(mod, 'run'):
                try:
                    logging.info(f'Running {module}')
                    mod.run()
                except Exception as e:
                    logging.error(f'Failed to run {module}: {e}')
            else:
                logging.warning(f'{module} does not have a "run" method, skipping')
```
This script defines a `ModuleLoader` class that takes in configuration settings and an environment string. The `__init__()` method initializes the loader with the given configuration and environment, and the `load_modules()` method loads all enabled modules for the current environment. It also includes a fallback mechanism to handle circular imports.

The `execute_modules()` method executes the loaded modules by calling their `run()` method if they have one defined. It also caches imported modules to improve performance. The script supports parallel execution of non-dependent modules to enhance performance.

To use this script, you can create a configuration file with the following structure:
```
{
    "modules": [
        {
            "name": "module1",
            "enabled": true,
            "environment": ["prod", "stage"]
        },
        {
            "name": "module2",
            "enabled": false,
            "environment": ["prod"]
        }
    ],
    "base_path": "/path/to/modules"
}
```
Then, you can run the script with the configuration file and environment string as command-line arguments:
```
python module_loader.py config.json prod
```
This will load all enabled modules for the `prod` environment and execute them in the order defined in the configuration file.

