    public async Task<T> LoadDataAsync<T>(string filePath, string extension, int retries = 3, int retryDelay = 1000) where T : class
    {
        if (filePath == null) throw new ArgumentNullException(nameof(filePath));
        if (extension == null) throw new ArgumentNullException(nameof(extension));

        // Check for supported file extensions and compression algorithms
        bool isSupported = IsSupportedFileExtension(extension) && IsSupportedCompressionAlgorithm(extension);
        if (!isSupported)
            throw new NotSupportedException($"The file extension '{extension}' or the compression algorithm are not supported.");

        // Fetch file names from REST API
        string[] fileNames = await GetFileNamesAsync();
        if (fileNames == null || !fileNames.Any())
