        string fileName = FindMatchingFileName(fileNames, extension);
        using FileStream fileStream = await DecompressFileAsync(fileName, retries, retryDelay);
        if (fileStream == null) throw new Exception("Failed to decompress the file");

        // Deserialize the data from the decompressed stream
        T data = await DeserializeDataAsync<T>(fileStream);
        if (data == null) throw new Exception("Failed to deserialize the data");

        return data;
    }

