#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/evp.h>
#include <openssl/err.h>

#define MAX_IV_LENGTH 16
#define KEY_SIZE 32

// Struct to store KDF parameters
struct kdf_params {
    const EVP_MD *kdf;
    int rounds;
};

// Map of supported KDFs and their corresponding params
const struct kdf_params kdfs[] = {
    {EVP_sha256(), 1000}, // PBKDF2-HMAC-SHA256 with 1000 rounds
    {EVP_bcrypt(), 12},   // bcrypt with 12 rounds
    {EVP_scrypt(), 18},   // scrypt with 18 rounds
    {EVP_argon2i(), 3},   // Argon2i with 3 rounds
};

// Function to generate a random IV of given length
void generate_iv(unsigned char *iv, int iv_len) {
    unsigned char rand[16];
    RAND_bytes(rand, sizeof(rand));
    memcpy(iv, rand, iv_len);
}

// Function to derive a key from a password and a KDF
int derive_key(const EVP_MD *kdf, const unsigned char *password, int pwd_len, unsigned char *derived_key, int key_size) {
    if (!EVP_PBE_CipherInit(kdf, NULL, password, pwd_len)) {
        printf("Error initializing KDF\n");
        return 0;
    }

    // Generate a random IV and set it as the salt for the KDF
    unsigned char iv[MAX_IV_LENGTH];
    generate_iv(iv, sizeof(iv));
    EVP_PBE_CipherInit(kdf, NULL, password, pwd_len);
    EVP_PBE_set_salt(kdf, (unsigned char *)&iv, sizeof(iv));

    // Derive the key using the KDF
    int key_len = EVP_PBE_key_length(kdf);
    if (!EVP_PBE_Cipher(&derived_key, &key_len, NULL, 0)) {
        printf("Error deriving key\n");
        return 0;
    }

    // Set the derived key as the key for the AES-256-CBC cipher
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit(ctx, EVP_aes_256_cbc(), derived_key, iv)) {
        printf("Error initializing AES-256-CBC\n");
        return 0;
    }

    // Generate a random IV for the encryption operation and set it as the nonce
    unsigned char nonce[MAX_IV_LENGTH];
    generate_iv(nonce, sizeof(nonce));
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, MAX_IV_LENGTH, 0);
    if (!EVP_EncryptInit(ctx, NULL, NULL, nonce)) {
        printf("Error initializing IV\n");
        return 0;
    }

    // Encrypt the input data using the AES-256-CBC cipher
    int output_len = 0;
    if (!EVP_EncryptUpdate(ctx, NULL, &output_len, (unsigned char *)input, strlen(input))) {
        printf("Error encrypting data\n");
        return 0;
    }

    // Clean up memory and return the encrypted output
    EVP_CIPHER_CTX_free(ctx);
    return output_len;
}

// Function to handle key derivation operations and record them in a log file
void handle_kdf(const unsigned char *password, int pwd_len, const struct kdf_params *params) {
    // Derive the key using the given KDF parameters
    unsigned char derived_key[KEY_SIZE];
    if (!derive_key(params->kdf, password, pwd_len, derived_key, KEY_SIZE)) {
        printf("Error deriving key\n");
        return;
    }

    // Log the KDF operation using a user-friendly format
    char log_message[512];
    sprintf(log_message, "KDF: %s, Rounds: %d", EVP_MD_get0_name(params->kdf), params->rounds);
    printf("%s\n", log_message);
}

// Function to handle encryption operations and record them in a log file
void handle_encryption(const unsigned char *input, const unsigned char *password, int pwd_len) {
    // Derive the key using a given password and KDF parameters
    struct kdf_params params = {EVP_sha256(), 1000};
    if (!derive_key(params.kdf, password, pwd_len, derived_key, KEY_SIZE)) {
        printf("Error deriving key\n");
        return;
    }

    // Set the derived key as the key for the AES-256-CBC cipher
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit(ctx, EVP_aes_256_cbc(), derived_key, iv)) {
        printf("Error initializing AES-256-CBC\n");
        return;
    }

    // Generate a random IV for the encryption operation and set it as the nonce
    unsigned char nonce[MAX_IV_LENGTH];
    generate_iv(nonce, sizeof(nonce));
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, MAX_IV_LENGTH, 0);
    if (!EVP_EncryptInit(ctx, NULL, NULL, nonce)) {
        printf("Error initializing IV\n");
        return;
    }

    // Encrypt the input data using the AES-256-CBC cipher
    int output_len = 0;
    if (!EVP_EncryptUpdate(ctx, NULL, &output_len, (unsigned char *)input, strlen(input))) {
        printf("Error encrypting data\n");
        return;
    }

    // Clean up memory and return the encrypted output
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    const unsigned char *password = "password";
    int pwd_len = strlen(password);

    struct kdf_params params[] = {EVP_sha256(), 1000, EVP_sha512(), 2000};

    for (int i = 0; i < sizeof(params) / sizeof(params[0]); i++) {
        handle_kdf(password, pwd_len, &params[i]);
    }

    return 0;
}
```

