    boost::asio::ip::tcp::endpoint listen_address;

    // Define the list of allowed client IP addresses
    std::vector<std::string> allowed_client_ips;

    // Define the rate limiting parameters
    int max_requests_per_minute;

    // Define a custom log file path
    std::string log_file_path;

    // Define a variable to store the server status
    bool server_running;

public:
    Server(std::string config_file_path, int server_port, int max_connections) {
        // Initialize the connection pool with an empty set of sockets
        connection_pool = boost::make_shared<boost::unordered_set<boost::asio::ip::tcp::socket*>>();

        // Set the configuration file path and server port
        this->config_file_path = config_file_path;
        this->server_port = server_port;

        // Set the maximum number of concurrent connections
        this->max_connections = max_connections;

        // Initialize the list of allowed client IP addresses and rate limiting settings to an empty map
        rate_limits = boost::unordered_map<std::string, int>();
        request_counts = boost::unordered_map<std::string, int>();

        // Set the server status to false (i.e., not running)
        server_running = false;
    }

    void start() {
        // Start the server by reading the configuration file and setting up the connection pool
        readConfigFile();
        setupConnectionPool();

        // Set the server status to true (i.e., running)
        server_running = true;

        // Run the server in a loop, accepting incoming connections and processing requests
        while (server_running) {
            boost::asio::ip::tcp::socket* new_connection = acceptConnection();
            if (new_connection != NULL) {
                processRequest(new_connection);
            }
        }
    }

    void stop() {
        // Stop the server by setting the server status to false
        server_running = false;
    }

    boost::asio::ip::tcp::socket* acceptConnection() {
        // Accept an incoming connection from the client
        boost::asio::ip::tcp::acceptor acceptor(boost::asio::io_service::strand(), listen_address);
        boost::asio::ip::tcp::socket socket(acceptor.get_io_service());
        acceptor.accept(socket);

        // Check if the client IP address is allowed and if the rate limit has been exceeded
        std::string client_ip = socket.remote_endpoint().address().to_string();
        if (!checkClientIPAllowed(client_ip)) {
            return NULL;
        } else if (checkRateLimitExceeded(client_ip)) {
            return NULL;
        }

        // Add the new connection to the connection pool and return it
        boost::mutex::scoped_lock lock(connection_pool_mutex);
        connection_pool->insert(&socket);
        return &socket;
    }

    void processRequest(boost::asio::ip::tcp::socket* socket) {
        // Process the incoming request from the client
        boost::system::error_code error;
        std::string request = readRequest(socket, error);
        if (!error) {
            // Check if the request is allowed and if the rate limit has been exceeded
            std::string client_ip = socket.remote_endpoint().address().to_string();
            if (checkClientIPAllowed(client_ip) && !checkRateLimitExceeded(client_ip)) {
                // Update the request count for the client IP address and log the request
                updateRequestCount(client_ip);
                logRequest(request);

                // Process the request and send a response back to the client
                processResponse(socket, request);
            } else {
                // Close the connection if the request is not allowed or the rate limit has been exceeded
                closeConnection(socket);
            }
        } else {
            // Close the connection if there was an error reading the request from the client
            closeConnection(socket);
        }
    }

    void readConfigFile() {
        // Read the configuration file and set up the server with the appropriate parameters
        boost::filesystem::ifstream config_file(config_file_path.c_str());
        std::string line;
        while (std::getline(config_file, line)) {
            std::vector<std::string> tokens;
            boost::split(tokens, line, boost::is_any_of(" "));
            if (tokens.size() > 0) {
                if (tokens[0] == "listen") {
                    listen_address = boost::asio::ip::tcp::endpoint(boost::asio::ip::address::from_string(tokens[1]), std::stoi(tokens[2]));
                } else if (tokens[0] == "max_connections") {
                    max_connections = std::stoi(tokens[1]);
                } else if (tokens[0] == "allowed_client_ips") {
                    for (int i = 1; i < tokens.size(); ++i) {
                        addClientIP(boost::asio::ip::address::from_string(tokens[i]));
                    }
                } else if (tokens[0] == "rate_limit") {
                    for (int i = 1; i < tokens.size(); ++i) {
                        addRateLimit(std::stoi(tokens[i]));
                    }
                } else if (tokens[0] == "log_file") {
                    log_file = tokens[1];
                }
            }
        }
    }

    void setupConnectionPool() {
        // Set up the connection pool by creating a new acceptor and adding it to the pool
        boost::asio::ip::tcp::acceptor acceptor(boost::asio::io_service::strand(), listen_address);
        connection_pool.insert(&acceptor);
    }

    void updateRequestCount(std::string client_ip) {
        // Update the request count for the client IP address by incrementing it by one
        boost::mutex::scoped_lock lock(request_count_mutex);
        if (request_count.find(client_ip) != request_count.end()) {
            request_count[client_ip]++;
        } else {
            request_count[client_ip] = 1;
        }
    }

    void logRequest(std::string request) {
        // Log the incoming request by writing it to the log file
        std::ofstream log_file_stream(log_file.c_str(), std::ios_base::app);
        if (log_file_stream.is_open()) {
            log_file_stream << "[" << boost::posix_time::to_iso_string(boost::posix_time::second_clock::local_time()) << "] - " << request << std::endl;
        }
    }

    void processResponse(boost::asio::ip::tcp::socket* socket, std::string request) {
        // Process the incoming request by sending a response back to the client
        boost::system::error_code error;
        std::string response = processRequest(request);
        writeResponse(socket, response, error);
    }

    void closeConnection(boost::asio::ip::tcp::socket* socket) {
        // Close the connection by removing it from the connection pool and closing the socket
        boost::mutex::scoped_lock lock(connection_pool_mutex);
        connection_pool.erase(socket);
        socket->close();
    }

    bool checkClientIPAllowed(std::string client_ip) {
        // Check if the client IP address is allowed by checking it against the list of allowed client IP addresses
        boost::mutex::scoped_lock lock(client_ip_mutex);
        return (allowed_client_ips.find(client_ip) != allowed_client_ips.end());
    }

    bool checkRateLimitExceeded(std::string client_ip) {
        // Check if the rate limit has been exceeded by checking it against the current request count for the client IP address
        boost::mutex::scoped_lock lock(request_count_mutex);
        return (request_count[client_ip] > rate_limit);
    }

private:
    std::string log_file;
    int rate_limit;
    boost::asio::io_service io_service;
    boost::mutex client_ip_mutex;
    boost::unordered_set<boost::asio::ip::address> allowed_client_ips;
    boost::mutex request_count_mutex;
    std::map<std::string, int> request_count;
    boost::mutex connection_pool_mutex;
    boost::unordered_set<boost::asio::ip::tcp::socket*> connection_pool;
};

int main() {
    // Create a new instance of the server class and start it
    Server server("config.txt", 8080);
    server.start();
}

