// Structure to hold the NFAPI_CRC_INDICATION_PDU and its associated data
typedef struct {
    NFAPI_CRC_INDICATION_PDU pdu;
    RX_UE_INFORMATION_TAG rx_ue_tag;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
