// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDUs
void *generate_crc_indication_pdus(void *arg) {
    PDU_DATA *pdu_data = (PDU_DATA *) arg;
    RX_UE_INFORMATION_TAG rx_ue_tag = pdu_data->rx_ue_tag;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag = pdu_data->crc_ind_rel8_tag;

    // Get the CRC count from the data source
    int crccount = ((DATA_SOURCE *)pdu_data->data_source)->get_crccount(rx_ue_tag.rnti);

    // Set the CRCFLAG value to a random value between MIN_CRCFLAG and MAX_CRCFLAG
    crc_ind_rel8_tag.crcflag = (rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1)) + MIN_CRCFLAG;

    // Set the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG values in the PDU
    pdu_data->pdu.rx_ue_information.tag = rx_ue_tag;
    pdu_data->pdu.crc_indication_rel8.tag = crc_ind_rel8_tag;

    // Log the successful operation
    printf("Successfully generated CRC indication PDU for RNTI %d with CRCFLAG %u\n", rx_ue_tag.rnti, crc_ind_rel8_tag.crcflag);
}

