// Function to manage concurrent access from multiple threads generating up to 10,000 PDUs simultaneously
void *manage_thread_pool(void *arg) {
    pthread_t *threads = (pthread_t *) arg;
    int thread_count = sizeof(threads) / sizeof(pthread_t);

    // Create a thread pool with the maximum number of threads allowed
    pthread_t thread_pool[MAX_THREADS];

    // Initialize the thread pool
    for (int i = 0; i < MAX_THREADS; i++) {
        thread_pool[i] = NULL;
    }

    // Loop through each thread and create a new PDU_DATA structure for it
    for (int i = 0; i < thread_count; i++) {
        pthread_t thread = threads[i];
        void *arg = (void *) malloc(sizeof(PDU_DATA));
        if (!arg) {
            printf("Error: Failed to allocate memory for PDU_DATA\n");
            exit(1);
        }
        memset(arg, 0, sizeof(PDU_DATA));
        thread_pool[i] = thread;
    }

    // Loop through each thread and execute the generate_crc_indication_pdus function for it
    for (int i = 0; i < thread_count; i++) {
        pthread_t thread = threads[i];
        PDU_DATA *pdu_data = (PDU_DATA *) arg;
        generate_crc_indication_pdus(pdu_data);
    }
}

