import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class RestClient {
    private static final Logger LOGGER = Logger.getLogger(RestClient.class.getName());
    private static final Duration RATE_LIMIT_DURATION = Duration.ofSeconds(1);
    private static final int MAX_RETRIES = 3;
    private static final Executors EXECUTORS = Executors.newCachedThreadPool();

    public <T> Optional<T> sendRequest(String endpoint, String method, Object payload) {
        HttpClient client = HttpClient.newHttpClient();
        URI uri = URI.create("https://api.example.com" + endpoint);
        HttpRequest request = HttpRequest.newBuilder()
                .uri(uri)
                .method(method, Optional.ofNullable(payload).map(String::getBytes).orElse(null))
                .build();

        return sendRequest(client, request, RATE_LIMIT_DURATION, MAX_RETRIES);
    }

    private <T> Optional<T> sendRequest(HttpClient client, HttpRequest request, Duration rateLimitDuration, int maxRetries) {
        try {
            var response = client.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() == 200) {
                return Optional.of(response.body());
            } else if (response.statusCode() == 429) {
                Thread.sleep(rateLimitDuration.toMillis());
                return sendRequest(client, request, rateLimitDuration, maxRetries - 1);
            } else {
                LOGGER.log(Level.WARNING, "Received unexpected status code: " + response.statusCode());
                if (maxRetries > 0) {
                    Thread.sleep(rateLimitDuration.toMillis());
                    return sendRequest(client, request, rateLimitDuration, maxRetries - 1);
                } else {
                    throw new RuntimeException("Failed to send request after " + maxRetries + " retries");
                }
            }
        } catch (InterruptedException | IOException e) {
            LOGGER.log(Level.SEVERE, "Error sending request", e);
            return Optional.empty();
        }
    }
}
```
