        self.transmission_id = transmission_id
        self.data_packet = data_packet
        self.status = status

def manage_nf_data(nf_data_list: List[NFData]) -> None:
    # Generate random data packet for each NFData instance
    for nf_data in nf_data_list:
        nf_data.data_packet = bytes([random.randint(0, 255) for _ in range(1000)])

    # Set status based on simulated transmission success rate
    for nf_data in nf_data_list:
