        public async Task<IActionResult> UpdateElement([FromBody] string htmlContent, Guid pageSectionId, Guid elementId)
        {
            try
            {
                // Validate input data
                if (string.IsNullOrWhiteSpace(htmlContent))
                {
                    return BadRequest("HTML content is required.");
                }

                // Update element's HTML content using a service class
                var updatedElement = await _pageSectionService.UpdateElementHtmlAsync(pageSectionId, elementId, htmlContent);

                // Notify cache invalidation service to clear the corresponding page section cache
                if (updatedElement != null)
                {
                    _cacheInvalidationService.ClearCache(updatedElement.PageSectionId);
                }

                return Ok();
            }
