public class DatabaseClient
{
    private readonly TcpClient _client;
    private readonly NetworkStream _stream;
    private readonly byte[] _buffer;

    public DatabaseClient(string host, int port)
    {
        _client = new TcpClient(host, port);
        _stream = _client.GetStream();
        _buffer = new byte[8192];
    }

    public DataTableReader ExecuteQueryAndReturnDataTableReader(byte[] queryBytes)
    {
        // Send the query to the server over the network stream
        _stream.Write(queryBytes, 0, queryBytes.Length);

        // Read the response from the server
        int bytesRead = _stream.Read(_buffer, 0, _buffer.Length);

        // Convert the response to a DataTableReader object
        DataTableReader reader = new DataTableReader(new DataTable());
        for (int i = 0; i < bytesRead; i++) {
            byte b = _buffer[i];
            reader.GetBytes(b);
        }

        return reader;
    }
}
