        memcpy(pdu->crc_indication_rel8_tag, crcflag_value.value, NFAPI_CRC_INDICATION_REL8_TAG_SIZE);
        pdu_list.pdus[pdu_list.count++] = *pdu;
    }
    return pdu_list;
}

struct CRCFLAG_VALUE get_random_crcflag() {
    struct CRCFLAG_VALUE crcflag_value;
    crcflag_value.isSet = false;
    for (int i = 0; i < CRCFLAG_SIZE; i++) {
        crcflag_value.value[i] = rand() % 2;
        if (!crcflag_value.isSet) {
            crcflag_value.isSet = true;
        } else {
            break;
        }
    }
    return crcflag_value;
}

struct CONFIGURATION *create_configuration(const char *rx_ue_information_tag, unsigned int crcflag_value) {
