    memcpy(configuration->rx_ue_information_tag, rx_ue_information_tag, RX_UE_INFORMATION_TAG_SIZE);
    configuration->crcflag_value[0] = crcflag_value;
    return configuration;
}

void destroy_configuration(struct CONFIGURATION *configuration) {
