    public class RandomValueGenerator
    {
        private readonly object _lock = new object();
        private double _minValue;
        private double _maxValue;
        private int _precision;

        // Cache the JSON configuration file locally to minimize frequent reads from remote sources
        private string _jsonConfigFilePath;
        private string _configJson;

        public RandomValueGenerator(string jsonConfigFilePath)
        {
            _jsonConfigFilePath = jsonConfigFilePath;
            LoadConfig();
        }

        // Method to fetch the random value from the JSON configuration file
        public double GetRandomValue()
        {
            lock (_lock)
            {
                if (DateTime.Now - _lastReadTime > TimeSpan.FromSeconds(30))
                {
                    LoadConfig();
                }
                return GetRandomValueInternal();
            }
        }

        private double GetRandomValueInternal()
        {
            var random = new Random((int)(_minValue + _maxValue) / 2);
            return (random.NextDouble() * (_maxValue - _minValue)) + _minValue;
        }

        // Method to update the range limits in the JSON configuration file
        public void UpdateRangeLimits(double minValue, double maxValue, int precision)
        {
            lock (_lock)
            {
                _minValue = minValue;
                _maxValue = maxValue;
                _precision = precision;
                SaveConfig();
            }
        }

        // Method to fetch the range limits from the JSON configuration file
        public (double, double, int) GetRangeLimits()
        {
            lock (_lock)
            {
                return (_minValue, _maxValue, _precision);
            }
        }

        private void LoadConfig()
        {
            var json = File.ReadAllText(_jsonConfigFilePath);
            if (string.IsNullOrEmpty(json))
            {
                throw new Exception("Failed to read JSON configuration file.");
            }

            try
            {
                _configJson = json;
            }
            catch (Exception ex)
            {
                throw new Exception($"Failed to parse JSON configuration file: {ex.Message}");
            }
        }

        private void SaveConfig()
        {
            try
            {
                File.WriteAllText(_jsonConfigFilePath, _configJson);
            }
            catch (Exception ex)
            {
                throw new Exception($"Failed to save JSON configuration file: {ex.Message}");
            }
        }
    }
}
