    public class RandomWeightedSumCalculator
    {
        private readonly object _lock = new object();
        private double _maxWeightedSum;
        private string _transactionId;
        private List<Transaction> _transactions;

        // Priority queue to efficiently find the transaction with the highest weighted sum without sorting the entire list every time a new transaction is added
        private readonly PriorityQueue<Transaction> _priorityQueue = new PriorityQueue<Transaction>();

        public RandomWeightedSumCalculator()
        {
            _transactions = new List<Transaction>();
            _maxWeightedSum = 0;
        }

        // Method to add a transaction to the priority queue
        public void AddTransaction(string id, double weight)
        {
            lock (_lock)
            {
                var transaction = new Transaction()
                {
                    Id = id,
                    Weight = weight
                };
                _priorityQueue.Enqueue(transaction);
            }
        }

        // Method to update the maximum weighted sum based on the priority queue
        public void UpdateMaxWeightedSum()
        {
            lock (_lock)
            {
                _maxWeightedSum = _priorityQueue.Peek().Weight;
                while (_priorityQueue.Count > 0 && _priorityQueue.Peek().Weight <= _maxWeightedSum)
                {
                    var transaction = _priorityQueue.Dequeue();
                    if (transaction.Weight > _maxWeightedSum)
                    {
                        _maxWeightedSum = transaction.Weight;
                        _transactionId = transaction.Id;
                    }
                }
            }
        }

        // Method to fetch the maximum weighted sum and corresponding transaction ID from the priority queue
        public (double, string) GetMaxWeightedSum()
        {
            lock (_lock)
            {
                return (_maxWeightedSum, _transactionId);
            }
        }
    }
}
