using System;
using System.Collections.Generic;
using System.Linq;

namespace DynamicRandomValueGenerator
{
    public class PriorityQueue<T> where T : IComparable<T>
    {
        private readonly List<T> _heap = new List<T>();

        // Method to add an item to the priority queue
        public void Enqueue(T item)
        {
            int i = 0;
            while (i < _heap.Count && _heap[i].CompareTo(item) >= 0)
            {
                i++;
            }
            _heap.Insert(i, item);
        }

        // Method to remove the highest-priority item from the priority queue
        public T Dequeue()
        {
            var item = _heap[0];
            _heap[0] = _heap[_heap.Count - 1];
            _heap.RemoveAt(_heap.Count - 1);
            HeapifyDown(0);
            return item;
        }

        // Method to peek at the highest-priority item in the priority queue without removing it
        public T Peek()
        {
            if (_heap.Count == 0)
            {
                throw new InvalidOperationException("Priority queue is empty.");
            }
            return _heap[0];
        }

        // Method to check whether the priority queue is empty or not
        public bool IsEmpty()
        {
            return _heap.Count == 0;
        }

        private void HeapifyDown(int i)
        {
            while (true)
            {
                int child = 2 * i + 1;
                if (child >= _heap.Count)
                {
                    break;
                }
                int rightChild = child + 1;
                if (rightChild < _heap.Count && _heap[rightChild].CompareTo(_heap[child]) > 0)
                {
                    child = rightChild;
                }
                if (_heap[child].CompareTo(_heap[i]) >= 0)
                {
                    break;
                }
                T tmp = _heap[child];
                _heap[child] = _heap[i];
                _heap[i] = tmp;
                i = child;
            }
        }
    }
}
