    public class Randomizer<T> where T : IComparable<T>
    {
        private readonly PriorityQueue<T> _priorityQueue = new PriorityQueue<T>();

        // Method to add an item to the priority queue
        public void AddItem(T item)
        {
            _priorityQueue.Enqueue(item);
        }

        // Method to remove the highest-priority item from the priority queue
        public T RemoveItem()
        {
            return _priorityQueue.Dequeue();
        }

        // Method to peek at the highest-priority item in the priority queue without removing it
        public T PeekItem()
        {
            return _priorityQueue.Peek();
        }

        // Method to check whether the priority queue is empty or not
        public bool IsEmpty()
        {
            return _priorityQueue.IsEmpty();
        }
    }
}
