typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} nfapi_crc_indication_pdu_t;

// Define a thread pool to manage concurrent access from multiple threads
#define THREAD_POOL_SIZE 10
pthread_t thread_pool[THREAD_POOL_SIZE];
semaphore_t semaphore;

// Define a function to dynamically generate and populate a forward list of NFAPI_CRC_INDICATION_PDUs
void generate_crc_indication_pdu(nfapi_crc_indication_pdu_t *pdu, uint32_t rx_ue_information_tag, uint16_t rnti) {
    // Initialize the PDU with the specified RX_UE_INFORMATION_TAG and RNTI
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;

    // Set a random value for the CRCFLAG field
    uint8_t crcflag = rand() % 2;
    pdu->crc_indication_rel8_tag = crcflag;
}

// Define a function to handle concurrent access from multiple threads
void *handle_thread(void *args) {
    // Cast the arguments to a pointer to an integer
    int thread_index = (intptr_t) args;

    // Create a local copy of the thread pool and semaphore
    pthread_t thread_pool[THREAD_POOL_SIZE];
    semaphore_t semaphore;

    // Initialize the local copy of the thread pool and semaphore
    for (int i = 0; i < THREAD_POOL_SIZE; i++) {
        thread_pool[i] = pthread_self();
        semaphore_init(&semaphore, 1);
    }

    // Generate and populate the NFAPI_CRC_INDICATION_PDUs in a loop
    for (int i = 0; i < 10000; i++) {
        // Acquire the semaphore to access the shared data structure
        semaphore_wait(&semaphore);

        // Generate and populate a new NFAPI_CRC_INDICATION_PDU
        nfapi_crc_indication_pdu_t *pdu = (nfapi_crc_indication_pdu_t *) malloc(sizeof(nfapi_crc_indication_pdu_t));
        generate_crc_indication_pdu(pdu, i, rand() % 1024);

        // Add the new PDU to the forward list
        forward_list_add(&forward_list, pdu);

        // Release the semaphore to release the shared data structure
        semaphore_post(&semaphore);
    }

    // Return the thread to the main function
    return NULL;
}

// Define a function to manage concurrent access from multiple threads and adjust the size of the thread pool dynamically
void generate_crc_indication_pdus(int num_threads, int timeout) {
    // Initialize the thread pool and semaphore
    for (int i = 0; i < THREAD_POOL_SIZE; i++) {
        thread_pool[i] = pthread_self();
        semaphore_init(&semaphore, 1);
    }

    // Create a barrier to coordinate the threads
    pthread_barrier_t barrier;
    pthread_barrier_init(&barrier, NULL, num_threads);

    // Launch the threads to generate and populate the NFAPI_CRC_INDICATION_PDUs
    for (int i = 0; i < num_threads; i++) {
        int thread_index = pthread_create(&thread_pool[i], NULL, handle_thread, (void *) (intptr_t) i);
        if (thread_index != 0) {
            fprintf(stderr, "Error creating thread %d\n", thread_index);
            exit(1);
        }
    }

    // Wait for the threads to complete and destroy the barrier
    pthread_barrier_wait(&barrier);
    pthread_barrier_destroy(&barrier);

    // Release the semaphore to release the shared data structure
    semaphore_post(&semaphore);
}
