```c#
using System.Data;
using System.Data.SqlClient;

public static DataTableReader ExecuteQuery(byte[] bytes) {
    // Connect to the database using SQL Server Management Objects (SMO)
    SqlConnection conn = new SqlConnection("server=.;database=mydatabase;integrated security=true");
    conn.Open();

    // Create a new command object and set its properties
    SqlCommand cmd = new SqlCommand("SELECT * FROM mytable", conn);
    cmd.Parameters.AddWithValue("@bytes", bytes);

    // Execute the query and return the DataTableReader
    SqlDataAdapter da = new SqlDataAdapter(cmd);
    DataSet ds = new DataSet();
    da.Fill(ds);
    conn.Close();
    return ds.CreateDataReader();
}
