```python
import os
import sys
import json
import hashlib
import base64
from Crypto.Cipher import AES
from Crypto.Util import Counter
from Crypto.Protocol.KDF import PBKDF2

# Configuration parameters
CIPHER_MODES = ["CBC", "CTR", "GCM", "EAX"]
KEY_LENGTHS = [128, 192, 256]
IV_LENGTHS = {
    "CBC": 16,
    "CTR": 16,
    "GCM": 16,
    "EAX": 16
}
DEFAULT_CIPHER_MODE = "CBC"
DEFAULT_KEY_LENGTH = 256
DEFAULT_IV_LENGTH = 16

# Cache for initialized cipher contexts
CACHE = {}

def aes_encrypt(plaintext, key=None, iv=None, mode=None):
    """Encrypt plaintext using AES with the specified key and IV."""
    # Check if the cipher mode is valid
    if mode not in CIPHER_MODES:
        raise ValueError("Invalid cipher mode")

    # Generate a new key if none was provided
    if key is None:
        key = os.urandom(DEFAULT_KEY_LENGTH // 8)

    # Generate a new IV if none was provided
    if iv is None:
        iv = os.urandom(DEFAULT_IV_LENGTH // 8)

    # Wrap the key using KDF2 and save it in the cache
    wrapped_key = PBKDF2(key, salt=os.urandom(32), dklen=DEFAULT_KEY_LENGTH)
    if wrapped_key not in CACHE:
        CACHE[wrapped_key] = AES.new(wrapped_key, mode=mode)

    # Encrypt the plaintext using the cached cipher context
    return CACHE[wrapped_key].encrypt(plaintext).decode()

def aes_decrypt(ciphertext, key=None, iv=None, mode=None):
    """Decrypt ciphertext using AES with the specified key and IV."""
    # Check if the cipher mode is valid
    if mode not in CIPHER_MODES:
        raise ValueError("Invalid cipher mode")

    # Generate a new key if none was provided
    if key is None:
        key = os.urandom(DEFAULT_KEY_LENGTH // 8)

    # Generate a new IV if none was provided
    if iv is None:
        iv = os.urandom(DEFAULT_IV_LENGTH // 8)

    # Wrap the key using KDF2 and save it in the cache
    wrapped_key = PBKDF2(key, salt=os.urandom(32), dklen=DEFAULT_KEY_LENGTH)
    if wrapped_key not in CACHE:
        CACHE[wrapped_key] = AES.new(wrapped_key, mode=mode)

    # Decrypt the ciphertext using the cached cipher context
    return CACHE[wrapped_key].decrypt(ciphertext).decode()

def aes_gen_key():
    """Generate a new AES key."""
    return os.urandom(DEFAULT_KEY_LENGTH // 8)

def aes_gen_iv(mode):
    """Generate a new IV for the specified mode."""
    if mode not in CIPHER_MODES:
        raise ValueError("Invalid cipher mode")
    return os.urandom(IV_LENGTHS[mode] // 8)

def aes_key_wrap(key, salt=None):
    """Wrap the specified key using KDF2."""
    # Generate a new salt if none was provided
    if salt is None:
        salt = os.urandom(32)

    # Perform KDF2 on the key and save it in the cache
    wrapped_key = PBKDF2(key, salt=salt, dklen=DEFAULT_KEY_LENGTH)
    if wrapped_key not in CACHE:
        CACHE[wrapped_key] = AES.new(wrapped_key, mode="CBC")

    # Return the wrapped key
    return wrapped_key

def aes_key_unwrap(wrapped_key):
    """Unwrap the specified wrapped key using KDF2."""
    # Check if the wrapped key is in the cache
    if wrapped_key not in CACHE:
        raise ValueError("Invalid wrapped key")

    # Return the unwrapped key
    return CACHE[wrapped_key].unwrap()

if __name__ == "__main__":
    import doctest
    doctest.testmod()
