// HTTP client module
use anyhow::Result;
use std::error::Error;
use std::net::{IpAddr, SocketAddr};
use std::sync::Arc;
use tokio::task::JoinHandle;
use tower::ServiceExt;

// OpenWeatherMap API client
use openweathermap::Client;

// Historical weather API client
use historical_weather_api::Client;

// Logger
use log::{error, info};

// MongoDB database
use mongodb::sync::Collection;

// Token bucket algorithm for rate limiting
use token_bucket::TokenBucket;

// Distributed caching mechanism
use distributed_caching::DistributedCache;

// Weather data entry struct
struct WeatherData {
    city: String,
    temperature: f32,
    humidity: u8,
}

#[derive(Debug)]
enum ErrorKind {
    NetworkError,
    ApiError,
    RateLimitError,
}

#[derive(Debug)]
struct WeatherClientError {
    kind: ErrorKind,
    message: String,
}

impl std::error::Error for WeatherClientError {}

impl std::fmt::Display for WeatherClientError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.message)
    }
}

pub struct WeatherClient {
    client: Client,
    historical_client: HistoricalWeatherApiClient,
    cache: DistributedCache<WeatherData>,
    db: Collection,
}

impl WeatherClient {
    pub fn new(ip: IpAddr, port: u16) -> Self {
        Self {
            client: Client::new(SocketAddr::from((ip, port))),
            historical_client: HistoricalWeatherApiClient::new(),
            cache: DistributedCache::new(),
            db: Collection::new("weather"),
        }
    }

    pub fn fetch_current(&self, city: &str) -> Result<Option<f32>, WeatherClientError> {
        let request = self.client.get(city);

        // Check if the data is in cache
        if let Some(data) = self.cache.get(city) {
            return Ok(Some(data.temperature));
        }

        match request.await {
            Ok(response) => {
                if response.status().is_success() {
                    // Parse the data from the response
                    let temperature = parse_current_weather(&response.body());
                    self.cache.put(city, WeatherData {
                        city: city.to_owned(),
                        temperature,
                        humidity: 0, // Temporarily set to zero until the historical data is fetched
                    });

                    Ok(Some(temperature))
                } else {
                    Err(WeatherClientError {
                        kind: ErrorKind::ApiError,
                        message: format!("API returned {}", response.status()),
                    })
                }
            }
            Err(error) => {
                self.cache.put(city, WeatherData {
                    city: city.to_owned(),
                    temperature: 0.0, // Temporarily set to zero until the historical data is fetched
                    humidity: 0,
                });

                Err(WeatherClientError {
                    kind: ErrorKind::NetworkError,
                    message: format!("{}", error),
                })
            }
        }
    }

    pub fn fetch_historical(&self, city: &str) -> Result<Option<f32>, WeatherClientError> {
        let request = self.historical_client.get(city);

        match request.await {
            Ok(response) => {
                if response.status().is_success() {
                    // Parse the data from the response
                    let temperature = parse_historical_weather(&response.body());
                    self.cache.put(city, WeatherData {
                        city: city.to_owned(),
                        temperature,
                        humidity: 100, // Temporarily set to 100 until the current data is fetched
                    });

                    Ok(Some(temperature))
                } else {
                    Err(WeatherClientError {
                        kind: ErrorKind::ApiError,
                        message: format!("API returned {}", response.status()),
                    })
                }
            }
            Err(error) => {
                self.cache.put(city, WeatherData {
                    city: city.to_owned(),
                    temperature: 0.0, // Temporarily set to zero until the current data is fetched
                    humidity: 100,
                });

                Err(WeatherClientError {
                    kind: ErrorKind::NetworkError,
                    message: format!("{}", error),
                })
            }
        }
    }

    pub fn fetch_forecast(&self, city: &str) -> Result<Option<Vec<f32>>, WeatherClientError> {
        let request = self.client.get(city);

        match request.await {
            Ok(response) => {
                if response.status().is_success() {
                    // Parse the data from the response
                    let forecast = parse_forecast(&response.body());
                    self.cache.put(city, WeatherData {
                        city: city.to_owned(),
                        temperature: forecast[0],
                        humidity: 100, // Temporarily set to 100 until the current data is fetched
                    });

                    Ok(Some(forecast))
                } else {
                    Err(WeatherClientError {
                        kind: ErrorKind::ApiError,
                        message: format!("API returned {}", response.status()),
                    })
                }
            }
            Err(error) => {
                self.cache.put(city, WeatherData {
                    city: city.to_owned(),
                    temperature: 0.0, // Temporarily set to zero until the current data is fetched
                    humidity: 100,
                });

                Err(WeatherClientError {
                    kind: ErrorKind::NetworkError,
                    message: format!("{}", error),
                })
            }
        }
    }
}

impl Drop for WeatherClient {
    fn drop(&mut self) {
        // Close the clients and free resources
        self.client.close();
        self.historical_client.close();
    }
}
