#include <stdio.h>
#include <stdarg.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>

// Define logging levels
#define LOG_LEVEL_ERROR   0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_INFO    2

// Define configuration options
#define CONFIG_BUFFER_SIZE  4096
#define CONFIG_FLUSH_INTERVAL 5
#define CONFIG_MAX_LOG_LENGTH 1024

// Global variables
FILE *log_file;
int log_level = LOG_LEVEL_ERROR;
char *log_buffer;
size_t buffer_pos = 0;
size_t buffer_size = CONFIG_BUFFER_SIZE;
time_t flush_interval = CONFIG_FLUSH_INTERVAL;
size_t max_log_length = CONFIG_MAX_LOG_LENGTH;
int is_buffering = 1; // Default to buffering logs

// Function prototypes
void logError(const char *format, ...);
void flushLogs();
void closeLogFile();

// Main function
int main() {
    // Initialize logging variables
    log_file = fopen("error.log", "a+");
    if (!log_file) {
        perror("fopen error: ");
        exit(1);
    }
    log_buffer = malloc(CONFIG_BUFFER_SIZE * sizeof(char));
    if (!log_buffer) {
        fprintf(stderr, "malloc error: %s\n", strerror(errno));
        closeLogFile();
        exit(1);
    }

    // Start the logging thread
    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, flushLogs, NULL)) {
        fprintf(stderr, "pthread_create error: %s\n", strerror(errno));
        closeLogFile();
        exit(1);
    }

    // Set the log level based on an environment variable
    char *log_level_str = getenv("LOG_LEVEL");
    if (log_level_str) {
        int parsed_log_level;
        if (!sscanf(log_level_str, "%d", &parsed_log_level)) {
            fprintf(stderr, "Invalid LOG_LEVEL value: %s\n", log_level_str);
            closeLogFile();
            exit(1);
        }
        log_level = parsed_log_level;
    }

    // Set the buffering option based on an environment variable
    char *is_buffering_str = getenv("IS_BUFFERING");
    if (is_buffering_str) {
        int parsed_is_buffering;
        if (!sscanf(is_buffering_str, "%d", &parsed_is_buffering)) {
            fprintf(stderr, "Invalid IS_BUFFERING value: %s\n", is_buffering_str);
            closeLogFile();
            exit(1);
        }
        is_buffering = parsed_is_buffering;
    }

    // Set the flush interval based on an environment variable
    char *flush_interval_str = getenv("FLUSH_INTERVAL");
    if (flush_interval_str) {
        int parsed_flush_interval;
        if (!sscanf(flush_interval_str, "%d", &parsed_flush_interval)) {
            fprintf(stderr, "Invalid FLUSH_INTERVAL value: %s\n", flush_interval_str);
            closeLogFile();
            exit(1);
        }
        flush_interval = parsed_flush_interval;
    }

    // Set the maximum log length based on an environment variable
    char *max_log_length_str = getenv("MAX_LOG_LENGTH");
    if (max_log_length_str) {
        int parsed_max_log_length;
        if (!sscanf(max_log_length_str, "%d", &parsed_max_log_length)) {
            fprintf(stderr, "Invalid MAX_LOG_LENGTH value: %s\n", max_log_length_str);
            closeLogFile();
            exit(1);
        }
        max_log_length = parsed_max_log_length;
    }

    // Log a message with the logError function
    logError("Hello, world! This is a test message.");

    // Close the logging file and clean up resources
    closeLogFile();

    return 0;
}

// Function to handle logging errors
void logError(const char *format, ...) {
    va_list args;
    va_start(args, format);
    int bytes_written = vsnprintf(log_buffer + buffer_pos, buffer_size - buffer_pos, format, args);
    if (bytes_written > 0) {
        buffer_pos += bytes_written;
        if (!is_buffering || buffer_pos >= flush_interval) {
            // Flush the log buffer to disk
            fprintf(log_file, "%s", log_buffer);
            buffer_pos = 0;
        }
    } else {
        perror("vsnprintf error: ");
    }
    va_end(args);
}

// Function to flush the logging buffer periodically
void *flushLogs() {
    while (1) {
        sleep(flush_interval);
        if (buffer_pos > 0) {
            // Flush the log buffer to disk
            fprintf(log_file, "%s", log_buffer);
            buffer_pos = 0;
        }
    }
}

// Function to close the logging file and clean up resources
void closeLogFile() {
    pthread_cancel(log_thread);
    if (log_file != NULL) {
        fclose(log_file);
    }
    free(log_buffer);
}
```

In this example, we define a `main` function that sets up the logging system. We first check for any environment variables that may affect the logging behavior, such as the log level, buffering option, and flush interval. If these variables are present, we use `getenv` to get their values and parse them using `sscanf`.

We then create a new thread using `pthread_create` to handle the periodic flushing of the logging buffer. We pass `flushLogs` as the function to be executed by the new thread.

The `logError` function takes a variable number of arguments, similar to `printf`, and formats them into a string that can be logged. We use `vsnprintf` to format the message into a temporary buffer, and then log it to disk using `fprintf`. If there is an error in formatting the message, we print an error message using `perror`.

The `flushLogs` function simply sleeps for a certain amount of time (as specified by the flush interval), and then checks if any data needs to be flushed to disk. If so, it flushes the log buffer to disk using `fprintf`. This function is executed in its own thread, so it runs independently of the main program.

Finally, we define a `closeLogFile` function that cleans up resources when the program exits. It cancels the logging thread and closes the logging file using `fclose`, and frees any allocated memory using `free`.

