import java.io.ObjectInputStream;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PokemonDeserializer {
    private static final String[] types = {"Grass", "Fire", "Water", "Electric"};
    private static final Map<String, List<String>> weaknesses = new HashMap<>();
    private static final Map<String, List<String>> resistances = new HashMap<>();
    private static final Map<String, List<String>> immunities = new HashMap<>();

    public String getPokemonProperties(byte[] bytes) {
        ObjectInputStream ois = null;
        try {
            Pokemon pokemon = (Pokemon) ois.readObject();
            switch (pokemon.getType()) {
                case "Grass":
                    return getGrassProperties(pokemon);
                case "Fire":
                    return getFireProperties(pokemon);
                case "Water":
                    return getWaterProperties(pokemon);
                case "Electric":
                    return getElectricProperties(pokemon);
            }
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize Pokemon object", e);
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException e) {
                    // log error
                }
            }
        }
    }

    private String getGrassProperties(Pokemon pokemon) {
        List<String> weaknesses = new ArrayList<>();
        List<String> resistances = new ArrayList<>();
        List<String> immunities = new ArrayList<>();
        // handle edge case where the class of the object being deserialized is not found
        if (pokemon.getType() == null) {
            return "Invalid Pokemon type";
        }
        switch (pokemon.getType()) {
            case "Grass":
                weaknesses.add("Fire");
                resistances.add("Water");
                immunities.add("Electric");
                break;
            case "Fire":
                weaknesses.add("Water");
                resistances.add("Grass");
                immunities.add("Electric");
                break;
            case "Water":
                weaknesses.add("Fire");
                resistances.add("Grass");
                immunities.add("Electric");
                break;
            case "Electric":
                weaknesses.add("Grass");
                resistances.add("Water");
                immunities.add("Fire");
                break;
        }
        return "Weaknesses: " + weaknesses + "\nResistances: " + resistances + "\nImmunities: " + immunities;
    }

    private String getFireProperties(Pokemon pokemon) {
        // handle edge case where the class of the object being deserialized is not found
        if (pokemon.getType() == null) {
            return "Invalid Pokemon type";
        }
        switch (pokemon.getType()) {
            case "Grass":
                return getGrassProperties(pokemon);
            case "Fire":
                return getFireProperties(pokemon);
            case "Water":
                return getWaterProperties(pokemon);
            case "Electric":
                return getElectricProperties(pokemon);
        }
    }

    private String getWaterProperties(Pokemon pokemon) {
        // handle edge case where the class of the object being deserialized is not found
        if (pokemon.getType() == null) {
            return "Invalid Pokemon type";
        }
        switch (pokemon.getType()) {
            case "Grass":
                return getGrassProperties(pokemon);
            case "Fire":
                return getFireProperties(pokemon);
            case "Water":
                return getWaterProperties(pokemon);
            case "Electric":
                return getElectricProperties(pokemon);
        }
    }

    private String getElectricProperties(Pokemon pokemon) {
        // handle edge case where the class of the object being deserialized is not found
        if (pokemon.getType() == null) {
            return "Invalid Pokemon type";
        }
        switch (pokemon.getType()) {
            case "Grass":
                return getGrassProperties(pokemon);
            case "Fire":
                return getFireProperties(pokemon);
            case "Water":
                return getWaterProperties(pokemon);
            case "Electric":
                return getElectricProperties(pokemon);
        }
    }

    public static void updateWeaknesses(List<String> weaknesses) {
        // handle edge case where the list of weaknesses is null or empty
        if (weaknesses == null || weaknesses.isEmpty()) {
            return;
        }
        // update the cache with the new list of weaknesses
        for (String weakness : weaknesses) {
            // handle edge case where the weakness is not found in the cache
            if (!weaknesses.contains(weakness)) {
                continue;
            }
            weaknesses.add(weakness);
        }
