    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to fetch resource bundle: %s\n", curl_easy_strerror(res));
        return -1;
    }

    // Get the response code and check for errors
    long response_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code < 200 || response_code > 299) {
        fprintf(stderr, "Received non-successful response code: %ld\n", response_code);
        return -1;
    }

    // Get the response data and check for errors
    curl_easy_getinfo(curl, CURLINFO_CONTENT_TYPE, &buffer);
    if (!buffer) {
        fprintf(stderr, "Failed to retrieve response data\n");
        return -1;
    }

    // Parse the response data as JSON or XML based on the content type
    json_object *json = NULL;
    if (strcmp(buffer, "application/json") == 0) {
        json = json_tokener_parse((const char *) buffer);
        if (!json) {
            fprintf(stderr, "Failed to parse JSON response\n");
            return -1;
