    } else {
        fprintf(stderr, "Unsupported content type: %s\n", buffer);
        return -1;
    }

    // Process the parsed JSON or XML data
    bundle_t *bundle = (bundle_t *) malloc(sizeof(bundle_t));
    bundle->url = url;
    bundle->data = json;
    process_bundle(bundle);

    // Clean up any allocated memory
    curl_easy_cleanup(curl);
    free(buffer);
    json_object_put(json);

    return 0;
}

