const express = require('express');
const axios = require('axios');
const redis = require('redis');
const { promisify } = require('util');

const app = express();
const client = redis.createClient();

app.use(express.json());

// Set up authentication tokens and API rate limits
const authToken = 'YOUR_AUTH_TOKEN';
const apiUrl = 'https://api.openweathermap.org/data/2.5/weather?q=London,uk&appid=' + authToken;
const apiRateLimit = 10; // API requests per second

// Set up caching mechanism
const cache = promisify(client.get).bind(client);
const setCache = promisify(client.set).bind(client);

// Fetch weather data from API and update web page in real-time
app.get('/weather', async (req, res) => {
  try {
    // Check cache for weather data
    const cachedData = await cache('WEATHER_DATA');
    if (cachedData) {
      console.log('Fetching weather data from cache');
      return res.json(JSON.parse(cachedData));
    }

    // Fetch weather data from API
    const response = await axios.get(apiUrl);

    // Set cache for 10 minutes
    setCache('WEATHER_DATA', JSON.stringify(response.data), 'EX', 600);

    res.json(response.data);
  } catch (error) {
    console.log(error);
    res.status(500).send('Failed to fetch weather data');
  }
});

// Handle potential network failures and API timeouts gracefully
app.use((req, res, next) => {
  next();
});

// Provide a clear logging mechanism for debugging and monitoring
app.use((req, res, next) => {
  const log = `${req.method} ${req.url} ${res.statusCode}`;
  console.log(log);
  next();
});

// Start server on port 3000
const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server started on port ${PORT}`);
});
