import os
from urllib import request
from time import sleep
from datetime import datetime
from collections import deque

class RateLimitedCache:
    def __init__(self, cache_size=1000, rate_limit=10):
        self.cache_size = cache_size
        self.rate_limit = rate_limit
        self.cache = deque(maxlen=cache_size)

    def add(self, url, method, session):
        if len(self.cache) < self.cache_size:
            self.cache.append((url, method, session))
        else:
            oldest_item = self.cache[0]
            self.cache.popleft()
            self.cache.append((url, method, session))

    def get(self, url, method):
        for item in self.cache:
            if item[0] == url and item[1] == method:
                return item[2]
        return None

class SessionManager:
    def __init__(self, session_manager=None, rate_limit=10, cache_size=1000):
        self.session_manager = session_manager or request.Session()
        self.rate_limit = rate_limit
        self.cache = RateLimitedCache(cache_size)

    def init_session(self, url, method="GET"):
        key = f"{url}-{method}"
        session = self.cache.get(key)
        if session is not None:
            return session
        else:
            session = self.session_manager.init_session(url, method)
            self.cache.add(url, method, session)
            return session

    def get_session(self, url, method="GET"):
        key = f"{url}-{method}"
        session = self.cache.get(key)
        if session is None:
            session = self.init_session(url, method)
        return session

    def close_sessions(self):
        for item in self.cache:
            item[2].close()
        self.cache.clear()

def main():
    # Load configuration from environment variables or config file
    url = os.getenv("URL")
    method = os.getenv("METHOD", "GET")
    rate_limit = int(os.getenv("RATE_LIMIT", 10))
    cache_size = int(os.getenv("CACHE_SIZE", 1000))

    # Initialize session manager with configuration parameters
    sm = SessionManager(rate_limit=rate_limit, cache_size=cache_size)

    # Handle multiple requests concurrently with minimal overhead
    request_queue = []
    for i in range(10):
        req = request.Request(url, method)
        request_queue.append(req)
    responses = [sm.get_session(req.url, req.method) for req in request_queue]

    # Ensure robustness against common network and HTTP errors
    for response in responses:
        try:
            resp = sm.session_manager.send(response)
            print(resp)
        except Exception as e:
            print("Error:", e)

    # Clean up resources when sessions are no longer needed
    sm.close_sessions()

if __name__ == "__main__":
    main()
