import java.util.HashMap;
import java.util.Map;

public class UnionFind {
  private Map<Integer, Integer> parents;
  private Map<Integer, Integer> sizes;
  private int[] cooldowns;

  public UnionFind(int numAttackOptions) {
    this.parents = new HashMap<>();
    this.sizes = new HashMap<>();
    this.cooldowns = new int[numAttackOptions];
  }

  public void addAttackOption(int attackOption) {
    if (attackOption < 0 || attackOption >= cooldowns.length) {
      throw new IllegalArgumentException("Invalid attack option");
    }
    parents.putIfAbsent(attackOption, attackOption);
    sizes.put(attackOption, 1);
  }

  public void union(int attackOption1, int attackOption2) {
    if (attackOption1 < 0 || attackOption1 >= cooldowns.length ||
        attackOption2 < 0 || attackOption2 >= cooldowns.length) {
      throw new IllegalArgumentException("Invalid attack option");
    }
    int parent1 = find(attackOption1);
    int parent2 = find(attackOption2);
    if (parent1 == parent2) {
      return;
    }
    int size1 = sizes.get(parent1);
    int size2 = sizes.get(parent2);
    if (size1 < size2) {
      parents.put(parent1, parent2);
      sizes.put(parent2, size2 + size1);
    } else {
      parents.put(parent2, parent1);
      sizes.put(parent1, size1 + size2);
    }
  }

  public int find(int attackOption) {
    if (attackOption < 0 || attackOption >= cooldowns.length) {
      throw new IllegalArgumentException("Invalid attack option");
    }
    while (parents.get(attackOption) != attackOption) {
      attackOption = parents.get(attackOption);
    }
    return attackOption;
  }

  public boolean isConnected(int attackOption1, int attackOption2) {
    if (attackOption1 < 0 || attackOption1 >= cooldowns.length ||
        attackOption2 < 0 || attackOption2 >= cooldowns.length) {
      throw new IllegalArgumentException("Invalid attack option");
    }
    return find(attackOption1) == find(attackOption2);
  }
}
