import java.util.HashMap;
import java.util.Map;

public class AttackSelection {
  private UnionFind unionFind;
  private int[] cooldowns;
  private long[] attackTimes;
  private Map<Integer, Integer> attackOptions;
  private Map<Integer, Integer> attackOptionCooldowns;

  public AttackSelection(int numAttackOptions) {
    this.unionFind = new UnionFind(numAttackOptions);
    this.cooldowns = new int[numAttackOptions];
    this.attackTimes = new long[numAttackOptions];
    this.attackOptions = new HashMap<>();
    this.attackOptionCooldowns = new HashMap<>();
  }

  public void addAttackOption(int attackOption, int cooldown) {
    if (cooldown < 0) {
      throw new IllegalArgumentException("Invalid cooldown");
    }
    unionFind.addAttackOption(attackOption);
    this.cooldowns[attackOption] = cooldown;
    this.attackOptions.put(attackOption, 0);
    this.attackOptionCooldowns.put(attackOption, cooldown);
  }

  public void union(int attackOption1, int attackOption2) {
    if (attackOption1 < 0 || attackOption1 >= cooldowns.length ||
        attackOption2 < 0 || attackOption2 >= cooldowns.length) {
      throw new IllegalArgumentException("Invalid attack option");
    }
    unionFind.union(attackOption1, attackOption2);
  }

  public int find(int attackOption) {
    if (attackOption < 0 || attackOption >= cooldowns.length) {
      throw new IllegalArgumentException("Invalid attack option");
    }
    return unionFind.find(attackOption);
  }

  public boolean isConnected(int attackOption1, int attackOption2) {
    if (attackOption1 < 0 || attackOption1 >= cooldowns.length ||
        attackOption2 < 0 || attackOption2 >= cooldowns.length) {
      throw new IllegalArgumentException("Invalid attack option");
    }
    return unionFind.isConnected(attackOption1, attackOption2);
  }

  public int selectAttack(int characterId) {
    long currentTime = System.currentTimeMillis();
    int selectedAttack = -1;
    for (int attackOption : attackOptions.keySet()) {
      if (!isConnected(attackOption, selectedAttack)) {
        continue;
      }
      if (currentTime - attackTimes[attackOption] >= cooldowns[attackOption]) {
        attackTimes[attackOption] = currentTime;
        selectedAttack = attackOption;
        break;
      }
    }
    if (selectedAttack != -1) {
      attackOptions.put(characterId, selectedAttack);
      return selectedAttack;
    } else {
      throw new RuntimeException("No available attack options");
    }
  }

  public void saveIntermediateResults(int characterId, int attackOption, long time) {
    if (attackOption < 0 || attackOption >= cooldowns.length) {
      throw new IllegalArgumentException("Invalid attack option");
    }
    if (time <= 0) {
      throw new IllegalArgumentException("Invalid time value");
    }
    attackTimes[attackOption] = time;
    attackOptions.put(characterId, attackOption);
  }

  public void handleOutOfMemoryError() {
    // TODO: Implement intelligent data structure resize
