#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 1024

char* uploadAndModifyFilename(const char* filename, const char* url) {
    // Get the file extension from the filename
    char* ext = strrchr(filename, '.');
    if (ext == NULL) {
        return NULL;
    }

    // Determine the number of digits in the filename and the file type
    int numDigits = 0;
    char* fileType = "";
    for (int i = 0; i < strlen(filename); i++) {
        if (isdigit(filename[i])) {
            numDigits++;
        } else {
            fileType = filename + i;
            break;
        }
    }

    // Modify the extension based on the number of digits and file type
    char* modifiedExt = "";
    if (numDigits > 0) {
        if (strcmp(fileType, "jpg") == 0 || strcmp(fileType, "jpeg") == 0) {
            modifiedExt = ".jpg";
        } else if (strcmp(fileType, "png") == 0) {
            modifiedExt = ".png";
        } else if (strcmp(fileType, "gif") == 0) {
            modifiedExt = ".gif";
        } else {
            modifiedExt = "";
        }
    }

    // Upload the file using a chosen library (e.g., Bluebird, Logger, File Uploader)
    char* uploadedFileUrl = "";
    if (modifiedExt != "") {
        uploadedFileUrl = bluebird_upload(url, modifiedExt);
    } else {
        uploadedFileUrl = logger_upload(url, ext + 1);
    }

    return uploadedFileUrl;
}
