```java
import java.io.File;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;

public class FileHasher {
    private static final Map<String, String> fileHashes = new HashMap<>();

    public static String getFileHash(String filePath) throws Exception {
        // Check if the hash for this file path is already computed and stored in the cache
        if (fileHashes.containsKey(filePath)) {
            return fileHashes.get(filePath);
        }

        File file = new File(filePath);
        MessageDigest digest = MessageDigest.getInstance("SHA-256");

        try (InputStream inputStream = Files.newInputStream(file.toPath())) {
            byte[] buffer = new byte[8192];
            int bytesRead;

            while ((bytesRead = inputStream.read(buffer)) > 0) {
                digest.update(buffer, 0, bytesRead);
            }
        } catch (IOException e) {
            // Handle any errors that occur during the file reading process
            System.out.println("Error reading file: " + filePath);
            return null;
        }

        String hash = digest.digest().toString();
        fileHashes.put(filePath, hash);
        return hash;
    }
}
