// C++ code for `insertStringAfterNfaCRC` function
#include <string>
#include <forward_list>

void insertStringAfterNfaCRC(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    // Find the first occurrence of the target string in the forward list
    auto it = list.begin();
    while (it != list.end() && *it != target) {
        ++it;
    }

    // If the target string is not found, insert at the end of the list
    if (it == list.end()) {
        list.push_front(insertion);
    } else {
        // Insert the insertion string after the target string
        list.insert_after(it, insertion);
    }
}

// C# code for `SendPDUToDatabase` method
using System;
using System.Data;
using System.Threading;

class NfaDatabase {
    private readonly string _connectionString;

    public NfaDatabase(string connectionString) {
        _connectionString = connectionString;
    }

    public DataTableReader SendPDUToDatabase(byte[] pdu) {
        // Connect to the database server using the provided connection string
        var connection = new SqlConnection(_connectionString);
        connection.Open();

        try {
            // Create a command object and set its properties
            var command = new SqlCommand("INSERT INTO NFA_PDU (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG) VALUES (@RX_UE_INFORMATION_TAG, @RNTI, @CRC_INDICATION_REL8_TAG)", connection);
            command.Parameters.AddWithValue("@RX_UE_INFORMATION_TAG", pdu[0]);
            command.Parameters.AddWithValue("@RNTI", pdu[1]);
            command.Parameters.AddWithValue("@CRC_INDICATION_REL8_TAG", pdu[2]);

            // Execute the query and return the result set
            var reader = command.ExecuteReader();
            return reader;
        } catch (Exception e) {
            Console.WriteLine("Error occurred while sending PDU to database: " + e.Message);
            return null;
        } finally {
            connection.Close();
        }
    }
}

