        var reader = _nfaDatabase.SendPDUToDatabase(pdu);
        Assert.IsNotNull(reader);
        reader.Close();

        // Test case 2: Send a valid PDU with CRCFLAG not set (should be set to 0x00)
        pdu = new byte[] { 0x01, 0x02, 0x00 };
        reader = _nfaDatabase.SendPDUToDatabase(pdu);
        Assert.IsNotNull(reader);
        reader.Close();

        // Test case 3: Send an invalid PDU (too short)
        pdu = new byte[] { 0x01, 0x02 };
        reader = _nfaDatabase.SendPDUToDatabase(pdu);
        Assert.IsNull(reader);

        // Test case 4: Send an invalid PDU (too long)
        pdu = new byte[] { 0x01, 0x02, 0x03, 0x04 };
        reader = _nfaDatabase.SendPDUToDatabase(pdu);
        Assert.IsNull(reader);
    }
