        let response = self.client.get(url).send().await?;
        Ok(response.json::<HistoricalWeatherData>().await?)
    }

    // get forecast data from a third API
    async fn fetch_forecast(&self, city: &str) -> Result<ForecastData, anyhow::Error> {
        let url = format!("{}/forecast?q={}", FORECAST_URL, city);
        let response = self.client.get(url).send().await?;
        Ok(response.json::<ForecastData>().await?)
    }
}

// logging implementation
