    logger: log::Logger,
}

impl Logger {
    fn new() -> Self {
        let logger = log::logger(log::LogLevelFilter::Info);
        Self { logger }
    }

    // log information messages
    fn info(&self, msg: &str) {
        self.logger.log(log::LogLevel::Info, msg);
    }

    // log warning messages
