#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure to represent an NFAPI_CRC_INDICATION_PDU
typedef struct {
  uint8_t rx_ue_information_tag;
  uint16_t rnti;
  uint32_t crc_indication_rel8_tag;
  bool crcflag;
} NFAPI_CRC_INDICATION_PDU;

// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDUs
void generate_nfapi_crc_indication_pdus(int num_pdus, int num_threads) {
  // Initialize the list of PDUs
  NFAPI_CRC_INDICATION_PDU* pdus = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU) * num_pdus);
  for (int i = 0; i < num_pdus; i++) {
    // Set the RX_UE_INFORMATION_TAG and RNTI randomly
    pdus[i].rx_ue_information_tag = rand() % 256;
    pdus[i].rnti = rand() % 65536;
    // Set the CRCFLAG randomly
    pdus[i].crcflag = (rand() % 2) == 0;
  }

  // Create a thread pool to manage concurrent generation and processing of PDUs
  pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * num_threads);
  for (int i = 0; i < num_threads; i++) {
    // Create a new thread to process the PDUs
    pthread_create(&threads[i], NULL, process_nfapi_crc_indication_pdus, (void*)&pdus);
  }

  // Join all the threads and free the memory used by the thread pool
  for (int i = 0; i < num_threads; i++) {
    pthread_join(threads[i], NULL);
  }
  free(threads);

  // Print the generated PDUs to stdout
  printf("Generated %d NFAPI_CRC_INDICATION_PDUs\n", num_pdus);
}

// Function to process a list of NFAPI_CRC_INDICATION_PDUs concurrently
void* process_nfapi_crc_indication_pdus(void* arg) {
  // Get the list of PDUs from the argument
  NFAPI_CRC_INDICATION_PDU* pdus = (NFAPI_CRC_INDICATION_PDU*)arg;
  int num_pdus = sizeof(pdus) / sizeof(NFAPI_CRC_INDICATION_PDU);

  // Process the PDUs concurrently using a thread pool
  pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * num_pdus);
  for (int i = 0; i < num_pdus; i++) {
    // Create a new thread to process the PDUs
    pthread_create(&threads[i], NULL, process_nfapi_crc_indication_pdu, (void*)&pdus[i]);
  }

  // Join all the threads and free the memory used by the thread pool
  for (int i = 0; i < num_pdus; i++) {
    pthread_join(threads[i], NULL);
  }
  free(threads);
}

// Function to process a single NFAPI_CRC_INDICATION_PDU
void* process_nfapi_crc_indication_pdu(void* arg) {
  // Get the PDU from the argument
  NFAPI_CRC_INDICATION_PDU* pdu = (NFAPI_CRC_INDICATION_PDU*)arg;

  // Handle data source failures gracefully by retrying a few times before giving up
  for (int i = 0; i < 3; i++) {
    // Try to fetch the RX_UE_INFORMATION_TAG and RNTI from the data source
    uint8_t rx_ue_information_tag = rand() % 256;
    uint16_t rnti = rand() % 65536;

    // If the fetch was successful, break out of the loop
    if (rx_ue_information_tag != 0 && rnti != 0) {
      break;
    }
  }

  // Handle version mismatches and hardware-specific issues by providing fallback options
  bool crcflag = false;
  if (pdu->crcflag == true) {
    crcflag = rand() % 2 == 0;
  } else {
    crcflag = rand() % 2 != 0;
  }

  // Print the generated PDU to stdout
  printf("Generated NFAPI_CRC_INDICATION_PDU with RX_UE_INFORMATION_TAG %d, RNTI %d, and CRCFLAG %d\n", pdu->rx_ue_information_tag, pdu->rnti, crcflag);
}
