using Microsoft.AspNetCore.Identity;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace MyApp.Authentication
{
    public class UserManager : IUserManager
    {
        private readonly IConfiguration _configuration;
        private readonly IdentityErrorDescriber _errorDescriber;
        private readonly ILogger<UserManager> _logger;

        public UserManager(IConfiguration configuration, IdentityErrorDescriber errorDescriber, ILogger<UserManager> logger)
        {
            _configuration = configuration;
            _errorDescriber = errorDescriber;
            _logger = logger;
        }

        public async Task<IdentityResult> CreateAsync(string userName, string password, string provider = null)
        {
            // Validate the username and password
            if (!ValidateUserName(userName))
            {
                return IdentityResult.Failed(_errorDescriber.InvalidUserName(userName));
            }
            if (!ValidatePassword(password))
            {
                return IdentityResult.Failed(_errorDescriber.InvalidPassword(password));
            }

            // Create the user and store it in the database
            var user = new User
            {
                UserName = userName,
                Provider = provider,
            };
            await _context.Users.AddAsync(user);

            // Update the password hash
            await _passwordHasher.HashPasswordAsync(user, password);

            return IdentityResult.Success;
        }

        public bool ValidateUserName(string userName)
        {
            // Check if the username is valid according to the configured rules
            var minLength = _configuration.GetValue<int>("MinimumUsernameLength");
            if (userName.Length < minLength)
            {
                return false;
            }
            var excludedWords = _configuration.GetValue<string[]>("ExcludedUsernameWords");
            foreach (var word in excludedWords)
            {
                if (userName.Contains(word))
                {
                    return false;
                }
            }
            return true;
        }

        public bool ValidatePassword(string password)
        {
            // Check if the password is valid according to the configured rules
            var minLength = _configuration.GetValue<int>("MinimumPasswordLength");
            if (password.Length < minLength)
            {
                return false;
            }
            var requiredChars = _configuration.GetValue<char[]>("RequiredPasswordCharacters");
            foreach (var c in requiredChars)
            {
                if (!password.Contains(c))
                {
                    return false;
                }
            }
            return true;
        }

        public async Task LockoutAsync(string userName, int lockoutTime = 300, int failedAttempts = 5)
        {
            // Check if the user is locked out and update the lockout time and failed attempts accordingly
            var user = await _context.Users.FirstOrDefaultAsync(u => u.UserName == userName);
            if (user != null && user.IsLockedOut)
            {
                user.LockoutEndDateUtc = DateTime.UtcNow.AddSeconds(lockoutTime);
                user.FailedAttempts += failedAttempts;
                await _context.SaveChangesAsync();
            }
        }
    }
}
