forward_list<NFAPI_CRC_INDICATION_PDU> generateAndPopulateForwardList(int n) {
    // Initialize the forward list
    forward_list<NFAPI_CRC_INDICATION_PDU> list;

    // Generate random RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<uint32_t> RX_UE_INFORMATION_TAG_dist(0, 65535);
    uniform_int_distribution<uint64_t> RNTI_dist(0, 18446744073709551615ULL);
    uniform_int_distribution<uint8_t> CRC_INDICATION_REL8_TAG_dist(0, 255);

    // Fill the forward list with random values
    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU pdu;
        pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_dist(gen);
        pdu.RNTI = RNTI_dist(gen);
        pdu.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG_dist(gen);
        list.push_front(pdu);
    }

