import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class WebAPI {
    private static final String BASE_URL = "https://example.com/api";
    private static final int TIMEOUT = 5000; // in milliseconds

    public static void main(String[] args) throws IOException, InterruptedException {
        System.out.println("Web API Client");

        // create a map to store the resources and their disjoint sets
        Map<Integer, List<Integer>> resourceMap = new HashMap<>();

        // read the input arrays used for determining disjointness
        int[] inputs = {1, 2, 3, 4, 5};
        int[] outputs = {6, 7, 8, 9, 10};

        // populate the map with initial resources
        for (int i = 0; i < inputs.length; i++) {
            resourceMap.put(inputs[i], new ArrayList<Integer>());
            resourceMap.get(inputs[i]).add(outputs[i]);
        }

        // perform the command execution phase
        for (int i = 0; i < inputs.length; i++) {
            // delete any existing file before running the command
            File file = new File("command-output");
            if (file.exists()) {
                file.delete();
            }

            // execute the command and read the output and error streams
            String[] command = {"ls", "-l"};
            Process process = Runtime.getRuntime().exec(command, null, new File("."));
            BufferedReader stdOutput = new BufferedReader(new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8));
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream(), StandardCharsets.UTF_8));
            String output;
            while ((output = stdOutput.readLine()) != null) {
                System.out.println(output);
            }
            String error;
            while ((error = stdError.readLine()) != null) {
                System.err.println(error);
            }

            // update the resource map with the updated disjoint sets
            for (int j = 0; j < inputs[i]; j++) {
                List<Integer> disjointSet = resourceMap.get(j);
                if (disjointSet != null) {
                    // add the output to the disjoint set
                    disjointSet.add(outputs[i]);
                    // remove any duplicates from the list
                    disjointSet.removeIf(x -> x.equals(outputs[i]));
                } else {
                    // create a new disjoint set with the output
                    List<Integer> newDisjointSet = new ArrayList<>();
                    newDisjointSet.add(outputs[i]);
                    resourceMap.put(j, newDisjointSet);
                }
            }

            System.out.println("Disjoint sets after execution:");
            for (int j = 0; j < inputs.length; j++) {
                List<Integer> disjointSet = resourceMap.get(inputs[j]);
                if (disjointSet != null) {
                    System.out.println("Input " + inputs[j] + ": " + disjointSet);
                } else {
                    System.out.println("Input " + inputs[j] + ": (empty)");
                }
            }
        }
    }

    public static int updateResource(int id, String data) throws IOException {
        // create a connection to the API endpoint using the HTTP PUT method
        HttpURLConnection conn = (HttpURLConnection) new URL(BASE_URL + "/resources/" + id).openConnection();
        conn.setRequestMethod("PUT");
        conn.setDoOutput(true);
        conn.setConnectTimeout(TIMEOUT);
        conn.setReadTimeout(TIMEOUT);

        // write the request body to the connection
        OutputStreamWriter writer = new OutputStreamWriter(conn.getOutputStream());
        writer.write(data);
        writer.flush();

        // read the response from the API endpoint
        InputStreamReader reader = new InputStreamReader(conn.getInputStream(), StandardCharsets.UTF_8);
        StringBuilder builder = new StringBuilder();
        char[] buffer = new char[1024];
        int len;
        while ((len = reader.read(buffer)) > 0) {
            builder.append(buffer, 0, len);
        }
        String response = builder.toString();

        // close the connection and return the updated resource
        conn.disconnect();
        return Integer.parseInt(response);
    }

    public static int deleteResource(int id) throws IOException {
        // create a connection to the API endpoint using the HTTP DELETE method
        HttpURLConnection conn = (HttpURLConnection) new URL(BASE_URL + "/resources/" + id).openConnection();
        conn.setRequestMethod("DELETE");
        conn.setDoOutput(true);
        conn.setConnectTimeout(TIMEOUT);
        conn.setReadTimeout(TIMEOUT);

        // read the response from the API endpoint
        InputStreamReader reader = new InputStreamReader(conn.getInputStream(), StandardCharsets.UTF_8);
        StringBuilder builder = new StringBuilder();
        char[] buffer = new char[1024];
        int len;
        while ((len = reader.read(buffer)) > 0) {
            builder.append(buffer, 0, len);
        }
        String response = builder.toString();

        // close the connection and return the new resource with default values
        conn.disconnect();
        return Integer.parseInt(response);
    }
}
