    private bool TryFetchDistributionMetadataFromRemote(string remoteUrl, out (DistributionType, double[]) distributionMetadata)
    {
        try
        {
            using (var client = new WebClient())
            {
                var jsonData = JsonConvert.DeserializeObject<dynamic>(client.DownloadString(remoteUrl));
