    private readonly Dictionary<string, (int min, int max)> _cacheRangeLimits = new Dictionary<string, (int min, int max)>();
    private readonly Dictionary<string, (DistributionType, double[])> _cacheDistributionMetadata = new Dictionary<string, (DistributionType, double[])>();

    public void CacheRangeLimits(string key, (int min, int max) rangeLimits) { _cacheRangeLimits[key] = rangeLimits; }
    public void CacheDistributionMetadata(string key, (DistributionType, double[]) distributionMetadata) { _cacheDistributionMetadata[key] = distributionMetadata; }

    // Implement a logging mechanism to track errors and improve debugging
    private readonly ILogger _logger = new LoggerFactory().CreateLogger<DynamicRandomizer>();

    public void LogError(Exception exception, string message) { _logger.LogError(exception, message); }

    // Implement a unit of work pattern to group related actions together and make them easier to manage
    private readonly IUnitOfWork _unitOfWork = new UnitOfWork();

    public void BeginTransaction() { _unitOfWork.Begin(); }
    public void CommitTransaction() { _unitOfWork.Commit(); }
    public void RollbackTransaction() { _unitOfWork.Rollback(); }
