#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define a structure to hold the cipher object and its context
struct Cipher {
    EVP_CIPHER_CTX* ctx;
};

// Function to create a new cipher object
EVP_CIPHER_CTX* createCipher(const char* filePath, const char* command) {
    // Check if the file path is valid and the command is supported
    if (!filePath || !command || strcmp(command, "encrypt") && strcmp(command, "decrypt")) {
        return NULL;
    }

    // Open the file in binary mode for reading/writing
    FILE* fp = fopen(filePath, "rb+");
    if (!fp) {
        perror("fopen");
        return NULL;
    }

    // Create a new cipher object and its context
    struct Cipher* cipher = (struct Cipher*) malloc(sizeof(struct Cipher));
    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        perror("EVP_CIPHER_CTX_new");
        fclose(fp);
        return NULL;
    }

    // Set the cipher mode and key based on the command
    int mode = strcmp(command, "encrypt") ? EVP_DecryptInit : EVP_EncryptInit;
    if (EVP_CIPHER_CTX_cipher(cipher->ctx) != NULL) {
        EVP_CIPHER_CTX_cleanup(cipher->ctx);
    }
    EVP_CipherInit(cipher->ctx, EVP_aes_256_cbc(), NULL, NULL, mode);

    // Encrypt/decrypt the file and store the result in the cipher object
    size_t len;
    unsigned char buffer[1024];
    int ret;
    while ((ret = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        if (EVP_CipherUpdate(cipher->ctx, buffer, ret, buffer, &len) <= 0) {
            perror("EVP_CipherUpdate");
            EVP_CIPHER_CTX_cleanup(cipher->ctx);
            fclose(fp);
            return NULL;
        }
    }

    // Check for any errors during the encryption/decryption process
    if (EVP_CipherFinal(cipher->ctx, buffer, &len) <= 0) {
        perror("EVP_CipherFinal");
        EVP_CIPHER_CTX_cleanup(cipher->ctx);
        fclose(fp);
        return NULL;
    }

    // Close the file and return the cipher object
    fclose(fp);
    return cipher;
}

// Function to destroy a cipher object
void destroyCipher(struct Cipher* cipher) {
    if (cipher != NULL) {
        EVP_CIPHER_CTX_cleanup(cipher->ctx);
        free(cipher);
    }
}
