public class SecureRandomValueGenerator : IRandomValueGenerator
{
    private const string KEY_URL = "https://example.com/api/keys";
    private const string IV_URL = "https://example.com/api/ivs";
    private static readonly HttpClient _client = new HttpClient();
    private static readonly ConcurrentDictionary<string, byte[]> _cache = new ConcurrentDictionary<string, byte[]>();

    public SecureRandomValueGenerator(int min, int max)
    {
        MinValue = min;
        MaxValue = max;
    }

    public int MinValue { get; private set; }
    public int MaxValue { get; private set; }

    public async Task<int> GenerateRandomValue()
    {
        var keyResponse = await _client.GetAsync(KEY_URL);
        if (!keyResponse.IsSuccessStatusCode)
        {
            return -1; // error handling here
        }

        var ivResponse = await _client.GetAsync(IV_URL);
        if (!ivResponse.IsSuccessStatusCode)
        {
            return -2; // error handling here
        }

        var keyBytes = await keyResponse.Content.ReadAsByteArrayAsync();
        var ivBytes = await ivResponse.Content.ReadAsByteArrayAsync();

        using (var aes = new AesCryptoServiceProvider())
        {
            aes.Key = keyBytes;
            aes.IV = ivBytes;

            // Generate random value within range using AES encryption
            var randomValue = Random.Range(MinValue, MaxValue);
            var encryptedValue = Convert.ToBase64String(aes.Encrypt(BitConverter.GetBytes(randomValue)));

            return Convert.ToInt32(encryptedValue);
        }
    }

