#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <memory>

using namespace std;

class Octree {
private:
    // Define the structure of an octree node
    struct Node {
        int data[3]; // Assuming the feature size is 3 for now
        vector<Node*> children; // Vector of pointers to child nodes
        mutex mtx; // Mutex for thread safety
        condition_variable cv; // Condition variable for signaling updates
    };

    // Define the root node of the octree
    Node* root = nullptr;

    // Define the maximum number of leaf nodes in the octree
    int maxLeafNodes = 0;

    // Define the total memory usage limit for the octree
    int memLimit = 0;

    // Define a vector to store all the allocated nodes
    vector<Node*> allocatedNodes;

public:
    // Constructor
    Octree(int maxLeafNodes, int memLimit) {
        this->maxLeafNodes = maxLeafNodes;
        this->memLimit = memLimit;
    }

    // Function to initialize the octree with data from an external source
    void initFromSource(vector<float>* data) {
        int numDataPoints = data->size();
        int curLeafNodeIdx = 0;

        // Loop through all the data points and add them to the octree
        for (int i = 0; i < numDataPoints; ++i) {
            // Check if the current leaf node is full
            if (curLeafNodeIdx == maxLeafNodes) {
                // If it is, split the parent node and add the new child to it
                root->mtx.lock();
                Node* parent = root;
                while (parent->children.size() < 8) {
                    parent->children.push_back(new Node());
                }
                parent->mtx.unlock();
                curLeafNodeIdx++;
            }

            // Add the data point to the current leaf node
            root->children[curLeafNodeIdx]->data[0] = (*data)[i];
        }
    }

    // Function to update a specific node in the octree with new data
    void updateNode(int nodeIdx, vector<float>* newData) {
        root->mtx.lock();
        Node* curNode = root;
        for (int i = 0; i < nodeIdx; ++i) {
            curNode = curNode->children[i];
        }
        curNode->data[0] = (*newData)[nodeIdx];
        curNode->mtx.unlock();
    }

    // Function to query the value of a specific node in the octree
    float queryNode(int nodeIdx) {
        root->mtx.lock();
        Node* curNode = root;
        for (int i = 0; i < nodeIdx; ++i) {
            curNode = curNode->children[i];
        }
        float value = curNode->data[0];
        root->mtx.unlock();
        return value;
    }

    // Function to destroy the octree and free all allocated memory
    void destroy() {
        for (int i = 0; i < allocatedNodes.size(); ++i) {
            delete allocatedNodes[i];
        }
        root = nullptr;
    }
};
