#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <pthread.h>

// Define a structure to represent each log entry
typedef struct {
    char* payload; // payload of the log entry (string)
    long timestamp; // timestamp of the log entry (long)
} LogEntry;

// Function to read a large binary log file in chunks and sort the entries based on timestamps
void read_sort_log(char* input_file, char* output_file, char* filter_rules, long max_chunk_size, int timeout, char* error_log) {
    // Open the input file for reading
    FILE* fp = fopen(input_file, "rb");
    if (fp == NULL) {
        printf("Error: failed to open input file %s\n", input_file);
        return;
    }

    // Create a buffer to read the input file in chunks
    char* buffer = malloc(max_chunk_size);
    if (buffer == NULL) {
        printf("Error: failed to allocate memory for chunk reading\n");
        fclose(fp);
        return;
    }

    // Define a list to store the log entries read from the input file
    List* log_entries = create_list();

    // Read the input file in chunks and extract the log entries
    while (true) {
        // Read the next chunk of data from the input file
        size_t bytes_read = fread(buffer, 1, max_chunk_size, fp);
        if (bytes_read == 0) {
            break;
        }

        // Extract each log entry from the buffer and store it in the list
        for (int i = 0; i < bytes_read; i += sizeof(LogEntry)) {
            LogEntry* entry = (LogEntry*) &buffer[i];
            add_to_list(log_entries, entry);
        }
    }

    // Sort the log entries based on their timestamps
    sort_by_timestamp(log_entries);

    // Filter the log entries according to the filtering rules
    filter_log_entries(log_entries, filter_rules);

    // Write the filtered log entries to the output file
    FILE* out = fopen(output_file, "wb");
    if (out == NULL) {
        printf("Error: failed to open output file %s\n", output_file);
        return;
    }
    for (int i = 0; i < log_entries->size; i++) {
        LogEntry* entry = get_from_list(log_entries, i);
        fwrite(entry->payload, strlen(entry->payload), 1, out);
    }
    fclose(out);

    // Free the memory used by the list and close the input file
    free_list(log_entries);
    fclose(fp);
}

// Function to filter log entries according to a set of filtering rules
void filter_log_entries(List* log_entries, char* filter_rules) {
    // Extract the filtering rules from the command-line argument
    int rule1 = atoi(strtok(filter_rules, ":"));
    int rule2 = atoi(strtok(NULL, ":"));
    long rule3 = atol(strtok(NULL, ":"));

    // Create a new list to store the filtered log entries
    List* filtered_log_entries = create_list();

    // Iterate over each log entry and apply the filtering rules
    for (int i = 0; i < log_entries->size; i++) {
        LogEntry* entry = get_from_list(log_entries, i);
        long timestamp = entry->timestamp;
        char* payload = entry->payload;
        if (timestamp >= rule3 && strstr(payload, rule1) != NULL && strstr(payload, rule2) != NULL) {
            add_to_list(filtered_log_entries, entry);
        }
    }

    // Free the memory used by the old list and replace it with the filtered one
    free_list(log_entries);
    *log_entries = filtered_log_entries;
}

// Function to sort log entries based on their timestamps
void sort_by_timestamp(List* log_entries) {
    // Create a new list with the same elements as the original one, but sorted by timestamp
    List* sorted_list = create_list();
    for (int i = 0; i < log_entries->size; i++) {
        LogEntry* entry = get_from_list(log_entries, i);
        add_to_list(sorted_list, entry);
    }
    sort_list(sorted_list);

    // Free the memory used by the old list and replace it with the sorted one
    free_list(log_entries);
    *log_entries = sorted_list;
}

// Function to create a new list
List* create_list() {
    List* list = malloc(sizeof(List));
    if (list == NULL) {
        printf("Error: failed to allocate memory for the list\n");
        return NULL;
    }
    list->size = 0;
    list->capacity = 16;
    list->elements = malloc(list->capacity * sizeof(LogEntry*));
    if (list->elements == NULL) {
        printf("Error: failed to allocate memory for the list elements\n");
        free(list);
        return NULL;
    }
    return list;
}

// Function to add an element to a list
void add_to_list(List* list, LogEntry* element) {
    if (list->size == list->capacity) {
        // If the list is full, increase its capacity by 16 elements
        list->capacity += 16;
        list->elements = realloc(list->elements, list->capacity * sizeof(LogEntry*));
        if (list->elements == NULL) {
            printf("Error: failed to allocate memory for the list elements\n");
            return;
        }
    }
    list->elements[list->size] = element;
    list->size++;
}

// Function to free the memory used by a list
void free_list(List* list) {
    if (list != NULL) {
        for (int i = 0; i < list->size; i++) {
            LogEntry* entry = get_from_list(list, i);
            free(entry);
        }
        free(list->elements);
        free(list);
    }
}

// Function to get an element from a list by its index
LogEntry* get_from_list(List* list, int index) {
    if (index < 0 || index >= list->size) {
        printf("Error: invalid index %d\n", index);
        return NULL;
    }
    return list->elements[index];
}

// Function to sort a list of log entries by their timestamps
void sort_list(List* list) {
    // Bubble sort the list
    for (int i = 0; i < list->size - 1; i++) {
        for (int j = i + 1; j < list->size; j++) {
            LogEntry* current = get_from_list(list, i);
            LogEntry* next = get_from_list(list, j);
            if (current->timestamp > next->timestamp) {
                add_to_list(list, next);
                add_to_list(list, current);
            }
        }
    }
}
