// Define a struct to store temperature data
struct TemperatureData {
    int sensor_id; // Sensor ID
    double temperature; // Temperature value
};

// Define a data structure to store temperature data from multiple sensors
typedef struct TemperatureDataList {
    struct TemperatureData *data; // Array of temperature data
    size_t num_sensors; // Number of sensors
} TemperatureDataList;

// Initialize the temperature data list with a given number of sensors
void init_temperature_data_list(TemperatureDataList *list, size_t num_sensors) {
    list->num_sensors = num_sensors;
    list->data = (struct TemperatureData *)malloc(sizeof(struct TemperatureData) * num_sensors);
}

// Add temperature data from a sensor to the list
void add_temperature_data(TemperatureDataList *list, int sensor_id, double temperature) {
    for (size_t i = 0; i < list->num_sensors; i++) {
        if (list->data[i].sensor_id == sensor_id) {
            list->data[i].temperature = temperature;
            return;
        }
    }
    // If the sensor ID is not found in the list, add a new entry
    struct TemperatureData new_entry = {sensor_id, temperature};
    list->num_sensors++;
    list->data = (struct TemperatureData *)realloc(list->data, sizeof(struct TemperatureData) * list->num_sensors);
    list->data[list->num_sensors - 1] = new_entry;
}

// Update the maximum temperature value in the list
void update_max_temperature(TemperatureDataList *list) {
    double max_temperature = -INFINITY;
    for (size_t i = 0; i < list->num_sensors; i++) {
        if (list->data[i].temperature > max_temperature) {
            max_temperature = list->data[i].temperature;
        }
    }
    list->max_temperature = max_temperature;
}

// Print the maximum temperature value in the list
void print_max_temperature(TemperatureDataList *list) {
    printf("Maximum temperature: %f\n", list->max_temperature);
}

int main() {
    // Initialize the temperature data list with 10 sensors
    TemperatureDataList list;
    init_temperature_data_list(&list, 10);

    // Add temperature data from a sensor
    add_temperature_data(&list, 1, 25.6);
    add_temperature_data(&list, 2, 30.2);
    add_temperature_data(&list, 3, 28.7);
    update_max_temperature(&list);
    print_max_temperature(&list); // Output: Maximum temperature: 30.2

    // Add more temperature data from a sensor
    add_temperature_data(&list, 1, 26.4);
    update_max_temperature(&list);
    print_max_temperature(&list); // Output: Maximum temperature: 30.2

    // Add temperature data from another sensor
    add_temperature_data(&list, 5, 29.8);
    update_max_temperature(&list);
