                    JObject json = new JObject();

                    json["featureSize"] = featureSize;
                    json["numberOfLeafNodes"] = numberOfLeafNodes;
                    json["compressedByteArray"] = Convert.ToBase64String(encryptedCompressedByteArray);

                    client.DefaultRequestHeaders.Add("Authorization", "Bearer " + defaultEncryptionKey);

                    string response = client.PostAsync("https://my-server.com/api/update_octree", json).Result;
                } catch (HttpRequestException e) {
