                } catch (SocketException e) {
                    Console.WriteLine("A socket error occurred: " + e.Message);
                } catch (InvalidOperationException e) {
                    Console.WriteLine("An invalid operation was attempted: " + e.Message);
                } catch (JsonSerializationException e) {
                    Console.WriteLine("There was a problem serializing the JSON data: " + e.Message);
                } catch (DatabaseConnectionException e) {
                    Console.WriteLine("A database connection error occurred: " + e.Message);
                } catch (DataCompressionFailureException e) {
                    Console.WriteLine("There was a problem with the compressed data: " + e.Message);
                } finally {
                    if (client != null) {
                        client.Dispose();
                    }
                }
            }
        }

        // Custom compression algorithm using GZipStream class
        public static byte[] CompressData(int featureSize, int numberOfLeafNodes) {
