```
class NfalibManager {
private:
    std::map<std::string, NFAPI_CRC_INDICATION_PDU> rntiToPduMap; // RNTI to PDU map
    std::mutex mutex; // Mutex for thread safety
public:
    void addPdu(NFAPI_CRC_INDICATION_PDU pdu) {
        std::lock_guard<std::mutex> lock(mutex);
        if (pdu.rx_ue_information.tag == RX_UE_INFORMATION_TAG && pdu.crc_indication.rel8.tag == CRC_INDICATION_REL8_TAG) {
            rntiToPduMap[std::to_string(pdu.rx_ue_information.rnti)] = pdu;
        } else {
            throw std::runtime_error("Invalid input tags or RNTI values");
        }
    }

    NFAPI_CRC_INDICATION_PDU getPdu(std::string rnti) {
        std::lock_guard<std::mutex> lock(mutex);
        if (rntiToPduMap.find(rnti) == rntiToPduMap.end()) {
            throw std::runtime_error("RNTI not found");
        }
        return rntiToPduMap[rnti];
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mutex);
        rntiToPduMap.clear();
    }

    std::string serialize() {
        std::lock_guard<std::mutex> lock(mutex);
        std::ostringstream oss;
        for (auto it = rntiToPduMap.begin(); it != rntiToPduMap.end(); ++it) {
            oss << it->first << ":" << it->second.rx_ue_information.rnti << "," << it->second.crc_indication.rel8.val << ";";
        }
        return oss.str();
    }
};
```
