// DynamicRandomValueGenerator.cs
using System;
using System.IO;
using System.Text.Json;
using System.Threading;

public class DynamicRandomValueGenerator
{
    // Range limits for generating random values
    private readonly int _minimum;
    private readonly int _maximum;

    // JSON configuration file path
    private string _configFilePath;

    // Caching mechanism to store frequently accessed configuration ranges
    private Dictionary<int, int> _cachedRanges = new Dictionary<int, int>();

    public DynamicRandomValueGenerator(string configFilePath)
    {
        _configFilePath = configFilePath;
        LoadConfig();
    }

    // Load configuration from JSON file and set range limits
    private void LoadConfig()
    {
        try
        {
            string jsonString = File.ReadAllText(_configFilePath);
            JsonDocument doc = JsonDocument.Parse(jsonString);

            _minimum = doc.RootElement.GetProperty("minimum").GetInt32();
            _maximum = doc.RootElement.GetProperty("maximum").GetInt32();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration: {ex.Message}");
        }
    }

    // Generate random integer within configured range limits
    public int GenerateRandomInteger()
    {
        // Use caching mechanism to reduce overhead of frequently accessed ranges
        if (_cachedRanges.TryGetValue(_maximum - _minimum + 1, out int cachedRange))
        {
            return Random.Next(cachedRange);
        }

        // Generate random integer within configured range limits
        return Random.Next(_minimum, _maximum);
    }

    // Generate random float within configured range limits
    public float GenerateRandomFloat()
    {
        // Use caching mechanism to reduce overhead of frequently accessed ranges
        if (_cachedRanges.TryGetValue(_maximum - _minimum + 1, out int cachedRange))
        {
            return Random.Next(cachedRange);
        }

        // Generate random float within configured range limits
        return (float)Random.NextDouble() * (_maximum - _minimum) + _minimum;
    }

    // Filter transactions based on a set of criteria, including age, number in past 3 seconds, and weighted sum
    public Tuple<int, int> FilterTransactions(List<Transaction> transactions)
    {
        try
        {
            // Calculate maximum weighted sum and corresponding transaction ID
            int maxWeightedSum = 0;
            int maxTransactionId = -1;

            foreach (Transaction transaction in transactions)
            {
                int weightedSum = transaction.Age * transaction.NumberInPast3Seconds * transaction.Amount;

                if (weightedSum > maxWeightedSum)
                {
                    maxWeightedSum = weightedSum;
                    maxTransactionId = transaction.Id;
                }
            }

            return Tuple.Create(maxWeightedSum, maxTransactionId);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error filtering transactions: {ex.Message}");
        }
    }
}

