use std::{
    env,
    path::PathBuf,
    process::Command,
    sync::{Arc, RwLock},
    thread::spawn,
};

struct CompilationResult {
    time: u64,
    rss: u64,
}

fn main() {
    let args = env::args().collect::<Vec<String>>();
    if args.len() < 2 {
        println!("Usage: {} [source files]", args[0]);
        return;
    }

    // Initialize thread-safe cache and logger
    let cache = Arc::new(RwLock::new(HashMap::new()));
    let logger = Logger::new();

    // Iterate over source files, compile each one in a separate thread
    for file in &args[1..] {
        let cache = Arc::clone(&cache);
        let logger = logger.clone();
        spawn(move || {
            let start = Instant::now();
            let res = rustc_driver::catch_with_exit_code(&file, vec!["--log-level", "info"]).unwrap();
            cache.write().unwrap().insert(file.clone(), CompilationResult { time: start.elapsed().as_millis() as u64, rss: res.rss() });
            logger.log("Compiled {} in {:?}\n", file, start.elapsed());
        });
    }
}

// Implement a custom logging system to capture detailed compilation events
struct Logger {
    level: LogLevel,
}

impl Logger {
    fn new() -> Self {
        // Initialize logger with default log level
        Self { level: LogLevel::Info }
    }

    fn set_level(&mut self, level: LogLevel) {
        // Set log level based on user input
        self.level = level;
    }

    fn log(&self, msg: &str, args: impl std::fmt::Display) {
        // Print message if log level is sufficient
        if self.level <= LogLevel::Info {
            println!("{}", format_args!(msg, args));
        }
    }
}

// Implement thread-safe caching mechanism to store compiled results
struct Cache {
    inner: HashMap<String, CompilationResult>,
}

impl Cache {
    fn new() -> Self {
        // Initialize cache with default settings
        Self { inner: HashMap::new() }
    }

    fn get(&self, file: &str) -> Option<&CompilationResult> {
        // Get cached compilation result for a specific file
        self.inner.get(file)
    }

    fn set(&mut self, file: String, res: CompilationResult) {
        // Set cached compilation result for a specific file
        self.inner.insert(file, res);
    }
}

// Implement custom logging levels to handle verbose output
#[derive(Debug)]
enum LogLevel {
    Error,
    Warning,
    Info,
    Debug,
}

impl FromStr for LogLevel {
    type Err = &'static str;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "error" => Ok(LogLevel::Error),
            "warning" => Ok(LogLevel::Warning),
            "info" => Ok(LogLevel::Info),
            "debug" => Ok(LogLevel::Debug),
            _ => Err("invalid log level"),
        }
    }
}
