#include <forward_list>
#include <string>
#include <iostream>

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& newString) {
    auto it = std::find(list.begin(), list.end(), target);
    if (it != list.end()) {
        ++it;
        list.insert_after(it, newString);
    } else {
        list.push_back(newString);
    }
}
