        return;
    }

    // Set parameter and execute query
    int param_count = 1;
    MYSQL_BIND params[param_count];
    MYSQL_RES *result;
    memset(params, 0, sizeof(params));
    params[0].buffer_type = MYSQL_TYPE_STRING;
    params[0].buffer = (char *)employee_id;
    params[0].buffer_length = strlen(employee_id);
    if (mysql_stmt_bind_param(stmt, params) != 0) {
        fprintf(stderr, "Failed to bind parameter\n");
        return;
    }
    if (mysql_stmt_execute(stmt) != 0) {
        fprintf(stderr, "Failed to execute query\n");
        return;
    }

    // Retrieve results and close statement
    result = mysql_stmt_use_result(stmt);
    if (result == NULL) {
        fprintf(stderr, "Failed to get results\n");
        return;
    }
    struct employee_details details;
    while ((row = mysql_fetch_row(result)) != NULL) {
        details.name = row[0];
        details.city = row[1];
        details.address = row[2];
    }
    mysql_stmt_close(stmt);

    // Handle error scenarios
    if (mysql_errno(conn) != 0) {
        fprintf(stderr, "Error executing query: %s\n", mysql_error(conn));
        return;
    }

    // Logging and resource management
    char *log_message = malloc(strlen(details.name) + strlen(details.city) + strlen(details.address));
    sprintf(log_message, "Retrieved employee details: %s - %s - %s", details.name, details.city, details.address);
    fprintf(stderr, log_message);
    free(log_message);
    mysql_close(conn);

    return details;
}

int main() {
    struct employee_details details = retrieveEmployeeDetails("1234", 0);
    printf("Name: %s\nCity: %s\nAddress: %s\n", details.name, details.city, details.address);
    return 0;
}
