```c
#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <string.h>

#define LOG_ERROR 0
#define LOG_WARNING 1
#define LOG_INFO 2
#define MAX_LOG_LENGTH 4096
#define LOG_FILE "error.log"

typedef struct {
    int level;
    char *message;
} LogEntry;

void logEvent(int level, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);

    // Get current time
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    // Build log message
    LogEntry entry;
    entry.level = level;
    vsnprintf(entry.message, MAX_LOG_LENGTH, fmt, args);

    // Open/create log file in append mode
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Error opening log file!\n");
        return;
    }

    // Write log entry to file
    fprintf(file, "%s [%d] %s\n", timestamp, level, entry.message);

    // Close log file
    fclose(file);
}
```
