const reduceAsync = (arr, initialValue, callback) => {
  // Create a new promise that will resolve when the reduction is complete
  const promise = new Promise((resolve, reject) => {
    let result = initialValue;

    // Use a separate function to handle fetching values from the external data source
    const fetchValues = async (startIndex, endIndex) => {
      try {
        // Fetch the values between startIndex and endIndex from the external data source
        const values = await fetchExternalData(startIndex, endIndex);

        // Use a for loop to reduce the values and update the result variable
        for (let i = 0; i < values.length; i++) {
          result = callback(result, values[i]);
        }
      } catch (error) {
        // If an error occurs during fetching or reducing the values, resolve with a fallback value
        resolve(result);
      }
    };

    // Use a separate function to handle the parallel reduction operations
    const reduceParallel = async () => {
      try {
        // Divide the array into smaller chunks and fetch values for each chunk concurrently
        const chunks = [];
        const chunkSize = Math.ceil(arr.length / 2);
        for (let i = 0; i < arr.length; i += chunkSize) {
          chunks.push(fetchValues(i, i + chunkSize));
        }

        // Wait for all the chunks to be fetched and reduced
        await Promise.all(chunks);

        // Return the final result
        resolve(result);
      } catch (error) {
        // If an error occurs during parallel reduction, reject with the original error
        reject(error);
      }
    };

    // Start the parallel reduction operation if the array is too large to be reduced in a single step
    if (arr.length > 1000) {
      reduceParallel();
    } else {
      // Reduce the array sequentially and return the final result
      arr.forEach((element, index) => {
        result = callback(result, element);
      });
      resolve(result);
    }
  });

  // Return the promise that will resolve with the reduced value
  return promise;
};

// Test the reduceAsync function with various arrays and initial values
describe('reduceAsync', () => {
  it('reduces an array of numbers sequentially', async () => {
    const arr = [1, 2, 3, 4];
    const initialValue = 0;
    const callback = (accumulator, currentValue) => accumulator + currentValue;
    expect(await reduceAsync(arr, initialValue, callback)).toEqual(10);
  });

  it('reduces an array of numbers in parallel', async () => {
    const arr = [1, 2, 3, 4];
    const initialValue = 0;
    const callback = (accumulator, currentValue) => accumulator + currentValue;
    expect(await reduceAsync(arr, initialValue, callback)).toEqual(10);
  });

  it('handles errors from the external data source', async () => {
    // Mock a failing fetchExternalData function that always throws an error
    const fetchValues = jest.fn(() => {
      throw new Error('Failed to fetch values');
    });
    const arr = [1, 2, 3, 4];
    const initialValue = 0;
    const callback = (accumulator, currentValue) => accumulator + currentValue;
    expect(await reduceAsync(arr, initialValue, callback)).toEqual(0);
  });

  it('handles network latency and partial failures', async () => {
    // Mock a slow fetchExternalData function that takes some time to respond
    const fetchValues = jest.fn(() => new Promise((resolve) => setTimeout(resolve, 1000)));
    const arr = [1, 2, 3, 4];
    const initialValue = 0;
    const callback = (accumulator, currentValue) => accumulator + currentValue;
    expect(await reduceAsync(arr, initialValue, callback)).toEqual(0);
  });
});
