import os
import datetime
from collections import defaultdict

class ImageCache:
    def __init__(self, cache_dir='cache', default_theme_dir='default'):
        self.cache_dir = cache_dir
        self.default_theme_dir = default_theme_dir
        self.image_map = {}
        self.last_accessed = defaultdict(list)
        self.usage_frequency = defaultdict(int)

    def get_image(self, image_path):
        if not os.path.isfile(image_path):
            raise ValueError('Image path does not exist')

        image_name = os.path.basename(image_path)
        theme_dir = os.path.dirname(image_path)
        user_id = os.getuid()

        if self.cache_dir not in theme_dir:
            theme_dir = os.path.join(self.cache_dir, theme_dir)

        cache_file = os.path.join(theme_dir, image_name)

        if not os.path.exists(cache_file):
            try:
                with open(image_path, 'rb') as f:
                    data = f.read()
                    with open(cache_file, 'wb') as cf:
                        cf.write(data)
            except Exception as e:
                print('Failed to cache image', e)
                return None

        self.last_accessed[user_id].append(image_name)
        self.usage_frequency[image_name] += 1

        return cache_file

    def recycle_old_images(self):
        user_ids = self.last_accessed.keys()
        for user_id in user_ids:
            image_names = self.last_accessed[user_id]
            for image_name in image_names:
                cache_file = os.path.join(self.cache_dir, user_id, image_name)
                if not os.path.exists(cache_file):
                    continue

                last_accessed = self.last_accessed[user_id][image_name]
                usage_frequency = self.usage_frequency[image_name]
                if usage_frequency == 0 or datetime.datetime.now() - last_accessed > datetime.timedelta(days=30):
                    try:
                        os.remove(cache_file)
                    except Exception as e:
                        print('Failed to remove old image', e)

    def clear_unused_images(self):
        user_ids = self.last_accessed.keys()
        for user_id in user_ids:
            image_names = self.last_accessed[user_id]
            for image_name in image_names:
                cache_file = os.path.join(self.cache_dir, user_id, image_name)
                if not os.path.exists(cache_file):
                    continue

                usage_frequency = self.usage_frequency[image_name]
                if usage_frequency == 0:
                    try:
                        os.remove(cache_file)
                    except Exception as e:
                        print('Failed to remove unused image', e)
