using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

namespace GameServerConfigManager
{
    public class ConfigManager
    {
        private readonly string _configServiceUrl;
        private readonly Dictionary<string, object> _cachedParameters = new Dictionary<string, object>();
        private readonly SemaphoreSlim _lock = new SemaphoreSlim(1);

        public ConfigManager(string configServiceUrl)
        {
            _configServiceUrl = configServiceUrl;
        }

        public async Task<object> GetParameterAsync(string parameterName, CancellationToken cancellationToken)
        {
            if (_cachedParameters.TryGetValue(parameterName, out var value))
            {
                return value;
            }

            using (await _lock.LockAsync(cancellationToken))
            {
                if (_cachedParameters.TryGetValue(parameterName, out value))
                {
                    return value;
                }

                try
                {
                    var response = await FetchParameterFromServiceAsync(parameterName, cancellationToken);
                    value = ConvertResponseToValue(response);
                    _cachedParameters[parameterName] = value;
                }
                catch (Exception ex) when (ex is HttpRequestException || ex is DecryptionIssueException)
                {
                    throw new ParameterFetchingException($"Failed to fetch parameter '{parameterName}' from service", ex);
                }
            }

            return value;
        }

        private async Task<string> FetchParameterFromServiceAsync(string parameterName, CancellationToken cancellationToken)
        {
            var request = new HttpRequestMessage(HttpMethod.Get, $"{_configServiceUrl}/parameters/{parameterName}");
            using var response = await _httpClient.SendAsync(request, cancellationToken);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Failed to fetch parameter '{parameterName}' from service: HTTP {response.StatusCode}");
            }

            var responseContent = await response.Content.ReadAsStringAsync();
            return responseContent;
        }

