        {
            // Implement conversion logic based on the type of the parameter
            throw new NotImplementedException("Conversion logic not implemented");
        }

        public async Task ValidateUserAsync(string username, string password, CancellationToken cancellationToken)
        {
            if (string.IsNullOrEmpty(username))
            {
                throw new ArgumentNullException(nameof(username));
            }

            if (string.IsNullOrEmpty(password))
            {
                throw new ArgumentNullException(nameof(password));
            }

            var request = new HttpRequestMessage(HttpMethod.Post, $"{_configServiceUrl}/validate/{username}");
            request.Content = new StringContent(password);
            using var response = await _httpClient.SendAsync(request, cancellationToken);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Failed to validate user '{username}' with service");
            }
        }

        public async Task<UserLockoutInfo> GetUserLockoutInfoAsync(string username, CancellationToken cancellationToken)
        {
            if (string.IsNullOrEmpty(username))
            {
                throw new ArgumentNullException(nameof(username));
            }

            var request = new HttpRequestMessage(HttpMethod.Get, $"{_configServiceUrl}/lockout/{username}");
            using var response = await _httpClient.SendAsync(request, cancellationToken);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Failed to get lockout info for user '{username}' from service");
            }

            var responseContent = await response.Content.ReadAsStringAsync();
            return ConvertResponseToLockoutInfo(responseContent);
