using System;
using System.Net.Http;
using Newtonsoft.Json;
using OAuth2;

public class GameSettingsModule
{
    private readonly HttpClient _httpClient;
    private readonly JsonSerializer _jsonSerializer;
    private readonly OAuth2Token _token;

    public GameSettingsModule(string baseUrl, string apiKey)
    {
        _httpClient = new HttpClient();
        _jsonSerializer = new Newtonsoft.Json.JsonSerializer();
        _token = new OAuth2Token(apiKey);

        _httpClient.DefaultRequestHeaders.Authorization = $"Bearer {_token}";
    }

    public async Task<GameSettings> GetSettingsAsync()
    {
        var requestUrl = $"{baseUrl}/settings";
        var response = await _httpClient.GetAsync(requestUrl);
        response.EnsureSuccessStatusCode();

        var jsonResponse = await response.Content.ReadAsStringAsync();
        return _jsonSerializer.Deserialize<GameSettings>(jsonResponse);
    }

    public async Task UpdateSettingsAsync(GameSettings settings)
    {
        var requestUrl = $"{baseUrl}/settings";
        var jsonRequest = _jsonSerializer.Serialize(settings);

        using (var httpContent = new StringContent(jsonRequest, Encoding.UTF8, "application/json"))
        {
            var response = await _httpClient.PutAsync(requestUrl, httpContent);
            response.EnsureSuccessStatusCode();

            var jsonResponse = await response.Content.ReadAsStringAsync();
            if (response.IsSuccessStatusCode)
            {
                // Update local cache with new settings
                _settings = _jsonSerializer.Deserialize<GameSettings>(jsonResponse);
                Console.WriteLine("Updated game settings successfully.");
            }
            else
            {
                // Log detailed errors and exceptions for troubleshooting
                var errorMessage = response.Content.ReadAsStringAsync().Result;
                Console.WriteLine($"Error updating game settings: {errorMessage}");
            }
        }
    }
}

public class GameSettings
{
    public string HostName { get; set; }
    public int PortNumber { get; set; }
    public bool EnableDebugMode { get; set; }
    // Other settings as needed...
}
