};

// Generate and populate a list of NFAPI_CRC_INDICATION_PDUs with unique RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG values
void generate_nfapi_crc_indication_pdus(struct NFAPI_CRC_INDICATION_PDU *pdu_list) {
    // Get the current time in milliseconds
    uint64_t curr_time = (uint64_t)(time(NULL) * 1000);

    // Initialize a random seed for generating unique values
    srand(curr_time);

    // Loop through each PDU in the list
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        struct NFAPI_CRC_INDICATION_PDU *pdu = &pdu_list[i];

        // Generate a unique RX_UE_INFORMATION_TAG value
        pdu->rx_ue_information_tag = rand() % MAX_RX_UE_INFORMATION_TAG;

        // Generate a unique RNTI value
        pdu->rnti = rand() % MAX_RNTI;

        // Set the CRCFLAG to a random value
        pdu->crc_indication_rel8_tag.crcflag = rand() % 256;
    }
}
