import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import com.google.common.base.Preconditions;
import com.google.common.util.concurrent.ListenableFuture;
import com.google.common.util.concurrent.MoreExecutors;
import io.grpc.ManagedChannel;
import io.grpc.stub.StreamObserver;

public class ChannelPool {
    private static final int MAX_CONCURRENT_CHANNELS = 10;
    private static final ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_CHANNELS);

    // Map of channel addresses to ManagedChannels
    private Map<String, ManagedChannel> channels = new HashMap<>();

    public ChannelPool() {
        super();
    }

    public ListenableFuture<ManagedChannel> getOrCreate(String address) {
        Preconditions.checkNotNull(address);

        // Check if a channel exists for the given address
        ManagedChannel channel = channels.get(address);

        // If a channel does not exist, create it
        if (channel == null) {
            channel = ManagedChannelBuilder.forAddress(address).maxInboundMessageSize(1024 * 1024).usePlaintext().build();
            channels.put(address, channel);
        }

        // Return a ListenableFuture for the channel
        return MoreExecutors.listeningDecorator(executor).submit(() -> {
            try {
                // Wait for the channel to become ready
                while (!channel.isReady()) {
                    Thread.sleep(10);
                }

                return channel;
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });
    }

    public void shutdown() throws InterruptedException {
        executor.shutdown();

        // Wait for all channels to be closed
        while (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
            Iterator<ManagedChannel> it = channels.values().iterator();

            while (it.hasNext()) {
                ManagedChannel channel = it.next();

                // Close the channel and remove it from the map
                try {
                    channel.shutdownNow();
                    it.remove();
                } catch (Exception e) {
                    System.err.println("Error closing channel: " + e);
                }
            }
        }
    }
}
