#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class BackgroundExecutor {
private:
    struct Command {
        std::string command;
        int priority;
        bool completed = false;
        std::string output;
        std::string error;
    };

    std::vector<Command> commands_;
    size_t nextIndex_ = 0;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::thread execThread_;
    bool running_ = false;

public:
    BackgroundExecutor() {}

    // Add a new command to the queue with a specified priority for execution.
    void addCommand(const std::string& command, int priority) {
        std::lock_guard<std::mutex> lock(mutex_);
        commands_.push_back({command, priority, false, "", ""});
        cv_.notify_all();
    }

    // Execute the next command in the queue based on priority levels.
    void executeNext() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (running_) {
            return;
        }
        running_ = true;
        execThread_ = std::thread([this] { this->executeCommands(); });
    }

    // Return the status of a specific command (by index).
    bool getStatus(size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        return commands_[index].completed;
    }

    // Retrieve the output of a specific command if it has completed successfully.
    std::string getOutput(size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        return commands_[index].output;
    }

    // Retrieve the error message of a specific command if it has failed.
    std::string getError(size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        return commands_[index].error;
    }

    // Set configuration parameters for the executor.
    void configure(int maxThreads, int execTimeout, int statusCheckInterval) {}

    // Provide an interactive command input interface for users.
    void interactiveInput() {}

    // Display the current status of all commands in the queue.
    void viewAllCommands() {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& command : commands_) {
            if (command.completed) {
                std::cout << "Command " << command.priority << " completed with output: " << command.output << "\n";
            } else {
                std::cout << "Command " << command.priority << " running...\n";
            }
        }
    }

    // Allow retrieval of either the output or error message of a specific command.
    void retrieveResult(size_t index) {}

private:
    // Execute commands based on priority levels.
    void executeCommands() {
        std::lock_guard<std::mutex> lock(mutex_);
        while (nextIndex_ < commands_.size()) {
            Command& command = commands_[nextIndex_];
            if (!command.completed) {
                command.output = executeCommand(command.command);
                command.completed = true;
            }
            nextIndex_++;
        }
        running_ = false;
    }

    // Execute a specific command and return its output or error message.
    std::string executeCommand(const std::string& command) {
        std::string output, error;
        int result = system(command.c_str());
        if (result == 0) {
            output = "Command completed successfully.";
        } else {
            error = "Command execution failed with exit code: " + std::to_string(result);
        }
        return output;
    }
};

