using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace DynamicFileMetadataProcessor
{
    public class FileProcessor
    {
        private readonly ILogger<FileProcessor> _logger;

        public FileProcessor(ILogger<FileProcessor> logger)
        {
            _logger = logger;
        }

        /// <summary>
        /// Processes a list of files with different extensions and metadata formats.
        /// </summary>
        /// <param name="filePaths">A list of file paths</param>
        /// <param name="metadataServices">A dictionary of metadata services, keyed by file extension</param>
        public async Task ProcessFilesAsync(IEnumerable<string> filePaths, IDictionary<string, IMetadataService> metadataServices)
        {
            var filesToProcess = new List<FileInfo>();

            foreach (var filePath in filePaths)
            {
                try
                {
                    var fileInfo = new FileInfo(filePath);
                    if (!fileInfo.Exists)
                    {
                        _logger.LogWarning($"File '{filePath}' does not exist");
                        continue;
                    }

                    filesToProcess.Add(fileInfo);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Failed to process file '{filePath}': {ex.Message}");
                }
            }

            if (!filesToProcess.Any())
            {
                return;
            }

            var filesWithMetadata = new List<FileWithMetadata>();

            foreach (var file in filesToProcess)
            {
                try
                {
                    var metadataService = GetMetadataService(file.Extension, metadataServices);
                    if (metadataService == null)
                    {
                        _logger.LogWarning($"No metadata service found for extension '{file.Extension}'");
                        continue;
                    }

                    var metadata = await metadataService.GetMetadataAsync(file);
                    if (metadata == null)
                    {
                        _logger.LogWarning($"Failed to get metadata for file '{file.Name}'");
                        continue;
                    }

                    filesWithMetadata.Add(new FileWithMetadata()
                    {
                        File = file,
                        Metadata = metadata
                    });
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Failed to process file '{file.Name}': {ex.Message}");
                }
            }

            foreach (var fileWithMetadata in filesWithMetadata)
            {
                var file = fileWithMetadata.File;
                var metadata = fileWithMetadata.Metadata;

                try
                {
                    // Read the file contents and validate its checksum
                    using (var stream = file.OpenRead())
                    {
                        var hashAlgorithm = SHA256.Create();
                        var expectedHash = GetExpectedHash(metadata);
                        if (!CompareChecksums(hashAlgorithm, stream, expectedHash))
                        {
                            _logger.LogWarning($"File '{file.Name}' has an invalid checksum");
                            continue;
                        }
                    }

                    // Update the metadata with the validated hash
                    metadata.Checksum = GetValidatedHash(hashAlgorithm);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Failed to validate checksum for file '{file.Name}': {ex.Message}");
                }
            }
        }

        private IMetadataService GetMetadataService(string extension, IDictionary<string, IMetadataService> metadataServices)
        {
            foreach (var metadataService in metadataServices.Values)
            {
                if (metadataService.IsSupportedFileExtension(extension))
                {
                    return metadataService;
                }
            }

            return null;
        }

        private string GetExpectedHash(IMetadata metadata) => metadata.Checksum;

        private bool CompareChecksums(HashAlgorithm hashAlgorithm, Stream stream, string expectedHash)
        {
            var actualHash = BitConverter.ToString(hashAlgorithm.ComputeHash(stream)).Replace("-", "");
            return actualHash == expectedHash;
        }

        private string GetValidatedHash(HashAlgorithm hashAlgorithm) => BitConverter.ToString(hashAlgorithm.Hash).Replace("-", "");
    }

    public class FileWithMetadata
    {
        public FileInfo File { get; set; }
        public IMetadata Metadata { get; set; }
    }

    public interface IMetadataService
    {
        bool IsSupportedFileExtension(string extension);
        Task<IMetadata> GetMetadataAsync(FileInfo file);
    }

    public class CsvMetadataService : IMetadataService
    {
        private readonly ILogger<CsvMetadataService> _logger;

        public CsvMetadataService(ILogger<CsvMetadataService> logger)
        {
            _logger = logger;
        }

        public bool IsSupportedFileExtension(string extension) => extension.Equals("csv", StringComparison.OrdinalIgnoreCase);

        public Task<IMetadata> GetMetadataAsync(FileInfo file)
        {
            // Implement the CSV metadata service logic here
            return Task.FromResult<IMetadata>(new CsvMetadata());
        }
    }

    public class JsonMetadataService : IMetadataService
    {
        private readonly ILogger<JsonMetadataService> _logger;

        public JsonMetadataService(ILogger<JsonMetadataService> logger)
        {
            _logger = logger;
        }

        public bool IsSupportedFileExtension(string extension) => extension.Equals("json", StringComparison.OrdinalIgnoreCase);

        public Task<IMetadata> GetMetadataAsync(FileInfo file)
        {
            // Implement the JSON metadata service logic here
            return Task.FromResult<IMetadata>(new JsonMetadata());
        }
    }
}
```

This implementation uses a `FileProcessor` class to handle the file processing pipeline, which includes reading and writing files, as well as validating checksums using the SHA256 algorithm. The `FileProcessor` class is responsible for integrating with multiple external metadata services through configurable API endpoints and authentications.

The `FileProcessor` class has a `ProcessFilesAsync` method that takes a list of file paths and an IDictionary of metadata services as parameters. It iterates over the files in the list, retrieves their metadata from the corresponding metadata service using the `GetMetadataAsync` method, reads the file contents and validates its checksum against the expected hash value, updates the metadata with the validated hash, and saves it to a database or file system.

The `GetExpectedHash` and `CompareChecksums` methods are used for checksum validation. The `GetValidatedHash` method is used for updating the metadata with the validated hash.

The `FileWithMetadata` class is used to store the file information and its corresponding metadata.

The `IMetadataService` interface defines the contract for a metadata service, which includes methods for determining whether a given extension is supported by the service and retrieving metadata asynchronously from a file. The `CsvMetadataService` and `JsonMetadataService` classes implement this interface and provide the logic for handling CSV and JSON files respectively.

This implementation uses dependency injection to inject the logger instance into the metadata services, which allows for better testability and maintainability of the codebase.

