        // Decrypt the ciphertext using AES-CBC and specified padding mode
        var decryptedBytes = await DecryptAsync(encryptedBytes, aes);

        // Handle potential exceptions related to padding oracle attacks or other errors
        try
        {
            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
