import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MoSTStateManager {
    private static final Logger logger = LoggerFactory.getLogger(MoSTStateManager.class);

    private Properties properties;

    public MoSTState loadMoSTStateFromFile(String filePath) throws CustomException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            MoSTState state = (MoSTState) ois.readObject();
            logger.info("Loaded MoST state from {}", filePath);
            return state;
        } catch (ClassNotFoundException | IOException e) {
            logger.error("Error loading MoST state from {}", filePath, e);
            throw new CustomException("Failed to load MoST state from " + filePath, e);
        }
    }
}
