use std::error::Error;
use std::time::{SystemTime, UNIX_EPOCH};
use std::env;
use std::fs;
use std::io::Write;
use std::path::PathBuf;

fn generate_token(username: String, timestamp: u64, secret_key: &str) -> Result<String, Box<dyn Error>> {
    // Concatenate the username, timestamp, and secret key
    let token_data = format!("{}{}{}", username, timestamp, secret_key);

    // Hash the concatenated data using SHA-256
    let hashed_token = sha2::Sha256::hash(token_data.as_bytes());

    // Return the hexadecimal representation of the hashed token
    Ok(hex::encode(hashed_token))
}

fn validate_token(token: String, secret_key: &str) -> Result<bool, Box<dyn Error>> {
    // Extract the username and timestamp from the token
    let (username, timestamp) = token.split_once("-").ok_or(Error::new("Invalid token format"))?;

    // Calculate the current timestamp
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?;
    let now = now.as_secs();

    // Check if the timestamp is within a certain range of the current time
    if (timestamp - 30) < now && now < (timestamp + 30) {
        return Ok(true);
    }

    // The token is not valid, return false
    Ok(false)
}

fn check_token_cache(token: String) -> Result<bool, Box<dyn Error>> {
    // Check if the token exists in the cache
    let cached_token = token_cache.get(&token).ok_or(Error::new("Token not found in cache"))?;

    // If the token is found in the cache, check if it is still valid
    if validate_token(cached_token.clone(), secret_key)? {
        return Ok(true);
    }

    // The token is not valid or has expired, remove it from the cache and return false
    token_cache.remove(&token);
    Ok(false)
}

fn add_token_to_cache(token: String) -> Result<(), Box<dyn Error>> {
    // Check if the token already exists in the cache
    let existing_token = check_token_cache(token.clone())?;

    // If the token is not found in the cache, add it to the cache
    if !existing_token {
        token_cache.insert(token, token);
    }

    // Return success
    Ok(())
}

fn handle_token(token: String) -> Result<String, Box<dyn Error>> {
    // Check if the token is already in the cache
    let cached = check_token_cache(token.clone())?;

    // If the token is found in the cache, return it
    if cached {
        return Ok(token);
    }

    // The token is not found in the cache, validate it and add it to the cache if valid
    let valid = validate_token(token.clone(), secret_key)?;

    if !valid {
        // The token is invalid, return an error
        Err(Error::new("Invalid token"))
    } else {
        // The token is valid, add it to the cache and return it
        add_token_to_cache(token.clone())?;
        Ok(token)
    }
}

fn create_directory(name: String) -> Result<(), Box<dyn Error>> {
    // Check if the directory already exists
    let dir = PathBuf::from(&name);
    if fs::metadata(&dir).is_ok() {
        return Err(Error::new("Directory already exists"));
    }

    // Create the new directory and set the environment variable
    match fs::create_dir_all(&dir) {
        Ok(_) => (),
        Err(e) => return Err(Box::new(e)),
    };
    env::set_var("DIRECTORY", dir.to_str().unwrap());

    // Log the operation for auditing purposes
    println!("Created directory {}", &name);

    // Return success
    Ok(())
}
