class DistributedCache {
private:
    // Forward list structure to store strings
    std::forward_list<std::string> cache;

    // Map to store string keys with their corresponding indices in the forward list
    std::map<std::string, size_t> keyToIndexMap;

    // Mutex for synchronizing access to the cache and its data structures
    std::mutex cacheMutex;

public:
    // Insert a string into the cache
    void insert(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        size_t index = cache.size();
        cache.push_front(key);
        keyToIndexMap[key] = index;
    }

    // Search for a string in the cache, case-insensitively
    std::optional<std::string> search(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = keyToIndexMap.find(key);
        if (it == keyToIndexMap.end()) {
            return std::nullopt;
        } else {
            return cache[it->second];
        }
    }

    // Delete a string from the cache
    void delete(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = keyToIndexMap.find(key);
        if (it != keyToIndexMap.end()) {
            size_t index = it->second;
            cache.erase(cache.begin() + index);
            keyToIndexMap.erase(it);
        }
    }

