```php
function validatePasswordStrength($password) {
    // Minimum length requirement.
    if (strlen($password) < 8) {
        return false;
    }

    // Character set requirements.
    $lowercase = preg_match('/[a-z]/', $password);
    $uppercase = preg_match('/[A-Z]/', $password);
    $number = preg_match('/\d/', $password);
    $specialCharacters = preg_match('/[^a-zA-Z\d]/', $password);
    if (!$lowercase || !$uppercase || !$number || !$specialCharacters) {
        return false;
    }

    // Exclusion of common words.
    $commonWords = array("hello", "world", "foo", "bar");
    foreach ($commonWords as $word) {
        if (strpos($password, $word) !== false) {
            return false;
        }
    }

    // Password strength validation passed.
    return true;
}
```
