using System;
using System.Threading.Tasks;
using UnityEngine;

namespace DynamicRandomValueGenerator
{
    public class RandomValueGenerator
    {
        // Cache for encryption keys and initialization vectors (IVs) from the external web API
        private static Dictionary<string, string> keyCache = new Dictionary<string, string>();
        private static object cacheLock = new object();

        // Encryption/decryption methods
        public static async Task<byte[]> Encrypt(byte[] message, string encryptionKey)
        {
            // Use cached encryption key if available, otherwise fetch from API and update cache
            if (keyCache.ContainsKey(encryptionKey))
            {
                return AES.Encrypt(message, keyCache[encryptionKey]);
            }
            else
            {
                string apiResponse = await FetchApiDataAsync(encryptionKey);
                if (!string.IsNullOrEmpty(apiResponse))
                {
                    try
                    {
                        keyCache[encryptionKey] = apiResponse;
                        return AES.Encrypt(message, apiResponse);
                    }
                    catch (Exception e)
                    {
                        // Log error and return null to indicate failure
                        Debug.LogError($"Failed to encrypt message with key '{encryptionKey}': {e.Message}");
                        return null;
                    }
                }
            }

            // No cached key or API response, return null to indicate failure
            return null;
        }

        public static async Task<byte[]> Decrypt(byte[] message, string encryptionKey)
        {
            // Use cached encryption key if available, otherwise fetch from API and update cache
            if (keyCache.ContainsKey(encryptionKey))
            {
                return AES.Decrypt(message, keyCache[encryptionKey]);
            }
            else
            {
                string apiResponse = await FetchApiDataAsync(encryptionKey);
                if (!string.IsNullOrEmpty(apiResponse))
                {
                    try
                    {
                        keyCache[encryptionKey] = apiResponse;
                        return AES.Decrypt(message, apiResponse);
                    }
                    catch (Exception e)
                    {
                        // Log error and return null to indicate failure
                        Debug.LogError($"Failed to decrypt message with key '{encryptionKey}': {e.Message}");
                        return null;
                    }
                }
            }

            // No cached key or API response, return null to indicate failure
            return null;
        }

        private static async Task<string> FetchApiDataAsync(string encryptionKey)
        {
            try
            {
                string apiResponse = await new WebClient().DownloadStringTaskAsync("https://external-api.com/encryption_key/" + encryptionKey);
                return apiResponse;
            }
            catch (Exception e)
            {
                // Log error and return null to indicate failure
                Debug.LogError($"Failed to fetch encryption key from API: {e.Message}");
                return null;
            }
        }

        public static void GenerateRandomValue(int min, int max)
        {
            Task.Run(() =>
            {
                try
                {
                    // Use cached encryption key if available, otherwise fetch from API and update cache
                    string encryptionKey = "cached_key";
                    if (!keyCache.ContainsKey(encryptionKey))
                    {
                        string apiResponse = FetchApiDataAsync(encryptionKey).Result;
                        if (apiResponse != null)
                        {
                            keyCache[encryptionKey] = apiResponse;
                        }
                        else
                        {
                            // Log error and return null to indicate failure
                            Debug.LogError("Failed to fetch encryption key from API");
                            return;
                        }
                    }

                    // Generate random value within specified range using cached encryption key
                    int randomValue = UnityEngine.Random.Range(min, max);

                    // Encrypt and send encrypted message to the game server for processing
                    byte[] encryptedMessage = AES.Encrypt(BitConverter.GetBytes(randomValue), keyCache[encryptionKey]);
                    await SendToGameServerAsync(encryptedMessage);
                }
                catch (Exception e)
                {
                    // Log error and return null to indicate failure
                    Debug.LogError($"Failed to generate random value: {e.Message}");
                    return;
                }
            });
        }

        private static async Task SendToGameServerAsync(byte[] message)
        {
            try
            {
                // Send encrypted message to game server for processing
                Debug.Log("Sending encrypted message to game server");
                await new WebClient().UploadDataTaskAsync("https://game-server.com/process_message", "POST", message);
            }
            catch (Exception e)
            {
                // Log error and return null to indicate failure
                Debug.LogError($"Failed to send encrypted message to game server: {e.Message}");
                return;
            }
        }
    }
}
