void insertAfterString(forward_list<string>& list, const string& str, const string& newStr) {
    // Find the first occurrence of the specified string in the list
    auto it = find(list.begin(), list.end(), str);

    // If the string is found, insert the new string after it
    if (it != list.end()) {
        ++it;
        it = list.insert_after(it, newStr);
    } else {
        // If the string is not found, insert the new string at the end of the list
        it = list.insert_after(list.end(), newStr);
    }
