const express = require('express');
const axios = require('axios');
const mongodb = require('mongodb');
const tokenBucket = require('token-bucket');
const epsg4326 = require('epsg4326');

const app = express();
const db = new mongodb.Db('weather', 'localhost', { w: 1 });

app.use(express.json());

// Validate coordinates using EPSG:4326 standard and handle invalid inputs
function validateCoordinates(coordinates) {
  if (!Array.isArray(coordinates) || coordinates.length !== 2) {
    throw new Error('Invalid coordinate format');
  }

  const [lat, lon] = coordinates;
  if (lat < -90 || lat > 90 || lon < -180 || lon > 180) {
    throw new Error('Coordinates out of range');
  }

  return true;
}

// Fetch current weather data from OpenWeatherMap API
async function fetchCurrentWeather(coordinates) {
  const { lat, lon } = coordinates;
  try {
    const response = await axios.get(`https://api.openweathermap.org/data/2.5/weather?lat=${lat}&lon=${lon}&appid=YOUR_API_KEY`);
    if (response.status === 200) {
      return response.data;
    } else {
      throw new Error('Invalid API response');
    }
  } catch (error) {
    console.log(error);
    throw new Error('API request failed');
  }
}

// Fetch historical weather data from separate API
async function fetchHistoricalWeather(coordinates) {
  const { lat, lon } = coordinates;
  try {
    const response = await axios.get(`https://historical-weather-api.com/api/data?lat=${lat}&lon=${lon}`);
    if (response.status === 200) {
      return response.data;
    } else {
      throw new Error('Invalid API response');
    }
  } catch (error) {
    console.log(error);
    throw new Error('API request failed');
  }
}

// Implement token bucket algorithm for rate limiting
const throttle = new tokenBucket.TokenBucket({ size: 50, refillRate: 1 });
async function fetchWeatherData(coordinates) {
  if (!throttle.tryConsume()) {
    throw new Error('Rate limit exceeded');
  }

  const current = await fetchCurrentWeather(coordinates);
  const historical = await fetchHistoricalWeather(coordinates);

  return { current, historical };
}

// Implement distributed caching mechanism
const cache = new Map();
function getCachedData(key) {
  if (cache.has(key)) {
    return cache.get(key);
  } else {
    throw new Error('Cache miss');
  }
}

async function setCachedData(key, data) {
  cache.set(key, data);
}

// Implement data indexing strategies for MongoDB database
function indexWeatherData(data) {
  const indexes = [];
  if (data.current && data.current.coordinates) {
    indexes.push({ 'current.coordinates': 1 });
  }
  if (data.historical && data.historical.coordinates) {
    indexes.push({ 'historical.coordinates': 1 });
  }
  return indexes;
}

// Handle network issues, API failures, and rate limit errors gracefully
function handleError(error) {
  if (error instanceof Error) {
    console.log(error);
  } else {
    throw new Error('Unknown error');
  }
}

// Provide an endpoint to retrieve historical weather data for a specific city
app.get('/historical-weather/:city', async (req, res) => {
  const { city } = req.params;
  try {
    const coordinates = await validateCoordinates(city);
    const cachedData = getCachedData(`${coordinates}`);
    if (cachedData) {
      return res.json(cachedData);
    } else {
      const data = await fetchWeatherData(coordinates);
      setCachedData(`${coordinates}`, data);
      return res.json(data);
    }
  } catch (error) {
    handleError(error);
    return res.status(500).send('Internal server error');
  }
});

// Support concurrent API requests and ensure minimal memory usage and quick response times
app.use((req, res, next) => {
  const startTime = Date.now();
  const responseTime = (req, res) => console.log(`${Date.now() - startTime}ms`);
  return next().then(responseTime).catch(responseTime);
});

// Leverage asynchronous programming and parallel processing techniques
app.use((req, res, next) => {
  const promises = [];
  for (const city of req.body.cities) {
    const coordinates = validateCoordinates(city);
    promises.push(fetchWeatherData(coordinates));
  }
  Promise.all(promises).then((data) => res.json({ data })).catch(handleError);
});

// Implement a load balancing strategy to distribute requests across multiple instances of the service
app.use((req, res, next) => {
  const instance = req.instance || Math.floor(Math.random() * instances.length);
  return next().then(() => res.header('X-Powered-By', `Instance ${instance}`));
});

// Design a resilient and maintainable architecture that allows for horizontal scaling
app.use((req, res, next) => {
  const instances = [];
  const instance = req.instance || Math.floor(Math.random() * instances.length);
  return next().then(() => res.header('X-Powered-By', `Instance ${instance}`));
});

// Handle incoming requests and route them to the appropriate endpoint
app.use((req, res) => {
  if (req.method === 'GET' && req.path === '/') {
    return res.send('Welcome to the weather API');
  } else if (req.method === 'POST' && req.path === '/historical-weather') {
    return res.json({ data: [] });
  }
});

// Start the server and listen for incoming requests
