import json

def generate_dashboard_widgets(widgets):
    # Initialize JSON object to store dashboard configuration
    dashboard = {
        "widgets": []
    }

    # Iterate over each widget and add it to the dashboard configuration
    for widget in widgets:
        # Handle missing title attribute
        if not widget["title"]:
            continue

        # Validate data source
        if not is_valid_data_source(widget["data_source"]):
            log_error("Invalid data source provided for widget {}".format(widget["title"]))
            continue

        # Check refresh interval
        if widget["refresh_interval"] < MINIMUM_REFRESH_INTERVAL:
            log_error("Refresh interval too low for widget {} (minimum is {})".format(widget["title"], MINIMUM_REFRESH_INTERVAL))
            continue

        # Add widget to dashboard configuration
        dashboard["widgets"].append({
            "title": widget["title"],
            "width": widget["width"] if "width" in widget else DEFAULT_WIDTH,
            "height": widget["height"] if "height" in widget else DEFAULT_HEIGHT,
            "data_source": widget["data_source"],
            "refresh_interval": widget["refresh_interval"]
        })

    # Return JSON string representing dashboard configuration
    return json.dumps(dashboard)

# Cache valid data sources to prevent unnecessary requests
valid_data_sources = {}

def is_valid_data_source(data_source):
    global valid_data_sources

    # Check cache first
    if data_source in valid_data_sources:
        return True

    # Send request to endpoint and check response
    try:
        response = requests.get(data_source)
        if response.status_code == 200:
            valid_data_sources[data_source] = True
            return True
        else:
            log_error("Invalid data source provided for widget {} (status code {})".format(widget["title"], response.status_code))
            return False
    except requests.exceptions.RequestException as e:
        log_error("Error checking validity of data source for widget {} ({})".format(widget["title"], e))
        return False
