```cpp
#include <iostream>
#include <string>
#include <forward_list>

void insertAfter(std::forward_list<std::string>& list, const std::string& value, const std::string& position) {
  // Find the first occurrence of the given value in the list
  auto it = list.begin();
  while (it != list.end() && *it != value) {
    ++it;
  }

  // If the value is not found, insert at the end of the list
  if (it == list.end()) {
    list.push_back(value);
  } else {
    // Insert after the first occurrence of the given value
    ++it;
    list.insert_after(it, value);
  }
}
```
