```csharp
using System.Collections.Generic;
using System.Data;
using System.Net;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

public static async Task<DataTableReader> sendToDatabase(byte[] data, string connectionString, string sqlQuery) {
  // Create a SQL Server connection using the specified connection string
  SqlConnection conn = new SqlConnection(connectionString);

  // Send the byte array to the database server asynchronously
  await conn.OpenAsync();
  SqlCommand cmd = new SqlCommand(sqlQuery, conn);
  cmd.Parameters.AddWithValue("@data", data);
  SqlDataReader reader = await cmd.ExecuteReaderAsync();

  // Return a DataTableReader object containing the result of the query
  return reader;
}
