```
using System;
using System.Security.Cryptography;

namespace Encryption
{
    public static class AESCbcDecrypter
    {
        private const int KeySize = 256; // in bits
        private const int IvSize = 128; // in bits

        public static byte[] DecryptWithAesCbc(byte[] ciphertext, string password, string salt)
        {
            try
            {
                var key = DeriveKeyFromPassword(password, salt);
                var iv = GenerateIv();

                using (var aesAlgorithm = Aes.Create())
                {
                    aesAlgorithm.KeySize = KeySize;
                    aesAlgorithm.BlockSize = IvSize;
                    aesAlgorithm.Mode = CipherMode.CBC;

                    using (var decryptor = aesAlgorithm.CreateDecryptor(key, iv))
                    {
                        var plaintext = new byte[ciphertext.Length];
                        var bytesRead = 0;
                        var numBytesDecrypted = 0;

                        while (bytesRead < ciphertext.Length)
                        {
                            numBytesDecrypted = decryptor.TransformBlock(ciphertext, bytesRead, ciphertext.Length - bytesRead, plaintext, bytesRead);
                            bytesRead += numBytesDecrypted;
                        }

                        return plaintext;
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred during decryption: " + ex.Message);
                return null;
            }
        }

        private static byte[] DeriveKeyFromPassword(string password, string salt)
        {
            var key = new byte[KeySize / 8];
            using (var pbkdf2 = new Rfc2898DeriveBytes(password, salt))
            {
                key = pbkdf2.GetBytes(key.Length);
            }
            return key;
        }

        private static byte[] GenerateIv()
        {
            var iv = new byte[IvSize / 8];
            using (var rng = new RNGCryptoServiceProvider())
            {
                rng.GetBytes(iv);
            }
            return iv;
        }
    }
}
```
