import java.io.File;
import java.util.HashMap;
import java.util.Map;

public class AudioTranscoder {
    private static final Map<Integer, String> SAMPLING_RATES = new HashMap<>() {{
        put(8000, "8kHz");
        put(16000, "16kHz");
        put(22050, "22.05kHz");
        put(44100, "44.1kHz");
        put(48000, "48kHz");
    }};

    private static final Map<Integer, String> BIT_DEPTHS = new HashMap<>() {{
        put(16, "16-bit");
        put(24, "24-bit");
    }};

    private static final Map<String, String> CHANNEL_CONFIGS = new HashMap<>() {{
        put("stereo", "Stereo");
        put("mono", "Mono");
    }};

    public void processAudioFiles(String inputFilePath, String outputFilePath) {
        // Validate file paths and audio format support
        if (!isValidFilePath(inputFilePath)) {
            System.out.println("Invalid input file path!");
            return;
        }
        if (!isValidFilePath(outputFilePath)) {
            System.out.println("Invalid output file path!");
            return;
        }
        if (!isSupportedAudioFormat(inputFilePath)) {
            System.out.println("Unsupported audio format in input file!");
            return;
        }

        // Transcode and extract metadata
        AudioTranscoder transcoder = new LAME();
        AudioInfo audioInfo = transcoder.transcode(inputFilePath, outputFilePath);

        // Store extracted metadata in struct
        audioInfo.getSamplingRate() != null ? SAMPLING_RATES.put(audioInfo.getSamplingRate(), "8kHz") : "";
        audioInfo.getBitDepth() != null ? BIT_DEPTHS.put(audioInfo.getBitDepth(), "16-bit") : "";
        audioInfo.getChannelConfig() != null ? CHANNEL_CONFIGS.put(audioInfo.getChannelConfig(), "Stereo") : "";
    }

    private boolean isValidFilePath(String filePath) {
        // Check if file path exists and is a valid file
        File file = new File(filePath);
        return file.exists() && file.isFile();
    }

    private boolean isSupportedAudioFormat(String filePath) {
        // Check if audio format in input file is supported
        String[] extensions = {"mp3", "wav"};
        for (String extension : extensions) {
            if (filePath.endsWith("." + extension)) {
                return true;
            }
        }
        return false;
    }
}
