// Define a function to validate the SHA-256 hash of a file
bool validate_sha256(const char *file_path) {
    // Calculate the SHA-256 hash of the file content
    uint8_t hash[32];
    sha256(hash, file_path);

    // Read the previously computed hash for the same file path from cache
    const char *cache_key = "sha256:" + file_path;
    const char *cached_hash = cache_get(cache_key);

    // Check if the cached hash is available and matches the calculated hash
    bool valid = cached_hash && !strcmp(cached_hash, hash);

    // Update the cache with the new hash value
    cache_set(cache_key, hash);

    return valid;
}

