namespace Octree {
    class OctreeRandomGenerator {
    public:
        // Constructor
        OctreeRandomGenerator(int featureSize, int numLeafNodes, int dataCapacity) {
            // Initialize the random number generator
            mt19937.seed(std::random_device()());

            // Allocate memory for the octree
            allocateMemory(featureSize, numLeafNodes, dataCapacity);
        }

        // Destructor
        ~OctreeRandomGenerator() {
            delete[] mt19937;
        }

        static void initializeOctree(int featureSize, int numLeafNodes, int dataCapacity) {
            // Allocate memory for the octree
            m_octree = new OctreeNode[numLeafNodes];

            // Set the capacity of the octree
            m_capacity = numLeafNodes;

            // Allocate memory for the prefix leafs and data arrays
            m_prefixLeafs = new int[m_capacity + 1];
            m_dataArray = new float[m_capacity * featureSize];

            // Initialize the prefix leafs and data arrays
            for (int i = 0; i < m_capacity + 1; i++) {
                m_prefixLeafs[i] = 0;
            }
            for (int i = 0; i < m_capacity * featureSize; i++) {
                m_dataArray[i] = 0.0f;
            }
        }
    private:
        // Random number generator
        static std::mt19937 mt19937;

        // Octree node
        struct OctreeNode {
            int prefixLeaf;
            float* data;
        };

        // Octree nodes
        static OctreeNode* m_octree;

        // Capacity of the octree
        static int m_capacity;

        // Prefix leafs
        static int* m_prefixLeafs;

        // Data array
        static float* m_dataArray;
    };
}
