   * @param {number} max - maximum value of the range (exclusive)
   * @returns {number} a randomly generated integer within the specified range
   */
  generateRandomInteger(min, max) {
    // validate input range limits
    if (!this.rangeLimits || this.rangeLimits.min > min || this.rangeLimits.max < max) {
      throw new Error(`Invalid range limits: ${min}-${max}`);
    }

    // generate random integer within the specified range
    const diff = max - min + 1;
    return Math.floor(Math.random() * diff) + min;
  }

