   * @param {number} min - minimum value of the range (inclusive)
   * @param {number} max - maximum value of the range (exclusive)
   * @param {number} precision - number of decimal places for floating-point values
   * @returns {number} a randomly generated float within the specified range with the specified precision
   */
  generateRandomFloat(min, max, precision) {
    // validate input range limits and precision
    if (!this.rangeLimits || this.rangeLimits.min > min || this.rangeLimits.max < max) {
      throw new Error(`Invalid range limits: ${min}-${max}`);
    }
    if (precision <= 0 || precision > 10) {
      throw new Error(`Invalid precision: ${precision}`);
    }

    // generate random float within the specified range with the specified precision
