function copyBytesAsync(buffer, start, end, callback) {
    // Asynchronous copying of a specified range of bytes from a list of potentially large, compressed buffered data chunks into a new buffer without decompressing the original data.
    if (end > buffer.length) {
        throw new Error("End index is out of bounds");
    }
    const newBuffer = Buffer.alloc(end - start);
    let offset = 0;
    for (let i = start; i < end; i += BUFFER_SIZE) {
        const sliceStart = i;
        const sliceEnd = Math.min(i + BUFFER_SIZE, buffer.length);
        buffer.copy(newBuffer, offset, sliceStart, sliceEnd);
        offset += sliceEnd - sliceStart;
    }
    callback(null, newBuffer);
}
