const { Client } = require('ssh2');
const { Pool } = require('pg');

class RemoteExecutor {
  constructor(config) {
    this.client = new Client();
    this.pool = new Pool({
      connectionString: process.env.DATABASE_URL,
    });
  }

  async executeRemoteCommand(config) {
    const {
      server, protocol, username, password, command, params,
    } = config;

    try {
      await this.client.connect();
      const result = await this.client.execCommand(`${command} ${params}`);
      await this.client.end();
      return result;
    } catch (err) {
      console.error(err);
      await this.client.end();
      throw err;
    }
  }

  async getRecentTransactions() {
    const transactions = [];
    const query = 'SELECT * FROM transactions ORDER BY timestamp DESC LIMIT 10';
    const result = await this.pool.query(query);
    for (const row of result.rows) {
      transactions.push({
        id: row.id,
        timestamp: new Date(row.timestamp),
        weightedValue: parseFloat(row.weighted_value),
      });
    }
    return transactions;
  }
}

module.exports = RemoteExecutor;
```
