import java.io.ObjectInputStream;
import java.io.IOException;

public static Object deserialize(byte[] bytes) throws DeserializationException {
    if (!isValidSerializedObject(bytes)) {
        throw new DeserializationException("Invalid serialized object");
    }

    try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(bytes))) {
        return ois.readObject();
    } catch (IOException | ClassNotFoundException e) {
        if (e instanceof EOFException) {
            throw new DeserializationException("Invalid serialized object", e);
        } else if (e instanceof VersionMismatchException) {
            throw new VersionMismatchException(e.getMessage(), e);
        } else if (e instanceof ClassNotFoundException) {
            throw new ClassNotFoundException(e.getMessage(), e);
        } else {
            throw new DeserializationException("Failed to deserialize object", e);
        }
    }
}

