import java.io.*;

public class DeserializationTest {
    @org.junit.jupiter.api.Test
    public void testValidSerializedObject() throws Exception {
        byte[] bytes = new byte[]{0, 1, 2, 3};
        Object object = deserialize(bytes);
        assertEquals("[C@4567", object.toString());
    }

    @org.junit.jupiter.api.Test
    public void testInvalidSerializedObject() {
        byte[] bytes = new byte[]{0, 1, 2};
        try {
            deserialize(bytes);
            fail("DeserializationException expected");
        } catch (DeserializationException e) {
            assertEquals("Invalid serialized object", e.getMessage());
        }
    }

    @org.junit.jupiter.api.Test
    public void testVersionMismatch() throws Exception {
        byte[] bytes = new byte[]{0, 1, 2, 3};
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            ois.readObject(); // read the object to cause a version mismatch
            fail("VersionMismatchException expected");
        } catch (VersionMismatchException e) {
            assertEquals("Object version mismatch", e.getMessage());
        }
    }

    @org.junit.jupiter.api.Test
    public void testClassNotFound() throws Exception {
        byte[] bytes = new byte[]{0, 1, 2, 3};
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            // cause a class not found exception by changing the object type
            ois.readObject();
            fail("ClassNotFoundException expected");
        } catch (ClassNotFoundException e) {
            assertEquals("Unknown class", e.getMessage());
        }
    }
}
