import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.stereotype.Service;

@Service
public class AutoscalingService {

    @Autowired
    private ThreadPoolExecutor executor;

    @Autowired
    private LockingMechanism lockingMechanism;

    public void scaleUp() {
        // Acquire the lock to prevent concurrent scaling operations
        lockingMechanism.acquireLock();
        try {
            // Increase the number of threads in the thread pool
            executor.setMaximumPoolSize(executor.getMaximumPoolSize() + 1);
        } finally {
            // Release the lock
            lockingMechanism.releaseLock();
        }
    }

    public void scaleDown() {
        // Acquire the lock to prevent concurrent scaling operations
        lockingMechanism.acquireLock();
        try {
            // Decrease the number of threads in the thread pool
            executor.setMaximumPoolSize(executor.getMaximumPoolSize() - 1);
        } finally {
            // Release the lock
            lockingMechanism.releaseLock();
        }
    }
}
