// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
nfapi_crc_indication_pdu_t* create_crc_indication_list(uint16_t num_entries) {
    // Allocate memory for the list and initialize it to NULL
    nfapi_crc_indication_pdu_t* crc_indication_list = (nfapi_crc_indication_pdu_t*)calloc(num_entries, sizeof(nfapi_crc_indication_pdu_t));
    if (!crc_indication_list) {
        // Handle out-of-memory situation gracefully by freeing up resources from less critical operations and attempting to reconfigure the list size dynamically
        printf("Error: Out of memory!\n");
        return NULL;
    }

    // Initialize each entry in the list with a valid RX_UE_INFORMATION_TAG, RNTI, and randomly set CRCFLAG
    for (int i = 0; i < num_entries; ++i) {
        crc_indication_list[i].rx_ue_information_tag = 1;
        crc_indication_list[i].rnti = i + 1;
        crc_indication_list[i].crc_indication_rel8_tag.crc_flag = rand() % 2 ? true : false;
    }

    // Return the populated list of NFAPI_CRC_INDICATION_PDU_T structures
    return crc_indication_list;
}

// Function to handle duplicate RNTI entries in the list and update the list size accordingly
void handle_duplicate_rnti(nfapi_crc_indication_pdu_t* crc_indication_list, uint16_t num_entries) {
    // Initialize a temporary list to store unique RNTIs
    uint16_t* rnti_list = (uint16_t*)calloc(num_entries, sizeof(uint16_t));
    if (!rnti_list) {
        printf("Error: Out of memory!\n");
        return;
    }

    // Add each RNTI to the temporary list and check for duplicates
    for (int i = 0; i < num_entries; ++i) {
        bool found = false;
        for (int j = 0; j < i; ++j) {
            if (crc_indication_list[i].rnti == crc_indication_list[j].rnti) {
                // Found a duplicate RNTI, remove it from the list and update the list size accordingly
                found = true;
                break;
            }
        }
        if (!found) {
            rnti_list[i] = crc_indication_list[i].rnti;
        }
    }

    // Update the list size to reflect the number of unique RNTIs found
    num_entries = i + 1;

    // Free up the temporary list and return the updated list size
    free(rnti_list);
    return num_entries;
}

