```
use std::env;
use reqwest::blocking::get;
use serde_json::Value;
use tokio::runtime::Runtime;

fn main() {
    let mut args = env::args();
    let location = args.nth(1).unwrap();
    let action = args.next().unwrap();

    // Set up rate limiting for API calls
    let mut runtime = Runtime::new().unwrap();
    let rate_limit = 5;
    let mut request_count = 0;

    loop {
        match action.as_str() {
            "temperature" => {
                // Retrieve the current temperature for a given location
                let response = get(&format!("https://api.openweathermap.org/data/2.5/weather?q={}&appid=YOUR_API_KEY", location)).await;
                if response.is_err() {
                    println!("Failed to fetch current temperature");
                    return;
                }
                let data = response.unwrap().json::<Value>().await;
                let temp = data["main"]["temp"].as_f64().unwrap();
                println!("Current temperature: {}", temp);
            },
            "forecast" => {
                // Fetch a 7-day weather forecast for a specified location
                let response = get(&format!("https://api.openweathermap.org/data/2.5/forecast?q={}&appid=YOUR_API_KEY", location)).await;
                if response.is_err() {
                    println!("Failed to fetch weather forecast");
                    return;
                }
                let data = response.unwrap().json::<Value>().await;
                for day in 0..7 {
                    let temp = data["list"][day]["main"]["temp"].as_f64().unwrap();
                    println!("Weather forecast for {}, day {}: {}", location, day + 1, temp);
                }
            },
            "alerts" => {
                // Check for severe weather alerts for a given location
                let response = get(&format!("https://api.openweathermap.org/data/2.5/alerts?q={}&appid=YOUR_API_KEY", location)).await;
                if response.is_err() {
                    println!("Failed to fetch weather alerts");
                    return;
                }
                let data = response.unwrap().json::<Value>().await;
                for alert in data["alerts"].as_array().unwrap() {
                    if alert["severity"] == "Severe" {
                        println!("Weather alert: {}", alert["description"].as_str().unwrap());
                    }
                }
            },
            _ => {
                // Invalid action specified
                println!("Invalid action specified");
            }
        }

        request_count += 1;
        if request_count >= rate_limit {
            runtime.sleep(std::time::Duration::from_secs(60)).await;
            request_count = 0;
        }
    }
}
```
