#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <md5sum.h>

int run_background_command(char* command, char* filepath) {
    int pid = fork();
    if (pid == 0) { // child process
        execl("/bin/bash", "bash", "-c", command, NULL);
    } else if (pid > 0) { // parent process
        wait(NULL);
        char* hash = md5sum_file(filepath);
        return strcmp(hash, "") == 0 ? 1 : 0;
    } else {
        perror("fork");
        return -1;
    }
}
