using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public class GameEventManager
{
    private readonly Dictionary<string, Server> _servers = new Dictionary<string, Server>();
    private readonly object _syncRoot = new object();
    private readonly ILogger _logger;

    public GameEventManager(ILogger logger)
    {
        _logger = logger;
    }

    public void AddServer(string name, string url)
    {
        lock (_syncRoot)
        {
            if (!_servers.ContainsKey(name))
            {
                _servers[name] = new Server(url);
            }
        }
    }

    public async Task<double> GenerateRandomValueAsync(string serverName, string eventType)
    {
        lock (_syncRoot)
        {
            if (!_servers.ContainsKey(serverName))
            {
                throw new ArgumentException("Server not found", nameof(serverName));
            }
        }

        var server = _servers[serverName];

        return await server.GenerateRandomValueAsync(eventType);
    }

    public async Task<bool> FetchConfigurationAsync()
    {
        lock (_syncRoot)
        {
            foreach (var server in _servers.Values)
            {
                if (!await server.FetchConfigurationAsync())
                {
                    return false;
                }
            }
        }

        return true;
    }

    public async Task<bool> FetchEncryptionKeysAsync()
    {
        lock (_syncRoot)
        {
            foreach (var server in _servers.Values)
            {
                if (!await server.FetchEncryptionKeysAsync())
                {
                    return false;
                }
            }
        }

        return true;
    }

    public async Task<string> EncryptDataAsync(string data)
    {
        lock (_syncRoot)
        {
            var primaryServer = _servers.Values.First();
            return await primaryServer.EncryptDataAsync(data);
        }
    }

    public async Task<string> DecryptDataAsync(string data)
    {
        lock (_syncRoot)
        {
            var primaryServer = _servers.Values.First();
            return await primaryServer.DecryptDataAsync(data);
        }
    }

    public void SetPrimaryServer(string serverName)
    {
        lock (_syncRoot)
        {
            if (!_servers.ContainsKey(serverName))
            {
                throw new ArgumentException("Server not found", nameof(serverName));
            }

            var primaryServer = _servers[serverName];
            foreach (var server in _servers.Values)
            {
                if (primaryServer != server)
                {
                    server.Disconnect();
                }
            }
        }
    }

    public void Dispose()
    {
        lock (_syncRoot)
        {
            foreach (var server in _servers.Values)
            {
                server.Disconnect();
            }
        }
    }
}

