const { promisify } = require('util');

// Create a new HTTP server and listen on port 3000
createServer((req, res) => {
  // Handle incoming requests
}).listen(3000);

// Promisify the exec function to make it async
const execAsync = promisify(exec);

// Define a function to execute commands on remote servers
async function executeCommandOnRemoteServer(server, command) {
  // Connect to the server using SSH or HTTP
  const client = connectToServer(server);

  // Execute the command and get the result
  const result = await execAsync(`${command}`, { cwd: '/path/to/working/dir' });

  // Close the connection to the server
  client.close();

  // Return the result
  return result;
}

// Define a function to execute commands on multiple remote servers
async function executeCommandOnMultipleServers(servers, command) {
  // Create a promise array for all servers
  const promises = servers.map((server) => executeCommandOnRemoteServer(server, command));

  // Await the results from all servers
  const results = await Promise.all(promises);

  // Return the combined results
  return results.join('\n');
}

// Define a function to handle incoming requests
async function handleRequest(req, res) {
  // Get the command and server from the request body
  const { command, server } = req.body;

  // Execute the command on the remote server
  const result = await executeCommandOnRemoteServer(server, command);

  // Send the result back to the client
  res.send(result);
}

// Listen for incoming requests on port 3000
createServer((req, res) => {
  handleRequest(req, res);
}).listen(3000);
```
