// Define a function to parse command-line arguments
void parse_args(int argc, char **argv) {
  // Initialize variables for parsing command-line options
  char c;
  int option_index = 0;
  char *option_string = NULL;
  static struct option long_options[] = {
    {"manpage", no_argument, NULL, OPT_MANPAGE},
    {"count-special", no_argument, NULL, OPT_COUNT_SPECIAL},
    {"output-file", required_argument, NULL, OPT_OUTPUT_FILE},
    {"log-file-path", required_argument, NULL, OPT_LOG_FILE_PATH},
    {NULL, 0, NULL, 0}
  };

  // Loop through command-line options and parse them
  while ((c = getopt_long(argc, argv, "o:l:", long_options, &option_index)) != -1) {
    switch (c) {
      case OPT_MANPAGE:
        printf("Usage: ./myprogram [OPTION]...\n");
        printf("\n");
        printf("  -o --output-file=FILE     Write output to FILE\n");
        printf("  -l --log-file-path=PATH   Log errors to PATH\n");
        break;
      case OPT_COUNT_SPECIAL:
        printf("Counting special characters is not supported yet.\n");
        exit(1);
        break;
      case OPT_OUTPUT_FILE:
        // Check if the output file exists and is writable
        if (access(optarg, W_OK) == -1) {
          printf("Error: Output file does not exist or is not writable\n");
          exit(1);
        }
        break;
      case OPT_LOG_FILE_PATH:
        // Check if the log file exists and is writable
        if (access(optarg, W_OK) == -1) {
          printf("Error: Log file does not exist or is not writable\n");
          exit(1);
        }
        break;
    }
  }
}

// Define a function to read a file line by line and count the number of lines
long int read_file(char *filename) {
  // Open the file in read-only mode
  int fd = open(filename, O_RDONLY);
  if (fd == -1) {
    printf("Error: Unable to open file %s\n", filename);
    exit(1);
  }

  // Initialize variables for reading the file
  char buffer[BUFSIZ];
  long int lines = 0;
  ssize_t num_read;

  // Read the file line by line and count the number of lines
  while ((num_read = read(fd, buffer, BUFSIZ)) > 0) {
    for (int i = 0; i < num_read; i++) {
      if (buffer[i] == '\n') {
        lines++;
      }
    }
  }

  // Close the file and return the number of lines
  close(fd);
  return lines;
}

// Define a function to validate the file format and content
void validate_file(char *filename) {
  // Open the file in read-only mode
  int fd = open(filename, O_RDONLY);
  if (fd == -1) {
    printf("Error: Unable to open file %s\n", filename);
    exit(1);
  }

  // Initialize variables for reading the file
  char buffer[BUFSIZ];
  ssize_t num_read;

  // Read the first line of the file and validate its format
  if ((num_read = read(fd, buffer, BUFSIZ)) > 0) {
    for (int i = 0; i < num_read; i++) {
      if (!isalnum(buffer[i])) {
        printf("Error: File format is not supported\n");
        exit(1);
      }
    }
  }

  // Close the file and return
  close(fd);
}

// Define a function to count special characters in a file
long int count_special_chars(char *filename) {
  // Open the file in read-only mode
  int fd = open(filename, O_RDONLY);
  if (fd == -1) {
    printf("Error: Unable to open file %s\n", filename);
    exit(1);
  }

  // Initialize variables for reading the file
  char buffer[BUFSIZ];
  long int special_chars = 0;
  ssize_t num_read;

  // Read the file line by line and count the number of special characters
  while ((num_read = read(fd, buffer, BUFSIZ)) > 0) {
    for (int i = 0; i < num_read; i++) {
      if (!isalnum(buffer[i])) {
        special_chars++;
      }
    }
  }

  // Close the file and return the number of special characters
  close(fd);
  return special_chars;
}

