using System;
using System.IO;
using System.Xml;
using System.Threading;
using System.Collections.Generic;

public class ConfigManager {
    private static readonly Dictionary<string, string> configs = new Dictionary<string, string>();
    private static readonly object lockObj = new object();

    public static void LoadConfig(string filePath) {
        XmlDocument doc = new XmlDocument();
        doc.Load(filePath);
        foreach (XmlNode node in doc.GetElementsByTagName("config")) {
            string key = node.Attributes["key"].Value;
            string value = node.Attributes["value"].Value;
            configs[key] = value;
        }
    }

    public static void UpdateConfig(string key, string value) {
        lock (lockObj) {
            if (configs.ContainsKey(key)) {
                configs[key] = value;
            } else {
                configs.Add(key, value);
            }
        }
    }

    public static string GetConfig(string key) {
        lock (lockObj) {
            return configs.ContainsKey(key) ? configs[key] : null;
        }
    }
}
```
This code creates a `ConfigManager` class that provides a static method for loading configuration settings from an external XML file, and another method for updating those configurations in real-time. The `configs` dictionary is used to store the loaded configuration settings, and a lock object is used to ensure thread-safe access to the dictionary.

The `LoadConfig` method takes a file path as input, loads the XML document at that location, and extracts the configuration settings from the document using the `GetElementsByTagName` method. The configuration settings are then added to the `configs` dictionary.

The `UpdateConfig` method updates the configuration setting for the specified key with the new value. If the key does not exist in the dictionary, a new entry is created.

The `GetConfig` method retrieves the configuration setting for the specified key from the dictionary. If the key does not exist in the dictionary, null is returned.

To ensure minimal impact on overall performance, the `configs` dictionary is accessed using a lock object to prevent concurrent access. This ensures that multiple threads attempting to read or write the configuration settings simultaneously will not interfere with each other.

