using System;
using System.Threading;

public class SecureRandomNumberGenerator
{
    private const int DefaultSeed = 1234567890;
    private static Random random = new Random(DefaultSeed);
    private static long seedValue = DefaultSeed;

    public float GenerateRandomFloat(float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax, RandomDistribution distribution)
    {
        // Validate input parameters
        if (minValue > maxValue || (inclusiveMin && inclusiveMax && minValue == maxValue))
            throw new ArgumentException("Invalid range");

        float randomFloat = 0;
        switch (distribution)
        {
            case RandomDistribution.Uniform:
                randomFloat = GenerateRandomUniform(minValue, maxValue, inclusiveMin, inclusiveMax);
                break;
            case RandomDistribution.Normal:
                randomFloat = GenerateRandomNormal(minValue, maxValue, inclusiveMin, inclusiveMax);
                break;
        }

        return randomFloat;
    }

    public int GenerateRandomInt(int minValue, int maxValue, bool inclusiveMin, bool inclusiveMax, RandomDistribution distribution)
    {
        // Validate input parameters
        if (minValue > maxValue || (inclusiveMin && inclusiveMax && minValue == maxValue))
            throw new ArgumentException("Invalid range");

        int randomInt = 0;
        switch (distribution)
        {
            case RandomDistribution.Uniform:
                randomInt = GenerateRandomUniform(minValue, maxValue, inclusiveMin, inclusiveMax);
                break;
            case RandomDistribution.Normal:
                randomInt = GenerateRandomNormal(minValue, maxValue, inclusiveMin, inclusiveMax);
                break;
        }

        return randomInt;
    }

    public float GenerateSeededRandomFloat(float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax, long seed, RandomDistribution distribution)
    {
        // Validate input parameters
        if (minValue > maxValue || (inclusiveMin && inclusiveMax && minValue == maxValue))
            throw new ArgumentException("Invalid range");
        if (seed < 0)
            throw new ArgumentException("Seed must be non-negative");

        float randomFloat = 0;
        using (var seededRandom = new Random(seed))
        {
            switch (distribution)
            {
                case RandomDistribution.Uniform:
                    randomFloat = GenerateSeededRandomUniform(minValue, maxValue, inclusiveMin, inclusiveMax, seededRandom);
                    break;
                case RandomDistribution.Normal:
                    randomFloat = GenerateSeededRandomNormal(minValue, maxValue, inclusiveMin, inclusiveMax, seededRandom);
                    break;
            }
        }

        return randomFloat;
    }

    public int GenerateSeededRandomInt(int minValue, int maxValue, bool inclusiveMin, bool inclusiveMax, long seed, RandomDistribution distribution)
    {
        // Validate input parameters
        if (minValue > maxValue || (inclusiveMin && inclusiveMax && minValue == maxValue))
            throw new ArgumentException("Invalid range");
        if (seed < 0)
            throw new ArgumentException("Seed must be non-negative");

        int randomInt = 0;
        using (var seededRandom = new Random(seed))
        {
            switch (distribution)
            {
                case RandomDistribution.Uniform:
                    randomInt = GenerateSeededRandomUniform(minValue, maxValue, inclusiveMin, inclusiveMax, seededRandom);
                    break;
                case RandomDistribution.Normal:
                    randomInt = GenerateSeededRandomNormal(minValue, maxValue, inclusiveMin, inclusiveMax, seededRandom);
                    break;
            }
        }

        return randomInt;
    }

    private float GenerateRandomUniform(float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax)
    {
        // Calculate the range of values
        float range = maxValue - minValue;
        if (inclusiveMin && inclusiveMax)
            range++;

        // Generate a random number within the range
        return (float)(minValue + random.NextDouble() * range);
    }

    private int GenerateRandomUniform(int minValue, int maxValue, bool inclusiveMin, bool inclusiveMax)
    {
        // Calculate the range of values
        int range = maxValue - minValue;
        if (inclusiveMin && inclusiveMax)
            range++;

        // Generate a random number within the range
        return minValue + random.Next(range);
    }

    private float GenerateSeededRandomUniform(float minValue, float maxValue, bool inclusiveMin, bool inclusiveMax, Random seededRandom)
    {
        // Calculate the range of values
        float range = maxValue - minValue;
        if (inclusiveMin && inclusiveMax)
            range++;

        // Generate a random number within the range
        return (float)(minValue + seededRandom.NextDouble() * range);
    }

    private int GenerateSeededRandomUniform(int minValue, int maxValue, bool inclusiveMin, bool inclusiveMax, Random seededRandom)
    {
        // Calculate the range of values
        int range = maxValue - minValue;
        if (inclusiveMin && inclusiveMax)
            range++;

        // Generate a random number within the range
        return minValue + seededRandom.Next(range);
    }

    private float GenerateRandomNormal(float mean, float standardDeviation, bool inclusiveMin, bool inclusiveMax)
    {
        // Calculate the range of values
        float range = (standardDeviation * 2) + (mean - minValue);
        if (inclusiveMin && inclusiveMax)
            range++;

        // Generate a random number within the range
        return mean + standardDeviation * (float)(random.NextGaussian());
    }

    private int GenerateRandomNormal(int mean, int standardDeviation, bool inclusiveMin, bool inclusiveMax)
    {
        // Calculate the range of values
        int range = (standardDeviation * 2) + (mean - minValue);
        if (inclusiveMin && inclusiveMax)
            range++;

        // Generate a random number within the range
        return mean + standardDeviation * (random.NextGaussian());
    }

    private float GenerateSeededRandomNormal(float mean, float standardDeviation, bool inclusiveMin, bool inclusiveMax, Random seededRandom)
    {
        // Calculate the range of values
        float range = (standardDeviation * 2) + (mean - minValue);
        if (inclusiveMin && inclusiveMax)
            range++;

        // Generate a random number within the range
        return mean + standardDeviation * (float)(seededRandom.NextGaussian());
    }

    private int GenerateSeededRandomNormal(int mean, int standardDeviation, bool inclusiveMin, bool inclusiveMax, Random seededRandom)
    {
        // Calculate the range of values
        int range = (standardDeviation * 2) + (mean - minValue);
        if (inclusiveMin && inclusiveMax)
            range++;

        // Generate a random number within the range
        return mean + standardDeviation * (seededRandom.NextGaussian());
    }
