<?php

function generateSecureRandomString($length = 10, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$%^&*()-=_+\|[]{}?:;<>~`') {
    // Validate input parameters
    if ($length < 8 || $length > 128) {
        throw new \InvalidArgumentException('Length must be between 8 and 128 characters');
    }
    if (strlen($charset) < 8 || !preg_match('/[a-zA-Z\d!@#$%^&*()-=_\|\\[\]{}:;<>~`]/', $charset)) {
        throw new \InvalidArgumentException('Charset must be at least 8 characters long and include uppercase letters, lowercase letters, digits, and special characters');
    }

    // Generate a random string using the specified charset
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset[mt_rand(0, strlen($charset) - 1)];
    }

    // Hash the generated random string using Bcrypt algorithm with cost factor of at least 12
    $hashedString = password_hash($randomString, PASSWORD_BCRYPT, ['cost' => 12]);

    // Validate the hashed string and return result
    if ($hashedString === false) {
        throw new \Exception('Failed to generate secure random string');
    }
    return $hashedString;
}
