import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ServiceManager {
    private static final Logger logger = Logger.getLogger(ServiceManager.class.getName());

    // Configuration parameters
    private int numInstances;
    private long startDelayRange;
    private String messagingSystem;

    // Service instances and their statuses
    private Map<String, ServiceInstance> serviceInstances = new HashMap<>();
    private Map<String, Boolean> instanceStatuses = new HashMap<>();

    public ServiceManager(int numInstances, long startDelayRange, String messagingSystem) {
        this.numInstances = numInstances;
        this.startDelayRange = startDelayRange;
        this.messagingSystem = messagingSystem;
    }

    // Start a service instance with a randomly chosen delay within the specified range
    public void startInstance(String instanceName) {
        if (!serviceInstances.containsKey(instanceName)) {
            ServiceInstance instance = new ServiceInstance(instanceName);
            instanceStatuses.put(instanceName, false);
            serviceInstances.put(instanceName, instance);
            logger.info("Starting " + instanceName + "...");
            instance.start();
        } else {
            logger.warning("Service " + instanceName + " already running.");
        }
    }

    // Stop a service instance with a randomly chosen delay within the specified range
    public void stopInstance(String instanceName) {
        if (serviceInstances.containsKey(instanceName)) {
            ServiceInstance instance = serviceInstances.get(instanceName);
            instanceStatuses.put(instanceName, true);
            logger.info("Stopping " + instanceName + "...");
            instance.stop();
        } else {
            logger.warning("Service " + instanceName + " not running.");
        }
    }

    // Return the status of a service instance
    public boolean isRunning(String instanceName) {
        return serviceInstances.containsKey(instanceName) && !instanceStatuses.get(instanceName);
    }

    // Handle service failures gracefully by logging and recovery
    private void handleServiceFailure(String instanceName, Exception e) {
        logger.log(Level.SEVERE, "Failed to start/stop service " + instanceName, e);
        recoverInstance(instanceName);
    }

    // Recover a failed service instance by restarting it
    private void recoverInstance(String instanceName) {
        ServiceInstance instance = new ServiceInstance(instanceName);
        instanceStatuses.put(instanceName, false);
        serviceInstances.put(instanceName, instance);
        logger.info("Recovering failed service " + instanceName + "...");
        instance.start();
    }

    // Implement logging for all operations, including errors
    private static class ServiceInstance {
        private String name;
        private long startTime;
        private long stopTime;
        private boolean running = false;

        public ServiceInstance(String name) {
            this.name = name;
        }

        public void start() {
            try {
                startTime = System.currentTimeMillis();
                running = true;
                logger.info("Started " + name);
            } catch (Exception e) {
                handleServiceFailure(name, e);
            }
        }

        public void stop() {
            try {
                if (running) {
                    stopTime = System.currentTimeMillis();
                    running = false;
                    logger.info("Stopped " + name);
                } else {
                    throw new RuntimeException("Service " + name + " not running.");
                }
            } catch (Exception e) {
                handleServiceFailure(name, e);
            }
        }
    }
}
