        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread\n");
            return -1;
        }
    }

    /* Clean up the thread pool */
    for (int i = 0; i < THREAD_POOL_SIZE; i++) {
        pthread_detach(threads[i]);
    }

    return 0;
}
