using System;
using System.Data;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class DatabaseManager
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<DatabaseManager> _logger;

    public DatabaseManager(HttpClient httpClient, ILogger<DatabaseManager> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public async Task<DataTableReader> EncodeAndSendToDatabaseAsync(byte[] data)
    {
        try
        {
            // Base64 encode the data
            string encodedData = Convert.ToBase64String(data);

            // Construct the request body with the encoded data
            var jsonBody = new { Data = encodedData };

            // Send the request to the REST API and await the response
            HttpResponseMessage response = await _httpClient.PostAsync("https://example.com/api/data", new StringContent(jsonBody, Encoding.UTF8, "application/json"));

            // Check for network errors and dispose of the response
            if (response.StatusCode == System.Net.HttpStatusCode.OK)
            {
                var streamReader = new StreamReader(await response.Content.ReadAsStreamAsync());
                string jsonResponse = await streamReader.ReadToEndAsync();

                // Deserialize the JSON response into a DataTableReader object
                DataTableReader reader = JsonConvert.DeserializeObject<DataTableReader>(jsonResponse);

                return reader;
            }
            else
            {
                _logger.LogError($"Failed to send data to database: {response.StatusCode}");
                return null;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to send data to database");
            return null;
        }
    }

    public byte[] DecryptWithAESCbc(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, PaddingMode padding = PaddingMode.PKCS7)
    {
        try
        {
            // Validate the input key and IV to prevent injection attacks
            if (encryptionKey == null || initializationVector == null)
                throw new ArgumentException("Invalid encryption key or initialization vector");

            using (AesCryptoServiceProvider aes = new AesCryptoServiceProvider())
            {
                // Set the algorithm mode to CBC and the padding mode to PKCS7
                aes.Mode = CipherMode.CBC;
                aes.Padding = padding;

                // Derive the encryption key from the password and salt using OpenSSL
                var derivedKey = new byte[aes.KeySize / 8];
                var derivedSalt = new byte[aes.BlockSize / 8];
                using (var deriveBytes = new PasswordDeriveBytes(encryptionKey, derivedSalt))
                {
                    aes.Key = derivedBytes.GetBytes(aes.KeySize / 8);
                    aes.IV = derivedBytes.GetBytes(aes.BlockSize / 8);
                }

                // Decrypt the ciphertext using AES-CBC
                ICryptoTransform decryptor = aes.CreateDecryptor();
                byte[] plaintext = decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);

                return plaintext;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to decrypt data with AES-CBC");
            throw new ArgumentException("Invalid encryption key or initialization vector");
        }
    }
}
