// Secure token generator using SHA-256 algorithm
fn secureTokenGenerator(username: &str, timestamp: u64, secret_key: &str) -> String {
    // Concatenate username, timestamp, and secret key
    let mut token = String::new();
    token.push_str(username);
    token.push_str(&timestamp.to_string());
    token.push_str(secret_key);

    // Hash the concatenated string using SHA-256 algorithm
    let hashed_token = sha2::Sha256::digest(&token.as_bytes());

    // Return the hashed token as a String
    return format!("{:x}", hashed_token);
}

