use std::env;
use std::fs::{create_dir_all, File};
use std::path::PathBuf;
use std::process::Command;

fn create_directory(name: &str, version: Option<u32>) -> Result<(), String> {
    // Validate input
    if name.is_empty() || !name.chars().all(|c| c.is_alphanumeric()) {
        return Err("Invalid directory name".to_string());
    }

    let mut path = PathBuf::from(env::var("APP_ROOT").unwrap());
    path.push(name);

    // Create directory with specified version number
    if let Some(version) = version {
        path.push(format!("v{}", version));
    }

    // Check file permissions and ensure only authorized users can create directories
    if !path.is_dir() || !path.has_permission(File::CREATE_ALL) {
        return Err("Invalid directory permissions".to_string());
    }

    // Create directory and set environment variable
    match create_dir_all(path.as_os_str()) {
        Ok(_) => {
            env::set_var("APP_DIR", path);
            Ok(())
        },
        Err(e) => Err(format!("Failed to create directory: {}", e)),
    }
}
