class NfaApiCrcIndicationPdu {
public:
    RxUeInformationTag rxUeInfo;
    CrcIndicationRel8Tag crcIndication;
};

class CrcIndicationManager {
private:
    std::mutex mtx;
    std::vector<NfaApiCrcIndicationPdu> pduList;
    std::unordered_map<int, size_t> rntiMap;

public:
    void add(const RxUeInformationTag& rxUeInfo, const CrcIndicationRel8Tag& crcIndication) {
        std::lock_guard<std::mutex> lock(mtx);
        pduList.push_back({rxUeInfo, crcIndication});
        rntiMap[rxUeInfo.getRnti()] = pduList.size() - 1;
    }

    void remove(int rnti) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end()) {
            // error handling for not found
        } else {
            pduList.erase(pduList.begin() + it->second);
            rntiMap.erase(it);
        }
    }

    void updateCrcFlag(int rnti, bool newCrcFlag) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end()) {
            // error handling for not found
        } else {
            pduList[it->second].crcIndication.setCrcFlag(newCrcFlag);
        }
    }
};
