// Generate a secure random string of a specified length using a given character set and return it along with a secure hash of a provided password.
function generateRandomString($length, $charset) {
    // Ensure the character set is at least 8 characters long and includes at least one uppercase letter, one lowercase letter, one digit, and one special character
    if (strlen($charset) < 8 || !preg_match("/[a-z]/", $charset) || !preg_match("/[A-Z]/", $charset) || !preg_match("/\d/", $charset) || !preg_match("/[$@#\*/+=-._!&^%{}()|~<>]/", $charset)) {
        return "Invalid character set";
    }

    // Generate a random string using the given character set
    $randomString = "";
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset{mt_rand(0, strlen($charset) - 1)};
    }

    // Hash the provided password using the BCRYPT algorithm with a cost factor of at least 12
    $hash = password_hash($password, PASSWORD_BCRYPT, ["cost" => 12]);

    // Return the generated random string and hashed password
    return array("randomString" => $randomString, "hash" => $hash);
}

// Validate the input password and character set to ensure the character set is at least 8 characters long and includes at least one uppercase letter, one lowercase letter, one digit, and one special character, and the password is at least 12 characters long and meets the same criteria.
function validateInput($password, $charset) {
    // Check if the character set is valid
    if (strlen($charset) < 8 || !preg_match("/[a-z]/", $charset) || !preg_match("/[A-Z]/", $charset) || !preg_match("/\d/", $charset) || !preg_match("/[$@#\*/+=-._!&^%{}()|~<>]/", $charset)) {
        return "Invalid character set";
    }

    // Check if the password is valid
    if (strlen($password) < 12 || !preg_match("/[a-z]/", $password) || !preg_match("/[A-Z]/", $password) || !preg_match("/\d/", $password) || !preg_match("/[$@#\*/+=-._!&^%{}()|~<>]/", $password)) {
        return "Invalid password";
    }

    // Return a successful validation message if the input is valid
    return "Valid input";
}

// Use the password_hash function with the PASSWORD_BCRYPT algorithm for hashing passwords, ensuring the hash is generated with a cost factor of at least 12.
function hashPassword($password) {
    $hash = password_hash($password, PASSWORD_BCRYPT, ["cost" => 12]);
    return $hash;
}

// Implement error handling to check if the generated random string and hashed password are valid and return appropriate error messages if not.
function handleError($error) {
    // Return a custom error message if an error occurs during validation or hashing
    if ($error == "Invalid character set" || $error == "Invalid password") {
        return "Failed to generate random string and hashed password";
    } else {
        return "Error: " . $error;
    }
}

// Optimize the function to generate the random string efficiently without compromising security.
function optimizeRandomString($length, $charset) {
    // Use a cache for frequently used character sets to improve performance for subsequent requests with the same set
    if (isset($_SESSION["cache"][$charset])) {
        return $_SESSION["cache"][$charset];
    } else {
        // Generate a random string using the given character set
        $randomString = "";
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $charset{mt_rand(0, strlen($charset) - 1)};
        }

        // Store the generated random string in the cache for future use
        $_SESSION["cache"][$charset] = $randomString;

        return $randomString;
    }
}

// Securely store the generated random string and hashed password in a database.
function secureStore($randomString, $hash) {
    // Connect to the database
    $conn = new mysqli("localhost", "username", "password", "database_name");
    if ($conn->connect_error) {
        die("Connection failed: " . $conn->connect_error);
    }

    // Insert the generated random string and hashed password into the database
    $sql = "INSERT INTO passwords (randomString, hash) VALUES (?, ?)";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("ss", $randomString, $hash);
    $stmt->execute();

    // Close the database connection
    $conn->close();
}

// Integrate with an external API to verify the strength of the generated password before hashing.
function integrateWithExternalApi($password) {
    // Use a third-party library or framework to make an HTTP request to the external API
    $response = file_get_contents("https://api.example.com/strength?password=" . $password);

    // Check if the response contains the expected data and return a successful message if it does, otherwise return an error message
    if ($response) {
        $data = json_decode($response);
        if ($data->isStrong) {
            return "Successfully integrated with external API";
        } else {
            return "Failed to integrate with external API";
        }
    } else {
        return "Error: Could not connect to external API";
    }
}

