```csharp
using System;
using System.Threading.Tasks;
using System.IO;
using Newtonsoft.Json;

public class DataLoader
{
    private readonly string _filePath;
    private readonly int _concurrentRequests;
    private readonly int _retryAttempts;
    private readonly TimeSpan _retryInterval;

    public DataLoader(string filePath, int concurrentRequests = 10, int retryAttempts = 5, TimeSpan retryInterval = TimeSpan.FromSeconds(30))
    {
        _filePath = filePath;
        _concurrentRequests = concurrentRequests;
        _retryAttempts = retryAttempts;
        _retryInterval = retryInterval;
    }

    public async Task<List<object>> LoadDataAsync()
    {
        var data = new List<object>();

        using (var stream = File.OpenRead(_filePath))
        {
            while (stream.Position < stream.Length)
            {
                var record = await DeserializeRecordAsync(stream);
                data.Add(record);
            }
        }

        return data;
    }

    private async Task<object> DeserializeRecordAsync(Stream stream)
    {
        try
        {
            using (var reader = new StreamReader(stream))
            {
                var json = await reader.ReadToEndAsync();
                return JsonConvert.DeserializeObject<object>(json);
            }
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to deserialize record", ex);
        }
    }
}
```
