from typing import List

def read_config_file(filename: str) -> List[str]:
    """Reads a configuration file and returns a list of lines sorted based on specific criteria."""
    try:
        with open(filename, "r") as f:
            lines = f.readlines()
            # Sort the lines by numerical value
            return sorted(lines, key=lambda x: int(x.strip()))
    except FileNotFoundError:
        print(f"File {filename} not found.")
        return []
    except ValueError:
        print("Invalid data in configuration file.")
        return []
