    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }
    free(threads);

    int totalRequests = 0, averageResponseTime = 0, errorRate = 0;
    for (int i = 0; i < argc - 1; ++i) {
        totalRequests += requests[i];
        averageResponseTime += responseTimes[i];
        errorRate += errorRates[i];
    }
    averageResponseTime /= totalRequests;
    errorRate /= totalRequests;

    // Log any errors and debugging purposes if logging is enabled
    if (loggingEnabled) {
        FILE* logFile = fopen(logFilePath, "a");
        if (logFile == NULL) {
            perror("Error opening log file for writing");
            return 1;
        }
        fprintf(logFile, "Total requests: %d\n", totalRequests);
        fprintf(logFile, "Average response time: %f\n", averageResponseTime);
        fprintf(logFile, "Error rate: %f%%\n", errorRate * 100);
    }

    // Clean up any resources and return a success code
    for (int i = 0; i < argc - 1; ++i) {
        munmap(logFilePaths[i], sizeof(char*) * (argc - 1));
    }
    free(logFilePaths);
    return 0;
