// Define the function to process a single log file concurrently
static void* processLogFile(void* arg) {
    char* logFilePath = (char*)arg;
    int fd = open(logFilePath, O_RDONLY);
    if (fd == -1) {
        perror("Error opening log file");
        return NULL;
    }
    struct stat sb;
    fstat(fd, &sb);
    void* mmap = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (mmap == MAP_FAILED) {
        perror("Error mapping log file");
        return NULL;
    }
    close(fd);

    // Parse the log file line by line and filter relevant entries
    char* line = mmap;
    while (line < mmap + sb.st_size) {
        if (*line == '#') {
            line++;
            continue;
        }
        char* requestType = strstr(line, "REQUEST_TYPE:");
        char* responseTime = strstr(line, "RESPONSE_TIME:");
        char* errorCode = strstr(line, "ERROR_CODE:");
        if (requestType && responseTime && errorCode) {
            // Calculate the key metrics for this log entry and update the global variables
            int requestType = atoi(requestType + 12);
            double responseTime = atof(responseTime + 13);
            double errorCode = atof(errorCode + 12);
            if (requestType == 1) {
                requests++;
            } else if (requestType == 2) {
                responses++;
            } else {
                errors++;
            }
            responseTimes += responseTime;
            errorRates += errorCode;
        }
    }

    // Clean up any resources and return a success code
    munmap(mmap, sb.st_size);
    close(fd);
    return NULL;
}
