import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.logging.Logger;

public class DisjointPairs {
    private static final Logger LOGGER = Logger.getLogger(DisjointPairs.class.getName());

    public static int findDisjointPairs(int[] inputArray) {
        if (inputArray == null || inputArray.length == 0) {
            return 0;
        }

        long startTime = System.currentTimeMillis();

        Set<Integer> unionFind = new HashSet<>();

        for (int i = 0; i < inputArray.length; i++) {
            int element = inputArray[i];
            if (unionFind.contains(element)) {
                LOGGER.info("Disjoint pair found between " + element + " and another element in the set.");
                continue;
            }
            for (int j = i + 1; j < inputArray.length; j++) {
                int otherElement = inputArray[j];
                if (!unionFind.contains(otherElement)) {
                    unionFind.add(element);
                    unionFind.add(otherElement);
                    LOGGER.info("Disjoint pair found between " + element + " and " + otherElement);
                }
            }
        }

        long endTime = System.currentTimeMillis();
        long processingTime = endTime - startTime;
        LOGGER.info("Processing time: " + processingTime + " milliseconds.");

        return unionFind.size();
    }
}
