using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.IO;
using System.Net;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace SessionTokenService
{
    public class Program
    {
        private static Dictionary<string, string> sessionTokens = new Dictionary<string, string>();

        public static void Main(string[] args)
        {
            Console.WriteLine("Session Token Service Started");

            while (true)
            {
                try
                {
                    var request = HttpListener.GetContext();
                    var response = request.Response;

                    if (request.HttpMethod == "POST")
                    {
                        // Process POST request
                        var requestBody = new StreamReader(request.InputStream).ReadToEnd();
                        dynamic jsonRequest = JObject.Parse(requestBody);

                        string userId = jsonRequest.userId;
                        int timestamp = jsonRequest.timestamp;
                        string salt = jsonRequest.salt;

                        var sessionToken = GenerateSessionToken(userId, timestamp, salt);
                        response.StatusCode = 201;
                        response.Headers.Add("Content-Type", "application/json");
                        response.Write("{\"sessionToken\": \"" + sessionToken + "\"}");
                    }
                    else if (request.HttpMethod == "GET")
                    {
                        // Process GET request
                        string sessionToken = request.QueryString["sessionToken"];

                        var isValidSessionToken = IsValidSessionToken(sessionToken);
                        response.StatusCode = 200;
                        response.Headers.Add("Content-Type", "application/json");
                        response.Write("{\"isValidSessionToken\": \"" + isValidSessionToken + "\"}");
                    }
                    else
                    {
                        // Unsupported HTTP method, return 405
                        response.StatusCode = 405;
                        response.Headers.Add("Allow", "GET, POST");
                        response.Write("Method Not Allowed");
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine("Error: " + ex.Message);
                }
            }
        }

        private static string GenerateSessionToken(string userId, int timestamp, string salt)
        {
            var sessionToken = new StringBuilder();
            sessionToken.Append(userId);
            sessionToken.Append(":");
            sessionToken.Append(timestamp);
            sessionToken.Append(":");
            sessionToken.Append(salt);

            using (var hash = SHA256.Create())
            {
                byte[] hashBytes = hash.ComputeHash(Encoding.UTF8.GetBytes(sessionToken.ToString()));
                return Convert.ToBase64String(hashBytes);
            }
        }

        private static bool IsValidSessionToken(string sessionToken)
        {
            var isValid = false;

            if (sessionTokens.ContainsKey(sessionToken))
            {
                isValid = true;
            }
            else
            {
                try
                {
                    // Call external authentication service to verify session token
                    var request = WebRequest.CreateHttp("https://external-auth-service/verify-session-token");
                    request.Method = "POST";
                    request.ContentType = "application/json";
                    using (var stream = request.GetRequestStream())
                    {
                        var json = JsonConvert.SerializeObject(new { sessionToken });
                        byte[] bytes = Encoding.UTF8.GetBytes(json);
                        stream.Write(bytes, 0, bytes.Length);
                    }

                    var response = (HttpWebResponse)request.GetResponse();
                    using (var stream = response.GetResponseStream())
                    {
                        if (stream != null)
                        {
                            var reader = new StreamReader(stream);
                            var jsonResponse = reader.ReadToEnd();
                            dynamic jsonResult = JObject.Parse(jsonResponse);
                            isValid = jsonResult.valid;
                        }
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine("Error: " + ex.Message);
                }
            }

            return isValid;
        }
    }
}
