from datetime import datetime
from urllib.parse import quote
from typing import Dict, List

class StockPriceAggregator:
    def __init__(self):
        self.apis = ["Alpha Vantage", "Yahoo Finance", "Google Finance"]
        self.cached_stocks = {}  # { stock symbol: { timestamp: price, ... } }
        self.cache_eviction_policy = "LRU"  # Least Recently Used
        self.cache_size = 10000
        self.monitoring_thresholds = {
            "api_call_frequency": 50,
            "cache_hit_rate": 90,
            "validation_errors": 10,
            "error_logs": 10
        }

    def get_stock_price(self, stock: str, timestamp: datetime) -> float:
        # Check if the stock is in the cache and return it if it's available.
        if stock in self.cached_stocks and timestamp in self.cached_stocks[stock]:
            print("Cache hit!")
            return self.cached_stocks[stock][timestamp]

        # If not, fetch the data from the most reliable API available at the time of request.
        for api in self.apis:
            try:
                url = f"https://{api}.com/api/v2/quote?symbol={quote(stock)}&timestamp={timestamp}"
                response = requests.get(url)
                if response.status_code == 200:
                    data = json.loads(response.text)
                    price = float(data["price"])
                    self.cached_stocks[stock] = {timestamp: price}
                    print("Fetched from API:", api)
                    return price
            except Exception as e:
                print("Error fetching stock price from API:", api, e)

        # If all APIs fail, use historical data stored in the database.
        try:
            query = "SELECT * FROM stocks WHERE symbol = %s AND timestamp < %s ORDER BY timestamp DESC LIMIT 1"
            cursor.execute(query, (stock, timestamp))
            result = cursor.fetchone()
            if result is not None:
                print("Fetched from database.")
                return float(result["price"])
        except Exception as e:
            print("Error fetching historical stock price data:", e)

        # If all else fails, use a fallback price.
        print("Using fallback price.")
        return 0.0

    def validate_stock_data(self, stock: str, timestamp: datetime, price: float) -> bool:
        # Check if the data is consistent across different providers.
        for api in self.apis:
            try:
                url = f"https://{api}.com/api/v2/quote?symbol={quote(stock)}&timestamp={timestamp}"
                response = requests.get(url)
                if response.status_code == 200:
                    data = json.loads(response.text)
                    price_api = float(data["price"])
                    if abs(price - price_api) > 1e-5:
                        print("Validation error!")
                        return False
            except Exception as e:
                print("Error validating stock data from API:", api, e)

        # If all APIs validate the data successfully, return True.
        return True

    def handle_concurrent_requests(self, requests: List[Dict]):
        # Handle multiple concurrent requests by processing them one by one and using a lock to prevent race conditions.
        for request in requests:
            stock = request["stock"]
            timestamp = request["timestamp"]
            price = self.get_stock_price(stock, timestamp)
            if not self.validate_stock_data(stock, timestamp, price):
                print("Validation error!")
                continue
            yield {
                "status": 200,
                "stock": stock,
                "timestamp": timestamp,
                "price": price
            }

    def cache_eviction_policy(self, key: str):
        # Implement the Least Recently Used (LRU) caching policy.
        self.cached_stocks[key] = self.cached_stocks[key][1:]  # remove oldest entry
        if len(self.cached_stocks[key]) == self.cache_size:
            del self.cached_stocks[key]

    def monitor_api_usage(self):
        # Monitor API call frequencies, cache hit rates, validation errors, and error logs.
        pass

    def send_notification(self, stock: str, threshold: float):
        # Send a notification via email or SMS when the stock price reaches a certain threshold.
