import json
import logging
import requests

class GameSettings:
    def __init__(self, url):
        self.url = url
        self.cache = {}

    def get_settings(self):
        try:
            response = requests.get(self.url)
            if response.status_code == 200:
                self.cache = json.loads(response.content)
                return self.cache
            else:
                logging.error("Failed to fetch game settings")
        except Exception as e:
            logging.exception(e)
        return {}

    def put_settings(self, data):
        try:
            response = requests.put(self.url, json=data)
            if response.status_code == 204:
                self.cache = data
                logging.info("Successfully updated game settings")
                return True
            else:
                logging.error("Failed to update game settings")
        except Exception as e:
            logging.exception(e)
        return False

    def delete_resource(self, id):
        try:
            response = requests.delete(f"{self.url}/{id}")
            if response.status_code == 204:
                self.cache = None
                logging.info("Successfully deleted resource")
                return True
            else:
                logging.error("Failed to delete resource")
        except Exception as e:
            logging.exception(e)
        return False

    def create_resource(self, data):
        try:
            response = requests.post(f"{self.url}/", json=data)
            if response.status_code == 201:
                self.cache = None
                logging.info("Successfully created resource")
                return True
            else:
                logging.error("Failed to create resource")
        except Exception as e:
            logging.exception(e)
        return False

    def render_scripts(self):
        scripts = []
        for script in self.cache["scripts"]:
            if script["type"] == "text/javascript" or script["type"] == "module":
                scripts.append(f'<script src="{script["src"]}" type="{script["type"]}"></script>')
        return "\n".join(scripts)
