Here is a sample Python-based continuous deployment pipeline for a microservices architecture:
```python
import os
from datetime import datetime
from typing import List, Dict

# Import Kubernetes client library
from kubernetes import client

# Import Docker client library
from docker import client as docker_client

# Define the list of services to be deployed
SERVICES = [
    {
        "name": "service1",
        "image": "private-registry/service1:latest",
        "configuration": {
            "key1": "value1"
        }
    },
    {
        "name": "service2",
        "image": "private-registry/service2:latest",
        "configuration": {
            "key2": "value2"
        }
    }
]

# Define the Kubernetes deployment configuration
KUBERNETES_CONFIG = {
    "namespace": "microservices",
    "cluster": "k8s-cluster"
}

def deploy_service(service: Dict, registry_url: str) -> None:
    """Deploy a service to Kubernetes."""
    # Get the Docker image for the service from the registry
    docker_image = get_docker_image(registry_url, service["image"])

    # Build the Docker container using the specified image and configuration
    container = build_container(docker_image, service["configuration"])

    # Deploy the container to Kubernetes
    deploy_kubernetes_service(container)

def get_docker_image(registry_url: str, image_name: str) -> Dict[str]:
    """Get a Docker image from a private registry."""
    # Connect to the registry using the provided URL and credentials
    with docker_client.from_env() as client:
        try:
            return client.images.get(registry_url + "/" + image_name)
        except ImageNotFoundError:
            print("Image not found in registry")
            return None

def build_container(docker_image: Dict[str], configuration: Dict[str]) -> Dict[str]:
    """Build a Docker container using the specified image and configuration."""
    # Create a new container using the provided image
    container = docker_client.containers.run(docker_image, detach=True)

    # Configure the container using the provided configuration
    for key, value in configuration.items():
        container.environment[key] = str(value)

    return container

def deploy_kubernetes_service(container: Dict[str]) -> None:
    """Deploy a Docker container to Kubernetes."""
    # Create a new Kubernetes deployment using the provided container
    deployment = client.AppsV1Api().create_namespaced_deployment(
        body=client.V1Deployment(
            metadata=client.V1ObjectMeta(name="microservices-deployment"),
            spec=client.V1DeploymentSpec(
                selector=client.V1LabelSelector(match_labels={"app": "microservices"}),
                template=client.V1PodTemplateSpec(
                    metadata=client.V1ObjectMeta(labels={"app": "microservices"}),
                    spec=client.V1PodSpec(containers=[container])
                )
            )
        ),
        namespace=KUBERNETES_CONFIG["namespace"]
    )

def configure_kubernetes_resource(resource: Dict[str], configuration: Dict[str]) -> None:
    """Configure a Kubernetes resource using the provided configuration."""
    # Update the resource with the specified configuration
    for key, value in configuration.items():
        resource[key] = str(value)

def handle_service_deployment(service: Dict[str], registry_url: str) -> None:
    """Handle a deployment of a service to Kubernetes."""
    # Deploy the service using the specified configuration and registry URL
    deploy_service(service, registry_url)

def handle_service_configuration(service: Dict[str], configuration: Dict[str]) -> None:
    """Handle a configuration change for a deployed service."""
    # Get the Kubernetes deployment for the specified service
    deployment = client.AppsV1Api().read_namespaced_deployment(
        name=service["name"],
        namespace=KUBERNETES_CONFIG["namespace"]
    )

    # Configure the deployment using the provided configuration
    configure_kubernetes_resource(deployment, configuration)

def handle_service_removal(service: Dict[str]) -> None:
    """Handle a removal of a deployed service."""
    # Delete the Kubernetes deployment for the specified service
    client.AppsV1Api().delete_namespaced_deployment(
        name=service["name"],
        namespace=KUBERNETES_CONFIG["namespace"]
    )

def handle_configuration_update(services: List[Dict[str]], configuration: Dict[str]) -> None:
    """Handle an update to the global configuration."""
    # Update the Kubernetes deployment for each service using the provided configuration
    for service in services:
        configure_kubernetes_resource(service, configuration)

def handle_deployment_request(services: List[Dict[str]]) -> None:
    """Handle a request to deploy the specified services."""
    # Deploy each service using the provided configuration
    for service in services:
        handle_service_deployment(service, "private-registry")

def handle_configuration_request(services: List[Dict[str]], configuration: Dict[str]) -> None:
    """Handle a request to update the global configuration."""
    # Update the Kubernetes deployment for each service using the provided configuration
    for service in services:
        handle_service_configuration(service, configuration)

def handle_removal_request(services: List[Dict[str]]) -> None:
    """Handle a request to remove the specified services."""
    # Remove each service from Kubernetes using the provided configuration
    for service in services:
        handle_service_removal(service)

def main():
    # Handle incoming requests and deployments of services
    while True:
        # Get the next request from the queue
        request = receive_request()

        if request["action"] == "deployment":
            # Deploy the specified services using the provided configuration
            handle_deployment_request(request["services"])
        elif request["action"] == "configuration":
            # Update the global configuration for each service
            handle_configuration_request(request["services"], request["configuration"])
        elif request["action"] == "removal":
            # Remove the specified services from Kubernetes
            handle_removal_request(request["services"])

if __name__ == "__main__":
    main()
```

This script will receive requests from the deployment pipeline and perform the necessary actions to deploy, update, or remove a service. It will also configure the environment for each service using the provided configuration. The script will use the `docker` and `kubernetes` python libraries to interact with Docker and Kubernetes, respectively.

