            name: String::from(name),
            value: String::from(value),
        }
    }
}

struct IRBuilder {
    nodes: Vec<Node>,
    optimization_level: OptimizationLevel,
    target_architecture: TargetArchitecture,
}

impl IRBuilder {
    fn new(optimization_level: OptimizationLevel, target_architecture: TargetArchitecture) -> Self {
        Self {
            nodes: Vec::new(),
            optimization_level,
            target_architecture,
        }
    }

    fn build(&self) -> Result<Vec<String>, Error> {
        // Implement LLVM IR generation logic here
    }
}

fn generate_llvm_ir(file_path: &str) -> Result<Vec<String>, Error> {
    let grammar = get_grammar(file_path)?;
    let file_ext = Path::new(file_path).extension().unwrap();
    let lexer = Lexer::new(file_path);
    let parser = Parser::new(&lexer, &grammar);
    let mut nodes = Vec::new();
    for node in parser.parse()? {
        nodes.push(node);
    }
    let ir_builder = IRBuilder::new(OptimizationLevel::default(), TargetArchitecture::default());
    for node in nodes {
        ir_builder.nodes.push(node);
    }
    Ok(ir_builder.build()?)
}

fn get_grammar(file_path: &str) -> Result<Grammar, Error> {
    let file_ext = Path::new(file_path).extension().unwrap();
    let grammar = match file_ext.to_string_lossy().as_ref() {
        "c" => Grammar { name: String::from("C"), file_ext: String::from("c") },
        "cpp" => Grammar { name: String::from("C++"), file_ext: String::from("cpp") },
        _ => Err(Error::new(format!("Unsupported file extension: {}", file_ext)))?
    };
    Ok(grammar)
}
