// Logging levels
#define LOG_LEVEL_ERROR   0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_INFO    2

// Configuration settings
#define MAX_LOG_MESSAGE_LENGTH  4096
#define LOGGING_BUFFER_SIZE     8192
#define BUFFER_FLUSH_INTERVAL   5 // seconds

static FILE *log_file = NULL;
static int log_level = LOG_LEVEL_INFO;
static char logging_buffer[LOGGING_BUFFER_SIZE];

// Logs a message to the error log file based on the specified conditions and logging levels.
void logError(const char *fmt, ...) {
    va_list args;
    int n;

    // Open the log file in append mode if necessary
    if (log_file == NULL) {
        log_file = fopen("error.log", "a");
        if (log_file == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
    }

    // Format the message using va_start and va_end
    va_start(args, fmt);
    n = vsnprintf(logging_buffer, sizeof(logging_buffer), fmt, args);
    if (n < 0 || n >= LOGGING_BUFFER_SIZE) {
        perror("vsnprintf");
        exit(EXIT_FAILURE);
    }
    va_end(args);

    // Determine the appropriate log level and format the message accordingly
    if (log_level >= LOG_LEVEL_ERROR) {
        fprintf(stderr, "%s", logging_buffer);
    } else {
        fprintf(stdout, "%s", logging_buffer);
    }

    // Close the log file after each write operation to avoid memory leaks
    if (fclose(log_file) == EOF) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }
}
