class FileMetadataUpdater:
    def __init__(self, api_url, thread_pool_size=500):
        self.api_url = api_url
        self.thread_pool = ThreadPoolExecutor(max_workers=thread_pool_size)

    def update_file_metadata(self, file_id, metadata_dict):
        # Validate input parameters
        if not isinstance(file_id, str) or not isinstance(metadata_dict, dict):
            raise ValueError("Invalid input parameters")

        # Create a thread for each metadata update
        threads = []
        for field, value in metadata_dict.items():
            threads.append(self.thread_pool.submit(self._update_file_metadata, file_id, field, value))

        # Wait for all threads to complete
        results = [thread.result() for thread in threads]

        # Check for any errors during metadata updates
        if any(result is not None for result in results):
            raise RuntimeError("Failed to update file metadata")

    def _update_file_metadata(self, file_id, field, value):
        # Build the API request data
        data = {
            "file_id": file_id,
            "field": field,
            "value": value
        }

        # Make the API call to update the metadata
        try:
            response = requests.put(f"{self.api_url}/update_metadata", data=data)
            if response.status_code != 200:
                raise RuntimeError("Failed to update file metadata")
        except RequestException as e:
            return "Failed to connect to API: {}".format(e)

    def shutdown(self):
        self.thread_pool.shutdown()
