        self.file_updater.shutdown()

    def test_update_metadata(self):
        # Update metadata for the file
        self.file_updater.update_file_metadata(self.file_id, self.metadata_dict)

        # Check that the metadata was updated successfully
        response = requests.get(f"{self.api_url}/get_metadata/{self.file_id}")
        self.assertEqual(response.status_code, 200)
        self.assertDictEqual(response.json(), self.metadata_dict)

    def test_concurrent_updates(self):
        # Update metadata for multiple files simultaneously
        threads = []
        for i in range(5):
            threads.append(Thread(target=self.file_updater.update_file_metadata, args=(f"{self.file_id}{i}", self.metadata_dict)))

        # Wait for all threads to complete
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

        # Check that the metadata was updated successfully for all files
        response = requests.get(f"{self.api_url}/get_metadata/{self.file_id}0")
        self.assertEqual(response.status_code, 200)
        self.assertDictEqual(response.json(), self.metadata_dict)

    def test_large_scale_updates(self):
        # Update metadata for a large number of files
        file_ids = [f"{self.file_id}{i}" for i in range(100)]
        threads = []
        for file_id in file_ids:
            threads.append(Thread(target=self.file_updater.update_file_metadata, args=(file_id, self.metadata_dict)))

        # Wait for all threads to complete
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

        # Check that the metadata was updated successfully for all files
        for file_id in file_ids:
            response = requests.get(f"{self.api_url}/get_metadata/{file_id}")
            self.assertEqual(response.status_code, 200)
            self.assertDictEqual(response.json(), self.metadata_dict)

    def test_failover_mechanism(self):
        # Simulate a temporary disconnection from the API
        self.file_updater.api_url = "http://example.com/api"

        # Update metadata for the file
        try:
            self.file_updater.update_file_metadata(self.file_id, self.metadata_dict)
        except RequestException as e:
            print("Failed to connect to API: {}".format(e))

        # Check that the metadata was updated successfully after failover
        response = requests.get(f"{self.api_url}/get_metadata/{self.file_id}")
        self.assertEqual(response.status_code, 200)
        self.assertDictEqual(response.json(), self.metadata_dict)
