using System;
using System.Threading;
using System.Collections.Generic;

namespace FilterTransactions
{
    public class TransactionFilter
    {
        private const int MAX_TRANSACTIONS = 1000;
        private readonly List<Transaction> _transactions = new List<Transaction>();
        private readonly object _lock = new object();

        public void AddTransaction(int id, float weight)
        {
            lock (_lock)
            {
                if (_transactions.Count >= MAX_TRANSACTIONS)
                {
                    RemoveOldestTransaction();
                }
                var transaction = new Transaction(id, weight);
                _transactions.Add(transaction);
            }
        }

        public void UpdateMetrics()
        {
            lock (_lock)
            {
                foreach (var transaction in _transactions)
                {
                    transaction.Update();
                }
            }
        }

        public int GetMaxWeightedSum()
        {
            var maxWeight = 0;
            lock (_lock)
            {
                foreach (var transaction in _transactions)
                {
                    if (transaction.Weight > maxWeight)
                    {
                        maxWeight = transaction.Weight;
                    }
                }
            }
            return maxWeight;
        }

        public int GetOldestTransactionId()
        {
            var oldestId = -1;
            lock (_lock)
            {
                foreach (var transaction in _transactions)
                {
                    if (transaction.Id < oldestId || oldestId == -1)
                    {
                        oldestId = transaction.Id;
                    }
                }
            }
            return oldestId;
        }

        private void RemoveOldestTransaction()
        {
            lock (_lock)
            {
                var oldestIndex = _transactions.FindIndex(transaction => transaction.Id == GetOldestTransactionId());
                if (oldestIndex != -1)
                {
                    _transactions.RemoveAt(oldestIndex);
                }
            }
        }

        public class Transaction
        {
            public int Id { get; set; }
            public float Weight { get; set; }
            private int _age = 0;
            private int _recentTransactionsCount = 0;

            public Transaction(int id, float weight)
            {
                Id = id;
                Weight = weight;
            }

            public void Update()
            {
                _age++;
                if (_age > 10)
                {
                    _recentTransactionsCount++;
                    _age = 0;
                }
            }
        }
    }
}
