using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;

namespace CryptographicOperations
{
    public class CryptoOperation
    {
        private const int BUFFER_SIZE = 1024;
        private readonly FileStream _fileStream;
        private readonly Encoding _encoding;
        private readonly OpenSslCipher _cipher;
        private readonly object _lock = new object();

        public CryptoOperation(string filePath, string mode)
        {
            if (mode == "encrypt")
            {
                _fileStream = new FileStream(filePath, FileMode.Create);
                _encoding = Encoding.UTF8;
                _cipher = OpenSslCipher.Encryption();
            }
            else if (mode == "decrypt")
            {
                _fileStream = new FileStream(filePath, FileMode.Open);
                _encoding = Encoding.UTF8;
                _cipher = OpenSslCipher.Decryption();
            }
        }

        public void RunOperation()
        {
            lock (_lock)
            {
                using (var buffer = new byte[BUFFER_SIZE])
                {
                    while (true)
                    {
                        var bytesRead = _fileStream.Read(buffer, 0, BUFFER_SIZE);
                        if (bytesRead == 0)
                        {
                            break;
                        }
                        using (var ciphertext = new MemoryStream())
                        {
                            using (var cryptoTransform = _cipher.CreateDecryptor())
                            {
                                var outputBuffer = cryptoTransform.TransformFinalBlock(buffer, 0, bytesRead);
                                ciphertext.Write(outputBuffer, 0, outputBuffer.Length);
                            }
                            using (var reader = new StreamReader(_fileStream))
                            {
                                var plaintext = _encoding.GetString(ciphertext.ToArray());
                                Console.WriteLine(plaintext);
                            }
                        }
                    }
                }
            }
        }

        public void Dispose()
        {
            lock (_lock)
            {
                _fileStream.Dispose();
            }
        }
    }
}
