```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace DatabaseOperations
{
    public class Program
    {
        private static readonly string ConnectionString = "Server=localhost\\SQLEXPRESS;Database=MyDb;Trusted_Connection=True";
        private static readonly ILogger<Program> Logger = LogManager.GetLogger<Program>();

        public static async Task Main(string[] args)
        {
            if (args.Length < 1)
            {
                Console.WriteLine("Usage: DatabaseOperations [operation]");
                return;
            }

            string operation = args[0];
            switch (operation)
            {
                case "select":
                    await ExecuteSelectQuery(args);
                    break;
                case "insert":
                    await ExecuteInsertQuery(args);
                    break;
                default:
                    Console.WriteLine("Unsupported operation");
                    return;
            }
        }

        private static async Task ExecuteSelectQuery(string[] args)
        {
            if (args.Length < 2)
            {
                Console.WriteLine("Usage: DatabaseOperations select [query]");
                return;
            }

            string query = args[1];
            using (var connection = new SqlConnection(ConnectionString))
            {
                try
                {
                    await connection.OpenAsync();
                }
                catch (SqlException ex)
                {
                    Logger.LogError(ex, "Failed to open connection");
                    return;
                }

                using (var command = new SqlCommand(query, connection))
                {
                    try
                    {
                        var reader = await command.ExecuteReaderAsync();
                        while (await reader.ReadAsync())
                        {
                            Console.WriteLine($"{reader["Name"]} - {reader["Age"]}");
                        }
                    }
                    catch (SqlException ex)
                    {
                        Logger.LogError(ex, "Failed to execute query");
                        return;
                    }
                }
            }
        }

        private static async Task ExecuteInsertQuery(string[] args)
        {
            if (args.Length < 3)
            {
                Console.WriteLine("Usage: DatabaseOperations insert [table] [column1] [value1] ...");
                return;
            }

            string table = args[1];
            string[] columnValues = new string[args.Length - 2];
            for (int i = 0; i < columnValues.Length; i++)
            {
                columnValues[i] = $"@{i + 2}";
            }

            using (var connection = new SqlConnection(ConnectionString))
            {
                try
                {
                    await connection.OpenAsync();
                }
                catch (SqlException ex)
                {
                    Logger.LogError(ex, "Failed to open connection");
                    return;
                }

                using (var command = new SqlCommand($"INSERT INTO {table} ({string.Join(", ", columnValues)}) VALUES ({string.Join(", ", args.Skip(2))})", connection))
                {
                    try
                    {
                        await command.ExecuteNonQueryAsync();
                        Console.WriteLine("Inserted successfully");
                    }
                    catch (SqlException ex)
                    {
                        Logger.LogError(ex, "Failed to execute query");
                        return;
                    }
                }
            }
        }
    }
}
```
