    public List<String> getWeaknesses(byte[] byteArray) {
        String typeName = null;
        try {
            Pokemon pokemon = deserializePokemon(byteArray);
            typeName = pokemon.getType().getName();
            if (pokemonCache.containsKey(typeName)) {
                return pokemonCache.get(typeName);
            } else {
                List<String> weaknesses = fetchWeaknessesFromApi(typeName);
                if (weaknesses != null) {
                    pokemonCache.put(typeName, weaknesses);
                    return weaknesses;
                }
            }
        } catch (Exception e) {
            System.out.println("Error in getWeaknesses: " + e.getMessage());
        }
        return null;
    }

    private Pokemon deserializePokemon(byte[] byteArray) throws Exception {
        // Use a JSON serializer to deserialize the byte array into a Pokemon object
        JSONSerializer serializer = new JSONSerializer();
        return serializer.deserialize(byteArray, Pokemon.class);
    }

    private List<String> fetchWeaknessesFromApi(String typeName) {
        // Use an external REST API to retrieve the weaknesses for a given Pokemon type
        URL url = new URL("https://api.pokemontcg.io/v1/types/" + typeName);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        if (connection.getResponseCode() == 200) {
            InputStream inputStream = connection.getInputStream();
            // Use a JSON serializer to deserialize the API response into a list of weaknesses
            JSONSerializer serializer = new JSONSerializer();
            List<String> weaknesses = serializer.deserialize(inputStream, List.class);
            return weaknesses;
        } else {
            System.out.println("Error in fetchWeaknessesFromApi: " + connection.getResponseMessage());
            return null;
        }
    }

    private void updatePokemonCache(String typeName, List<String> weaknesses) {
        // Update the cache with the latest weaknesses for a given Pokemon type
        pokemonCache.put(typeName, weaknesses);
    }
}
