      sensorDataCollection.find().toArray(function(err, sensors) {
        if (err) {
          console.log("Error retrieving sensors:", err);
          res.status(500).json({ message: "Error retrieving sensors" });
        } else {
          res.json(sensors);
        }
      });
    });

    app.post('/sensor', function(req, res) {
      // Save a new sensor reading to the database
      const data = req.body;
      if (!data || !data.sensorId || !data.reading) {
        return res.status(400).json({ message: "Invalid sensor reading" });
      }
      const sensorData = new SensorData(data);
      sensorDataCollection.insertOne(sensorData, function(err, result) {
        if (err) {
          console.log("Error saving sensor reading:", err);
          res.status(500).json({ message: "Error saving sensor reading" });
        } else {
          res.json({ message: "Sensor reading saved successfully" });
        }
      });
    });
  }
});

// Start the server
