using Microsoft.Web.Administration;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

namespace IISManagerService
{
    public class SiteManager : IDisposable
    {
        private const string WebConfigFileName = "web.config";
        private readonly ServerManager _serverManager;
        private readonly IIISManager _iisManager;

        public SiteManager(string serverName)
        {
            _serverManager = new ServerManager(serverName);
            _iisManager = new IIISManager();
        }

        public async Task<bool> AddSiteAsync(string siteName, string directoryPath)
        {
            try
            {
                var webConfigFilePath = Path.Combine(directoryPath, WebConfigFileName);
                if (!File.Exists(webConfigFilePath))
                {
                    // Log error message and return false
                    Console.WriteLine($"{WebConfigFileName} file not found in {directoryPath}. Site addition failed.");
                    return false;
                }

                var site = _serverManager.Sites.FirstOrDefault(s => s.Name == siteName);
                if (site != null)
                {
                    // Log error message and return false
                    Console.WriteLine($"Site with name '{siteName}' already exists.");
                    return false;
                }

                var newSite = _serverManager.Sites.Add(siteName, "http");
                newSite.Bindings.Add("*:80:" + siteName);
                newSite.Applications["/"].ApplicationPoolName = "DefaultAppPool";
                await newSite.Applications["/"].VirtualDirectories.Add("/", directoryPath).ConfigureAwait(false);
                _serverManager.CommitChanges();

                // Log success message and return true
                Console.WriteLine($"Site with name '{siteName}' added successfully.");
                return true;
            }
            catch (Exception e)
            {
                // Log error message and return false
                Console.WriteLine($"Error adding site: {e.Message}");
                return false;
            }
        }

        public async Task<bool> RemoveSiteAsync(string siteName)
        {
            try
            {
                var site = _serverManager.Sites.FirstOrDefault(s => s.Name == siteName);
                if (site == null)
                {
                    // Log error message and return false
                    Console.WriteLine($"Site with name '{siteName}' does not exist.");
                    return false;
                }

                _serverManager.Sites.Remove(site);
                _serverManager.CommitChanges();

                // Log success message and return true
                Console.WriteLine($"Site with name '{siteName}' removed successfully.");
                return true;
            }
            catch (Exception e)
            {
                // Log error message and return false
                Console.WriteLine($"Error removing site: {e.Message}");
                return false;
            }
        }

        public async Task<bool> UpdateSiteAsync(string siteName, string directoryPath)
        {
            try
            {
                var webConfigFilePath = Path.Combine(directoryPath, WebConfigFileName);
                if (!File.Exists(webConfigFilePath))
                {
                    // Log error message and return false
                    Console.WriteLine($"{WebConfigFileName} file not found in {directoryPath}. Site update failed.");
                    return false;
                }

                var site = _serverManager.Sites.FirstOrDefault(s => s.Name == siteName);
                if (site == null)
                {
                    // Log error message and return false
                    Console.WriteLine($"Site with name '{siteName}' does not exist.");
                    return false;
                }

                site.Applications["/"].VirtualDirectories[0].PhysicalPath = directoryPath;
                _serverManager.CommitChanges();

                // Log success message and return true
                Console.WriteLine($"Site with name '{siteName}' updated successfully.");
                return true;
            }
            catch (Exception e)
            {
                // Log error message and return false
                Console.WriteLine($"Error updating site: {e.Message}");
                return false;
            }
        }

        public void Dispose()
        {
            _serverManager?.Dispose();
        }
    }
}
```
This code creates a `SiteManager` class that uses the `Microsoft.Web.Administration` namespace to manage IIS sites and applications. The `AddSiteAsync`, `RemoveSiteAsync`, and `UpdateSiteAsync` methods allow for adding, removing, and updating websites on an IIS server respectively. The `IDisposable` interface is implemented to ensure proper resource cleanup.

The code uses the `FirstOrDefault` method of the `Sites` collection to check if a site with the specified name already exists before proceeding with any operations. If no such site is found, an error message is logged and the operation fails.

The `AddSiteAsync` method creates a new site using the `Sites.Add` method and adds a binding for the default HTTP protocol to port 80 with the specified site name. It then sets the application pool name to "DefaultAppPool" and adds a virtual directory at the root of the website with the physical path set to the specified directory path. Finally, it commits the changes using the `CommitChanges` method of the `ServerManager` class.

The `RemoveSiteAsync` method removes the site from the IIS server using the `Sites.Remove` method and then commits the changes. If no such site is found, an error message is logged and the operation fails.

The `UpdateSiteAsync` method updates the virtual directory of the specified website with the physical path set to the specified directory path using the `Applications["/"].VirtualDirectories[0].PhysicalPath = directoryPath;` line of code. It then commits the changes using the `CommitChanges` method of the `ServerManager` class.

The code uses the `IDisposable` interface to ensure proper resource cleanup and the `async`/`await` keywords for asynchronous programming and better performance. The `using` statement is also used to dispose of the `ServerManager` instance after use.

