// C++ function to dynamically generate and populate a forward list of NFAPI_CRC_INDICATION_PDUs
void generateCrcIndicationPdus(int numPdus, int rxUeInformationTag, int rnti, int crcIndicationRel8Tag) {
    // Thread pool for efficient task distribution and scalable processing
    std::vector<std::thread> threads;

    // Dynamic adjustment of the size of the thread pool based on the current load
    if (numPdus > 10000) {
        numThreads = std::min(numPdus, 50);
    } else {
        numThreads = std::min(numPdus, 10);
    }

    // Initialize the thread pool with the appropriate number of threads
    for (int i = 0; i < numThreads; ++i) {
        threads.push_back(std::thread([=]() {
            // Generate and populate a forward list of NFAPI_CRC_INDICATION_PDUs
            std::forward_list<NFAPI_CRC_INDICATION_PDU> crcIndicationPdus;
            for (int i = 0; i < numPdus; ++i) {
                NFAPI_CRC_INDICATION_PDU pdu;
                pdu.rxUeInformationTag = rxUeInformationTag;
                pdu.rnti = rnti;
                pdu.crcIndicationRel8Tag = crcIndicationRel8Tag;
                // Randomly set CRCFLAG value for demonstration purposes only
                pdu.CRCFlag = static_cast<uint8_t>(std::rand() % 2);
                crcIndicationPdus.push_back(pdu);
            }
        }));
    }

    // Wait for all threads to complete
    for (auto& thread : threads) {
        thread.join();
    }
}

// C# method to insert a second string after the first occurrence of a specified string in a forward list
void InsertAfter(String value, String target) {
    // Check if the value is null or empty
    if (string.IsNullOrEmpty(value)) {
        throw new ArgumentException("Value cannot be null or empty.", "value");
    }

    // Check if the target is null or empty
    if (string.IsNullOrEmpty(target)) {
        throw new ArgumentException("Target cannot be null or empty.", "target");
    }

    // Get the first index of the target in the forward list
    int targetIndex = 0;
    for (int i = 0; i < forwardList.Count; ++i) {
        if (forwardList[i] == target) {
            targetIndex = i + 1;
            break;
        }
    }

    // Insert the value after the first occurrence of the target in the forward list
    for (int i = targetIndex; i < forwardList.Count; ++i) {
        forwardList.InsertAfter(forwardList[i], value);
    }
}

