// Compression algorithm to compress data using the GZip algorithm
byte[] GZip(byte[] data) {
    MemoryStream memoryStream = new MemoryStream();
    using (var compressionStream = new GZipStream(memoryStream, CompressionMode.Compress)) {
        compressionStream.Write(data, 0, data.Length);
    }
    return memoryStream.ToArray();
}

// Compression algorithm to compress data using the Deflate algorithm
byte[] Deflate(byte[] data) {
    MemoryStream memoryStream = new MemoryStream();
    using (var compressionStream = new DeflateStream(memoryStream, CompressionMode.Compress)) {
        compressionStream.Write(data, 0, data.Length);
    }
    return memoryStream.ToArray();
}

// Encryption algorithm to encrypt data using the AES128 algorithm
byte[] AESEncrypt(byte[] data, string password) {
    byte[] key = new byte[16];
    var salt = new byte[16];
    var rng = new RNGCryptoServiceProvider();
    rng.GetBytes(salt);
    byte[] iv = new byte[16];
    rng.GetBytes(iv);
    using (var aes = Aes.Create()) {
        aes.KeySize = 128;
        aes.BlockSize = 128;
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;
        using (var encryptor = aes.CreateEncryptor(key, iv)) {
            MemoryStream memoryStream = new MemoryStream();
            using (var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write)) {
                cryptoStream.Write(data, 0, data.Length);
            }
            return memoryStream.ToArray();
        }
    }
}

// Encryption algorithm to encrypt data using the DESede192 algorithm
byte[] DESedeEncrypt(byte[] data, string password) {
    byte[] key = new byte[24];
    var salt = new byte[24];
    var rng = new RNGCryptoServiceProvider();
    rng.GetBytes(salt);
    using (var des = new DESCryptoServiceProvider()) {
        des.KeySize = 192;
        des.BlockSize = 64;
        des.Mode = CipherMode.CBC;
        des.Padding = PaddingMode.PKCS7;
        using (var encryptor = des.CreateEncryptor(key, salt)) {
            MemoryStream memoryStream = new MemoryStream();
            using (var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write)) {
                cryptoStream.Write(data, 0, data.Length);
            }
            return memoryStream.ToArray();
        }
    }
}
