int process_file(struct InputFile *input) {
  // Check if password is empty or NULL
  if (input->password == NULL || input->password[0] == '\0') {
    return ERROR_PASSWORD_REQUIRED;
  }

  // Check if input file has a title set
  if (input->title == NULL) {
    return ERROR_INPUT_TITLE_REQUIRED;
  }

  // Check if callback function is not NULL
  if (input->callback == NULL) {
    return ERROR_CALLBACK_FUNCTION_REQUIRED;
  }

  // Read binary contents of input file
  FILE *infile = fopen(input->filename, "rb");
  if (infile == NULL) {
    return ERROR_OPENING_INPUT_FILE;
  }
  size_t file_size = get_file_size(infile);
  uint8_t *buffer = malloc(file_size);
  fread(buffer, 1, file_size, infile);
  fclose(infile);

  // Parse input contents and generate output file based on rules provided by callback function
  FILE *outfile = fopen(input->output_filename, "wb");
  if (outfile == NULL) {
    return ERROR_CREATING_OUTPUT_FILE;
  }
  for (size_t i = 0; i < file_size; i++) {
    uint8_t byte = buffer[i];
    // Invoke callback function to parse and transform current byte
    byte = input->callback(byte);
    fwrite(&byte, 1, sizeof(byte), outfile);
  }
  free(buffer);
  fclose(outfile);

  return ERROR_NONE;
}
