#include <random>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>

namespace RandomGenerator {
    class ParallelMTGenerator {
    public:
        ParallelMTGenerator(unsigned int seed) : _seed(seed), _mt19937Pool() {
            // Initialize the pool of MT19937 instances
            for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
                _mt19937Pool.emplace_back(seed);
            }
        }

        ~ParallelMTGenerator() {}

        // Generate a sequence of random numbers within the specified range
        template <typename T>
        std::vector<T> generateRandomSequence(T min, T max) {
            std::lock_guard<std::mutex> lock(_mutex);

            if (min > max) {
                throw std::invalid_argument("Invalid range");
            }

            // Generate a random number within the specified range using each MT19937 instance in parallel
            std::vector<T> result(std::thread::hardware_concurrency());
            for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
                T randomNumber = _mt19937Pool[i]();
                if (randomNumber >= min && randomNumber <= max) {
                    result.push_back(randomNumber);
                }
            }
            return result;
        }

    private:
        unsigned int _seed;
        std::vector<std::mt19937> _mt19937Pool;
        std::mutex _mutex;
        std::condition_variable _cv;
    };
}
```
