using CacheConditionVariable = std::condition_variable;

// Define a function to perform HTTP requests and return the response as a string
std::string httpRequest(const Config& config, const std::string& url, const std::string& method, const std::unordered_map<std::string, std::string>& headers) {
    // Initialize the HTTP client with the configuration provided
    HttpClient httpClient(config.httpConfig);

    // Set up the request parameters
    HttpRequestParameters params;
    params.url = url;
    params.method = method;
    params.headers = headers;

    // Perform the HTTP request and return the response as a string
    return httpClient.request(params).body;
}

// Define a function to add a session to the cache
void addSessionToCache(const Config& config, const std::string& url, const std::string& method, const std::unordered_map<std::string, std::string>& headers) {
    // Acquire the lock on the cache mutex
    CacheMutex().lock();

    // Check if the session already exists in the cache
    auto it = sessionCache.find(url);

    // If the session does not exist, add it to the cache and signal any waiting threads
    if (it == sessionCache.end()) {
        SessionCacheEntry entry;
        entry.url = url;
        entry.method = method;
        entry.headers = headers;
        sessionCache[url] = entry;
        CacheConditionVariable().notify_all();
    }

    // Release the lock on the cache mutex
    CacheMutex().unlock();
}

// Define a function to remove a session from the cache
void removeSessionFromCache(const std::string& url) {
    // Acquire the lock on the cache mutex
    CacheMutex().lock();

    // Remove the session from the cache
    sessionCache.erase(url);

    // Release the lock on the cache mutex
    CacheMutex().unlock();
}

// Define a function to retrieve a session from the cache
SessionCacheEntry getSessionFromCache(const std::string& url) {
    // Acquire the lock on the cache mutex
    CacheMutex().lock();

    // Check if the session exists in the cache and return it if it does
    auto it = sessionCache.find(url);
    SessionCacheEntry entry;
    if (it != sessionCache.end()) {
        entry = it->second;
    }

    // Release the lock on the cache mutex
    CacheMutex().unlock();

    return entry;
}

// Define a function to update a session in the cache
void updateSessionInCache(const std::string& url, const SessionCacheEntry& entry) {
    // Acquire the lock on the cache mutex
    CacheMutex().lock();

    // Update the session in the cache
    sessionCache[url] = entry;

    // Release the lock on the cache mutex
    CacheMutex().unlock();
}

// Define a function to retrieve a token from a session and update it if necessary
std::string getTokenFromSession(const Config& config, const std::string& url) {
    // Retrieve the session from the cache
    SessionCacheEntry entry = getSessionFromCache(url);

    // If the session does not exist in the cache or has expired, return an empty string
    if (entry.token == "") {
        return "";
    }

    // Check if the token is still valid by sending a request with the token
    HttpRequestParameters params;
    params.url = url;
    params.method = "GET";
    params.headers = entry.headers;
    params.headers["Authorization"] = "Bearer " + entry.token;

    // Perform the request and check if it was successful
    std::string response = httpRequest(config, url, params);
    if (response == "") {
        return "";
    }

    // Parse the response to extract the token
    std::regex pattern("\"token\": \"(.*)\"");
    std::smatch match;
    if (!std::regex_search(response, match, pattern)) {
        return "";
    }

    // Update the token in the session cache and return it
    SessionCacheEntry updatedEntry = entry;
    updatedEntry.token = match[1];
    updateSessionInCache(url, updatedEntry);
    return updatedEntry.token;
}

// Define a function to perform a request with a token from a session
std::string requestWithTokenFromSession(const Config& config, const std::string& url) {
    // Retrieve the token from the session cache and check if it is valid
    std::string token = getTokenFromSession(config, url);
    if (token == "") {
        return "";
    }

    // Perform the request with the token
    HttpRequestParameters params;
    params.url = url;
    params.method = "GET";
    params.headers["Authorization"] = "Bearer " + token;
    std::string response = httpRequest(config, url, params);

    // Check if the request was successful and return the response
    if (response == "") {
        return "";
    } else {
        return response;
    }
}

// Define a function to perform a request with a token from a session and add it to the cache if necessary
void requestWithTokenFromSessionAndAddToCache(const Config& config, const std::string& url) {
    // Retrieve the token from the session cache and check if it is valid
    std::string token = getTokenFromSession(config, url);
    if (token == "") {
        return;
    }

    // Perform the request with the token
    HttpRequestParameters params;
    params.url = url;
    params.method = "GET";
    params.headers["Authorization"] = "Bearer " + token;
    std::string response = httpRequest(config, url, params);

    // Check if the request was successful and add it to the cache if necessary
    if (response != "") {
        SessionCacheEntry entry;
        entry.token = token;
        updateSessionInCache(url, entry);
    }
}

// Define a function to perform a request with a token from a session and remove it from the cache if necessary
void requestWithTokenFromSessionAndRemoveFromCache(const Config& config, const std::string& url) {
    // Retrieve the token from the session cache and check if it is valid
    std::string token = getTokenFromSession(config, url);
    if (token == "") {
        return;
    }

    // Perform the request with the token
    HttpRequestParameters params;
    params.url = url;
    params.method = "GET";
    params.headers["Authorization"] = "Bearer " + token;
    std::string response = httpRequest(config, url, params);

    // Check if the request was successful and remove it from the cache if necessary
    if (response == "") {
        removeSessionFromCache(url);
    }
}
