// SecureTokenGenerator.rs
use std::collections::HashMap;
use std::hash::Hash;
use std::string::String;
use std::vec::Vec;
use chrono::prelude::*;
use sha2::Sha256;

fn secure_token_generator(username: &str, timestamp: i64, secret_key: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(username);
    hasher.update(&timestamp.to_string());
    hasher.update(secret_key);
    hasher.finalize().as_slice().to_hex()
}

fn load_resource_bundle(url: &str, max_size: usize) -> Result<Vec<HashMap<String, String>>, Box<dyn Error>> {
    let mut res = Vec::with_capacity(max_size);
    let mut resp = reqwest::blocking::get(url)?;
    let mut buf = Vec::new();
    let _ = resp.read_to_end(&mut buf)?;

    // Parse the response body as JSON and convert it to a vector of maps
    let parsed: Vec<HashMap<String, String>> = serde_json::from_slice(buf.as_ref())?;
    Ok(parsed)
}
