    public function index() {
        $client = new OAuth2Client($this->config);
        $access_token = $client->authenticate("user", "password");

        // Use the access token to retrieve user information
        $response = $client->get(
            'https://api.example.com/users',
            [
                'headers' => [
                    'Authorization' => 'Bearer ' . $access_token,
                ],
            ]
        );

        // Handle error cases and check the response status code
        if ($response->getStatusCode() === 200) {
            $data = json_decode($response->getBody(), true);
            return view('users', ['users' => $data]);
        } else {
            throw new \Exception("Error occurred while retrieving user information");
        }
    }
}
