#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

// Helper function to read a line of integers from standard input
int read_line(char* buffer, size_t size) {
    int num = 0;
    while (fgets(buffer, size, stdin)) {
        char* endptr;
        errno = 0;
        long int i = strtol(buffer, &endptr, 10);
        if (errno != 0 || *endptr != '\n') {
            printf("Invalid input. Please enter a valid integer.\n");
            continue;
        }
        num++;
    }
    return num;
}

// Helper function to allocate memory for an array of integers
int* allocate_array(size_t size) {
    int* arr = (int*)malloc(size * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Error: unable to allocate memory. Aborting...\n");
        exit(EXIT_FAILURE);
    }
    return arr;
}

// Helper function to free memory allocated for an array of integers
void free_array(int* arr) {
    if (arr) {
        free(arr);
    }
}

// Function to read a list of integers from standard input, store them in a dynamically allocated array, and find the largest integer
int largest_integer() {
    // Read the number of integers from standard input
    int num = 0;
    do {
        printf("Enter the number of integers: ");
        if ((num = read_line(buffer, sizeof(buffer))) == -1) {
            printf("Invalid input. Please enter a valid integer.\n");
        }
    } while (num <= 0);

    // Allocate memory for the array of integers
    int* arr = allocate_array(num * sizeof(int));

    // Read the integers from standard input and store them in the array
    for (int i = 0; i < num; i++) {
        printf("Enter integer #%d: ", i + 1);
        if ((arr[i] = read_line(buffer, sizeof(buffer))) == -1) {
            printf("Invalid input. Please enter a valid integer.\n");
            free_array(arr);
            return -1;
        }
    }

    // Find the largest integer in the array and print it
    int largest = arr[0];
    for (int i = 1; i < num; i++) {
        if (largest < arr[i]) {
            largest = arr[i];
        }
    }
    printf("Largest integer: %d\n", largest);

    // Free memory allocated for the array of integers
    free_array(arr);

    return 0;
}
