```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.IO;
using System.Net.Http;
using System.Net.NetworkInformation;

namespace DynamicRandomValueGenerator
{
    public class DynamicRandomValueGenerator
    {
        private readonly string _configFilePath;
        private int _minValue;
        private int _maxValue;
        private Random _random = new Random();
        private bool _isRangeValid;

        public DynamicRandomValueGenerator(string configFilePath)
        {
            _configFilePath = configFilePath;
            LoadConfigFromFile(_configFilePath);
        }

        public int GetNextInt()
        {
            return GetNextRandomValue();
        }

        public float GetNextFloat(int precision = 2)
        {
            return (float)GetNextRandomValue() / Math.Pow(10, precision);
        }

        private int GetNextRandomValue()
        {
            if (!_isRangeValid)
                throw new InvalidOperationException("Invalid range limits.");

            return _random.Next(_minValue, _maxValue + 1);
        }

        private void LoadConfigFromFile(string configFilePath)
        {
            try
            {
                using (var reader = new StreamReader(configFilePath))
                {
                    var json = reader.ReadToEnd();
                    var config = JsonConvert.DeserializeObject<RandomValueConfig>(json);
                    _minValue = config.MinValue;
                    _maxValue = config.MaxValue;
                    _isRangeValid = true;
                }
            }
            catch (Exception ex) when (ex is FileNotFoundException || ex is IOException)
            {
                Console.WriteLine($"Error loading configuration from file: {ex.Message}");
            }
        }

        private void LoadConfigFromRemoteSource(string remoteUrl)
        {
            try
            {
                using (var client = new HttpClient())
                {
                    var json = client.GetStringAsync(remoteUrl).Result;
                    var config = JsonConvert.DeserializeObject<RandomValueConfig>(json);
                    _minValue = config.MinValue;
                    _maxValue = config.MaxValue;
                    _isRangeValid = true;
                }
            }
            catch (Exception ex) when (ex is HttpRequestException || ex is NetworkInformationException)
            {
                Console.WriteLine($"Error fetching configuration from remote source: {ex.Message}");
            }
        }
    }

    public class RandomValueConfig
    {
        public int MinValue { get; set; }
        public int MaxValue { get; set; }
    }
}
