##### 使用`uv_ip4_addr()`和`uv_tcp_bind()`实现IPv4地址解析与绑定

###### IPv4地址解析与绑定

**代码清单10-9：使用`uv_ip4_addr()`和`uv_tcp_bind()`实现IPv4地址解析与绑定**
```c
#include <stdio.h>
#include <stdlib.h>
#include <uv.h>

int main() {
    uv_loop_t *loop = uv_default_loop();

    struct sockaddr_in addr;
    if (uv_ip4_addr("127.0.0.1", 8080, &addr)) {
        fprintf(stderr, "Invalid IP address or port number\n");
        return 1;
    }

    uv_tcp_t *server = malloc(sizeof(*server));
    int r = uv_tcp_init(loop, server);
    if (r) {
        fprintf(stderr, "Init error: %s\n", uv_strerror(r));
        return 1;
    }

    r = uv_tcp_bind(server, (struct sockaddr *)&addr, 0);
    if (r) {
        fprintf(stderr, "Bind error: %s\n", uv_strerror(r));
        return 1;
    }

    r = uv_listen((uv_stream_t *)server, 128, on_new_connection);
    if (r) {
        fprintf(stderr, "Listen error: %s\n", uv_strerror(r));
        return 1;
    }

    uv_run(loop, UV_RUN_DEFAULT);
    return 0;
}
```
###### 监听描述符的创建和绑定

**代码清单10-10：监听描述符的创建和绑定**
```c
int r = uv_tcp_init(loop, server);
if (r) {
    fprintf(stderr, "Init error: %s\n", uv_strerror(r));
    return 1;
}

uv_os_fd_t fd;
uv_file file = -1;
r = uv_fileno((const uv_handle_t *)server, &fd);
if (r) {
    fprintf(stderr, "fileno error: %s\n", uv_strerror(r));
    return 1;
}
file = fd;

struct sockaddr addr;
socklen_t addrlen = sizeof(addr);
if (getsockname(file, &addr, &addrlen)) {
    perror("getsockname");
    return 1;
}

uv_os_fd_t sock;
r = uv_tcp_open(server, file);
if (r) {
    fprintf(stderr, "TCP open error: %s\n", uv_strerror(r));
    return 1;
}

uv_os_sock_t sockaddr = addr.sa_data;
r = uv_listen((uv_stream_t *)server, 128, on_new_connection);
if (r) {
    fprintf(stderr, "Listen error: %s\n", uv_strerror(r));
    return 1;
}
```
