    char **arguments;
    char **environment_variables;
    char *working_directory;
    int timeout;
    int priority;
} Command;

typedef struct Group {
    Command commands[MAX_COMMANDS];
    int num_commands;
    semaphore_t semaphore;
} Group;

// Function to execute a command in the background using fork and wait
int execute_background_command(Command *command) {
    pid_t pid = fork();
    if (pid == 0) { // Child process
        int status = execve(command->command, command->arguments, command->environment_variables);
        perror("execve");
        exit(1);
    } else if (pid > 0) { // Parent process
        waitpid(pid, NULL, WNOHANG);
    } else {
        perror("fork");
        return 0;
    }
    return 1;
}

// Function to execute a group of commands in the background using fork and wait
int execute_group(Group *group) {
    int i, j;
    for (i = 0; i < group->num_commands; i++) {
        Command *command = &(group->commands[i]);
        if (!execute_background_command(command)) {
            perror("execute_background_command");
            return 0;
        }
    }
    return 1;
}

