int execute_custom_signal_handlers(Command *command, void (*custom_handler)(int)) {
    pid_t pid = fork();
    if (pid == 0) { // Child process
        struct sigaction sa;
        sa.sa_handler = custom_handler;
        sa.sa_flags = SA_NODEFER | SA_RESETHAND;
        sigemptyset(&(sa.sa_mask));
