<?php

namespace OAuth;

use Redis;
use GuzzleHttp\Client as HttpClient;
use Psr\Log\LoggerInterface;
use Symfony\Component\Cache\Adapter\RedisAdapter;

class Authenticator
{
    private $httpClient;
    private $cache;
    private $logger;

    public function __construct(HttpClient $httpClient, RedisAdapter $cache, LoggerInterface $logger)
    {
        $this->httpClient = $httpClient;
        $this->cache = $cache;
        $this->logger = $logger;
    }

    /**
     * Authenticate a user using an OAuth 2.0 client and retrieve their information
     *
     * @param string $provider The name of the OAuth provider (e.g., 'google', 'facebook', 'github')
     * @param array $credentials An array of credentials required for authentication (e.g., access token, client secret)
     * @param int $sessionTimeout The amount of time in seconds that the user's session should be valid for
     * @param int $cacheExpiration The amount of time in seconds that the user information should be cached for
     * @return array An associative array containing the authenticated user's information (e.g., id, name, email)
     */
    public function authenticateUser(string $provider, array $credentials, int $sessionTimeout = 3600, int $cacheExpiration = 86400): array
    {
        // Check if the user is already authenticated and retrieve their session ID
        $sessionId = $this->checkSession($provider);

        // If a session ID was not found, create a new one and store it in the cache
        if (!$sessionId) {
            $sessionId = bin2hex(random_bytes(16));
            $this->cache->set('auth:' . $provider . ':' . $sessionId, [], $sessionTimeout);
        }

        // Retrieve the user's information from the API using the access token and store it in the cache
        $userInfo = $this->getUserInfo($credentials['access_token']);
        $this->cache->set('auth:' . $provider . ':' . $sessionId, $userInfo, $cacheExpiration);

        // Return the authenticated user's information
        return [
            'id' => $userInfo['id'],
            'name' => $userInfo['name'],
            'email' => $userInfo['email'],
        ];
    }

    /**
     * Check if a user is already authenticated and retrieve their session ID
     *
     * @param string $provider The name of the OAuth provider (e.g., 'google', 'facebook', 'github')
     * @return string|null The session ID if a user is already authenticated, null otherwise
     */
    private function checkSession(string $provider): ?string
    {
        // Check if there is an active session in the cache
        $sessionId = $this->cache->get('auth:' . $provider . ':session_id');

        // If a session ID was found, check if it has not expired and return it
        if ($sessionId) {
            $sessionInfo = $this->cache->get('auth:' . $provider . ':' . $sessionId);
            if (is_array($sessionInfo) && count($sessionInfo) > 0) {
                return $sessionId;
            }
        }

        // No active session was found, return null
        return null;
    }

    /**
     * Retrieve the user's information from the API using the access token
     *
     * @param string $accessToken The access token provided by the OAuth provider
     * @return array An associative array containing the user's information (e.g., id, name, email)
     */
    private function getUserInfo(string $accessToken): array
    {
        // Set up the HTTP client and make a GET request to the API endpoint with the access token
        $response = $this->httpClient->get('https://api.example.com/user', [
            'headers' => ['Authorization' => 'Bearer ' . $accessToken],
        ]);

        // Check if the response was successful and return the user's information
        if ($response->getStatusCode() == 200) {
            $data = json_decode($response->getBody()->getContents(), true);
            return [
                'id' => $data['id'],
                'name' => $data['name'],
                'email' => $data['email'],
            ];
        } else {
            // Handle error response from the API
            $this->logger->error('Failed to retrieve user information: ' . json_encode($response));
            return [];
        }
    }
}
