```csharp
using System;
using System.Data;
using System.Threading.Tasks;
using Npgsql;

namespace ConsoleApp1
{
    class Program
    {
        static async Task Main(string[] args)
        {
            // Check for correct number of arguments
            if (args.Length != 3)
            {
                Console.WriteLine("Invalid number of arguments. Usage: <connection string> <SQL command> <parameter values>");
                return;
            }

            // Parse connection string, SQL command, and parameter values
            var connectionString = args[0];
            var sqlCommand = args[1];
            var parameterValues = args.Skip(2).Select(arg => Convert.ChangeType(arg, typeof(object))).ToArray();

            // Construct the SQL command with parameters
            using (var conn = new NpgsqlConnection(connectionString))
            {
                await conn.OpenAsync();

                var cmd = conn.CreateCommand();
                cmd.CommandText = sqlCommand;
                cmd.Parameters.AddRange(parameterValues);

                // Execute the command asynchronously and retrieve the result set
                using (var reader = await cmd.ExecuteReaderAsync())
                {
                    // Read the result set and print each row
                    while (await reader.ReadAsync())
                    {
                        var columns = new string[reader.FieldCount];
                        reader.GetValues(columns);
                        Console.WriteLine("Row: " + String.Join(", ", columns));
                    }
                }
            }
        }
    }
}
```
