public class DynamicRandomValueGenerator : MonoBehaviour
{
    // External data source settings
    private const string API_URL = "https://example.com/api";
    private const int KEY_CACHE_SIZE = 10;
    private const int IV_CACHE_SIZE = 5;
    private const float CACHE_EXPIRATION_TIME = 30f; // in minutes
    private const string ENCRYPTION_ALGORITHM = "AES";
    private const string DECRYPTION_MODE = "GCM";

    // Key and IV caches
    private static readonly Dictionary<string, object> KEY_CACHE = new Dictionary<string, object>(KEY_CACHE_SIZE);
    private static readonly Dictionary<string, object> IV_CACHE = new Dictionary<string, object>(IV_CACHE_SIZE);

    // Random value generation settings
    private const int MIN_VALUE = 0;
    private const int MAX_VALUE = 100;
    private static readonly Random RANDOM = new Random();

    // Encryption and decryption settings
    private static readonly Encoding ENCODING = Encoding.UTF8;
    private static readonly CipherMode CIPHER_MODE = CipherMode.GCM;

    // Public interface methods
    public int GenerateRandomValue()
    {
        return RANDOM.Next(MIN_VALUE, MAX_VALUE);
    }

    public string EncryptMessage(string message)
    {
        var key = GetKey();
        var iv = GetIV();

        using (var encryptor = new AesGcmEncryptor(ENCODING, CIPHER_MODE))
        {
            return encryptor.Encrypt(message, key, iv);
        }
    }

    public string DecryptMessage(string message)
    {
        var key = GetKey();
        var iv = GetIV();

        using (var decryptor = new AesGcmDecryptor(ENCODING, CIPHER_MODE))
        {
            return decryptor.Decrypt(message, key, iv);
        }
    }

    // Private helper methods
    private static string GetKey()
    {
        if (KEY_CACHE.Count > 0)
        {
            var key = KEY_CACHE.Values.First();
            return key as string;
        }

        var keyResponse = FetchKeysFromAPI();
        if (keyResponse != null && keyResponse.IsSuccessful)
        {
            var key = keyResponse.Data.Keys[0];
            KEY_CACHE.Add(key, key);
            return key;
        }

        throw new Exception("Failed to fetch keys from API.");
    }

    private static string GetIV()
    {
        if (IV_CACHE.Count > 0)
        {
            var iv = IV_CACHE.Values.First();
            return iv as string;
        }

        var ivResponse = FetchIVsFromAPI();
        if (ivResponse != null && ivResponse.IsSuccessful)
        {
            var iv = ivResponse.Data.IVs[0];
            IV_CACHE.Add(iv, iv);
            return iv;
        }

        throw new Exception("Failed to fetch IVs from API.");
    }

    private static ApiResponse FetchKeysFromAPI()
    {
        var response = UnityWebRequest.Get($"{API_URL}/keys").Send();
        return JsonUtility.FromJson<ApiResponse>(response.downloadHandler.text);
    }

    private static ApiResponse FetchIVsFromAPI()
    {
        var response = UnityWebRequest.Get($"{API_URL}/ivs").Send();
        return JsonUtility.FromJson<ApiResponse>(response.downloadHandler.text);
    }

    // Classes and structs for API responses and caching
    [Serializable]
    public class ApiResponse
    {
        public List<string> Keys;
        public List<string> IVs;
    }

    [Serializable]
    public class KeyCacheEntry
    {
        public string Key;
        public DateTime ExpirationTime;
    }

    [Serializable]
    public class IvCacheEntry
    {
        public string IV;
        public DateTime ExpirationTime;
    }
}
