use std::sync::{Arc, Mutex};
use std::time::Instant;
use std::fs::File;
use std::io::Read;
use std::path::PathBuf;
use rustc_driver::catch_with_exit_code;
use rustc_driver::Session;
use rustc_driver::plugin::{PluginRegistrar, PluginResult};
use rustc_driver::plugin::CompilationReport;
use rustc_driver::rustc_interface::Input;
use synclazy::SyncLazy;

struct CompilePlugin {
    session: Arc<Mutex<Session>>,
    logger: SyncLazy<Logger>,
}

impl CompilePlugin {
    fn new() -> Self {
        let session = Arc::new(Mutex::new(Session::create()));
        let logger = SyncLazy::new(Logger);

        Self {
            session,
            logger,
        }
    }
}

impl PluginRegistrar for CompilePlugin {
    fn register(&self) -> Option<Box<dyn Fn(Vec<PathBuf>) -> Result<(), ()>>> {
        Some(Box::new(|files: Vec<PathBuf>| -> Result<(), ()> {
            let mut reports = vec![];

            for file in files {
                let input = Input::File(file);
                let session = self.session.clone();
                let logger = self.logger.get_or_init(|| Logger);

                match catch_with_exit_code(&input, &session) {
                    Ok(_) => {},
                    Err(e) => eprintln!("{}", e),
                }

                if let Some(report) = session.take_compilation_reports() {
                    reports.push(report);
                }
            }

            Ok(())
        }))
    }
}
