using System;
using System.Data;
using System.Text;
using System.Threading.Tasks;

namespace MyWebApp
{
    public class PageSectionElementUpdater
    {
        private readonly DatabaseConnection _databaseConnection;
        private readonly ServiceClass _serviceClass;

        public PageSectionElementUpdater(DatabaseConnection databaseConnection, ServiceClass serviceClass)
        {
            _databaseConnection = databaseConnection;
            _serviceClass = serviceClass;
        }

        public async Task<bool> UpdatePageSectionElementAsync(int pageSectionId, int elementId, string htmlContent)
        {
            try
            {
                // Validate input IDs against the database to ensure they exist and belong to the same page
                bool isValid = await ValidateInputIdsAsync(pageSectionId, elementId);
                if (!isValid)
                {
                    return false;
                }

                // Update the element's HTML content using a service class
                await _serviceClass.UpdateElementHtmlContentAsync(elementId, htmlContent);

                // Check if the updated content exceeds the predefined size limit and handle appropriately
                int contentSize = Encoding.UTF8.GetByteCount(htmlContent);
                bool isOverLimit = contentSize > _serviceClass.MaxContentSize;
                if (isOverLimit)
                {
                    return false;
                }

                // Notify the client that the page should be refreshed
                Console.WriteLine("The element's HTML content has been updated successfully.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error updating page section element: {ex.Message}");
                return false;
            }

            return true;
        }

        private async Task<bool> ValidateInputIdsAsync(int pageSectionId, int elementId)
        {
            // Check if the input IDs exist in the database and belong to the same page
            using (var command = _databaseConnection.CreateCommand())
            {
                command.CommandText = "SELECT COUNT(*) FROM page_sections WHERE id = @pageSectionId AND EXISTS(SELECT 1 FROM elements WHERE page_id = @pageSectionId AND id = @elementId)";
                command.Parameters.AddWithValue("@pageSectionId", pageSectionId);
                command.Parameters.AddWithValue("@elementId", elementId);

                int count = (int)await command.ExecuteScalarAsync();
                return count > 0;
            }
        }
    }
}
