using System;
using UnityEngine;

public class DynamicRandomValueGenerator
{
    private static readonly float[] DistributionTypes = { 0f, 1f }; // inclusive, exclusive
    private static readonly int[] RangeLimits = { 0, 1 }; // default range limits for int and float
    private static readonly string ConfigFilePath = "random_value_config.json"; // default config file path
    private static readonly string RemoteConfigServerUrl = "https://example.com/random_value_config"; // default remote config server URL

    public static float GenerateRandomValue(int min, int max, bool isInclusive)
    {
        if (min > max || min < 0) throw new ArgumentException("Invalid range limits");
        if (!DistributionTypes.Contains(isInclusive)) throw new ArgumentException("Invalid distribution type");

        float randomValue = UnityEngine.Random.Range(min, max + (isInclusive ? 1 : 0));
        return randomValue;
    }

    public static float GenerateRandomFloat(float min, float max)
    {
        if (min > max || min < 0) throw new ArgumentException("Invalid range limits");

        float randomValue = UnityEngine.Random.Range(min, max);
        return randomValue;
    }

    public static int GenerateRandomInt(int min, int max)
    {
        if (min > max || min < 0) throw new ArgumentException("Invalid range limits");

        int randomValue = UnityEngine.Random.Range(min, max);
        return randomValue;
    }

    public static void SetConfigFilePath(string filePath)
    {
        ConfigFilePath = filePath;
    }

    public static void SetRemoteConfigServerUrl(string url)
    {
        RemoteConfigServerUrl = url;
    }
}
