```rust
use std::{
    collections::HashMap,
    fs::File,
    io::BufReader,
    path::Path,
    process::Command,
};

use rustc_driver::{Driver, Session};

fn compile_reports(files: &[&str]) -> Vec<CompilationReport> {
    let mut compilation_reports = vec![];
    for file in files {
        let path = Path::new(file);
        if !path.is_file() {
            continue;
        }

        // Create a new driver instance
        let mut driver = Driver::new();

        // Set the session options to include error reporting and logging
        driver.session().set_options(&[("error-format", "json"), ("log-file", "compilation_reports.log")]);

        // Create a new compiler invocation for this file
        let invocation = driver.new_invocation(path);

        // Compile the file and capture any errors or warnings
        let (mut compilation_report, error) = invocation.compile();
        if let Some(error) = error {
            println!("Error compiling {}: {}", path.display(), error);
            continue;
        }

        // Add the file path and compile time to the report struct
        let compile_time = compilation_report.build_time().unwrap();
        compilation_report.push_entry(("file_path".to_string(), path.to_str().unwrap().to_string()));
        compilation_report.push_entry(("compile_time".to_string(), format!("{:?}", compile_time)));

        // Add the resident set size (RSS) before and after compiling the file
        let mut rss_before = 0;
        let mut rss_after = 0;
        if let Some(report) = compilation_report.as_mut() {
            rss_before = report.memory_usage().unwrap();
            report.build_time().unwrap();
            rss_after = report.memory_usage().unwrap();
        }
        compilation_report.push_entry(("rss_before".to_string(), format!("{}", rss_before)));
        compilation_report.push_entry(("rss_after".to_string(), format!("{}", rss_after)));

        // Add any error messages from the compiler to the report struct
        let mut errors = HashMap::new();
        if let Some(error) = error {
            errors.insert(path, vec![error]);
        }
        compilation_report.extend(errors);

        // Add the compilation report to the list of reports
        compilation_reports.push(compilation_report);
    }

    return compilation_reports;
}
