@Service
public class TransactionRepository implements CrudRepository<Transaction, Long> {

    private static final Map<Long, Transaction> transactions = new HashMap<>();

    @Override
    public Optional<Transaction> findById(Long id) {
        return Optional.ofNullable(transactions.get(id));
    }

    @Override
    public List<Transaction> findAll() {
        return transactions.values().stream().collect(Collectors.toList());
    }

    @Override
    public void save(Transaction transaction) {
        transactions.put(transaction.getId(), transaction);
    }

    @Override
    public void deleteById(Long id) {
        transactions.remove(id);
    }
}
