```java
@Service
public class RedisTemplate<K, V> extends JdkSerializationRedisSerializer {

    private final JedisPool jedisPool;

    public RedisTemplate() {
        this.jedisPool = new JedisPool();
    }

    @Override
    public <T> T get(K key) {
        // Retrieve the value from the cache
        String jsonResponse = jedisPool.getResource().get("transaction:" + key);
        if (jsonResponse != null && !jsonResponse.isEmpty()) {
            return JSON.parseObject(jsonResponse, (Class<T>) Object.class);
        } else {
            return null;
        }
    }

    @Override
    public <T> void set(K key, T value) {
        // Store the value in the cache
        jedisPool.getResource().set("transaction:" + key, JSON.toJSONString(value));
    }
}
