@Service
public class TransactionValidator implements Validator {

    @Override
    public boolean supports(Class<?> clazz) {
        return clazz.equals(Transaction.class);
    }

    @Override
    public void validate(Object target, Errors errors) {
        // Validate the transaction details
        Transaction transaction = (Transaction) target;
        if (transaction.getAmount() <= 0) {
            errors.rejectValue("amount", "invalid_amount");
        }
        if (transaction.getCurrency().isEmpty()) {
            errors.rejectValue("currency", "invalid_currency");
        }
        if (transaction.getDescription().length() > 10) {
            errors.rejectValue("description", "invalid_description");
        }
    }
}
