using System;
using System.Data;
using System.Threading;
using System.Threading.Tasks;

public class DatabaseConnectionPool {
    private static readonly int MAX_CONNECTIONS = 10; // maximum number of connections in the pool
    private static readonly ConcurrentQueue<IDbConnection> _connections = new(); // queue to hold available connections
    private static readonly SemaphoreSlim _semaphore = new(MAX_CONNECTIONS); // semaphore to control access to the queue

    public static async Task<IDbConnection> GetConnectionAsync() {
        await _semaphore.WaitAsync();
        try {
            if (_connections.Count > 0) {
                return _connections.Dequeue(); // get an available connection from the queue
            } else {
                var conn = CreateNewConnection(); // create a new connection
                return conn;
            }
        } finally {
            _semaphore.Release();
        }
    }

    public static async Task ReturnConnectionAsync(IDbConnection connection) {
        await _semaphore.WaitAsync();
        try {
            if (_connections.Count < MAX_CONNECTIONS) {
                _connections.Enqueue(connection); // return the connection to the queue
            } else {
                DisposeConnection(connection); // dispose the connection if the queue is full
            }
        } finally {
            _semaphore.Release();
        }
    }

    private static IDbConnection CreateNewConnection() {
        // create a new database connection here
    }

    private static void DisposeConnection(IDbConnection connection) {
        // dispose the database connection here
    }
}
