using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

public class MyDatabase {
    private readonly string _connectionString; // connection string to the database

    public MyDatabase(string connectionString) {
        _connectionString = connectionString;
    }

    public async Task<DataTableReader> SendDataToDatabaseAsync(byte[] data, CancellationToken cancellationToken) {
        using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync();
        using var command = new SqlCommand("sp_InsertData", connection);
        command.CommandType = CommandType.StoredProcedure;

        // define parameters for the stored procedure here

        try {
            var reader = await command.ExecuteReaderAsync(cancellationToken);
            return reader;
        } catch (SqlException ex) {
            Console.WriteLine("Error while inserting data: " + ex.Message);
            throw;
        } finally {
            connection.Close();
        }
    }
}
