    uv_tcp_t* client = (uv_tcp_t*)malloc(sizeof(uv_tcp_t));
    if (client == NULL) {
        log(LOGGING_LEVEL_ERROR, "Failed to allocate memory for client");
        return;
    }
    uv_ip4_addr("localhost", 80, &client->addr);
    uv_connect(client, on_connect);
}

void on_connect(uv_connect_t* connect, int status) {
    if (status < 0) {
        log(LOGGING_LEVEL_ERROR, "Connection failed: %s", uv_strerror(status));
        return;
    }

    // Perform a compatibility check for OpenSSL version 1.1.0 or higher
    if (OPENSSL_VERSION_NUMBER < 0x10101000L) {
        log(LOGGING_LEVEL_ERROR, "OpenSSL version must be at least 1.1.1");
        return;
    }

    // Use libuv for asynchronous network operations
    uv_tcp_t* client = (uv_tcp_t*)malloc(sizeof(uv_tcp_t));
    if (client == NULL) {
        log(LOGGING_LEVEL_ERROR, "Failed to allocate memory for client");
        return;
    }
    uv_ip4_addr("localhost", 80, &client->addr);
    uv_connect(client, on_connect);
}

