import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ServiceManager {
    private static final Logger logger = Logger.getLogger(ServiceManager.class.getName());
    private Map<String, ServiceInstance> instances = new ConcurrentHashMap<>();
    private List<MessageQueue> messageQueues = new ArrayList<>();

    public void startService(String serviceName) {
        // Start the service instance and add it to the map of instances
        ServiceInstance instance = new ServiceInstance(serviceName);
        instances.put(serviceName, instance);

        // Send a message to the messaging system to start the service
        MessageQueue queue = getMessageQueue(serviceName);
        queue.sendMessage("START");
    }

    public void stopService(String serviceName) {
        // Stop the service instance and remove it from the map of instances
        ServiceInstance instance = instances.get(serviceName);
        if (instance != null) {
            instance.stop();
            instances.remove(serviceName);
        }

        // Send a message to the messaging system to stop the service
        MessageQueue queue = getMessageQueue(serviceName);
        queue.sendMessage("STOP");
    }

    public void checkServiceStatus(String serviceName) {
        // Check the status of the service instance and log it
        ServiceInstance instance = instances.get(serviceName);
        if (instance != null) {
            logger.log(Level.INFO, "Service {0} is running", serviceName);
        } else {
            logger.log(Level.WARNING, "Service {0} is not running", serviceName);
        }
    }

    private MessageQueue getMessageQueue(String serviceName) {
        // Create a new message queue if one does not already exist for the service
        MessageQueue queue = messageQueues.get(serviceName);
        if (queue == null) {
            queue = new MessageQueue(serviceName);
            messageQueues.add(queue);
        }

        return queue;
    }
}

class ServiceInstance {
    private String serviceName;
    private boolean running = false;

    public ServiceInstance(String serviceName) {
        this.serviceName = serviceName;
    }

    public void start() {
        // Start the service instance and log it
        if (!running) {
            logger.log(Level.INFO, "Starting service {0}", serviceName);
            running = true;
        }
    }

    public void stop() {
        // Stop the service instance and log it
        if (running) {
            logger.log(Level.INFO, "Stopping service {0}", serviceName);
            running = false;
        }
    }
}

class MessageQueue {
    private String serviceName;
    private List<String> messages = new ArrayList<>();

    public MessageQueue(String serviceName) {
        this.serviceName = serviceName;
    }

    public void sendMessage(String message) {
        // Add the message to the queue and log it
        logger.log(Level.INFO, "Sending message {0} to service {1}", message, serviceName);
        messages.add(message);
    }
}
