public static String generateImageCaches(List<String> imageURLs) {
    StringBuilder html = new StringBuilder();
    for (String imageURL : imageURLs) {
        try {
            URL url = new URL(imageURL);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();
            int statusCode = connection.getResponseCode();
            if (statusCode == 200) {
                BufferedInputStream inputStream = new BufferedInputStream(connection.getInputStream());
                byte[] imageBytes = IOUtils.toByteArray(inputStream);
                String cacheKey = DigestUtils.md5Hex(imageURL);
                ImageCache imageCache = new ImageCache(cacheKey, imageBytes);
                html.append("<img src=\"").append(imageCache.getUrl()).append("\" alt=\"").append(imageCache.getName()).append("\"/>");
            } else {
                LOGGER.error("Error fetching image from " + url + ": " + statusCode);
            }
        } catch (IOException e) {
            LOGGER.error("Error generating image cache", e);
        }
    }
    return html.toString();
}

private static class ImageCache {
    private String key;
    private byte[] bytes;
    public ImageCache(String key, byte[] bytes) {
        this.key = key;
        this.bytes = bytes;
    }
    public String getUrl() {
        return "data:image/jpeg;base64," + Base64.getEncoder().encodeToString(bytes);
    }
    public String getName() {
        return key.substring(key.lastIndexOf("/") + 1);
    }
}
