        threadPool.emplace_back(processFile, filename);
        rateLimit();
    }

    for (auto& thread : threadPool) {
        thread.join();
    }

    // write metadata to database
}

void recursiveDirectoryTraversal(const string& directoryPath, vector<string>& filenames) {
    directoryIterator it = directoryIterator(directoryPath);
    while (it.hasNext()) {
        const fileStatus status = it.next();
        if (status.isRegularFile()) {
            filenames.push_back(status.path());
        } else if (status.isDirectory()) {
            recursiveDirectoryTraversal(status.path(), filenames);
        }
    }
}

vector<string> split(const string& str, const char delimiter) {
    vector<string> tokens;
    stringstream ss(str);
    string token;
    while (getline(ss, token, delimiter)) {
        tokens.push_back(token);
    }
    return tokens;
}

