use std::{collections::HashMap, time::Instant};

struct CompilationReport {
    path: String,
    duration: u64,
    rss_before: u64,
    rss_after: u64,
    warnings: Vec<String>,
    errors: Vec<String>,
}

fn compile_files(paths: &[String]) -> HashMap<String, CompilationReport> {
    let mut reports = HashMap::new();
    for path in paths {
        let report = compile_file(path);
        reports.insert(path.to_string(), report);
    }
    reports
}

fn compile_file(path: &str) -> CompilationReport {
    let mut rss_before = 0;
    let mut rss_after = 0;
    let mut warnings = Vec::new();
    let mut errors = Vec::new();
    let start = Instant::now();
    let result = catch_with_exit_code(|| {
        rustc_driver::run(&[path]);
    });
    if result.is_err() {
        for warning in result.warnings() {
            warnings.push(warning.to_string());
        }
        for error in result.errors() {
            errors.push(error.to_string());
        }
    } else {
        rss_before = get_rss();
        rustc_driver::run(&[path]);
        rss_after = get_rss();
    }
    let duration = start.elapsed().as_secs();
    CompilationReport {
        path: path.to_string(),
        duration,
        rss_before,
        rss_after,
        warnings,
        errors,
    }
}

