#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#include "ImageMagick.h"

// Struct to store parsed information about the TIFF image's bits per sample, sample per pixel, and compression type
typedef struct {
    uint8_t bitsPerSample;
    uint16_t samplesPerPixel;
    uint32_t compressionType;
} tiffInfo_t;

// Function to manage the dynamic conversion and analysis of image files in a production environment
void dynamicImageProcessing(const char* inputFile, const char* outputJSONFile, tiffInfo_t* info) {
    // Check if the input file exists and is a supported image type (JPEG, PNG, BMP)
    if (!fileExists(inputFile)) {
        printf("Input file %s does not exist or is not a supported image type\n", inputFile);
        return;
    }

    // Convert the input image to TIFF format using ImageMagick library
    char* tiffFile = convertToTIFF(inputFile);
    if (!tiffFile) {
        printf("Failed to convert input file %s to TIFF format\n", inputFile);
        return;
    }

    // Analyze the TIFF image to extract details on its bits per sample, sample per pixel, and compression type
    bool success = analyzeTIFF(tiffFile, info);
    if (!success) {
        printf("Failed to analyze TIFF file %s\n", tiffFile);
        return;
    }

    // Save the parsed information to the output JSON file
    writeJSONFile(outputJSONFile, info);

    // Free memory allocated by ImageMagick library for converted TIFF image
    free(tiffFile);
}

// Check if a file exists and is a supported image type (JPEG, PNG, BMP)
bool fileExists(const char* path) {
    struct stat buffer;
    return (stat(path, &buffer) == 0);
}

// Convert the input image to TIFF format using ImageMagick library
char* convertToTIFF(const char* inputFile) {
    // Initialize variables for ImageMagick command and conversion output file
    char* cmd = malloc(128 * sizeof(char));
    sprintf(cmd, "convert %s tiff:-", inputFile);
    FILE* outFile;

    // Execute ImageMagick command to convert input image to TIFF format
    outFile = popen(cmd, "r");
    if (!outFile) {
        printf("Failed to execute ImageMagick command for conversion\n");
        return NULL;
    }

    // Allocate memory for the converted TIFF image
    char* tiffFile = malloc(1024 * sizeof(char));
    size_t nBytes = fread(tiffFile, 1, 1024, outFile);
    if (nBytes == 0) {
        printf("Failed to read converted TIFF image from output file\n");
        return NULL;
    }

    // Free memory allocated by ImageMagick library for converted TIFF image
    free(cmd);
    pclose(outFile);

    return tiffFile;
}

// Analyze the TIFF image to extract details on its bits per sample, sample per pixel, and compression type
bool analyzeTIFF(const char* inputFile, tiffInfo_t* info) {
    // Initialize variables for ImageMagick command and analysis output file
    char* cmd = malloc(256 * sizeof(char));
    sprintf(cmd, "identify -format '%%b/pixel; %%c' %s", inputFile);
    FILE* outFile;

    // Execute ImageMagick command to analyze TIFF image and extract details on its bits per sample, sample per pixel, and compression type
    outFile = popen(cmd, "r");
    if (!outFile) {
        printf("Failed to execute ImageMagick command for analysis\n");
        return false;
    }

    // Read analysis output from the file and parse details on bits per sample, sample per pixel, and compression type
    char* line = malloc(256 * sizeof(char));
    size_t nBytes = fread(line, 1, 256, outFile);
    if (nBytes == 0) {
        printf("Failed to read analysis output from file\n");
        return false;
    }
    sscanf(line, "%hhu/%hu; %" SCNu32, &info->bitsPerSample, &info->samplesPerPixel, &info->compressionType);

    // Free memory allocated by ImageMagick library for analyzed TIFF image
    free(cmd);
    pclose(outFile);

    return true;
}

// Write the parsed information to the output JSON file
void writeJSONFile(const char* outputFile, tiffInfo_t* info) {
    // Initialize variables for JSON file and string buffer
    FILE* outFile = fopen(outputFile, "w");
    if (!outFile) {
        printf("Failed to open output JSON file %s\n", outputFile);
        return;
    }
    char* jsonBuffer = malloc(1024 * sizeof(char));
    size_t nBytes = 0;

    // Build JSON string buffer for the parsed information
    nBytes += sprintf(jsonBuffer, "{\"bitsPerSample\": %hhu, \"samplesPerPixel\": %hu, \"compressionType\": %" PRIu32 "}", info->bitsPerSample, info->samplesPerPixel, info->compressionType);

    // Write JSON string buffer to the output file
    fwrite(jsonBuffer, 1, nBytes, outFile);

    // Free memory allocated by JSON string buffer
    free(jsonBuffer);

    // Close output file
    fclose(outFile);
}

int main() {
    tiffInfo_t info;
