static void readInputFile(const char* filename, char** buffer) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Failed to open input file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Get the size of the file
    fseek(file, 0, SEEK_END);
    long int length = ftell(file);
    rewind(file);

    // Allocate memory for the file contents
    *buffer = (char*)malloc(length);
    if (*buffer == NULL) {
        printf("Failed to allocate memory for input file\n");
        exit(EXIT_FAILURE);
    }

    // Read the file into the buffer
    size_t read_bytes = fread(*buffer, sizeof(char), length, file);
    if (read_bytes != length) {
        printf("Failed to read input file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Close the file
    fclose(file);
}

static void parseInputFile(const char* buffer, const PokemonType pokemon_type) {
    // TODO: implement this function to parse the input file and extract the necessary information for the given Pokémon type
}

static void writeOutputFile(const char* output_buffer) {
    FILE* file = fopen("output.txt", "wb");
    if (file == NULL) {
        printf("Failed to open output file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Write the buffer to the file
    size_t write_bytes = fwrite(output_buffer, sizeof(char), strlen(output_buffer), file);
    if (write_bytes != strlen(output_buffer)) {
        printf("Failed to write output file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Close the file
    fclose(file);
}

