    std::string configFile = "config.json";
    if (argc > 1) {
        configFile = argv[1];
    }
    try {
        config.load(configFile);
    } catch (const std::exception& e) {
        LOG_ERROR("Failed to load configuration file: " << configFile);
        return -1;
    }

    // Set up server with configuration parameters
    Server server;
    server.setPort(config.getPort());
    server.setMaxConcurrentConnections(config.getMaxConcurrentConnections());
    server.setListenAddress(config.getListenAddress());
    server.setSslTlsSettings(config.getSslTlsSettings());
    server.setLoggingLevels(config.getLoggingLevels());

    // Start server in debug mode if specified
    bool debugMode = false;
    std::optional<std::string> debugArg;
    for (int i = 0; i < argc; ++i) {
        if (std::string(argv[i]) == "-d" || std::string(argv[i]) == "--debug") {
            debugMode = true;
            break;
        }
    }
    if (debugMode) {
        server.startDebug();
    } else {
        server.start();
    }

    // Wait for server to exit
    while (server.isRunning()) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    return 0;
}
