        // Start fetching configuration data from external service and caching it locally
        FetchAndCacheConfigurationDataAsync();
    }

    // Generate a random value for a given in-game event
    public int GetRandomValue(string eventName)
    {
        // Fetch the latest configuration data from cache
        var config = _cache["configuration"];

        // Use the configuration data to generate a random value
        var randomValue = GenerateRandomValue(eventName, config);

        return randomValue;
    }

    // Encrypt and decrypt Base64-encoded sensitive data using fetched encryption keys and initialization vectors (IVs)
    public string Encrypt(string unencryptedData)
    {
        // Fetch the latest encryption key from cache
        var encryptionKey = _cache["encryption_key"];

        // Use the encryption key to encrypt the data using AES-256 with PKCS#7 padding
        var encryptedData = EncryptData(unencryptedData, encryptionKey);

        return encryptedData;
    }

    public string Decrypt(string encryptedData)
    {
        // Fetch the latest encryption key from cache
        var encryptionKey = _cache["encryption_key"];

        // Use the encryption key to decrypt the data using AES-256 with PKCS#7 padding
        var decryptedData = DecryptData(encryptedData, encryptionKey);

        return decryptedData;
    }

    // Update cache with latest configuration data from external service and notify user of changes
    public void FetchAndCacheConfigurationDataAsync()
    {
        // Fetch latest configuration data from external service
        var config = GetLatestConfiguration();

        // Add the fetched configuration to the cache
        _cache["configuration"] = config;

        // Notify user of updated configuration data
        OnServerStatusChanged(new ServerStatusChangedEventArgs("Fetched and cached latest configuration data"));
    }

    // Automatically switch between primary and backup servers in case one goes down
    public void SetUpServerFailover()
    {
        // Add all available servers to the list of failover servers
        foreach (var server in GetAllAvailableServers())
        {
            _servers.Add(server);
        }
    }

    // Update cache with latest encryption key from external service and notify user of changes
    public void FetchAndCacheEncryptionKeyAsync()
    {
        // Fetch latest encryption key from external service
        var encryptionKey = GetLatestEncryptionKey();

        // Add the fetched encryption key to the cache
        _cache["encryption_key"] = encryptionKey;

        // Notify user of updated encryption key
        OnServerStatusChanged(new ServerStatusChangedEventArgs("Fetched and cached latest encryption key"));
    }

    // Event handler for server status changes
    private void OnServerStatusChanged(ServerStatusChangedEventArgs e)
    {
        ServerStatusChanged?.Invoke(this, e);
    }

    // Fetch the latest configuration data from external service
    private Configuration GetLatestConfiguration()
    {
        // Fetch the latest configuration data from external service
        var config = GetConfigurationFromExternalService();

        return config;
    }

    // Fetch the latest encryption key from external service
    private EncryptionKey GetLatestEncryptionKey()
    {
        // Fetch the latest encryption key from external service
        var encryptionKey = GetEncryptionKeyFromExternalService();

        return encryptionKey;
    }

    // Generate a random value for a given in-game event using the fetched configuration data
    private int GenerateRandomValue(string eventName, Configuration config)
    {
        // Use the configuration data to generate a random value for the given in-game event
        var randomValue = GenerateRandomValueFromConfigurationData(eventName, config);

        return randomValue;
    }

    // Encrypt and decrypt Base64-encoded sensitive data using fetched encryption keys and initialization vectors (IVs)
    private string EncryptData(string unencryptedData, EncryptionKey encryptionKey)
    {
        // Use the encryption key to encrypt the data using AES-256 with PKCS#7 padding
        var encryptedData = EncryptDataUsingAes256Pkcs7(unencryptedData, encryptionKey);

        return encryptedData;
    }

    private string DecryptData(string encryptedData, EncryptionKey encryptionKey)
    {
        // Use the encryption key to decrypt the data using AES-256 with PKCS#7 padding
        var decryptedData = DecryptDataUsingAes256Pkcs7(encryptedData, encryptionKey);

        return decryptedData;
    }

    // Initialize cache with default configuration data
    private void InitializeCache()
    {
        // Add default configuration data to the cache
        _cache["configuration"] = GetDefaultConfiguration();

        // Add default encryption key to the cache
        _cache["encryption_key"] = GetDefaultEncryptionKey();
    }

    // Fetch all available servers from external service
    private List<GameServer> GetAllAvailableServers()
    {
        // Fetch all available servers from external service
        var servers = GetAvailableServersFromExternalService();

        return servers;
    }
}
