```javascript
const DATA_WINDOW_SIZE = 100; // fixed-size window of most recent data points to keep in memory at any time
const MAX_CONCURRENT_REQUESTS = 5; // maximum number of concurrent requests to external storage system
const ERROR_HANDLING_DELAY = 5000; // delay before retrying a failed request to the external storage system

let dataWindow = []; // array to store the most recent data points
let paused = false; // flag to indicate whether the data collection process is paused or not
let currentRequests = 0; // number of concurrent requests to the external storage system
let errorCount = 0; // counter for number of errors that have occurred during data collection

function dataCollector(stream) {
  stream.on('data', async (dataPoint) => {
    if (!paused && currentRequests < MAX_CONCURRENT_REQUESTS) {
      try {
        await saveDataPointToStorage(dataPoint); // save the data point to an external storage system
        errorCount = 0; // reset the error count after successful request
      } catch (error) {
        errorCount++; // increment the error count if the request failed
        logError(`Error saving data point ${dataPoint} to external storage: ${error}`);
        if (errorCount > ERROR_HANDLING_DELAY) { // retry the request after a delay if the error count exceeds the threshold
          await wait(ERROR_HANDLING_DELAY);
          saveDataPointToStorage(dataPoint);
        }
      }
    } else {
      logInfo(`Queueing data point ${dataPoint} for later processing`); // queue the data point if the data collection process is paused or the concurrent requests limit has been reached
      dataWindow.push(dataPoint);
    }
  });
}

async function saveDataPointToStorage(dataPoint) {
  const storageSystem = getExternalStorageSystem(); // get an external storage system instance
  return new Promise((resolve, reject) => {
    storageSystem.saveDataPoint(dataPoint, (error, response) => {
      if (error) {
        reject(error);
      } else {
        resolve(response);
      }
    });
  });
}

function getExternalStorageSystem() {
  return new ExternalStorageSystem(); // get an instance of the external storage system class
}

class ExternalStorageSystem {
  async saveDataPoint(dataPoint) {
    const response = await fetch('https://example.com/save-data', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(dataPoint),
    });
    return response;
  }
}
```
