// Function to check OpenSSL version and perform runtime checks
int openssl_version_check() {
    // Get the current OpenSSL version
    const char *openssl_version = SSLeay_version(SSLEAY_VERSION);
    if (strcmp(openssl_version, "OpenSSL 1.1.0") < 0) {
        return 0;
    }
    // Perform runtime checks for different OpenSSL versions
    if (strcmp(openssl_version, "OpenSSL 1.1.0") == 0) {
        // Check for AES, Camellia, MD5, SHA, and RSA support
        if (!EVP_get_cipherbyname("aes-256-cbc")) {
            return 0;
        }
    } else if (strcmp(openssl_version, "OpenSSL 1.1.1") == 0) {
        // Check for AES, Camellia, MD5, SHA, RSA, and ECDH support
        if (!EVP_get_cipherbyname("aes-256-cbc")) {
            return 0;
        }
    } else {
        // Unsupported OpenSSL version
        return 0;
    }
    return 1;
}

