    // Read and parse the JSON configuration file
    cryptographic_configuration config;
    if (json_parse(filename, &config) < 0) {
        return -1;
    }
    // Find the specified primitive in the configuration file
    for (int i = 0; i < config.num_primitives; i++) {
        if (strcmp(config.primitives[i].name, name) == 0 && version <= config.primitives[i].version) {
            // Load the primitive using the appropriate function
            if (!strcmp(name, "AES")) {
                EVP_add_cipher(EVP_aes_256_cbc());
            } else if (!strcmp(name, "Camellia")) {
                EVP_add_cipher(EVP_camellia_256_cbc());
            } else if (!strcmp(name, "MD5")) {
                EVP_add_digest(EVP_md5());
            } else if (!strcmp(name, "SHA")) {
                EVP_add_digest(EVP_sha256());
            } else if (!strcmp(name, "RSA")) {
                RSA_add_method();
            }
            return 0;
        }
    }
    // No matching primitive found in the configuration file
    return -1;
}

// Function to add a cryptographic primitive to the tool
int add_cryptographic_primitive(const char *filename, const char *name, int version) {
    if (!openssl_version_check()) {
        return -1;
    }
    // Load the primitive from the configuration file
    if (load_cryptographic_primitive(filename, name, version) < 0) {
        return -1;
    }
    // Log the addition of the primitive
    log("Added cryptographic primitive %s-%d", name, version);
    return 0;
}

// Function to remove a cryptographic primitive from the tool
int remove_cryptographic_primitive(const char *name) {
    if (!openssl_version_check()) {
        return -1;
    }
    // Check if the primitive is loaded
    if (!EVP_get_cipherbyname(name)) {
        log("Cannot remove %s-%d, it is not loaded", name, version);
        return -1;
    }
    // Remove the primitive using the appropriate function
    if (!strcmp(name, "AES")) {
        EVP_cleanup();
    } else if (!strcmp(name, "Camellia")) {
        EVP_cleanup();
    } else if (!strcmp(name, "MD5")) {
        EVP_cleanup();
    } else if (!strcmp(name, "SHA")) {
        EVP_cleanup();
    } else if (!strcmp(name, "RSA")) {
        RSA_free();
    }
    // Log the removal of the primitive
    log("Removed cryptographic primitive %s-%d", name, version);
    return 0;
}

// Function to perform a cryptographic operation using the loaded primitives
int cryptographic_operation(const char *filename) {
    if (!openssl_version_check()) {
        return -1;
    }
    // Load all the necessary primitives from the configuration file
    for (int i = 0; i < config.num_primitives; i++) {
        load_cryptographic_primitive(filename, config.primitives[i].name, config.primitives[i].version);
    }
    // Perform the cryptographic operation using the appropriate functions
    if (!strcmp(config.primitives[0].name, "AES")) {
        EVP_EncryptInit_ex();
    } else if (!strcmp(config.primitives[0].name, "Camellia")) {
        EVP_EncryptInit_ex();
    } else if (!strcmp(config.primitives[0].name, "MD5")) {
        EVP_DigestInit_ex();
    } else if (!strcmp(config.primitives[0].name, "SHA")) {
        EVP_DigestInit_ex();
    } else if (!strcmp(config.primitives[0].name, "RSA")) {
        RSA_sign();
    }
    // Log the completion of the cryptographic operation
    log("Completed cryptographic operation using %d primitive%s", config.num_primitives, (config.num_primitives > 1) ? "s" : "");
    return 0;
}

// Function to handle a request to add a cryptographic primitive
int handle_add(const char *filename, const char *name, int version) {
    if (!openssl_version_check()) {
        return -1;
    }
    // Add the requested primitive to the tool
    if (add_cryptographic_primitive(filename, name, version) < 0) {
        log("Failed to add %s-%d", name, version);
        return -1;
    }
    return 0;
}

// Function to handle a request to remove a cryptographic primitive
int handle_remove(const char *name) {
    if (!openssl_version_check()) {
        return -1;
    }
    // Remove the requested primitive from the tool
    if (remove_cryptographic_primitive(name) < 0) {
        log("Failed to remove %s-%d", name, version);
        return -1;
    }
    return 0;
}

// Function to handle a request to perform a cryptographic operation
int handle_operation(const char *filename) {
    if (!openssl_version_check()) {
        return -1;
    }
    // Perform the requested cryptographic operation using the loaded primitives
    if (cryptographic_operation(filename) < 0) {
        log("Failed to perform cryptographic operation using %d primitive%s", config.num_primitives, (config.num_primitives > 1) ? "s" : "");
        return -1;
    }
    return 0;
}

// Main function of the tool
int main(const char *filename) {
    if (!openssl_version_check()) {
        return -1;
    }
    // Load all the necessary primitives from the configuration file
    for (int i = 0; i < config.num_primitives; i++) {
        load_cryptographic_primitive(filename, config.primitives[i].name, config.primitives[i].version);
    }
    // Perform the cryptographic operation using the appropriate functions
    if (!strcmp(config.primitives[0].name, "AES")) {
        EVP_EncryptInit_ex();
    } else if (!strcmp(config.primitives[0].name, "Camellia")) {
        EVP_EncryptInit_ex();
    } else if (!strcmp(config.primitives[0].name, "MD5")) {
        EVP_DigestInit_ex();
    } else if (!strcmp(config.primitives[0].name, "SHA")) {
        EVP_DigestInit_ex();
    } else if (!strcmp(config.primitives[0].name, "RSA")) {
        RSA_sign();
    }
    // Log the completion of the cryptographic operation
    log("Completed cryptographic operation using %d primitive%s", config.num_primitives, (config.num_primitives > 1) ? "s" : "");
    return 0;
