use std::env;
use tokio::runtime::Runtime;

struct Config {
    backend: String,
    api_endpoint: String,
}

impl Config {
    fn new(backend: &str, api_endpoint: &str) -> Self {
        Config {
            backend: backend.to_string(),
            api_endpoint: api_endpoint.to_string(),
        }
    }
}

async fn main() -> Result<(), String> {
    let args = env::args().collect::<Vec<String>>();
    if args.len() != 3 {
        return Err("Invalid number of command line arguments".to_string());
    }

    let config = Config::new(&args[1], &args[2]);
    let runtime = Runtime::new().unwrap();
    let backend = match config.backend.as_str() {
        "sqlite" => SQLiteBackend::new(),
        "postgresql" => PostgreSQLBackend::new(),
        _ => return Err("Invalid backend".to_string()),
    };

    let api_client = ApiClient::new(config.api_endpoint);

    runtime.block_on(async {
        let records = fetch_records(&backend, &api_client).await?;
        for record in records {
            backend.update_record(&record).await?;
        }
        Ok(())
    })?;

    Ok(())
}
```
