using System;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptionService
{
    private readonly Aes _aes;
    private readonly ICryptoTransform _decryptor;

    public AesCbcDecryptionService(string key, string iv)
    {
        _aes = new AesManaged();
        _aes.KeySize = 256;
        _aes.BlockSize = 128;
        _aes.Mode = CipherMode.CBC;
        _aes.Padding = PaddingMode.PKCS7;
        _decryptor = _aes.CreateDecryptor(Encoding.UTF8.GetBytes(key), Encoding.UTF8.GetBytes(iv));
    }

    public string Decrypt(string ciphertext)
    {
        byte[] cipherbytes = Convert.FromBase64String(ciphertext);
        byte[] plainbytes = _decryptor.TransformFinalBlock(cipherbytes, 0, cipherbytes.Length);
        return Encoding.UTF8.GetString(plainbytes);
    }
}
```
