```
// Log a message with a given level and format string
void log_message(int level, char *format, ...) {
    va_list args;
    char msg[MAX_MSG_LEN];

    // Lock the mutex to prevent concurrent access to logs
    pthread_mutex_lock(&lock);

    // Build the message with variable arguments
    va_start(args, format);
    vsnprintf(msg, sizeof(msg), format, args);
    va_end(args);

    // Write the message to all configured log files
    for (int i = 0; i < cfg.numfiles; i++) {
        write_log_file(cfg.files[i], level, msg);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}
```

```
// Write a message to a given log file
void write_log_file(log_file_cfg_t *file, int level, char *msg) {
    FILE *fp;
    char filename[MAX_FILENAME_LEN];
    struct stat fileinfo;
    size_t filesize;

    // Check if the log file exists and is large enough to store the message
    snprintf(filename, sizeof(filename), "%s", file->filepath);
    if (stat(filename, &fileinfo) < 0 || fileinfo.st_size >= file->maxsize) {
        // Rotate the log file if necessary
        rotate_log_file(file);
    }

    // Open the log file in append mode
    fp = fopen(filename, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", filename);
        return;
    }

    // Write the message to the log file
    fprintf(fp, "%d %s\n", level, msg);
    filesize = ftell(fp);

    // Close the log file
    fclose(fp);

    // Update the log file size
    file->maxsize = MAX(fileinfo.st_size, filesize);
}
```

```
// Rotate a log file based on its maximum size and number of rotations
void rotate_log_file(log_file_cfg_t *file) {
    char filename[MAX_FILENAME_LEN];
    struct stat fileinfo;
    int retval;

    // Check if the log file exists
    snprintf(filename, sizeof(filename), "%s", file->filepath);
    if (stat(filename, &fileinfo) < 0) {
        syslog(LOG_ERR, "Failed to rotate log file: %s", filename);
        return;
    }

    // Rotate the log file if necessary
    if (fileinfo.st_size >= file->maxsize && file->numrotations > 0) {
        retval = rename(filename, filename".1");
        if (retval < 0) {
            syslog(LOG_ERR, "Failed to rotate log file: %s", filename);
            return;
        }

        // Update the number of rotations
        file->numrotations--;
    }
}
```

```
// Release resources allocated by the logging module
void cleanup_logging(void) {
    for (int i = 0; i < cfg.numfiles; i++) {
        free(cfg.files[i]);
    }
}
