```
// Load configuration from a given configuration file
void load_configuration(const char *filename) {
    FILE *fp;
    int numfiles;
    log_file_cfg_t *files[MAX_FILES];
    char line[MAX_LINE_LEN];

    // Open the configuration file in read mode
    fp = fopen(filename, "r");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open logging configuration file: %s", filename);
        return;
    }

    // Read the number of log files from the configuration file
    fgets(line, sizeof(line), fp);
    numfiles = atoi(line);

    // Read the log file configuration for each file
    for (int i = 0; i < numfiles; i++) {
        char *filepath = NULL;
        size_t maxsize = 0;
        int numrotations = 0;

        fgets(line, sizeof(line), fp);
        sscanf(line, "%s %zu %d", filepath, &maxsize, &numrotations);
        files[i] = malloc(sizeof(log_file_cfg_t));
        if (files[i] == NULL) {
            syslog(LOG_ERR, "Failed to allocate memory for log file configuration");
            return;
        }

        strncpy(files[i]->filepath, filepath, MAX_FILENAME_LEN);
        files[i]->maxsize = maxsize;
        files[i]->numrotations = numrotations;
    }

    // Close the configuration file
    fclose(fp);
}
