            string decryptedMessage = TripleDES.Decrypt(inputKey, inputIV);

            // Check if the theme bitmap is recycled and set it to null if necessary
            if (themeBitmap != null)
            {
                themeBitmap.Dispose();
                themeBitmap = null;
            }

            // Configure the default theme directory if not already set
            if (string.IsNullOrEmpty(defaultThemeDirectory))
            {
                defaultThemeDirectory = "path/to/theme/directory";
            }

            // Parse a PNG file from the cache root directory and incorporate it into the theme cache
            Image themeBitmap = new Image();
            themeBitmap.Load(imagePath);
            themeCache[themeName] = themeBitmap;
        }
        catch (Exception e)
        {
            Debug.LogError("Failed to handle image conversion and parsing: " + e.Message);
        }
    }

    private void Start()
    {
        // Initialize the minimum value and maximum value for generating random values within a specified range
        _minValue = 0;
        _maxValue = 100;
    }

    private int GenerateRandomValue(int min, int max)
    {
        return UnityEngine.Random.Range(_minValue, _maxValue);
    }

    private void Update()
    {
        // Check if the theme bitmap is recycled and set it to null if necessary
        if (themeBitmap != null)
        {
            themeBitmap.Dispose();
            themeBitmap = null;
        }

        // Configure the default theme directory if not already set
        if (string.IsNullOrEmpty(defaultThemeDirectory))
        {
            defaultThemeDirectory = "path/to/theme/directory";
        }

        // Parse a PNG file from the cache root directory and incorporate it into the theme cache
        Image themeBitmap = new Image();
        themeBitmap.Load(imagePath);
        themeCache[themeName] = themeBitmap;
    }
}
