import os
import requests
import json
from datetime import datetime, timedelta
from typing import List, Dict
from collections import OrderedDict
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy.orm import sessionmaker
from sqlalchemy import Column, Integer, String, DateTime, Index
from sqlalchemy.ext.declarative import declarative_base
from requests.exceptions import ConnectionError, HTTPError
from ratelimit import RateLimitException, global_limits
from functools import lru_cache

app = Flask(__name__)
db = SQLAlchemy(app)
Session = sessionmaker(bind=db)

@global_limits([1000], timedelta(minutes=1))
def call_api(url: str, params: Dict[str, str]) -> requests.Response:
    try:
        return requests.get(url, params=params)
    except ConnectionError as e:
        raise RateLimitException("Network error") from e
    except HTTPError as e:
        if e.response.status_code == 429:
            raise RateLimitException("API rate limit reached") from e
        else:
            raise ValueError(f"Invalid API response: {e}") from e

class WeatherData(db.Model):
    __tablename__ = "weather_data"
    id = Column(Integer, primary_key=True)
    zipcode = Column(String)
    country_code = Column(String)
    current_temperature = Column(Float)
    forecasted_temperature = Column(Float)
    timestamp = Column(DateTime, default=datetime.utcnow())

@lru_cache(maxsize=1000)
def fetch_weather_data(zipcodes: List[str]) -> Dict[str, Any]:
    # Validate input zip codes and construct API endpoints for each API
    valid_zipcodes = [x for x in zipcodes if len(x) == 5]
    openweathermap_endpoints = [f"https://api.openweathermap.org/data/2.5/weather?zip={z}&units=metric&appid={os.environ['OPENWEATHERMAP_API_KEY']}" for z in valid_zipcodes]
    weatherstack_endpoints = [f"https://api.weatherstack.com/current?access_key={os.environ['WEATHERSTACK_API_KEY']}&query={z}" for z in valid_zipcodes]

    # Fetch data from multiple APIs and handle rate limiting and API failures
    openweathermap_responses = [call_api(url, {}) for url in openweathermap_endpoints]
    weatherstack_responses = [call_api(url, {}) for url in weatherstack_endpoints]

    # Merge responses from both APIs and handle missing data
    weather_data = []
    for response in openweathermap_responses + weatherstack_responses:
        try:
            data = json.loads(response.content)["main"]
            if "temp" in data:
                weather_data.append({"zipcode": response.url.split("?zip=")[1], "current_temperature": data["temp"], "country_code": data["sys"]["country"]})
        except (KeyError, TypeError) as e:
            pass

    # Cache fetched weather data for a set period and implement cache eviction policy based on LRU
    session = Session()
    for data in weather_data:
        try:
            current_weather = session.query(WeatherData).filter(WeatherData.zipcode == data["zipcode"]).one()
            if current_weather.timestamp < datetime.utcnow() - timedelta(hours=1):
                current_weather.current_temperature = data["current_temperature"]
                current_weather.country_code = data["country_code"]
                session.commit()
        except NoResultFound:
            weather_data.append(WeatherData(zipcode=data["zipcode"], country_code=data["country_code"], current_temperature=data["current_temperature"]))
            session.add(weather_data)
    session.commit()

    return {z: weather_data[z] for z in zipcodes}

@app.route("/weather/<zipcode>", methods=["GET"])
def get_current_weather(zipcode: str) -> Dict[str, Any]:
    # Retrieve current weather data from cache
    session = Session()
    try:
        current_weather = session.query(WeatherData).filter(WeatherData.zipcode == zipcode).one()
        return jsonify({"zipcode": zipcode, "current_temperature": current_weather.current_temperature})
    except NoResultFound:
        return jsonify({"error": f"No weather data found for {zipcode}"}), 404

@app.route("/weather/<zipcode>/forecast", methods=["GET"])
def get_forecasted_weather(zipcode: str) -> Dict[str, Any]:
    # Retrieve forecasted weather data from cache
    session = Session()
    try:
        forecasted_weather = session.query(WeatherData).filter(WeatherData.zipcode == zipcode).one()
        return jsonify({"zipcode": zipcode, "forecasted_temperature": forecasted_weather.forecasted_temperature})
    except NoResultFound:
        return jsonify({"error": f"No weather data found for {zipcode}"}), 404

@app.route("/weather/<zipcode>/history", methods=["GET"])
def get_historical_weather(zipcode: str) -> Dict[str, Any]:
    # Retrieve historical weather data from database
    session = Session()
    try:
        history = session.query(WeatherData).filter(WeatherData.zipcode == zipcode).order_by(desc(WeatherData.timestamp)).all()
        return jsonify([{"zipcode": h.zipcode, "current_temperature": h.current_temperature, "country_code": h.country_code, "timestamp": h.timestamp} for h in history])
    except NoResultFound:
        return jsonify({"error": f"No weather data found for {zipcode}"}), 404

if __name__ == "__main__":
    app.run(debug=True)

