#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <openssl/evp.h>
#include <openssl/sha.h>

// Encryption algorithm settings loaded from configuration file
typedef struct {
    char *algorithm; // Name of the encryption algorithm (e.g., "AES-256")
    unsigned int key_size; // Key size in bits (e.g., 256)
} AlgorithmSettings;

// Encryption/decryption function that takes a file path as input and returns a pointer to the encrypted/decrypted data
char *encryptDecryptFile(const char *filePath, const char *commandLineOption) {
    // Initialize OpenSSL library
    OPENSSL_init_ssl(OPENSSL_INIT_LOAD_CONFIG, NULL);

    // Load encryption settings from configuration file
    AlgorithmSettings settings;
    FILE *configFile = fopen("encryption-settings.conf", "r");
    if (configFile == NULL) {
        printf("Error: Could not open configuration file\n");
        return NULL;
    }
    fscanf(configFile, "%s %u", settings.algorithm, &settings.key_size);
    fclose(configFile);

    // Check if encryption/decryption command line option is valid
    if (strcmp(commandLineOption, "encrypt") && strcmp(commandLineOption, "decrypt")) {
        printf("Error: Invalid encryption/decryption command line option\n");
        return NULL;
    }

    // Initialize encryption/decryption algorithm and key
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: Could not create encryption/decryption context\n");
        return NULL;
    }
    int cipher = EVP_get_cipherbyname(settings.algorithm);
    if (cipher == NULL) {
        printf("Error: Invalid encryption algorithm\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    unsigned char key[settings.key_size / 8];
    memset(key, 0x00, sizeof(key)); // Initialize key with zeros

    // Read input file and encrypt/decrypt data
    FILE *inputFile = fopen(filePath, "rb");
    if (inputFile == NULL) {
        printf("Error: Could not open input file\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    size_t inputSize = 0;
    unsigned char *inputData = NULL;
    if (fread(&inputData, &inputSize, 1, inputFile) < 0) {
        printf("Error: Could not read input data\n");
        fclose(inputFile);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    fclose(inputFile);

    // Allocate memory for output buffer
    size_t outputSize = inputSize + AES_BLOCK_SIZE - (inputSize % AES_BLOCK_SIZE);
    unsigned char *outputData = malloc(sizeof(unsigned char) * outputSize);
    if (outputData == NULL) {
        printf("Error: Could not allocate memory for output buffer\n");
        EVP_CIPHER_CTX_free(ctx);
        free(inputData);
        return NULL;
    }

    // Encrypt/decrypt data and store in output buffer
    int outlen = 0;
    if (strcmp(commandLineOption, "encrypt") == 0) {
        EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
        EVP_EncryptUpdate(ctx, outputData, &outlen, inputData, inputSize);
    } else if (strcmp(commandLineOption, "decrypt") == 0) {
        EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv);
        EVP_DecryptUpdate(ctx, outputData, &outlen, inputData, inputSize);
    }
    EVP_CIPHER_CTX_free(ctx);
    free(inputData);

    // Return encrypted/decrypted data as a pointer to the output buffer
    return outputData;
}

// Main function that takes file path and encryption/decryption command line option as input
int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <file_path> <encrypt/decrypt>\n", argv[0]);
        return 1;
    }
    const char *filePath = argv[1];
    const char *commandLineOption = argv[2];

    // Call encryption/decryption function and handle potential errors
    char *encryptedData = encryptDecryptFile(filePath, commandLineOption);
    if (encryptedData == NULL) {
        printf("Error: Encryption/decryption failed\n");
        return 1;
    }

    // Print encrypted/decrypted data to console
    for (int i = 0; i < strlen(encryptedData); ++i) {
        printf("%c", encryptedData[i]);
    }
    free(encryptedData);

    return 0;
}
```
This code uses the OpenSSL library to perform encryption and decryption. The `encryptDecryptFile` function takes a file path as input, reads the contents of the file into a buffer, encrypts or decrypts the data using the specified algorithm and key size, and then returns a pointer to the encrypted/decrypted data.

The `main` function is responsible for handling command line arguments and calling the `encryptDecryptFile` function with the appropriate parameters. It also handles potential errors during file reading, encryption/decryption processes, and memory management.

Note that this code assumes that the configuration file "encryption-settings.conf" is located in the same directory as the executable. The configuration file should contain the name of the encryption algorithm and the key size, for example:
```c
AES-256 256
