    int bits; // Number of bits used by the primitive
} Primitive;

// Define an array to hold information about all available cryptographic primitives
Primitive prim[MAX_PRIMITIVES];

// Define a function to initialize the system and load configuration data from an external file
void init() {
    // Load configuration data from an external file using the third-party dependency management system (e.g., Conan, vcpkg)
    FILE* configFile = fopen("config.json", "r");
    if (configFile == NULL) {
        printf("Error: Unable to open configuration file\n");
        return;
    }

    // Load the configuration data into an array using a JSON parser (e.g., JSON for Modern C++)
    json_t* config = json_loadf(configFile, 0, NULL);
    if (config == NULL) {
        printf("Error: Unable to parse configuration file\n");
        return;
    }

    // Extract the information about available cryptographic primitives from the configuration data
    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        json_t* primitive = json_array_get(config, i);
        if (primitive == NULL) {
            break;
        }

        prim[i].type = json_object_get_int(primitive, "type");
        prim[i].bits = json_object_get_int(primitive, "bits");
    }

    // Check if any cryptographic primitives were found in the configuration file
    if (i == 0) {
        printf("Error: No cryptographic primitives found in configuration file\n");
        return;
    }

    // Close the configuration file and perform additional setup tasks as needed
    fclose(configFile);
}

// Define a function to add or remove a cryptographic primitive from the system
void addRemovePrimitive(int type, int bits) {
    // Check if the requested cryptographic primitive is available in the configuration data
    bool found = false;
    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        if (prim[i].type == type && prim[i].bits == bits) {
            found = true;
            break;
        }
    }

    // If the requested cryptographic primitive is not available, return an error message
    if (!found) {
        printf("Error: The requested cryptographic primitive is not available\n");
        return;
    }

    // Load the selected cryptographic primitive into the system using the third-party dependency management system (e.g., Conan, vcpkg)
    FILE* libraryFile = fopen(prim[i].type == AES ? "libcrypto_aes.so" : "libcrypto_camellia.so", "r");
    if (libraryFile == NULL) {
        printf("Error: Unable to open library file for requested cryptographic primitive\n");
        return;
    }

    // Load the selected cryptographic primitive into the system using a dynamic loader (e.g., dlopen() on Linux)
    void* handle = dlopen(libraryFile, RTLD_NOW | RTLD_LOCAL);
    if (handle == NULL) {
        printf("Error: Unable to load library file for requested cryptographic primitive\n");
        return;
    }

    // Close the configuration file and perform additional setup tasks as needed
    fclose(libraryFile);
}

// Define a function to encrypt data using a selected cryptographic primitive
void encrypt(int type, int bits, const char* plaintext) {
    // Check if the requested cryptographic primitive is available in the configuration data
    bool found = false;
    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        if (prim[i].type == type && prim[i].bits == bits) {
            found = true;
            break;
        }
    }

    // If the requested cryptographic primitive is not available, return an error message
    if (!found) {
        printf("Error: The requested cryptographic primitive is not available\n");
        return;
    }

    // Load the selected cryptographic primitive into the system using the third-party dependency management system (e.g., Conan, vcpkg)
    FILE* libraryFile = fopen(prim[i].type == AES ? "libcrypto_aes.so" : "libcrypto_camellia.so", "r");
    if (libraryFile == NULL) {
        printf("Error: Unable to open library file for requested cryptographic primitive\n");
        return;
    }

    // Load the selected cryptographic primitive into the system using a dynamic loader (e.g., dlopen() on Linux)
    void* handle = dlopen(libraryFile, RTLD_NOW | RTLD_LOCAL);
    if (handle == NULL) {
        printf("Error: Unable to load library file for requested cryptographic primitive\n");
        return;
    }

    // Call the selected encryption function using the loaded library (e.g., AES_encrypt() or Camellia_encrypt())
    void (*encryptFunction)(unsigned char*, unsigned char*, int) = dlsym(handle, "encrypt");
    if (encryptFunction == NULL) {
        printf("Error: Unable to find encryption function for requested cryptographic primitive\n");
        return;
    }

    // Encrypt the plaintext using the selected encryption function and output the ciphertext
    unsigned char* plaintextBytes = (unsigned char*)plaintext;
    unsigned char* ciphertextBytes = (unsigned char*)malloc(sizeof(char) * (bits / 8));
    encryptFunction(ciphertextBytes, plaintextBytes, bits / 8);

    // Output the ciphertext to stdout as a hexadecimal string
    printf("%s\n", ciphertextBytes);

    // Close the library file and perform additional cleanup tasks as needed
    fclose(libraryFile);
}

// Define a function to decrypt data using a selected cryptographic primitive
void decrypt(int type, int bits, const char* ciphertext) {
    // Check if the requested cryptographic primitive is available in the configuration data
    bool found = false;
    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        if (prim[i].type == type && prim[i].bits == bits) {
            found = true;
            break;
        }
    }

    // If the requested cryptographic primitive is not available, return an error message
    if (!found) {
        printf("Error: The requested cryptographic primitive is not available\n");
        return;
    }

    // Load the selected cryptographic primitive into the system using the third-party dependency management system (e.g., Conan, vcpkg)
    FILE* libraryFile = fopen(prim[i].type == AES ? "libcrypto_aes.so" : "libcrypto_camellia.so", "r");
    if (libraryFile == NULL) {
        printf("Error: Unable to open library file for requested cryptographic primitive\n");
        return;
    }

    // Load the selected cryptographic primitive into the system using a dynamic loader (e.g., dlopen() on Linux)
    void* handle = dlopen(libraryFile, RTLD_NOW | RTLD_LOCAL);
    if (handle == NULL) {
        printf("Error: Unable to load library file for requested cryptographic primitive\n");
        return;
    }

    // Call the selected decryption function using the loaded library (e.g., AES_decrypt() or Camellia_decrypt())
    void (*decryptFunction)(unsigned char*, unsigned char*, int) = dlsym(handle, "decrypt");
    if (decryptFunction == NULL) {
        printf("Error: Unable to find decryption function for requested cryptographic primitive\n");
        return;
    }

    // Decrypt the ciphertext using the selected decryption function and output the plaintext
    unsigned char* ciphertextBytes = (unsigned char*)ciphertext;
    unsigned char* plaintextBytes = (unsigned char*)malloc(sizeof(char) * (bits / 8));
    decryptFunction(plaintextBytes, ciphertextBytes, bits / 8);

    // Output the plaintext to stdout as a hexadecimal string
    printf("%s\n", plaintextBytes);

    // Close the library file and perform additional cleanup tasks as needed
    fclose(libraryFile);
}
