import json
import os
import sys
import time
from datetime import datetime
from paho.mqtt import client as mqtt_client
from statistics import mean, median, stdev
from typing import List, Dict, Any

def main():
    # Parse command-line arguments
    args = parse_args()

    # Set up MQTT connection
    mqtt_client = init_mqtt(args.broker_host, args.broker_port)

    # Set up logging
    log_file = open(args.log_path, "a")

    # Set up data processing
    device_ids = args.device_ids.split(",")
    filtering_criteria = args.filtering_criteria.split(",")
    output_files = {id: open(f"{args.output_dir}/{id}.txt", "w") for id in device_ids}

    # Set up anomaly detection
    anomaly_types = load_anomaly_types()

    while True:
        try:
            mqtt_client.connect(args.broker_host, args.broker_port)
            break
        except ConnectionRefusedError as e:
            time.sleep(1)

    # Start processing data
    for message in mqtt_client.iter_messages():
        try:
            message = json.loads(message.payload)
        except json.JSONDecodeError:
            print("Invalid JSON received from MQTT broker. Disconnecting...")
            break

        device_id = message["deviceId"]
        if device_id not in device_ids:
            continue

        energy_consumption = message["energyConsumption"]
        timestamp = datetime.utcfromtimestamp(message["timestamp"])

        # Filter data according to specified criteria
        filtered_data = filter_data(energy_consumption, filtering_criteria)

        # Calculate statistical metrics
        mean_value = mean(filtered_data)
        median_value = median(filtered_data)
        standard_deviation = stdev(filtered_data)

        # Log data to output files
        output_files[device_id].write(f"{timestamp}, {mean_value}, {median_value}, {standard_deviation}\n")

        # Check for anomalies
        for anomaly_type in anomaly_types:
            if check_anomaly(filtered_data, anomaly_type):
                log_anomaly(device_id, timestamp, anomaly_type, args.log_path)

    mqtt_client.disconnect()

def parse_args():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--broker-host", default="localhost")
    parser.add_argument("--broker-port", type=int, default=1883)
    parser.add_argument("--device-ids", required=True)
    parser.add_argument("--filtering-criteria", required=True)
    parser.add_argument("--output-dir", required=True)
    parser.add_argument("--log-path", required=True)
    return parser.parse_args()

def init_mqtt(broker_host, broker_port):
    mqtt_client = mqtt_client.Client()
    mqtt_client.connect(broker_host, broker_port)
    mqtt_client.subscribe("iot-data")
    return mqtt_client

def filter_data(energy_consumption: List[float], filtering_criteria: str) -> List[float]:
    filtered_data = []
    for value in energy_consumption:
        if filtering_criteria == "greater than":
            if value > 0.5:
                filtered_data.append(value)
        elif filtering_criteria == "less than":
            if value < 0.1:
                filtered_data.append(value)
        else:
            raise ValueError("Invalid filtering criteria")
    return filtered_data

def check_anomaly(energy_consumption: List[float], anomaly_type: str) -> bool:
    if anomaly_type == "sudden spike":
        return any(value > 1.5 for value in energy_consumption)
    elif anomaly_type == "gradual increase":
        return any(value > 0.75 for value in energy_consumption)
    else:
        raise ValueError("Invalid anomaly type")

def log_anomaly(device_id: str, timestamp: datetime, anomaly_type: str, log_path: str):
    with open(log_path, "a") as f:
        f.write(f"{device_id}, {timestamp}, {anomaly_type}\n")

def load_anomaly_types() -> Dict[str, str]:
    # Load predefined anomaly types and descriptions from a file or database
    return {
        "sudden spike": "A sudden increase in energy consumption",
        "gradual increase": "A gradual increase in energy consumption over time"
    }
```

