namespace AESDecryptionWithKeyManagementService
{
    /// <summary>
    /// Securely decrypts ciphertext using AES-GCM with an external key management service.
    /// </summary>
    public class Decrypter
    {
        private const string KEY_ID = "my-key";
        private const string IV_ID = "my-iv";
        private static readonly Encoding ENCODING = Encoding.UTF8;

        // Cache for key and IV fetching results to reduce external service calls.
        private static Dictionary<string, KeyAndIV> _cache = new Dictionary<string, KeyAndIV>();

        /// <summary>
        /// Decrypts the given ciphertext using AES-GCM with an external key management service.
        /// </summary>
        /// <param name="ciphertext">The ciphertext to be decrypted.</param>
        /// <returns>The decrypted plaintext as a string, or null if decryption failed.</returns>
        public static string Decrypt(byte[] ciphertext)
        {
            // Fetch the key and IV from the external service using caching.
            KeyAndIV cacheResult = GetKeyAndIVFromCache();
            if (cacheResult == null)
            {
                return null;
            }

            try
            {
                AesGcm aes = new AesGcm(cacheResult.Key);
                aes.IV = cacheResult.IV;

                // Use the appropriate padding mode based on the input ciphertext length.
                int plaintextLength = ENCODING.GetByteCount(ciphertext);
                byte[] paddingMode = GetPaddingMode(plaintextLength);
                aes.PaddingMode = (AesGcmPaddingMode)paddingMode;

                // Decrypt the ciphertext and verify the authentication tag.
                byte[] plaintext = aes.Decrypt(ciphertext, ENCODING.GetBytes(cacheResult.IV), out byte[] tag);
                if (VerifyAuthenticationTag(tag))
                {
                    return ENCODING.GetString(plaintext);
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Decryption failed: {e.Message}");
            }

            return null;
        }

        /// <summary>
        /// Gets the key and IV from the external service using caching.
        /// </summary>
        private static KeyAndIV GetKeyAndIVFromCache()
        {
            // Check if the cache already has the necessary key and IV.
            if (_cache.TryGetValue(KEY_ID, out KeyAndIV key))
            {
                return key;
            }

            // If not, fetch the key and IV from the external service and add them to the cache.
            try
            {
                string response = ExternalServiceCall();
                if (response == null)
                {
                    return null;
                }

                string[] keysAndIVs = response.Split(' ');
                _cache[KEY_ID] = new KeyAndIV(keysAndIVs[0], keysAndIVs[1]);
            }
            catch (Exception e)
            {
                Console.WriteLine($"Key and IV fetch failed: {e.Message}");
            }

            return _cache.TryGetValue(KEY_ID, out KeyAndIV key) ? key : null;
        }

        /// <summary>
        /// Gets the padding mode based on the input ciphertext length.
        /// </summary>
        private static byte[] GetPaddingMode(int plaintextLength)
        {
            if (plaintextLength > 1024)
            {
