using System;
using System.Security.Cryptography;
using System.Threading;
using System.Collections.Generic;

public class DynamicSecureRandomGenerator {
    private static readonly Dictionary<int, int> _randomValues = new Dictionary<int, int>();
    private static readonly object _lock = new object();
    private static readonly Random _rand = new Random();

    public static int Next(int minValue, int maxValue) {
        int value;

        if (_randomValues.TryGetValue(minValue, out value)) {
            return value;
        } else {
            lock(_lock) {
                value = _rand.Next(minValue, maxValue);
                _randomValues[minValue] = value;
                return value;
            }
        }
    }

    public static double NextDouble() {
        return _rand.NextDouble();
    }

    public static int[] GenerateRandomIntegers(int minValue, int maxValue, int count) {
        int[] values = new int[count];

        for (int i = 0; i < count; i++) {
            values[i] = Next(minValue, maxValue);
        }

        return values;
    }

    public static double[] GenerateRandomDoubles(double minValue, double maxValue, int count) {
        double[] values = new double[count];

        for (int i = 0; i < count; i++) {
            values[i] = NextDouble() * (maxValue - minValue) + minValue;
        }

        return values;
    }
}

public class SecureRandomNumberGenerator : DynamicSecureRandomGenerator {
    private static readonly Dictionary<int, int> _randomValues = new Dictionary<int, int>();
    private static readonly object _lock = new object();
    private static readonly AesGcmCipher _cipher;

    public SecureRandomNumberGenerator(string password) {
        _cipher = new AesGcmCipher(password);
    }

    public int Next(int minValue, int maxValue) {
        int value;

        if (_randomValues.TryGetValue(minValue, out value)) {
            return value;
        } else {
            lock(_lock) {
                value = _cipher.GenerateRandomNumber(minValue, maxValue);
                _randomValues[minValue] = value;
                return value;
            }
        }
    }

    public double NextDouble() {
        return _cipher.GenerateRandomNumber(0, 1) * (maxValue - minValue) + minValue;
    }

    public int[] GenerateRandomIntegers(int minValue, int maxValue, int count) {
        int[] values = new int[count];

        for (int i = 0; i < count; i++) {
            values[i] = Next(minValue, maxValue);
        }

        return values;
    }

    public double[] GenerateRandomDoubles(double minValue, double maxValue, int count) {
        double[] values = new double[count];

        for (int i = 0; i < count; i++) {
            values[i] = NextDouble() * (maxValue - minValue) + minValue;
        }

        return values;
    }
}

public class AesGcmCipher {
    private readonly string _password;
    private readonly byte[] _salt;
    private readonly HashAlgorithmName _hashAlgorithm;
    private readonly SymmetricAlgorithm _algorithm;

    public AesGcmCipher(string password) {
        if (String.IsNullOrEmpty(password)) {
            throw new ArgumentException("Password is required", nameof(password));
        }

        _password = password;
        _salt = GetRandomSalt();
        _hashAlgorithm = HashAlgorithmName.SHA256;
        _algorithm = AesGcm.Create();
    }

    public int GenerateRandomNumber(int minValue, int maxValue) {
        int value;

        try {
            byte[] iv = GetRandomIv();
            using (var encryptor = _algorithm.CreateEncryptor()) {
                var ciphertext = Encrypt(minValue, maxValue, iv, encryptor);
                using (var decryptor = _algorithm.CreateDecryptor()) {
                    value = Decrypt(ciphertext, iv, decryptor);
                }
            }
        } catch (Exception e) {
            throw new InvalidOperationException("Failed to generate random number", e);
        }

        return value;
    }

    public double GenerateRandomNumber(double minValue, double maxValue) {
        double value;

        try {
            byte[] iv = GetRandomIv();
            using (var encryptor = _algorithm.CreateEncryptor()) {
                var ciphertext = Encrypt(minValue, maxValue, iv, encryptor);
                using (var decryptor = _algorithm.CreateDecryptor()) {
                    value = Decrypt(ciphertext, iv, decryptor);
                }
            }
        } catch (Exception e) {
            throw new InvalidOperationException("Failed to generate random number", e);
        }

        return value;
    }
}
