namespace AdvancedRandomValueGenerator
{
    public class RandomValueGenerator
    {
        private float _minValue;
        private float _maxValue;
        private bool _isUniformDistribution;
        private bool _isNormalDistribution;
        private bool _isCustomDistribution;
        private NormalDistribution _normalDistribution;
        private CustomDistribution _customDistribution;
        private ConcurrentDictionary<string, float[]> _cache;
        private object _lock = new object();

        public RandomValueGenerator(float minValue, float maxValue)
            : this(minValue, maxValue, false)
        {
        }

        public RandomValueGenerator(float minValue, float maxValue, bool isUniformDistribution)
        {
            if (minValue >= maxValue)
            {
                throw new ArgumentException("Minimum value must be less than maximum value.");
            }

            _minValue = minValue;
            _maxValue = maxValue;
            _isUniformDistribution = isUniformDistribution;
            _isNormalDistribution = false;
            _isCustomDistribution = false;
            _normalDistribution = new NormalDistribution();
            _customDistribution = new CustomDistribution();
            _cache = new ConcurrentDictionary<string, float[]>();
        }

        public RandomValueGenerator(float minValue, float maxValue, bool isUniformDistribution, bool isNormalDistribution)
        {
            if (minValue >= maxValue)
            {
                throw new ArgumentException("Minimum value must be less than maximum value.");
            }

            _minValue = minValue;
            _maxValue = maxValue;
            _isUniformDistribution = isUniformDistribution;
            _isNormalDistribution = isNormalDistribution;
            _isCustomDistribution = false;
            _normalDistribution = new NormalDistribution();
            _customDistribution = new CustomDistribution();
            _cache = new ConcurrentDictionary<string, float[]>();
        }

        public RandomValueGenerator(float minValue, float maxValue, bool isUniformDistribution, bool isNormalDistribution, float mean, float standardDeviation)
        {
            if (minValue >= maxValue)
            {
                throw new ArgumentException("Minimum value must be less than maximum value.");
            }

            _minValue = minValue;
            _maxValue = maxValue;
            _isUniformDistribution = isUniformDistribution;
            _isNormalDistribution = isNormalDistribution;
            _isCustomDistribution = false;
            _normalDistribution = new NormalDistribution(mean, standardDeviation);
            _customDistribution = new CustomDistribution();
            _cache = new ConcurrentDictionary<string, float[]>();
        }

        public RandomValueGenerator(float minValue, float maxValue, bool isUniformDistribution, bool isNormalDistribution, float mean, float standardDeviation, Func<float, float> customDistribution)
        {
            if (minValue >= maxValue)
            {
                throw new ArgumentException("Minimum value must be less than maximum value.");
            }

            _minValue = minValue;
            _maxValue = maxValue;
            _isUniformDistribution = isUniformDistribution;
            _isNormalDistribution = isNormalDistribution;
            _isCustomDistribution = true;
            _normalDistribution = new NormalDistribution(mean, standardDeviation);
            _customDistribution = new CustomDistribution(customDistribution);
            _cache = new ConcurrentDictionary<string, float[]>();
        }

        public static RandomValueGenerator Default()
        {
            return new RandomValueGenerator(0.0f, 1.0f);
        }

        public static RandomValueGenerator Uniform(float minValue, float maxValue)
        {
            return new RandomValueGenerator(minValue, maxValue, true);
        }

        public static RandomValueGenerator Normal(float mean, float standardDeviation)
        {
            return new RandomValueGenerator(mean, standardDeviation, true, false);
        }

        public static RandomValueGenerator Custom(float minValue, float maxValue, Func<float, float> customDistribution)
        {
            return new RandomValueGenerator(minValue, maxValue, false, false, mean, standardDeviation, customDistribution);
        }

        public void Seed(int seed)
        {
            if (seed < 0)
            {
                throw new ArgumentException("Seed must be a positive integer.");
            }

            _normalDistribution.Seed(seed);
            _customDistribution.Seed(seed);
        }

        public float NextFloat()
        {
            if (_isUniformDistribution)
            {
                return (float)(_minValue + ((double)_maxValue - _minValue) * _random.NextDouble());
            }
            else if (_isNormalDistribution)
            {
                return (float)(_normalDistribution.Sample());
            }
            else if (_isCustomDistribution)
            {
                return (float)_customDistribution.Sample();
            }
            else
            {
                throw new InvalidOperationException("No distribution has been set.");
            }
        }

        public int NextInt(int minValue, int maxValue)
        {
            if (_isUniformDistribution)
            {
                return _random.Next(minValue, maxValue + 1);
            }
            else
            {
                throw new InvalidOperationException("Random value generation is not supported for integer distributions.");
            }
        }

        public double NextDouble()
        {
            if (_isUniformDistribution)
            {
                return _random.NextDouble();
            }
            else
            {
                throw new InvalidOperationException("Random value generation is not supported for double distributions.");
            }
        }

        public float NextFloat(float minValue, float maxValue)
        {
            if (_isUniformDistribution)
            {
                return (float)(minValue + ((double)maxValue - minValue) * _random.NextDouble());
            }
            else
            {
                throw new InvalidOperationException("Random value generation is not supported for float distributions.");
            }
        }

        public int NextInt(int maxValue)
        {
            if (_isUniformDistribution)
            {
                return _random.Next(maxValue + 1);
            }
            else
            {
                throw new InvalidOperationException("Random value generation is not supported for integer distributions.");
            }
        }

        public float Sample()
        {
            return NextFloat();
        }

        public void Cache(int size)
        {
            _cache = new ConcurrentQueue<float>();
            for (int i = 0; i < size; i++)
            {
                _cache.Enqueue(NextFloat());
            }
        }

        public float Peek()
        {
            if (_cache.Count > 0)
            {
                return _cache.Peek();
            }
            else
            {
                throw new InvalidOperationException("Cache is empty.");
            }
        }

        public float Pop()
        {
            if (_cache.Count > 0)
            {
                float value = _cache.Dequeue();
                _cache.Enqueue(NextFloat());
                return value;
            }
            else
            {
                throw new InvalidOperationException("Cache is empty.");
            }
        }

        public void Clear()
        {
            if (_cache != null)
            {
                _cache = new ConcurrentQueue<float>();
            }
        }

        public override string ToString()
        {
            return $"{{{typeof(RandomValueGenerator)}: distribution={_distribution}, mean={_mean}, standardDeviation={_standardDeviation}}}";
        }
    }
}
