    private const string OPENWEATHERMAP_API_KEY = "YOUR_OPENWEATHERMAP_API_KEY";

    // Historical weather API URL
    private const string HISTORICAL_WEATHER_API_URL = "https://api.openweathermap.org/data/2.5/history?appid=" + OPENWEATHERMAP_API_KEY;

    // Forecast weather API URL
    private const string FORECAST_WEATHER_API_URL = "https://api.openweathermap.org/data/2.5/forecast?appid=" + OPENWEATHERMAP_API_KEY;

    // Token bucket algorithm parameters
    private const int TOKEN_BUCKET_SIZE = 10;
    private const int TOKENS_PER_SECOND = 3;

    // Union-Find data structure for disjointness check
    private readonly UnionFind unionFind = new UnionFind();

    // Cache for current weather data
    private Dictionary<string, WeatherData> currentWeatherCache = new Dictionary<string, WeatherData>();

    // Cache for historical weather data
    private Dictionary<string, List<WeatherData>> historicalWeatherCache = new Dictionary<string, List<WeatherData>>();

    // Cache for forecast weather data
    private Dictionary<string, List<WeatherData>> forecastWeatherCache = new Dictionary<string, List<WeatherData>>();

    public void Start()
    {
        InitializeMongoClient();
        StartTokenBucketAlgorithm();
    }

    // Initialize MongoDB client
    private void InitializeMongoClient()
    {
        // Connect to MongoDB using the connection string
        var mongoClient = new MongoClient(MONGO_CONNECTION_STRING);
        var database = mongoClient.GetDatabase("weather_data");
        var collection = database.GetCollection<WeatherData>("weather_data");

        // Create indexes on the collection for efficiency
        collection.CreateIndex(Builders<WeatherData>.IndexKeys.Ascending(x => x.City));
        collection.CreateIndex(Builders<WeatherData>.IndexKeys.Ascending(x => x.Timestamp));
    }

    // Start token bucket algorithm for rate limiting
    private void StartTokenBucketAlgorithm()
    {
        var tokenBucket = new TokenBucket(TOKEN_BUCKET_SIZE, TOKENS_PER_SECOND);
        tokenBucket.Start();
    }

    // Handles HTTP requests for weather data
    public void HandleRequests()
    {
        var request = UnityWebRequest.Get("http://localhost:8080/weather");
        yield return request.SendWebRequest();

        if (request.isNetworkError)
        {
            Debug.LogError(request.error);
            return;
        }

        var response = JsonConvert.DeserializeObject<WeatherResponse>(request.downloadHandler.text);
        HandleWeatherData(response);
    }

    // Handles incoming weather data and stores it in the cache
    private void HandleWeatherData(WeatherResponse response)
    {
        foreach (var city in response.Cities)
        {
            var coordinates = string.Join(",", city.Coordinates);
            var currentWeather = GetCurrentWeather(coordinates);
            var historicalWeather = GetHistoricalWeather(coordinates);
            var forecastWeather = GetForecastWeather(coordinates);

            // Store the weather data in the cache
            currentWeatherCache[coordinates] = currentWeather;
            historicalWeatherCache[coordinates] = historicalWeather;
            forecastWeatherCache[coordinates] = forecastWeather;
        }
    }

    // Gets current weather data for a given city
    private WeatherData GetCurrentWeather(string coordinates)
    {
        var cacheHit = currentWeatherCache.TryGetValue(coordinates, out WeatherData currentWeather);

        if (cacheHit)
        {
            // Use the cached data if it's still valid
            if (currentWeather.IsValid())
            {
                return currentWeather;
            }
            else
            {
                // Invalidate the cache entry and fetch fresh data
                currentWeatherCache.Remove(coordinates);
            }
        }

        var url = string.Format("{0}{1}", FORECAST_WEATHER_API_URL, coordinates);
        var request = UnityWebRequest.Get(url);
        yield return request.SendWebRequest();

        if (request.isNetworkError)
        {
            Debug.LogError(request.error);
            return new WeatherData();
        }

        var response = JsonConvert.DeserializeObject<WeatherResponse>(request.downloadHandler.text);
        currentWeather = GetCurrentWeather(coordinates, response);

        // Store the fresh data in the cache
        currentWeatherCache[coordinates] = currentWeather;

        return currentWeather;
    }

    // Gets historical weather data for a given city
    private List<WeatherData> GetHistoricalWeather(string coordinates)
    {
        var cacheHit = historicalWeatherCache.TryGetValue(coordinates, out List<WeatherData> historicalWeather);

        if (cacheHit)
        {
            // Use the cached data if it's still valid
            if (historicalWeather.Any())
            {
                return historicalWeather;
            }
            else
            {
                // Invalidate the cache entry and fetch fresh data
                historicalWeatherCache.Remove(coordinates);
            }
        }

        var url = string.Format("{0}{1}", HISTORICAL_WEATHER_API_URL, coordinates);
        var request = UnityWebRequest.Get(url);
        yield return request.SendWebRequest();

        if (request.isNetworkError)
        {
            Debug.LogError(request.error);
            return new List<WeatherData>();
        }

        var response = JsonConvert.DeserializeObject<HistoricalWeatherResponse>(request.downloadHandler.text);
        historicalWeather = GetHistoricalWeather(coordinates, response);

        // Store the fresh data in the cache
        historicalWeatherCache[coordinates] = historicalWeather;

        return historicalWeather;
    }

    // Gets forecasted weather data for a given city
    private List<WeatherData> GetForecastWeather(string coordinates)
    {
        var cacheHit = forecastWeatherCache.TryGetValue(coordinates, out List<WeatherData> forecastWeather);

        if (cacheHit)
        {
            // Use the cached data if it's still valid
            if (forecastWeather.Any())
            {
                return forecastWeather;
            }
            else
            {
                // Invalidate the cache entry and fetch fresh data
                forecastWeatherCache.Remove(coordinates);
            }
        }

        var url = string.Format("{0}{1}", FORECAST_WEATHER_API_URL, coordinates);
        var request = UnityWebRequest.Get(url);
        yield return request.SendWebRequest();

        if (request.isNetworkError)
        {
            Debug.LogError(request.error);
            return new List<WeatherData>();
        }

        var response = JsonConvert.DeserializeObject<ForecastWeatherResponse>(request.downloadHandler.text);
        forecastWeather = GetForecastWeather(coordinates, response);

        // Store the fresh data in the cache
        forecastWeatherCache[coordinates] = forecastWeather;

        return forecastWeather;
    }

    // Validates weather data by checking if it's still within a certain range of time
    private bool IsValid(WeatherData weatherData)
    {
        var now = DateTime.UtcNow;
        var diff = Mathf.Abs((weatherData.Timestamp - now).TotalMinutes);

        return diff < 10;
    }
}

