// Token bucket rate limiter class
[Serializable]
public class TokenBucket
{
    public float BucketSize { get; set; }
    public float TokensPerSecond { get; set; }
    public int MaxTokens { get; set; }

    private Queue<float> tokens;
    private float lastUpdateTime;
    private bool isActive;

    public TokenBucket(float bucketSize, float tokensPerSecond)
    {
        BucketSize = bucketSize;
        TokensPerSecond = tokensPerSecond;
        MaxTokens = (int)(bucketSize / tokensPerSecond);
        tokens = new Queue<float>();
        lastUpdateTime = Time.time;
        isActive = false;
    }

    public void Start()
    {
        isActive = true;
    }

    public bool TryAddToken(int amount)
    {
        if (!isActive)
        {
            return false;
        }

        var currentTime = Time.time;
        var dt = currentTime - lastUpdateTime;
        var tokensPerDT = TokensPerSecond * dt;

        for (var i = 0; i < amount; i++)
        {
            if (!tokens.Any() && tokens.Count < MaxTokens)
            {
                tokens.Enqueue(1);
            }
            else if (tokens.Any())
            {
                var token = tokens.Dequeue();
                tokens.Enqueue(token + tokensPerDT);
            }
        }

        lastUpdateTime = currentTime;

        return true;
    }
}

