using System;
using System.Collections.Concurrent;
using System.Threading;

public class AdvancedRandomValueGenerator
{
    // Private fields
    private float minValue;
    private float maxValue;
    private bool generateType;
    private static readonly Random random = new Random();
    private static readonly ConcurrentDictionary<string, List<float>> cache = new ConcurrentDictionary<string, List<float>>();

    // Constructor with default values
    public AdvancedRandomValueGenerator() : this(0.0f, 1.0f, false) { }

    // Constructor with custom arguments
    public AdvancedRandomValueGenerator(float minValue, float maxValue, bool generateType)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Minimum value cannot be greater than or equal to maximum value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.generateType = generateType;
    }

    // Method to return a random float value within the specified range
    public float GetRandomFloat() => GetRandomValue(false);

    // Method to return a random int value within the specified range
    public int GetRandomInt() => (int)GetRandomValue(true);

    // Method to return a random double value within the specified range
    public double GetRandomDouble() => (double)GetRandomValue(false);

    // Method to seed the random number generator with a given value
    public void Seed(int seed) => random.Seed(seed);

    // Method to generate random values from a normal distribution centered around the specified range
    public float GetRandomNormalDistribution() => (float)(random.NextDouble() * maxValue - minValue);

    // Method to apply custom probability density functions for generating random values
    public float GetCustomPDF(Func<float, float> pdf) => (float)(pdf(GetRandomFloat()));

    // Private method to generate a random value within the specified range
    private object GetRandomValue(bool integer)
    {
        if (generateType == GenerateType.Uniform)
            return RandomRange(minValue, maxValue);
        else if (generateType == GenerateType.Normal)
            return GetRandomNormalDistribution();
        else if (generateType == GenerateType.Custom)
            throw new NotImplementedException("Custom distribution is not yet implemented.");
        else if (generateType == GenerateType.Weighted)
            throw new NotImplementedException("Weighted distribution is not yet implemented.");
    }

    // Private method to generate a random value within the specified range using caching
    private object GetRandomValueWithCache(bool integer)
    {
        var cacheKey = $"{minValue}-{maxValue}_{integer}";
        if (!cache.TryGetValue(cacheKey, out List<float> cachedValues))
        {
            lock (cache)
            {
                // Generate and cache new values when there are no pre-generated sequences available
                cachedValues = new List<float>();
                for (int i = 0; i < 1000; i++)
                    cachedValues.Add(RandomRange(minValue, maxValue));
                cache[cacheKey] = cachedValues;
            }
        }

        // Return a random value from the pre-generated sequence
        lock (cachedValues)
        {
            return cachedValues[random.Next(0, cachedValues.Count)];
        }
    }

    // Enum for generate type options
    public enum GenerateType
    {
        Uniform = 1,
        Normal = 2,
        Custom = 3,
        Weighted = 4
    }

    // Helper method to generate a random value within the specified range using System.Random
    private static float RandomRange(float minValue, float maxValue) => (float)(random.NextDouble() * (maxValue - minValue) + minValue);

    // Overriding ToString method to display current range, generation type, and additional details
    public override string ToString()
    {
        var builder = new StringBuilder();
        builder.AppendLine($"Range: {minValue} - {maxValue}");
        builder.AppendLine($"Generation Type: {generateType}");
        if (generateType == GenerateType.Normal)
            builder.AppendLine($"Mean: {RandomRange(minValue, maxValue)}");
        else if (generateType == GenerateType.Custom)
            throw new NotImplementedException("Custom distribution is not yet implemented.");
        return builder.ToString();
    }
}
