public void processPayment(Map<String, Object> paymentDetails, String connectionString, PaymentGatewayConfig config) {
    // Validate input parameters
    if (paymentDetails == null || paymentDetails.isEmpty()) {
        throw new IllegalArgumentException("Invalid payment details");
    }
    if (connectionString == null || connectionString.isEmpty()) {
        throw new IllegalArgumentException("Invalid database connection string");
    }
    if (config == null) {
        throw new IllegalArgumentException("Invalid payment gateway configuration");
    }

    // Build payment processing request
    Map<String, Object> request = new HashMap<>();
    for (Map.Entry<String, Object> entry : paymentDetails.entrySet()) {
        String key = entry.getKey();
        Object value = entry.getValue();
        if (value != null) {
            // Handle cases where the parameter types might not match the expected API types
            switch (key) {
                case "amount":
                    request.put("amount", ((Number) value).doubleValue());
                    break;
                case "currency":
                    request.put("currency", ((String) value));
                    break;
                case "customer_id":
                    request.put("customer_id", ((Integer) value));
                    break;
                default:
                    request.put(key, value);
            }
        }
    }

    // Validate payment before submission
    if (!validatePayment(request)) {
        throw new IllegalArgumentException("Invalid payment details");
    }

    // Submit payment processing request to the payment gateway API
    try {
        HttpURLConnection connection = (HttpURLConnection) new URL(config.getApiUrl()).openConnection();
        connection.setRequestMethod("POST");
        connection.setDoOutput(true);
        connection.setRequestProperty("Content-Type", "application/json");
        try (OutputStream outputStream = connection.getOutputStream()) {
            outputStream.write(request.toString().getBytes());
        } catch (IOException e) {
            throw new RuntimeException("Failed to submit payment processing request", e);
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    } catch (MalformedURLException e) {
        throw new RuntimeException("Invalid payment gateway API URL", e);
    }
}

