using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Threading.Tasks;
using Npgsql;
using YamlDotNet.Serialization;
using Serilog;
using Logstash.net;
using Redis.Cache;

namespace ConsoleApp1
{
    class Program
    {
        static async Task Main(string[] args)
        {
            var logger = new LoggerConfiguration()
                .WriteTo.Console()
                .CreateLogger();

            try
            {
                // Load configuration settings from YAML file
                var config = LoadConfig();

                // Create a connection pool for database connections
                var connectionPool = new ConnectionPool(config["database"]);

                // Loop through each command line argument
                foreach (var arg in args)
                {
                    var operation = ParseOperation(arg);

                    if (operation == null) continue;

                    logger.Information("Processing operation: {operation}", operation.Name);

                    // Get the list of databases to connect to
                    var databases = GetDatabases(config, operation.DatabaseName);

                    foreach (var database in databases)
                    {
                        // Connect to the database
                        using var connection = await connectionPool.GetConnectionAsync();
                        if (connection == null) continue;

                        logger.Information("Connected to {database} on {server}", database.Name, database.Server);

                        try
                        {
                            // Execute the SQL command and fetch the results
                            using var command = new NpgsqlCommand(operation.SqlQuery, connection);
                            var result = await command.ExecuteReaderAsync();

                            logger.Information("Fetched {rowCount} rows from {database}", result.RecordsAffected, database.Name);

                            // Cache the results in Redis for future use
                            using var redisClient = new RedisCacheClient(config["redis"]);
                            await redisClient.AddAsync(operation.CacheKey, result.GetDateTime());

                            logger.Information("Cached {rowCount} rows in Redis", result.RecordsAffected);
                        }
                        catch (Exception ex)
                        {
                            // Log the exception and continue processing other databases
                            logger.Error(ex, "Failed to execute SQL command for {database}: {errorMessage}", database.Name, ex.Message);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                // Log the exception and exit the application
                logger.Fatal(ex, "Unhandled exception: {errorMessage}", ex.Message);
            }
        }

        private static List<Database> GetDatabases(Dictionary<string, object> config, string databaseName)
        {
            var databases = new List<Database>();

            foreach (var db in config["database"])
            {
                if (db.Value.Name == databaseName)
                {
                    databases.Add(new Database
                    {
                        Name = db.Value.Name,
                        Server = db.Value.Server,
                        Port = db.Value.Port,
                        Username = db.Value.Username,
                        Password = db.Value.Password,
                        ConnectionString = $"Server={db.Value.Server};Port={db.Value.Port};Database={db.Value.Name};User Id={db.Value.Username};Password={db.Value.Password}"
                    });
                }
            }

            return databases;
        }

