const int MIN_THREADS = 10; // minimum number of threads to handle requests
const int THREAD_STEP = 5; // step size for adjusting the number of threads
const int MAX_REQUESTS = 500000; // maximum number of requests per second during peak hours
const int MIN_REQUESTS = 1000; // minimum number of requests per second during off-peak times
const int RATE_LIMIT = 100; // rate limit for requests in milliseconds
const int MAX_LATENCY = 500; // maximum latency in milliseconds
const int MIN_MEMORY = 256; // minimum memory usage in MB
const int MAX_MEMORY = 1024; // maximum memory usage in MB

// Define a struct for storing request information
struct Request {
    std::string method;
    std::string path;
    std::string body;
