import json
from datetime import timedelta
from typing import Dict
from urllib.parse import quote_plus

import requests
from flask import Flask, session, request, Response
from flask_oauthlib.client import OAuth
from flask_sse import sse
from ratelimit import RateLimit, RateLimitException

app = Flask(__name__)
app.config["SECRET_KEY"] = "your-secret-key"
oauth = OAuth(app)

# Configure OAuth client for weather API
weather_api = oauth.remote_app(
    "weather_api",
    consumer_key="YOUR_CONSUMER_KEY",
    consumer_secret="YOUR_CONSUMER_SECRET",
    request_token_params={"scope": "read"},
)

# Set up SSE endpoint for real-time weather updates
@app.route("/weather/updates")
def weather_updates():
    # Check if user is authenticated and authorized to access the API
    if not session.get("oauth_token"):
        return Response(status=401)

    # Initialize SSE connection
    sse = sse.SSE(app, "/weather/updates")

    # Send initial weather conditions to client
    current_conditions = get_current_conditions()
    sse.send({"type": "current_conditions", "data": json.dumps(current_conditions)})

    # Handle SSE events and send updates to client
    for event in sse:
        if event["type"] == "message":
            data = json.loads(event["data"])
            conditions = get_current_conditions()
            if data["type"] == "refresh":
                # Refresh user token if necessary
                session["oauth_token"] = refresh_token(session["oauth_token"])

            # Send updated weather conditions to client
            sse.send({"type": "current_conditions", "data": json.dumps(conditions)})

    # Clean up SSE connection when finished
    sse.close()
    return Response("")

# Get current weather conditions from API
def get_current_conditions():
    response = weather_api.get("/current-conditions", params={"location": session["oauth_token"]["access_token"]})
    if response.status_code == 200:
        return json.loads(response.content)["data"]
    else:
        raise Exception("Error retrieving weather conditions")

# Refresh user token if necessary
def refresh_token(token):
    # Check if token is expired and needs to be refreshed
    if token["expires_at"] - timedelta(minutes=10) < datetime.utcnow():
        response = weather_api.post("/refresh", params={"refresh_token": token["refresh_token"]})
        if response.status_code == 200:
            return json.loads(response.content)["access_token"]
        else:
            raise Exception("Error refreshing token")
    else:
        # Token is not expired, so no need to refresh it
        return token["access_token"]

# Handle rate limiting for API requests
@RateLimit(limit=10, per=timedelta(minutes=1))
def handle_rate_limit():
    raise RateLimitException("Exceeded rate limit of 10 requests per minute")

# Handle errors and exceptions
def handle_error(e):
    if isinstance(e, RateLimitException):
        return Response(status=429)
    else:
        return Response(status=500)

if __name__ == "__main__":
    app.run()
