// SessionManager.rs

use std::sync::{Arc, RwLock};
use std::collections::HashMap;
use std::time::SystemTime;
use crypto::sha2::Sha256;
use oauth2::Client;
use yup_oauth2::authenticator::Authenticator;
use resource_bundle::ResourceBundle;

struct SessionManager {
    clients: Arc<RwLock<HashMap<String, Client>>>,
    token_cache: Arc<RwLock<HashMap<String, String>>>,
}

impl SessionManager {
    fn new() -> Self {
        let clients = HashMap::new();
        let token_cache = HashMap::new();
        Self { clients, token_cache }
    }

    fn generate_secure_token(&self, username: &str, secret_key: &str, prefix: Option<&str>) -> String {
        // Generate a timestamp for the token
        let timestamp = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap();
        let mut hasher = Sha256::new();
        hasher.update(format!("{}{}", timestamp, username));
        hasher.update(secret_key);
        if let Some(prefix) = prefix {
            hasher.update(prefix);
        }
        let hashed_token = hasher.finalize().to_string();
        // Concatenate the token with the timestamp and return it
        format!("{}{}", timestamp, hashed_token)
    }

    fn load_resource_bundle(&self, url: &str) -> ResourceBundle {
        let mut resource_bundle = ResourceBundle::new();
        // Fetch the resource bundle from the specified URL
        match reqwest::blocking::get(url).json() {
            Ok(data) => {
                // Parse the resource bundle data into a JSON object
                if let Some(resource_data) = serde_json::from_value::<HashMap<String, String>>(data) {
                    // Load the resource bundle and return it
                    resource_bundle.load(&resource_data).unwrap();
                } else {
                    // Handle invalid data format or error during parsing
                }
            },
            Err(error) => {
                // Handle network failure, invalid URL, or other error
            }
        }
        resource_bundle
    }
}
