// resource_bundle.rs

use std::collections::HashMap;
use std::fs::File;
use std::io::prelude::*;
use serde_json::{Deserializer, Deserialize};

struct ResourceBundle {
    data: HashMap<String, String>,
}

impl ResourceBundle {
    fn new() -> Self {
        let mut resource_data = HashMap::new();
        // Load the resource data from a JSON file
        if let Ok(mut file) = File::open("resource_bundle.json") {
            let mut resource_string = String::new();
            match file.read_to_string(&mut resource_string) {
                Ok(_) => {
                    // Deserialize the JSON data into a HashMap<String, String>
                    if let Some(data) = serde_json::from_str::<HashMap<String, String>>(&resource_string) {
                        resource_data = data;
                    } else {
                        // Handle invalid data format or error during parsing
                    }
                },
                Err(_) => {
                    // Handle file reading error
                }
            }
        } else {
            // Handle file opening error
        }
        Self { data: resource_data }
    }

    fn load(&mut self, data: &HashMap<String, String>) -> Result<(), String> {
        for (key, value) in data.iter() {
            self.data.insert(key.to_string(), value.to_string());
        }
        Ok(())
    }
}
