using System;
using System.Security.Cryptography;

public class CustomRandomGenerator : IRandomGenerator
{
    private readonly Random _random;
    private readonly string _seed;

    public CustomRandomGenerator(string seed)
    {
        if (string.IsNullOrEmpty(seed))
            throw new ArgumentException("Seed cannot be null or empty", nameof(seed));

        _seed = seed;
        _random = new Random(_seed);
    }

    public int Next() => _random.Next();

    public int Next(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value", nameof(maxValue));

        return _random.Next(minValue, maxValue);
    }

    public float NextFloat() => _random.NextFloat();

    public float NextFloat(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value", nameof(maxValue));

        return _random.NextFloat(minValue, maxValue);
    }

    public int NextInt() => _random.NextInt();

    public int NextInt(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value", nameof(maxValue));

        return _random.NextInt(minValue, maxValue);
    }

    public override string ToString()
    {
        var sb = new StringBuilder();

        sb.AppendLine($"Seed: {_seed}");
        sb.AppendLine($"Range: [{minValue}, {maxValue}]");
        sb.AppendLine($"Algorithm: Triple DES");
        sb.AppendLine($"Key: {_key}");
        sb.AppendLine($"IV: {_iv}");
        sb.AppendLine($"Padding scheme: PKCS#7");

        return sb.ToString();
    }

    private static readonly Dictionary<string, string> _encryptedMessage = new Dictionary<string, string>();

    public static void Decrypt(string encryptedMessage)
    {
        if (string.IsNullOrEmpty(encryptedMessage))
            throw new ArgumentException("Encrypted message cannot be null or empty", nameof(encryptedMessage));

        var key = GetKey();
        var iv = GetIV();

        using (var aesAlgorithm = Aes.Create())
        {
            aesAlgorithm.Mode = CipherMode.CBC;
            aesAlgorithm.Padding = PaddingMode.PKCS7;
            aesAlgorithm.KeySize = 128;
            aesAlgorithm.BlockSize = 128;

            using (var decryptor = aesAlgorithm.CreateDecryptor(key, iv))
            {
                using (var msDecrypt = new MemoryStream())
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
                    {
                        byte[] messageBytes = Encoding.UTF8.GetBytes(encryptedMessage);
                        csDecrypt.Write(messageBytes, 0, messageBytes.Length);
                        csDecrypt.FlushFinalBlock();
                        decryptedBytes = msDecrypt.ToArray();
                    }
                }
            }
        }

        return Encoding.UTF8.GetString(decryptedBytes);
    }

