#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <dirent.h>
#include <errno.h>
#include <imagemagick/api.h>
#include "image_metadata.h"

void processImageSequence(const char* dirPath) {
    DIR* dir = opendir(dirPath);
    if (!dir) {
        printf("Error opening directory %s: %s\n", dirPath, strerror(errno));
        return;
    }

    // Iterate over all JPEG files in the directory
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char* filePath = malloc(strlen(dirPath) + strlen(entry->d_name) + 1);
        if (!filePath) {
            printf("Error allocating memory for file path: %s\n", strerror(errno));
            return;
        }
        sprintf(filePath, "%s/%s", dirPath, entry->d_name);

        // Check if the file is a JPEG image
        struct stat sb;
        if (stat(filePath, &sb) == 0 && S_ISREG(sb.st_mode)) {
            char* outputFile = malloc(strlen(filePath) + strlen(".tif") + 1);
            if (!outputFile) {
                printf("Error allocating memory for output file: %s\n", strerror(errno));
                return;
            }
            sprintf(outputFile, "%s.tif", filePath);

            // Convert the JPEG image to TIFF format using ImageMagick
            char* convertCmd = malloc(strlen("convert -quality 100 ") + strlen(filePath) + strlen(outputFile) + 1);
            if (!convertCmd) {
                printf("Error allocating memory for conversion command: %s\n", strerror(errno));
                return;
            }
            sprintf(convertCmd, "convert -quality 100 %s %s", filePath, outputFile);
            int result = system(convertCmd);
            if (result != 0) {
                printf("Error converting JPEG to TIFF: %s\n", strerror(errno));
                return;
            }

            // Parse the metadata of the converted TIFF image
            char* metadata = getImageMetadata(outputFile);
            if (!metadata) {
                printf("Error parsing metadata for file %s: %s\n", outputFile, strerror(errno));
                return;
            }
            int bitsPerSample = atoi(metadata[0]);
            int samplePerPixel = atoi(metadata[1]);
            if (bitsPerSample == 0 || samplePerPixel == 0) {
                printf("Error parsing metadata for file %s: %s\n", outputFile, strerror(errno));
                return;
            }

            // Handle extra samples in the image (if any)
            int numExtraSamples = atoi(metadata[2]);
            if (numExtraSamples > 0) {
                printf("Warning: file %s has %d extra samples\n", outputFile, numExtraSamples);
            }

            // Free memory for metadata and output file paths
            free(outputFile);
            free(metadata);
        } else {
            printf("Error accessing file %s: %s\n", entry->d_name, strerror(errno));
            return;
        }
    }

    closedir(dir);
}

// Get the metadata for a TIFF image using ImageMagick
char* getImageMetadata(const char* filePath) {
    // Convert the TIFF image to text format using ImageMagick
    char* convertCmd = malloc(strlen("convert -format %%s ") + strlen(filePath) + 1);
    if (!convertCmd) {
        printf("Error allocating memory for conversion command: %s\n", strerror(errno));
        return NULL;
    }
    sprintf(convertCmd, "convert -format %%s %s", filePath);
    FILE* metadata = popen(convertCmd, "r");
    if (!metadata) {
        printf("Error opening metadata for file %s: %s\n", filePath, strerror(errno));
        return NULL;
    }

    // Read the metadata from the output of the command
    char* buffer = malloc(BUFSIZ);
    if (!buffer) {
        printf("Error allocating memory for metadata: %s\n", strerror(errno));
        return NULL;
    }
    int bytesRead = fread(buffer, 1, BUFSIZ, metadata);
    if (bytesRead == 0) {
        printf("Error reading metadata for file %s: %s\n", filePath, strerror(errno));
        return NULL;
    }

    // Parse the metadata and extract the bits per sample and sample per pixel values
    char* delimiter = "\t";
    char* token = strtok(buffer, delimiter);
    int bitsPerSample = 0;
    int samplePerPixel = 0;
    while (token != NULL) {
        if (strncmp(token, "bits", 4) == 0) {
            bitsPerSample = atoi(token + 5);
        } else if (strncmp(token, "sample", 6) == 0) {
            samplePerPixel = atoi(token + 7);
        }
        token = strtok(NULL, delimiter);
    }

    // Free memory for metadata and output file paths
    free(buffer);
    pclose(metadata);

    return malloc(2 * sizeof(int));
}
