using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Collections.Generic;
using System.Linq;

namespace CustomRandomGenerator
{
    public class Randomizer
    {
        private readonly SecureRandom _secureRandom = new SecureRandom();
        private readonly List<byte> _keys = new List<byte>();
        private readonly byte[] _iv;
        private readonly bool _useAES;
        private readonly bool _useRSA;
        private readonly int _bitsPerSample;
        private readonly double _randomValueInterval;
        private readonly int _seed;
        private int _decryptionAttempts;
        private int _randomValueGenerations;

        public Randomizer(int seed, bool useAES = false, bool useRSA = false, int bitsPerSample = 128)
        {
            if (bitsPerSample < 0 || bitsPerSample > 64)
                throw new ArgumentOutOfRangeException("Bits per sample must be between 0 and 64");

            _seed = seed;
            _useAES = useAES;
            _useRSA = useRSA;
            _bitsPerSample = bitsPerSample;

            _secureRandom.SetSeed(_seed);
            _iv = GenerateIV();
        }

        public int Next()
        {
            if (_useAES)
                return (int)_secureRandom.GetAESNext(_iv, _bitsPerSample);
            else if (_useRSA)
                return (int)_secureRandom.GetRSANext(_iv, _bitsPerSample);
            else
                return _secureRandom.Next();
        }

        public int Next(int maxValue)
        {
            if (_useAES)
                return (int)(_secureRandom.GetAESNext(_iv, _bitsPerSample) % maxValue);
            else if (_useRSA)
                return (int)(_secureRandom.GetRSANext(_iv, _bitsPerSample) % maxValue);
            else
                return _secureRandom.Next(maxValue);
        }

        public int Next(int minValue, int maxValue)
        {
            if (_useAES)
                return (int)(_secureRandom.GetAESNext(_iv, _bitsPerSample) % (maxValue - minValue + 1) + minValue);
            else if (_useRSA)
                return (int)(_secureRandom.GetRSANext(_iv, _bitsPerSample) % (maxValue - minValue + 1) + minValue);
            else
                return _secureRandom.Next(minValue, maxValue);
        }

        public double NextDouble()
        {
            if (_useAES)
                return _secureRandom.GetAESNext(_iv, _bitsPerSample);
            else if (_useRSA)
                return _secureRandom.GetRSANext(_iv, _bitsPerSample);
            else
                return _secureRandom.NextDouble();
        }

        public float NextFloat()
        {
            if (_useAES)
                return (float)_secureRandom.GetAESNext(_iv, _bitsPerSample);
            else if (_useRSA)
                return (float)_secureRandom.GetRSANext(_iv, _bitsPerSample);
            else
                return _secureRandom.NextFloat();
        }

        public double NextDouble(double maxValue)
        {
            if (_useAES)
                return (double)(_secureRandom.GetAESNext(_iv, _bitsPerSample) % maxValue);
            else if (_useRSA)
                return (double)(_secureRandom.GetRSANext(_iv, _bitsPerSample) % maxValue);
            else
                return _secureRandom.NextDouble(maxValue);
        }

        public float NextFloat(float maxValue)
        {
            if (_useAES)
                return (float)(_secureRandom.GetAESNext(_iv, _bitsPerSample) % maxValue);
            else if (_useRSA)
                return (float)(_secureRandom.GetRSANext(_iv, _bitsPerSample) % maxValue);
            else
                return _secureRandom.NextFloat(maxValue);
        }

        public double NextDouble(double minValue, double maxValue)
        {
            if (_useAES)
                return (double)(_secureRandom.GetAESNext(_iv, _bitsPerSample) % (maxValue - minValue + 1) + minValue);
            else if (_useRSA)
                return (double)(_secureRandom.GetRSANext(_iv, _bitsPerSample) % (maxValue - minValue + 1) + minValue);
            else
                return _secureRandom.NextDouble(minValue, maxValue);
        }

        public float NextFloat(float minValue, float maxValue)
        {
            if (_useAES)
                return (float)(_secureRandom.GetAESNext(_iv, _bitsPerSample) % (maxValue - minValue + 1) + minValue);
            else if (_useRSA)
                return (float)(_secureRandom.GetRSANext(_iv, _bitsPerSample) % (maxValue - minValue + 1) + minValue);
            else
                return _secureRandom.NextFloat(minValue, maxValue);
        }

        public byte[] GenerateIV()
        {
            // Generate a random IV for the encryption/decryption process
            var iv = new byte[_iv.Length];
            _secureRandom.NextBytes(iv);
            return iv;
        }

        public bool DecryptMessage(string encryptedMessage, out string decryptedMessage)
        {
            try
            {
                // Decrypt the message using Triple DES encryption with a key and initialization vector (IV) read from an encrypted configuration file stored in a secure database
                var des = new TripleDESCryptoServiceProvider();
                var msDecrypted = new MemoryStream();
                des.CreateDecryptor(_keys, _iv).TransformBlock(encryptedMessage, 0, encryptedMessage.Length, null, msDecrypted);
                decryptedMessage = Encoding.UTF8.GetString(msDecrypted.ToArray());
                return true;
            }
            catch (Exception ex)
            {
                // If there is an error during the decryption process, log the exception and return false
                Console.WriteLine("Error during message decryption: " + ex.Message);
                decryptedMessage = null;
                return false;
            }
        }
    }
}
