typedef struct {
    int rx_ue_information_tag;
    int rnti;
    char crc_indication_rel8_tag[10];
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node to hold the CRC indication data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct nfapi_crc_indication_node *next;
} NFAPI_CRC_INDICATION_NODE_T;

// Define a linked list to hold the CRC indication data
NFAPI_CRC_INDICATION_NODE_T *crc_indications = NULL;

// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void create_crc_indications(int num_crc_indications) {
    // Allocate memory for the linked list node
    NFAPI_CRC_INDICATION_NODE_T *node = (NFAPI_CRC_INDICATION_NODE_T *) malloc(sizeof(NFAPI_CRC_INDICATION_NODE_T));
    if (!node) {
        // Handle memory allocation failure
        printf("Error: unable to allocate memory for linked list node\n");
        return;
    }

    // Initialize the linked list node with valid RX_UE_INFORMATION_TAG and RNTI values
    node->data = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node->data) {
        // Handle memory allocation failure
        printf("Error: unable to allocate memory for CRC indication data\n");
        free(node);
        return;
    }
    node->data->rx_ue_information_tag = 1234;
    node->data->rnti = 5678;
    strcpy(node->data->crc_indication_rel8_tag, "REL8");

    // Add the linked list node to the end of the linked list
    if (crc_indications) {
        NFAPI_CRC_INDICATION_NODE_T *cur = crc_indications;
        while (cur->next) {
            cur = cur->next;
        }
        cur->next = node;
    } else {
        crc_indications = node;
    }

    // Create additional linked list nodes and populate them with CRC indication data
    for (int i = 1; i < num_crc_indications; i++) {
        NFAPI_CRC_INDICATION_NODE_T *node = (NFAPI_CRC_INDICATION_NODE_T *) malloc(sizeof(NFAPI_CRC_INDICATION_NODE_T));
        if (!node) {
            // Handle memory allocation failure
            printf("Error: unable to allocate memory for linked list node\n");
            free(node->data);
            return;
        }
        node->data = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node->data) {
            // Handle memory allocation failure
            printf("Error: unable to allocate memory for CRC indication data\n");
            free(node);
            return;
        }
        node->data->rx_ue_information_tag = i + 1234;
        node->data->rnti = i + 5678;
        strcpy(node->data->crc_indication_rel8_tag, "REL8");

        // Add the linked list node to the end of the linked list
        if (crc_indications) {
            NFAPI_CRC_INDICATION_NODE_T *cur = crc_indications;
            while (cur->next) {
                cur = cur->next;
            }
            cur->next = node;
        } else {
            crc_indications = node;
        }
    }
}

// Function to delete a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void delete_crc_indications() {
    NFAPI_CRC_INDICATION_NODE_T *cur = crc_indications;
    while (cur) {
        NFAPI_CRC_INDICATION_NODE_T *next = cur->next;
        free(cur->data);
        free(cur);
        cur = next;
    }
    crc_indications = NULL;
}

// Function to insert a new linked list node with CRC indication data into the linked list
void insert_crc_indication(NFAPI_CRC_INDICATION_PDU_T *data) {
    NFAPI_CRC_INDICATION_NODE_T *node = (NFAPI_CRC_INDICATION_NODE_T *) malloc(sizeof(NFAPI_CRC_INDICATION_NODE_T));
    if (!node) {
        // Handle memory allocation failure
        printf("Error: unable to allocate memory for linked list node\n");
        return;
    }
    node->data = data;
    node->next = crc_indications;
    crc_indications = node;
}

// Function to delete a linked list node with CRC indication data from the linked list
void delete_crc_indication(NFAPI_CRC_INDICATION_PDU_T *data) {
    NFAPI_CRC_INDICATION_NODE_T *cur = crc_indications;
    while (cur && cur->next) {
        if (cur->next->data == data) {
            NFAPI_CRC_INDICATION_NODE_T *tmp = cur->next;
            cur->next = tmp->next;
            free(tmp->data);
            free(tmp);
            return;
        }
        cur = cur->next;
    }
}

// Function to retrieve a linked list node with CRC indication data from the linked list
NFAPI_CRC_INDICATION_NODE_T *get_crc_indication(int index) {
    NFAPI_CRC_INDICATION_NODE_T *cur = crc_indications;
    while (cur && cur->next) {
        if (index-- == 0) {
            return cur;
        }
        cur = cur->next;
    }
    return NULL;
}

// Function to sort the linked list of CRC indication data by a user-specified sorting criteria
void sort_crc_indications(int (*sorting_function)(NFAPI_CRC_INDICATION_PDU_T *a, NFAPI_CRC_INDICATION_PDU_T *b)) {
    NFAPI_CRC_INDICATION_NODE_T *cur = crc_indications;
    while (cur && cur->next) {
        NFAPI_CRC_INDICATION_NODE_T *tmp = cur->next;
        cur->next = tmp->next;
        tmp->next = NULL;
        insert_crc_indication(tmp);
    }
}
