    }

    // Return JSON response with success or error message
    if ($sub_action === 'create' || $sub_action === 'update') {
        return jsonResponse(200, "Success");
    } else {
        return jsonResponse(400, "Invalid sub_action value");
    }
}

function validateInputData($data) {
    // Check format of email and strength of password
    if (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
        return false;
    }
    if (strlen($data['password']) < 8) {
        return false;
    }

    // Check for missing or invalid ID in create and update requests
    if ($data['sub_action'] === 'create' || $data['sub_action'] === 'update') {
        if (!$data['id'] || !is_int($data['id'])) {
            return false;
        }
    }

    // Check for missing or invalid sub_action in delete request
    if ($data['sub_action'] === 'delete') {
        if (!$data['id']) {
            return false;
        }
    }

    return true;
}

function validatePassword($password) {
    // Validate password through external authentication service
    $authService = new ExternalAuthService();
    return $authService->validatePassword($password);
}

function createUserAccount($name, $email, $password) {
    // Save user account data to database
    $db = new Database();
    $db->insert('users', ['name' => $name, 'email' => $email, 'password' => $password]);
}

function updateUserAccount($id, $name, $email, $password) {
    // Update user account data in database
    $db = new Database();
    $db->update('users', ['name' => $name, 'email' => $email, 'password' => $password], ['id' => $id]);
}

function deleteUserAccount($id) {
    // Delete user account data from database
    $db = new Database();
    $db->delete('users', ['id' => $id]);
}

// JSON response helper function
function jsonResponse($status, $message) {
    return [
        'message' => $message,
        'data' => [],
    ];
}
