// DataProcessingModule.cpp
#include "DataProcessingModule.h"

void DataProcessingModule::insertMetadataAfterTarget(std::forward_list<std::string>& data, const std::string& target, const std::string& metadata) {
    auto it = std::find(data.begin(), data.end(), target);
    if (it != data.end()) {
        ++it; // Move iterator to next position after target
        data.insert_after(it, metadata);
    } else {
        data.push_back(metadata);
    }
}
