                    throw new IllegalArgumentException("Unsupported log source");
            }
        }
        return logEntries;
    }

    private static void storeLogEntryInElasticsearch(LogEntry entry) {
        // Store logs in Elasticsearch using the Elasticsearch Java API
        String index = "logs-" + System.currentTimeMillis();
        Map<String, Object> data = new HashMap<>();
        data.put("timestamp", System.currentTimeMillis());
