void parse_binary(char* input, char* output, char* rules, char* language, char* region) {
    // Open the input file for reading and ensure it exists
    FILE* infile = fopen(input, "rb");
    if (infile == NULL) {
        perror("Error opening input file");
        return;
    }

    // Allocate memory dynamically to store the contents of the input file
    struct Pokemon* pokemon = malloc(sizeof(struct Pokemon));
    if (pokemon == NULL) {
        perror("Error allocating memory for Pokemon");
        return;
    }

