    }
    written = fwrite(translated_abilities, sizeof(char), strlen(translated_abilities), outfile);
    if (written == 0) {
        perror("Error writing abilities to output file");
        return;
    }

    // Close the input and output files and free the allocated memory
    fclose(infile);
    fclose(outfile);
    free(translated_weaknesses);
    free(translated_name);
    free(translated_abilities);
}

