using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;

public class SQLExecutor
{
    private readonly IConfiguration _config;

    public SQLExecutor(IConfiguration config)
    {
        _config = config;
    }

    public async Task<List<object>> ExecuteSQLCommandAsync(string command, List<object> parameters, string connectionString, int timeout = 30, CommandType type = CommandType.Text, IsolationLevel isolationLevel = IsolationLevel.ReadCommitted)
    {
        // Initialize a new SqlConnection
        using var connection = new SqlConnection(connectionString);

        // Open the connection
        await connection.OpenAsync();

        try
        {
            // Create a new SqlCommand with the provided parameters and type
            var command = new SqlCommand(command, connection) { CommandTimeout = timeout };
            command.CommandType = type;
            command.Transaction = connection.BeginTransaction(isolationLevel);

            // Add the parameters to the command
            foreach (var param in parameters)
            {
                var paramName = $"@p{command.Parameters.Count}";
                command.Parameters.AddWithValue(paramName, param);
            }

            // Execute the command and get the results
            using var reader = await command.ExecuteReaderAsync();

            // Read the results into a list of objects
            var result = new List<object>();
            while (reader.Read())
            {
                var row = new object[reader.FieldCount];
                reader.GetValues(row);
                result.Add(row);
            }

            // Commit the transaction and close the connection
            command.Transaction.Commit();
            await connection.CloseAsync();

            return result;
        }
        catch (Exception ex)
        {
            // Rollback the transaction if an exception occurred
            command.Transaction.Rollback();

            // Close the connection and re-throw the exception
            await connection.CloseAsync();
            throw new Exception("Error executing SQL command", ex);
        }
    }
}
```
