#include <unordered_map>
#include <vector>
#include <mutex>

class NfaApiCrcManager {
private:
    std::mutex mutex_;
    std::unordered_map<std::string, std::vector<NfaApiCrcIndicationPdu>> map_;

public:
    void add(const NfaApiCrcIndicationPdu &pdu) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(pdu.getRnti());
        if (it != map_.end()) {
            it->second.push_back(pdu);
        } else {
            std::vector<NfaApiCrcIndicationPdu> vec;
            vec.push_back(pdu);
            map_.emplace(std::make_pair(pdu.getRnti(), vec));
        }
    }

    void remove(const std::string &rnti) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(rnti);
        if (it != map_.end()) {
            map_.erase(it);
        } else {
            throw std::runtime_error("RNTI not found");
        }
    }

    void update(const std::string &rnti, const CrcIndicationRel8Tag &crc) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(rnti);
        if (it != map_.end()) {
            for (auto &pdu : it->second) {
                pdu.setCrcIndicationRel8Tag(crc);
            }
        } else {
            throw std::runtime_error("RNTI not found");
        }
    }

    NfaApiCrcIndicationPdu query(const std::string &rnti) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(rnti);
        if (it != map_.end()) {
            return it->second.front();
        } else {
            throw std::runtime_error("RNTI not found");
        }
    }
};
```
