// Structure to hold information about a command and its status
struct Command {
    char *command; // The command to execute
    pid_t pid; // The process ID of the command
    int exit_status; // The exit status of the command
    double cpu_usage; // The CPU usage of the command
    size_t memory_usage; // The memory usage of the command
};

// Structure to hold information about a command and its status
struct CommandQueue {
    struct Command *commands[MAX_COMMANDS]; // An array of pointers to commands
    int num_commands; // The number of commands in the queue
    int next_command; // The index of the next command to execute
};

// Initialize a new command queue
struct CommandQueue *new_command_queue() {
    struct CommandQueue *queue = malloc(sizeof(struct CommandQueue));
    if (!queue) {
        perror("malloc");
        return NULL;
    }
    queue->num_commands = 0;
    queue->next_command = 0;
    return queue;
}

// Add a new command to the queue
int add_command(struct CommandQueue *queue, char *command) {
    if (queue->num_commands >= MAX_COMMANDS) {
        fprintf(stderr, "Error: maximum number of commands reached\n");
        return -1;
    }
    struct Command *new_command = malloc(sizeof(struct Command));
    if (!new_command) {
        perror("malloc");
        return -1;
    }
    new_command->command = command;
    new_command->pid = 0;
    new_command->exit_status = 0;
    new_command->cpu_usage = 0.0;
    new_command->memory_usage = 0;
    queue->commands[queue->num_commands++] = new_command;
    return 0;
}

// Execute the next command in the queue
int execute_next_command(struct CommandQueue *queue) {
    if (queue->num_commands == 0) {
        fprintf(stderr, "Error: no commands to execute\n");
        return -1;
    }
    struct Command *current_command = queue->commands[queue->next_command];
    pid_t pid = fork();
    if (pid == 0) {
        // Child process executes the command
        execlp(current_command->command, NULL);
        fprintf(stderr, "Error: failed to execute command\n");
        return -1;
    } else if (pid > 0) {
        // Parent process monitors the child process and handles errors
        int status;
        pid_t wait_result = waitpid(pid, &status, WNOHANG);
        if (wait_result == -1) {
            perror("waitpid");
            return -1;
        } else if (wait_result == 0) {
            // Command is still running
            current_command->cpu_usage = get_cpu_usage(current_command);
            current_command->memory_usage = get_memory_usage(current_command);
            return 0;
        } else {
            // Command has completed
            if (WIFEXITED(status)) {
                current_command->exit_status = WEXITSTATUS(status);
                fprintf(stderr, "Command exited with status %d\n", current_command->exit_status);
            } else if (WIFSIGNALED(status)) {
                current_command->exit_status = WTERMSIG(status);
                fprintf(stderr, "Command terminated by signal %d\n", current_command->exit_status);
            } else {
                fprintf(stderr, "Unknown exit status: %d\n", status);
            }
            return -1;
        }
    } else {
        fprintf(stderr, "Error: failed to fork child process\n");
        return -1;
    }
}

