void generateAndPopulateCRCIndicationPDUs(size_t N, std::forward_list<NFAPI_CRC_INDICATION_PDU>& pduList) {
  // Generate unique RX_UE_INFORMATION_TAG and RNTI values for each PDU
  srand(time(NULL));
  for (size_t i = 0; i < N; ++i) {
    NFAPI_CRC_INDICATION_PDU pdu;
    pdu.RX_UE_INFORMATION_TAG = rand() % 65536;
    pdu.RNTI = rand() % 65536;
    // Set CRCFLAG to a randomly set value
    pdu.CRCFLAG = (rand() % 2 == 0);
    pduList.push_front(pdu);
  }
}
```
This function takes in an integer `N` representing the number of PDUs to generate and populates a forward list of `NFAPI_CRC_INDICATION_PDU` structs with unique RX_UE_INFORMATION_TAG and RNTI values, as well as a randomly set CRCFLAG value.

