import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class AudioConverter {
    private static final String DEFAULT_OUTPUT_FILENAME = "converted_audio.wav";
    private static final int DEFAULT_SAMPLE_RATE = 44100;
    private static final int DEFAULT_BIT_DEPTH = 16;
    private static final int DEFAULT_NUM_CHANNELS = 2;

    public static void main(String[] args) {
        // Create an ExecutorService to handle asynchronous processing for concurrent file operations
        ExecutorService executorService = Executors.newFixedThreadPool(4);

        // Define the input and output file paths, target configurations, and metadata storage struct
        String inputFilePath = "path/to/input/audio/file.mp3";
        String outputFilePath = Paths.get(inputFilePath).resolveSibling(DEFAULT_OUTPUT_FILENAME).toString();
        int targetSampleRate = DEFAULT_SAMPLE_RATE;
        int targetBitDepth = DEFAULT_BIT_DEPTH;
        int targetNumChannels = DEFAULT_NUM_CHANNELS;
        MetadataStorage metadataStorage = new MetadataStorage();

        // Create a CompletableFuture to handle the conversion process asynchronously
        CompletableFuture<Void> future = CompletableFuture.runAsync(() -> {
            convertAndExtractMetadata(inputFilePath, outputFilePath, targetSampleRate, targetBitDepth, targetNumChannels, metadataStorage);
        }, executorService);

        // Wait for the conversion process to complete
        try {
            future.get();
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }

        // Print the extracted metadata and converted audio file path
        System.out.println("Metadata:");
        System.out.println(metadataStorage);
        System.out.println("Converted audio file saved to: " + outputFilePath);
    }

    private static void convertAndExtractMetadata(String inputFilePath, String outputFilePath, int targetSampleRate, int targetBitDepth, int targetNumChannels, MetadataStorage metadataStorage) {
        // Check if the input file exists and is a supported audio format
        File inputFile = new File(inputFilePath);
        if (!inputFile.exists() || !isSupportedAudioFormat(inputFile)) {
            throw new IllegalArgumentException("Invalid input file path or format");
        }

        // Check if the output file exists and is a supported audio format
        File outputFile = new File(outputFilePath);
        if (outputFile.exists() && !isSupportedAudioFormat(outputFile)) {
            throw new IllegalArgumentException("Invalid output file path or format");
        }

        // Load the appropriate audio processing library based on the input file format and target configuration
        Map<String, String> supportedFormats = getSupportedFormats();
        String inputFormat = supportedFormats.get(inputFilePath);
        if (inputFormat == null) {
            throw new UnsupportedOperationException("Input file format not supported");
        }
        boolean transcodingRequired = targetSampleRate != DEFAULT_SAMPLE_RATE || targetBitDepth != DEFAULT_BIT_DEPTH || targetNumChannels != DEFAULT_NUM_CHANNELS;
        String libName = getLibName(inputFormat, targetSampleRate, targetBitDepth, targetNumChannels, transcodingRequired);
        LibraryLoader loader = new LibraryLoader();
        AudioLibrary library = loader.loadLibrary(libName);

        // Extract the metadata from the input file
        library.extractMetadata(inputFilePath, metadataStorage);

        // Convert the audio to WAV format and write it to disk
        if (transcodingRequired) {
            library.transcode(inputFilePath, outputFilePath, targetSampleRate, targetBitDepth, targetNumChannels);
        } else {
            library.writeToDisk(inputFilePath, outputFilePath);
        }
    }

    private static boolean isSupportedAudioFormat(File file) {
        String extension = getExtension(file);
        if (extension == null) {
            return false;
        }
        switch (extension.toLowerCase()) {
            case "mp3":
            case "aac":
            case "flac":
                return true;
            default:
                return false;
        }
    }

    private static String getLibName(String inputFormat, int targetSampleRate, int targetBitDepth, int targetNumChannels, boolean transcodingRequired) {
        // Determine the appropriate audio processing library based on the input file format and target configuration
        switch (inputFormat.toLowerCase()) {
            case "mp3":
                return transcodingRequired ? "lame" : "ffmpeg";
            case "aac":
                return transcodingRequired ? "ffmpeg" : "ffmpeg";
            case "flac":
                return "ffmpeg";
            default:
                throw new UnsupportedOperationException("Input file format not supported");
        }
    }

    private static String getExtension(File file) {
        return Files.getFileExtension(file.toPath());
    }

    private static Map<String, String> getSupportedFormats() {
        // Define the supported audio formats and their corresponding libraries
        Map<String, String> supportedFormats = new HashMap<>();
        supportedFormats.put("mp3", "lame");
        supportedFormats.put("aac", "ffmpeg");
        supportedFormats.put("flac", "ffmpeg");
        return supportedFormats;
    }
}
```

This program uses the `LibraryLoader` class to load the appropriate audio processing library based on the input file format and target configuration, and then uses the loaded library's functions to extract metadata from the input file and convert it to WAV format. The program also provides a user-friendly command-line interface for specifying input and output file paths, target configurations, and controling the conversion process.

The `LibraryLoader` class is used to load the appropriate audio processing library based on the input file format and target configuration. This class uses the `System.load()` method to load the library, and then returns an instance of the loaded library's `AudioLibrary` interface. The `AudioLibrary` interface provides functions for extracting metadata from an audio file, converting it to WAV format, and writing it to disk.

The program also uses the `MetadataStorage` class to store the extracted metadata in a structured format. This class provides a map of metadata keys to values, and allows for adding and retrieving metadata entries. The program uses this class to store the extracted metadata from the input file, and then prints it out to the console.

The `getSupportedFormats()` method is used to define the supported audio formats and their corresponding libraries. This method returns a map of format names to library names, which are used by the `LibraryLoader` class to load the appropriate audio processing library.

The program also provides a user-friendly command-line interface for specifying input and output file paths, target configurations, and controlling the conversion process. The command-line interface can be accessed using the `main()` method, which takes in the following arguments:

* `inputFilePath`: the path to the input audio file
* `outputFilePath`: the path to save the converted audio file
* `targetSampleRate`: the target sample rate for the conversion process (defaults to 44100)
* `targetBitDepth`: the target bit depth for the conversion process (defaults to 16)
* `targetNumChannels`: the target number of channels for the conversion process (defaults to 2)
* `transcodingRequired`: whether transcoding is required for the conversion process (defaults to false)

The program can be run using the following command:
```bash
java -jar audio-converter.jar input_file.mp3 output_file.wav
```
