public class AsyncDataProcessor {
    private static final int DEFAULT_POOL_SIZE = 10;
    private ExecutorService executor;

    public AsyncDataProcessor() {
        this(DEFAULT_POOL_SIZE);
    }

    public AsyncDataProcessor(int poolSize) {
        this.executor = Executors.newFixedThreadPool(poolSize);
    }

    public void processAsync(List<Record> records) throws Exception {
        if (records == null || records.isEmpty()) {
            throw new IllegalArgumentException("Input records cannot be null or empty");
        }

        // Initialize the metadata map with default values for each record
        Map<String, Object> metadataMap = new HashMap<>();
        for (Record record : records) {
            metadataMap.put(record.getId(), new Metadata(null, null));
        }

        // Fetch metadata from external REST API in parallel using the executor service
        List<Future<Metadata>> futures = new ArrayList<>();
        for (Record record : records) {
            Future<Metadata> future = executor.submit(() -> fetchMetadata(record));
            futures.add(future);
        }

        // Wait for all futures to complete and update the metadata map accordingly
        for (Future<Metadata> future : futures) {
            try {
                Metadata metadata = future.get();
                if (metadata != null) {
                    metadataMap.put(metadata.getId(), metadata);
                }
            } catch (ExecutionException e) {
                // Handle API unavailability or incorrect metadata gracefully by providing default values or fallback strategies
                Metadata metadata = new Metadata();
                metadata.setId(record.getId());
                metadataMap.put(metadata.getId(), metadata);
            }
        }

        // Process each record in parallel using the executor service and update the shared resources accordingly
        for (Record record : records) {
            Metadata metadata = metadataMap.get(record.getId());
            executor.submit(() -> processRecord(record, metadata));
        }
    }

    private Metadata fetchMetadata(Record record) throws Exception {
        // Fetch metadata from external REST API using the record's ID
        String url = "https://api.example.com/metadata/" + record.getId();
        RestTemplate restTemplate = new RestTemplate();
        ResponseEntity<Metadata> response = restTemplate.exchange(url, HttpMethod.GET, null, Metadata.class);
        if (response == null || response.getStatusCode() != HttpStatus.OK) {
            throw new Exception("Failed to fetch metadata for record " + record.getId());
        }
        return response.getBody();
    }

    private void processRecord(Record record, Metadata metadata) {
        // Process the record using the metadata
        // ...
    }

    public void setThreadPoolSize(int poolSize) {
        this.executor = Executors.newFixedThreadPool(poolSize);
    }
}
```
