import java.io.File;
import java.io.IOException;
import java.util.Date;

import org.json.JSONObject;

import com.google.common.hash.Hashing;

public class StaticSiteDeployment {
    private static final String GIT_API = "https://api.github.com";
    private static final String CDN_API = "https://cdn.example.com/api";

    private static final int COMPRESSION_LEVEL = 6; // 1-9, higher is more compression
    private static final String[] COMPRESSIBLE_FILE_TYPES = {"html", "css", "js"};

    public static void main(String[] args) throws IOException {
        if (args.length != 4) {
            System.err.println("Usage: java StaticSiteDeployment <git-repository> <domain> <branch/tag> <user>");
            return;
        }

        String repositoryUrl = args[0];
        String domainName = args[1];
        String branchOrTag = args[2];
        String userId = args[3];

        // Verify the Git repository URL and extract the repository name
        if (!repositoryUrl.startsWith("https://github.com/")) {
            System.err.println("Invalid Git repository URL");
            return;
        }
        String repoName = repositoryUrl.substring(21); // length of "https://github.com/"

        // Clone the Git repository and verify its integrity using checksums
        File cloneDir = new File("/tmp/clones", userId + "_" + repoName);
        if (!cloneDir.exists()) {
            try {
                cloneDir.mkdir();
            } catch (Exception e) {
                System.err.println("Failed to create directory for cloning: " + e.getMessage());
                return;
            }
        }
        String checkoutBranch = branchOrTag.startsWith("refs/heads/") ? branchOrTag : "refs/tags/" + branchOrTag;
        ProcessBuilder pb = new ProcessBuilder("git", "clone", repositoryUrl, cloneDir.getAbsolutePath());
        try {
            System.out.println("Cloning Git repository...");
            Process process = pb.start();
            process.waitFor();
            if (process.exitValue() != 0) {
                System.err.println("Error cloning Git repository: " + process.exitValue());
                return;
            }
        } catch (Exception e) {
            System.err.println("Failed to clone Git repository: " + e.getMessage());
            return;
        }

        // Verify the integrity of the cloned repository using checksums
        try {
            String rootDir = cloneDir.getAbsolutePath();
            JSONObject rootConfig = new JSONObject(new File(rootDir, "static.json"));
            JSONObject deployConfig = rootConfig.getJSONObject("deploy");
            if (deployConfig == null) {
                System.err.println("Error: missing static.json configuration file in root of repository");
                return;
            }
            String deployDir = deployConfig.getString("directory");
            File deployPath = new File(rootDir, deployDir);
            if (!deployPath.exists()) {
                System.err.println("Error: missing deployment directory " + deployDir);
                return;
            }

            // Verify the integrity of files in the deployment directory using checksums
            String[] fileList = deployPath.list();
            for (String fileName : fileList) {
                File file = new File(deployPath, fileName);
                if (!file.isFile()) continue;

                // Calculate the SHA-256 hash of the file and verify it against the checksum in static.json
                String fileHash = Hashing.sha256().hashString(file).toString();
                JSONObject fileConfig = rootConfig.getJSONObject("files").getJSONObject(fileName);
                if (fileConfig == null) {
                    System.err.println("Error: missing checksum for file " + fileName);
                    return;
                }
                String expectedHash = fileConfig.getString("sha256");
                if (!expectedHash.equals(fileHash)) {
                    System.err.println("Error: checksum mismatch for file " + fileName);
                    return;
                }
            }
        } catch (Exception e) {
            System.err.println("Failed to verify integrity of repository files: " + e.getMessage());
            return;
        }

        // Configure the CDN for the deployment
        try {
            System.out.println("Configuring CDN for deployment...");
            String cdnEndpoint = domainName + "/" + branchOrTag;
            JSONObject cdnConfig = new JSONObject();
            cdnConfig.put("endpoint", cdnEndpoint);
            JSONObject cdnFileConfig = new JSONObject();
            cdnFileConfig.put("directory", deployDir);
            for (String fileType : COMPRESSIBLE_FILE_TYPES) {
                cdnFileConfig.put(fileType + ".compression", COMPRESSION_LEVEL);
            }
            cdnConfig.put("files", cdnFileConfig);
            JSONObject cdnRequest = new JSONObject();
            cdnRequest.put("cdn", cdnConfig);
            String requestUrl = CDN_API + "/deployments/create";
            HttpClient client = new DefaultHttpClient();
            HttpPost post = new HttpPost(requestUrl);
            post.setEntity(new StringEntity(cdnRequest.toString(), ContentType.APPLICATION_JSON));
            HttpResponse response = client.execute(post);
            if (response.getStatusLine().getStatusCode() != 201) {
                System.err.println("Error: CDN API request failed with status code " + response.getStatusLine().getStatusCode());
                return;
            }
        } catch (Exception e) {
            System.err.println("Failed to configure CDN for deployment: " + e.getMessage());
            return;
        }

        // Success!
        System.out.println("Deployment successful!");
    }
}

