void modifyFileName(char* oldName, char* newName) {
  // Check if the new name meets the naming rules
  if (!regexMatches(newName, NAMING_RULES)) {
    fprintf(stderr, "Invalid file name: %s\n", newName);
    return;
  }

  // Open the old file for reading and writing
  int oldFd = open(oldName, O_RDWR);
  if (oldFd < 0) {
    perror("Failed to open old file");
    return;
  }

  // Create a new file for writing
  int newFd = creat(newName, S_IRUSR | S_IWUSR);
  if (newFd < 0) {
    perror("Failed to create new file");
    close(oldFd);
    return;
  }

  // Copy the content of the old file to the new file
  while (1) {
    char buffer[BUFSIZ];
    ssize_t bytesRead = read(oldFd, buffer, BUFSIZ);
    if (bytesRead <= 0) break;
    ssize_t bytesWritten = write(newFd, buffer, bytesRead);
    if (bytesWritten != bytesRead) {
      perror("Failed to write to new file");
      close(oldFd);
      close(newFd);
      return;
    }
  }

  // Close the files and remove the old file
  close(oldFd);
  close(newFd);
  unlink(oldName);
}

