def validate_symbols(symbols):
    # Validate each symbol in the list
    for symbol in symbols:
        if not re.match(r"^[A-Z]{2,5}$", symbol):
            raise ValueError(f"Invalid symbol {symbol}")
    return [symbol.upper() for symbol in symbols]

# Define a function to fetch real-time stock data from Alpha Vantage API
def get_real_time_stock_data(symbols, cache=True):
    # Validate the input symbols and handle invalid inputs gracefully
    try:
        validated_symbols = validate_symbols(symbols)
    except ValueError as e:
        print(f"Invalid symbol detected: {e}")
        return None

    # Construct API endpoints for fetching real-time stock data from Alpha Vantage API
    api_endpoints = [alpha_vantage_api.format(symbol, alpha_vantage_api_key) for symbol in validated_symbols]

    # Cache the real-time stock data for a set period (e.g., 5 minutes) to minimize API calls and improve performance
    if cache:
        cached_data = {}
        for api_endpoint in api_endpoints:
            if api_endpoint not in cached_data or datetime.timedelta(minutes=5) > (datetime.datetime.now() - cached_data[api_endpoint]["timestamp"]):
                response = requests.get(api_endpoint)
                data = json.loads(response.text)
                cached_data[api_endpoint] = {
                    "data": data,
                    "timestamp": datetime.datetime.now()
                }
            else:
                data = cached_data[api_endpoint]["data"]

        # Convert the API response into a Pandas DataFrame for easier manipulation and storage
        data = pd.DataFrame(data)

        return data
    else:
        # Handle rate limiting for the Alpha Vantage API by implementing a token bucket algorithm
        # This mechanism limits the number of API requests per minute to prevent abuse while allowing legitimate high-frequency requests
        token_bucket = {
            "tokens": 10,
            "timestamp": datetime.datetime.now()
        }

        data = []
        for api_endpoint in api_endpoints:
            response = requests.get(api_endpoint)
            data.extend(json.loads(response.text))

            # Update the token bucket and handle rate limit errors gracefully
            if "X-Ratelimit-Remaining" in response.headers:
                remaining_requests = int(response.headers["X-Ratelimit-Remaining"])
                now = datetime.datetime.now()
                tokens_used = now - token_bucket["timestamp"]
                tokens_left = remaining_requests / 60 * (tokens_used.total_seconds())
                token_bucket["tokens"] += tokens_left
                token_bucket["timestamp"] = now
            else:
                raise Exception("Rate limit header not found in response")

        # Convert the API response into a Pandas DataFrame for easier manipulation and storage
        data = pd.DataFrame(data)

        return data

# Define a function to store fetched real-time stock data into a PostgreSQL database
def store_real_time_stock_data(symbol, data):
    # Validate the input symbol and handle invalid inputs gracefully
    try:
        validate_symbols([symbol])
