var generator = new RandomNumberGenerator("path/to/config.json");

// Get a random integer within the configured range.
int value = generator.GetRandomInteger();

// Get a random float within the configured range with a specified precision.
float value = generator.GetRandomFloat(0.1f, 0.9f);
