Here is an example of how you can define a C function that manages a dynamic list of `NFAPI_CRC_INDICATION_PDU` structures:
```c
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include "nfapi_crc_indication_pdu.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU *crc_indication;
    pthread_mutex_t mutex;
} nfapi_crc_indication_list;

bool add_crc_indication(nfapi_crc_indication_list *list, NFAPI_CRC_INDICATION_PDU *crc_indication) {
    pthread_mutex_lock(&list->mutex);

    // Check if the RNTI already exists in the list
    bool found = false;
    for (int i = 0; i < list->size; i++) {
        if (list->crc_indications[i].rnti == crc_indication->rnti) {
            found = true;
            break;
        }
    }

    // If the RNTI is not found, add a new entry to the list
    if (!found) {
        list->size++;
        list->crc_indications = realloc(list->crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU) * list->size);
        list->crc_indications[list->size - 1] = *crc_indication;
    } else {
        // If the RNTI is found, update the existing entry with the new information
        for (int i = 0; i < list->size; i++) {
            if (list->crc_indications[i].rnti == crc_indication->rnti) {
                list->crc_indications[i] = *crc_indication;
                break;
            }
        }
    }

    pthread_mutex_unlock(&list->mutex);

    return true;
}

bool remove_crc_indication(nfapi_crc_indication_list *list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);

    // Find the entry with the specified RNTI and remove it from the list
    for (int i = 0; i < list->size; i++) {
        if (list->crc_indications[i].rnti == rnti) {
            list->size--;
            memmove(list->crc_indications + i, list->crc_indications + i + 1, sizeof(NFAPI_CRC_INDICATION_PDU) * (list->size - i));
            break;
        }
    }

    pthread_mutex_unlock(&list->mutex);

    return true;
}
```
This function uses a `pthread_mutex` to ensure that the list is accessed safely from multiple threads. It also checks for out-of-memory conditions and invalid input, such as attempting to add or remove an entry with an invalid RNTI value.

