using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace DynamicNetworkTrafficSimulator
{
    public class Simulator
    {
        private int minPacketSize;
        private int maxPacketSize;
        private double arrivalRate;
        private double lossRate;
        private bool distributionModelExponential;
        private bool distributionModelPoisson;
        private List<ExternalService> externalServices;
        private Random random = new Random();

        public Simulator()
        {
            minPacketSize = 1024;
            maxPacketSize = 1500;
            arrivalRate = 10;
            lossRate = 0.01;
            distributionModelExponential = true;
            distributionModelPoisson = false;
            externalServices = new List<ExternalService>();
        }

        public Simulator(int minPacketSize, int maxPacketSize, double arrivalRate, double lossRate, bool distributionModelExponential, bool distributionModelPoisson, List<ExternalService> externalServices)
        {
            this.minPacketSize = minPacketSize;
            this.maxPacketSize = maxPacketSize;
            this.arrivalRate = arrivalRate;
            this.lossRate = lossRate;
            this.distributionModelExponential = distributionModelExponential;
            this.distributionModelPoisson = distributionModelPoisson;
            this.externalServices = externalServices;
        }

        public void SeedRandom(int seed)
        {
            random.Seed(seed);
        }

        public void ConfigureDistributionModel(bool exponential, bool poisson)
        {
            distributionModelExponential = exponential;
            distributionModelPoisson = poisson;
        }

        public SyntheticPacket GenerateSyntheticPacket()
        {
            int packetSize = GetNextPacketSize();
            double arrivalTime = GetNextArrivalTime();
            bool isLost = IsPacketLost(arrivalTime);

            return new SyntheticPacket(packetSize, arrivalTime, isLost);
        }

        private int GetNextPacketSize()
        {
            if (distributionModelExponential)
                return (int)Math.Round(random.NextDouble() * (maxPacketSize - minPacketSize) + minPacketSize);
            else if (distributionModelPoisson)
                return random.NextPoisson(lambda: arrivalRate);
            else
                throw new NotImplementedException("Unsupported distribution model");
        }

        private double GetNextArrivalTime()
        {
            double interArrivalTime = -Math.Log(random.NextDouble()) / arrivalRate;

            return DateTime.Now.AddSeconds(interArrivalTime);
        }

        private bool IsPacketLost(double arrivalTime)
        {
            if (lossRate == 0)
                return false;

            double lossTime = -Math.Log(random.NextDouble()) / lossRate;

            return arrivalTime + lossTime < DateTime.Now;
        }

        public override string ToString()
        {
            return $"Minimum packet size: {minPacketSize}\n" +
                   $"Maximum packet size: {maxPacketSize}\n" +
                   $"Arrival rate: {arrivalRate}\n" +
                   $"Loss rate: {lossRate}\n" +
                   $"Distribution model (exponential): {distributionModelExponential}\n" +
                   $"Distribution model (Poisson): {distributionModelPoisson}\n";
        }
    }

    public class SyntheticPacket
    {
        private int size;
        private DateTime arrivalTime;
        private bool isLost;

        public SyntheticPacket(int size, DateTime arrivalTime, bool isLost)
        {
            this.size = size;
            this.arrivalTime = arrivalTime;
            this.isLost = isLost;
        }

        public int Size { get => size; set => size = value; }
        public DateTime ArrivalTime { get => arrivalTime; set => arrivalTime = value; }
        public bool IsLost { get => isLost; set => isLost = value; }
    }

    public class ExternalService
    {
        private string name;
        private int currentLoad;

        public ExternalService(string name, int currentLoad)
        {
            this.name = name;
            this.currentLoad = currentLoad;
        }

        public string Name { get => name; set => name = value; }
        public int CurrentLoad { get => currentLoad; set => currentLoad = value; }
    }
}
