Here is a sample code for the Node.js application module that integrates with a third-party streaming API to collect real-time sensor data from multiple devices across a network:
```
const express = require('express');
const app = express();
const request = require('request');
const mongoose = require('mongoose');
const db = mongoose.connect('mongodb://localhost/mydb');

app.get('/api/v1/devices', (req, res) => {
  const devices = [];
  request.get({
    url: 'https://third-party-api.com/streaming-data',
    headers: { Authorization: `Bearer ${process.env.API_TOKEN}` },
  }, (err, response) => {
    if (err) {
      console.error(err);
      return;
    }
    const data = JSON.parse(response.body);
    data.forEach((device) => {
      devices.push({
        deviceId: device.deviceId,
        timestamp: device.timestamp,
        sensorData: device.sensorData,
      });
    });
  });
  res.send(devices);
});

app.post('/api/v1/devices', (req, res) => {
  const { deviceId } = req.body;
  request.get({
    url: `https://third-party-api.com/streaming-data?deviceId=${deviceId}`,
    headers: { Authorization: `Bearer ${process.env.API_TOKEN}` },
  }, (err, response) => {
    if (err) {
      console.error(err);
      return;
    }
    const data = JSON.parse(response.body);
    db.collection('sensor-data')
      .insertOne({ deviceId, timestamp: Date.now(), sensorData: data })
      .then(() => {
        res.status(201).send();
      })
      .catch((err) => {
        console.error(err);
        res.status(500).send('Error saving data');
      });
  });
});

app.get('/api/v1/devices/:deviceId', (req, res) => {
  const deviceId = req.params.deviceId;
  db.collection('sensor-data')
    .find({ deviceId })
    .sort({ timestamp: -1 })
    .limit(10)
    .toArray((err, data) => {
      if (err) {
        console.error(err);
        return;
      }
      res.send(data);
    });
});
```
