import java.io.*;
import java.util.*;
import javax.imageio.*;
import javax.imageio.metadata.*;
import org.apache.commons.imaging.ImageInfo;
import org.json.simple.JSONObject;
import org.yaml.snakeyaml.Yaml;

public class ImageResizerService {
    private static final int DEFAULT_WIDTH = 500;
    private static final int DEFAULT_HEIGHT = 500;
    private static final int DEFAULT_QUALITY = 90;

    public static void main(String[] args) throws Exception {
        // Load external configuration file (JSON or YAML format)
        JSONObject config = new JSONObject();
        try (FileInputStream inputStream = new FileInputStream("image-resizer.conf")) {
            config = (JSONObject) new JSONParser().parse(new InputStreamReader(inputStream));
        }

        // Initialize resized image cache for efficient concurrent access
        Map<String, BufferedImage> cache = new HashMap<>();

        // Set default dimensions and quality settings based on external configuration file
        int width = (int) config.get("width");
        int height = (int) config.get("height");
        int quality = (int) config.get("quality");

        // Handle incoming image resizing requests
        while (true) {
            // Fetch next request from queue or user input
            String filePath = null;
            try {
                filePath = System.in.readLine();
            } catch (IOException e) {
                System.err.println("Error reading from stdin: " + e.getMessage());
                continue;
            }

            // Skip empty lines or comments
            if (filePath == null || filePath.trim().isEmpty() || filePath.startsWith("#")) {
                continue;
            }

            // Load image from disk
            BufferedImage originalImage = ImageIO.read(new File(filePath));
            if (originalImage == null) {
                System.err.println("Invalid image format: " + filePath);
                continue;
            }

            // Fetch custom dimensions and quality settings from request parameter or external configuration file
            int reqWidth = (int) config.get("width");
            int reqHeight = (int) config.get("height");
            int reqQuality = (int) config.get("quality");
            if (reqWidth > 0 || reqHeight > 0 || reqQuality > 0) {
                width = reqWidth;
                height = reqHeight;
                quality = reqQuality;
            }

            // Resize image and store in cache for efficient concurrent access
            BufferedImage resizedImage = resizeImage(originalImage, width, height);
            String cacheKey = filePath + "@" + width + "x" + height + ":" + quality;
            cache.put(cacheKey, resizedImage);

            // Write resized image to disk using appropriate format and quality settings
            ImageIO.write(resizedImage, "png", new File(filePath));
        }
    }

    private static BufferedImage resizeImage(BufferedImage originalImage, int width, int height) {
        try {
            return Scalr.resize(originalImage, Scalr.Method.ULTRA_QUALITY, width, height);
        } catch (Exception e) {
            System.err.println("Error resizing image: " + e.getMessage());
            return originalImage;
        }
    }
}
