public class FileUploader {
    private static final int CHUNK_SIZE = 1024 * 1024; // 1MB chunks

    public List<FileMetadata> uploadFiles(List<String> filePaths) {
        if (filePaths.isEmpty()) {
            return new ArrayList<>();
        }

        List<FileMetadata> uploadedFiles = new ArrayList<>();

        for (String filePath : filePaths) {
            FileMetadata metadata = uploadFile(filePath);
            if (metadata != null) {
                uploadedFiles.add(metadata);
            }
        }

        return uploadedFiles;
    }

    private FileMetadata uploadFile(String filePath) {
        try {
            File file = new File(filePath);
            String fileName = file.getName();
            long fileSize = file.length();

            // Upload the file in chunks to optimize performance for large files
            List<byte[]> chunks = uploadChunks(file, CHUNK_SIZE);

            // Retrieve metadata for each uploaded chunk
            List<FileMetadata> chunkMetadatas = retrieveChunkMetadatas(chunks);

            // Combine the chunk metadatas to get the final file metadata
            FileMetadata metadata = combineChunkMetadatas(chunkMetadatas, fileName, fileSize);

            return metadata;
        } catch (IOException e) {
            System.out.println("Failed to upload file: " + filePath);
            e.printStackTrace();
            return null;
        }
    }

    private List<byte[]> uploadChunks(File file, int chunkSize) throws IOException {
        long fileSize = file.length();
        int numChunks = (int) Math.ceil((double) fileSize / chunkSize);

        List<byte[]> chunks = new ArrayList<>();

        for (int i = 0; i < numChunks; i++) {
            long offset = i * chunkSize;
            int length = Math.min(chunkSize, (int) fileSize - offset);

            byte[] chunk = new byte[length];
            try (FileInputStream inputStream = new FileInputStream(file)) {
                inputStream.skip(offset);
                inputStream.read(chunk);
            }

            chunks.add(chunk);
        }

        return chunks;
    }

    private List<FileMetadata> retrieveChunkMetadatas(List<byte[]> chunks) {
        // Implement this method to retrieve metadata for each uploaded chunk, e.g., upload time and MD5 checksum
        return new ArrayList<>();
    }

    private FileMetadata combineChunkMetadatas(List<FileMetadata> chunkMetadatas, String fileName, long fileSize) {
        // Implement this method to combine the chunk metadatas to get the final file metadata
        return new FileMetadata();
    }

    class FileMetadata {
        private String fileName;
        private long fileSize;
        private String uploadTime;
        private String md5Checksum;

        public FileMetadata(String fileName, long fileSize, String uploadTime, String md5Checksum) {
            this.fileName = fileName;
            this.fileSize = fileSize;
            this.uploadTime = uploadTime;
            this.md5Checksum = md5Checksum;
