void manageNFAPI_CRC_INDICATION_PDU(const NFAPI_CRC_INDICATION_PDU& pdu) {
    // Add new entry to the list if not already present
    if (allowedClients.find(pdu.RNTI) == allowedClients.end()) {
        allowedClients[pdu.RNTI] = std::string();
    }

    // Update existing entry with new RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
    allowedClients[pdu.RNTI].RX_UE_INFORMATION_TAG = pdu.RX_UE_INFORMATION_TAG;
    allowedClients[pdu.RNTI].CRC_INDICATION_REL8_TAG = pdu.CRC_INDICATION_REL8_TAG;
}

// Define the function to remove an entry from the list based on RNTI
void removeNFAPI_CRC_INDICATION_PDU(int rnti) {
