}

// Define the function to handle concurrent access from multiple threads and ensure thread safety
void manageConcurrentAccess() {
    // Use a mutex to synchronize access to the list of allowed clients
    std::mutex mtx;

    // Use a condition variable to signal when a new entry is added or an existing entry is updated
    std::condition_variable cv;

    // Define a function to add a new entry to the list and notify all waiting threads
    void addNewEntry(int rnti, int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
        std::unique_lock<std::mutex> lck(mtx);
        allowedClients[rnti] = NFAPI_CRC_INDICATION_PDU{RX_UE_INFORMATION_TAG, rnti, CRC_INDICATION_REL8_TAG};
        cv.notify_all();
    }

    // Define a function to update an existing entry and notify all waiting threads
    void updateEntry(int rnti, int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
        std::unique_lock<std::mutex> lck(mtx);
        allowedClients[rnti].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        allowedClients[rnti].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        cv.notify_all();
    }

    // Define a function to remove an entry from the list and notify all waiting threads
    void removeEntry(int rnti) {
        std::unique_lock<std::mutex> lck(mtx);
        allowedClients.erase(rnti);
        cv.notify_all();
    }
}

