```javascript
const express = require('express');
const app = express();
const db = require('monk')('mongodb://localhost/env_data');
const logger = require('logdna').createLogger();

// Setup routes for incoming sensor data
app.post('/sensors', (req, res) => {
  const sensorData = req.body;
  // Validate and normalize sensor data
  if (!sensorData.temperature || !sensorData.humidity) {
    logger.warn('Skipping invalid sensor data: ', sensorData);
    return res.status(400).send('Invalid sensor data');
  }
  const normalizedData = {
    temperature: sensorData.temperature,
    humidity: sensorData.humidity,
  };
  // Persist normalized data to database
  db.collection('env_data').insertOne(normalizedData)
    .then(() => res.status(201).send())
    .catch((err) => {
      logger.error('Failed to persist sensor data: ', err);
      return res.status(500).send('Internal server error');
    });
});

