    // insert elements into the map
    myMap["apple"] = 10;
    myMap["banana"] = 20;
    myMap["orange"] = 30;

    // search for an element in the map
    if (myMap.find("apple") != myMap.end()) {
        cout << "Element found: " << myMap["apple"] << endl;
    } else {
        cout << "Element not found" << endl;
    }

    // search for an element in the map using case-insensitive comparison
    if (myMap.find("APPLE", [](const string& a, const string& b) { return a == b || tolower(a[0]) == tolower(b[0]); }) != myMap.end()) {
        cout << "Element found: " << myMap["apple"] << endl;
    } else {
        cout << "Element not found" << endl;
    }

    return 0;
}
