import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.model.ObjectMetadata;
import com.google.cloud.storage.Bucket;
import com.google.cloud.storage.Storage;
import com.google.cloud.storage.StorageOptions;

public class ImageUploader {
    private static final int DEFAULT_COMPRESSION_LEVEL = 6;
    private static final String DEFAULT_ENCRYPTION_METHOD = "aes-256-cbc";

    public Map<String, Object> uploadImages(List<byte[]> images) {
        // Create a map to store the metadata of the uploaded images
        Map<String, Object> imageMetadata = new HashMap<>();

        // Check if the input list is empty
        if (images.isEmpty()) {
            return imageMetadata;
        }

        try {
            // Decompress and encrypt each image in the list
            List<byte[]> decompressedImages = decompressAndEncrypt(images);

            // Upload the decompressed images to the cloud storage provider
            Storage storage = StorageOptions.getDefaultInstance().getService();
            Bucket bucket = storage.get(config.getBucketName());
            ObjectMetadata metadata = new ObjectMetadata()
                .setContentType("image/jpeg")
                .setCacheControl("public, max-age=31536000");

            // Upload each image to the cloud storage provider
            for (byte[] image : decompressedImages) {
                String fileName = UUID.randomUUID().toString() + ".jpg";
                byte[] fileBytes = compressAndDecrypt(image);

                try {
                    bucket.create(fileName, fileBytes, metadata);
                    imageMetadata.put(fileName, "success");
                } catch (StorageException e) {
                    // Handle storage exception
                    log.error("Failed to upload {} to cloud storage: {}", fileName, e.getMessage());
                    imageMetadata.put(fileName, "failed");
                }
            }
        } catch (IOException | GeneralSecurityException e) {
            // Handle I/O and security exception
            log.error("Failed to upload images: {}", e.getMessage());
            return null;
        } finally {
            // Close the storage client
            if (storage != null) {
                storage.close();
            }
        }

        return imageMetadata;
    }

    private List<byte[]> decompressAndEncrypt(List<byte[]> images) throws IOException, GeneralSecurityException {
        // Decompress and encrypt each image in the list
        return images.stream()
            .map(image -> {
                try {
                    byte[] decompressedImage = ZipUtil.decompress(image);
                    byte[] encryptedImage = EncryptionUtils.encrypt(decompressedImage, DEFAULT_ENCRYPTION_METHOD);
                    return encryptedImage;
                } catch (IOException | GeneralSecurityException e) {
                    // Handle I/O and security exception
                    log.error("Failed to decompress and encrypt image: {}", e.getMessage());
                    return null;
                }
            })
            .filter(Objects::nonNull)
            .collect(Collectors.toList());
    }

    private byte[] compressAndDecrypt(byte[] image) throws IOException, GeneralSecurityException {
        // Decompress and encrypt each image in the list
        return image;
    }
