```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/engine.h>
#include <openssl/rand.h>

#define MIN_KEY_LEN 16
#define MAX_KEY_LEN 32

struct key {
    char *key;
    int len;
};

struct config {
    struct key aes_key;
    struct key camellia_key;
    struct key md5_key;
    struct key sha_key;
    struct key rsa_key;
    struct key rsa_pub_key;
    char *rsa_pub_exp;
};

struct config config;

int init_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error opening configuration file\n");
        return -1;
    }

    int ret = 0;

    // Read AES key from config file
    ret = read_key(&config.aes_key, file);
    if (ret != 0) {
        printf("Error reading AES key\n");
        return -1;
    }

    // Read Camellia key from config file
    ret = read_key(&config.camellia_key, file);
    if (ret != 0) {
        printf("Error reading Camellia key\n");
        return -1;
    }

    // Read MD5 key from config file
    ret = read_key(&config.md5_key, file);
    if (ret != 0) {
        printf("Error reading MD5 key\n");
        return -1;
    }

    // Read SHA key from config file
    ret = read_key(&config.sha_key, file);
    if (ret != 0) {
        printf("Error reading SHA key\n");
        return -1;
    }

    // Read RSA key and public exponent from config file
    ret = read_rsa_keys(&config, file);
    if (ret != 0) {
        printf("Error reading RSA keys\n");
        return -1;
    }

    fclose(file);
    return 0;
}

int read_key(struct key *key, FILE *file) {
    char line[128];
    while (fgets(line, sizeof(line), file)) {
        if (!strncmp(line, "Key: ", 5)) {
            // Extract the key from the line
            int len = strlen(line + 5);
            char *key_str = malloc(len + 1);
            memcpy(key_str, line + 5, len);
            key_str[len] = '\0';

            // Check if the key is valid and of sufficient length
            if (is_valid_key(key_str)) {
                int key_len = strlen(key_str) / 2;
                if (key_len < MIN_KEY_LEN || key_len > MAX_KEY_LEN) {
                    printf("Error: Key length not within valid range\n");
                    return -1;
                }
                key->key = key_str;
                key->len = key_len;
            } else {
                printf("Error: Invalid key format\n");
                free(key_str);
                return -1;
            }
        }
    }
    return 0;
}

int read_rsa_keys(struct config *config, FILE *file) {
    char line[128];
    while (fgets(line, sizeof(line), file)) {
        if (!strncmp(line, "RSA Key: ", 9)) {
            // Extract the RSA key from the line
            int len = strlen(line + 9);
            char *key_str = malloc(len + 1);
            memcpy(key_str, line + 9, len);
            key_str[len] = '\0';

            // Check if the RSA key is valid and of sufficient length
            if (is_valid_rsa_key(key_str)) {
                int key_len = strlen(key_str) / 2;
                if (key_len < MIN_KEY_LEN || key_len > MAX_KEY_LEN) {
                    printf("Error: RSA Key length not within valid range\n");
                    return -1;
                }
                config->rsa_key = key_str;
            } else {
                printf("Error: Invalid RSA key format\n");
                free(key_str);
                return -1;
            }
        } else if (!strncmp(line, "RSA Public Exponent: ", 20)) {
            // Extract the public exponent from the line
            int len = strlen(line + 20);
            char *exp_str = malloc(len + 1);
            memcpy(exp_str, line + 20, len);
            exp_str[len] = '\0';

            // Check if the public exponent is valid and of sufficient length
            if (is_valid_rsa_exp(exp_str)) {
                int exp_len = strlen(exp_str) / 2;
                if (exp_len < MIN_KEY_LEN || exp_len > MAX_KEY_LEN) {
                    printf("Error: Public exponent length not within valid range\n");
                    return -1;
                }
                config->rsa_pub_exp = exp_str;
            } else {
                printf("Error: Invalid public exponent format\n");
                free(exp_str);
                return -1;
            }
        }
    }
    return 0;
}

int is_valid_key(char *key) {
    // Check if the key is in valid hexadecimal format (even length)
    int len = strlen(key);
    if (len % 2 != 0 || !isxdigit(key[0])) {
        return 0;
    }

    // Check if all characters in the key are valid hexadecimal digits
    for (int i = 1; i < len; i++) {
        if (!isxdigit(key[i]) || !isxdigit(key[i - 1])) {
            return 0;
        }
    }
    return 1;
}

int is_valid_rsa_key(char *key) {
    // Check if the key is in valid hexadecimal format (even length)
    int len = strlen(key);
    if (len % 2 != 0 || !isxdigit(key[0])) {
        return 0;
    }

    // Check if all characters in the key are valid hexadecimal digits
    for (int i = 1; i < len; i++) {
        if (!isxdigit(key[i]) || !isxdigit(key[i - 1])) {
            return 0;
        }
    }

    // Check if the modulus length is sufficient for RSA key exchange
    int mod_len = len / 2;
    if (mod_len < MIN_KEY_LEN || mod_len > MAX_KEY_LEN) {
        return 0;
    }
    return 1;
}

int is_valid_rsa_exp(char *exp) {
    // Check if the public exponent is in valid hexadecimal format (even length)
    int len = strlen(exp);
    if (len % 2 != 0 || !isxdigit(exp[0])) {
        return 0;
    }

    // Check if all characters in the public exponent are valid hexadecimal digits
    for (int i = 1; i < len; i++) {
        if (!isxdigit(exp[i]) || !isxdigit(exp[i - 1])) {
            return 0;
        }
    }

    // Check if the public exponent is a valid value (2, 3, or 17)
    int exp_val = strtol(exp, NULL, 16);
    if (exp_val != 2 && exp_val != 3 && exp_val != 17) {
        return 0;
    }
    return 1;
}
