```
void insertAfter(std::forward_list<std::string> &list, const std::string &str1, const std::string &str2) {
  // Find the first occurrence of str1 in the list
  auto it = std::find(list.begin(), list.end(), str1);

  // If str1 was found, insert str2 after it
  if (it != list.end()) {
    list.insert_after(it, str2);
  } else {
    // If str1 was not found, insert str2 at the end of the list
    list.push_back(str2);
  }
}
