```
using System.Data;
using System.Data.SqlClient;

public static DataTableReader ExecuteQuery(byte[] data) {
  // Validate input parameters
  if (data == null || data.Length == 0) {
    throw new ArgumentException("Invalid argument: 'data' must be a non-empty byte array.");
  }

  // Connect to the database server using the specified connection string
  SqlConnection conn = new SqlConnection("connection_string");
  try {
    conn.Open();
  } catch (SqlException ex) {
    Console.WriteLine("Error opening SQL connection: " + ex.Message);
    return null;
  }

  // Create a command object and set the query string
  SqlCommand cmd = new SqlCommand();
  cmd.Connection = conn;
  cmd.CommandText = "query_string";

  // Add the input data as a parameter to the command object
  cmd.Parameters.Add(new SqlParameter("@data", data));

  // Execute the query and retrieve the results
  try {
    SqlDataReader reader = cmd.ExecuteReader();
    return new DataTableReader(reader);
  } catch (SqlException ex) {
    Console.WriteLine("Error executing SQL command: " + ex.Message);
    return null;
  } finally {
    conn.Close();
  }
}
