class StockMarketDataProcessor {
  private final Map<String, DataSource> dataSources = new HashMap<>();
  private final ExecutorService executor;
  private final Dashboard dashboard;

  public StockMarketDataProcessor(ExecutorService executor, Dashboard dashboard) {
    this.executor = executor;
    this.dashboard = dashboard;
  }

  public void addDataSource(String symbol, DataSource dataSource) {
    dataSources.put(symbol, dataSource);
  }

  public void removeDataSource(String symbol) {
    dataSources.remove(symbol);
  }

  public Stream<StockData> getStockDataStream(String symbol) {
    return dataSources.get(symbol).getDataStream();
  }

  public Map<String, StockData> getLatestStockData() {
    return dataSources.values().stream()
      .flatMap(dataSource -> dataSource.getDataStream())
      .collect(Collectors.toMap(StockData::getSymbol, Function.identity()));
  }

  public void updateStockData(String symbol, StockData stockData) {
    DataSource dataSource = dataSources.get(symbol);
    if (dataSource != null) {
      dataSource.updateData(stockData);
    }
  }

  public void processStockData(String symbol, List<StockData> stockDataList) {
    DataSource dataSource = dataSources.get(symbol);
    if (dataSource != null) {
      for (StockData stockData : stockDataList) {
        dataSource.processData(stockData);
      }
    }
  }

  public void handleDataSourceError(String symbol, Exception e) {
    DataSource dataSource = dataSources.get(symbol);
    if (dataSource != null) {
      dataSource.handleError(e);
    }
  }
}

