#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <openssl/pem.h>
#include <stdlib.h>
#include <stdio.h>

// Function to initialize an AES-256-CBC cipher with a given password, salt, and iteration count
int init_aes_cbc(const char* password, const char* salt, int iter_count) {
    // Define the key length and IV length for AES-256-CBC
    const int KEY_LEN = 32;
    const int IV_LEN = 16;

    // Declare variables for the derived key and IV
    unsigned char key[KEY_LEN];
    unsigned char iv[IV_LEN];

    // Generate a random salt if one is not provided
    if (salt == NULL) {
        unsigned char rand_salt[64];
        RAND_bytes(rand_salt, 64);
        salt = (char*)rand_salt;
    }

    // Derive the encryption key and IV from the password using SHA-256 and PBKDF2
    PKCS5_PBKDF2_HMAC(password, strlen(password), (const unsigned char*)salt, strlen(salt), iter_count, EVP_sha256(), KEY_LEN + IV_LEN, key);
    memcpy(iv, key + KEY_LEN, IV_LEN);
    OPENSSL_cleanse(key, KEY_LEN); // Cleanse the memory of the derived key

    // Initialize the AES-256-CBC cipher with the derived key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    OPENSSL_cleanse(key, KEY_LEN + IV_LEN); // Cleanse the memory of the derived key and IV

    return ctx;
}

// Function to clean up and disable an AES-256-CBC cipher
void cleanup_aes_cbc(EVP_CIPHER_CTX* ctx) {
    // Check if the cipher is initialized before attempting to clean it up
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx); // Free the memory allocated for the cipher context
    }
}

// Test code for the above functions
int main() {
    const char* password = "password";
    const char* salt = "salt";
    int iter_count = 1000;

    // Initialize and encrypt a message using the AES-256-CBC cipher
    EVP_CIPHER_CTX* ctx = init_aes_cbc(password, salt, iter_count);
    unsigned char plaintext[] = "Hello, World!";
    int plaintext_len = strlen((const char*)plaintext);
    unsigned char ciphertext[plaintext_len];
    int ciphertext_len;
    EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    printf("Ciphertext: ");
    for (int i = 0; i < ciphertext_len; i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    // Clean up the AES-256-CBC cipher and exit
    cleanup_aes_cbc(ctx);
    return 0;
}

