                // Validate the key and IV fetched from the secure external key management service.
                if (_cipher.Key == null || _cipher.IV == null)
                {
                    throw new Exception("Invalid key or initialization vector.");
                }

                // Decrypt the ciphertext using AES-GCM with the specified padding mode.
                byte[] plaintext = _cipher.Decrypt(ciphertext, paddingMode);

