#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU;

// Define a structure to hold the data for each thread
typedef struct {
    NFAPI_CRC_INDICATION_PDU pdu;
    bool running;
} ThreadData;

// Define a function to generate and populate a list of NFAPI_CRC_INDICATION_PDUs
void generate_nfaapi_crc_indications(int num_threads) {
    // Initialize the thread pool with the number of threads requested
    pthread_t threads[num_threads];
    ThreadData *data = (ThreadData *)malloc(sizeof(ThreadData) * num_threads);

    for (int i = 0; i < num_threads; i++) {
        data[i].running = true;

        // Create a new thread to generate and populate the list of NFAPI_CRC_INDICATION_PDUs
        pthread_create(&threads[i], NULL, (void *(*)(void *))generate_crc_indications, data + i);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated for the thread data
    free(data);
}

// Define a function that generates and populates a list of NFAPI_CRC_INDICATION_PDUs in a single thread
void generate_crc_indications(ThreadData *data) {
    // Initialize the list of NFAPI_CRC_INDICATION_PDUs to an empty list
    List<NFAPI_CRC_INDICATION_PDU> crc_indications;

    // Generate and populate the list of NFAPI_CRC_INDICATION_PDUs in a loop
    while (data->running) {
        // Extract a random RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG value from an external data source
        int rx_ue_information_tag = get_random_rx_ue_information_tag();
        int rnti = get_random_rnti();
        bool crcflag = get_random_crcflag();

        // Create a new NFAPI_CRC_INDICATION_PDU and add it to the list
        NFAPI_CRC_INDICATION_PDU pdu;
        pdu.rx_ue_information_tag = rx_ue_information_tag;
        pdu.rnti = rnti;
        pdu.crc_indication_rel8_tag = crcflag ? 1 : 0;
        crc_indications.add(pdu);
    }

    // Return the list of NFAPI_CRC_INDICATION_PDUs to the caller
    return crc_indications;
}
