// Define a function to run the given command in the background and calculate its MD5 hash
void run_command_and_calculate_md5(char *cmd, size_t len) {
    // Fork a child process to run the command
    pid_t pid = fork();

    if (pid == 0) {
        // In the child process, execute the command and calculate its MD5 hash
        char buf[len];
        int status = read(STDIN_FILENO, buf, len);

        if (status > 0) {
            printf("Command output: %s\n", buf);

            // Calculate the MD5 hash of the command output
            unsigned char md5[MD5_DIGEST_LENGTH];
            MD5(buf, len, md5);

            // Print the MD5 hash
            printf("MD5 hash: ");
            for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
                printf("%02x", md5[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Error reading from stdin\n");
        }

        // Exit the child process
        exit(EXIT_SUCCESS);
    } else if (pid > 0) {
        // In the parent process, wait for the child process to complete and free its resources
        int status;
        wait(&status);

        printf("Child process exited with status %d\n", WEXITSTATUS(status));
    } else {
        fprintf(stderr, "Error forking a new process: %s\n", strerror(errno));
    }
}
