using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

namespace MultiLanguageApplicationModule
{
    public class DatabaseConnection
    {
        private readonly string _connectionString;
        private readonly SqlCommandBehavior _commandBehavior;
        private readonly int _commandTimeout;
        private readonly IsolationLevel _isolationLevel;

        public DatabaseConnection(string connectionString, SqlCommandBehavior commandBehavior, int commandTimeout, IsolationLevel isolationLevel)
        {
            _connectionString = connectionString;
            _commandBehavior = commandBehavior;
            _commandTimeout = commandTimeout;
            _isolationLevel = isolationLevel;
        }

        public async Task<SqlDataReader> ExecuteReaderAsync(string query, object[] parameters)
        {
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            using var command = new SqlCommand(query, connection);
            command.CommandBehavior = _commandBehavior;
            command.CommandTimeout = _commandTimeout;
            command.Transaction.IsolationLevel = _isolationLevel;
            command.Parameters.AddRange(parameters);

            return await command.ExecuteReaderAsync();
        }

        public async Task<SqlDataAdapter> ExecuteAdapterAsync(string query, object[] parameters)
        {
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            using var command = new SqlCommand(query, connection);
            command.CommandBehavior = _commandBehavior;
            command.CommandTimeout = _commandTimeout;
            command.Transaction.IsolationLevel = _isolationLevel;
            command.Parameters.AddRange(parameters);

            return new SqlDataAdapter(command);
        }

        public async Task<int> ExecuteNonQueryAsync(string query, object[] parameters)
        {
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            using var command = new SqlCommand(query, connection);
            command.CommandBehavior = _commandBehavior;
            command.CommandTimeout = _commandTimeout;
            command.Transaction.IsolationLevel = _isolationLevel;
            command.Parameters.AddRange(parameters);

            return await command.ExecuteNonQueryAsync();
        }
    }
}
