import logging
import requests
from requests_oauthlib import OAuth2Session

logging.basicConfig(level=logging.INFO)

class DatabaseConnection:
    def __init__(self, connection_string):
        self.connection_string = connection_string

    def execute_reader(self, query, parameters):
        with requests.Session() as session:
            session.headers = {
                "Content-Type": "application/json"
            }
            response = session.post(f"{self.connection_string}/query", json={"query": query, "parameters": parameters})
            if response.status_code == 200:
                return response.json()["data"]
            else:
                logging.error(f"Failed to execute query: {response.text}")

    def execute_adapter(self, query, parameters):
        with requests.Session() as session:
            session.headers = {
