                "Content-Type": "application/json"
            }
            response = session.post(f"{self.database_connection}/query", json={"query": query, "parameters": parameters})
            if response.status_code == 200:
                return response.json()["data"]
            else:
                logging.error(f"Failed to execute query: {response.text}")

    def update_settings(self, settings):
        self.game_settings.update_settings(settings)
