The `get`, `put`, `get_int`, and `put_int` methods are used to interact with the cache objects in a thread-safe manner. The `get` method retrieves a token from the cache by its username as key, while the `put` method adds a token to the cache with a username as key and token as value. Similarly, the `get_int` method retrieves an integer from the cache at the given index, while the `put_int` method adds an integer to the cache at the next available index.

The system includes a robust error handling mechanism for network failures, invalid URLs, and parsing errors, as well as a min-heap data structure to keep track of the largest number as new integers are read, minimizing memory usage and maximizing performance. Additionally, it supports configuration through a configuration file or environment variables, with a flexible update mechanism, and includes APIs to monitor the health and status of the token generation and resource bundle loading processes.

Here is a sample C function that parses a TIFF image file and extracts detailed information about the image's bits per sample, sample per pixel, compression method, image dimensions, and photometric interpretation:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Define constants for TIFF tags
#define TAG_BITS_PER_SAMPLE 256
#define TAG_SAMPLES_PER_PIXEL 257
#define TAG_COMPRESSION_METHOD 259
#define TAG_IMAGE_DIMENSIONS 263
#define TAG_PHOTOMETRIC_INTERPRETATION 262
#define TAG_EXTRA_SAMPLES 338
#define TAG_STRIP_OFFSETS 273
#define TAG_STRIP_BYTE_COUNTS 279

// Define constants for TIFF compression methods
#define COMPRESSION_NONE 1
#define COMPRESSION_CCITT_RLE 3
#define COMPRESSION_CCITT_GROUP_3 32771
#define COMPRESSION_CCITT_GROUP_4 32773
#define COMPRESSION_LZW 5
#define COMPRESSION_JPEG 6
#define COMPRESSION_DEFLATE 8
#define COMPRESSION_PACKBITS 32773

// Define constants for TIFF photometric interpretations
#define PHOTOMETRIC_INTERPRETATION_WHITE_IS_ZERO 0
#define PHOTOMETRIC_INTERPRETATION_BLACK_IS_ZERO 16
#define PHOTOMETRIC_INTERPRETATION_RGB 2
#define PHOTOMETRIC_INTERPRETATION_PALETTE_COLOR 3
#define PHOTOMETRIC_INTERPRETATION_TRANSPARENCY 4
#define PHOTOMETRIC_INTERPRETATION_SEPARATED 5
#define PHOTOMETRIC_INTERPRETATION_YCBCR 6
#define PHOTOMETRIC_INTERPRETATION_CIELAB 7

// Define constants for TIFF extra samples
#define EXTRA_SAMPLES_UNSUPPORTED 0
#define EXTRA_SAMPLES_ASSOCIATED_ALPHA 1
#define EXTRA_SAMPLES_UNASSOCIATED_ALPHA 2

// Define constants for TIFF image dimensions
#define IMAGE_DIMENSIONS_WIDTH 0
#define IMAGE_DIMENSIONS_HEIGHT 1

// Define structure to hold TIFF metadata
typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int compressionMethod;
    int photometricInterpretation;
    int extraSamples;
    int stripOffsets[];
    int stripByteCounts[];
} TiffMetadata;

// Function to parse a TIFF file and extract metadata
int parseTiff(const char* filename, TiffMetadata* metadata) {
    // Open the TIFF file for reading
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return 0;
    }

    // Read the TIFF header
    int header[2];
    if (fread(&header, sizeof(int), 2, file) != 2) {
        fclose(file);
        return 0;
    }

    // Check for the TIFF magic number
    if (header[0] != 73 || header[1] != 73) {
        fclose(file);
        return 0;
    }

    // Read the directory offset
    int directoryOffset;
    if (fread(&directoryOffset, sizeof(int), 1, file) != 1) {
        fclose(file);
        return 0;
    }

    // Seek to the start of the directory
    fseek(file, directoryOffset, SEEK_SET);

    // Read the directory entries
    int entryCount;
    if (fread(&entryCount, sizeof(int), 1, file) != 1) {
        fclose(file);
        return 0;
    }

    for (int i = 0; i < entryCount; i++) {
        // Read the tag and data type
        int tag, dataType;
        if (fread(&tag, sizeof(int), 1, file) != 1 || fread(&dataType, sizeof(int), 1, file) != 1) {
            break;
        }

        // Check for the tags we want to extract
        if (tag == TAG_BITS_PER_SAMPLE || tag == TAG_SAMPLES_PER_PIXEL ||
            tag == TAG_COMPRESSION_METHOD || tag == TAG_IMAGE_DIMENSIONS ||
            tag == TAG_PHOTOMETRIC_INTERPRETATION || tag == TAG_EXTRA_SAMPLES) {

            // Read the data count and value(s)
            int dataCount, dataValue;
            if (fread(&dataCount, sizeof(int), 1, file) != 1) {
                break;
            }

            for (int j = 0; j < dataCount; j++) {
                // Read the value and update the metadata structure accordingly
                if (fread(&dataValue, sizeof(int), 1, file) != 1) {
                    break;
                }

                switch (tag) {
                    case TAG_BITS_PER_SAMPLE:
                        metadata->bitsPerSample = dataValue;
                        break;
                    case TAG_SAMPLES_PER_PIXEL:
                        metadata->samplesPerPixel = dataValue;
                        break;
                    case TAG_COMPRESSION_METHOD:
                        metadata->compressionMethod = dataValue;
                        break;
                    case TAG_IMAGE_DIMENSIONS:
                        metadata->imageDimensions[i] = dataValue;
                        break;
                    case TAG_PHOTOMETRIC_INTERPRETATION:
                        metadata->photometricInterpretation = dataValue;
                        break;
                    case TAG_EXTRA_SAMPLES:
                        metadata->extraSamples = dataValue;
                        break;
                }
            }
        } else if (tag == TAG_STRIP_OFFSETS || tag == TAG_STRIP_BYTE_COUNTS) {
            // Read the data count and value(s)
            int dataCount;
            if (fread(&dataCount, sizeof(int), 1, file) != 1) {
                break;
            }

            for (int j = 0; j < dataCount; j++) {
                // Read the value and update the metadata structure accordingly
                int dataValue;
                if (fread(&dataValue, sizeof(int), 1, file) != 1) {
                    break;
                }

                switch (tag) {
                    case TAG_STRIP_OFFSETS:
                        metadata->stripOffsets[i] = dataValue;
                        break;
                    case TAG_STRIP_BYTE_COUNTS:
                        metadata->stripByteCounts[i] = dataValue;
                        break;
                }
            }
        }
    }

    // Close the file and return 1 if no errors occurred
    fclose(file);
    return 1;
}

int main() {
    TiffMetadata metadata;
    parseTiff("example.tif", &metadata);

    // Print the extracted metadata
    printf("Bits per sample: %d\n", metadata.bitsPerSample);
    printf("Samples per pixel: %d\n", metadata.samplesPerPixel);
    printf("Compression method: %d\n", metadata.compressionMethod);
    printf("Photometric interpretation: %d\n", metadata.photometricInterpretation);
    printf("Extra samples: %d\n", metadata.extraSamples);
    for (int i = 0; i < metadata.stripOffsets.size(); i++) {
        printf("Strip offset %d: %d\n", i, metadata.stripOffsets[i]);
        printf("Strip byte count %d: %d\n", i, metadata.stripByteCounts[i]);
    }

    return 0;
}
```

This code first opens the TIFF file for reading and reads the TIFF header to ensure it is a valid TIFF file. It then reads the directory offset from the header and seeks to the start of the directory in the file. It then reads the number of entries in the directory and iterates over each entry, reading the tag and data type and using a switch statement to extract the relevant metadata. For tags that have multiple values, it reads the data count and value(s) and updates the metadata structure accordingly.

The code also uses a `TiffMetadata` structure to store the extracted metadata. This structure contains fields for each of the metadata elements that are of interest, along with arrays for the strip offsets and byte counts. The size of these arrays is determined by the number of entries in the directory, which can be different for each file.

Finally, the code prints out the extracted metadata using `printf` statements. This output can be used to generate reports or other analysis of the TIFF files being processed.

