using System;
using System.Security.Cryptography;
using System.Threading;

namespace DynamicSecureRandomNumberGenerator
{
    public class RandomNumberGenerator : IRandomNumberGenerator
    {
        private readonly object _lock = new object();
        private readonly RNGCryptoServiceProvider _csp = new RNGCryptoServiceProvider();
        private readonly ISeedSource _seedSource;
        private readonly bool _reproducible;

        public RandomNumberGenerator(ISeedSource seedSource, bool reproducible = false)
        {
            _seedSource = seedSource;
            _reproducible = reproducible;
        }

        public float GenerateRandomFloat(float minValue, float maxValue)
        {
            // Validate input parameters
            if (minValue >= maxValue)
                throw new ArgumentException($"Invalid range specified: {minValue} to {maxValue}.");

            var exclusiveMax = maxValue.ToString().EndsWith("]");
            var inclusiveMin = minValue.ToString().StartsWith("[");

            // Generate random number within the specified range
            float randomNumber;
            do
            {
                var buffer = new byte[4];
                lock (_lock) _csp.GetNonZeroBytes(buffer);
                randomNumber = BitConverter.ToSingle(buffer, 0);
            } while (randomNumber < minValue || randomNumber >= maxValue);

            // Adjust for inclusive or exclusive range specifications
            if (exclusiveMax) randomNumber -= 1;
            else if (inclusiveMin) randomNumber += 1;

            return randomNumber;
        }

        public int GenerateRandomInt(int minValue, int maxValue)
        {
            // Validate input parameters
            if (minValue >= maxValue)
                throw new ArgumentException($"Invalid range specified: {minValue} to {maxValue}.");

            var exclusiveMax = maxValue.ToString().EndsWith("]");
            var inclusiveMin = minValue.ToString().StartsWith("[");

            // Generate random number within the specified range
            int randomNumber;
            do
            {
                var buffer = new byte[4];
                lock (_lock) _csp.GetNonZeroBytes(buffer);
                randomNumber = BitConverter.ToInt32(buffer, 0);
            } while (randomNumber < minValue || randomNumber >= maxValue);

            // Adjust for inclusive or exclusive range specifications
            if (exclusiveMax) randomNumber -= 1;
            else if (inclusiveMin) randomNumber += 1;

            return randomNumber;
        }

        public float GenerateSeededRandomFloat(float minValue, float maxValue, byte[] seed)
        {
            // Validate input parameters and seed value
            if (minValue >= maxValue)
                throw new ArgumentException($"Invalid range specified: {minValue} to {maxValue}.");
            if (seed.Length != 4)
                throw new ArgumentException("Seed value must be exactly 4 bytes.", nameof(seed));

            var exclusiveMax = maxValue.ToString().EndsWith("]");
            var inclusiveMin = minValue.ToString().StartsWith("[");

            // Generate random number within the specified range using seed value
            float randomNumber;
            do
            {
                var buffer = new byte[4];
                lock (_lock) _csp.GetNonZeroBytes(buffer);
                randomNumber = BitConverter.ToSingle(seed, 0);
            } while (randomNumber < minValue || randomNumber >= maxValue);

            // Adjust for inclusive or exclusive range specifications
            if (exclusiveMax) randomNumber -= 1;
            else if (inclusiveMin) randomNumber += 1;

            return randomNumber;
        }

        public int GenerateSeededRandomInt(int minValue, int maxValue, byte[] seed)
        {
            // Validate input parameters and seed value
            if (minValue >= maxValue)
                throw new ArgumentException($"Invalid range specified: {minValue} to {maxValue}.");
            if (seed.Length != 4)
                throw new ArgumentException("Seed value must be exactly 4 bytes.", nameof(seed));

            var exclusiveMax = maxValue.ToString().EndsWith("]");
            var inclusiveMin = minValue.ToString().StartsWith("[");

            // Generate random number within the specified range using seed value
            int randomNumber;
            do
            {
                var buffer = new byte[4];
                lock (_lock) _csp.GetNonZeroBytes(buffer);
                randomNumber = BitConverter.ToInt32(seed, 0);
            } while (randomNumber < minValue || randomNumber >= maxValue);

            // Adjust for inclusive or exclusive range specifications
            if (exclusiveMax) randomNumber -= 1;
            else if (inclusiveMin) randomNumber += 1;

            return randomNumber;
        }
    }
