import json
import time
from datetime import datetime

import paho.mqtt.client as mqtt
from anomaly_detection import detect_anomalies

class IoTMonitor:
    def __init__(self, device_filters, threshold_filters):
        self.device_filters = device_filters
        self.threshold_filters = threshold_filters
        self.connections = {}
        self.data_queue = {}
        self.anomalies = []

    def establish_connection(self, device_id):
        if device_id in self.connections:
            return self.connections[device_id]
        else:
            client = mqtt.Client()
            client.connect("mqtt://<broker>")
            self.connections[device_id] = client
            return client

    def handle_message(self, client, userdata, message):
        device_id = message.topic.split("/")[-1]
        if device_id in self.device_filters:
            try:
                data = json.loads(message.payload)
                if self.validate_data(data):
                    if device_id not in self.data_queue:
                        self.data_queue[device_id] = []
                    self.data_queue[device_id].append(data)
            except json.decoder.JSONDecodeError as e:
                print("Invalid JSON payload")

    def validate_data(self, data):
        if "sensor" in data and "value" in data["sensor"]:
            if data["sensor"]["type"] == "energy":
                return True
            else:
                print("Unsupported sensor type")
        else:
            print("Missing required fields")
        return False

    def process_data(self):
        for device_id, data in self.data_queue.items():
            if len(data) > 10:
                self.anomalies = []
                for i in range(len(data)-1):
                    for j in range(i+1, len(data)):
                        time_diff = (data[j]["timestamp"] - data[i]["timestamp"]).total_seconds()
                        if time_diff > 60:
                            break
                        else:
                            self.anomalies.append((device_id, data[i], data[j]))
                for anomaly in self.anomalies:
                    device_id = anomaly[0]
                    data1 = anomaly[1]
                    data2 = anomaly[2]
                    if detect_anomalies(data1, data2):
                        print("Anomaly detected!")
                        # Log anomaly to database
                        with open("anomalies.txt", "a+") as f:
                            f.write(f"{device_id},{data1['timestamp']},{data2['timestamp']}\n")
                        # Send alert to user
                        # ...
                self.data_queue[device_id] = data[-10:]
        time.sleep(1)

if __name__ == "__main__":
    device_filters = ["sensor=energy"]
    threshold_filters = {"sudden_spike": 2, "gradual_increase": 1.5}
    monitor = IoTMonitor(device_filters, threshold_filters)
    client = mqtt.Client()
    client.connect("mqtt://<broker>")
    client.subscribe("#")
    client.on_message = monitor.handle_message
    while True:
        try:
            client.loop(1)
        except Exception as e:
            print(f"Error in loop(): {e}")
