#include <ImageMagick.h>
#include "custom_parser.h"

#define MAX_IMAGE_SIZE 1024 * 1024 * 50 // 50 MB
#define MIN_COMPRESSION_RATIO 1.0
#define MAX_COMPRESSION_RATIO 10.0
#define MAX_DIMENSIONS 3072
#define ICC_PROFILE_SIZE 4096
#define EXIF_DATA_SIZE 256

// Enum for image formats
typedef enum {JPEG, PNG, GIF, BMP} ImageFormat;

// Struct for storing metadata extracted from PDF files
typedef struct {
    unsigned int dimensions[2];
    char color_profile[ICC_PROFILE_SIZE];
    char compression_type[EXIF_DATA_SIZE];
    float compression_ratio;
} Metadata;

// Struct for storing image data and metadata
typedef struct {
    ImageFormat format;
    unsigned char* data;
    size_t size;
    Metadata meta;
} ImageData;

// Function to convert an image file from one format to another
int convert_image(ImageFormat src, ImageFormat dst, const char* input_path, const char* output_path) {
    // Initialize variables for conversion parameters
    int quality = 90;
    bool progressive = false;
    bool optimize = true;

    // Set up ImageMagick settings and convert image
    MagickWand *source, *destination;
    ExceptionInfo *exception;
    PixelWand *pixel_wand;
    Image* source_image;
    Image* destination_image;

    exception = AcquireExceptionInfo();
    source = NewMagickWandFromImageFile(input_path, exception);
    if (source == NULL) {
        printf("Error: Failed to read image file.\n");
        return 1;
    }

    // Determine destination format and set up conversion parameters
    switch (dst) {
        case JPEG:
            quality = MIN(quality, MAX_COMPRESSION_RATIO * 100);
            progressive = true;
            optimize = false;
            break;
        case PNG:
            quality = MIN(quality, MAX_COMPRESSION_RATIO * 100);
            progressive = false;
            optimize = true;
            break;
        case GIF:
            quality = MIN(quality, MAX_COMPRESSION_RATIO * 100);
            progressive = false;
            optimize = false;
            break;
        default:
            printf("Error: Unsupported destination format.\n");
            return 2;
    }

    // Set up image properties for conversion and convert image
    destination_image = CloneImage(source_image, 0, 0, exception);
    destination_image->quality = quality;
    destination_image->progressive = progressive;
    destination_image->optimize = optimize;

    // Write converted image to file and clean up resources
    status = MagickWriteImages(destination, output_path, exception);
    if (status == MagickFalse) {
        printf("Error: Failed to write converted image.\n");
        return 3;
    }

    // Clean up resources and return success
    DestroyMagickWand(source);
    DestroyMagickWand(destination);
    DestroyExceptionInfo(exception);

    return 0;
}

// Function to extract metadata from a PDF file
Metadata extract_metadata(const char* input_path) {
    // Initialize variables for metadata extraction
    Metadata meta = {NULL, NULL, NULL};

    // Set up PDF properties and extract metadata
    PdfDocument* document;
    PdfPage* page;
    const PdfRectangle* box;
    const char* color_profile;
    unsigned int dimensions[2];
    float compression_ratio;

    // Open PDF file for reading
    if (PdfOpenFile(input_path, "rb") == NULL) {
        printf("Error: Failed to open PDF file.\n");
        return meta;
    }

    // Initialize PDF document and get number of pages
    document = PdfCreateDocument();
    int num_pages = PdfGetPageCount(document);

    // Extract metadata from each page
    for (int i = 0; i < num_pages; i++) {
        page = PdfGetPage(document, i);
        box = PdfGetArtBox(page);
        dimensions[0] = box->x1 - box->x0;
        dimensions[1] = box->y1 - box->y0;
        compression_ratio = (float)PdfGetImageXObject(page)->compression / 100.0f;

        // Extract color profile and update metadata if available
        color_profile = PdfGetPageColorProfile(page);
        if (color_profile != NULL) {
            memcpy(meta.color_profile, color_profile, strlen(color_profile));
        }
    }

    // Clean up resources and return metadata
    PdfCloseDocument(document);
    return meta;
}

// Function to convert an image file into a standardized PDF format
int pdfize_image(const char* input_path, const char* output_path) {
    // Initialize variables for conversion parameters
    int quality = 90;
    bool progressive = false;
    bool optimize = true;

    // Set up ImageMagick settings and convert image
    MagickWand *source, *destination;
    ExceptionInfo *exception;
    PixelWand *pixel_wand;
    Image* source_image;
    Image* destination_image;

    exception = AcquireExceptionInfo();
    source = NewMagickWandFromImageFile(input_path, exception);
    if (source == NULL) {
        printf("Error: Failed to read image file.\n");
        return 1;
    }

    // Determine destination format and set up conversion parameters
    ImageFormat dst = JPEG;
    switch (dst) {
        case JPEG:
            quality = MIN(quality, MAX_COMPRESSION_RATIO * 100);
            progressive = true;
            optimize = false;
            break;
        case PNG:
            quality = MIN(quality, MAX_COMPRESSION_RATIO * 100);
            progressive = false;
            optimize = true;
            break;
        case GIF:
            quality = MIN(quality, MAX_COMPRESSION_RATIO * 100);
            progressive = false;
            optimize = false;
            break;
        default:
            printf("Error: Unsupported destination format.\n");
            return 2;
    }

    // Set up image properties for conversion and convert image
    destination_image = CloneImage(source_image, 0, 0, exception);
    destination_image->quality = quality;
    destination_image->progressive = progressive;
    destination_image->optimize = optimize;

    // Write converted image to file and clean up resources
    status = MagickWriteImages(destination, output_path, exception);
    if (status == MagickFalse) {
        printf("Error: Failed to write converted image.\n");
        return 3;
    }

    // Clean up resources and return success
    DestroyMagickWand(source);
    DestroyMagickWand(destination);
    DestroyExceptionInfo(exception);

    return 0;
}
