import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.io.FileUtils;
import org.openidex.crypto.EVP_CIPHER;
import org.openidex.crypto.OpenSSL;

public class FileEncryption {
    private static final Map<String, EVP_CIPHER> CIPHERS = new HashMap<>();

    public static void main(String[] args) throws Exception {
        // Read file path from command line arguments or environment variables
        String filePath = "path/to/file.txt";

        // Initialize OpenSSL library and create a cipher context for the given cipher
        OpenSSL openSsl = new OpenSSL();
        EVP_CIPHER cipher = getCipher(openSsl, args);

        // Generate initialization vector (IV) if not provided
        IvParameterSpec iv;
        if (args.length > 2 && args[2] != null) {
            iv = new IvParameterSpec(args[2].getBytes());
        } else {
            iv = generateIv();
        }

        // Compute MD5 hash of file contents
        byte[] md5Hash = computeMd5Hash(filePath);

        // Encrypt file content using selected cipher and IV
        byte[] encryptedContent = encryptFile(filePath, cipher, iv, md5Hash);

        // Print encryption results
        System.out.println("Encryption Results:");
        System.out.printf("  Cipher: %s%n", cipher.getCipherName());
        System.out.printf("  Key Length: %d bits%n", cipher.getKeyLength() * 8);
        System.out.printf("  IV Length: %d bytes%n", iv.getIV().length);
        System.out.println("  Encrypted File Contents:");
        System.out.println(encryptedContent);
    }

    private static EVP_CIPHER getCipher(OpenSSL openSsl, String[] args) throws Exception {
        // Get cipher name from command line arguments or environment variables
        String cipherName = "AES";
        if (args.length > 0 && args[0] != null) {
            cipherName = args[0];
        } else if (System.getenv("CIPHER") != null) {
            cipherName = System.getenv("CIPHER");
        }

        // Get key length from command line arguments or environment variables
        int keyLength = 128;
        if (args.length > 1 && args[1] != null) {
            try {
                keyLength = Integer.parseInt(args[1]);
            } catch (NumberFormatException e) {
                System.err.printf("Invalid key length: %s%n", args[1]);
                return null;
            }
        } else if (System.getenv("KEY_LENGTH") != null) {
            try {
                keyLength = Integer.parseInt(System.getenv("KEY_LENGTH"));
            } catch (NumberFormatException e) {
                System.err.printf("Invalid key length: %s%n", System.getenv("KEY_LENGTH"));
                return null;
            }
        }

        // Check if cipher and key length are valid
        if (!openSsl.isCipherAvailable(cipherName)) {
            System.err.printf("Unsupported cipher: %s%n", cipherName);
            return null;
        } else if (keyLength != 64 && keyLength != 128) {
            System.err.println("Invalid key length, must be 64 or 128 bits");
            return null;
        }

        // Initialize cipher context and return EVP_CIPHER object
        Cipher cipher = openSsl.getCipherInstance(cipherName);
        SecretKeySpec key = new SecretKeySpec(generateKey(keyLength), "AES");
        cipher.init(Cipher.ENCRYPT_MODE, key);
        return EVP_CIPHER.getInstance(cipherName, keyLength);
    }

    private static byte[] generateKey(int keyLength) {
        // Generate random key of specified length using SecureRandom
        SecureRandom random = new SecureRandom();
        byte[] key = new byte[keyLength / 8];
        random.nextBytes(key);
        return key;
    }

    private static IvParameterSpec generateIv() {
        // Generate random initialization vector of length 16 bytes using SecureRandom
        SecureRandom random = new SecureRandom();
        byte[] iv = new byte[16];
        random.nextBytes(iv);
        return new IvParameterSpec(iv);
    }

    private static byte[] computeMd5Hash(String filePath) throws Exception {
        // Compute MD5 hash of file contents using Apache Commons IO library
        File file = new File(filePath);
        if (!file.exists() || !file.canRead()) {
            throw new IOException("File does not exist or is unreadable: " + filePath);
        }
        byte[] fileContent = Files.readAllBytes(Paths.get(filePath));
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        return md5.digest(fileContent);
    }

    private static byte[] encryptFile(String filePath, EVP_CIPHER cipher, IvParameterSpec iv, byte[] md5Hash) throws Exception {
        // Encrypt file content using selected cipher and IV
        FileInputStream inputStream = null;
        CipherOutputStream outputStream = null;
        try {
            File file = new File(filePath);
            inputStream = new FileInputStream(file);
            outputStream = new CipherOutputStream(outputStream, cipher.getCipherInstance());
            byte[] encryptedContent = openSsl.encrypt(inputStream, outputStream, iv);
            return encryptedContent;
        } finally {
            if (inputStream != null) inputStream.close();
            if (outputStream != null) outputStream.close();
        }
    }
}
```
