use std::sync::Mutex;
use std::time::Duration;

struct Clinic {
    id: i32,
    status: String,
    last_modified_ip: String,
    last_modified_date: chrono::DateTime<chrono::Utc>,
}

impl Clinic {
    fn new(id: i32) -> Self {
        Self {
            id,
            status: "".to_string(),
            last_modified_ip: "".to_string(),
            last_modified_date: chrono::Utc::now(),
        }
    }
}

struct ClinicDatabase {
    clinics: Mutex<HashMap<i32, Clinic>>,
}

impl ClinicDatabase {
    fn new() -> Self {
        let mut clinics = HashMap::new();
        clinics.insert(1, Clinic::new(1));
        clinics.insert(2, Clinic::new(2));
        clinics.insert(3, Clinic::new(3));
        Self { clinics }
    }

    fn update_status(&self, id: i32, status: &str) -> Result<(), Error> {
        let mut clinics = self.clinics.lock().unwrap();
        if !clinics.contains_key(&id) {
            return Err(Error::InvalidId);
        }
        let clinic = clinics.get_mut(&id).unwrap();
        clinic.status = status.to_string();
        clinic.last_modified_ip = reqwest::get("http://127.0.0.1").unwrap().remote_addr().map(|x| x.ip()).unwrap();
        clinic.last_modified_date = chrono::Utc::now();
        Ok(())
    }
}

struct Error {
    reason: String,
}

impl Error {
    fn new(reason: &str) -> Self {
        Self {
            reason: reason.to_string(),
        }
    }
}

fn main() {
    let database = ClinicDatabase::new();
    let id = 1;
    let status = "New Status";
    match database.update_status(id, status) {
        Ok(_) => println!("Update successful"),
        Err(error) => println!("Error: {}", error),
    }
}
```
