import json
import os
import re
from typing import Dict, List

class JSONLogParser:
    def __init__(self):
        self.logs = []
        self.metrics = {}
        self.service_names = set()
        self.metric_names = set()

    def parse(self, log_dir: str) -> None:
        """Parses the JSON logs in the given directory and aggregates metrics."""
        for filename in os.listdir(log_dir):
            with open(os.path.join(log_dir, filename)) as f:
                try:
                    log = json.load(f)
                    self._validate_log(log)
                    self._aggregate_metrics(log)
                except json.JSONDecodeError as e:
                    print(f"Invalid JSON log: {filename}")
                    continue

    def _validate_log(self, log: Dict[str, str]) -> None:
        """Validates the schema and integrity of a single JSON log."""
        if "service" not in log or "metrics" not in log:
            raise ValueError("Log does not contain required fields.")
        for metric in log["metrics"]:
            if "name" not in metric or "value" not in metric:
                raise ValueError(f"Metric {metric} does not contain required fields.")

    def _aggregate_metrics(self, log: Dict[str, str]) -> None:
        """Aggregates the metrics from a single JSON log."""
        for service in log["services"]:
            self.service_names.add(service)
            for metric in service["metrics"]:
                name = metric["name"]
                value = metric["value"]
                if name not in self.metric_names:
                    self.metric_names.add(name)
                self.metrics[name] = self.metrics.get(name, 0) + value

    def generate_summary_report(self) -> Dict[str, str]:
        """Generates a summary report of the aggregated metrics."""
        return {
            "services": list(self.service_names),
            "metrics": list(self.metric_names),
            "data": self.metrics
        }

    def write_summary_report(self, filename: str) -> None:
        """Writes the summary report to a file."""
        with open(filename, "w") as f:
            json.dump(self.generate_summary_report(), f, indent=4)

if __name__ == "__main__":
    parser = JSONLogParser()
    parser.parse("logs/")
    report = parser.generate_summary_report()
    print(json.dumps(report, indent=4))
```

