```cpp
#include <iostream>
#include <string>
#include <vector>

std::vector<std::string> &insertAfter(std::vector<std::string> &str_list, const std::string &target, const std::string &new_str) {
    // Find the first occurrence of the target string in the list
    auto it = std::find(str_list.begin(), str_list.end(), target);

    // If the target string is not found, append the new string to the end of the list
    if (it == str_list.end()) {
        str_list.push_back(new_str);
    } else {
        // Insert the new string after the first occurrence of the target string
        it = str_list.insert(it + 1, new_str);
    }

    return str_list;
}
