TEST(InsertAfterTest, AppendNewStringToEndIfNotFound) {
    // Define the forward list of strings and target string to insert after
    std::vector<std::string> str_list = {"hello", "world"};
    const std::string target = "goodbye";
    const std::string new_str = "there";

    // Insert the new string after the first occurrence of the target string
    insertAfter(str_list, target, new_str);

    // Assert that the new string is appended to the end of the list if the target string is not found
    EXPECT_EQ("hello", str_list[0]);
    EXPECT_EQ("world", str_list[1]);
    EXPECT_EQ("there", str_list[2]);
}
