<?php

namespace ExecutionUtility;

class CommandExecutor
{
    private $processes = array();
    private $runningProcessCount = 0;
    private $signalHandlers = array();
    private $timeouts = array();
    private $logFilePath = null;
    private $logger = null;

    public function __construct(string $logFilePath, LoggerInterface $logger)
    {
        $this->logFilePath = $logFilePath;
        $this->logger = $logger;
    }

    /**
     * Execute a command in the background and return its process ID.
     *
     * @param string $command The command to execute, including any arguments or flags.
     * @param array $environmentVariables An optional array of environment variables to set before executing the command.
     * @param array $stdoutFilePath An optional path to a file where the command's standard output should be redirected.
     * @param array $stderrFilePath An optional path to a file where the command's error output should be redirected.
     * @return int The process ID of the executed command, or -1 if an error occurred.
     */
    public function execute(string $command, array $environmentVariables = [], string $stdoutFilePath = null, string $stderrFilePath = null)
    {
        // Validate the input parameters
        if (!$this->validateCommand($command)) {
            return -1;
        }

        // Set up the signal handling mechanism
        pcntl_signal(SIGCHLD, function ($signo) {
            $this->handleChildSignal($signo);
        });

        // Fork and execute the command
        $pid = pcntl_fork();
        if ($pid === -1) {
            $this->logger->error("Failed to fork a new process. Error: " . posix_strerror(posix_get_last_error()));
            return -1;
        } elseif ($pid === 0) {
            // In the child process, execute the command
            exec($command, $stdout, $stderr);

            if (!empty($stdoutFilePath)) {
                file_put_contents($stdoutFilePath, implode("\n", $stdout));
            }
            if (!empty($stderrFilePath)) {
                file_put_contents($stderrFilePath, implode("\n", $stderr));
            }
        } else {
            // In the parent process, store the process ID and its timeout
            $this->processes[$pid] = array(
                'timeout' => 0,
                'environmentVariables' => $environmentVariables,
            );
        }

        return $pid;
    }

    /**
     * Set the timeout for a specific process.
     *
     * @param int $processId The ID of the process to set the timeout for.
     * @param int $timeout The timeout value in seconds.
     */
    public function setTimeout(int $processId, int $timeout)
    {
        if (!isset($this->processes[$processId])) {
            return;
        }

        // Update the process's timeout value
        $this->processes[$processId]['timeout'] = $timeout;
    }

    /**
     * Handle a child signal.
     *
     * @param int $signo The signal number.
     */
    public function handleChildSignal(int $signo)
    {
        // Check if the signal is for a process that we're waiting on
        foreach ($this->processes as $pid => $process) {
            if (pcntl_wait($status, WNOHANG | WUNTRACED, $pid)) {
                // Process has terminated, remove it from the list of running processes
                unset($this->processes[$pid]);
                break;
            }
        }
    }

    /**
     * Validate a command string.
     *
     * @param string $command The command to validate.
     * @return bool True if the command is valid, false otherwise.
     */
    private function validateCommand(string $command): bool
    {
        // Check for shell metacharacters in the command
        if (preg_match('/[`$&*(){}<>|]/', $command)) {
            return false;
        }

        // Check for a valid executable path
        $executable = strtok($command, ' ');
        if (!file_exists($executable) || !is_executable($executable)) {
            return false;
        }

        return true;
    }
}
