        public static void RegisterAndStartSite(string directoryPath, string siteName)
        {
            // Validate input parameters
            if (string.IsNullOrEmpty(directoryPath))
                throw new ArgumentException("Invalid directory path", nameof(directoryPath));
            if (string.IsNullOrEmpty(siteName))
                throw new ArgumentException("Invalid site name", nameof(siteName));

            // Ensure the web.config file exists and is valid
            var configFile = Path.Combine(directoryPath, WebConfigFileName);
            if (!File.Exists(configFile))
            {
                EventLog.WriteEntry("SiteRegistrar", $"Missing web.config file at {configFile}.");
                return;
            }

            // Load the site's configuration from the web.config file
            var config = new Configuration();
            config.Load(configFile);

            // Validate the site's configuration and log any errors or warnings
            if (ValidateSiteConfiguration(config, siteName))
            {
                EventLog.WriteEntry("SiteRegistrar", $"Invalid site configuration for {siteName}.");
                return;
            }

            // Register the site with IIS
            var manager = new ServerManager();
            var site = manager.Sites[siteName];
            if (site == null)
            {
                EventLog.WriteEntry("SiteRegistrar", $"Failed to register {siteName}.");
                return;
            }

            // Start the site
            try
            {
                site.Start();
            }
            catch (Exception ex)
