package com.example.weather;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

import com.example.weather.datamodel.WeatherData;
import com.example.weather.datamodel.Pokemon;
import com.example.weather.repository.WeatherRepository;
import com.example.weather.service.WeatherService;
import com.example.weather.util.LoggingUtil;
import com.example.weather.util.RateLimiter;

public class WeatherMicroservice {
    private static final int MAX_THREADS = 10;
    private static final int QUEUE_CAPACITY = 10000;
    private static final long KEEP_ALIVE_TIME = 60L;
    private static final String WEATHER_REPO_URL = "http://weather-api.com/data";
    private static final String POKEMON_API_URL = "https://pokeapi.co/api/v2/pokemon/";

    private ExecutorService executor;
    private WeatherRepository weatherRepo;
    private WeatherService weatherService;
    private RateLimiter rateLimiter;

    public static void main(String[] args) {
        new WeatherMicroservice().start();
    }

    public void start() {
        executor = new ThreadPoolExecutor(MAX_THREADS, MAX_THREADS, KEEP_ALIVE_TIME, TimeUnit.SECONDS, new LinkedBlockingQueue<>(QUEUE_CAPACITY));
        weatherRepo = new WeatherRepository();
        weatherService = new WeatherService();
        rateLimiter = new RateLimiter(MAX_THREADS);

        LoggingUtil.initLogging("weather-microservice");

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            weatherRepo.close();
            executor.shutdownNow();
        }));
    }

    public void processMessage(byte[] message) {
        try {
            String json = new String(message, "UTF-8");
            WeatherData data = weatherService.parseJson(json);
            if (data == null) {
                return;
            }

            executor.execute(() -> {
                try {
                    // handle the data
                    processWeatherData(data);
                } catch (Exception e) {
                    LoggingUtil.logError("Failed to process weather data", e);
                }
            });
        } catch (Exception e) {
            LoggingUtil.logError("Failed to parse message", e);
        }
    }

    public void processWeatherData(WeatherData data) {
        if (data == null) {
            return;
        }

        try {
            // handle the data
            String weatherString = data.getWeather();
            String pokemonName = data.getPokemonName();

            if (weatherString != null && !weatherString.isEmpty()) {
                handleWeatherData(weatherString);
            } else if (pokemonName != null && !pokemonName.isEmpty()) {
                handlePokemonData(pokemonName);
            }
        } catch (Exception e) {
            LoggingUtil.logError("Failed to process weather data", e);
        }
    }

    public void handleWeatherData(String weatherString) throws Exception {
        // store the weather data in the local database
        weatherRepo.saveWeatherData(weatherString);

        // retrieve the current weather conditions from the external API
        String currentWeather = weatherService.getCurrentWeather(weatherString);

        // handle the current weather conditions
        if (currentWeather != null && !currentWeather.isEmpty()) {
            handleCurrentWeather(currentWeather);
        }
    }

    public void handlePokemonData(String pokemonName) throws Exception {
        // retrieve the Pokemon data from the external API
        String pokemonJson = weatherService.getPokemonData(pokemonName);

        if (pokemonJson != null && !pokemonJson.isEmpty()) {
            // handle the Pokemon data
            Pokemon pokemon = weatherService.parsePokemonJson(pokemonJson);
            if (pokemon != null) {
                handlePokemon(pokemon);
            }
        }
    }

    public void handleCurrentWeather(String currentWeather) throws Exception {
        // handle the current weather conditions
    }

    public void handlePokemon(Pokemon pokemon) throws Exception {
        // handle the Pokemon data
    }
}
