public class PokemonWeaknesses {
    private static final Map<String, List<String>> weaknessCache = new HashMap<>();

    public static String getWeaknesses(byte[] pokemonBytes) {
        if (pokemonBytes == null || pokemonBytes.length == 0) {
            throw new RuntimeException("Invalid Pokemon bytes");
        }

        // Validate byte array format before deserialization
        validateByteArrayFormat(pokemonBytes);

        String type = getPokemonType(pokemonBytes);
        if (type == null) {
            throw new RuntimeException("Invalid Pokemon type");
        }

        // Check cache for previously deserialized Pokemon objects
        List<String> weaknesses = weaknessCache.get(type);
        if (weaknesses != null) {
            return weaknesses;
        }

        // Deserialize Pokemon object from byte array
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(pokemonBytes));
        try {
            Pokemon pokemon = (Pokemon) ois.readObject();
            weaknesses = getWeaknessesFromType(type);
            if (weaknesses == null || weaknesses.isEmpty()) {
                // Integrate with external database to retrieve additional weakness information
                weaknesses = getExternalWeaknesses(pokemon);
            }
        } catch (ClassNotFoundException | IOException e) {
            throw new RuntimeException("Failed to deserialize Pokemon object", e);
        } finally {
            try {
                ois.close();
            } catch (IOException ignored) {}
        }

        // Serialize Pokemon object back to byte array
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(bos);
        try {
            oos.writeObject(pokemon);
        } catch (IOException e) {
            throw new RuntimeException("Failed to serialize Pokemon object", e);
        } finally {
            try {
                oos.close();
            } catch (IOException ignored) {}
        }
        byte[] serializedPokemon = bos.toByteArray();

        // Cache deserialized Pokemon objects for future use
        weaknessCache.put(type, weaknesses);

        return weaknesses;
    }

    private static String getPokemonType(byte[] pokemonBytes) {
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(pokemonBytes));
        try {
            Pokemon pokemon = (Pokemon) ois.readObject();
            return pokemon.getType().toString();
        } catch (ClassNotFoundException | IOException e) {
            throw new RuntimeException("Failed to deserialize Pokemon object", e);
        } finally {
            try {
