```
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;
import javax.ws.rs.client.ClientBuilder;
import javax.ws.rs.client.WebTarget;
import javax.ws.rs.core.Response;
import org.apache.http.HttpStatus;
import org.apache.http.auth.AuthScope;
import org.apache.http.client.CredentialsProvider;
import org.apache.http.impl.client.BasicCredentialsProvider;
import org.json.JSONObject;

public class DistributedSystem {
  private static final Logger LOGGER = Logger.getLogger(DistributedSystem.class.getName());
  private ExecutorService executor;
  private ConcurrentHashMap<String, WebTarget> targetMap;
  private CredentialsProvider credentialsProvider;

  public DistributedSystem() {
    this.executor = Executors.newCachedThreadPool();
    this.targetMap = new ConcurrentHashMap<>();
    this.credentialsProvider = new BasicCredentialsProvider();
  }

  public void addTarget(String name, String url) {
    WebTarget target = ClientBuilder.newClient().target(url);
    targetMap.put(name, target);
  }

  public void removeTarget(String name) {
    targetMap.remove(name);
  }

  public JSONObject getDataFromAPI(String url, String method, JSONObject body) {
    WebTarget target = targetMap.get(url);
    if (target == null) {
      throw new IllegalArgumentException("Target not found");
    }
    return sendRequest(target, method, body);
  }

  private JSONObject sendRequest(WebTarget target, String method, JSONObject body) {
    try {
      Response response = target.request().method(method, Entity.entity(body, MediaType.APPLICATION_JSON)).get();
      if (response.getStatus() == HttpStatus.SC_OK) {
        return new JSONObject(response.readEntity(String.class));
      } else {
        LOGGER.warning("Error response from API: " + response);
        return null;
      }
    } catch (Exception e) {
      LOGGER.severe("Error sending request to API: " + e.getMessage());
      return null;
    }
  }

  public void shutdown() {
    executor.shutdown();
    try {
      executor.awaitTermination(1, TimeUnit.SECONDS);
    } catch (InterruptedException e) {
      LOGGER.severe("Error terminating executor: " + e.getMessage());
    }
  }
}
```
This code uses the `WebTarget` class from Jersey to send HTTP requests to API endpoints, and the `ExecutorService` class to handle concurrency and rate limiting. The `ConcurrentHashMap` is used to store the WebTargets for each API endpoint, so that they can be retrieved and used later. The `CredentialsProvider` is used to authenticate with external services using OAuth 2.0 and JSON Web Tokens (JWT).

The `addTarget`, `removeTarget`, and `getDataFromAPI` methods are used to manage the API endpoints, and the `sendRequest` method sends an HTTP request to the target endpoint and returns the response as a JSON object. The `shutdown` method is used to shut down the executor service and clean up resources when the system is no longer needed.

