package secure_encryption_service;

import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.NoSuchPaddingException;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.codec.digest.DigestUtils;
import org.apache.commons.codec.digest.MessageDigestAlgorithm;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class SecureEncryptionService {
    private static final Logger logger = LogManager.getLogger(SecureEncryptionService.class);

    // KDF configuration
    private static final String KDF_ALGORITHM = "bcrypt";
    private static final int SALT_BYTE_SIZE = 16;
    private static final int HASH_ITERATIONS = 12;
    private static final int KEY_BYTE_SIZE = 32;
    private static final String CIPHER_ALGORITHM = "AES/GCM/NoPadding";

    // IV generation configuration
    private static final SecureRandom secureRandom = new SecureRandom();
    private static final int IV_BYTE_SIZE = 12;

    // Key management system configuration
    private static final String KMS_ALGORITHM = "AES/GCM/NoPadding";

    // Rate limiting configuration
    private static final long MAX_ENCRYPTION_REQUESTS_PER_SECOND = 50;
    private static final int RATE_LIMIT_INTERVAL_MS = 1000;

    // Memory management configuration
    private static final int MEMORY_ALLOCATION_SIZE = 16 * 1024 * 1024;

    public SecureEncryptionService() {}

    /**
     * Encrypts the given plaintext using AES-256-GCM and the specified password.
     * @param plaintext The plaintext to encrypt.
     * @param password The password used for key derivation.
     * @return The encrypted ciphertext.
     */
    public String encrypt(String plaintext, String password) throws NoSuchAlgorithmException, NoSuchPaddingException {
        // Validate input parameters
        if (plaintext == null || plaintext.isEmpty()) {
            throw new IllegalArgumentException("Plaintext cannot be empty");
        }
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be empty");
        }

        // Derive key and salt from password using KDF
        byte[] salt = new byte[SALT_BYTE_SIZE];
        secureRandom.nextBytes(salt);
        byte[] derivedKey = deriveKey(password, salt, KEY_BYTE_SIZE);

        // Generate a new random IV for each encryption operation
        byte[] iv = new byte[IV_BYTE_SIZE];
        secureRandom.nextBytes(iv);

        // Create AES-256-GCM cipher and encrypt the plaintext using the derived key and IV
        Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
        GCMParameterSpec gcmParams = new GCMParameterSpec(128, iv);
        SecretKeySpec secretKey = new SecretKeySpec(derivedKey, "AES");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, gcmParams);
        byte[] encryptedTextBytes = cipher.doFinal(plaintext.getBytes());

        // Base64 encode the encrypted text and salt for storage
        String encryptedTextBase64 = Base64.getEncoder().encodeToString(encryptedTextBytes);
        String saltBase64 = Base64.getEncoder().encodeToString(salt);

        // Record key derivation operation in log
        logger.info("Key derivation: {} iterations, {} bytes", HASH_ITERATIONS, KEY_BYTE_SIZE);
        logger.info("IV generation: {} bytes", IV_BYTE_SIZE);

        return encryptedTextBase64 + "::" + saltBase64;
    }

    /**
     * Decrypts the given ciphertext using AES-256-GCM and the specified password.
     * @param ciphertext The ciphertext to decrypt.
     * @param password The password used for key derivation.
     * @return The original plaintext.
     */
    public String decrypt(String ciphertext, String password) throws NoSuchAlgorithmException, NoSuchPaddingException {
        // Validate input parameters
        if (ciphertext == null || ciphertext.isEmpty()) {
            throw new IllegalArgumentException("Ciphertext cannot be empty");
        }
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be empty");
        }

        // Split the ciphertext into encrypted text and salt
        String[] parts = ciphertext.split("::");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Invalid ciphertext format");
        }
        String encryptedTextBase64 = parts[0];
        String saltBase64 = parts[1];

        // Derive key and salt from password using KDF
        byte[] salt = Base64.getDecoder().decode(saltBase64);
        byte[] derivedKey = deriveKey(password, salt, KEY_BYTE_SIZE);

        // Create AES-256-GCM cipher and decrypt the encrypted text using the derived key and IV
        Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
        GCMParameterSpec gcmParams = new GCMParameterSpec(128, iv);
        SecretKeySpec secretKey = new SecretKeySpec(derivedKey, "AES");
        cipher.init(Cipher.DECRYPT_MODE, secretKey, gcmParams);
        byte[] encryptedTextBytes = Base64.getDecoder().decode(encryptedTextBase64);
        byte[] plaintextBytes = cipher.doFinal(encryptedTextBytes);

        // Return the original plaintext
        return new String(plaintextBytes);
    }

    /**
     * Derives a key from the given password and salt using the specified KDF algorithm.
     * @param password The password to derive the key from.
     * @param salt The salt used for the KDF.
     * @param bytes The number of bytes to generate for the derived key.
     * @return The derived key.
     */
    public static byte[] deriveKey(String password, byte[] salt, int bytes) {
        // Validate input parameters
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be empty");
        }
        if (salt == null || salt.length != SALT_BYTE_SIZE) {
            throw new IllegalArgumentException("Salt must be " + SALT_BYTE_SIZE + " bytes");
        }

        // Derive the key using PBKDF2 with the specified number of iterations
        byte[] derivedKey = new byte[bytes];
        int offset = 0;
        while (offset < bytes) {
            byte[] subkey = pbkdf2(password, salt, offset + 1);
            System.arraycopy(subkey, 0, derivedKey, offset, Math.min(subkey.length, bytes - offset));
            offset += subkey.length;
        }

        // Return the derived key
        return derivedKey;
    }

    /**
     * Performs PBKDF2 with the specified number of iterations on the given password and salt.
     * @param password The password to use for PBKDF2.
     * @param salt The salt to use for PBKDF2.
     * @param iterations The number of iterations to perform for PBKDF2.
     * @return The derived key.
     */
    public static byte[] pbkdf2(String password, byte[] salt, int iterations) {
        // Validate input parameters
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be empty");
        }
        if (salt == null || salt.length != SALT_BYTE_SIZE) {
            throw new IllegalArgumentException("Salt must be " + SALT_BYTE_SIZE + " bytes");
        }

        // Perform PBKDF2 on the password and salt using the specified number of iterations
        byte[] derivedKey = new byte[16];
        int offset = 0;
        while (offset < derivedKey.length) {
            byte[] subkey = pbkdf2(password, salt, iterations);
            System.arraycopy(subkey, 0, derivedKey, offset, Math.min(subkey.length, derivedKey.length - offset));
            offset += subkey.length;
        }

        // Return the derived key
        return derivedKey;
    }
}
```

#### 4.2 AES-GCM Encryption/Decryption with Random IV and Authentication Tag

The following code snippets demonstrate how to use the `AES` class in Java to perform symmetric encryption using AES-GCM mode of operation with random initialization vector (IV) and authentication tag generation.

**Java Example:**
```java
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;

public class AESGCMExample {
    public static void main(String[] args) throws Exception {
        String key = "YELLOW SUBMARINE"; // Use a key of at least 16 bytes for AES-GCM
        byte[] iv = new byte[12];      // Create a random IV for each encryption operation (recommended)
        secureRandom.nextBytes(iv);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes(), "AES");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivSpec);

        byte[] plaintext = "Hello World!".getBytes();
        byte[] ciphertext = cipher.doFinal(plaintext);

        // Output the ciphertext and its authentication tag
        System.out.println("Ciphertext: " + new String(ciphertext));
        System.out.println("Authentication Tag: " + cipher.getTag());
    }
}
```

