from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

# Define the key and IV as hexadecimal strings for convenience
key = "000102030405060708090a0b0c0d0e0f"
iv = "1011121314151617"

# Define the data to be encrypted as a hexadecimal string
