ciphertext = encryptor.update(bytes.fromhex(data)) + encryptor.finalize()
tag = encryptor.tag

# Print the results
print("Ciphertext: " + base64.b64encode(ciphertext).decode())
print("Authentication Tag: " + tag.hex())
```

