    }

    // Process the bundles using the chosen cipher and encryption mode
    for (size_t i = 0; i < numBundles; i++) {
        bundleUrl = bundleUrls[i];
        if (!processBundle(bundleUrl, cipher, keyLength, ivLength)) {
            printf("Failed to process bundle: %s\n", bundleUrl);
            return NULL;
        }
    }

    // Return the EVP_CIPHER structure representing the chosen cipher
    return cipher;
