import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.stream.Collectors;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.stereotype.Component;
import org.springframework.web.bind.annotation.*;

@RestController
public class PokemonService {
    private static final Logger logger = Logger.getLogger(PokemonService.class.getName());

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private PokemonRepository pokemonRepository;

    @Autowired
    private ExternalApiClient externalApiClient;

    @Bean
    public ExecutorService executor() {
        return Executors.newFixedThreadPool(5);
    }

    @GetMapping("/pokemons")
    public List<Pokemon> getAllPokemons() {
        return pokemonRepository.findAll();
    }

    @PostMapping("/pokemons")
    public void createPokemon(@RequestBody Pokemon pokemon) {
        pokemonRepository.save(pokemon);
    }

    @GetMapping("/pokemons/{id}")
    public Pokemon getPokemonById(@PathVariable Long id) {
        return pokemonRepository.findById(id).orElseThrow(() -> new ResourceNotFoundException("Pokemon not found"));
    }

    @DeleteMapping("/pokemons/{id}")
    public void deletePokemon(@PathVariable Long id) {
        Pokemon pokemon = pokemonRepository.findById(id).orElseThrow(() -> new ResourceNotFoundException("Pokemon not found"));
        pokemonRepository.delete(pokemon);
    }

    @PutMapping("/pokemons/{id}")
    public void updatePokemon(@PathVariable Long id, @RequestBody Pokemon updatedPokemon) {
        Pokemon pokemon = pokemonRepository.findById(id).orElseThrow(() -> new ResourceNotFoundException("Pokemon not found"));
        pokemon.setName(updatedPokemon.getName());
        pokemon.setType(updatedPokemon.getType());
        pokemon.setWeaknesses(updatedPokemon.getWeaknesses());
        pokemonRepository.save(pokemon);
    }

    @GetMapping("/pokemons/weaknesses")
    public List<String> getAllWeaknesses() {
        return pokemonRepository.findAll().stream()
                .map(Pokemon::getWeaknesses)
                .flatMap(List::stream)
                .collect(Collectors.toList());
    }

    @GetMapping("/pokemons/types")
    public List<String> getAllTypes() {
        return pokemonRepository.findAll().stream()
                .map(Pokemon::getType)
                .distinct()
                .collect(Collectors.toList());
    }

    @GetMapping("/pokemons/rares")
    public List<String> getRareTypes() {
        return pokemonRepository.findAll().stream()
                .filter(p -> p.getType().contains("rare"))
                .map(Pokemon::getType)
                .distinct()
                .collect(Collectors.toList());
    }

    @GetMapping("/pokemons/weaknesses/{type}")
    public List<String> getWeaknessesByType(@PathVariable String type) {
        return pokemonRepository.findAll().stream()
                .filter(p -> p.getType().equalsIgnoreCase(type))
                .map(Pokemon::getWeaknesses)
                .flatMap(List::stream)
                .collect(Collectors.toList());
    }

    @GetMapping("/pokemons/rares/{type}")
    public List<String> getRareTypesByType(@PathVariable String type) {
        return pokemonRepository.findAll().stream()
                .filter(p -> p.getType().equalsIgnoreCase(type))
                .filter(p -> p.getType().contains("rare"))
                .map(Pokemon::getType)
                .distinct()
                .collect(Collectors.toList());
    }

    @PostMapping("/pokemons/weaknesses")
    public void updateWeaknesses(@RequestBody List<String> weaknesses) {
        pokemonRepository.findAll().forEach(p -> p.setWeaknesses(weaknesses));
    }

    @PostMapping("/pokemons/types")
    public void updateTypes(@RequestBody List<String> types) {
        pokemonRepository.findAll().forEach(p -> p.setType(types));
    }

    @PostMapping("/pokemons/rares")
    public void updateRareTypes(@RequestBody List<String> rareTypes) {
        pokemonRepository.findAll().stream()
                .filter(p -> p.getType().contains("rare"))
                .forEach(p -> p.setType(rareTypes));
    }

    @GetMapping("/pokemons/analytics")
    public PokemonAnalytics getPokemonAnalytics() {
        return new PokemonAnalytics();
    }

    @GetMapping("/pokemons/analytics/types")
    public List<String> getTypeAnalytics() {
        return pokemonRepository.findAll().stream()
                .map(Pokemon::getType)
                .collect(Collectors.toList());
    }

    @GetMapping("/pokemons/analytics/weaknesses")
    public List<String> getWeaknessAnalytics() {
        return pokemonRepository.findAll().stream()
                .map(Pokemon::getWeaknesses)
                .flatMap(List::stream)
                .collect(Collectors.toList());
    }

    @GetMapping("/pokemons/analytics/rares")
    public List<String> getRareAnalytics() {
        return pokemonRepository.findAll().stream()
                .filter(p -> p.getType().contains("rare"))
                .map(Pokemon::getType)
                .collect(Collectors.toList());
    }

    @PostMapping("/pokemons/analytics")
    public void updateAnalytics(@RequestBody PokemonAnalytics analytics) {
        pokemonRepository.findAll().forEach(p -> p.setType(analytics.getTypes()));
        pokemonRepository.findAll().forEach(p -> p.setWeaknesses(analytics.getWeaknesses()));
    }
}

