using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace DynamicConfigurableValueGenerator
{
    public class RandomNumberGenerator
    {
        private readonly object _lockObject = new object();
        private double[] _cachedValues = new double[0];
        private int _maxCacheSize = 10000;
        private int _currentCacheSize = 0;
        private readonly Random _random = new Random();

        public Task<double> GenerateRandomValueAsync(int min, int max)
        {
            return Task.FromResult(_random.NextDouble() * (max - min) + min);
        }

        public Task<double[]> GenerateRandomValuesAsync(int count, int min, int max)
        {
            double[] values = new double[count];
            for (int i = 0; i < count; i++)
            {
                values[i] = _random.NextDouble() * (max - min) + min;
            }
            return Task.FromResult(values);
        }

        public void AddCachedValue(double value)
        {
            lock (_lockObject)
            {
                if (_currentCacheSize < _maxCacheSize)
                {
                    _cachedValues = _cachedValues.Concat(new[] { value }).ToArray();
                    _currentCacheSize++;
                }
            }
        }

        public Task<double> GetCachedValueAsync()
        {
            lock (_lockObject)
            {
                if (_currentCacheSize == 0)
                {
                    return Task.FromResult(default);
                }

                double value = _cachedValues[_currentCacheSize - 1];
                _cachedValues = _cachedValues.Take(_currentCacheSize - 1).ToArray();
                _currentCacheSize--;
                return Task.FromResult(value);
            }
        }
    }
}
```
