using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class GameEventManager
{
    private readonly List<GameServer> _servers;
    private readonly List<string> _serverAddresses;
    private readonly Dictionary<string, ServerStatus> _serverStatuses;
    private readonly Dictionary<string, int> _serverLoads;
    private readonly string _encryptionKey;
    private readonly bool _usingCache;
    private readonly Cache<string, EncryptedData> _cache;

    public GameEventManager(List<GameServer> servers, string encryptionKey, bool usingCache)
    {
        _servers = servers;
        _serverAddresses = servers.Select(s => s.Address).ToList();
        _serverStatuses = new Dictionary<string, ServerStatus>();
        _serverLoads = new Dictionary<string, int>();
        _encryptionKey = encryptionKey;
        _usingCache = usingCache;
        if (_usingCache)
        {
            _cache = new Cache<string, EncryptedData>(GetEncryptedData);
        }
    }

    public async Task<T> GetRandomValueAsync<T>()
    {
        // Determine the best server to route the request to based on load and geographic proximity.
        var selectedServer = GetBestServer();
        if (selectedServer == null)
        {
            return default(T);
        }

        // Fetch the random value from the selected server.
        try
        {
            return await selectedServer.GetRandomValueAsync<T>();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to fetch random value from server {selectedServer.Address}: {ex}");
            return default(T);
        }
    }

    public async Task UpdateEncryptionKeyAsync()
    {
        if (!_usingCache)
        {
            return;
        }

        // Fetch the latest encryption key from the external game backend service.
        var newEncryptionKey = await GetLatestEncryptionKey();
        if (string.IsNullOrEmpty(newEncryptionKey))
        {
            return;
        }

        // Update the current encryption key and invalidate the cache.
        _encryptionKey = newEncryptionKey;
        _cache.Clear();
    }

    private GameServer GetBestServer()
    {
        // Determine the best server to route the request to based on load and geographic proximity.
        var selectedServer = _servers.OrderBy(s => s.Load).FirstOrDefault();
        if (selectedServer == null)
        {
            return default(GameServer);
        }

        // Update the server's load status based on its performance.
        selectedServer.UpdateStatus();
        _serverStatuses[selectedServer.Address] = selectedServer.Status;

        // Return the best server based on the current load and geographic proximity.
        return selectedServer;
    }

    private async Task<string> GetLatestEncryptionKey()
    {
        // Fetch the latest encryption key from the external game backend service.
        var response = await _backendServiceClient.GetEncryptionKeyAsync();
        if (response == null || string.IsNullOrEmpty(response.EncryptionKey))
        {
            return default;
        }

        // Return the latest encryption key from the external game backend service.
        return response.EncryptionKey;
    }

    private async Task<EncryptedData> GetEncryptedData(string dataId)
    {
        // Fetch the encrypted data from the external game backend service using the current encryption key.
        var response = await _backendServiceClient.GetEncryptedDataAsync(_encryptionKey, dataId);
        if (response == null || string.IsNullOrEmpty(response.Data))
        {
            return default;
        }

        // Decrypt the encrypted data using the current initialization vector (IV) and encryption key.
        var iv = response.InitializationVector;
        var cipherText = Convert.FromBase64String(response.Data);
        var plainText = AESCipher.Decrypt(cipherText, iv, _encryptionKey);

        // Return the decrypted data as a string.
        return Encoding.UTF8.GetString(plainText);
    }
}
