const TOKEN_LENGTH: usize = 32;
const SECRET_KEY: &str = "my-secret-key";
const CACHE_SIZE: usize = 10000;

// Token cache data structure
#[derive(Clone, Debug)]
struct TokenCache {
    tokens: HashMap<String, (i64, String)>,
}

impl TokenCache {
    fn new() -> Self {
        TokenCache {
            tokens: HashMap::new(),
        }
    }

    fn add_token(&mut self, token: &str, expiration: i64) {
        self.tokens.insert(token.to_string(), (expiration, "".to_string()));
    }

    fn get_token(&self, token: &str) -> Option<String> {
        if let Some((_, token)) = self.tokens.get(token) {
            return Some(token.clone());
        }
        None
    }
}

// SessionManager struct
#[derive(Clone, Debug)]
pub struct SessionManager {
    cache: Arc<Mutex<TokenCache>>,
    secret_key: String,
}

impl SessionManager {
    pub fn new(secret_key: &str) -> Self {
        SessionManager {
            cache: Arc::new(Mutex::new(TokenCache::new())),
            secret_key: secret_key.to_string(),
        }
    }

    // Generate a secure and efficient token for user sessions
    pub fn generate_secure_token(&self, username: &str) -> String {
        let mut hasher = SipHasher::new();
        hasher.write(username.as_bytes());
        hasher.write(SECRET_KEY.as_bytes());
        format!("{:x}", hasher.finish())[..TOKEN_LENGTH].to_string()
    }

    // Process a resource bundle from a specified URL
    pub fn process_resource_bundle(&self, url: &str) -> Result<Vec<i64>, String> {
        let mut result = Vec::new();
        match get(url) {
            Ok(response) => {
                if response.status().is_success() {
                    match serde_json::from_reader(&response) {
                        Ok(bundle) => {
                            for entry in bundle["data"].members() {
                            let id = entry["id"].as_i64().unwrap();
                            result.push(id);
                        }
                    }
                } else {
                    return Err(format!("Invalid status code: {}", response.status()));
                }
            }
            Err(_) => {
                return Err("Error fetching resource bundle".to_string());
            }
        }
        Ok(result)
    }

