// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populate_crc_indication_pdu_list(int n) {
    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

