    for (int i = 0; i < n; i++) {
        crc_indication_pdu_list[i].rx_ue_information_tag = rand() % 256;
        crc_indication_pdu_list[i].rnti = rand() % 65536;
        crc_indication_pdu_list[i].crc_indication_rel8_tag = rand() % 256;
        crc_indication_pdu_list[i].crcflag = (rand() % 100) > 50;
    }

    // Test the populated structures
    for (int i = 0; i < n; i++) {
        BLUESLIP_LOG(BLUESLIP_INFO, "Testing CRC Indication PDU %d", i);
        if (!check_crc_indication_pdu(&crc_indication_pdu_list[i])) {
            BLUESLIP_LOG(BLUESLIP_ERROR, "CRC Indication PDU %d is invalid", i);
            break;
        }
    }

    // Reset the mocking library for the testing framework
    reset_blueslip();
}

// Function to check the validity of a NFAPI_CRC_INDICATION_PDU_T structure
bool check_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    // Check that the RX UE Information Tag is valid
    if (crc_indication_pdu->rx_ue_information_tag < 0 || crc_indication_pdu->rx_ue_information_tag > 255) {
        return false;
    }

    // Check that the RNTI is valid
    if (crc_indication_pdu->rnti < 0 || crc_indication_pdu->rnti > 65535) {
        return false;
    }

    // Check that the CRC Indication Rel-8 Tag is valid
    if (crc_indication_pdu->crc_indication_rel8_tag < 0 || crc_indication_pdu->crc_indication_rel8_tag > 255) {
        return false;
    }

    // Check that the CRC Flag is valid
    if (crc_indication_pdu->crcflag < 0 || crc_indication_pdu->crcflag > 1) {
        return false;
    }

    return true;
}
