// RemoteExecutor.js
const SSH = require('ssh2');
const HTTP = require('http');
const DNS = require('dns');
const ConfigParser = require('configparser');
const { promisify } = require('util');

class RemoteExecutor {
  constructor(config) {
    this.config = config;
    this.sshClient = new SSH();
    this.httpClient = new HTTP();
  }

  async executeRemoteCommand(command, options) {
    const { server, protocol, auth, commandParams, constraints } = options;

    // Connect to the server using the specified protocol (SSH or HTTP)
    let client;
    if (protocol === 'ssh') {
      client = this.sshClient;
    } else if (protocol === 'http') {
      client = this.httpClient;
    } else {
      throw new Error(`Unsupported protocol: ${protocol}`);
    }

    // Authenticate with the server using the specified auth method (password or key)
    if (auth.method === 'password') {
      await client.connect({
        host: server,
        username: auth.username,
        password: auth.password,
      });
    } else if (auth.method === 'key') {
      await client.connect({
        host: server,
        username: auth.username,
        privateKey: auth.privateKey,
        passphrase: auth.passphrase,
      });
    } else {
      throw new Error(`Unsupported authentication method: ${auth.method}`);
    }

    // Execute the command on the server and retrieve the output
    const { stdout, stderr } = await client.execCommand(command, { cwd: auth.cwd });
    let output = stdout;
    if (stderr) {
      output += stderr;
    }

    // Close the connection to the server and return the output
    await client.close();
    return output;
  }

  async discoverServers() {
    const servers = [];
    const configParser = new ConfigParser(this.config);

    // Discover servers using DNS, configuration files, and forward lists of strings
    if (configParser.has('dns')) {
      const dnsConfig = configParser.get('dns');
      const resolver = promisify(DNS.Resolver().resolve4);
      const records = await resolver(dnsConfig.domain, { ttl: true });
      for (const record of records) {
        servers.push(`${record}`)
      }
    } else if (configParser.has('configuration')) {
      const configuration = configParser.get('configuration');
      for (const server of configuration.servers) {
        servers.push(server);
      }
    } else if (configParser.has('forward_list')) {
      const forwardList = configParser.get('forward_list');
      servers.push(...forwardList);
    }

    return servers;
  }
}

module.exports = RemoteExecutor;
