// validateAndInsertTokenData.cpp
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>

using namespace std;

bool validateAndInsertTokenData(const unordered_map<string, string>& tokenData) {
  // Check if all required fields are present
  for (const auto& field : {"token_type", "expires_in"}) {
    if (!tokenData.contains(field)) {
      cerr << "Missing field: " << field << endl;
      return false;
    }
  }

  // Check if the token type is Bearer and expires in a positive integer value
  const auto& tokenType = tokenData.at("token_type");
  const auto& expiresIn = tokenData.at("expires_in");
  if (tokenType != "Bearer" || expiresIn <= 0) {
    cerr << "Invalid token type or expiration: " << tokenType << ", " << expiresIn << endl;
    return false;
  }

  // Check if the other fields are valid
  for (const auto& field : {"refresh_token", "scope"}) {
    if (!tokenData.contains(field)) continue;
    const auto& value = tokenData.at(field);
    if (value.empty()) {
      cerr << "Invalid field: " << field << endl;
      return false;
    }
  }

  return true;
}
