// ProcessUserQueryAsync.cs
using System;
using System.Data;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace MyNamespace {
  public class ProcessUserQueryAsync {
    private readonly string _connectionString;

    public ProcessUserQueryAsync(string connectionString) {
      _connectionString = connectionString;
    }

    public async Task<DataTable> QueryAsync(byte[] queryBytes) {
      using (var connection = new SqlConnection(_connectionString)) {
        try {
          await connection.OpenAsync();
        } catch (SqlException ex) {
          Console.WriteLine("Failed to connect to database: " + ex.Message);
          return null;
        }

        var query = Encoding.UTF8.GetString(queryBytes);
        using (var command = new SqlCommand(query, connection)) {
          try {
            using (var reader = await command.ExecuteReaderAsync()) {
              var table = new DataTable();
              table.Load(reader);
              return table;
            }
          } catch (SqlException ex) {
            Console.WriteLine("Failed to execute query: " + ex.Message);
            return null;
          }
        }
      }
    }
  }
}
