using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Collections.Generic;
using Newtonsoft.Json;

namespace BinaryDataDeserializer
{
    public class Deserializer
    {
        private readonly IDictionary<string, Func<Stream, object>> _deserializers = new Dictionary<string, Func<Stream, object>>();
        private readonly IList<string> _supportedFormats = new List<string>();

        public Deserializer()
        {
            RegisterDeserializer("application/json", stream => JsonConvert.DeserializeObject(stream));
            RegisterDeserializer("application/xml", stream => XmlConvert.DeserializeObject(stream));
            RegisterDeserializer("application/protobuf", stream => ProtoBuf.Serializer.Deserialize<object>(stream));
            RegisterDeserializer("application/msgpack", stream => MessagePackSerializer.Deserialize<object>(stream));
        }

        public void RegisterDeserializer(string contentType, Func<Stream, object> deserializer)
        {
            _deserializers[contentType] = deserializer;
            _supportedFormats.Add(contentType);
        }

        public async Task<object> DeserializeAsync(Stream stream, string contentType)
        {
            if (_deserializers.TryGetValue(contentType, out var deserializer))
            {
                return await Task.Run(() => deserializer(stream));
            }
            else
            {
                throw new Exception($"Unsupported content type: {contentType}");
            }
        }
    }

    public class DeserializationResult
    {
        public object Data { get; set; }
        public bool Success { get; set; }
        public string ErrorMessage { get; set; }
    }
}
```
