        private readonly bool _enableCache;
        private readonly int _cacheExpirationTime;
        private readonly DataTable _dataTable;

        public DataTableReader(string endpointUrl, string cachePath, bool enableCache, int cacheExpirationTime)
        {
            _httpClient = new HttpClient();
            _endpointUrl = endpointUrl;
            _cachePath = cachePath;
            _enableCache = enableCache;
            _cacheExpirationTime = cacheExpirationTime;
            _dataTable = null;
        }

        public async Task<DataTable> QueryAsync(string query, int maxRows)
        {
            // Check if the query is already cached
            if (_enableCache && IsCachedQuery(query))
            {
                return await GetCachedDataTable(query);
            }

            // Perform the query and cache the result
            var response = await _httpClient.GetAsync(_endpointUrl + "?q=" + query);
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception("Failed to retrieve data from server");
            }

            var result = await response.Content.ReadAsStringAsync();
            _dataTable = ConvertToDataTable(result, maxRows);
            CacheQuery(query, _dataTable);

            return _dataTable;
        }

