        {
            // Implement your own data conversion logic here
            var table = new DataTable();
            // Add columns to the table based on the query results
            // ...
            return table;
        }

        private bool IsCachedQuery(string query)
        {
            // Check if the query is already cached in memory or on disk
            var cacheFile = _cachePath + query + ".json";
            if (System.IO.File.Exists(cacheFile))
            {
                return true;
            }
            else
            {
                return false;
            }
        }

        private void CacheQuery(string query, DataTable dataTable)
        {
            // Write the cached data to a JSON file
            var cacheFile = _cachePath + query + ".json";
            System.IO.File.WriteAllText(cacheFile, dataTable.ToJson());
        }

        private async Task<DataTable> GetCachedDataTable(string query)
        {
            // Read the cached data from a JSON file
            var cacheFile = _cachePath + query + ".json";
            var json = System.IO.File.ReadAllText(cacheFile);
            return ConvertToDataTable(json, int.MaxValue);
        }
    }
}
