using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using UnityEngine;

public class DynamicRandomValueGenerator
{
    private readonly object syncRoot = new object();
    private readonly Dictionary<int, DistributionMetadata> distributionMetadataCache = new Dictionary<int, DistributionMetadata>();
    private readonly ThreadPool threadPool = new ThreadPool(10);
    private int seed;
    private bool isSeedInitialized;
    private string jsonConfigurationFilePath;
    private string remoteServerUrl;

    public DynamicRandomValueGenerator() { }

    public void SetJsonConfigurationFilePath(string path)
    {
        jsonConfigurationFilePath = path;
    }

    public void SetRemoteServerUrl(string url)
    {
        remoteServerUrl = url;
    }

    public void GenerateRandomValues(int rangeStart, int rangeEnd, DistributionType distributionType, int threadCount)
    {
        if (!isSeedInitialized)
            InitializeSeed();

        List<Thread> threads = new List<Thread>();
        for (int i = 0; i < threadCount; i++)
        {
            Thread thread = new Thread(new ThreadStart(() =>
            {
                GenerateRandomValuesInRange(rangeStart, rangeEnd, distributionType);
            }));
            threads.Add(thread);
        }

        foreach (Thread thread in threads)
        {
            thread.Start();
        }

        foreach (Thread thread in threads)
        {
            thread.Join();
        }
    }

    private void InitializeSeed()
    {
        if (!isSeedInitialized)
        {
            seed = UnityEngine.Random.Range(1, int.MaxValue);
            isSeedInitialized = true;
        }
    }

    private void GenerateRandomValuesInRange(int rangeStart, int rangeEnd, DistributionType distributionType)
    {
        lock (syncRoot)
        {
            if (!distributionMetadataCache.ContainsKey(rangeStart))
                LoadDistributionMetadataFromExternalSource(rangeStart);

            DistributionMetadata metadata = distributionMetadataCache[rangeStart];
            float randomValue;

            switch (distributionType)
            {
                case DistributionType.Uniform:
                    randomValue = UnityEngine.Random.Range(metadata.Min, metadata.Max);
                    break;
                case DistributionType.Normal:
                    randomValue = Random.NextGaussian(metadata.Mean, metadata.StandardDeviation);
                    break;
                case DistributionType.Lognormal:
                    randomValue = Random.NextLognormal(metadata.Mean, metadata.StandardDeviation);
                    break;
            }

            Console.WriteLine($"Generated value {randomValue} for range [{rangeStart}, {rangeEnd}] using distribution type {distributionType}");
        }
    }

    private void LoadDistributionMetadataFromExternalSource(int rangeStart)
    {
        if (!string.IsNullOrEmpty(jsonConfigurationFilePath))
        {
            // Read JSON configuration file and parse it to get the distribution metadata for the given range
            DistributionMetadata metadata = ParseJsonConfigurationFile(jsonConfigurationFilePath, rangeStart);
            distributionMetadataCache[rangeStart] = metadata;
        }
        else if (!string.IsNullOrEmpty(remoteServerUrl))
        {
            // Fetch distribution metadata from remote server for the given range
            DistributionMetadata metadata = FetchDistributionMetadataFromRemoteServer(remoteServerUrl, rangeStart);
            distributionMetadataCache[rangeStart] = metadata;
        }
    }

    private DistributionMetadata ParseJsonConfigurationFile(string filePath, int rangeStart)
    {
        // Parse the JSON configuration file and return the distribution metadata for the given range
        using (StreamReader reader = new StreamReader(filePath))
        {
            string jsonData = reader.ReadToEnd();
            Dictionary<int, DistributionMetadata> metadataMap = JsonConvert.DeserializeObject<Dictionary<int, DistributionMetadata>>(jsonData);
            return metadataMap[rangeStart];
        }
    }

    private DistributionMetadata FetchDistributionMetadataFromRemoteServer(string url, int rangeStart)
    {
        // Fetch distribution metadata from remote server for the given range
        using (WebClient client = new WebClient())
        {
            string jsonData = client.DownloadString(url + "/" + rangeStart);
            return JsonConvert.DeserializeObject<DistributionMetadata>(jsonData);
        }
    }
}

public enum DistributionType
{
    Uniform,
    Normal,
    Lognormal
}

public class DistributionMetadata
{
    public float Min { get; set; }
    public float Max { get; set; }
    public float Mean { get; set; }
    public float StandardDeviation { get; set; }
}
