import json
from typing import List, Dict

def generate_dashboard_widgets(widgets: List[Dict]) -> str:
    # Validate the input data
    if not isinstance(widgets, list) or len(widgets) == 0:
        raise ValueError("Invalid widget list")
    for widget in widgets:
        if not isinstance(widget, dict) or "title" not in widget or "width" not in widget or "height" not in widget or "data_source" not in widget or "refresh_interval" not in widget or "secure" not in widget:
            raise ValueError("Invalid widget attributes")
        if not isinstance(widget["title"], str) or len(widget["title"]) == 0:
            raise ValueError("Widget title must be a non-empty string")
        if not isinstance(widget["width"], int) or widget["width"] < 1:
            raise ValueError("Widget width must be a positive integer")
        if not isinstance(widget["height"], int) or widget["height"] < 1:
            raise ValueError("Widget height must be a positive integer")
        if not isinstance(widget["data_source"], str) or len(widget["data_source"]) == 0:
            raise ValueError("Invalid data source URL")
        if not isinstance(widget["refresh_interval"], int) or widget["refresh_interval"] < 1:
            raise ValueError("Refresh interval must be a positive integer")
        if not isinstance(widget["secure"], bool):
            raise ValueError("Secure flag must be a boolean value")

    # Handle multiple dashboard layouts and dynamic resizing of widgets
    layout = "vertical"  # default layout
    total_width, total_height = 0, 0  # initialize total width and height
    for widget in widgets:
        if widget["secure"]:
            secure_widgets.append(widget)  # store secure widgets separately for caching
        else:
            insecure_widgets.append(widget)  # store insecure widgets separately for caching

    # Prioritize criticality level of widgets based on their importance
    critical_level = {
        "low": 1,
        "medium": 2,
        "high": 3,
    }
    widgets.sort(key=lambda x: critical_level[x["criticality"]])

    # Generate dashboard configuration JSON string
    config = {
        "title": "Dashboard",
        "layout": layout,
        "widgets": [],
        "refresh_interval": 10,  # default refresh interval (in seconds)
    }
    for widget in widgets:
        if not widget["secure"] or widget in secure_widgets:
            config["widgets"].append({
                "title": widget["title"],
                "width": widget["width"],
                "height": widget["height"],
                "data_source": widget["data_source"],
                "refresh_interval": widget["refresh_interval"],
                "secure": widget["secure"],
            })

    return json.dumps(config)
