```javascript
const express = require('express');
const request = require('request');
const redis = require('redis');
const cassandra = require('cassandra-driver');

// Set up the Express app
const app = express();
app.use(express.json());

// Set up the Redis client
const redisClient = redis.createClient({ host: 'localhost', port: 6379 });

// Set up the Cassandra client
const cassandraClient = new cassandra.Client({ contactPoints: ['localhost'] });

// Define the API endpoint for data collection
app.get('/collect-data', (req, res) => {
  // Make a request to the third-party streaming API
  const apiUrl = 'https://api.example.com/streaming';
  request({
    url: apiUrl,
    headers: {
      'Authorization': `Bearer ${req.query.token}`
    }
  }, (error, response, body) => {
    if (error || response.statusCode !== 200) {
      // Handle API errors and rate limiting
      console.log(`API error: ${error}. Status code: ${response.statusCode}`);
      res.status(500).send('Error collecting data');
    } else {
      const data = JSON.parse(body);
      // Process the collected data and save it to Redis
      redisClient.set(`${data.deviceId}-${data.timestamp}`, JSON.stringify(data));
      // Save the processed data to Cassandra
      cassandraClient.execute(`INSERT INTO sensor_data (device_id, timestamp, value) VALUES (${data.deviceId}, ${data.timestamp}, ${data.value})`);
      res.send('Data collected successfully');
    }
  });
});

// Define the API endpoint for data retrieval
app.get('/retrieve-data', (req, res) => {
  // Retrieve the requested device ID and timestamp from Redis
  const deviceId = req.query.device_id;
  const timestamp = req.query.timestamp;
  redisClient.get(`${deviceId}-${timestamp}`, (error, data) => {
    if (error || !data) {
      // Handle Redis errors and missing data
      console.log(`Redis error: ${error}. Data not found.`);
      res.status(404).send('Data not found');
    } else {
      const parsedData = JSON.parse(data);
      // Return the retrieved data as a JSON object
      res.json({
        deviceId,
        timestamp,
        value: parsedData.value
      });
    }
  });
});

// Define the API endpoint for data processing
app.post('/process-data', (req, res) => {
  // Retrieve the requested device ID and timestamp from Redis
  const deviceId = req.body.device_id;
  const timestamp = req.body.timestamp;
  redisClient.get(`${deviceId}-${timestamp}`, (error, data) => {
    if (error || !data) {
      // Handle Redis errors and missing data
      console.log(`Redis error: ${error}. Data not found.`);
      res.status(404).send('Data not found');
    } else {
      const parsedData = JSON.parse(data);
      // Process the collected data and save it to Cassandra
      cassandraClient.execute(`INSERT INTO sensor_data (device_id, timestamp, value) VALUES (${parsedData.deviceId}, ${parsedData.timestamp}, ${parsedData.value})`);
      res.send('Data processed successfully');
    }
  });
});

// Define the API endpoint for data validation and sanitization
app.post('/validate-data', (req, res) => {
  // Retrieve the requested device ID and timestamp from Redis
  const deviceId = req.body.device_id;
  const timestamp = req.body.timestamp;
  redisClient.get(`${deviceId}-${timestamp}`, (error, data) => {
    if (error || !data) {
      // Handle Redis errors and missing data
      console.log(`Redis error: ${error}. Data not found.`);
      res.status(404).send('Data not found');
    } else {
      const parsedData = JSON.parse(data);
      // Validate the collected data and sanitize it as needed
      if (parsedData.value < 0 || parsedData.value > 10) {
        res.status(400).send('Invalid data value');
      } else {
        cassandraClient.execute(`INSERT INTO sensor_data (device_id, timestamp, value) VALUES (${parsedData.deviceId}, ${parsedData.timestamp}, ${parsedData.value})`);
        res.send('Data validated and sanitized successfully');
      }
    }
  });
});

// Define the API endpoint for data configuration and management
app.post('/config', (req, res) => {
  // Retrieve the requested device ID and timestamp from Redis
  const deviceId = req.body.device_id;
  const timestamp = req.body.timestamp;
  redisClient.get(`${deviceId}-${timestamp}`, (error, data) => {
    if (error || !data) {
      // Handle Redis errors and missing data
      console.log(`Redis error: ${error}. Data not found.`);
      res.status(404).send('Data not found');
    } else {
      const parsedData = JSON.parse(data);
      // Update the collected data and save it to Redis and Cassandra
      cassandraClient.execute(`UPDATE sensor_data SET value=${parsedData.value} WHERE device_id=${parsedData.deviceId} AND timestamp=${parsedData.timestamp}`);
      redisClient.set(`${parsedData.deviceId}-${parsedData.timestamp}`, JSON.stringify(parsedData));
      res.send('Data updated successfully');
    }
  });
});

// Start the Express app
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
