    }
}

impl rustc_plugin::Plugin for MyPlugin {
    fn build(&mut self, registry: &mut Registry) {
        registry.register_late_pass(|| Box::new(MyLatePass));
    }
}

struct MyLatePass;

impl rustc_driver::Callback for MyLatePass {
    fn on_crate(&self, krate: &mut rustc_ast::Crate, _: &rustc_driver::Compilation) {
        let ctx = BuildContext::new(krate);
        let compiler = CargoCompiler::new();

        // measure compilation time and memory usage
        let start = std::time::Instant::now();
        compiler.run(&ctx, krate);
        let end = std::time::Instant::now();

        let elapsed_secs = end.duration_since(start).as_secs_f64();
        println!("Compilation time: {:?}", elapsed_secs);

        // report compilation statistics
        println!("RSS: {:?}", ctx.memory().rss());
        println!("Memory usage: {:?}", ctx.memory().used());
    }
}
