This program includes a function `DynamicImageProcessing` that manages the dynamic conversion and analysis of image files in a production environment. The function takes a file name for the input image (which can be either JPEG, PNG, or BMP), a file name for the output JSON file detailing the image properties, and pointers to structs to store parsed information about the TIFF image's bits per sample, sample per pixel, and compression type.

The program integrates a third-party image conversion library (e.g., ImageMagick) to convert the input image to a TIFF format if necessary. The function `ConvertImage` uses this library to convert the input image file to a TIFF format and save it to the output file path specified by the user.

The program also includes a function `AnalyzeImage` that analyzes the converted TIFF image and extracts details on its bits per sample, sample per pixel, and compression type. The function uses this library to analyze the TIFF image and store the extracted information in a struct defined by the user.

To handle potential errors during the conversion and analysis processes, the program includes a mechanism to limit the number of threads based on the system's CPU core count. This ensures efficient use of system resources and avoids contention issues. The function `DynamicImageProcessing` uses multi-threading support to run the conversion and analysis processes concurrently, which can improve performance for large image files.

The program also includes a function to decrypt a given ciphertext using AES-CBC with a specified encryption key, IV, and padding. This function returns the decrypted plaintext as a byte array. The user can specify the encryption key, initialization vector (IV), and padding mode when calling the function.

The codebase adheres to good coding practices by separating concerns, modular design, thorough unit testing, and gracefully handling edge cases such as invalid file paths, unsupported image types, and resource limitations. The program includes logging and monitoring mechanisms to track its performance and errors.

package com.example.imagemanagement;

import java.io.File;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.TimeUnit;

import org.apache.commons.io.FileUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ImageCacheManager {
    private static final Logger LOGGER = LoggerFactory.getLogger(ImageCacheManager.class);

    private final Map<String, List<Image>> imageMap = new HashMap<>();
    private final Set<String> recentlyAccessedImages = new HashSet<>();
    private final File cacheDir;
    private final int maxCacheSizeMB;
    private final long inactivityThresholdMillis;
    private final long usageFrequencyThresholdMillis;

    public ImageCacheManager(File cacheDir, int maxCacheSizeMB, long inactivityThresholdMillis,
            long usageFrequencyThresholdMillis) {
        this.cacheDir = cacheDir;
        this.maxCacheSizeMB = maxCacheSizeMB;
        this.inactivityThresholdMillis = inactivityThresholdMillis;
        this.usageFrequencyThresholdMillis = usageFrequencyThresholdMillis;
    }

    public void start() {
        LOGGER.info("Starting image cache manager");
        cleanupCache();
        loadCacheFromDisk();
        startBackgroundThread();
    }

    private void cleanupCache() {
        LOGGER.info("Cleaning up image cache");
        List<Image> toRemove = new ArrayList<>();
        for (String key : imageMap.keySet()) {
            if (!recentlyAccessedImages.contains(key)) {
                toRemove.addAll(imageMap.get(key));
            }
        }
        for (Image image : toRemove) {
            imageMap.remove(image.getName());
        }
    }

    private void loadCacheFromDisk() {
        File[] files = cacheDir.listFiles();
        if (files == null || files.length == 0) {
            return;
        }
        LOGGER.info("Loading image cache from disk");
        for (File file : files) {
            Image image = new Image(file);
            List<Image> images = imageMap.getOrDefault(image.getName(), new ArrayList<>());
            images.add(image);
            imageMap.put(image.getName(), images);
        }
    }

    private void startBackgroundThread() {
        Thread backgroundThread = new Thread(() -> {
            while (true) {
                try {
                    TimeUnit.MINUTES.sleep(10);
                } catch (InterruptedException e) {
                    LOGGER.error("Error sleeping in background thread", e);
                }
                cleanupCache();
            }
        });
        backgroundThread.start();
    }

    public void fetchImage(String imageName, String themeName) {
        Image image = new Image(imageName, themeName);
        List<Image> images = imageMap.getOrDefault(image.getName(), new ArrayList<>());
        if (images.size() >= 10) {
            recentlyAccessedImages.remove(images.get(0).getName());
            images.remove(0);
        }
        images.add(image);
        imageMap.put(imageName, images);
        recentlyAccessedImages.add(imageName);
    }

    public void switchTheme(String userId, String newThemeName) {
        for (String imageName : imageMap.keySet()) {
            List<Image> images = imageMap.get(imageName);
            Image newImage = new Image(imageName, newThemeName);
            if (!images.contains(newImage)) {
                images.add(newImage);
            }
        }
    }

    public void setInactivityThreshold(String userId, String themeName, long inactivityThresholdMillis) {
        Image image = new Image(userId, themeName);
        image.setInactivityThreshold(inactivityThresholdMillis);
    }

    public void setUsageFrequencyThreshold(String userId, String themeName, long usageFrequencyThresholdMillis) {
        Image image = new Image(userId, themeName);
        image.setUsageFrequencyThreshold(usageFrequencyThresholdMillis);
    }

    public void updateCache() {
        // TODO: Update cache with newly fetched images from external storage service
    }

    public static class Image {
        private final String name;
        private final String themeName;
        private long lastAccessTime;
        private long usageFrequency;
        private int version;
        private File file;

        public Image(String name, String themeName) {
            this.name = name;
            this.themeName = themeName;
        }

        public String getName() {
            return name;
        }

        public String getThemeName() {
            return themeName;
        }

        public long getLastAccessTime() {
            return lastAccessTime;
        }

        public void setLastAccessTime(long lastAccessTime) {
            this.lastAccessTime = lastAccessTime;
        }

        public long getUsageFrequency() {
            return usageFrequency;
        }

        public void setUsageFrequency(long usageFrequency) {
            this.usageFrequency = usageFrequency;
        }

        public int getVersion() {
            return version;
        }

        public void setVersion(int version) {
            this.version = version;
        }

        public File getFile() {
            return file;
        }

        public void setFile(File file) {
            this.file = file;
        }
    }
}

