#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Constants
#define MAX_FILENAME_LENGTH 256
#define MAX_EXTENSION_LENGTH 10
#define CONFIG_FILE "config.txt"
#define NUM_THREADS 8

// Data structures
typedef struct {
    char *filename;
    char *extension;
} file_t;

typedef struct {
    char *filename;
    char *old_extension;
    char *new_extension;
} modify_file_args_t;

// Global variables
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int num_threads = 0;
int num_files = 0;
file_t *files = NULL;

// Function declarations
void *modify_file(void *args);
void read_config();
void write_config();
void handle_errors(char *filename, char *extension, int rc);
void handle_race_conditions(file_t *file);
void handle_deadlocks(int rc);
void cleanup();

// Main function
int main() {
    // Initialize global variables and data structures
    read_config();

    // Start threads to modify files
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_t thread;
        int rc = pthread_create(&thread, NULL, modify_file, NULL);
        if (rc != 0) {
            handle_errors(NULL, NULL, rc);
        }
    }

    // Wait for threads to complete
    pthread_mutex_lock(&lock);
    while (num_threads > 0) {
        pthread_cond_wait(&cond, &lock);
    }
    pthread_mutex_unlock(&lock);

    // Clean up and exit
    cleanup();
    return 0;
}

// Function to modify files in parallel
void *modify_file(void *args) {
    modify_file_args_t *modify_args = (modify_file_args_t *) args;
    char *filename = modify_args->filename;
    char *old_extension = modify_args->old_extension;
    char *new_extension = modify_args->new_extension;

    // Check if file exists and is not already with the new extension
    struct stat file_info;
    int rc = stat(filename, &file_info);
    if (rc == -1) {
        handle_errors(filename, old_extension, rc);
    } else if (!strcmp(old_extension, new_extension)) {
        // File is already with the new extension, skip modification
        return NULL;
    }

    // Acquire lock to modify file
    pthread_mutex_lock(&lock);

    // Modify file name and update configuration
    char *old_filename = filename;
    filename = strdup(strcat(filename, new_extension));
    free(old_filename);
    write_config();

    // Release lock and signal completion
    pthread_mutex_unlock(&lock);
    pthread_cond_signal(&cond);

    return NULL;
}

// Function to read configuration data from file
void read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        handle_errors("", "", ENOENT);
    }

    // Read number of files and allocate memory for file list
    fscanf(fp, "%d\n", &num_files);
    files = calloc(num_files, sizeof(file_t));

    // Read file names and extensions from configuration file
    char *filename;
    char *extension;
    for (int i = 0; i < num_files; i++) {
        fscanf(fp, "%s %s\n", &filename, &extension);
        files[i].filename = filename;
        files[i].extension = extension;
    }

    // Close configuration file
    fclose(fp);
}

// Function to write configuration data to file
void write_config() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        handle_errors("", "", ENOENT);
    }

    // Write number of files and file list to configuration file
    fprintf(fp, "%d\n", num_files);
    for (int i = 0; i < num_files; i++) {
        fprintf(fp, "%s %s\n", files[i].filename, files[i].extension);
    }

    // Close configuration file
    fclose(fp);
}

// Function to handle errors during file name parsing and modification
void handle_errors(char *filename, char *extension, int rc) {
    printf("Error: %s\n", strerror(rc));
    if (filename != NULL && extension != NULL) {
        printf("File: %s%s\n", filename, extension);
    }
    cleanup();
    exit(EXIT_FAILURE);
}

// Function to handle race conditions during file modification
void handle_race_conditions(file_t *file) {
    // Check if file exists and is not already with the new extension
    struct stat file_info;
    int rc = stat(file->filename, &file_info);
    if (rc == -1) {
        handle_errors(file->filename, file->extension, rc);
    } else if (!strcmp(file->extension, new_extension)) {
        // File is already with the new extension, skip modification
        return;
    }

    // Acquire lock to modify file
    pthread_mutex_lock(&lock);

    // Modify file name and update configuration
    char *old_filename = file->filename;
    file->filename = strdup(strcat(file->filename, new_extension));
    free(old_filename);
    write_config();

    // Release lock and signal completion
    pthread_mutex_unlock(&lock);
    pthread_cond_signal(&cond);
}

// Function to handle potential deadlocks during file modification
void handle_deadlocks(file_t *file) {
    // Check if file exists and is not already with the new extension
    struct stat file_info;
    int rc = stat(file->filename, &file_info);
    if (rc == -1) {
        handle_errors(file->filename, file->extension, rc);
    } else if (!strcmp(file->extension, new_extension)) {
        // File is already with the new extension, skip modification
        return;
    }

    // Acquire lock to modify file
    pthread_mutex_lock(&lock);

    // Modify file name and update configuration
    char *old_filename = file->filename;
    file->filename = strdup(strcat(file->filename, new_extension));
    free(old_filename);
    write_config();

    // Release lock and signal completion
    pthread_mutex_unlock(&lock);
    pthread_cond_signal(&cond);
}

// Function to clean up resources after an error or termination
void cleanup() {
    if (files != NULL) {
        for (int i = 0; i < num_files; i++) {
            free(files[i].filename);
            free(files[i].extension);
        }
        free(files);
    }
}

