namespace RandomGenerator {
    class ParallelMTGenerator {
        std::vector<std::mt19937> mt_engines; // pool of Mersenne Twister engines
        int seed;                            // current seed value
        size_t thread_pool_size;             // number of threads in the pool
        bool initialized = false;           // flag to indicate initialization status

    public:
        ParallelMTGenerator(int seed, size_t thread_pool_size);
        ~ParallelMTGenerator();

