using namespace RandomGenerator;

ParallelMTGenerator::ParallelMTGenerator(int seed, size_t thread_pool_size) {
    this->seed = seed;
    this->thread_pool_size = thread_pool_size;
}

void ParallelMTGenerator::initialize() {
    if (initialized) return;

    // create a pool of Mersenne Twister engines
    mt_engines.resize(thread_pool_size);
    for (int i = 0; i < thread_pool_size; ++i) {
        std::mt19937& engine = mt_engines[i];
        engine.seed(seed + i);
    }

    initialized = true;
}

void ParallelMTGenerator::generateRandomNumber(std::mt19937& engine, int min, int max) {
    if (!initialized) initialize();

    // generate a random number using the Mersenne Twister algorithm
    std::uniform_int_distribution<int> distribution(min, max);
    return distribution(engine);
}

void ParallelMTGenerator::validateRandomness(std::vector<int>& random_numbers) {
    // perform statistical tests to validate the randomness of the generated numbers
