import json
import threading
import time
import random
from datetime import datetime

class SecureRandomStringGenerator:
    def __init__(self, config_file):
        self.config = json.load(open(config_file))
        self.contexts = {}
        self.rate_limit = self.config["rate_limit"]
        self.next_request_time = 0

    def get_random_string(self, context=None):
        if not context:
            context = "default"
        if context not in self.contexts:
            self.contexts[context] = {}

        current_time = datetime.now().timestamp()
        if current_time < self.next_request_time:
            time.sleep(self.next_request_time - current_time)

        entropy = self.config["entropy"]
        length = self.config[context]["string_length"]
        charsets = self.config[context]["charsets"]
        string = "".join([random.choice(charsets) for _ in range(length)])

        if self.validate_string(string, context):
            return string
        else:
            raise ValueError("Invalid generated string")

    def validate_string(self, string, context=None):
        if not context:
            context = "default"
        regexes = self.config[context]["regex"]
        for regex in regexes:
            if re.match(regex, string):
                return True
        return False

    def set_rate_limit(self, rate_limit):
        self.rate_limit = rate_limit

    def get_contexts(self):
        return list(self.contexts.keys())

    def get_config(self, context=None):
        if not context:
            context = "default"
        return self.config[context]

    def update_config(self, config):
        with open(self.config_file, "w") as f:
            json.dump(config, f)
        self.config = config

class SecureRandomStringGenerationTest(unittest.TestCase):
    def test_valid_string_generation(self):
        generator = SecureRandomStringGenerator("config.json")
        string = generator.get_random_string()
        self.assertIsNotNone(string)
        self.assertTrue(generator.validate_string(string))

    def test_invalid_string_generation(self):
        generator = SecureRandomStringGenerator("config.json")
        string = generator.get_random_string()
        self.assertIsNotNone(string)
        self.assertFalse(generator.validate_string("abc"))

    def test_context_switching(self):
        generator = SecureRandomStringGenerator("config.json")
        string1 = generator.get_random_string()
        string2 = generator.get_random_string("other_context")
        self.assertNotEqual(string1, string2)

    def test_rate_limiting(self):
        generator = SecureRandomStringGenerator("config.json")
        for _ in range(generator.rate_limit):
            generator.get_random_string()
        start_time = time.perf_counter()
        generator.get_random_string()
        end_time = time.perf_counter()
        self.assertGreater(end_time - start_time, 1)
