void nfapiDataGeneration() {
    // Get the current time in milliseconds
    auto startTime = chrono::high_resolution_clock::now().time_since_epoch();

    // Loop until the specified timeout is reached
    while (chrono::duration_cast<chrono::seconds>(chrono::high_resolution_clock::now().time_since_epoch() - startTime).count() < 60) {
        // Acquire the mutex for thread safety
        unique_lock<mutex> lock(mtx);

        // Fetch the CRC FLAG values from the API using an asynchronous query mechanism
        string crcFlagValues = apiQuery();

        // If the API fails to provide CRC FLAG values, use predefined default values to maintain service continuity
        if (crcFlagValues.empty()) {
            crcFlagValues = "010203";
        }

        // Parse the received CRC FLAG values and populate the forward list of NFAPI CRC Indication PDUS
        for (const auto& crcFlagValue : crcFlagValues) {
