// Function to insert a second string after the first occurrence of a specified string in a forward list, while ensuring thread safety for concurrent modifications
void insertStringAfterFirstOccurrence(const string& strToInsert, const string& strToSearchFor) {
    // Acquire the mutex for thread safety
    unique_lock<mutex> lock(mtx);

    // Find the first occurrence of the specified string in the forward list
    auto it = find(nfapiDataList.begin(), nfapiDataList.end(), strToSearchFor);

    // If the specified string is not found, insert the second string at the end of the list
