    } else {
        // Insert the second string after the first occurrence of the specified string in the forward list
        nfapiDataList.insert(it + 1, strToInsert);
    }

    // Release the mutex after populating the forward list
    lock.unlock();
}

// Function to monitor and alert on potential overloads caused by excessive API request rates or high traffic loads
void checkForOverloads() {
    // Acquire the mutex for thread safety
    unique_lock<mutex> lock(mtx);

    // Check if there are any potential overloads caused by excessive API request rates or high traffic loads
    auto it = find_if(nfapiDataList.begin(), nfapiDataList.end(), [](const NFAPIData& data) { return data.rxUETag > 9000; });

