#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <dirent.h>
#include <magick/Magick++.h>

void processImageSequence(const char* directoryPath, const char* supportedInputFormats, bool useConcurrency) {
    // Create a new image processing context
    Magick::InitializeMagick();
    Magick::ImageContext context;

    // Check if the input directory exists and is readable
    struct stat sb;
    if (stat(directoryPath, &sb) == -1 || !S_ISDIR(sb.st_mode)) {
        fprintf(stderr, "Error: Input directory %s does not exist or is not readable\n", directoryPath);
        return;
    }

    // Get the list of supported input formats from the command line argument
    char** supportedInputFormatsArray = (char**)supportedInputFormats;
    int numSupportedInputFormats = strlen(supportedInputFormatsArray[0]);

    // Create a new directory to store the processed images
    const char* outputDirectoryPath = "processed_images";
    mkdir(outputDirectoryPath, 0755);

    // Iterate over each image file in the input directory
    DIR* dir = opendir(directoryPath);
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Check if the current entry is a file and has one of the supported input formats
        const char* fileName = entry->d_name;
        if (strstr(fileName, ".") && strstr(fileName, ".")) {
            int indexOfDot = strlen(fileName) - 1;
            while (indexOfDot >= 0 && fileName[indexOfDot] != '.') {
                --indexOfDot;
            }
            if (indexOfDot == 0 || (indexOfDot > 0 && !strcmp(&fileName[indexOfDot - 1], "."))) {
                continue;
            }
        }

        // Convert the image file from its original format to TIFF format using ImageMagick
        Magick::Image inputImage(directoryPath + fileName);
        if (!inputImage.isValid()) {
            fprintf(stderr, "Error: Unable to read %s\n", fileName);
            continue;
        }
        inputImage.convert("TIFF");

        // Extract the metadata from the TIFF image file
        Magick::Metadata metadata = inputImage.getMetadata();
        if (metadata.isEmpty()) {
            fprintf(stderr, "Error: Unable to extract metadata from %s\n", fileName);
            continue;
        }

        // Print a summary of the extracted metadata
        printf("Processed image %s:\n", fileName);
        for (int i = 0; i < metadata.size(); ++i) {
            Magick::MetadataItem item = metadata[i];
            if (item.isString()) {
                printf("%s: %s\n", item.getName().data(), item.getStringValue());
            } else if (item.isDouble()) {
                printf("%s: %f\n", item.getName().data(), item.getDoubleValue());
            } else {
                printf("%s: %d\n", item.getName().data(), item.getIntValue());
            }
        }

        // Write the converted TIFF image to a new file in the output directory
        inputImage.write(outputDirectoryPath + "/" + fileName);
    }
}
