#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <limits.h>
#include <stdbool.h>

// Define a structure to hold the configuration information for the program
typedef struct {
    int num_digits;
    char* file_type;
} config_t;

// Define a function to read and parse the external configuration file
config_t* read_config(const char* filename) {
    // Open the configuration file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return NULL;
    }

    // Read and parse the contents of the file
    config_t* config = malloc(sizeof(config_t));
    if (fscanf(fp, "%d %s", &config->num_digits, config->file_type) != 2) {
        perror("Error reading configuration file");
        free(config);
        return NULL;
    }

    // Close the configuration file
    fclose(fp);

    return config;
}

// Define a function to modify the filename based on the criteria in the configuration file
char* modifyFileName(const char* original_filename, const config_t* config) {
    char* modified_filename = malloc(PATH_MAX + 1);
    if (modified_filename == NULL) {
        perror("Error allocating memory for modified filename");
        return NULL;
    }

    // Parse the original filename and extract the extension
    const char* dot = strrchr(original_filename, '.');
    if (dot == NULL) {
        fprintf(stderr, "Invalid original filename: %s\n", original_filename);
        free(modified_filename);
        return NULL;
    }

    // Append the new extension to the modified filename
    int len = dot - original_filename;
    memcpy(modified_filename, original_filename, len);
    snprintf(modified_filename + len, PATH_MAX - len, ".%s", config->file_type);

    return modified_filename;
}

// Define a function to handle potential errors during file name parsing and modification
bool validateFileName(const char* filename) {
    // Check if the filename is valid
    const char* dot = strrchr(filename, '.');
    if (dot == NULL) {
        fprintf(stderr, "Invalid original filename: %s\n", filename);
        return false;
    }

    // Check if the extension is supported
    size_t len = dot - filename;
    for (size_t i = 0; i < config->num_extensions; i++) {
        if (strcmp(config->file_types[i], dot + 1) == 0) {
            return true;
        }
    }

    fprintf(stderr, "Unsupported file extension: %s\n", dot + 1);
    return false;
}

// Define a function to lock the file for modification
int lockFile(const char* filename) {
    // Open the file for reading and writing
    int fd = open(filename, O_RDWR);
    if (fd == -1) {
        perror("Error opening file");
        return -1;
    }

    // Lock the file using the FLOCK system call
    struct flock fl;
    fl.l_type = F_WRLCK;
    fl.l_whence = SEEK_SET;
    fl.l_start = 0;
    fl.l_len = 1;
    if (fcntl(fd, F_SETLKW, &fl) == -1) {
        perror("Error locking file");
        close(fd);
        return -1;
    }

    return fd;
}

// Define a function to unlock the file after modification
void unlockFile(int fd) {
    struct flock fl;
    fl.l_type = F_UNLCK;
    fl.l_whence = SEEK_SET;
    fl.l_start = 0;
    fl.l_len = 1;
    if (fcntl(fd, F_SETLKW, &fl) == -1) {
        perror("Error unlocking file");
    }

    close(fd);
}

// Define a function to search for files in the directory and modify them based on the criteria in the configuration file
void processDirectory(const char* directory, const config_t* config) {
    // Open the directory for reading
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip over any files that begin with a '.'
        if (entry->d_name[0] == '.') {
            continue;
        }

        // Create the full path to the file
        char* filename = malloc(PATH_MAX + 1);
        snprintf(filename, PATH_MAX, "%s/%s", directory, entry->d_name);

        // Check if the file exists and is a regular file
        struct stat st;
        if (stat(filename, &st) == -1 || !S_ISREG(st.st_mode)) {
            free(filename);
            continue;
        }

        // Lock the file for modification
        int fd = lockFile(filename);
        if (fd == -1) {
            perror("Error locking file");
            free(filename);
            continue;
        }

        // Modify the filename based on the criteria in the configuration file
        char* modified_filename = modifyFileName(filename, config);
        if (modified_filename == NULL) {
            unlockFile(fd);
            free(filename);
            continue;
        }

        // Check if the new filename is valid
        if (!validateFileName(modified_filename)) {
            fprintf(stderr, "Invalid modified filename: %s\n", modified_filename);
            unlockFile(fd);
            free(modified_filename);
            free(filename);
            continue;
        }

        // Rename the file to the new modified name
        if (rename(filename, modified_filename) == -1) {
            perror("Error renaming file");
            unlockFile(fd);
            free(modified_filename);
            free(filename);
            continue;
        }

        // Unlock the file after modification
        unlockFile(fd);

        // Free memory allocated for the filename and modified filename
        free(modified_filename);
        free(filename);
    }
}

// Define a function to handle potential errors during directory traversal
void handleDirectoryError(const char* directory) {
    perror("Error opening directory");
    fprintf(stderr, "Skipping directory: %s\n", directory);
}

// Define the main function
int main(int argc, char** argv) {
    // Check if there are enough arguments provided
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <directory> <config_file>\n", argv[0]);
        return 1;
    }

    // Load the configuration file
    FILE* config = fopen(argv[2], "r");
    if (config == NULL) {
        perror("Error opening configuration file");
        return 1;
    }

    // Read the number of supported extensions from the configuration file
    size_t num_extensions = 0;
    fscanf(config, "%lu", &num_extensions);

    // Create an array to store the supported extensions
    char* file_types[num_extensions];
    for (size_t i = 0; i < num_extensions; i++) {
        fscanf(config, "%s", file_types[i]);
    }

    // Close the configuration file
    fclose(config);

    // Create a new configuration struct and fill it with the supported extensions
    config_t config = { .file_types = file_types };

    // Traverse through all the files in the directory and modify them based on the criteria in the configuration file
    processDirectory(argv[1], &config);
}
