import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class FileContentProcessor {
    private String inputFilePath;
    private String outputFilePath;
    private int bufferSize = 4096; // default buffer size
    private boolean isCaseSensitive;
    private boolean isPunctuationRemoved;
    private boolean isSpacesRemoved;
    private List<String> customTransformations;

    public FileContentProcessor(String inputFilePath, String outputFilePath) {
        this.inputFilePath = inputFilePath;
        this.outputFilePath = outputFilePath;
    }

    public void processFile() throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(inputFilePath));
        BufferedWriter writer = new BufferedWriter(new FileWriter(outputFilePath));
        String line;
        while ((line = reader.readLine()) != null) {
            String processedLine = transformLine(line);
            writer.write(processedLine + "\n");
        }
        reader.close();
        writer.close();
    }

    public String transformLine(String line) {
        if (isCaseSensitive) {
            return line;
        } else {
            return line.toLowerCase();
        }
        if (isPunctuationRemoved) {
            return line.replaceAll("\\p{Punct}", "");
        } else {
            return line;
        }
        if (isSpacesRemoved) {
            return line.replaceAll(" ", "");
        } else {
            return line;
        }
        for (String customTransformation : customTransformations) {
            line = customTransformation.apply(line);
        }
        return line;
    }

    public void seedTransformation(Function<String, String> transformation) {
        this.customTransformations.add(transformation);
    }

    @Override
    public String toString() {
        return "FileContentProcessor{" +
                "inputFilePath='" + inputFilePath + '\'' +
                ", outputFilePath='" + outputFilePath + '\'' +
                ", bufferSize=" + bufferSize +
                ", isCaseSensitive=" + isCaseSensitive +
                ", isPunctuationRemoved=" + isPunctuationRemoved +
                ", isSpacesRemoved=" + isSpacesRemoved +
                '}';
    }

    private static void initializeDefaultSettings() {
        // default settings for the class
    }
}
