// Function to insert a string after the first occurrence of another string in a forward list
void insertStringAfterMatch(forward_list<string>& fl, const string& matchStr, const string& insertStr) {
    // Find the first occurrence of the match string in the forward list
    auto it = find(fl.begin(), fl.end(), matchStr);

    // If the match string is found, insert the new string after it
    if (it != fl.end()) {
        fl.insert_after(it, insertStr);
    } else {
        // If the match string is not found, append the new string to the end of the list
        fl.push_back(insertStr);
    }
}
