import java.util.List;
import java.util.ArrayList;
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.net.URL;
import java.net.HttpURLConnection;
import javax.json.JsonObject;
import javax.json.JsonReader;
import javax.json.JsonWriter;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import redis.clients.jedis.JedisPool;
import redis.clients.jedis.JedisPoolConfig;
import redis.clients.jedis.ShardedJedisPool;
import java.util.logging.Logger;

public class WeaknessService {
    private static final Logger LOGGER = Logger.getLogger(WeaknessService.class.getName());

    // Configuration options
    public static final int MAX_THREADS = 50;
    public static final int MIN_THREADS = 10;
    public static final int THREAD_TIMEOUT = 60000;
    public static final String JEDIS_POOL_CONFIG_FILE = "jedisPoolConfig.json";

    // In-memory cache of Pokemon types and their weaknesses
    private Map<String, List<String>> pokemonWeaknessesMap = new HashMap<>();

    // Redis client connection pool
    private JedisPool jedisPool;

    public WeaknessService() {
        // Create a connection pool for the Redis client
        jedisPool = createJedisPool();
    }

    // Method to get the weaknesses of a Pokemon
    public List<String> getWeaknesses(String pokemonType) {
        // Check if the Pokemon type is in the cache
        if (pokemonWeaknessesMap.containsKey(pokemonType)) {
            return pokemonWeaknessesMap.get(pokemonType);
        }

        // If not, fetch it from the Redis cache or an external REST API
        List<String> weaknesses = getWeaknessesFromCache(pokemonType);
        if (weaknesses == null) {
            weaknesses = getWeaknessesFromAPI(pokemonType);
        }

        // Add the Pokemon type to the cache
        pokemonWeaknessesMap.put(pokemonType, weaknesses);

        return weaknesses;
    }

    // Method to fetch a list of weaknesses from the Redis cache or an external REST API
    private List<String> getWeaknessesFromCache(String pokemonType) {
        // Connect to the Redis client and retrieve the weaknesses for the Pokemon type
        try (JedisPool pool = createJedisPool()) {
            Jedis jedis = pool.getResource();
            String key = "pokemon:" + pokemonType;
            String json = jedis.hget(key, "weaknesses");
            if (json != null) {
                return JsonReader.parse(new StringReader(json)).asArray().toListOfStrings();
            } else {
                return null;
            }
        } catch (Exception e) {
            LOGGER.warning("Error fetching weaknesses from Redis cache: " + e);
            return null;
        }
    }

    // Method to fetch a list of weaknesses from an external REST API
    private List<String> getWeaknessesFromAPI(String pokemonType) {
        // Connect to the external REST API and retrieve the weaknesses for the Pokemon type
        try {
            URL url = new URL("https://pokeapi.co/api/v2/pokemon-type/" + pokemonType);
            HttpURLConnection conn = (HttpURLConnection)url.openConnection();
            conn.setRequestMethod("GET");
            conn.setConnectTimeout(THREAD_TIMEOUT);
            conn.connect();

            if (conn.getResponseCode() == 200) {
                Gson gson = new GsonBuilder().create();
                JsonObject jsonObject = gson.fromJson(new JsonReader(new InputStreamReader(conn.getInputStream())), JsonObject.class);
                List<String> weaknesses = JsonReader.parse(new StringReader(jsonObject.getString("weaknesses"))).asArray().toListOfStrings();
                return weaknesses;
            } else {
                LOGGER.warning("Error fetching weaknesses from external REST API: " + conn.getResponseCode());
                return null;
            }
        } catch (Exception e) {
            LOGGER.warning("Error fetching weaknesses from external REST API: " + e);
            return null;
        }
    }

    // Method to create a connection pool for the Redis client
    private JedisPool createJedisPool() throws Exception {
        // Load the configuration options from the JSON file
        InputStream is = WeaknessService.class.getResourceAsStream(JEDIS_POOL_CONFIG_FILE);
        if (is == null) {
            throw new FileNotFoundException("Could not find Redis pool configuration file: " + JEDIS_POOL_CONFIG_FILE);
        }

        JedisPoolConfig config = GsonBuilder.create().fromJson(new InputStreamReader(is), JedisPoolConfig.class);
        return new ShardedJedisPool(config);
    }

    // Method to shut down the Redis client connection pool
    public void shutdown() {
        jedisPool.close();
    }
}
