```c
#include <stdio.h>
#include <stdarg.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

#define LOG_ERROR 0
#define LOG_WARNING 1
#define LOG_INFO 2

// Define the maximum length of the log message
#define MAX_LOG_MESSAGE_LENGTH 4096

// Define the buffer size for logging
#define BUFFER_SIZE 4096

// Define the interval between buffer flushes in seconds
#define FLUSH_INTERVAL 5

// Lock to protect concurrent access to the log file
static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Log file handle
static FILE *log_file = NULL;

// Buffer for logging
static char log_buffer[BUFFER_SIZE];

// Current position in the buffer
static int buffer_position = 0;

// Flag to indicate if the buffer is full
static bool buffer_full = false;

// Current timestamp
static time_t current_timestamp;

// Open the log file in append mode, create it if it does not exist
static void open_log_file(void) {
    // Check if the log file already exists
    struct stat buf;
    int ret = stat("error.log", &buf);

    // If the file does not exist, create a new one
    if (ret == -1 || S_ISDIR(buf.st_mode)) {
        log_file = fopen("error.log", "a+");
    } else {
        log_file = fopen("error.log", "a+");
    }
}

// Close the log file and free resources
static void close_log_file(void) {
    // Check if the log file is open
    if (log_file != NULL) {
        // Close the file and free the buffer
        fclose(log_file);
        log_file = NULL;
    }
}

// Write a message to the log file, using snprintf for dynamic formatting
static void write_message(const char *level, const char *format, ...) {
    // Check if the log file is open
    if (log_file == NULL) {
        return;
    }

    // Get the current time as a string
    time(&current_timestamp);
    struct tm *time_info = localtime(&current_timestamp);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", time_info);

    // Build the log message using snprintf
    va_list args;
    va_start(args, format);
    vsnprintf(log_buffer + buffer_position, BUFFER_SIZE - buffer_position, format, args);
    buffer_position += strlen(log_buffer + buffer_position);

    // Add the log level and timestamp to the message
    sprintf(log_buffer + buffer_position, "%s %s\n", level, timestamp);
    buffer_position += strlen(level) + strlen(timestamp) + 2;

    // Check if the buffer is full
    if (buffer_position >= BUFFER_SIZE - 1) {
        flush_log_buffer();
    }
}

// Flush the log buffer to disk, locking concurrent access to the file
static void flush_log_buffer(void) {
    // Check if the log file is open
    if (log_file == NULL) {
        return;
    }

    // Lock the log file for writing
    pthread_mutex_lock(&log_lock);

    // Write the buffer to the log file and clear it
    fwrite(log_buffer, sizeof(char), buffer_position, log_file);
    buffer_position = 0;

    // Unlock the log file
    pthread_mutex_unlock(&log_lock);
}

// Log an error message with a given format and arguments
void logError(const char *format, ...) {
    // Write the log message using write_message
    va_list args;
    va_start(args, format);
    write_message("ERROR", format, args);
    va_end(args);

    // Flush the log buffer to disk if necessary
    flush_log_buffer();
}

// Log a warning message with a given format and arguments
void logWarning(const char *format, ...) {
    // Write the log message using write_message
    va_list args;
    va_start(args, format);
    write_message("WARNING", format, args);
    va_end(args);

    // Flush the log buffer to disk if necessary
    flush_log_buffer();
}

// Log an information message with a given format and arguments
void logInfo(const char *format, ...) {
    // Write the log message using write_message
    va_list args;
    va_start(args, format);
    write_message("INFO", format, args);
    va_end(args);

    // Flush the log buffer to disk if necessary
    flush_log_buffer();
}
```
