#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <errno.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdbool.h>
#include <ctype.h>
#include <assert.h>
#include <pthread.h>
#include <semaphore.h>
#include <syslog.h>
#include "logging_service.h"

/*
 * Constants
 */
#define MAX_COMMAND_LENGTH 4096
#define MAX_ENV_VARS 64
#define MAX_FILE_PATH 256
#define MAX_TIMEOUT 3600 /* in seconds */
#define TIMEOUT_UNIT 's'
#define DEFAULT_WAITING_INTERVAL 10
#define DEFAULT_MAX_RETRIES 3
#define DEFAULT_RETRY_INTERVAL 5
#define MIN_ARGUMENTS 2
#define MAX_ARGUMENTS 64
#define DEFAULT_ENVIRONMENT "/etc/environment"

/*
 * Data structures
 */
typedef struct {
    char* command;
    char** envp;
    int num_envp;
    char* stdout_file;
    char* stderr_file;
    long timeout;
    char timeout_unit;
    bool redirect_output;
    bool redirect_error;
    int waiting_interval;
    int max_retries;
    int retry_interval;
    pid_t child_pid;
} BackgroundCommand;

/*
 * Function prototypes
 */
void execute_background_command(BackgroundCommand* command);
int fork_and_exec(BackgroundCommand* command);
int handle_error(BackgroundCommand* command, int error_code);
bool is_allowed_command(char* command);
int setup_signal_handlers();
int cleanup_signal_handlers();
void log_error(BackgroundCommand* command, char* message);
void log_debug(BackgroundCommand* command, char* message);
void wait_for_child(BackgroundCommand* command);
void handle_timeout(BackgroundCommand* command);
bool check_command_args(int argc, char** argv);
void parse_environment_variables(char* envp[], int num_envp);
bool validate_file_path(char* file_path);
void redirect_output(BackgroundCommand* command);
void redirect_error(BackgroundCommand* command);
void handle_signal(int signal, siginfo_t* info, void* context);
void log_and_exit(BackgroundCommand* command, char* message);

/*
 * Implementation
 */

void execute_background_command(BackgroundCommand* command) {
    /* Validate input */
    if (!check_command_args(2, argv)) {
        handle_error(command, "Invalid number of arguments");
        return;
    }

    /* Setup signal handlers */
    setup_signal_handlers();

    /* Parse environment variables */
    parse_environment_variables(envp, num_envp);

    /* Fork and execute command in the background */
    int error_code = fork_and_exec(command);

    /* Cleanup signal handlers */
    cleanup_signal_handlers();

    /* Handle errors */
    if (error_code) {
        handle_error(command, "Failed to execute command in the background");
    }
}

int fork_and_exec(BackgroundCommand* command) {
    pid_t child_pid = 0;
    int error_code = 0;

    /* Fork a new process */
    child_pid = fork();
    if (child_pid == -1) {
        return errno;
    }

    /* If the parent process, wait for the child to terminate */
    if (child_pid == 0) {
        wait_for_child(command);
    } else {
        command->child_pid = child_pid;
    }

    return error_code;
}

int handle_error(BackgroundCommand* command, int error_code) {
    /* Log the error */
    log_error(command, "Failed to execute command in the background");

    /* Cleanup signal handlers */
    cleanup_signal_handlers();

    /* Exit with an error code */
    exit(EXIT_FAILURE);
}

bool is_allowed_command(char* command) {
    /* Check if the command contains any special characters that could be used for injection attacks */
    char* sanitized_command = strdup(command);
    char* token;
    int i = 0;
    while ((token = strsep(&sanitized_command, ";"))) {
        if (i == 0) {
            /* The first token is the command name */
            continue;
        } else {
            /* Check if the token contains any special characters that could be used for injection attacks */
            char* allowed_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-";
            int j = 0;
            while (allowed_chars[j]) {
                if (strchr(token, allowed_chars[j]) != NULL) {
                    free(sanitized_command);
                    return false;
                }
                j++;
            }
        }
    }
    free(sanitized_command);
    return true;
}

int setup_signal_handlers() {
    /* Setup signal handlers for SIGINT, SIGQUIT, and SIGTERM */
    struct sigaction sa;
    memset(&sa, 0, sizeof(struct sigaction));
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = handle_signal;
    if (sigaction(SIGINT, &sa, NULL) == -1 ||
        sigaction(SIGQUIT, &sa, NULL) == -1 ||
        sigaction(SIGTERM, &sa, NULL) == -1) {
            return errno;
    }
}

int cleanup_signal_handlers() {
    /* Cleanup signal handlers for SIGINT, SIGQUIT, and SIGTERM */
    struct sigaction sa;
    memset(&sa, 0, sizeof(struct sigaction));
    sa.sa_handler = SIG_DFL;
    if (sigaction(SIGINT, &sa, NULL) == -1 ||
        sigaction(SIGQUIT, &sa, NULL) == -1 ||
        sigaction(SIGTERM, &sa, NULL) == -1) {
            return errno;
    }
}

void log_error(BackgroundCommand* command, char* message) {
    /* Log the error and exit with an error code */
    log_debug(command, "Error: %s", message);
    exit(EXIT_FAILURE);
}

void log_debug(BackgroundCommand* command, char* message) {
    /* Log a debug message */
    printf("[%ld] Debug: %s\n", (long int) getpid(), message);
}

void wait_for_child(BackgroundCommand* command) {
    /* Wait for the child process to terminate */
    pid_t pid;
    int status;
    while ((pid = wait(&status)) > 0) {
        if (command->child_pid == pid) {
            /* Check if the child has terminated normally or with an error code */
            if (!WIFEXITED(status) || WEXITSTATUS(status) != EXIT_SUCCESS) {
                handle_error(command, "Failed to execute command in the background");
            }
        }
    }
}

void handle_timeout(BackgroundCommand* command) {
    /* Handle a timeout signal */
    log_debug(command, "Timeout occurred");
    /* Send SIGTERM to the child process */
    kill(command->child_pid, SIGTERM);
}

bool check_command_args(int argc, char** argv) {
    /* Check if there are enough arguments for the command */
    return (argc >= 2);
}

void parse_environment_variables(char* envp[], int num_envp) {
    /* Parse environment variables and add them to the command */
    int i = 0;
    while (i < num_envp) {
        if (strncmp(envp[i], "PATH=", strlen("PATH=")) == 0) {
            /* Add PATH to the command */
            add_env("PATH", envp[i] + strlen("PATH="));
        } else if (strncmp(envp[i], "LD_LIBRARY_PATH=", strlen("LD_LIBRARY_PATH=")) == 0) {
            /* Add LD_LIBRARY_PATH to the command */
            add_env("LD_LIBRARY_PATH", envp[i] + strlen("LD_LIBRARY_PATH="));
        } else if (strncmp(envp[i], "LD_PRELOAD=", strlen("LD_PRELOAD=")) == 0) {
            /* Add LD_PRELOAD to the command */
            add_env("LD_PRELOAD", envp[i] + strlen("LD_PRELOAD="));
        }
    }
}

bool validate_file_path(char* file_path) {
    /* Check if the file path is valid */
    return true;
}

void redirect_output(BackgroundCommand* command) {
    /* Redirect output to a log file */
    FILE* fp = fopen("log.txt", "w+");
    dup2(fileno(fp), STDOUT);
    dup2(fileno(fp), STDERR);
}

void redirect_error(BackgroundCommand* command) {
    /* Redirect error output to a log file */
    FILE* fp = fopen("log.txt", "w+");
    dup2(fileno(fp), STDERR);
}
