        if (response.getStatusLine().getStatusCode() != 200) {
            throw new RuntimeException("Failed to update resource: " + response.getStatusLine());
        }

        // Return updated resource along with version number
        JsonObject json = new JsonParser().parse(response.getEntity().getContent()).getAsJsonObject();
        return new Resource(json.get("id").getAsString(), json.get("version").getAsInt());
    } catch (IOException e) {
        throw new RuntimeException("Failed to update resource", e);
    }
}

public static void deleteResource(String id, String token) {
