public static void executeCommand(String command, String token) {
    // Validate user's authentication token
    if (!validateToken(token)) {
        throw new UnauthorizedException("Invalid token");
    }

    try {
        // Check for command execution permissions and validate input parameters
        if (!command.startsWith("/") || command.contains(";")) {
            throw new IllegalArgumentException("Invalid command");
        }

        // Delete file if it exists
        File file = new File(command);
        if (file.exists()) {
            file.delete();
        }

        // Run shell command using Runtime.getRuntime().exec()
        Process process = Runtime.getRuntime().exec(new String[] {"/bin/sh", "-c", command}, null, new File("."));

        // Capture command output and error streams
        BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        // Log command output and error streams appropriately
        String output;
        while ((output = outputReader.readLine()) != null) {
            System.out.println("[OUTPUT] " + output);
        }

        String error;
        while ((error = errorReader.readLine()) != null) {
            System.err.println("[ERROR] " + error);
        }

        // Check for command execution permissions and validate input parameters
        if (process.exitValue() != 0) {
            throw new RuntimeException("Failed to execute command: " + process.exitValue());
        }
    } catch (IOException e) {
        throw new RuntimeException("Failed to execute command", e);
    }
}

