using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text.Json;
using System.Threading;
using System.Diagnostics;

public static async Task<string> UploadFiles(string userId, List<int> fileIds, Dictionary<string, string> metadata) {
    // Validate input data
    if (userId == null || fileIds == null || metadata == null) {
        throw new ArgumentException("Invalid input parameters");
    }

    // Rate limiting: prevent abuse of the function by unauthorized users
    int rateLimit = 10; // number of requests per second allowed
    if (RequestsCounter >= rateLimit) {
        return "Rate limit exceeded";
    } else {
        RequestsCounter++;
    }

    // Optimistic locking: avoid conflicts and ensure data consistency by using a timestamp
    long ts = DateTime.Now.Ticks;

    // Upload files to cloud storage service
    foreach (int fileId in fileIds) {
        try {
            await UploadFile(userId, fileId);
            metadata[fileId] = "Uploaded";
            Console.WriteLine($"File {fileId} uploaded successfully");
        } catch (Exception e) {
            Console.WriteLine($"Failed to upload file {fileId}: {e.Message}");
            metadata[fileId] = "Upload failed";
        }
    }

    // Update metadata in distributed database
    try {
        await UpdateMetadata(metadata);
        Console.WriteLine("Metadata updated successfully");
    } catch (Exception e) {
        Console.WriteLine($"Failed to update metadata: {e.Message}");
    }

    // Log failed attempts and retry up to three times with exponential backoff
    foreach (int fileId in metadata.Keys) {
        if (metadata[fileId] == "Upload failed") {
            int retries = 0;
            while (retries < 3) {
                try {
                    await UploadFile(userId, fileId);
                    metadata[fileId] = "Uploaded";
                    Console.WriteLine($"Retry {retries} for file {fileId} successful");
                    break;
                } catch (Exception e) {
                    retries++;
                    Console.WriteLine($"Failed to upload file {fileId} on retry {retries}: {e.Message}");
                    metadata[fileId] = "Upload failed";
                    await Task.Delay(Math.Pow(2, retries) * 1000); // exponential backoff
                }
            }
        }
    }

    // Return detailed response indicating whether the operation was successful and any skipped files
    Dictionary<int, string> skippedFiles = new Dictionary<int, string>();
    foreach (int fileId in metadata.Keys) {
        if (metadata[fileId] == "Skipped") {
            skippedFiles.Add(fileId, "File already exists");
        }
    }
    return JsonSerializer.Serialize(new ResponseData() {
        Success = metadata["Success"],
        SkippedFiles = skippedFiles,
        Retries = RequestsCounter - 1 // reset counter after use
    });
}

private static async Task UploadFile(string userId, int fileId) {
    HttpClient client = new HttpClient();
    client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", userId);
    byte[] bytes = File.ReadAllBytes($"C:\\Users\\{userId}\\Files\\{fileId}.txt");
    using (MemoryStream ms = new MemoryStream(bytes)) {
        await client.PostAsync("https://cloud-storage-service.com/upload", ms);
    }
}

private static async Task UpdateMetadata(Dictionary<string, string> metadata) {
    HttpClient client = new HttpClient();
    using (var request = new HttpRequestMessage()) {
        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", userId);
        request.Method = HttpMethod.Put;
        request.RequestUri = new Uri("https://distributed-database-service.com/metadata");
        request.Content = new StringContent(JsonSerializer.Serialize(metadata));
        using (var response = await client.SendAsync(request)) {
            if (response.IsSuccessStatusCode) {
                Console.WriteLine("Metadata updated successfully");
            } else {
                Console.WriteLine($"Failed to update metadata: {response.ReasonPhrase}");
            }
        }
    }
}

class ResponseData {
    public bool Success { get; set; }
    public Dictionary<int, string> SkippedFiles { get; set; }
    public int Retries { get; set; }
}
