#include <string>
#include <forward_list>
#include <functional>
#include <unordered_map>

void insertAfter(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2) {
    // Use a hash map to quickly look up the first occurrence of str1 in the list
    std::unordered_map<std::string, int> map;
    for (int i = 0; i < list.size(); ++i) {
        const auto& elem = list[i];
        if (elem == str1) {
            map[str1] = i;
            break;
        }
    }

    // If the first string is not found in the list, insert it at the end
    if (map.find(str1) == map.end()) {
        list.push_back(str2);
        return;
    }

    // Insert the second string after the first occurrence of str1
    int index = map[str1] + 1;
    const auto& oldElem = list[index];
    list.insert(list.begin() + index, str2);
}
