private bool IsValidKeyAndIV(byte[] encryptionKey, byte[] IV) {
    if (encryptionKey.Length != 32 || IV.Length != 16) {
        return false;
    }

    foreach (byte keyByte in encryptionKey) {
        if (keyByte < 0x20 || keyByte > 0x7E) {
            return false;
        }
    }

    foreach (byte ivByte in IV) {
        if (ivByte < 0x20 || ivByte > 0x7E) {
            return false;
        }
    }

    return true;
}
