using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace OAuthUserAuthenticationService
{
    public class OAuthUserAuthenticationService
    {
        private readonly ILogger _logger;
        private readonly Dictionary<string, string> _keys;
        private readonly Dictionary<string, byte[]> _ivs;

        public OAuthUserAuthenticationService(ILogger logger)
        {
            _logger = logger;
            _keys = new Dictionary<string, string>();
            _ivs = new Dictionary<string, byte[]>();
        }

        // Add a key for encryption/decryption
        public void AddKey(string keyName, string keyValue)
        {
            if (_keys.ContainsKey(keyName))
                throw new ArgumentException($"Key with name {keyName} already exists.");

            _keys[keyName] = keyValue;
        }

        // Remove a key for encryption/decryption
        public void RemoveKey(string keyName)
        {
            if (!_keys.ContainsKey(keyName))
                throw new ArgumentException($"No such key with name {keyName}.");

            _keys.Remove(keyName);
        }

        // Encrypt a file using the specified key and IV
        public void EncryptFile(string inputPath, string outputPath, string keyName, byte[] iv)
        {
            if (!_keys.ContainsKey(keyName))
                throw new ArgumentException($"No such key with name {keyName}.");

            using (var fileStream = new FileStream(inputPath, FileMode.Open))
            using (var cryptStream = new AesGcmCryptor(_keys[keyName], iv))
            {
                _logger.LogInformation($"Encrypting file {inputPath} with key {keyName} and IV {BitConverter.ToString(iv)}.");
                var encryptedBytes = cryptStream.TransformFinalBlock(fileStream);
                using (var outputFile = new FileStream(outputPath, FileMode.Create))
                {
                    outputFile.Write(encryptedBytes, 0, encryptedBytes.Length);
                }
            }
        }

        // Decrypt a file using the specified key and IV
        public void DecryptFile(string inputPath, string outputPath, string keyName, byte[] iv)
        {
            if (!_keys.ContainsKey(keyName))
                throw new ArgumentException($"No such key with name {keyName}.");

            using (var fileStream = new FileStream(inputPath, FileMode.Open))
            using (var cryptStream = new AesGcmCryptor(_keys[keyName], iv))
            {
                _logger.LogInformation($"Decrypting file {inputPath} with key {keyName} and IV {BitConverter.ToString(iv)}.");
                var decryptedBytes = cryptStream.TransformFinalBlock(fileStream);
                using (var outputFile = new FileStream(outputPath, FileMode.Create))
                {
                    outputFile.Write(decryptedBytes, 0, decryptedBytes.Length);
                }
            }
        }

        // Add an IV for encryption/decryption
        public void AddIV(string keyName, byte[] iv)
        {
            if (_ivs.ContainsKey(keyName))
                throw new ArgumentException($"IV with name {keyName} already exists.");

            _ivs[keyName] = iv;
        }

        // Remove an IV for encryption/decryption
        public void RemoveIV(string keyName)
        {
            if (!_ivs.ContainsKey(keyName))
                throw new ArgumentException($"No such IV with name {keyName}.");

            _ivs.Remove(keyName);
        }

        // Verify the integrity of a decrypted file using the Authentication Tag provided by GCM
        public void VerifyFileIntegrity(string inputPath, string keyName)
        {
            if (!_keys.ContainsKey(keyName))
                throw new ArgumentException($"No such key with name {keyName}.");

            using (var fileStream = new FileStream(inputPath, FileMode.Open))
            using (var cryptStream = new AesGcmCryptor(_keys[keyName], iv: null))
            {
                var authenticationTag = cryptStream.ComputeAuthenticationTag();
                _logger.LogInformation($"Verifying file integrity of {inputPath} with key {keyName} and IV {BitConverter.ToString(iv)}.");
                if (!cryptStream.VerifyAuthenticationTag(authenticationTag))
                    throw new CryptographicException("The authentication tag does not match the expected value.");
            }
        }

        // Implement a mechanism to verify the integrity of the decrypted file using the Authentication Tag provided by GCM
        public void VerifyFileIntegrityAsync(string inputPath, string keyName)
        {
            if (!_keys.ContainsKey(keyName))
                throw new ArgumentException($"No such key with name {keyName}.");

            var fileStream = File.OpenRead(inputPath);
            var cryptStream = new AesGcmCryptor(_keys[keyName], iv: null);
            var authenticationTag = cryptStream.ComputeAuthenticationTag();
            _logger.LogInformation($"Verifying file integrity of {inputPath} with key {keyName} and IV {BitConverter.ToString(iv)}.");
            if (!cryptStream.VerifyAuthenticationTag(authenticationTag))
                throw new CryptographicException("The authentication tag does not match the expected value.");
        }
    }
}
