import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.apache.commons.lang3.tuple.Pair;
import com.cloud.storage.api.CloudStorageClient;
import com.cloud.storage.model.FileTransfer;

public class FileUploadManager {
  private static final int MAX_CONCURRENT_TRANSFERS = 1000;
  private static final long RETRY_BACKOFF_FACTOR = 500L; // 500 ms
  private static final long JITTER_RANGE = 200L; // 200 ms
  private static final int MONITORING_FREQUENCY = 10; // 10 seconds

  private CloudStorageClient cloudStorageClient;
  private ScheduledExecutorService scheduledExecutorService;
  private List<Pair<FileTransfer, Integer>> transferQueue;

  public FileUploadManager(CloudStorageClient cloudStorageClient) {
    this.cloudStorageClient = cloudStorageClient;
    this.scheduledExecutorService = Executors.newScheduledThreadPool(MAX_CONCURRENT_TRANSFERS);
    this.transferQueue = new ArrayList<>();
  }

  public void addTransfers(List<FileTransfer> fileTransfers) {
    for (FileTransfer transfer : fileTransfers) {
      transferQueue.add(Pair.of(transfer, 0));
    }
  }

  private void processTransfers() {
    while (!transferQueue.isEmpty()) {
      Pair<FileTransfer, Integer> currentTransfer = transferQueue.remove(0);
      FileTransfer transfer = currentTransfer.getKey();
      int retryCount = currentTransfer.getValue();

      try {
        cloudStorageClient.uploadFile(transfer.getFileContent(), transfer.getTransferId());
        transfer.setTransferStatus(FileTransferStatus.SUCCESS);
      } catch (CloudStorageException e) {
        if (retryCount >= MAX_RETRY_COUNT) {
          transfer.setTransferStatus(FileTransferStatus.FAILED);
        } else {
          long retryDelay = RETRY_BACKOFF_FACTOR * Math.pow(2, retryCount - 1) + (long)(Math.random() * JITTER_RANGE);
          scheduledExecutorService.schedule(() -> processTransfers(), retryDelay, TimeUnit.MILLISECONDS);
        }
      } finally {
        if (transfer.getTransferStatus() == FileTransferStatus.SUCCESS) {
          transfer.setEndTime(Instant.now());
          logTransferAttempt(transfer, retryCount);
        } else {
          transfer.setRetryCount(retryCount + 1);
        }
      }
    }
  }

  private void logTransferAttempt(FileTransfer transfer, int retryCount) {
    // TODO: implement logging of transfer attempts and failures using a centralized logging system
  }

  public void start() {
    scheduledExecutorService.scheduleAtFixedRate(() -> processTransfers(), 0, MONITORING_FREQUENCY, TimeUnit.SECONDS);
  }

  public void shutdown() {
    scheduledExecutorService.shutdown();
  }
}
