using System;
using System.Collections.Generic;
using System.Text;

namespace AdvancedRandomValueGenerator
{
    public class AdvancedRandomValueGenerator
    {
        // Private fields for minimum and maximum values, and a boolean flag to indicate the generation type (uniform, normal, or weighted)
        private float _minValue;
        private float _maxValue;
        private bool _isUniformGeneration = true;
        private bool _isNormalGeneration = false;
        private bool _isWeightedGeneration = false;

        // Constructor with default values if no arguments are provided
        public AdvancedRandomValueGenerator() : this(0f, 1f, true) { }

        // Constructor with specified minimum and maximum values, and generation type (uniform, normal, or weighted)
        public AdvancedRandomValueGenerator(float minValue, float maxValue, bool isUniformGeneration = true, bool isNormalGeneration = false, bool isWeightedGeneration = false)
        {
            _minValue = minValue;
            _maxValue = maxValue;
            _isUniformGeneration = isUniformGeneration;
            _isNormalGeneration = isNormalGeneration;
            _isWeightedGeneration = isWeightedGeneration;
        }

        // Seed the random number generator with a given value to ensure reproducibility in testing and simulations
        public void Seed(int seed)
        {
            Random rnd = new Random(seed);
        }

        // Generate a random float value within the specified range, with support for exclusive and inclusive boundaries
        public float NextFloat(float minValue = 0f, float maxValue = 1f, bool isInclusive = true)
        {
            if (minValue >= maxValue)
                throw new ArgumentException("Minimum value must be less than maximum value");

            Random rnd = new Random();
            float range = Math.Abs(maxValue - minValue);
            float randomNumber = (float)(rnd.NextDouble() * range) + minValue;

            if (!isInclusive)
                randomNumber += 0.5f;

            return randomNumber;
        }

        // Generate a random integer value within the specified range, with support for exclusive and inclusive boundaries
        public int NextInt(int minValue = 0, int maxValue = 1, bool isInclusive = true)
        {
            if (minValue >= maxValue)
                throw new ArgumentException("Minimum value must be less than maximum value");

            Random rnd = new Random();
            int range = Math.Abs(maxValue - minValue);
            int randomNumber = rnd.Next(range + 1);

            if (!isInclusive)
                randomNumber += 0.5f;

            return randomNumber;
        }

        // Generate a random double value within the specified range, with support for exclusive and inclusive boundaries
        public double NextDouble(double minValue = 0d, double maxValue = 1d, bool isInclusive = true)
        {
            if (minValue >= maxValue)
                throw new ArgumentException("Minimum value must be less than maximum value");

            Random rnd = new Random();
            double range = Math.Abs(maxValue - minValue);
            double randomNumber = rnd.NextDouble() * range;

            if (!isInclusive)
                randomNumber += 0.5f;

            return randomNumber;
        }

        // Generate a random value from a normal distribution centered around the specified range, with customizable mean and standard deviation
        public float NextNormal(float mean = 0f, float stdDev = 1f)
        {
            Random rnd = new Random();
            NormalDistribution dist = new NormalDistribution(mean, stdDev);
            return (float)dist.NextDouble();
        }

        // Apply a custom probability density function (PDF) for generating random values, allowing users to define their own distribution logic
        public float NextCustom(Func<float, float> pdf)
        {
            Random rnd = new Random();
            return (float)pdf((float)rnd.NextDouble());
        }

        // Overriding the ToString method to display the current range, generation type (uniform, normal, or weighted), and additional details like mean, standard deviation, and custom PDF for normal and custom distributions
        public override string ToString()
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine($"Range: {_minValue} - {_maxValue}");
            sb.AppendLine($"Generation Type: {(_isUniformGeneration ? "Uniform" : (_isNormalGeneration ? "Normal" : "Weighted"))}");
            sb.AppendLine($"Mean: {_mean}");
            sb.AppendLine($"Standard Deviation: {_stdDev}");
            sb.AppendLine($"Custom PDF: {(_customPDF == null ? "None" : _customPDF)}");
            return sb.ToString();
        }

        // Implementing caching to store and reuse pre-generated sequences of random numbers for performance optimization, especially when generating a large number of random values
        private static Dictionary<string, List<float>> _cache = new Dictionary<string, List<float>>();
        private float[] GenerateRandomSequence(int count)
        {
            string key = $"{count}-{_minValue}-{_maxValue}-{_mean}-{_stdDev}-{(_customPDF == null ? "None" : _customPDF)}";
            if (_cache.ContainsKey(key))
                return _cache[key];

            float[] sequence = new float[count];
            for (int i = 0; i < count; i++)
            {
                sequence[i] = NextFloat();
            }

            _cache.Add(key, sequence);
            return sequence;
        }

        // Handling different data types (float, int, double) seamlessly and ensuring integration with external systems that require random value generation
        public float NextFloat()
        {
            return isUniformGeneration ? GenerateRandomSequence(1)[0] : NextCustom(_customPDF);
        }

        // Ensuring that the cache can be cleared or refreshed as needed
        public void ClearCache()
        {
            _cache.Clear();
        }
    }
}
