const { createServer, Server } = require('ssh2');
const { Client } = require('@elastic/elasticsearch');
const sshConfig = {
  host: 'localhost',
  port: 22,
  user: 'root',
  password: 'password'
};
const esConfig = {
  host: 'localhost',
  port: 9200,
  auth: {
    username: 'elastic',
    password: 'changeme'
  }
};

class RemoteCommandRunner {
  constructor() {
    this.servers = [];
    this.sshClients = {};
    this.esClient = new Client(esConfig);
  }

  async executeCommand(config) {
    const { protocol, command, args, params, constraints } = config;
    let output = '';

    if (protocol === 'ssh') {
      const server = await this._getServer(constraints.server);
      const sshClient = await this._getSshClient(server);
      try {
        output = await sshClient.execCommand(`${command} ${args.join(' ')}`);
      } catch (err) {
        console.error(`Error executing command: ${err.message}`);
      } finally {
        this._putSshClient(server, sshClient);
      }
    } else if (protocol === 'elasticsearch') {
      try {
        const response = await this.esClient.search({
          index: constraints.index,
          body: {
            query: {
              bool: {
                must: [
                  { match_phrase: { command } },
                  { match_phrase: { args } }
                ]
              }
            }
          }
        });
        output = response.hits.hits[0]._source.output;
      } catch (err) {
        console.error(`Error executing command: ${err.message}`);
      }
    } else {
      throw new Error(`Unsupported protocol: ${protocol}`);
    }

    return output;
  }

  async _getServer(serverId) {
    let server = this.servers.find((s) => s.id === serverId);

    if (!server) {
      const inventory = await this._getInventory();
      const availableServers = inventory.filter((s) => !this.servers.includes(s));
      server = availableServers[0];
      this.servers.push(server);
    }

    return server;
  }

  async _getSshClient(server) {
    let sshClient = this.sshClients[server.id];

    if (!sshClient) {
      sshClient = createServer(server.host, server.port);
      this.sshClients[server.id] = sshClient;
    }

    return sshClient;
  }

  async _putSshClient(server, sshClient) {
    if (this.sshClients[server.id]) {
      await sshClient.close();
      delete this.sshClients[server.id];
    }
  }

  async _getInventory() {
    const inventory = [];

    // Add servers from AWS EC2 metadata
    try {
      const ec2Metadata = await fetch('http://169.254.169.254/latest/meta-data');
      const instances = await ec2Metadata.json();
      for (const instance of instances) {
        inventory.push({
          id: `${instance.publicIp}`,
          host: `${instance.publicIp}`,
          port: 22,
          user: 'root',
          password: 'password'
        });
      }
    } catch (err) {
      console.error(`Error fetching AWS EC2 metadata: ${err.message}`);
    }

    // Add servers from Kubernetes APIs
    try {
      const k8sApi = await fetch('https://kubernetes.default/api/v1/nodes');
      const nodes = await k8sApi.json();
      for (const node of nodes) {
        inventory.push({
          id: `${node.status.addresses[0].address}`,
          host: `${node.status.addresses[0].address}`,
          port: 22,
          user: 'root',
          password: 'password'
        });
      }
    } catch (err) {
      console.error(`Error fetching Kubernetes nodes: ${err.message}`);
    }

    // Add servers from custom configuration files
    try {
      const configFile = await fs.readFile('./servers.json');
      const config = JSON.parse(configFile);
      for (const server of config) {
        inventory.push({
          id: `${server.host}`,
          host: `${server.host}`,
          port: server.port,
          user: server.user,
          password: server.password
        });
      }
    } catch (err) {
      console.error(`Error reading servers configuration file: ${err.message}`);
    }

    return inventory;
  }
}

module.exports = RemoteCommandRunner;
```
This code defines a `RemoteCommandRunner` class that can execute remote shell commands across multiple servers using SSH and Elasticsearch protocols. The constructor initializes an empty server list, a map of open SSH clients, and an Elasticsearch client for querying the command output from Elasticsearch indices. The `executeCommand` method accepts a configuration object with the target server, protocol, authentication details, command parameters, and operational constraints, and returns the command output or an error description.

The `_getServer` method fetches a server from the inventory based on its ID, adds it to the server list if it's not already in the list, and returns the server object. The `_getSshClient` method creates a new SSH client for the given server or returns an existing one if it's already opened. The `_putSshClient` method closes the SSH client and removes it from the map of open clients.

The `_getInventory` method fetches servers from three sources: AWS EC2 metadata, Kubernetes APIs, and a custom configuration file. If any of these sources fail, the method logs an error message but continues to fetch other inventory sources to provide a complete inventory. The `module.exports` line exports the `RemoteCommandRunner` class for use in other modules.

Here is a possible C program that spawns multiple background processes to run a series of given commands concurrently, dynamically allocating resources based on available system memory, ensuring no more than 50% of the memory is used by the spawned processes at any time to prevent system instability:
