import os
import shutil

def batch_file_mover(source_paths, dest1_dir, dest2_dir):
    # Raise an exception if any of the source files do not exist
    for source_path in source_paths:
        if not os.path.exists(source_path):
            raise FileNotFoundError(f"Source file {source_path} does not exist")

    # Log all actions performed
    log = []

    # Optimize directory changes by grouping files with the same first character
    grouped_files = {}
    for source_path in source_paths:
        filename = os.path.basename(source_path)
        first_char = filename[0].lower()
        if first_char not in grouped_files:
            grouped_files[first_char] = []
        grouped_files[first_char].append(source_path)

    # Move files to the appropriate destination directory based on their first character
    for first_char, source_paths in grouped_files.items():
        if int(first_char) % 2 == 0:
            dest = dest1_dir
        else:
            dest = dest2_dir
        for source_path in source_paths:
            try:
                shutil.move(source_path, dest)
                log.append((source_path, dest))
            except (PermissionError, FileNotFoundError):
                log.append((source_path, "FAILED"))

    # Log all actions performed and handle potential permission errors or file movement failures gracefully
    print("File Movement Log:")
    for source_path, dest in log:
        if dest == "FAILED":
            print(f"{source_path}: FAILED")
        else:
            print(f"{source_path} moved to {dest}")
