#include <iostream>
#include <vector>
#include <memory>
#include <mutex>

// Define a struct to represent an octree node
struct OctreeNode {
  // Position of the center of the node in 3D space
  float position[3];

  // Size of the node in each dimension
  int size;

  // Number of objects contained within the node
  int numObjects;

  // Pointers to child nodes (if any)
  OctreeNode* children[8];
};

// Define a class to represent an octree
class Octree {
 public:
  // Constructor that initializes the octree with a specified number of leaf nodes and a minimum size for each node
  Octree(int numLeafNodes, int featureSize) {
    this->numLeafNodes = numLeafNodes;
    this->featureSize = featureSize;
    this->root = nullptr;
  }

  // Destructor that frees all memory allocated to the octree
  ~Octree() {
    deleteRoot();
  }

  // Adds a new object to the octree with its position and attributes
  void addObject(const float* position, const ObjectAttributes& attributes) {
    // Check if the object is within the boundaries of the octree
    if (!isInBoundaries(position)) return;

    // Add the object to the appropriate leaf node or create a new one if necessary
    addToLeafNode(position, attributes);
  }

  // Removes an object from the octree based on its position and attributes
  void removeObject(const float* position, const ObjectAttributes& attributes) {
    // Check if the object is within the boundaries of the octree
    if (!isInBoundaries(position)) return;

    // Remove the object from the appropriate leaf node or do nothing if it's not found
    removeFromLeafNode(position, attributes);
  }

  // Updates an object in the octree with its new position and attributes
  void updateObject(const float* oldPosition, const ObjectAttributes& oldAttributes, const float* newPosition, const ObjectAttributes& newAttributes) {
    // Check if the object is within the boundaries of the octree
    if (!isInBoundaries(oldPosition)) return;

    // Remove the object from the appropriate leaf node or do nothing if it's not found
    removeFromLeafNode(oldPosition, oldAttributes);

    // Add the updated object to the appropriate leaf node or create a new one if necessary
    addToLeafNode(newPosition, newAttributes);
  }

  // Finds the nearest neighbor of an object in the octree based on its position and attributes
  const Object* findNearestNeighbor(const float* position, const ObjectAttributes& attributes) {
    // Check if the object is within the boundaries of the octree
    if (!isInBoundaries(position)) return nullptr;

    // Find the nearest neighbor in the appropriate leaf node or return nullptr if it's not found
    return findNearestNeighborInLeafNode(position, attributes);
  }

  // Checks if an object is within the boundaries of the octree
  bool isInBoundaries(const float* position) {
    // Calculate the distance from the center of the octree to the given position
    double distance = std::sqrt((position[0] - root->position[0]) * (position[0] - root->position[0]) + 
                                (position[1] - root->position[1]) * (position[1] - root->position[1]) + 
                                (position[2] - root->position[2]) * (position[2] - root->position[2]));

    // Check if the distance is less than or equal to the radius of the octree
    return distance <= root->size;
  }

 private:
  // Root node of the octree
  OctreeNode* root;

  // Minimum size for each leaf node in the octree
  int featureSize;

  // Maximum number of leaf nodes in the octree
  int numLeafNodes;

  // Mutex to protect concurrent access to the octree
  std::mutex mutex;

  // Dynamically allocate memory for a new leaf node
  OctreeNode* allocateNode() {
    return new OctreeNode;
  }

  // Deallocate memory for an existing leaf node
  void deallocateNode(OctreeNode* node) {
    delete node;
  }

  // Add a new object to the appropriate leaf node or create a new one if necessary
  void addToLeafNode(const float* position, const ObjectAttributes& attributes) {
    std::lock_guard<std::mutex> lock(mutex);

    // Find the appropriate leaf node based on the given position
    OctreeNode* node = findLeafNode(position);

    // Create a new leaf node if necessary
    if (node == nullptr) {
      node = allocateNode();
      node->size = featureSize;

      // Add the new leaf node to the octree
      addLeafNode(node);
    }

    // Add the object to the appropriate leaf node
    node->numObjects++;
  }

  // Remove an object from the appropriate leaf node or do nothing if it's not found
  void removeFromLeafNode(const float* position, const ObjectAttributes& attributes) {
    std::lock_guard<std::mutex> lock(mutex);

    // Find the appropriate leaf node based on the given position
    OctreeNode* node = findLeafNode(position);

    // Do nothing if the object is not found in the leaf node
    if (node == nullptr) return;

    // Remove the object from the leaf node
    node->numObjects--;
  }

  // Find the nearest neighbor of an object in the appropriate leaf node or return nullptr if it's not found
  const Object* findNearestNeighborInLeafNode(const float* position, const ObjectAttributes& attributes) {
    std::lock_guard<std::mutex> lock(mutex);

    // Find the appropriate leaf node based on the given position
    OctreeNode* node = findLeafNode(position);

    // Do nothing if the object is not found in the leaf node
    if (node == nullptr) return nullptr;

    // Find the nearest neighbor of the object in the leaf node
    const Object* nearestNeighbor = findNearestNeighborInNode(position, attributes);

    // Return the nearest neighbor or nullptr if it's not found
    return nearestNeighbor;
  }

  // Find the appropriate leaf node based on the given position
  OctreeNode* findLeafNode(const float* position) {
    // Calculate the distance from the center of the octree to the given position
    double distance = std::sqrt((position[0] - root->position[0]) * (position[0] - root->position[0]) + 
                                (position[1] - root->position[1]) * (position[1] - root->position[1]) + 
                                (position[2] - root->position[2]) * (position[2] - root->position[2]));

    // Find the appropriate leaf node based on the distance
    OctreeNode* node = findLeafNodeRecursive(root, position, distance);

    // Return the found leaf node or nullptr if it's not found
    return node;
  }

  // Recursively find the appropriate leaf node based on the given position and distance from the center of the octree
  OctreeNode* findLeafNodeRecursive(OctreeNode* node, const float* position, double distance) {
    // Check if the given position is within the bounds of the current node
    bool isInBounds = (position[0] >= node->position[0] - node->size && position[0] <= node->position[0] + node->size && 
                       position[1] >= node->position[1] - node->size && position[1] <= node->position[1] + node->size && 
                       position[2] >= node->position[2] - node->size && position[2] <= node->position[2] + node->size);

    // If the given position is within the bounds of the current node, recursively search its child nodes
    if (isInBounds) {
      if (node->child1 != nullptr) {
        OctreeNode* foundNode = findLeafNodeRecursive(node->child1, position, distance);

        // Return the found leaf node or nullptr if it's not found
        return foundNode;
      } else if (node->child2 != nullptr) {
        OctreeNode* foundNode = findLeafNodeRecursive(node->child2, position, distance);

        // Return the found leaf node or nullptr if it's not found
        return foundNode;
      } else {
        // The given position is within the bounds of the current node and has no child nodes, so return this node
        return node;
      }
    } else {
      // The given position is outside the bounds of the current node, so recursively search its parent nodes
      if (node->parent != nullptr) {
        OctreeNode* foundNode = findLeafNodeRecursive(node->parent, position, distance);

        // Return the found leaf node or nullptr if it's not found
        return foundNode;
      } else {
        // The given position is outside all bounds of any nodes in the octree, so return nullptr
        return nullptr;
      }
    }
  }

  // Add a new leaf node to the octree
  void addLeafNode(OctreeNode* node) {
    // If the octree is empty, set the root node and return
    if (root == nullptr) {
      root = node;
      return;
    }

    // Find the appropriate leaf node based on the given position
    OctreeNode* parentNode = findLeafNode(node->position);

    // If no leaf node is found, set the root node and return
    if (parentNode == nullptr) {
      root = node;
      return;
    }

    // Recursively add the new leaf node to the octree
    addLeafNodeRecursive(parentNode, node);
  }

  // Recursively add a new leaf node to the octree
  void addLeafNodeRecursive(OctreeNode* node, OctreeNode* childNode) {
    // Check if the given node is within the bounds of the current node
    bool isInBounds = (childNode->position[0] >= node->position[0] - node->size && childNode->position[0] <= node->position[0] + node->size && 
                       childNode->position[1] >= node->position[1] - node->size && childNode->position[1] <= node->position[1] + node->size && 
                       childNode->position[2] >= node->position[2] - node->size && childNode->position[2] <= node->position[2] + node->size);

    // If the given node is within the bounds of the current node, add its child nodes recursively
    if (isInBounds) {
      if (node->child1 == nullptr) {
        node->child1 = childNode;
        return;
      } else if (node->child2 == nullptr) {
        node->child2 = childNode;
        return;
      } else {
        addLeafNodeRecursive(node->child1, childNode);
        addLeafNodeRecursive(node->child2, childNode);
      }
    // If the given node is outside the bounds of the current node, recursively search its parent nodes until it is found or a nullptr is reached
    } else {
      if (node->parent != nullptr) {
        addLeafNodeRecursive(node->parent, childNode);
      } else {
        root = childNode;
      }
    }
  }

  // Remove a leaf node from the octree
  void removeLeafNode(const float* position) {
    // Find the appropriate leaf node based on the given position
    OctreeNode* leafNode = findLeafNode(position);

    // If no leaf node is found, do nothing and return
    if (leafNode == nullptr) {
      return;
    }

    // Recursively remove the leaf node from the octree
    removeLeafNodeRecursive(leafNode);
  }

  // Recursively remove a leaf node from the octree
  void removeLeafNodeRecursive(OctreeNode* node) {
    // Check if the given node has child nodes and remove them recursively
    if (node->child1 != nullptr) {
      removeLeafNodeRecursive(node->child1);
    }

    if (node->child2 != nullptr) {
      removeLeafNodeRecursive(node->child2);
    }

    // If the given node has no child nodes, set its parent node's child reference to null and return
    if (node == root) {
      root = nullptr;
      return;
    } else if (node->parent != nullptr) {
      if (node->parent->child1 == node) {
        node->parent->child1 = nullptr;
      } else if (node->parent->child2 == node) {
        node->parent->child2 = nullptr;
      }

      return;
    }
  }
};
