    void wait() {
        if (nextIteration <= std::chrono::system_clock::now()) {
            nextIteration = std::chrono::system_clock::now() + std::chrono::milliseconds(delayMs);
        } else {
            auto timeToWait = nextIteration - std::chrono::system_clock::now();
            std::this_thread::sleep_for(timeToWait);
        }
    }
};

class CrcManager : public RateLimiter {
private:
    // ... other members ...
    RateLimiter& rateLimiter;
public:
    explicit CrcManager(RateLimiter& rateLimiter) : rateLimiter(rateLimiter) {}

    void processPdus() {
        while (!isShutdown) {
            std::optional<CrcIndication> pdu;
            {
                std::unique_lock<std::mutex> lock(pduMutex);
                if (pdus.empty()) {
                    threadCondVar.wait(lock);
                } else {
