import java.util.*;
import java.lang.Math;

public class DisjointPairs {
    // Union-Find data structure with support for path compression and union by rank
    private static class UF {
        private int[] id;  // array to store node ids (parent pointers)
        private int[] size; // array to store tree sizes
        private int count; // number of elements in the forest

        public UF(int n) {
            id = new int[n];
            size = new int[n];
            count = n;
            for (int i = 0; i < n; i++) {
                id[i] = i;
                size[i] = 1;
            }
        }

        public void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);

            if (rootP == rootQ) return;

            // update tree sizes and parent pointers
            if (size[rootP] < size[rootQ]) {
                id[rootP] = rootQ;
                size[rootQ] += size[rootP];
            } else {
                id[rootQ] = rootP;
                size[rootP] += size[rootQ];
            }

            count--;
        }

        public int find(int p) {
            while (p != id[p]) {
                id[p] = id[id[p]]; // path compression
                p = id[p];
            }
            return p;
        }
    }

    private static int disjointPairs(int[] arr) {
        UF uf = new UF(arr.length);

        for (int i = 0; i < arr.length - 1; i++) {
            // check if the two elements are disjoint using Union-Find
            int rootP = uf.find(i);
            int rootQ = uf.find(i + 1);

            if (rootP == rootQ) continue;

            uf.union(i, i + 1);
        }

        return uf.count;
    }

