#include <forward_list>
#include <string>
#include <algorithm>
#include <cctype>

void insertStringAfterMatch(std::forward_list<std::string>& list, const std::string& match, const std::string& toInsert) {
    // Find the first occurrence of `match` in the list
    auto it = std::find_if(list.begin(), list.end(), [&](const std::string& str) {
        return std::equal(str.begin(), str.end(), match.begin(), [](char a, char b) { return std::tolower(a) == std::tolower(b); });
    });

    // If the `match` is not found in the list, insert at the end of the list
    if (it == list.end()) {
        list.push_back(toInsert);
    } else {
        // Insert `toInsert` after the first occurrence of `match`
        list.insert_after(it, toInsert);
    }
