using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Text;
using System.Threading.Tasks;

public static void SendDataToDatabase(byte[] data, string connectionString, string sqlQuery) {
    // Create a new SqlConnection object using the specified connection string
    using (SqlConnection conn = new SqlConnection(connectionString)) {
        try {
            // Connect to the database and execute the SQL query with the provided data
            conn.Open();
            using (SqlCommand cmd = new SqlCommand(sqlQuery, conn)) {
                cmd.Parameters.AddWithValue("@data", data);
                using (var reader = await cmd.ExecuteReaderAsync()) {
                    // Read the result of the query and return it as a DataTableReader object
                    var table = new DataTable();
                    table.Load(reader);
                    return new DataTableReader(table);
                }
            }
        } catch (SqlException e) {
            Console.WriteLine("Error connecting to the database: " + e.Message);
            throw;
        } finally {
            conn.Close();
        }
    }
}
