const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const request = require('request');
const mongoose = require('mongoose');
const OpenWeatherMapAPI = 'https://api.openweathermap.org/data/2.5/';
const HistoricalWeatherAPI = 'https://historicalweatherapi.com/api/';
const rateLimiter = new RateLimit({ windowMs: 1000, max: 10 });

mongoose.connect('mongodb://localhost/weather_db', { useNewUrlParser: true });

app.use(bodyParser.json());
app.use(rateLimiter);

const WeatherSchema = new mongoose.Schema({
  city: String,
  coordinates: [Number],
  current_weather: {},
  historical_weather: [{}]
});

const WeatherModel = mongoose.model('Weather', WeatherSchema);

app.post('/weather/current', (req, res) => {
  const cities = req.body;
  const promises = [];
  for (let i = 0; i < cities.length; i++) {
    const city = cities[i];
    const promise = request(OpenWeatherMapAPI + 'weather?q=' + city.city + ',&appid=YOUR_OPENWEATHERMAP_API_KEY').then((response) => {
      return JSON.parse(response);
    }).catch((error) => {
      console.log('Error fetching current weather data for', city.city, ':', error);
    });
    promises.push(promise);
  }
  Promise.all(promises).then((results) => {
    const response = {};
    results.forEach((result) => {
      if (result && result.cod === 200) {
        response[result.city] = result;
      }
    });
    res.json(response);
  }).catch((error) => {
    console.log('Error handling current weather requests', error);
    res.status(500).send('Error fetching current weather data');
  });
});

app.post('/weather/historical', (req, res) => {
  const cities = req.body;
  const promises = [];
  for (let i = 0; i < cities.length; i++) {
    const city = cities[i];
    const promise = request(HistoricalWeatherAPI + 'weather?q=' + city.city + ',&appid=YOUR_HISTORICALWEATHER_API_KEY').then((response) => {
      return JSON.parse(response);
    }).catch((error) => {
      console.log('Error fetching historical weather data for', city.city, ':', error);
    });
    promises.push(promise);
  }
  Promise.all(promises).then((results) => {
    const response = {};
    results.forEach((result) => {
      if (result && result.cod === 200) {
        response[result.city] = result;
      }
    });
    res.json(response);
  }).catch((error) => {
    console.log('Error handling historical weather requests', error);
    res.status(500).send('Error fetching historical weather data');
  });
});

app.get('/weather/forecast', (req, res) => {
  const city = req.query.city;
  const promise = request(OpenWeatherMapAPI + 'forecast?q=' + city + ',&appid=YOUR_OPENWEATHERMAP_API_KEY').then((response) => {
    return JSON.parse(response);
  }).catch((error) => {
    console.log('Error fetching forecast for', city, ':', error);
  });
  promise.then((result) => {
    if (result && result.cod === 200) {
      res.json(result);
    } else {
      console.log('Error handling forecast request for', city);
      res.status(500).send('Error fetching forecast data');
    }
  });
});

app.get('/weather/custom/:city/:interval', (req, res) => {
  const city = req.params.city;
  const interval = req.params.interval;
  const promise = request(HistoricalWeatherAPI + 'weather?q=' + city + ',&appid=YOUR_HISTORICALWEATHER_API_KEY').then((response) => {
    return JSON.parse(response);
  }).catch((error) => {
    console.log('Error fetching custom weather data for', city, ':', error);
  });
  promise.then((result) => {
    if (result && result.cod === 200) {
      const historicalData = result.data;
      const dataAggregation = {};
      historicalData.forEach((dataPoint) => {
        if (dataPoint.date === interval) {
          dataAggregation[dataPoint.city] = dataPoint.weather;
        }
      });
      res.json(dataAggregation);
    } else {
      console.log('Error handling custom weather request for', city, ':', error);
      res.status(500).send('Error fetching custom weather data');
    }
  });
});

app.get('/weather/cache/:city', (req, res) => {
  const city = req.params.city;
  WeatherModel.findOne({ city: city }, (err, result) => {
    if (err) {
      console.log('Error fetching weather data from cache for', city);
      res.status(500).send('Error fetching weather data');
    } else {
      if (result && result.data) {
        const data = result.data;
        res.json(data);
      } else {
        console.log('No data found for', city, 'in cache');
        res.status(404).send('No weather data found');
      }
    }
  });
});

app.post('/weather/cache/:city', (req, res) => {
  const city = req.params.city;
  const currentTime = new Date().getTime();
  const data = req.body;
  if (data && data.city === city) {
    const newData = { city: city, data: data };
    WeatherModel.create(newData, (err) => {
      if (err) {
        console.log('Error caching weather data for', city);
        res.status(500).send('Error caching weather data');
      } else {
        console.log('Cached weather data for', city);
        res.json({ status: 'success' });
      }
    });
  } else {
    console.log('Invalid request to cache weather data for', city);
    res.status(400).send('Invalid request');
  }
});

app.listen(3000, () => {
  console.log('Server started on port 3000');
});
