#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

// Define the default file type if none is specified in the filename
#define DEFAULT_FILE_TYPE "jpg"

// Define the maximum length of the filename, including extension
#define FILENAME_MAX_LENGTH 255

// Define the format for the numeric identifier and timestamp
#define NUMERIC_IDENTIFIER_FORMAT "%06d-%02d-%02dT%02d:%02d:%02d"
#define TIMESTAMP_FORMAT "YYYY-MM-DDThh:mm:ss"

// Define the linked list node structure for storing modified filenames
typedef struct Node {
    char *filename;
    struct Node *next;
} Node;

// Define the function to optimize renameFileWithDigits
char *optimizedRenameFileWithDigits(const char *filename, int dry_run) {
    // Check for invalid input
    if (filename == NULL || strlen(filename) == 0) {
        fprintf(stderr, "Error: Invalid filename\n");
        return NULL;
    }

    // Get the original file extension and append the default extension if necessary
    const char *ext = getFileExtension(filename);
    if (ext == NULL) {
        ext = DEFAULT_FILE_TYPE;
    }
    char *new_filename = malloc(sizeof(char) * (strlen(filename) + strlen(ext) + 1));
    strcpy(new_filename, filename);
    if (strcmp(ext, "") != 0) {
        strcat(new_filename, ".");
        strcat(new_filename, ext);
    }

    // Count the number of digits in the filename and pad with zeros as necessary
    int num_digits = getNumDigits(new_filename);
    if (num_digits < 5) {
        char *tmp_filename = malloc(sizeof(char) * (strlen(new_filename) + 5));
        strcpy(tmp_filename, new_filename);
        while (num_digits < 5) {
            strcat(tmp_filename, "0");
            num_digits++;
        }
        free(new_filename);
        new_filename = tmp_filename;
    }

    // Append a unique numeric identifier and file type to the modified filename
    const char *file_type = getFileType(ext);
    int len = strlen(new_filename) + 14 + strlen(file_type);
    char *unique_filename = malloc(sizeof(char) * len);
    sprintf(unique_filename, "%s-%06d-%s", new_filename, getUniqueIdentifier(), file_type);

    // Check for potential conflicts with existing files in the directory
    struct stat buf;
    if (stat(unique_filename, &buf) == 0) {
        char *tmp_filename = malloc(sizeof(char) * len + 19);
        strcpy(tmp_filename, unique_filename);
        time_t timestamp = time(NULL);
        struct tm *timeinfo = localtime(&timestamp);
        sprintf(tmp_filename + strlen(unique_filename), "-" NUMERIC_IDENTIFIER_FORMAT, timeinfo->tm_year+1900, timeinfo->tm_mon+1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
        free(unique_filename);
        unique_filename = tmp_filename;
    }

    // Print the new filename to the console if in dry run mode
    if (dry_run) {
        printf("%s\n", unique_filename);
        return NULL;
    }

    // Rename the file and add it to the linked list of modified filenames
    int ret = rename(new_filename, unique_filename);
    if (ret != 0) {
        perror("Error renaming file");
        free(unique_filename);
        return NULL;
    }
    Node *node = malloc(sizeof(Node));
    node->filename = strdup(unique_filename);
    node->next = head;
    head = node;

    // Free the memory allocated for the temporary filenames
    free(new_filename);
    free(unique_filename);
    return unique_filename;
}

// Get the file extension from a filename, including the period (.)
const char *getFileExtension(const char *filename) {
    const char *ext = strrchr(filename, '.');
    if (ext != NULL && strlen(ext) > 0) {
        return ext + 1;
    } else {
        return NULL;
    }
}

// Get the number of digits in a filename excluding the extension
int getNumDigits(const char *filename) {
    int count = 0;
    const char *ext = strrchr(filename, '.');
    if (ext != NULL && strlen(ext) > 0) {
        filename = ext + 1;
    }
    for (int i = 0; filename[i] != '\0'; i++) {
        if (isdigit(filename[i])) {
            count++;
        }
    }
    return count;
}

// Get the unique numeric identifier
int getUniqueIdentifier() {
    return rand();
}

// Get the file type from a filename, based on the first character of the extension (if present)
const char *getFileType(const char *ext) {
    if (strcmp(ext, "jpg") == 0 || strcmp(ext, "jpeg") == 0) {
        return "jpg";
    } else if (strcmp(ext, "png") == 0) {
        return "png";
    } else if (strcmp(ext, "gif") == 0) {
        return "gif";
    } else {
        return DEFAULT_FILE_TYPE;
    }
}

// Linked list of modified filenames for logging purposes
Node *head = NULL;
```

