        int requestsPerHour = 500;
        String ipAddress = request.getRemoteAddr();
        if (ipAddress != null && !rateLimiter.isRateLimitExceeded(ipAddress, requestsPerHour)) {
            return new ResponseEntity<>("Rate limit exceeded", HttpStatus.TOO_MANY_REQUESTS);
        }

        // Hash the string using SHA-256
        String hash = null;
        try {
            hash = sha256Hash(string);
        } catch (NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "Error hashing string: " + e.getMessage());
            return new ResponseEntity<>("Internal server error", HttpStatus.INTERNAL_SERVER_ERROR);
