        // Store and retrieve hashed result from cache
        Jedis jedis = null;
        try {
            jedis = new Jedis(REDIS_HOST, REDIS_PORT);
            String cachedHash = jedis.get(hash);
            if (cachedHash != null) {
                logger.log(Level.INFO, "Returning cached hash for string: " + string);
                return new ResponseEntity<>(cachedHash, HttpStatus.OK);
            }
        } catch (JedisException e) {
            logger.log(Level.SEVERE, "Error connecting to Redis cache: " + e.getMessage());
        } finally {
            if (jedis != null) {
                jedis.close();
            }
        }

        // Add hashed result to cache with TTL of 30 minutes
        jedis = new Jedis(REDIS_HOST, REDIS_PORT);
        try {
            jedis.setex(hash, CACHE_TTL, string);
            logger.log(Level.INFO, "Added hash for string to cache: " + string);
        } catch (JedisException e) {
            logger.log(Level.SEVERE, "Error adding hash to Redis cache: " + e.getMessage());
        } finally {
            if (jedis != null) {
                jedis.close();
            }
        }

        return new ResponseEntity<>(hash, HttpStatus.OK);
    }

    @PostMapping("/hash")
    public ResponseEntity<String> hashString(@RequestParam("string") String string) {
        // Validate input parameters
        if (string == null || string.isEmpty()) {
            return new ResponseEntity<>("Invalid input parameter", HttpStatus.BAD_REQUEST);
        }

        // Log request with timestamp and IP address
        logger.log(Level.INFO, "Request received for hashing string: " + string);

        // Handle rate limiting for unique IP addresses
        int requestsPerHour = 500;
        String ipAddress = request.getRemoteAddr();
        if (ipAddress != null && !rateLimiter.isRateLimitExceeded(ipAddress, requestsPerHour)) {
            return new ResponseEntity<>("Rate limit exceeded", HttpStatus.TOO_MANY_REQUESTS);
        }

        // Hash the string using SHA-256
        String hash = null;
        try {
            hash = sha256Hash(string);
        } catch (NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "Error hashing string: " + e.getMessage());
            return new ResponseEntity<>("Internal server error", HttpStatus.INTERNAL_SERVER_ERROR);
        }

        // Store and retrieve hashed result from cache
        Jedis jedis = null;
        try {
            jedis = new Jedis(REDIS_HOST, REDIS_PORT);
            String cachedHash = jedis.get(hash);
            if (cachedHash != null) {
                logger.log(Level.INFO, "Returning cached hash for string: " + string);
                return new ResponseEntity<>(cachedHash, HttpStatus.OK);
            }
        } catch (JedisException e) {
            logger.log(Level.SEVERE, "Error connecting to Redis cache: " + e.getMessage());
        } finally {
            if (jedis != null) {
                jedis.close();
            }
        }

        // Add hashed result to cache with TTL of 30 minutes
        jedis = new Jedis(REDIS_HOST, REDIS_PORT);
        try {
            jedis.setex(hash, CACHE_TTL, string);
            logger.log(Level.INFO, "Added hash for string to cache: " + string);
        } catch (JedisException e) {
            logger.log(Level.SEVERE, "Error adding hash to Redis cache: " + e.getMessage());
        } finally {
            if (jedis != null) {
                jedis.close();
            }
        }

        return new ResponseEntity<>(hash, HttpStatus.OK);
    }

    private String sha256Hash(String string) throws NoSuchAlgorithmException {
        // Use SHA-256 to hash the input string
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hashedBytes = md.digest(string.getBytes());
        return Base64.encodeBase64String(hashedBytes);
    }

    private void startCacheRefreshThread() {
        // Start a thread that periodically refreshes the cache with new data
        Thread cacheRefreshThread = new Thread(() -> {
            while (true) {
                try {
                    // Refresh the cache with new data
                    logger.log(Level.INFO, "Refreshing cache...");
                    Jedis jedis = new Jedis(REDIS_HOST);
                    Set<String> keys = jedis.keys("*");
                    for (String key : keys) {
                        String value = jedis.get(key);
                        logger.log(Level.INFO, "Refreshed cache with new data: key=" + key + ", value=" + value);
                    }
                } catch (JedisException e) {
                    logger.log(Level.SEVERE, "Error refreshing cache: " + e.getMessage());
                } finally {
                    try {
                        Thread.sleep(10000); // Refresh every 10 seconds
                    } catch (InterruptedException e) {
                        logger.log(Level.SEVERE, "Error refreshing cache: " + e.getMessage());
                    }
                }
            }
        });
        cacheRefreshThread.start();
    }
}
```

This code uses the `Jedis` class to connect to Redis and retrieve the value associated with a given key. It also uses the `MessageDigest` class to hash the input string using the SHA-256 algorithm. The hashed value is then returned as the output of the function.

The code also includes a thread that periodically refreshes the cache with new data by retrieving all keys and values from Redis and adding them to the cache. This ensures that the cache remains up-to-date with any changes made to the data in Redis.

In this example, the `startCacheRefreshThread` method is called to start a new thread that periodically refreshes the cache with new data. The `while` loop in the thread checks for any changes to the keys and values in Redis every 10 seconds using the `Jedis` class. If any changes are detected, they are added to the cache using the `set` method of the `Jedis` class.

Note that this code assumes that you have already set up a Redis server and have access to it through a connection string (e.g., `REDIS_HOST`). You will need to modify the code accordingly if you are using a different Redis configuration.

