        configFilePath_(configFilePath),
        profileNames_(profileNames),
        currentProfileIndex_(-1)
    {}

    void initialize() {
        // Load configuration from file
        ifstream configFile(configFilePath_);
        string line;
        while (getline(configFile, line)) {
            istringstream iss(line);
            string key, value;
            iss >> key >> value;
            if (key == "serviceEndpoints") {
                vector<ServiceEndpoint> serviceEndpoints;
                for (string endpoint : value.split(';')) {
                    ServiceEndpoint se = {endpoint};
                    serviceEndpoints.push_back(se);
                }
                setServiceEndpoints(serviceEndpoints);
            } else if (key == "allowedClientIPRanges") {
                vector<ClientIPRange> allowedClientIPRanges;
                for (string range : value.split(';')) {
                    ClientIPRange cip = {range};
                    allowedClientIPRanges.push_back(cip);
                }
                setAllowedClientIPRanges(allowedClientIPRanges);
            } else if (key == "rateLimitingParameters") {
                vector<RateLimitingParameter> rateLimitingParameters;
                for (string param : value.split(';')) {
                    RateLimitingParameter rlp = {param};
                    rateLimitingParameters.push_back(rlp);
                }
                setRateLimitingParameters(rateLimitingParameters);
            } else if (key == "retryPolicies") {
                vector<RetryPolicy> retryPolicies;
                for (string policy : value.split(';')) {
                    RetryPolicy rp = {policy};
                    retryPolicies.push_back(rp);
                }
                setRetryPolicies(retryPolicies);
            } else if (key == "tlsConfiguration") {
                TLSConfiguration tlsConfig;
                iss >> tlsConfig.certificateFilePath >> tlsConfig.privateKeyFilePath;
                setTLSConfiguration(tlsConfig);
            }
        }
    }

    void run() {
        // Start listening for incoming requests
        while (true) {
            // Read the next request from the network
            string request = readRequest();

            // Process the request and send a response back to the client
            string response = processRequest(request);
            writeResponse(response);
        }
    }

private:
    string configFilePath_;
    vector<string> profileNames_;
    int currentProfileIndex_;

    // Service endpoints and their associated configuration parameters
    unordered_map<string, ServiceEndpoint> serviceEndpoints_;
    unordered_map<string, ClientIPRange> allowedClientIPRanges_;
    unordered_map<string, RateLimitingParameter> rateLimitingParameters_;
    unordered_map<string, RetryPolicy> retryPolicies_;
    TLSConfiguration tlsConfig_;

    // Mutex for protecting concurrent access to the service endpoints and rate limiters
    mutex serviceEndpointMutex_;
    mutex rateLimiterMutex_;

    // Condition variable for notifying waiting threads when a new profile is selected
    condition_variable profileChangedCV_;

    // Functions for reading and writing requests and responses
    void readRequest(string& request) {
        // Read the next line from the network stream
        getline(cin, request);
    }

    void writeResponse(const string& response) {
        // Write the response to the network stream
        cout << response << endl;
    }

    // Functions for processing requests and sending responses
    string processRequest(const string& request) {
        // Parse the incoming request into a JSON object
        json requestJSON = parseRequest(request);

        // Extract the service endpoint, client IP address, and rate limiting parameters from the request
        string serviceEndpoint = getServiceEndpoint(requestJSON);
        string clientIPAddress = getClientIPAddress(requestJSON);
        RateLimitingParameter rateLimitingParameter = getRateLimitingParameter(requestJSON);

        // Check if the client IP address is allowed to access the service endpoint
