        if (!isAllowed) {
            return "403 Forbidden";
        }

        // Check if the rate limiting parameters are within limits
        bool isWithinLimits = checkRateLimitingParameters(rateLimitingParameter);
        if (!isWithinLimits) {
            return "429 Too Many Requests";
        }

        // Retrieve the service endpoint configuration and TLS certificate, if applicable
        ServiceEndpoint se = getServiceEndpointConfig(serviceEndpoint);
        TLSConfiguration tlsConfig;
        if (se.isAuthenticated) {
            tlsConfig = getTLSConfiguration();
        }

        // Send the request to the service endpoint and retrieve the response
        string response = sendRequest(requestJSON, se, clientIPAddress, rateLimitingParameter, tlsConfig);

        // Check if there were any errors or exceptions during the request
        bool isError = checkForErrorsOrExceptions(response);
        if (isError) {
            return "500 Internal Server Error";
        }

        // Return the response to the client
        return response;
    }

    // Functions for parsing and generating requests and responses
    json parseRequest(const string& request) {
