    }

    string generateResponse(const json& responseJSON) {
        // Generate the response from the JSON object
        return responseJSON.dump();
    }

    // Functions for retrieving and updating service endpoint configurations
    ServiceEndpoint getServiceEndpointConfig(const string& serviceEndpoint) {
        lock_guard<mutex> serviceEndpointLock(serviceEndpointMutex_);
        if (serviceEndpoints_.find(serviceEndpoint) == serviceEndpoints_.end()) {
            return ServiceEndpoint();
        } else {
            return serviceEndpoints_.at(serviceEndpoint);
        }
    }

    void updateServiceEndpointConfig(const string& serviceEndpoint, const json& configJSON) {
        lock_guard<mutex> serviceEndpointLock(serviceEndpointMutex_);
        serviceEndpoints_[serviceEndpoint] = parseServiceEndpointConfig(configJSON);
    }

    // Functions for retrieving and updating rate limiters
    RateLimitingParameter getRateLimitingParameter(const string& clientIPAddress) {
        lock_guard<mutex> rateLimiterLock(rateLimiterMutex_);
        if (allowedClientIPRanges_.find(clientIPAddress) == allowedClientIPRanges_.end()) {
            return RateLimitingParameter();
        } else {
            return allowedClientIPRanges_.at(clientIPAddress);
        }
    }

    void updateRateLimiter(const string& clientIPAddress, const json& configJSON) {
        lock_guard<mutex> rateLimiterLock(rateLimiterMutex_);
        allowedClientIPRanges_[clientIPAddress] = parseRateLimitingParameter(configJSON);
    }

    // Functions for retrieving and updating TLS configurations
    TLSConfiguration getTLSConfiguration() {
        lock_guard<mutex> tlsConfigLock(tlsConfigMutex_);
        return tlsConfig_;
    }

    void updateTLSConfiguration(const json& configJSON) {
        lock_guard<mutex> tlsConfigLock(tlsConfigMutex_);
        tlsConfig_ = parseTLSConfiguration(configJSON);
    }
};
