import java.util.Random;

public class ServiceLifecycleManager {
    private static final Random RANDOM = new Random();

    // Define the external messaging system's configuration details
    private static final String MESSAGING_SYSTEM_URL = "kafka://localhost:9092";
    private static final String TOPIC_NAME = "my-service-topic";
    private static final int MESSAGE_SIZE = 100;

    // Define the service's lifecycle behavior
    public static void main(String[] args) {
        boolean started = startService();
        if (started) {
            System.out.println("Service started successfully");
            Thread.sleep(RANDOM.nextInt(1000)); // Simulate a random delay before stopping the service
            stopService();
            System.out.println("Service stopped successfully");
        } else {
            System.err.println("Failed to start service");
        }
    }

    private static boolean startService() {
        try {
            // Connect to the external messaging system and publish a message on the topic
            MessagingSystemConnection connection = new MessagingSystemConnection(MESSAGING_SYSTEM_URL);
            Topic topic = connection.createTopic(TOPIC_NAME, MESSAGE_SIZE);
            Message message = new Message("Service started");
            topic.publish(message);

            // Start the service's main loop
            Service service = new Service();
            service.start();

            return true;
        } catch (MessagingSystemException | ServiceException e) {
            System.err.println("Failed to start service: " + e.getMessage());
            return false;
        }
    }

    private static void stopService() {
        try {
            // Disconnect from the external messaging system and publish a message on the topic indicating that the service has stopped
            MessagingSystemConnection connection = new MessagingSystemConnection(MESSAGING_SYSTEM_URL);
            Topic topic = connection.createTopic(TOPIC_NAME, MESSAGE_SIZE);
            Message message = new Message("Service stopped");
            topic.publish(message);
        } catch (MessagingSystemException e) {
            System.err.println("Failed to stop service: " + e.getMessage());
        }
    }
}
```
