const fs = require('fs');
const path = require('path');
const request = require('request');
const { createWriteStream } = require('stream');
const { promisify } = require('util');
const { writeFile, readFile } = fs.promises;

const streamApiUrl = 'https://api.example.com/v1/stream';
const dataPath = path.join(__dirname, 'data');
const dataFile = path.join(dataPath, 'sensor-data.json');

async function collectData() {
  try {
    const sensorData = await requestStream();
    await writeFile(dataFile, JSON.stringify(sensorData));
  } catch (error) {
    console.error('Error collecting data:', error);
  }
}

async function processData() {
  try {
    const sensorData = await readFile(dataFile, 'utf-8');
    const processedData = processSensorData(sensorData);
    await writeFile(dataPath, JSON.stringify(processedData));
  } catch (error) {
    console.error('Error processing data:', error);
  }
}

async function requestStream() {
  const stream = createWriteStream(streamApiUrl);
  return new Promise((resolve, reject) => {
    stream.on('data', data => resolve(data));
    stream.on('error', error => reject(error));
  });
}

function processSensorData(sensorData) {
  // process the sensor data here and return the processed data
  const processedData = [];
  for (const dataPoint of sensorData) {
    if (dataPoint.temperature > 30 || dataPoint.humidity < 60) {
      processedData.push(dataPoint);
    }
  }
  return processedData;
}
