// ConcurrentHashMap class for thread-safe insertion and removal of elements
public class ConcurrentHashMap<K, V> {
    private final Map<K, V> map = new HashMap<>();

    public void put(K key, V value) {
        // put the element in the map using a lock to ensure thread safety
        synchronized (map) {
            map.put(key, value);
        }
    }

    public void remove(K key) {
        // remove the element from the map using a lock to ensure thread safety
        synchronized (map) {
            map.remove(key);
        }
    }
}

