const RemoteExecutor = require('remote-executor');
const { SSH, HTTPS, FTP } = require('protocols');

class RemoteExecutor {
  constructor(config) {
    this.config = config;
    this.protocol = null;
    this.connection = null;
    this.auth = null;
    this.authorization = null;
    this.logger = null;
  }

  executeRemoteCommand(command, outputFormat) {
    const protocol = this.getProtocol();
    const connection = this.getConnection();
    const auth = this.getAuth();
    const authorization = this.getAuthorization();
    const logger = this.getLogger();

    try {
      const result = await protocol.executeCommand(connection, command);
      if (outputFormat) {
        return this.formatResult(result, outputFormat);
      } else {
        return result;
      }
    } catch (error) {
      logger.log('error', `Error executing remote command: ${error}`);
      throw error;
    } finally {
      connection.close();
    }
  }

  getProtocol() {
    if (!this.protocol || !this.connection) {
      this.connectToServer();
    }
    return this.protocol;
  }

  connectToServer() {
    const protocol = this.getConfig().protocol;
    const connection = this.getConfig().connection;
    switch (protocol) {
      case 'ssh':
        this.protocol = new SSH(connection);
        break;
      case 'https':
        this.protocol = new HTTPS(connection);
        break;
      case 'ftp':
        this.protocol = new FTP(connection);
        break;
    }
  }

  getConfig() {
    return this.config;
  }

  setConnection(connection) {
    this.connection = connection;
  }

  getConnection() {
    if (!this.connection) {
      this.connectToServer();
    }
    return this.connection;
  }

  setAuth(auth) {
    this.auth = auth;
  }

  getAuth() {
    if (this.auth) {
      return this.auth;
    } else {
      return null;
    }
  }

  setAuthorization(authorization) {
    this.authorization = authorization;
  }

  getAuthorization() {
    if (this.authorization) {
      return this.authorization;
    } else {
      return null;
    }
  }

  setLogger(logger) {
    this.logger = logger;
  }

  getLogger() {
    if (this.logger) {
      return this.logger;
    } else {
      return null;
    }
  }

  formatResult(result, outputFormat) {
    // Implement formatting logic based on the outputFormat parameter
    // For example, convert a JSON object to a plain text string
    return result;
  }
}

module.exports = RemoteExecutor;
