<?php

namespace App\Helpers;

use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Str;
use App\Models\PasswordStrengthVerification;

class SecureGenerateAndVerify
{
    private $characterSet;
    private $costFactor;
    private $passwordLength;

    public function __construct()
    {
        $this->characterSet = config('app.secure_random_string_characters');
        $this->costFactor = config('app.hashing_cost_factor');
        $this->passwordLength = config('app.password_length');
    }

    public function generateAndVerify($username, $password)
    {
        // Validate input
        if (!$username || !$password) {
            throw new \Exception("Invalid username or password");
        }

        // Generate a secure random string based on the character set and password length
        $randomString = Str::random($this->passwordLength, $this->characterSet);

        // Verify the strength of the generated string using an external API
        $apiResponse = PasswordStrengthVerification::verify($randomString);
        if (!$apiResponse) {
            throw new \Exception("Password strength verification failed");
        }

        // Hash the password using a secure hashing algorithm with a cost factor of at least 12
        $hashedPassword = Hash::make($password, [
            'cost' => $this->costFactor,
            'algorithm' => config('app.hashing_algorithm') ?? 'bcrypt',
        ]);

        // Return the generated string and hashed password alongside a securely hashed password
        return [$randomString, $hashedPassword];
    }
}
```
