package com.example.payment;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;

@Service
public class PaymentService {

    @Autowired
    private StripePaymentGateway stripePaymentGateway;

    @Autowired
    private PayPalPaymentGateway payPalPaymentGateway;

    @Autowired
    private BraintreePaymentGateway braintreePaymentGateway;

    @Autowired
    private RedisCache redisCache;

    @Autowired
    private KafkaQueue kafkaQueue;

    @Autowired
    private FraudDetectionService fraudDetectionService;

    public void initiateTransaction(String paymentGatewayId, String transactionData) {
        // Validate payment gateway identifier and handle invalid inputs gracefully
        if (!paymentGatewayId.equals("stripe") && !paymentGatewayId.equals("paypal") && !paymentGatewayId.equals("braintree")) {
            throw new IllegalArgumentException("Invalid payment gateway ID: " + paymentGatewayId);
        }

        // Initiate transaction with selected payment gateway
        PaymentGateway paymentGateway = getPaymentGateway(paymentGatewayId);
        String transactionId = paymentGateway.initiateTransaction(transactionData);

        // Add transaction to cache for batch processing
        redisCache.addToSet("transactions", transactionId);

        // Send transaction data and user account details to fraud detection service via HTTP request
        sendFraudDetectionRequest(transactionId, paymentGateway.getUserAccountDetails());
    }

    public void queryTransactionStatus(String paymentGatewayId, String transactionId) {
        // Validate payment gateway identifier and handle invalid inputs gracefully
        if (!paymentGatewayId.equals("stripe") && !paymentGatewayId.equals("paypal") && !paymentGatewayId.equals("braintree")) {
            throw new IllegalArgumentException("Invalid payment gateway ID: " + paymentGatewayId);
        }

        // Query transaction status with selected payment gateway
        PaymentGateway paymentGateway = getPaymentGateway(paymentGatewayId);
        TransactionStatus transactionStatus = paymentGateway.queryTransactionStatus(transactionId);

        // Update transaction status in cache
        redisCache.set("transactions", transactionStatus, transactionId);
    }

    public void manageUserAccount(String paymentGatewayId, String userAccountData) {
        // Validate payment gateway identifier and handle invalid inputs gracefully
        if (!paymentGatewayId.equals("stripe") && !paymentGatewayId.equals("paypal") && !paymentGatewayId.equals("braintree")) {
            throw new IllegalArgumentException("Invalid payment gateway ID: " + paymentGatewayId);
        }

        // Manage user account with selected payment gateway
        PaymentGateway paymentGateway = getPaymentGateway(paymentGatewayId);
        paymentGateway.manageUserAccount(userAccountData);
    }

    private PaymentGateway getPaymentGateway(String paymentGatewayId) {
        if (paymentGatewayId.equals("stripe")) {
            return stripePaymentGateway;
        } else if (paymentGatewayId.equals("paypal")) {
            return payPalPaymentGateway;
        } else if (paymentGatewayId.equals("braintree")) {
            return braintreePaymentGateway;
        }
        throw new IllegalArgumentException("Invalid payment gateway ID: " + paymentGatewayId);
    }

    private void sendFraudDetectionRequest(String transactionId, String userAccountDetails) {
        // Send HTTP request to fraud detection service with transaction data and user account details
        fraudDetectionService.sendRequest(transactionId, userAccountDetails);
    }

    public TransactionStatus getTransactionStatus(String paymentGatewayId, String transactionId) {
        // Validate payment gateway identifier and handle invalid inputs gracefully
        if (!paymentGatewayId.equals("stripe") && !paymentGatewayId.equals("paypal") && !paymentGatewayId.equals("braintree")) {
            throw new IllegalArgumentException("Invalid payment gateway ID: " + paymentGatewayId);
        }

        // Get transaction status from cache
        TransactionStatus transactionStatus = redisCache.get("transactions", transactionId);

        // If not found in cache, query transaction status with selected payment gateway
        if (transactionStatus == null) {
            PaymentGateway paymentGateway = getPaymentGateway(paymentGatewayId);
            transactionStatus = paymentGateway.queryTransactionStatus(transactionId);

            // Update transaction status in cache
            redisCache.set("transactions", transactionStatus, transactionId);
        }

        return transactionStatus;
    }

    public List<Transaction> getTransactions(String paymentGatewayId, String userAccountData) {
        // Validate payment gateway identifier and handle invalid inputs gracefully
        if (!paymentGatewayId.equals("stripe") && !paymentGatewayId.equals("paypal") && !paymentGatewayId.equals("braintree")) {
            throw new IllegalArgumentException("Invalid payment gateway ID: " + paymentGatewayId);
        }

        // Get transactions from cache
        List<Transaction> transactions = redisCache.getAll("transactions");

        // If not found in cache, query transactions with selected payment gateway
        if (transactions == null) {
            PaymentGateway paymentGateway = getPaymentGateway(paymentGatewayId);
            transactions = paymentGateway.queryTransactions(userAccountData);

            // Update transactions in cache
            redisCache.set("transactions", transactions, transactionId);
        }

        return transactions;
    }
}
