class Cache {
    private int size;
    private int evictionThreshold;
    private Map<Integer, Weather> weatherCache;
    private Map<Integer, Pokemon> pokemonCache;

    public Cache(int size, int evictionThreshold) {
        this.size = size;
        this.evictionThreshold = evictionThreshold;
        weatherCache = new HashMap<>();
        pokemonCache = new HashMap<>();
    }

    public void put(Integer id, Weather weather) {
        if (weatherCache.size() >= size || weatherCache.containsKey(id)) {
            // handle cache full or duplicate key error
        } else {
            weatherCache.put(id, weather);
        }
    }

    public void put(Integer id, Pokemon pokemon) {
        if (pokemonCache.size() >= size || pokemonCache.containsKey(id)) {
            // handle cache full or duplicate key error
        } else {
            pokemonCache.put(id, pokemon);
        }
    }

    public Weather get(Integer id) {
        return weatherCache.get(id);
    }

    public Pokemon get(Integer id) {
        return pokemonCache.get(id);
    }
}

