import os
import threading
from concurrent.futures import ThreadPoolExecutor

class ThumbnailModule:
    def __init__(self, api_urls):
        self.api_urls = api_urls
        self.executor = ThreadPoolExecutor(max_workers=5)

    def generate_thumbnail(self, image_path, output_dimensions, custom_options=None):
        # Check if the input image is a valid file
        if not os.path.isfile(image_path):
            raise ValueError("Invalid image path")

        # Get the image format and extension
        image_format = self._get_image_format(image_path)
        image_extension = "." + image_format

        # Set default output dimensions if none are provided
        if not output_dimensions:
            output_dimensions = (128, 128)

        # Create a temporary file for the thumbnail
        with NamedTemporaryFile(suffix=image_extension, delete=False) as temp_file:
            # Set the custom options if provided
            if custom_options:
                options = custom_options
            else:
                options = {}

            # Generate a thumbnail using the first available API
            for api_url in self.api_urls:
                try:
                    response = requests.post(api_url, files={"file": open(image_path, "rb")}, data=options)
                    if response.status_code == 200:
                        break
                except Exception as e:
                    # If an API fails, try the next one
                    continue

            # Check if a thumbnail was generated successfully
            if not response.ok:
                raise ValueError("Thumbnail generation failed")

            # Write the thumbnail to the temporary file
            temp_file.write(response.content)

        # Return the path of the generated thumbnail
        return temp_file.name

    def _get_image_format(self, image_path):
        # Get the image format and extension from the file name
        file_name = os.path.basename(image_path)
        file_extension = os.path.splitext(file_name)[1]

        if file_extension == ".jpg" or file_extension == ".jpeg":
            return "JPEG"
        elif file_extension == ".png":
            return "PNG"
        elif file_extension == ".gif":
            return "GIF"
        elif file_extension == ".svg":
            return "SVG"
        else:
            raise ValueError("Unsupported image format")

# Test the ThumbnailModule
if __name__ == "__main__":
    # Initialize the module with a list of API URLs
    module = ThumbnailModule(["https://api1.example.com", "https://api2.example.com"])

    # Generate a thumbnail for an image file
    output_dimensions = (64, 64)
    custom_options = {"quality": 75}
    thumbnail_path = module.generate_thumbnail("image.jpg", output_dimensions, custom_options)

    # Check if the generated thumbnail exists and is a valid image file
    if os.path.isfile(thumbnail_path):
        print("Generated thumbnail: " + thumbnail_path)
    else:
        print("Thumbnail generation failed")
