#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

// Structure to represent an NFAPI_CRC_INDICATION_PDU
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU;

// Dynamic array to store the list of NFAPI_CRC_INDICATION_PDU structures
NFAPI_CRC_INDICATION_PDU *list = NULL;
size_t list_size = 0;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new entry to the list
void add_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    new_entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry->RNTI = RNTI;
    new_entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    pthread_mutex_lock(&list_lock);
    list = realloc(list, (list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (list == NULL) {
        fprintf(stderr, "Error: out of memory\n");
        exit(EXIT_FAILURE);
    }

    list[list_size] = new_entry;
    list_size++;
    pthread_mutex_unlock(&list_lock);
}

// Function to update an existing entry in the list
void update_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    int index = find_index(RNTI);
    if (index == -1) {
        return;
    }

    pthread_mutex_lock(&list_lock);
    list[index]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list[index]->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    pthread_mutex_unlock(&list_lock);
}

// Function to remove an entry from the list based on RNTI
void remove_entry(int RNTI) {
    int index = find_index(RNTI);
    if (index == -1) {
        return;
    }

    pthread_mutex_lock(&list_lock);
    for (size_t i = index; i < list_size - 1; i++) {
        list[i] = list[i + 1];
    }
    list_size--;
    pthread_mutex_unlock(&list_lock);
}

// Function to find the index of an entry in the list based on RNTI
int find_index(int RNTI) {
    for (size_t i = 0; i < list_size; i++) {
        if (list[i]->RNTI == RNTI) {
            return i;
        }
    }

    return -1;
}

// Main function to parse an input file and print the number of lines
int main(int argc, char *argv[]) {
    // Check command line arguments
    if (argc < 3) {
        fprintf(stderr, "Usage: %s [--manpage] [-cs] -o output_file input_file\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Parse command line options
    int manpage = 0;
    int cs = 0;
    char *output_file = NULL;
    for (int i = 1; i < argc - 1; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            manpage = 1;
        } else if (strcmp(argv[i], "-cs") == 0) {
            cs = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[i + 1];
        }
    }

    // Open input file and check for errors
    FILE *input_file = fopen(argv[argc - 1], "r");
    if (input_file == NULL) {
        fprintf(stderr, "Error: failed to open input file\n");
        return EXIT_FAILURE;
    }

    // Initialize list and read input file line by line
    list = malloc(0);
    if (list == NULL) {
        fprintf(stderr, "Error: out of memory\n");
        return EXIT_FAILURE;
    }

    int line_count = 0;
    char line[1024];
    while (fgets(line, sizeof(line), input_file) != NULL) {
        // Parse the current line and add/update/remove entries as needed
        parse_line(line);
        line_count++;
    }

    // Print the number of lines read from the input file
    printf("Read %d lines from input file\n", line_count);

    // Clean up and exit
    fclose(input_file);
    free(list);
    return EXIT_SUCCESS;
}

// Function to parse a single line of the input file and add/update/remove entries as needed
void parse_line(char *line) {
    // Tokenize the current line using spaces as delimiters
    char *tokens[10];
    int token_count = 0;
    for (char *token = strtok(line, " "); token != NULL; token = strtok(NULL, " ")) {
        tokens[token_count++] = token;
    }

    // Check the number of tokens and ensure that they are valid
    if (token_count < 3) {
        return;
    } else if (token_count == 4 && strcmp(tokens[2], "UPDATE") != 0) {
        return;
    }

    // Extract the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG from the tokens
    int RX_UE_INFORMATION_TAG = atoi(tokens[0]);
    int RNTI = atoi(tokens[1]);
    int CRC_INDICATION_REL8_TAG = token_count == 4 ? atoi(tokens[3]) : -1;

    // Add a new entry to the list if it does not already exist, update an existing entry, or remove an entry based on RNTI
    if (find_index(RNTI) == -1) {
        add_entry(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    } else if (strcmp(tokens[2], "UPDATE") == 0) {
        update_entry(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    } else {
        remove_entry(RNTI);
    }
}

// Function to add a new entry to the list
void add_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Allocate memory for the new entry and copy the data from the tokens
    struct list *new_entry = malloc(sizeof(struct list));
    if (new_entry == NULL) {
        fprintf(stderr, "Error: out of memory\n");
        return;
    }

    new_entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry->RNTI = RNTI;
    new_entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Add the new entry to the list and update the list size
    new_entry->next = NULL;
    if (list == NULL) {
        list = new_entry;
    } else {
        struct list *current = list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_entry;
    }
}

// Function to update an existing entry in the list
void update_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Find the index of the entry to be updated and check for errors
    int index = find_index(RNTI);
    if (index == -1) {
        fprintf(stderr, "Error: failed to update entry with RNTI %d\n", RNTI);
        return;
    }

    // Update the data for the entry and update the list size
    struct list *current = list + index;
    current->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    current->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
}

// Function to remove an entry from the list based on its RNTI
void remove_entry(int RNTI) {
    // Find the index of the entry to be removed and check for errors
    int index = find_index(RNTI);
    if (index == -1) {
        fprintf(stderr, "Error: failed to remove entry with RNTI %d\n", RNTI);
        return;
    }

    // Remove the entry from the list and update the list size
    struct list *current = list + index;
    if (index == 0) {
        list = current->next;
    } else {
        struct list *previous = list + (index - 1);
        previous->next = current->next;
    }
}
