using namespace std;
using namespace boost::asio;
using io_service = boost::asio::io_service;

class SandeshClient {
public:
    SandeshClient(const string& image_dir, const string& pdf_dir) : image_dir_(image_dir), pdf_dir_(pdf_dir) {}

    void start() {
        io_service io_svc;
        boost::asio::ip::tcp::resolver resolver(io_svc);
        boost::asio::streambuf request;
        boost::asio::streambuf response;

        // Get a list of all image files in the input directory
        vector<string> image_files = getFilesInDirectory(image_dir_);

        // Loop through each image file and convert it to PDF using ImageMagick
        for (const string& image_file : image_files) {
            const string pdf_file = getPdfFilePath(image_file, pdf_dir_);
            const string command = "convert -quality 100 " + image_file + " " + pdf_file;

            // Run the ImageMagick convert command asynchronously and handle any errors
            future<int> result = io_svc.post(boost::bind(&exec, command));
            try {
                const int exit_code = result.get();
                if (exit_code != 0) {
                    throw runtime_error("ImageMagick conversion failed with exit code " + to_string(exit_code));
                }
            } catch (const exception& e) {
                cerr << "Error: " << e.what() << endl;
            }
        }
    }

private:
    string image_dir_;
    string pdf_dir_;

    // Get a list of all files in the input directory
    vector<string> getFilesInDirectory(const string& dir) {
        const path p = boost::filesystem::path(dir);
        if (!boost::filesystem::exists(p)) {
            throw runtime_error("Input directory does not exist");
        }
        return {begin(boost::filesystem::directory_iterator(p)), end(boost::filesystem::directory_iterator(p))};
    }

    // Get the PDF file path for an image file
    string getPdfFilePath(const string& image_file, const string& pdf_dir) {
        const size_t pos = image_file.rfind(".");
        if (pos == string::npos) {
            return "";
        }
        return pdf_dir + "/" + image_file.substr(0, pos) + ".pdf";
    }

    // Run a shell command asynchronously and handle any errors
    future<int> exec(const string& cmd) {
        io_service io_svc;
        boost::asio::ip::tcp::endpoint endpoint;
        boost::asio::streambuf request;
        boost::asio::streambuf response;

        // Set up the request and send it to the server
        request << cmd << endl;
        boost::system::error_code ec;
        write(request, endpoint, ec);

        if (ec) {
            throw runtime_error("Failed to execute command: " + cmd);
        }

        // Get the response and handle any errors
        read(response, endpoint, ec);
        if (ec) {
            throw runtime_error("Failed to read response from server");
        }

        // Parse the exit code from the response
        stringstream ss;
        ss << response.data();
        int exit_code = 0;
        ss >> exit_code;

        return make_ready_future(exit_code);
    }
};
```
