        self.user_id = user_id
        self.location = location
        self.session = requests_get(f"https://api.weather.com/api/weather/{location}").json()
        self.geolocation = self._fetch_geolocation(location)

    def _fetch_geolocation(self, location):
        geolocation_url = f"https://api.geolocation.org/v1/ip?apikey=YOUR_API_KEY&format=json"
        response = requests_get(geolocation_url)
        if response.status_code == 200:
            return json.loads(response.text)["location"]
        else:
            logger.error("Failed to fetch geolocation for location {}".format(location))
            raise HTTPError("Geolocation API call failed")

