        weather_url = f"https://api.weather.com/api/weather/{self.location}?apikey=YOUR_API_KEY&units=imperial"
        response = requests_get(weather_url)
        if response.status_code == 200:
            return json.loads(response.text)["current_observation"]
        else:
            logger.error("Failed to fetch weather for location {}".format(self.location))
            raise HTTPError("Weather API call failed")

