            session = requests_get(f"https://api.weather.com/api/weather/{location}").json()
            self._update_session(session)
            return True
        except (HTTPError, Timeout, TooManyRedirects):
            logger.error("Failed to update weather for user {} and location {}".format(user_id, location))
