// Struct to store information about an audio file
struct audio_file {
    char *filename;
    int sampling_rate;
    int num_channels;
};

// Function to process and upload an audio file
char* processAndUploadAudioFile(const char *filename, const char *url) {
    // Check if the filename is valid
    if (!filename || !strlen(filename)) {
        logger("Error: Invalid filename\n");
        return NULL;
    }

    // Check if the URL is valid
    if (!url || !strlen(url)) {
        logger("Error: Invalid URL\n");
        return NULL;
    }

    // Get the file extension and check if it's supported
    char *extension = strrchr(filename, '.');
    if (extension && !strcmp(extension, ".mp3") || !strcmp(extension, ".wav")) {
        logger("Error: Unsupported audio format\n");
        return NULL;
    }

    // Get the file size and check if it's valid
    struct stat st;
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        logger("Error: Could not open file\n");
        return NULL;
    }
    if (fstat(fd, &st) < 0) {
        close(fd);
        logger("Error: Could not stat file\n");
        return NULL;
    }
    if (st.st_size <= 0) {
        close(fd);
        logger("Error: File is empty or invalid\n");
        return NULL;
    }

    // Initialize the audio file struct
    struct audio_file file = {filename, 0, 0};

    // Read the file header and determine the sampling rate and number of channels
    char *header = (char *)malloc(st.st_size);
    if (!header) {
        close(fd);
        logger("Error: Could not allocate memory for file header\n");
        return NULL;
    }
    ssize_t num_read = read(fd, header, st.st_size);
    if (num_read < 0) {
        free(header);
        close(fd);
        logger("Error: Could not read file header\n");
        return NULL;
    }
    if (!strcmp(extension, ".mp3")) {
        // Extract the sampling rate and number of channels from the MP3 header
        int version = (header[0] & 0xff) | ((header[1] & 0xff) << 8);
        if (version >= 0xFFE) {
            file.sampling_rate = (header[29] & 0xff) | ((header[30] & 0xff) << 8) | ((header[31] & 0xff) << 16);
            file.num_channels = (header[33] & 0xff) | ((header[34] & 0xff) << 8);
        } else {
            file.sampling_rate = 44100;
            file.num_channels = 2;
        }
    } else if (!strcmp(extension, ".wav")) {
        // Extract the sampling rate and number of channels from the WAV header
        int format = (header[20] & 0xff) | ((header[21] & 0xff) << 8);
        if (format == 1) {
            file.sampling_rate = (header[24] & 0xff) | ((header[25] & 0xff) << 8) | ((header[26] & 0xff) << 16);
            file.num_channels = (header[28] & 0xff) | ((header[29] & 0xff) << 8);
        } else {
            file.sampling_rate = 44100;
            file.num_channels = 2;
        }
    }

    // Close the file descriptor
    close(fd);

    // Check if the sampling rate and number of channels are valid
    if (file.sampling_rate < 8000 || file.sampling_rate > 48000) {
        logger("Error: Unsupported sampling rate\n");
        return NULL;
    }
    if (file.num_channels < 1 || file.num_channels > 2) {
        logger("Error: Unsupported number of channels\n");
        return NULL;
    }

    // Modify the filename based on the sampling rate and number of channels
    int num_digits = floor(log10(file.sampling_rate)) + 1;
    char *new_filename = (char *)malloc(strlen(filename) + num_digits + strlen(".wav"));
    if (!new_filename) {
        logger("Error: Could not allocate memory for modified filename\n");
        return NULL;
    }
    sprintf(new_filename, "%s%0*d.wav", filename, num_digits, file.sampling_rate);

    // Transcode the audio file using LAME
    char *transcoded_filename = (char *)malloc(strlen(new_filename) + strlen(".mp3"));
    if (!transcoded_filename) {
        logger("Error: Could not allocate memory for transcoded filename\n");
        return NULL;
    }
    sprintf(transcoded_filename, "%s.mp3", new_filename);
    int ret = lame_encode_file(new_filename, transcoded_filename, file.sampling_rate, file.num_channels, 0);
    if (ret < 0) {
        logger("Error: LAME transcoding failed\n");
        return NULL;
    }

    // Upload the transcoded audio file to the server using Bluebird
    char *uploaded_filename = (char *)malloc(strlen(transcoded_filename) + strlen(".mp3"));
    if (!uploaded_filename) {
        logger("Error: Could not allocate memory for uploaded filename\n");
        return NULL;
    }
    sprintf(uploaded_filename, "%s.mp3", transcoded_filename);
    ret = bluebird_upload_file(url, username, password, uploaded_filename);
    if (ret < 0) {
        logger("Error: Bluebird upload failed\n");
        return NULL;
    }

    // Free memory and return the uploaded filename
    free(new_filename);
    free(transcoded_filename);
    free(uploaded_filename);
    return uploaded_filename;
}

int main() {
    char *url = "http://example.com";
    char *username = "myuser";
    char *password = "mypass";
    char *filepath = "/path/to/audio.wav";
    char *uploaded_filename = transcode_and_upload(url, username, password, filepath);
    if (uploaded_filename) {
        printf("Uploaded filename: %s\n", uploaded_filename);
    } else {
        printf("Transcoding and uploading failed\n");
    }
}
