// Define constants for maximum file size and allowed script types
#define MAX_FILE_SIZE 1000000 // 1MB
#define ALLOWED_SCRIPT_TYPES "text/javascript", "module"

void log_script_errors(const struct Script *scripts, int num_scripts) {
    for (int i = 0; i < num_scripts; ++i) {
        const struct Script *script = scripts + i;

        // Check if script src and type are valid
        if (!script->src || !script->type) {
            continue;
        }

        // Check if script size is within limits
        if (script->size > MAX_FILE_SIZE) {
            continue;
        }

        // Check if script type is allowed
        if (strcmp(script->type, ALLOWED_SCRIPT_TYPES) != 0) {
            continue;
        }

        char log_msg[512];
        snprintf(log_msg, sizeof(log_msg), "Script %d: %s (%s)", i, script->src, script->type);
        va_list args;
        va_start(args, log_msg);
        vsyslog(LOG_INFO, log_msg, args);
        va_end(args);
    }
}
```
