```python
import json
from typing import Dict, Optional

import requests

class ExternalInventoryAPIClient:
    def __init__(self):
        self.session = requests.Session()

    def get_book_availability(self, book_id: str) -> bool:
        url = f"https://external-inventory-api.com/books/{book_id}"
        response = self.session.get(url)

        if response.status_code == 200:
            return response.json()["availability"]
        else:
            raise Exception(f"Failed to get book availability for {book_id}: {response.text}")

    def refresh_token(self) -> None:
        self.session.headers = {
            "Authorization": f"Bearer {self.session.auth.access_token}"
        }

        response = self.session.post("https://external-inventory-api.com/oauth2/token", data={
            "grant_type": "refresh_token",
            "client_id": "<CLIENT_ID>",
            "client_secret": "<CLIENT_SECRET>",
            "refresh_token": self.session.auth.refresh_token,
        })

        if response.status_code == 200:
            self.session.auth = OAuth2(response.json()["access_token"], response.json()["refresh_token"])
        else:
            raise Exception(f"Failed to refresh access token: {response.text}")

class BookOrderProcessor:
    def __init__(self):
        self.cache = {}
        self.api_client = ExternalInventoryAPIClient()

    def process_order(self, order: Dict[str, any]) -> Dict[str, int]:
        book_ids = [book["id"] for book in order["books"]]

        # Check if the books are available in the inventory
        for book_id in book_ids:
            if not self.api_client.get_book_availability(book_id):
                raise Exception(f"Book {book_id} is out of stock")

        # Update the cache with the new order
        self.cache[order["id"]] = book_ids

        # Return a dictionary indicating the total quantity of each book type ordered
        return {
            book["type"]: len(book_ids) for book in order["books"]
        }

    def get_cached_orders(self) -> Dict[str, any]:
        return self.cache
```
This code defines a `BookOrderProcessor` class that takes care of processing customer orders and updating the cache with the new order. It also includes an external inventory API client for checking the availability of books in the inventory. The `process_order` method takes a serialized order object (a JSON string) as input and returns a dictionary indicating the total quantity of each book type ordered. It first checks if the books are available in the inventory, then updates the cache with the new order and finally returns the dictionary.

The `get_cached_orders` method is used to retrieve all cached orders. The `ExternalInventoryAPIClient` class is used for interacting with the external inventory API, it includes a `get_book_availability` method that checks if a book is available in the inventory and a `refresh_token` method that refreshes the access token if it has expired.

The code also uses dependency injection for the external API client, this allows for easy testing and maintenance of the code.

