function logError(string $level, string $message): void {
    // Create new Monolog instance
    $logger = new Monolog\Logger('my_app');
    $logger->pushHandler(new Monolog\Handler\StreamHandler(__DIR__ . '/logs/error.log', Logger::ERROR));

    // Write log message to file
