class APIGateway {
public:
    APIGateway(const string& configFile, const string& profile) {
        // Load configuration from file and validate parameters
        ifstream configStream(configFile);
        if (!configStream.is_open()) {
            throw invalid_argument("Unable to open config file");
        }

        string profileStr = "default";
        if (profile != "") {
            profileStr = profile;
        }

        auto config = parseConfig(configStream, profileStr);
        if (!config.has_value()) {
            throw invalid_argument("Invalid configuration");
        }

        // Initialize gateway with config parameters
        this->config = config.value();
        this->profile = profile;
    }

    void handleRequest(const string& request) {
        auto startTime = chrono::high_resolution_clock::now();

        // Authenticate and authorize client request
        auto authResp = authenticateClient(request);
        if (!authResp.has_value()) {
            throw runtime_error("Authentication failed");
        }

        auto authorized = isAuthorized(authResp.value());
        if (!authorized) {
            throw runtime_error("Unauthorized client request");
        }

        // Rate limit client requests based on IP address and API key
        auto rateLimitResp = rateLimitClient(request);
        if (!rateLimitResp.has_value()) {
            throw runtime_error("Rate limit exceeded");
        }

        auto requestHeader = parseRequestHeaders(request);
        // Map client requests to backend services based on routing rules
        string targetService;
        if (config->routingRules.count(requestHeader) > 0) {
            targetService = config->routingRules[requestHeader];
        } else {
            throw runtime_error("Invalid request header");
        }

        // Invoke backend service with client request and handle response
        auto backendResp = invokeBackendService(targetService, request);
        if (!backendResp.has_value()) {
            throw runtime_error("Backend service invocation failed");
        }

        // Cache backend response for future use
        cacheResponse(requestHeader, backendResp.value());

        // Filter sensitive data from backend response and return to client
        auto filteredResp = filterSensitiveData(backendResp.value());
        if (!filteredResp.has_value()) {
            throw runtime_error("Response filtering failed");
        }

        auto endTime = chrono::high_resolution_clock::now();
        auto duration = chrono::duration_cast<chrono::milliseconds>(endTime - startTime);
        cout << "Request handled in " << duration.count() << "ms" << endl;
    }

private:
