import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;
import javax.annotation.PostConstruct;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

@Service
@ConfigurationProperties("api-gateways")
public class ApiGatewayService {
    private final Logger logger = LoggerFactory.getLogger(ApiGatewayService.class);

    @Autowired
    private CloseableHttpClient httpClient;

    private List<String> apiGateways;

    public ApiGatewayService() {}

    @PostConstruct
    public void init() {
        logger.info("Initializing API Gateway Service");
    }

    public CompletableFuture<List<JSONObject>> fetchDataFromGateways(String query) {
        List<CompletableFuture<JSONObject>> futures = new ArrayList<>();
        for (String apiGateway : apiGateways) {
            String url = apiGateway + "/" + query;
            HttpGet request = new HttpGet(url);
            CompletableFuture<JSONObject> future = httpClient.executeAsync(request, new JSONResponseHandler())
                    .thenApply(response -> response.getBody().readValueAs(JSONObject.class));
            futures.add(future);
        }
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).thenApply(v -> futures.stream()
                .map(CompletableFuture::join)
                .collect(Collectors.toList()));
    }

    public void close() throws IOException {
        httpClient.close();
    }
}

@Component
