// Global variables
int log_file_count; // Number of log files to process
char **log_file_paths; // Array of log file paths
time_t update_interval; // Interval for updating Pokemon data (seconds)
bool running = true; // Flag to indicate the program is running
struct database *db; // Database client
struct configuration *config; // Configuration management system
pthread_mutex_t db_lock; // Mutex for protecting concurrent access to the database
pthread_mutex_t config_lock; // Mutex for protecting concurrent access to the configuration

// Function declarations
