// Define the logging mechanism with thread-safe buffering
class Log {
  private static $logLevel = 'INFO';
  private static $bufferSize = 100; // maximum number of log messages to buffer
  private static $flushInterval = 60; // flush buffer every minute
  private static $maxLogMessageLength = 500; // maximum length of a single log message
  private static $logFilePath = '/var/log/update-password.log'; // path to the log file
  private static $opened = false; // whether the log file is currently opened for writing
  private static $buffer = []; // buffer for log messages

  public static function info($message) {
    self::writeLog('INFO', $message);
  }

  public static function warning($message) {
    self::writeLog('WARNING', $message);
  }

  public static function error($message) {
    self::writeLog('ERROR', $message);
  }

  private static function writeLog($level, $message) {
    // Check if the log file is opened for writing
    if (!self::$opened) {
      // Open the log file in append mode with appropriate error handling
      try {
        self::$pdo = new PDO('sqlite:/' . self::$logFilePath);
        self::$opened = true;
      } catch (PDOException $e) {
        throw new Exception($e->getMessage());
      }
    }

    // Format the log message in ISO 8601 standard
    $formattedMessage = date('c') . ' | ' . $level . ' | ' . $message;

    // Add the formatted log message to the buffer
    self::$buffer[] = $formattedMessage;

    // Check if the buffer is full or if it's time to flush
    if (count(self::$buffer) >= self::$bufferSize || time() - self::$lastFlushTime > self::$flushInterval) {
      // Flush the buffer to the log file
      try {
        $log = implode("\n", self::$buffer);
        self::$pdo->exec($log);
        self::$buffer = [];
        self::$lastFlushTime = time();
      } catch (PDOException $e) {
        // Handle error conditions gracefully
        throw new Exception($e->getMessage());
      }
    }
  }
}
