from typing import Dict, List, Optional
import boto3
import logging

class AWSLambdaIntegration:
    def __init__(self, region: str):
        self.region = region
        self.lambda_client = boto3.client('lambda', region_name=self.region)

    def invoke(self, function_name: str, payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Invoke a Lambda function and return the response."""
        try:
            response = self.lambda_client.invoke(FunctionName=function_name, Payload=json.dumps(payload))
            if 'Payload' in response:
                return json.loads(response['Payload'])
            else:
                logging.warning(f"Lambda function {function_name} returned no payload.")
                return None
        except Exception as e:
            logging.error(f"Failed to invoke Lambda function {function_name}: {e}")
            return None

    def list_functions(self) -> List[str]:
        """List all Lambda functions in the current region."""
        try:
            response = self.lambda_client.list_functions()
            return [f['FunctionName'] for f in response['Functions']]
        except Exception as e:
            logging.error(f"Failed to list Lambda functions in {self.region}: {e}")
            return []

    def start_execution(self, function_name: str, payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Start an execution of a Lambda function and return the response."""
        try:
            response = self.lambda_client.start_execution(FunctionName=function_name, Payload=json.dumps(payload))
            if 'Payload' in response:
                return json.loads(response['Payload'])
            else:
                logging.warning(f"Lambda function {function_name} returned no payload.")
                return None
        except Exception as e:
            logging.error(f"Failed to start execution of Lambda function {function_name}: {e}")
            return None

    def get_execution_status(self, execution_arn: str) -> Optional[Dict[str, Any]]:
        """Get the status of a Lambda function execution."""
        try:
            response = self.lambda_client.get_execution_status(ExecutionArn=execution_arn)
            return json.loads(response['Payload'])
        except Exception as e:
            logging.error(f"Failed to get status of Lambda function execution {execution_arn}: {e}")
            return None

    def stop_execution(self, execution_arn: str) -> bool:
        """Stop an execution of a Lambda function."""
        try:
            self.lambda_client.stop_execution(ExecutionArn=execution_arn)
            logging.info(f"Stopped execution of Lambda function {execution_arn}")
            return True
        except Exception as e:
            logging.error(f"Failed to stop execution of Lambda function {execution_arn}: {e}")
            return False

    def monitor_executions(self, executions: List[str], interval: int) -> None:
        """Monitor the status of a list of Lambda function executions."""
        while True:
            for execution in executions:
                status = self.get_execution_status(execution)
                if status and 'Status' in status and status['Status'] == 'SUCCEEDED':
                    logging.info(f"Execution of Lambda function {execution} succeeded.")
                elif status and 'Status' in status and status['Status'] == 'FAILED':
                    logging.error(f"Execution of Lambda function {execution} failed: {status}")
            time.sleep(interval)

class WorkflowOrchestrator:
    def __init__(self, aws_region: str):
        self.aws_region = aws_region
        self.lambda_client = boto3.client('lambda', region_name=self.aws_region)
        self.execution_map = {} # Map of execution ARNs to function names

    def add_step(self, function_name: str, payload: Dict[str, Any]) -> Optional[str]:
        """Add a step to the workflow orchestration."""
        try:
            response = self.lambda_client.invoke(FunctionName=function_name, Payload=json.dumps(payload))
            if 'Payload' in response:
                return json.loads(response['Payload'])
            else:
                logging.warning(f"Lambda function {function_name} returned no payload.")
                return None
        except Exception as e:
            logging.error(f"Failed to add step to workflow orchestration: {e}")
            return None

    def remove_step(self, function_name: str) -> bool:
        """Remove a step from the workflow orchestration."""
        try:
            self.execution_map = {execution: function for execution, function in self.execution_map.items() if function != function_name}
            logging.info(f"Removed step {function_name} from workflow orchestration.")
            return True
        except Exception as e:
            logging.error(f"Failed to remove step {function_name} from workflow orchestration: {e}")
            return False

    def execute_workflow(self) -> bool:
        """Execute the workflow orchestration."""
        try:
            executions = []
            for function, payload in self.execution_map.items():
                execution = self.add_step(function, payload)
                if execution:
                    executions.append(execution['ExecutionArn'])
            self.monitor_executions(executions, 10) # Monitor the status of the workflow execution every 10 seconds
            return True
        except Exception as e:
            logging.error(f"Failed to execute workflow orchestration: {e}")
            return False

    def monitor_executions(self, executions: List[str], interval: int) -> None:
        """Monitor the status of a list of Lambda function executions."""
        while True:
            for execution in executions:
                status = self.get_execution_status(execution)
                if status and 'Status' in status and status['Status'] == 'SUCCEEDED':
                    logging.info(f"Execution of Lambda function {execution} succeeded.")
                elif status and 'Status' in status and status['Status'] == 'FAILED':
                    logging.error(f"Execution of Lambda function {execution} failed: {status}")
            time.sleep(interval)
