```java
import java.io.File;
import java.util.List;
import java.util.Map;

public class ImageProcessingService {
    private static final String CONFIG_FILE = "image-processing-config.json";

    // Load configuration parameters from JSON file
    private static Map<String, Object> config = loadConfig();

    public void processImage(File image) {
        // Read image dimensions and quality settings from configuration file
        int width = (int) config.get("image-width");
        int height = (int) config.get("image-height");
        int quality = (int) config.get("quality");

        // Resize the image using a third-party library (e.g. ImageMagick)
        String resizeCommand = "convert -resize " + width + "x" + height + "!" + image.getAbsolutePath();
        Process process = Runtime.getRuntime().exec(resizeCommand);

        // Optimize image quality using a third-party library (e.g. ImageOptim)
        String optimizeCommand = "imageoptim -q" + quality + " -i " + image.getAbsolutePath();
        Process process2 = Runtime.getRuntime().exec(optimizeCommand);

        // Wait for both processes to finish before continuing
        try {
            process.waitFor();
            process2.waitFor();
        } catch (InterruptedException e) {
            throw new ImageProcessingException("Error while processing image", e);
        }
    }

    public void batchProcessImages(List<File> images) {
        // Use a thread pool to parallelize image processing for better performance
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        // Create a list of tasks that will be executed in the thread pool
        List<Callable<Void>> tasks = new ArrayList<>();
        for (File image : images) {
            tasks.add(() -> {
                processImage(image);
                return null;
            });
        }

        // Submit the list of tasks to the thread pool and wait for all tasks to complete
        try {
            executor.invokeAll(tasks).stream().map(future -> future.get());
        } catch (InterruptedException | ExecutionException e) {
            throw new ImageProcessingException("Error while processing images in batch", e);
        } finally {
            executor.shutdown();
        }
    }

    public void setConfig(Map<String, Object> newConfig) {
        // Update the configuration parameters with the new values
        config = newConfig;
    }

    public Map<String, Object> getConfig() {
        // Return a copy of the current configuration parameters
        return new HashMap<>(config);
    }

    private static Map<String, Object> loadConfig() {
        try {
            String configJson = Files.readString(Paths.get(CONFIG_FILE));
            return JsonUtils.fromJson(configJson, Map.class);
        } catch (IOException | JsonParseException e) {
            throw new ImageProcessingException("Error while loading configuration file", e);
        }
    }
}
