using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json;
using Newtonsoft.Json.Converters;
using Newtonsoft.Json.Serialization;

public class CompressAndEncryptStream : Stream
{
    private readonly Stream _inputStream;
    private readonly byte[] _encryptionKey;
    private readonly int _blockSize;
    private readonly ICompressionAlgorithm _compressionAlgorithm;
    private readonly ICryptoTransform _cryptoTransform;
    private bool _disposed;

    public CompressAndEncryptStream(Stream inputStream, byte[] encryptionKey, int blockSize = 8192, ICompressionAlgorithm compressionAlgorithm = null)
    {
        _inputStream = inputStream;
        _encryptionKey = encryptionKey;
        _blockSize = blockSize;
        _compressionAlgorithm = compressionAlgorithm ?? new DeflateStream();
        _cryptoTransform = new AesCryptoServiceProvider().CreateEncryptor(_encryptionKey);
    }

    public override void Flush() => throw new NotImplementedException();

    public override long Seek(long offset, SeekOrigin origin) => throw new NotImplementedException();

    public override void SetLength(long value) => throw new NotImplementedException();

    public override int Read(byte[] buffer, int offset, int count)
    {
        if (_disposed)
            throw new ObjectDisposedException(nameof(CompressAndEncryptStream));

        var compressed = _compressionAlgorithm.Compress(_inputStream);
        var encrypted = _cryptoTransform.TransformFinalBlock(compressed, 0, compressed.Length);
        var readCount = Math.Min(count, encrypted.Length - offset);
        Array.Copy(encrypted, offset, buffer, 0, readCount);
        return readCount;
    }

    public override void Write(byte[] buffer, int offset, int count) => throw new NotImplementedException();

    protected override void Dispose(bool disposing)
    {
        if (!_disposed && disposing)
        {
            _inputStream.Dispose();
            _cryptoTransform.Dispose();
        }

        _disposed = true;
        base.Dispose(disposing);
    }
}
