using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json;
using Newtonsoft.Json.Converters;
using Newtonsoft.Json.Serialization;

public class HttpClientHelper
{
    private readonly HttpClient _httpClient;
    private readonly JsonSerializerSettings _jsonSerializerSettings;

    public HttpClientHelper(HttpClient httpClient, IList<JsonConverter> jsonConverters = null)
    {
        _httpClient = httpClient;
        _jsonSerializerSettings = new JsonSerializerSettings
        {
            Converters = jsonConverters ?? new List<JsonConverter>()
        };
    }

    public async Task<T> GetAsync<T>(string url, int? timeout = null, IDictionary<string, string> headers = null)
    {
        var requestMessage = new HttpRequestMessage(HttpMethod.Get, url);
        if (timeout.HasValue)
            requestMessage.Headers.Add("Timeout", $"{timeout}");
        if (headers != null)
            foreach (var header in headers)
                requestMessage.Headers.Add(header.Key, header.Value);
        var response = await _httpClient.SendAsync(requestMessage);
        return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync(), _jsonSerializerSettings);
    }

    public async Task<T> PostAsync<T>(string url, object data, int? timeout = null, IDictionary<string, string> headers = null)
    {
        var requestMessage = new HttpRequestMessage(HttpMethod.Post, url);
        if (timeout.HasValue)
            requestMessage.Headers.Add("Timeout", $"{timeout}");
        if (headers != null)
            foreach (var header in headers)
                requestMessage.Headers.Add(header.Key, header.Value);
        var response = await _httpClient.SendAsync(requestMessage);
        return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync(), _jsonSerializerSettings);
    }
}
