namespace CachingAndErrorHandling
{
    public static class XmlParser
    {
        private const int MAX_BUFFER_SIZE = 1024 * 1024 * 1024; // 1GB

        private static readonly ILogger<XmlParser> _logger = new Logger<XmlParser>();
        private static readonly HttpClient _httpClient = new HttpClient();

        public static async Task<XPathNavigator> GetFirstElementByNameAsync(string xml, string elementName)
        {
            try
            {
                using (var stream = new MemoryStream(Encoding.UTF8.GetBytes(xml)))
                {
                    var document = new XPathDocument(stream);
                    return document.CreateNavigator().SelectSingleNode($"/*/{elementName}");
                }
            }
            catch (Exception ex) when (!(ex is HttpRequestException || ex is IOException))
            {
                _logger.LogError(ex, "Error parsing XML file.");
                throw;
            }
        }
    }

    public static class SecureTokenGenerator
    {
        private const int MAX_BUFFER_SIZE = 1024 * 1024 * 1024; // 1GB

        private static readonly ILogger<SecureTokenGenerator> _logger = new Logger<SecureTokenGenerator>();
        private static readonly HashAlgorithm SHA256 = new SHA256Managed();

        public static string GenerateToken(string username, DateTime timestamp, string secretKey)
        {
            try
            {
                var message = $"{username}{timestamp}{secretKey}";
                return Convert.ToBase64String(SHA256.ComputeHash(Encoding.UTF8.GetBytes(message)));
            }
            catch (Exception ex) when (!(ex is HttpRequestException || ex is IOException))
            {
                _logger.LogError(ex, "Error generating secure token.");
                throw;
            }
        }
    }
}
