      String symbol = entry.getKey();
      int quantity = entry.getValue().intValue();

      // TODO: Persist the updated quantity for the given symbol to a database or other storage mechanism
    }
  }

  private static class TransactionLogEntry {
    private final String symbol;
    private final int quantity;
    private final double price;

    public TransactionLogEntry(String symbol, int quantity, double price) {
      this.symbol = symbol;
      this.quantity = quantity;
      this.price = price;
    }

    public String getSymbol() {
      return symbol;
    }

    public int getQuantity() {
      return quantity;
    }

    public double getPrice() {
      return price;
    }
  }
}
