using System;
using UnityEngine;
using UnityEngine.Random;
using System.Security.Cryptography;
using System.Threading;

public class SecureRandomValueGenerator : MonoBehaviour
{
    // Configuration variables
    private const int DefaultMinimumLength = 8;
    private const int DefaultMaximumLength = 32;
    private const string DefaultCharacterSet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    private const int DefaultExclusionCount = 20;

    // Cache variables
    private readonly Dictionary<string, string> _cache = new Dictionary<string, string>();
    private readonly object _lock = new object();

    // ASP.NET Identity configuration
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly AuthenticationHeaderValue _authenticationHeader;

    // Validation settings
    private int _minimumLength = DefaultMinimumLength;
    private int _maximumLength = DefaultMaximumLength;
    private string _characterSet = DefaultCharacterSet;
    private int _exclusionCount = DefaultExclusionCount;

    // Failover settings
    private readonly List<string> _secondaryDataSources = new List<string>();
    private string _primaryDataSource;

    public SecureRandomValueGenerator(string primaryDataSource, List<string> secondaryDataSources)
    {
        _primaryDataSource = primaryDataSource;
        _secondaryDataSources = secondaryDataSources;
    }

    // Override the ToString method to display the current range of values, the status of the external data source integration, and the validation settings for user accounts and passwords.
    public override string ToString()
    {
        return $"Current Range: {MinimumLength} - {MaximumLength}\n" +
            $"External Data Source Status: {(_primaryDataSource == null ? "Not Connected" : "Connected")}\n" +
            $"Validation Settings:\n" +
            $"\tMinimum Length: {_minimumLength}\n" +
            $"\tMaximum Length: {_maximumLength}\n" +
            $"\tCharacter Set: {_characterSet}\n" +
            $"\tExclusion Count: {_exclusionCount}";
    }

    // Generate a random value within the specified range.
    public string GenerateValue(int minimumLength, int maximumLength)
    {
        string value = UnityEngine.Random.Range(minimumLength, maximumLength);
        return value;
    }

    // Validate user accounts and passwords using the ASP.NET Identity framework.
    public bool ValidateUserAccount(string username, string password)
    {
        if (username == null || password == null)
            return false;

        try
        {
            var request = new HttpRequestMessage(HttpMethod.Post, "/api/users/authenticate")
                .AddHeader("Authorization", _authenticationHeader.ToString())
                .Content = new StringContent(JsonConvert.SerializeObject(new UserAuthenticationModel()
                {
                    Username = username,
                    Password = password
                }), Encoding.UTF8, "application/json");

            var response = await _httpClient.SendAsync(request);
            if (response.StatusCode == HttpStatusCode.OK)
            {
                return true;
            }
            else
            {
                // Log the failed attempt
                Debug.Log($"Failed to validate user account: {username}");
            }
        }
        catch (Exception ex)
        {
            // Log the error and return false
            Debug.LogError($"Error validating user account: {ex.Message}");
        }

        return false;
    }

    // Set customizable requirements for minimum length, character sets, and exclusion of common words.
    public void SetValidationSettings(int minimumLength, int maximumLength, string characterSet, int exclusionCount)
    {
        _minimumLength = minimumLength;
        _maximumLength = maximumLength;
        _characterSet = characterSet;
        _exclusionCount = exclusionCount;
    }

    // Handle errors gracefully, including network failures, invalid API responses, and decryption failures.
    public void HandleError(Exception ex)
    {
        Debug.LogError($"Error: {ex.Message}");
    }

    // Implement a mechanism to cache keys and IVs locally to minimize the number of API calls and reduce latency.
    private async Task<string> GetCachedValue(string key)
    {
        string value = null;

        lock (_lock)
        {
            if (_cache.ContainsKey(key))
                value = _cache[key];
        }

        return value;
    }

    // Implement a strategy to purge old cache entries to free up resources.
    private async Task PurgeCache()
    {
        lock (_lock)
        {
            var expiredKeys = new List<string>();

            foreach (var item in _cache)
            {
                if (item.Value == null || DateTime.UtcNow - item.Value > TimeSpan.FromHours(1))
                    expiredKeys.Add(item.Key);
            }

            foreach (var key in expiredKeys)
                _cache.Remove(key);
        }
    }

    // Implement a mechanism to fetch and cache keys and IVs from the external data source, including support for a secondary data source.
    private async Task<string> GetValueFromExternalDataSource(string key)
    {
        string value = null;

        try
        {
            if (_primaryDataSource == null || _secondaryDataSources.Count == 0)
                return value;

            // Fetch the value from the primary data source
            var request = new HttpRequestMessage(HttpMethod.Get, $"{_primaryDataSource}/api/values/{key}");
            var response = await _httpClient.SendAsync(request);
            if (response.StatusCode == HttpStatusCode.OK)
            {
                value = await response.Content.ReadAsStringAsync();
            }
            else if (_secondaryDataSources.Count > 0)
            {
                // If the primary data source is not available, fetch the value from a secondary data source
                var secondaryDataSource = _secondaryDataSources[0];
                request = new HttpRequestMessage(HttpMethod.Get, $"{secondaryDataSource}/api/values/{key}");
                response = await _httpClient.SendAsync(request);
                if (response.StatusCode == HttpStatusCode.OK)
                {
                    value = await response.Content.ReadAsStringAsync();
                }
            }

            // Add the fetched value to the cache
            lock (_lock)
            {
                _cache[key] = value;
            }
        }
        catch (Exception ex)
        {
            Debug.LogError($"Error getting value from external data source: {ex.Message}");
        }

        return value;
    }
}

