// Define the maximum number of retries for conversion failures
#define MAX_RETRIES 3

// Define the minimum and maximum DPI values allowed
#define MIN_DPI 72
#define MAX_DPI 600

// Define the path to the temporary directory for storing converted files
#define TEMP_DIR "/tmp"

// Define the function to convert a single JPEG file to PDF
int convertJpegToPdf(char* inputFile, char* outputFile, int dpi) {
    // Check if the input and output directories exist and are writable
    if (!access(inputFile, R_OK)) {
        printf("Input file does not exist or is not readable: %s\n", inputFile);
        return 1;
    }
    if (!access(outputFile, W_OK)) {
        printf("Output directory does not exist or is not writable: %s\n", outputFile);
        return 1;
    }

    // Check if the provided DPI value is within a reasonable range
    if (dpi < MIN_DPI || dpi > MAX_DPI) {
        printf("Invalid DPI value provided: %d\n", dpi);
        return 1;
    }

    // Initialize variables for temporary file names and conversion attempts
    char* tempFile = NULL;
    int numAttempts = 0;

    do {
        // Generate a temporary file name for the converted PDF
        tempFile = generateTempFileName(outputFile);

        // Attempt to convert the JPEG file to PDF using the provided DPI value
        if (convertJpegToPdfImpl(inputFile, tempFile, dpi)) {
            // If conversion is successful, rename the temporary file to the final output name
            rename(tempFile, outputFile);
            return 0;
        } else {
            // If conversion fails, increment the number of attempts and try again with an exponential backoff
            numAttempts++;
            sleep(pow(2, numAttempts - 1));
        }
    } while (numAttempts < MAX_RETRIES);

    // If all retries fail, log the error and return a failure code
    printf("Failed to convert JPEG file: %s\n", inputFile);
    return 1;
}

// Implement the conversion function using a third-party tool
int convertJpegToPdfImpl(char* inputFile, char* outputFile, int dpi) {
    // Use the third-party tool to convert the JPEG file to PDF with the provided DPI value
    system(("convert -density %d -quality 100 %s %s", dpi, inputFile, outputFile));
}

// Generate a temporary file name for storing converted files
char* generateTempFileName(char* baseName) {
    // Use the basename of the input file as the prefix for the temporary file name
    char* tempName = (char*)malloc(strlen(baseName) + strlen(".pdf") + 1);
    strcpy(tempName, baseName);
    strcat(tempName, ".pdf");

    // Ensure that the generated temporary file does not already exist
    while (access(tempName, F_OK)) {
        tempName = (char*)realloc(tempName, strlen(baseName) + strlen(".pdf") + 1);
        sprintf(tempName, "%s-%d.pdf", baseName, rand() % 10000);
    }

    return tempName;
}
