import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.io.IOException;
import java.util.zip.DeflaterOutputStream;
import java.util.zip.InflaterInputStream;

public class Deserializer {
    private static final int CACHE_SIZE = 1024 * 1024; // 1MB cache size

    public static Object deserialize(byte[] data) throws IOException, ClassNotFoundException, DeserializationException {
        if (data == null || data.length == 0) {
            throw new DeserializationException("Input data is empty");
        }

        try (ByteArrayInputStream bais = new ByteArrayInputStream(data)) {
            ObjectInputStream ois = new ObjectInputStream(bais);

            // Validate the byte array before deserializing
            if (!ois.markSupported()) {
                throw new DeserializationException("Input data is not a valid serialized object");
            }

            // Check for version compatibility
            int version = ois.readInt();
            if (version > 1) {
                throw new VersionMismatchException(String.format("Unsupported version: %d", version));
            }

            try {
                // Load the class from a specified class loader
                Class<?> clazz = Class.forName("com.example.MyClass");

                // Deserialize the object
                return ois.readObject();
            } catch (ClassNotFoundException e) {
                throw new ClassNotFoundException(String.format("Cannot find class: %s", e.getMessage()), e);
            }
        }
    }
}
