import zlib
import pickle
from collections import deque
from typing import Deque, Dict, List, Optional, Set, Tuple

def compress(data: bytes) -> bytes:
    """Compresses the given data using LZ77 and Huffman coding."""
    # LZ77 compression with sliding window of size 32K
    window = deque([], maxlen=32 * 1024)
    compressed = b''

    for i in range(len(data)):
        if data[i] not in window:
            window.appendleft(data[i])
        else:
            window.rotate(-window.index(data[i]))
        while len(window) > 0 and len(compressed) > 256:
            compressed += bytes([window.pop()])
    # Huffman coding with fixed-size bit strings
    huffman = {(i,): bytes([i]) for i in range(256)}
    while any(len(v) > 1 for v in huffman.values()):
        new_huffman = {}
        for k, v in huffman.items():
            if len(v) == 1:
                continue
            else:
                for i in range(256):
                    if i not in v:
                        new_huffman[(k + (i,),)] = bytes([i])
        huffman = new_huffman
    compressed += b''
    return zlib.compress(pickle.dumps(huffman)) + compressed
