// Weather API Class
public class WeatherAPI {
    private readonly string _apiKey;
    private readonly HttpClient _httpClient;
    private readonly UnionFind _unionFind;
    private readonly Dictionary<string, object> _cache;
    private readonly object _lockObject = new();

    public WeatherAPI(string apiKey) {
        _apiKey = apiKey;
        _httpClient = new HttpClient();
        _unionFind = new UnionFind(100);
        _cache = new Dictionary<string, object>();
    }

    public async Task<WeatherData> GetCurrentWeather(string city) {
        // Check if the city is already in the cache
        if (_cache.ContainsKey(city)) {
            return (WeatherData)_cache[city];
        }

        // Fetch current weather data from OpenWeatherMap API
        string url = $"https://api.openweathermap.org/data/2.5/weather?q={city}&appid={_apiKey}";
        var response = await _httpClient.GetAsync(url);

        // Check if the API request was successful
        if (response.IsSuccessStatusCode) {
            string json = await response.Content.ReadAsStringAsync();
            WeatherData weatherData = JsonConvert.DeserializeObject<WeatherData>(json);

            // Cache the current weather data for future use
            lock (_lockObject) {
                _cache[city] = weatherData;
            }

            return weatherData;
        } else {
            throw new Exception("Failed to fetch current weather data");
        }
    }

    public async Task<WeatherForecast> GetWeatherForecast(string city, int days) {
        // Check if the city is already in the cache
        if (_cache.ContainsKey(city)) {
            return (WeatherForecast)_cache[city];
        }

        // Fetch historical weather data from a separate API
        string url = $"https://api.weatherprovider.com/historical-data?q={city}&days={days}";
        var response = await _httpClient.GetAsync(url);

        // Check if the API request was successful
        if (response.IsSuccessStatusCode) {
            string json = await response.Content.ReadAsStringAsync();
            WeatherForecast weatherForecast = JsonConvert.DeserializeObject<WeatherForecast>(json);

            // Cache the historical weather forecast for future use
            lock (_lockObject) {
                _cache[city] = weatherForecast;
            }

            return weatherForecast;
        } else {
            throw new Exception("Failed to fetch historical weather data");
        }
    }

    public async Task<WeatherData> GetWeatherData(string city) {
        // Check if the city is already in the cache
        if (_cache.ContainsKey(city)) {
            return (WeatherData)_cache[city];
        }

        // Fetch current weather data from OpenWeatherMap API
        string url = $"https://api.openweathermap.org/data/2.5/weather?q={city}&appid={_apiKey}";
        var response = await _httpClient.GetAsync(url);

        // Check if the API request was successful
        if (response.IsSuccessStatusCode) {
            string json = await response.Content.ReadAsStringAsync();
