import datetime
from collections import deque

class WeatherCache:
    def __init__(self):
        self.cache = {}

    def get_weather(self, user_id, location_id, date_range=None):
        if not self.has_cache(user_id, location_id, date_range):
            return None
        return self.cache[user_id][location_id]

    def set_weather(self, user_id, location_id, weather):
        if not self.has_cache(user_id, location_id):
            self.cache[user_id] = {}
        self.cache[user_id][location_id] = weather

    def has_cache(self, user_id, location_id, date_range=None):
        if not self.cache or not self.cache.get(user_id):
            return False
        cached_weather = self.cache[user_id][location_id]
        if date_range:
            start_date, end_date = date_range
            if not start_date <= cached_weather['date'] <= end_date:
                return False
        return True

class WeatherAPI:
    def __init__(self):
        self.rate_limit = 10
        self.requests = deque()

    def get_weather(self, user_id, location_id, date_range=None):
        if not self.has_cache(user_id, location_id):
            self.request_forecast(user_id, location_id)
        return self.get_cached_weather(user_id, location_id, date_range)

    def request_forecast(self, user_id, location_id):
        if len(self.requests) >= self.rate_limit:
            # Rate limit reached, wait for a request to complete before making another one
            while len(self.requests) > 0 and not self.requests[0].done():
                time.sleep(1)
        self.requests.append(self.fetch_weather(user_id, location_id))

    def fetch_weather(self, user_id, location_id):
        # Fetch weather data from third-party API
        return {'date': datetime.datetime.now(), 'temperature': 10, 'condition': 'Sunny'}

    def get_cached_weather(self, user_id, location_id, date_range=None):
        # Get weather data from cache
        if self.has_cache(user_id, location_id, date_range):
            return self.cache[user_id][location_id]
        else:
            return None

    def has_cache(self, user_id, location_id, date_range=None):
        # Check if weather data is cached for the given user and location
        if not self.cache or not self.cache.get(user_id):
            return False
        cached_weather = self.cache[user_id][location_id]
        if date_range:
            start_date, end_date = date_range
            if not start_date <= cached_weather['date'] <= end_date:
                return False
        return True

class WeatherUpdater:
    def __init__(self):
        self.cache = WeatherCache()
        self.api = WeatherAPI()

    def update_weather(self, user_id, location_id, date_range=None):
        # Fetch and cache new weather data for the given user and location
        weather = self.api.get_weather(user_id, location_id, date_range)
        if weather:
            self.cache.set_weather(user_id, location_id, weather)
            return True
        else:
            return False

    def get_weather(self, user_id, location_id, date_range=None):
        # Get cached weather data for the given user and location
        return self.cache.get_weather(user_id, location_id, date_range)
