#include <netinet/in.h>
#include <arpa/inet.h>
#include <assert.h>

#define MAX_THREADS 50000
#define BUFFER_SIZE 1024
#define MAX_DATA_RATE 10000000

typedef struct {
    int crc_indication_pdu;
    char *data;
} pdu_t;

void *process_pdu(void *arg) {
    pdu_t *pdu = (pdu_t *)arg;
    // Process the PDU here...
    free(pdu->data);
    free(pdu);
    return NULL;
}

int generate_pdu(char *data, int data_length) {
    pdu_t *pdu = (pdu_t *)malloc(sizeof(pdu_t));
    if (!pdu) {
        perror("Failed to allocate PDU");
        return -1;
    }
    pdu->data = malloc(data_length);
    if (!pdu->data) {
        perror("Failed to allocate data buffer");
        free(pdu);
        return -1;
    }
    memcpy(pdu->data, data, data_length);
    pdu->crc_indication_pdu = 1;
    // Process the PDU here...
    free(pdu->data);
    free(pdu);
    return 0;
}

int main() {
    int sockfd, portno, n;
    struct sockaddr_in serv_addr;
    struct hostent *server;
    char buffer[BUFFER_SIZE];
    pthread_t threads[MAX_THREADS];
    pthread_attr_t attr;

    // Initialize the thread attributes
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    // Create a socket and connect to server
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        return -1;
    }
    portno = atoi(argv[1]);
    server = gethostbyname(argv[2]);
    if (server == NULL) {
        fprintf(stderr, "ERROR, no such host\n");
        exit(0);
    }
    bzero((char *) &serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    bcopy((char *)server->h_addr, (char *)&serv_addr.sin_addr.s_addr, server->h_length);
    serv_addr.sin_port = htons(portno);
    if (connect(sockfd, &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR connecting");
        return -1;
    }

    // Initialize the dynamic thread pool
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
    int num_threads = 0;
    while (1) {
        // Check if there are any available threads
        for (int i = 0; i < MAX_THREADS; i++) {
            if (pthread_tryjoin_np(threads[i], NULL) == 0) {
                num_threads--;
            }
        }
        // If there are no available threads, create a new one
        if (num_threads < MAX_THREADS) {
            pthread_t thread;
            pthread_attr_init(&attr);
            pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
            void *status;
            int rc = pthread_create(&thread, &attr, process_pdu, NULL);
            if (rc) {
                perror("ERROR creating thread");
                return -1;
            }
            threads[num_threads] = thread;
            num_threads++;
        } else {
            // If there are no available threads, wait for one to finish
            pthread_join(threads[0], NULL);
            // Remove the finished thread from the pool
            memmove(&threads[0], &threads[1], sizeof(pthread_t) * (MAX_THREADS - 1));
        }
    }
