```cpp
#include <iostream>
#include <fstream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <map>

using namespace std;

struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
};

class ThreadPool {
public:
    ThreadPool(int numThreads) : threads_(numThreads) {}

    void addTask(function<void()> task) {
        tasks_.push_back(task);
    }

    void run() {
        for (auto& thread : threads_) {
            thread = std::thread(std::bind(&ThreadPool::execute, this));
        }

        while (!tasks_.empty()) {
            execute();
        }
    }

private:
    void execute() {
        if (tasks_.empty()) {
            return;
        }

        function<void()> task = tasks_.front();
        tasks_.pop_front();

        task();
    }

    vector<thread> threads_;
    list<function<void()>> tasks_;
};

int main(int argc, char* argv[]) {
    int numThreads = 10; // default value
    if (argc > 1) {
        numThreads = atoi(argv[1]);
    }

    vector<NFAPI_CRC_INDICATION_PDU> pduList;
    vector<thread> threadPool;

    for (int i = 0; i < numThreads; ++i) {
        threadPool.push_back(std::thread(std::bind(&ThreadPool::run, &threadPool)));
    }

    while (pduList.size() < 10000) {
        int RX_UE_INFORMATION_TAG = generateRandomInt(); // random function for generating unique RX_UE_INFORMATION_TAG
        int RNTI = generateRandomInt(); // random function for generating unique RNTI
        int CRC_INDICATION_REL8_TAG = generateRandomInt(); // random function for generating unique CRC_INDICATION_REL8_TAG with randomly set CRCFLAG values

        pduList.push_back({RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG});
    }

    for (auto& thread : threadPool) {
        thread.join();
    }

    cout << "Number of requests: " << pduList.size() << endl;

    return 0;
}
```
