    private static final int THREAD_POOL_SIZE = 10;
    private static final int MAX_CONCURRENT_REQUESTS = 50;

    public static String getPokemonDetails(byte[] serializedPokemon) throws IOException, DeserializationException {
        // Deserialize the Pokemon object from the byte array using ObjectInputStream
        ObjectInputStream inputStream = new ObjectInputStream(new ByteArrayInputStream(serializedPokemon));
        Pokemon pokemon = (Pokemon)inputStream.readObject();

        // Fetch additional data about Pokemon weaknesses, resistances, and immunities from an external REST API if local lookup is insufficient or fails
        String[] weaknesses;
        String[] resistances;
        String[] immunities;
        try {
            weaknesses = fetchWeaknesses(pokemon);
            resistances = fetchResistances(pokemon);
            immunities = fetchImmunities(pokemon);
        } catch (IOException | DeserializationException e) {
            // Handle failed API requests and cache responses to reduce redundant calls
            weaknesses = null;
            resistances = null;
            immunities = null;
        } finally {
            inputStream.close();
        }

        // Return a detailed string representing the weaknesses, resistances, and immunities of the Pokemon
        return String.format("Weaknesses: %s\nResistances: %s\nImmunities: %s",
                Arrays.toString(weaknesses), Arrays.toString(resistances), Arrays.toString(immunities));
    }

    private static String[] fetchWeaknesses(Pokemon pokemon) throws IOException {
        // Use a thread pool with fair scheduling to handle high volumes of deserialization and API request tasks efficiently
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE, new ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                return new Thread(r, "Deserializer-Thread");
            }
        });

        // Fetch weaknesses from an external REST API using a custom library function
        Future<String[]> weaknessesFuture = executor.submit(() -> fetchWeaknessesFromAPI(pokemon));

        try {
            return weaknessesFuture.get(MAX_CONCURRENT_REQUESTS, TimeUnit.SECONDS);
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            throw new DeserializationException("Failed to fetch weaknesses from API", e);
        } finally {
            executor.shutdown();
        }
    }

    private static String[] fetchResistances(Pokemon pokemon) throws IOException {
        // Use a thread pool with fair scheduling to handle high volumes of deserialization and API request tasks efficiently
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE, new ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                return new Thread(r, "Deserializer-Thread");
            }
        });

        // Fetch resistances from an external REST API using a custom library function
        Future<String[]> resistancesFuture = executor.submit(() -> fetchResistancesFromAPI(pokemon));

        try {
            return resistancesFuture.get(MAX_CONCURRENT_REQUESTS, TimeUnit.SECONDS);
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            throw new DeserializationException("Failed to fetch resistances from API", e);
        } finally {
            executor.shutdown();
        }
    }

    private static String[] fetchImmunities(Pokemon pokemon) throws IOException {
        // Use a thread pool with fair scheduling to handle high volumes of deserialization and API request tasks efficiently
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE, new ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                return new Thread(r, "Deserializer-Thread");
            }
        });

        // Fetch immunities from an external REST API using a custom library function
        Future<String[]> immunitiesFuture = executor.submit(() -> fetchImmunitiesFromAPI(pokemon));

        try {
            return immunitiesFuture.get(MAX_CONCURRENT_REQUESTS, TimeUnit.SECONDS);
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
