// ApiClient.rs
use reqwest::{self, blocking::get};

trait ApiClient {
    async fn fetch_data(&self) -> Result<Vec<Record>, Box<dyn std::error::Error>>;
}

struct ApiClient {
    // Use a connection pool to handle concurrent API client sessions
    pool: mpsc::channel();
}

impl ApiClient {
    async fn fetch_data(&self) -> Result<Vec<Record>, Box<dyn std::error::Error>> {
        let mut receiver = self.pool.receiver();
        let sender = receiver.1;

        // Create a new connection from the pool and fetch data asynchronously
        let task = async move {
            while let Some(conn) = receiver.next().await {
                conn.get_async("https://api.example.com/data").await?;
            }
            Ok(())
        };

        // Spawn the task and handle errors
        tokio::spawn(task);
        sender.close();
    }
}
