import os
import hashlib
import time
from concurrent.futures import ThreadPoolExecutor

class FileHasher:
    def __init__(self, file_path):
        self.file_path = file_path

    def get_hash(self):
        with open(self.file_path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

class DistributedFileHasher:
    def __init__(self, storage_system, logging_infrastructure):
        self.storage_system = storage_system
        self.logging_infrastructure = logging_infrastructure

    def get_hash(self, file_path):
        try:
            # Check if the file exists in the distributed storage system
            if not self.storage_system.file_exists(file_path):
                raise FileNotFoundError("File does not exist")

            # Calculate the MD5 hash of the file
            with open(file_path, 'rb') as f:
                return hashlib.md5(f.read()).hexdigest()
        except Exception as e:
            self.logging_infrastructure.log_error("Error calculating hash for {}: {}".format(file_path, str(e)))
            raise

class FileHashingService:
    def __init__(self):
        self.executor = ThreadPoolExecutor(max_workers=10)

    def get_hash(self, file_path):
        future = self.executor.submit(FileHasher(file_path).get_hash)
        return future.result()

    def distributed_get_hash(self, storage_system, logging_infrastructure, file_path):
        future = self.executor.submit(DistributedFileHasher(storage_system, logging_infrastructure).get_hash, file_path)
        return future.result()
