  // ImageMagick library for image conversion
  #include <magick/api.h>

  // Struct to represent an image with properties
  struct Image {
    std::string filePath;
    int width;
    int height;
    int channels;
    unsigned char* data;
  };

  // Function to read an image from a file and convert it to TIFF format if necessary
  void readImage(std::string filePath, Image& image) {
    MagickWandGenesis();
    std::unique_ptr<MagickWand, decltype(&DestroyMagickWand)> magickWand(NewMagickWand(), &DestroyMagickWand);

    // Read the image from file and check for errors
    MagickBooleanType status = MagickReadImage(magickWand.get(), filePath.c_str());
    if (status == MagickFalse) {
      throw std::runtime_error("Error reading image: " + std::string(MagickGetException(magickWand.get(), &exceptionInfo)));
    }

    // Convert the image to TIFF format if necessary
    std::string format = MagickGetImageFormat(magickWand.get());
    if (format != "TIFF") {
      status = MagickSetImageFormat(magickWand.get(), "TIFF");
      if (status == MagickFalse) {
        throw std::runtime_error("Error converting image to TIFF format: " + std::string(MagickGetException(magickWand.get(), &exceptionInfo)));
      }
    }

    // Get the image properties and allocate memory for the data
    MagickGetImageDimension(magickWand.get(), &image.width, &image.height);
    image.channels = MagickGetImageChannelDepth(magickWand.get(), ChannelType::UndefinedChannel);
    image.data = new unsigned char[image.width * image.height * image.channels];

    // Read the image data into memory and check for errors
    status = MagickExportImagePixels(magickWand.get(), 0, 0, image.width, image.height, "TIFF", CharPixel, image.data);
    if (status == MagickFalse) {
      throw std::runtime_error("Error reading image data: " + std::string(MagickGetException(magickWand.get(), &exceptionInfo)));
    }

    // Clean up the MagickWand and return the image properties
    DestroyMagickWand(magickWand.release());
    MagickWandTerminus();
  }

  // Function to write an image to a file in TIFF format
  void writeImage(std::string filePath, Image& image) {
    MagickWandGenesis();
    std::unique_ptr<MagickWand, decltype(&DestroyMagickWand)> magickWand(NewMagickWand(), &DestroyMagickWand);

    // Create a new image in TIFF format and set its properties
    MagickSetImageFormat(magickWand.get(), "TIFF");
    MagickSetSizeOffset(magickWand.get(), image.width, image.height, 0);

    // Write the image data to memory and check for errors
    MagickBooleanType status = MagickImportImagePixels(magickWand.get(), 0, 0, image.width, image.height, "TIFF", CharPixel, image.data);
    if (status == MagickFalse) {
      throw std::runtime_error("Error writing image data: " + std::string(MagickGetException(magickWand.get(), &exceptionInfo)));
    }

    // Write the image to file and check for errors
    status = MagickWriteImage(magickWand.get(), filePath.c_str());
    if (status == MagickFalse) {
      throw std::runtime_error("Error writing image to file: " + std::string(MagickGetException(magickWand.get(), &exceptionInfo)));
    }

    // Clean up the MagickWand and return
    DestroyMagickWand(magickWand.release());
    MagickWandTerminus();
  }

  // Function to analyze an image and calculate its properties
  void analyzeImage(Image& image) {
    // Calculate the average brightness of the image using the Luminance function
    int numPixels = image.width * image.height;
    double averageBrightness = 0;
    for (int i = 0; i < numPixels; i++) {
      averageBrightness += image.data[i];
    }
    averageBrightness /= numPixels;

    // Calculate the standard deviation of the brightness values using the Luminance function
    double stdDev = 0;
    for (int i = 0; i < numPixels; i++) {
      stdDev += pow(image.data[i] - averageBrightness, 2);
    }
    stdDev /= numPixels;
    stdDev = sqrt(stdDev);

    // Output the image properties to console
    printf("Image Properties:\n");
    printf("\tWidth: %d\n", image.width);
    printf("\tHeight: %d\n", image.height);
    printf("\tChannels: %d\n", image.channels);
    printf("\tAverage Brightness: %.2f\n", averageBrightness);
    printf("\tStandard Deviation of Brightness: %.2f\n", stdDev);
  }

  // Function to process an image and perform analysis on it
  void processImage(std::string filePath, Image& image) {
    try {
      readImage(filePath, image);
      analyzeImage(image);
    } catch (const std::exception& e) {
      std::cout << "Error processing image: " << e.what() << "\n";
    }
  }

  // Function to process multiple images and perform analysis on them
  void processImages(std::vector<std::string>& filePaths, std::map<std::string, Image>& images) {
    for (const auto& filePath : filePaths) {
      try {
        Image image;
        readImage(filePath, image);
        images[filePath] = image;
      } catch (const std::exception& e) {
        std::cout << "Error processing image: " << e.what() << "\n";
      }
    }
  }

  // Function to write a report of the processed images and their properties
  void writeReport(std::map<std::string, Image>& images) {
    std::cout << "Image Report:\n";
    for (const auto& [filePath, image] : images) {
      std::cout << "\t" << filePath << "\n";
      analyzeImage(image);
    }
  }

  // Function to process a single image and perform analysis on it in a separate thread
  void processImageThreaded(std::string filePath, Image& image) {
    try {
      readImage(filePath, image);
      analyzeImage(image);
    } catch (const std::exception& e) {
      std::cout << "Error processing image: " << e.what() << "\n";
    }
  }

  // Function to process multiple images and perform analysis on them in separate threads
  void processImagesThreaded(std::vector<std::string>& filePaths, std::map<std::string, Image>& images) {
    std::vector<std::thread> threads;
    for (const auto& filePath : filePaths) {
      try {
        threads.push_back(std::thread(processImageThreaded, filePath, images[filePath]));
      } catch (const std::exception& e) {
        std::cout << "Error processing image: " << e.what() << "\n";
      }
    }
    for (auto& thread : threads) {
      thread.join();
    }
  }

  int main() {
    // Initialize the input and output directories
    std::string inputDir = "/path/to/input/directory";
    std::string outputDir = "/path/to/output/directory";

    // Get a list of all image files in the input directory
    std::vector<std::string> filePaths;
    for (const auto& entry : fs::directory_iterator(inputDir)) {
      if (fs::is_regular_file(entry.status())) {
        filePaths.push_back(entry.path());
      }
    }

    // Process the images in parallel using threads
    std::map<std::string, Image> processedImages;
    processImagesThreaded(filePaths, processedImages);

    // Write a report of the processed images and their properties to console
    writeReport(processedImages);
  }
  ```

This code will read all the image files in the input directory, analyze them using the `analyzeImage` function, and then write a report of the analyzed images and their properties to the output directory. The analysis is performed in parallel using separate threads for each image file, which can significantly speed up the processing time.

