// Generate and populate NFAPI CRC Indication PDUs
forward_list<NFAPI_CRC_Indication_PDU> generate_crc_indication_pdus(const vector<uint16_t>& rx_ue_information_tags, const vector<uint16_t>& rntis) {
    forward_list<NFAPI_CRC_Indication_PDU> pdus;

