            pdu.rnti = rnti;
            pdu.crc_indication_flag = get_random_crc_flag(); // Query external API or use predefined default values
            pdus.push_front(pdu);
        }
    }

    return pdus;
}

// Manage thread pool and task distribution
void manage_thread_pool() {
    static std::mutex mutex;
    static std::vector<std::future<void>> futures;

    while (true) {
        // Wait for next task
        std::unique_lock<std::mutex> lock(mutex);
        if (futures.empty()) {
            mutex.unlock();
            continue;
        }

        // Execute task and remove from futures vector
        futures[0].wait();
        futures.erase(futures.begin());

        // Adjust thread pool size based on current workload
        if (futures.size() < 5) {
            mutex.unlock();
            continue;
        } else if (futures.size() > 10) {
            std::thread t(manage_thread_pool);
            t.detach();
            return;
        }
    }
}

