namespace RemoteDatabaseClient
{
    public class DatabaseConnection
    {
        private readonly string _databaseType;
        private readonly string _connectionString;
        private readonly NetworkService _networkService;

        public DatabaseConnection(string databaseType, string connectionString, NetworkService networkService)
        {
            _databaseType = databaseType;
            _connectionString = connectionString;
            _networkService = networkService;
        }

        public async Task<DataTableReader> ExecuteQueryAsync(string query)
        {
            try
            {
                var request = new HttpRequestMessage();
                request.Method = HttpMethod.Post;
                request.RequestUri = new Uri(_networkService.BaseUrl + "/execute-query");
                request.Content = new StringContent(JsonConvert.SerializeObject(new QueryRequest { Query = query }), Encoding.UTF8, "application/json");
                var response = await _networkService.Client.SendAsync(request);
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStreamAsync().ConfigureAwait(false);
                }
                else
                {
                    throw new Exception("Failed to execute query on remote database");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error executing query: {ex.Message}");
                return null;
            }
        }
    }

    public class NetworkService
    {
        private readonly HttpClient _client;
        private readonly string _baseUrl;

        public NetworkService(string baseUrl)
        {
            _client = new HttpClient();
            _baseUrl = baseUrl;
        }

        public async Task<DataTableReader> ExecuteQueryAsync(string query)
        {
            try
            {
                var request = new HttpRequestMessage();
                request.Method = HttpMethod.Post;
                request.RequestUri = new Uri(_baseUrl + "/execute-query");
                request.Content = new StringContent(JsonConvert.SerializeObject(new QueryRequest { Query = query }), Encoding.UTF8, "application/json");
                var response = await _client.SendAsync(request);
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStreamAsync().ConfigureAwait(false);
                }
                else
                {
                    throw new Exception("Failed to execute query on remote database");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error executing query: {ex.Message}");
                return null;
            }
        }
    }

    public class QueryRequest
    {
        public string Query { get; set; }
    }

    [Fact]
    public async Task ExecuteQuery_ShouldReturnDataTableReader()
    {
        // Arrange
        var databaseConnection = new DatabaseConnection("SQL Server", "connection-string", new NetworkService("http://localhost:5000"));

        // Act
        var result = await databaseConnection.ExecuteQueryAsync("SELECT * FROM customers");

        // Assert
        Assert.NotNull(result);
    }
