package com.example.staticwebsite;

import java.util.*;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.client.discovery.EnableDiscoveryClient;
import org.springframework.web.bind.annotation.*;

@SpringBootApplication
@RestController
@EnableDiscoveryClient
public class StaticWebsiteMicroservice {

    private static final Logger log = LoggerFactory.getLogger(StaticWebsiteMicroservice.class);

    @PostMapping("/deploy")
    public void deploy(@RequestBody Map<String, String> params) {
        String gitRepositoryUrl = params.get("gitRepositoryUrl");
        String domainName = params.get("domainName");
        String branchOrTag = params.get("branchOrTag");
        if (StringUtils.isEmpty(gitRepositoryUrl)) {
            throw new IllegalArgumentException("Missing required parameter 'gitRepositoryUrl'");
        }
        if (StringUtils.isEmpty(domainName)) {
            throw new IllegalArgumentException("Missing required parameter 'domainName'");
        }
        if (StringUtils.isEmpty(branchOrTag)) {
            throw new IllegalArgumentException("Missing required parameter 'branchOrTag'");
        }
        try {
            // Clone the Git repository
            Repository repository = Git.cloneRepository()
                    .setURI(gitRepositoryUrl)
                    .setDirectory(new File(gitRepositoryUrl))
                    .call();

            // Verify the integrity of the repository using checksums
            ObjectId headId = repository.resolve("HEAD");
            if (headId == null) {
                throw new IllegalStateException("Could not resolve HEAD commit for repository " + gitRepositoryUrl);
            }
            RevCommit revCommit = repository.parseCommit(headId);
            String sha1 = revCommit.getId().getName();
            if (!sha1.equalsIgnoreCase(branchOrTag)) {
                throw new IllegalStateException("The HEAD commit does not match the expected branch or tag for repository " + gitRepositoryUrl);
            }

            // Ensure that a 'static.json' configuration file exists at the root of the repository
            File staticConfigFile = new File(gitRepositoryUrl, "static.json");
            if (!staticConfigFile.exists()) {
                throw new IllegalStateException("Could not find 'static.json' configuration file for repository " + gitRepositoryUrl);
            }

            // Configure the CDNs with the static website files
            List<Cdn> cdns = getCdns();
            for (Cdn cdn : cdns) {
                Map<String, String> configParams = new HashMap<>();
                configParams.put("domainName", domainName);
                configParams.put("branchOrTag", branchOrTag);
                configParams.put("gitRepositoryUrl", gitRepositoryUrl);
                cdn.configure(configParams);
            }

            // Log a success message and return the response
            log.info("Successfully deployed static website to CDNs for repository {}", gitRepositoryUrl);
        } catch (Exception e) {
            // Log an error message and return a failure response
            log.error("Failed to deploy static website to CDNs for repository {}", gitRepositoryUrl, e);
        }
    }

    private List<Cdn> getCdns() {
        // TODO: Implement logic to retrieve the list of CDNs from a configuration file or database.
        return Collections.emptyList();
    }
}
