#include <iostream>
#include <string>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <chrono>

using namespace std;

int load_config(const string& endpoint, map<string, vector<pair<string, string>>>& config) {
    int num_sections = 0;

    // Create a HTTP client object
    HttpClient client;

    // Set the timeout for the HTTP request
    client.setTimeout(10);

    try {
        // Send an HTTP GET request to the endpoint
        auto response = client.get(endpoint);

        // Check if the request was successful
        if (response.status() != HttpStatus::OK) {
            throw runtime_error("Failed to load configuration file");
        }

        // Read the response body as a string
        stringstream ss;
        ss << response.body();

        // Parse the configuration file into a map of sections and key-value pairs
        while (ss >> section) {
            vector<pair<string, string>> section_values;

            // Read each line of the section as a key-value pair
            while (ss >> key >> value) {
                section_values.push_back(make_pair(key, value));
            }

            config[section] = move(section_values);
            num_sections++;
        }
    } catch (const exception& e) {
        // Handle network errors and other exceptions
        cout << "Error loading configuration file: " << e.what() << endl;
    }

    return num_sections;
}

int main() {
    const string endpoint = "http://example.com/config.txt";
    map<string, vector<pair<string, string>>> config;

    // Load the configuration file and retrieve the number of sections
    int num_sections = load_config(endpoint, config);

    // Print out the section names and key-value pairs for each section
    for (const auto& section : config) {
        cout << "Section: " << section.first << endl;

        for (const auto& pair : section.second) {
            cout << "\tKey: " << pair.first << ", Value: " << pair.second << endl;
        }
    }

    return 0;
}
```
This code uses the `HttpClient` class from the `httplib` library to send an HTTP GET request to the specified endpoint and read the response body as a string. It then parses the configuration file into a map of sections and key-value pairs using a `stringstream` object. The function returns the number of sections in the configuration file.

The `main()` function demonstrates how to use the `load_config()` function by loading a configuration file from an HTTP endpoint and printing out the section names and key-value pairs for each section.

