class ResourceLimitedImageDownloader {
public:
    // Constructor
    explicit ResourceLimitedImageDownloader(const std::string& baseUrl, const std::string& apiKey);

    // Destructor
    ~ResourceLimitedImageDownloader();

    // Download an image from the internet under a resource constraint
    // @param url: The URL of the image to download
    // @param format: The desired file format (e.g. JPEG, PNG)
    // @param size: The desired file size (in bytes)
    // @return: An optional string containing the downloaded image data, or an empty optional if downloading failed
    std::optional<std::string> download(const std::string& url, const std::string& format, const int size);

private:
    // The base URL of the image server
    std::string m_baseUrl;

    // The API key for authentication with the image server
    std::string m_apiKey;

    // The maximum allowed download speed (in bytes per second)
    int m_maxDownloadSpeed;

    // The maximum allowed file size (in bytes)
    int m_maxFileSize;

    // The current download speed (in bytes per second)
    int m_currentDownloadSpeed;

    // The current download limit (in bytes per second)
    int m_downloadLimit;

    // The last time the download speed was checked
    std::chrono::time_point<std::chrono::system_clock> m_lastCheckTime;

    // The number of successful downloads in the current interval
    int m_numSuccessfulDownloads;

    // The number of failed downloads in the current interval
    int m_numFailedDownloads;

    // The total size of all downloaded images (in bytes)
    int m_totalImageSize;

    // The average download speed over the last 10 seconds (in bytes per second)
    double m_averageDownloadSpeed;

    // The maximum allowed download speed for a single image (in bytes per second)
    int m_maxImageDownloadSpeed;

    // The minimum allowed download speed for a single image (in bytes per second)
    int m_minImageDownloadSpeed;

    // The last time an error occurred during a download attempt
    std::chrono::time_point<std::chrono::system_clock> m_lastErrorTime;

    // The number of retries for each download attempt
    int m_numRetries;

    // The current download retry limit
    int m_downloadRetryLimit;

    // The maximum allowed retry count
    int m_maxRetryCount;

    // The last time a successful download occurred
    std::chrono::time_point<std::chrono::system_clock> m_lastSuccessfulDownloadTime;

    // The current state of the downloader (active/inactive)
    bool m_isActive;
};

#endif // RESOURCE_LIMITED_IMAGE_DOWNLOADER_H
