    : m_baseUrl(baseUrl),
      m_apiKey(apiKey),
      m_maxDownloadSpeed(10 * 1024 * 1024), // 10 MB/s
      m_maxFileSize(5 * 1024 * 1024), // 5 MB
      m_currentDownloadSpeed(m_maxDownloadSpeed),
      m_downloadLimit(m_maxDownloadSpeed),
      m_lastCheckTime(std::chrono::system_clock::now()),
      m_numSuccessfulDownloads(0),
      m_numFailedDownloads(0),
      m_totalImageSize(0),
      m_averageDownloadSpeed(0.0),
      m_maxImageDownloadSpeed(m_maxDownloadSpeed),
      m_minImageDownloadSpeed(m_maxDownloadSpeed),
      m_lastErrorTime(),
      m_numRetries(0),
      m_downloadRetryLimit(5),
      m_maxRetryCount(10),
      m_lastSuccessfulDownloadTime(),
      m_isActive(true) {}

ResourceLimitedImageDownloader::~ResourceLimitedImageDownloader() {
    // Clean up any remaining downloads
}

std::optional<std::string> ResourceLimitedImageDownloader::download(const std::string& url, const std::string& format, const int size) {
    if (!m_isActive) {
        return {};
    }

    // Check the download speed and adjust the download limit accordingly
    checkDownloadSpeed();

    // Set up the cURL handle for the download
    CURL* curl = curl_easy_init();
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeData);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &m_responseBuffer);
    curl_easy_setopt(curl, CURLOPT_USERAGENT, "ResourceLimitedImageDownloader");
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 30L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    // Set the download limit for this specific request
    curl_easy_setopt(curl, CURLOPT_MAXREDIRS, m_maxRedirects);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, m_downloadTimeout * 1000);

    // Perform the download
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        handleError();
        return {};
    }

    // Extract the downloaded image data from the response buffer
    std::string data;
    long responseCode;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &responseCode);
    if (responseCode == 200) {
        data = m_responseBuffer.str();
    } else {
        handleError();
        return {};
    }

    // Check the file size and adjust the download limit accordingly
    long fileSize = data.size();
    if (fileSize > m_maxFileSize) {
        handleError();
        return {};
    }
    double currentDownloadSpeed = fileSize / std::chrono::duration<double>(std::chrono::system_clock::now() - m_lastCheckTime).count();
    if (currentDownloadSpeed > m_maxImageDownloadSpeed) {
        handleError();
        return {};
    }
    m_averageDownloadSpeed = m_averageDownloadSpeed + currentDownloadSpeed;
    m_numSuccessfulDownloads++;

    // Clean up the cURL handle
    curl_easy_cleanup(curl);

    return data;
}
