import org.apache.commons.codec.binary.Hex;
import com.example.passwordverificationservice.PasswordVerificationService;

public class PasswordHasher {
  private static final int HASH_WORK_FACTOR = 12;
  private static final int SALT_LENGTH = 16;

  public static String generateSecurePasswordHash(String password) throws Exception {
    // Generate a salt for the password hash
    byte[] salt = new byte[SALT_LENGTH];
    secureRandom.nextBytes(salt);

    // Use Bcrypt to hash the password with the generated salt
    MessageDigest md = MessageDigest.getInstance("SHA-256");
    md.update((password + Hex.encodeHexString(salt)).getBytes());
    byte[] hashedPassword = md.digest();

    // Verify the password with a third-party service using the generated hash
    PasswordVerificationService service = new PasswordVerificationService();
    String hash = Hex.encodeHexString(hashedPassword);
    if (!service.verifyPassword(password, hash)) {
      throw new Exception("Invalid password");
    }

    // Return the generated hash
    return hash;
  }
}
