  log_filter.addFilter(lambda record: record.levelno >= filter_level)
  syslog_handler.setFormatter(logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s'))

  # Set up the log compression and rotation
  compress_log = True
  rotate_logs = True
