using System;
using System.Threading;
using System.Threading.Tasks;

public class FileAccessManager
{
    private readonly EncryptionService _encryptionService;
    private readonly Dictionary<string, string> _cache;
    private readonly SemaphoreSlim _lock = new SemaphoreSlim(1);

    public FileAccessManager(EncryptionService encryptionService)
    {
        _encryptionService = encryptionService;
        _cache = new Dictionary<string, string>();
    }

    public async Task<byte[]> ReadFileAsync(string filePath)
    {
        var key = GetKeyForFile(filePath);
        var iv = GetIvForFile(filePath);
        return await _encryptionService.DecryptAsync(key, iv);
    }

    public async Task WriteFileAsync(string filePath, byte[] data)
    {
        var key = GetKeyForFile(filePath);
        var iv = GetIvForFile(filePath);
        await _encryptionService.EncryptAndSaveAsync(key, iv, data);
    }

    public async Task DeleteFileAsync(string filePath)
    {
        var key = GetKeyForFile(filePath);
        var iv = GetIvForFile(filePath);
        await _encryptionService.DeleteAsync(key, iv);
    }

    private string GetKeyForFile(string filePath)
    {
        if (_cache.TryGetValue(filePath, out var key))
            return key;

        var keys = await _encryptionService.FetchKeysAsync();
        foreach (var kvp in keys)
        {
            if (kvp.Key == filePath)
                return kvp.Value;
        }

        throw new Exception($"No encryption key found for file: {filePath}");
    }

    private string GetIvForFile(string filePath)
    {
        var ivs = await _encryptionService.FetchIvsAsync();
        foreach (var kvp in ivs)
        {
            if (kvp.Key == filePath)
                return kvp.Value;
        }

        throw new Exception($"No initialization vector found for file: {filePath}");
    }

    private async Task<Dictionary<string, string>> FetchKeysAsync()
    {
        var keys = await _encryptionService.FetchKeysAsync();
        foreach (var kvp in keys)
        {
            if (_cache.ContainsKey(kvp.Key))
                continue;
            _cache[kvp.Key] = kvp.Value;
        }
        return keys;
    }

    private async Task<Dictionary<string, string>> FetchIvsAsync()
    {
        var ivs = await _encryptionService.FetchIvsAsync();
        foreach (var kvp in ivs)
        {
            if (_cache.ContainsKey(kvp.Key))
                continue;
            _cache[kvp.Key] = kvp.Value;
        }
        return ivs;
    }
}
