    public void addMicroService(String serviceName, String endpoint) {
        MicroService ms = new MicroService(serviceName, endpoint);
        microServices.add(ms);
    }

    // Remove a microservice from the aggregation list
    public void removeMicroService(String serviceName) {
        for (MicroService ms : microServices) {
            if (ms.getName().equals(serviceName)) {
                microServices.remove(ms);
                break;
            }
        }
    }

    // Aggregate log events from all microservices and store them in the eventMap
    public void aggregateLogEvents() {
        for (MicroService ms : microServices) {
            List<LogEvent> events = ms.getLogEvents();
            if (events != null && !events.isEmpty()) {
                synchronized (lock) {
                    for (LogEvent event : events) {
                        eventMap.computeIfAbsent(event.getServiceName(), k -> new ArrayList<>()).add(event);
                    }
                }
            }
        }
