import java.io.File;
import java.util.List;
import java.util.concurrent.*;
import org.eclipse.jgit.api.Git;
import org.eclipse.jgit.lib.Repository;
import org.eclipse.jgit.transport.UsernamePasswordCredentialsProvider;
import com.amazonaws.services.s3.AmazonS3Client;
import com.amazonaws.services.s3.model.PutObjectRequest;
import com.google.common.util.concurrent.RateLimiter;

public class StaticContentDeployer {
    private static final int CONCURRENT_THREADS = 10;
    private static final int MAX_RATE_LIMIT = 50;
    private static final String DOMAIN_NAME = "example.com";

    public static void main(String[] args) {
        if (args.length < 4) {
            System.out.println("Usage: java StaticContentDeployer <directory-path> <git-repository-url> <domain-name> <rate-limit>");
            return;
        }

        String directoryPath = args[0];
        String gitRepositoryUrl = args[1];
        String domainName = args[2];
        int rateLimit = Integer.parseInt(args[3]);

        List<File> files = listFiles(directoryPath);
        RateLimiter limiter = RateLimiter.create(rateLimit);

        for (File file : files) {
            limiter.acquire();
            deployStaticContent(file, gitRepositoryUrl, domainName);
        }
    }

    private static void deployStaticContent(File file, String gitRepositoryUrl, String domainName) {
        try {
            Git git = Git.open(new File(gitRepositoryUrl));
            Repository repository = git.getRepository();
            UsernamePasswordCredentialsProvider credentials = new UsernamePasswordCredentialsProvider("username", "password");
            String commitMessage = "Automatic deployment of static content";

            // Clone the repository and verify its integrity
            Git.cloneRepository()
                    .setURI(gitRepositoryUrl)
                    .setDirectory(new File(directoryPath))
                    .setCredentialsProvider(credentials)
                    .call();

            // Ensure that a `static.json` configuration file exists at the root of the repository
            if (!new File(directoryPath + "/static.json").exists()) {
                System.out.println("Missing static.json configuration file");
                return;
            }

            // Modify the file as needed based on its format
            String modifiedFilename = modifyFile(file, domainName);

            // Push changes to the repository
            git.add().addFilepattern(modifiedFilename).call();
            git.commit().setMessage(commitMessage).call();
            git.push().setCredentialsProvider(credentials).call();

            // Upload modified file to the CDN
            AmazonS3Client s3 = new AmazonS3Client();
            PutObjectRequest request = new PutObjectRequest(DOMAIN_NAME, modifiedFilename, file);
            s3.putObject(request);
        } catch (Exception e) {
            System.out.println("Error deploying static content: " + e.getMessage());
        }
    }

    private static String modifyFile(File file, String domainName) throws Exception {
        // Modify the file as needed based on its format
        String modifiedFilename = "";
        if (file.getName().endsWith(".txt")) {
            modifiedFilename = "modified-" + file.getName();
            FileWriter writer = new FileWriter(new File(directoryPath, modifiedFilename));
            BufferedReader reader = new BufferedReader(new FileReader(file));
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.contains("domain")) {
                    line = line.replaceAll("domain", domainName);
                }
                writer.write(line + "\n");
            }
            writer.close();
        } else if (file.getName().endsWith(".csv")) {
            modifiedFilename = "modified-" + file.getName();
            FileWriter writer = new FileWriter(new File(directoryPath, modifiedFilename));
            BufferedReader reader = new BufferedReader(new FileReader(file));
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.contains("domain")) {
                    line = line.replaceAll("domain", domainName);
                }
                writer.write(line + "\n");
            }
            writer.close();
        } else if (file.getName().endsWith(".jpg")) {
            // Modify the file as needed for image files
        }
        return modifiedFilename;
    }

    private static List<File> listFiles(String directoryPath) {
        File[] files = new File(directoryPath).listFiles();
        List<File> filteredFiles = new ArrayList<>();
        for (File file : files) {
            if (file.isDirectory()) {
                filteredFiles.addAll(listFiles(file.getAbsolutePath()));
            } else {
                filteredFiles.add(file);
            }
        }
        return filteredFiles;
    }
}
```
