#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define constants for the file and database
#define FILE_NAME "input.txt"
#define DATABASE_NAME "output.db"
#define QUERY_INSERT "insert into output values (?, ?, ?)"
#define QUERY_SELECT "select * from output"
#define QUERY_DELETE "delete from output"
#define BUFFER_SIZE 1024

// Define the structure to hold the sensor data
typedef struct {
    char *line;
    int lineLength;
} LineData;

// Function to process a single line of data
void processLine(char *line, int lineLength) {
    // Split the line into fields using tab-delimited format
    char **fields = strtok(line, "\t");

    // Calculate the average of the last two numerical fields
    float total = 0.0;
    int fieldCount = 0;
    while (fields[fieldCount] != NULL) {
        if (!isNumeric(fields[fieldCount])) {
            continue;
        }
        total += atof(fields[fieldCount]);
        fieldCount++;
        if (fieldCount > 2) {
            break;
        }
    }
    if (fieldCount < 2) {
        // Skip this line since it has fewer than two numerical fields
        return;
    }
    float average = total / 2.0;

    // Insert the average into the database
    sqlite3 *db;
    char *zErrMsg = NULL;
    int rc = sqlite3_open(DATABASE_NAME, &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error opening database: %s\n", sqlite3_errmsg(db));
        return;
    }
    char *query = sqlite3_mprintf(QUERY_INSERT, average);
    rc = sqlite3_exec(db, query, NULL, NULL, &zErrMsg);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error inserting into database: %s\n", zErrMsg);
    } else {
        printf("Inserted average of %.2f into database.\n", average);
    }
    sqlite3_close(db);
}

// Function to read the input file and process each line
void readFileAndProcessLines() {
    FILE *file = fopen(FILE_NAME, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Read the entire file into memory using malloc and realloc
    size_t fileSize = 0;
    char *buffer = NULL;
    while (!feof(file)) {
        fgets(buffer, BUFFER_SIZE, file);
        buffer = (char *)realloc(buffer, ++fileSize);
    }
    buffer[--fileSize] = '\0'; // Remove the newline character at the end of the buffer

    // Split the file into lines and process each line separately
    char *line = strtok(buffer, "\n");
    while (line != NULL) {
        processLine(line, strlen(line));
        line = strtok(NULL, "\n");
    }
    free(buffer);
}

// Main function to read the file and process each line concurrently
void main() {
    // Create a thread pool for processing lines in parallel
    int numThreads = 4;
    pthread_t threads[numThreads];

    // Read the input file and split it into lines
    char *fileBuffer = (char *)malloc(sizeof(char) * BUFFER_SIZE);
    size_t fileSize = fread(fileBuffer, 1, BUFFER_SIZE, stdin);
    if (ferror(stdin)) {
        perror("Error reading from stdin");
        return;
    }
    char **lines = strtok(fileBuffer, "\n");

    // Initialize the thread pool and spawn threads to process each line
    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threads[i], NULL, readFileAndProcessLines, lines);
    }

    // Wait for all threads to complete and free the buffer
    for (int i = 0; i < numThreads; i++) {
        void *status;
        pthread_join(threads[i], &status);
    }
    free(fileBuffer);
}
```
This code uses a combination of `fread`, `strtok`, and `pthread` to read the input file, split it into lines, and process each line concurrently using threads. It also uses `sqlite3` to interact with an external database. The `processLine` function calculates the average of the last two numerical fields in a line and inserts it into the database using prepared statements. The `readFileAndProcessLines` function reads the input file and splits it into lines, then spawns threads to process each line using the `pthread_create` and `pthread_join` functions. Finally, the `main` function initializes the thread pool and waits for all threads to complete before freeing the buffer.

The code includes robust error handling to manage various scenarios, such as file not found or permission issues, using the `perror` function to print an error message. It also provides options for logging, outputting progress information, and configuring the threshold for numerical field counts.

