  // Get access token using authorization code
  $accessToken = $oauthClient->getAccessTokenUsingAuthorizationCode($authorizationCode);

  // Cache access token for future use
  $tokenCache[$userInfo['id']] = $accessToken;

  return $accessToken;
}

