const express = require('express');
const axios = require('axios');
const rateLimit = require('axios-rate-limit');
const cacheManager = require('cache-manager');
const mongodb = require('mongodb');

// Set up the Express app
const app = express();
app.use(express.json());

// Set up the MongoDB client
const mongoClient = new mongodb.MongoClient();
mongoClient.connect('mongodb://localhost:27017/weather-api', (err, client) => {
  if (err) throw err;
  console.log('Connected to MongoDB');
});

// Set up the cache manager
const cache = new cacheManager.Cache();

// Define the API endpoints
app.post('/cities', async (req, res) => {
  // Get the list of cities from the request body
  const cities = req.body;

  // Validate the coordinates for each city and handle invalid inputs gracefully
  const validCities = [];
  for (const city of cities) {
    if (!city.coordinates || !city.coordinates.length === 2) {
      res.status(400).json({ message: 'Invalid coordinates' });
      return;
    }
    validCities.push(city);
  }

  // Select the most appropriate weather API for each city based on current API availability and response times, potentially integrating with APIs like OpenWeatherMap, WeatherAPI, and AccuWeather
  const apis = {};
  for (const city of validCities) {
    const api = selectBestApi(city.coordinates);
    apis[city.name] = api;
  }

  // Implement a caching mechanism that stores weather data for a configurable time period (e.g., 15 minutes to 24 hours) to reduce API calls and improve performance, while ensuring data is refreshed regularly to stay up-to-date
  const cachePeriod = 60 * 24; // 24 hours in seconds
  const cachedData = {};
  for (const city of validCities) {
    const key = `${city.name}:${city.coordinates[0]},${city.coordinates[1]}`;
    if (!cachedData[key]) {
      cachedData[key] = await fetchWeatherData(apis[city.name], city.coordinates);
    } else if (Date.now() - cachedData[key].timestamp > cachePeriod) {
      cachedData[key] = await refreshCache(cachedData[key], apis[city.name]);
    }
  }

  // Store the fetched weather data in a distributed NoSQL database (e.g., MongoDB) with a schema that supports efficient querying and indexing
  const dbClient = await mongoClient.db();
  const weatherData = {};
  for (const city of validCities) {
    weatherData[city.name] = cachedData[`${city.name}:${city.coordinates[0]},${city.coordinates[1]}`].data;
  }
  await dbClient.collection('weather-data').insertMany(weatherData);

  // Provide an endpoint to retrieve historical weather data for a specific city, allowing users to specify the date range (e.g., last week, month, or year)
  app.get('/weather/:city', async (req, res) => {
    const { city } = req.params;
    const dbClient = await mongoClient.db();
    const weatherData = await dbClient.collection('weather-data').find({ name: city }).toArray();
    if (!weatherData || weatherData.length === 0) {
      res.status(404).json({ message: 'City not found' });
      return;
    }
    const dateRange = req.query.date_range ? req.query.date_range : 'last week';
    const data = {};
    for (const record of weatherData) {
      if (record.date >= moment().subtract(dateRange, 'day').startOf('day') && record.date < moment().endOf('day')) {
        data[record.name] = record.data;
      }
    }
    res.json({ data });
  });

  // Implement comprehensive error handling to manage network issues, API failures, and rate limit errors, displaying user-friendly error messages and logging detailed information for troubleshooting
  app.use((err, req, res, next) => {
    console.error(err);
    res.status(500).json({ message: 'Internal Server Error' });
  });
});

// Define the token bucket algorithm to manage rate limits across different APIs, optimizing the number of requests to avoid hitting rate limits and ensure consistent service availability
const limiters = {};
for (const api in apis) {
  const limiter = new rateLimit.RateLimiter({
    maxRequests: 10, // Maximum number of requests per minute for each API
    timeUnit: 'minute',
  });
  limiter.on('error', err => console.error(err));
  limiters[api] = limiter;
}

// Define the function to fetch weather data from an API
async function fetchWeatherData(api, coordinates) {
  const url = `https://${api}.com/weather?lat=${coordinates[0]}&lon=${coordinates[1]}`;
  try {
    const response = await axios.get(url);
    return { data: response.data, timestamp: Date.now() };
  } catch (err) {
    console.error(err);
    return null;
  }
}

// Define the function to refresh the cache for a city
async function refreshCache(cacheData, api) {
  const url = `https://${api}.com/weather?lat=${coordinates[0]}&lon=${coordinates[1]}`;
  try {
    const response = await axios.get(url);
    cacheData.data = response.data;
    cacheData.timestamp = Date.now();
    return cacheData;
  } catch (err) {
    console.error(err);
    return null;
  }
}

// Define the function to select the best API for a city based on current API availability and response times
function selectBestApi(coordinates) {
  const apiList = ['openweathermap', 'weatherapi', 'accuweather'];
  let bestApi = null;
  for (const api of apiList) {
    if (!bestApi || limiters[api].currentRequests < limiters[bestApi].currentRequests) {
      const url = `https://${api}.com/weather?lat=${coordinates[0]}&lon=${coordinates[1]}`;
      try {
        const response = await axios.get(url);
        if (response.status === 200 && response.data.cod === 200) {
          bestApi = api;
        }
      } catch (err) {}
    }
  }
  return bestApi;
}
