using UnityEngine;

public class RandomValueGenerator
{
    private int minValue;
    private int maxValue;

    public RandomValueGenerator(int minValue, int maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public async Task<int> GenerateRandomIntAsync()
    {
        return UnityEngine.Random.Range(this.minValue, this.maxValue + 1);
    }

    public async Task<int> GenerateRandomIntExclusiveAsync()
    {
        return UnityEngine.Random.Range(this.minValue, this.maxValue);
