    };

    public async Task<(int samplePerPixel, int bitsPerSample)> ParseTiffImageAsync(string filePath)
    {
        // Use a third-party image conversion library to convert the input JPEG image to TIFF format.
        var tiffFilePath = ConvertJpegToTiff(filePath);

        // Load the TIFF image and extract details on its bits per sample and sample per pixel.
        using (var image = ImageMagick.ReadImage(tiffFilePath))
        {
            var samplePerPixel = image.GetPropertyInt(ImageMagick.Property.SAMPLES_PER_PIXEL);
            var bitsPerSample = image.GetPropertyInt(ImageMagick.Property.BITS_PER_SAMPLE);
            return (samplePerPixel, bitsPerSample);
        }
    }

    public async Task<bool> IsSupportedImageTypeAsync(string filePath)
    {
        // Use a third-party image conversion library to convert the input JPEG image to TIFF format.
        var tiffFilePath = ConvertJpegToTiff(filePath);

        // Check if the TIFF image has extra samples and store this information in the provided struct.
        using (var image = ImageMagick.ReadImage(tiffFilePath))
        {
            var hasExtraSamples = image.HasProperty(ImageMagick.Property.EXTRA_SAMPLES);
            return !hasExtraSamples;
        }
    }

    private string ConvertJpegToTiff(string filePath)
    {
        // Use a third-party image conversion library to convert the input JPEG image to TIFF format.
        var tempFilePath = Path.GetTempFileName();
        using (var converter = new ImageMagick.ImageConverter())
        {
            converter.Convert(filePath, tempFilePath);
        }
        return tempFilePath;
    }
}
