struct User {
    std::string username;
    std::string email;
    std::time_t lastUpdatedTime;

    // Custom comparator for comparing users based on their username.
    bool operator==(const User& other) const {
        return username == other.username;
    }
};

// Update the email addresses of users in the local cache based on data from an external API.
void updateUserEmails(std::forward_list<User>& localCache, const std::map<std::string, std::string>& apiData, std::mutex& mutex) {
    // Lock the mutex to avoid concurrent modifications to the user database.
    std::lock_guard<std::mutex> lock(mutex);

    // Iterate over the external API data and update the email addresses of matching users in the local cache.
    for (const auto& [username, newEmail] : apiData) {
        // Find the user with the matching username in the local cache.
        auto it = std::find_if(localCache.begin(), localCache.end(), [&](const User& user) { return user.username == username; });

        // If a matching user is found, update its email address and set the last updated time to the current timestamp.
        if (it != localCache.end()) {
            it->email = newEmail;
            it->lastUpdatedTime = std::time(nullptr);
        }
    }
}
