        public int NextInt() => GetRandomValue(int.MinValue, int.MaxValue);

        // Method to return a random double value within the specified range, with support for exclusive and inclusive boundaries
        public double NextDouble() => GetRandomValue(double.MinValue, double.MaxValue);

        // Method to seed the random number generator with a given value to ensure reproducibility in testing and simulations
        public void Seed(int seed) => new Random(seed).Next();

        // Method to generate random values from a normal distribution centered around the specified range, with customizable mean and standard deviation
        public double NextNormal(double mean = 0.0, double stdDev = 1.0) => GetRandomValue(mean - stdDev, mean + stdDev);

