        private float GetRandomValue(float minValue, float maxValue, Func<double, double> pdf = null)
        {
            if (minValue >= maxValue) throw new ArgumentException("Minimum value must be less than the maximum value");
            if (!Enum.IsDefined(typeof(GenerationType), _generationType)) throw new ArgumentException("Invalid generation type specified");

            // Generate a random value within the specified range, using the appropriate generation method based on the provided parameters
            switch (_generationType)
            {
                case GenerationType.Uniform:
                    return Uniform(minValue, maxValue);
                case GenerationType.Normal:
                    return Normal(mean, stdDev);
                case GenerationType.Custom:
                    return Custom(pdf);
            }
        }

        // Method to generate random values from a uniform distribution within the specified range
        private float Uniform(float minValue, float maxValue) => (float)_random.NextDouble() * (maxValue - minValue) + minValue;

        // Method to generate random values from a normal distribution centered around the specified mean and standard deviation
        private double Normal(double mean = 0.0, double stdDev = 1.0) => _normalDistribution.NextDouble() * stdDev + mean;

        // Method to apply custom probability density functions (PDFs) for generating random values, allowing users to define their own distribution logic
        private double Custom(Func<double, double> pdf) => pdf(_random.NextDouble()) * _maxValue - _minValue;

        // Overriding the ToString method to display the current range, generation type (uniform, normal, or weighted), and additional details like mean, standard deviation, and custom PDF for normal and custom distributions
        public override string ToString() => $"Range: [{_minValue}, {_maxValue}] Generation Type: {(_generationType == GenerationType.Uniform ? "Uniform" : (_generationType == GenerationType.Normal ? "Normal" : "Custom"))} Mean: {_normalDistribution.Mean} StdDev: {_normalDistribution.StandardDeviation}";

        // Implementing caching to store and reuse pre-generated sequences of random numbers for performance optimization, especially when generating a large number of random values
        private readonly List<float> _cache = new List<float>();

        // Methods to manage the cache, ensuring that it is managed efficiently to avoid memory leaks and provide configurable cache size limits
        public void CacheClear() => _cache.Clear();
        public int CacheSize => _cache.Count;

        // Implementing thread safety for multi-threaded access, using locking mechanisms and concurrent collections to manage shared resources
        private readonly object _lock = new object();
        private readonly ConcurrentDictionary<float, float> _concurrentCache = new ConcurrentDictionary<float, float>();

        // Methods to ensure that the class adheres to [TODO] principles and supports different data types (float, int, double) seamlessly and ensuring integration with external systems that require random value generation
        public void Seed(int seed) => new Random(seed).Next();
        public float NextFloat() => GetRandomValue(float.MinValue, float.MaxValue);
        public int NextInt() => GetRandomValue(int.MinValue, int.MaxValue);
        public double NextDouble() => GetRandomValue(double.MinValue, double.MaxValue);

        // Method to handle different data types (float, int, double) seamlessly and ensuring integration with external systems that require random value generation
        private T ConvertTo<T>(float value) where T : struct
        {
            if (typeof(T) == typeof(float)) return (T)(object)value;
            else if (typeof(T) == typeof(int)) return (T)(object)Convert.ToInt32(Math.Round(value));
            else if (typeof(T) == typeof(double)) return (T)(object)value;
        }

        // Method to support integration with external systems that require random value generation
        public T Next<T>(float minValue, float maxValue) where T : struct => ConvertTo<T>(GetRandomValue(minValue, maxValue));
    }
}
