void read_integers_from_file(const char* filepath, int** arr) {
    // Open the input file for reading
    FILE *input_file = fopen(filepath, "r");
    if (input_file == NULL) {
        perror("Failed to open input file for reading.");
        exit(1);
    }

    // Read the first line of the file and check its length
    char* line = malloc(sizeof(char)*1024);
    int line_length = fgets(line, 1024, input_file);
    if (line_length == 0) {
        perror("Failed to read from input file.");
        exit(1);
    }

    // Count the number of integers in the first line and allocate memory for the array
    int num_integers = count_integers(line);
    *arr = malloc(sizeof(int)*num_integers);

    // Read the remaining lines of the file and store the integers in the array
    while (fgets(line, 1024, input_file) != NULL) {
        int* arr_ptr = *arr;
        for (int i = 0; i < num_integers; i++) {
            char* token = strtok(line, " ");
            if (token == NULL) {
                break;
            }
            arr_ptr[i] = atoi(token);
            line = NULL;
        }
    }

    // Close the input file and return the array
    fclose(input_file);
}

