void process_input_file(const char* input_filepath, int log_level) {
    // Initialize variables for storing the array of integers and the largest integer
    int* arr = NULL;
    int largest = 0;

    // Open the input file for reading
    FILE *input_file = fopen(input_filepath, "r");
    if (input_file == NULL) {
        perror("Failed to open input file for reading.");
        exit(1);
    }

    // Read the first line of the file and check its length
    char* line = malloc(sizeof(char)*1024);
    int line_length = fgets(line, 1024, input_file);
    if (line_length == 0) {
        perror("Failed to read from input file.");
        exit(1);
    }

    // Check if the first line of the file is a valid integer
    char* endptr = NULL;
    int num = strtol(line, &endptr, 10);
    if (num < INT_MIN || num > INT_MAX || *endptr != '\n') {
        fprintf(stderr, "Error: Invalid integer format\n");
        exit(1);
    }

    // Initialize the array of integers and find the largest integer in it
    arr = malloc(sizeof(int)*line_length);
    for (int i = 0; i < line_length; i++) {
        num = strtol(line, &endptr, 10);
        if (num < INT_MIN || num > INT_MAX || *endptr != '\n') {
            fprintf(stderr, "Error: Invalid integer format\n");
            exit(1);
        }
        arr[i] = num;
        if (arr[i] > largest) {
            largest = arr[i];
        }
