        exit(1);
    }

    // Check if the first line of the file is a valid integer
    char* endptr = NULL;
    int num = strtol(line, &endptr, 10);
    if (num < INT_MIN || num > INT_MAX || *endptr != '\n') {
        fprintf(stderr, "Error: Invalid integer format\n");
        exit(1);
    }

    // Initialize the array of integers and find the largest integer in it
    arr = malloc(sizeof(int)*line_length);
    for (int i = 0; i < line_length; i++) {
        num = strtol(line, &endptr, 10);
        if (num < INT_MIN || num > INT_MAX || *endptr != '\n') {
            fprintf(stderr, "Error: Invalid integer format\n");
            exit(1);
        }
        arr[i] = num;
    }

    // Print the weaknesses of the Pokemon based on its type
    int* weaknesses = NULL;
    get_pokemon_weaknesses(pokemon_type, &weaknesses);
    if (weaknesses != NULL) {
        printf("The weaknesses of %s are ", pokemon_type);
        for (int i = 0; i < 2; i++) {
            printf("%d ", weaknesses[i]);
        }
        printf("\n");
    } else {
        printf("No weaknesses found\n");
    }

    // Close the input file
    fclose(input_file);
}

// Define a function to print the usage instructions
void print_usage(const char* executable_name) {
    printf("Usage: %s <command> [<options>]\n", executable_name);
    printf("\n");
    printf("Where <command> is one of the following:\n");
    printf("\n");
    printf("  largest-integer          Find the largest integer in an input file\n");
    printf("  weaknesses                Print the weaknesses of a Pokemon based on its type\n");
    printf("\n");
    printf("The following options are available for each command:\n");
    printf("\n");
    printf("  -f, --file <filename>     Input file name (required for 'largest-integer' and 'weaknesses')\n");
    printf("  -t, --type <pokemon_type>  Type of Pokemon to get weaknesses for (required for 'weaknesses')\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage(argv[0]);
        return 1;
    }

    // Check the command and options
    const char* command = argv[1];
    const char* input_file = NULL;
    const char* pokemon_type = NULL;

    for (int i = 2; i < argc; i++) {
        if (!strcmp(argv[i], "-f") || !strcmp(argv[i], "--file")) {
            input_file = argv[++i];
        } else if (!strcmp(argv[i], "-t") || !strcmp(argv[i], "--type")) {
            pokemon_type = argv[++i];
        } else {
            print_usage(argv[0]);
            return 1;
        }
    }

    // Execute the command
    if (!strcmp(command, "largest-integer")) {
        if (input_file == NULL) {
            fprintf(stderr, "Error: Missing input file\n");
            print_usage(argv[0]);
            return 1;
        }
        process_input_file(input_file);
    } else if (!strcmp(command, "weaknesses")) {
        if (input_file == NULL || pokemon_type == NULL) {
            fprintf(stderr, "Error: Missing input file or Pokemon type\n");
            print_usage(argv[0]);
            return 1;
        }
        process_input_file_pokemon(input_file, pokemon_type);
    } else {
        fprintf(stderr, "Error: Invalid command\n");
        print_usage(argv[0]);
        return 1;
    }

    return 0;
}

