#include <stdbool.h>
#include "nfapi_crc_indication_pdu.h"
#include "external_data_source.h"

// Thread pool parameters
#define THREAD_POOL_SIZE 10
#define MAX_THREADS 50
#define MIN_THREADS 10
#define QUEUE_SIZE 1000

// Timeout settings for external data source
#define EXTERNAL_DATA_TIMEOUT 5 // seconds
#define CRCFLAG_TIMEOUT 3 // seconds

// Error codes
#define SUCCESS 0
#define FAILURE -1
#define TIMEOUT -2
#define INVALID_PARAMETERS -3
#define NETWORK_LATENCY_ERROR -4
#define FIRMWARE_VERSION_MISMATCH -5

// Logging mechanism
#define LOG_FILE "crc_indication_pdu.log"
#define DEBUG 1

// Function prototypes
void* generateCRCIndicationPDU(void* args);
int generateCRCIndications(uint32_t num_pdus, uint32_t* rx_ue_information_tags, uint16_t* crc_indication_relt8_tags);
int populateCRCIndicationPDU(NFAPI_CRC_INDICATION_PDU* pdu, uint32_t rx_ue_information_tag, uint16_t crc_indication_relt8_tag);
int getCRCFlagFromDataSource(uint32_t rx_ue_information_tag, uint16_t* crc_flag);
void threadPoolInit();
void threadPoolDeinit();
void* threadPoolWorker(void* args);
void threadPoolWait();
bool isQueueFull();

int main() {
  // Initialize thread pool
  threadPoolInit();

  // Generate CRC indications for 10,000 PDUs
  int num_pdus = 10000;
  uint32_t* rx_ue_information_tags = malloc(num_pdus * sizeof(uint32_t));
  uint16_t* crc_indication_relt8_tags = malloc(num_pdus * sizeof(uint16_t));
  generateCRCIndications(num_pdus, rx_ue_information_tags, crc_indication_relt8_tags);

  // Clean up resources
  free(rx_ue_information_tags);
  free(crc_indication_relt8_tags);

  // Deinitialize thread pool
  threadPoolDeinit();

  return SUCCESS;
}

// Generate CRC indications for the given number of PDUs
int generateCRCIndications(uint32_t num_pdus, uint32_t* rx_ue_information_tags, uint16_t* crc_indication_relt8_tags) {
  // Initialize external data source
  initExternalDataSource();

  // Initialize thread pool
  threadPoolInit();

  // Populate PDUs with CRC indications
  for (int i = 0; i < num_pdus; i++) {
    uint32_t rx_ue_information_tag = rx_ue_information_tags[i];
    uint16_t crc_indication_relt8_tag = crc_indication_relt8_tags[i];
    pthread_create(&threadPoolWorker, NULL, generateCRCIndicationPDU, (void*)rx_ue_information_tag);
  }

  // Wait for all PDUs to be generated
  threadPoolWait();

  // Deinitialize external data source
  deinitExternalDataSource();

  return SUCCESS;
}

// Generate a single CRC indication PDU
void* generateCRCIndicationPDU(void* args) {
  uint32_t rx_ue_information_tag = (uint32_t)args;

  // Allocate memory for the PDU
  NFAPI_CRC_INDICATION_PDU* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));

  // Populate the PDU with the given RX UE information tag and CRC indication REL8 tag
  int result = populateCRCIndicationPDU(pdu, rx_ue_information_tag, 0);

  // Handle failure
  if (result != SUCCESS) {
    free(pdu);
    return FAILURE;
  }

  // Return the PDU to the caller
  return pdu;
}

// Populate a CRC indication PDU with the given RX UE information tag and CRC indication REL8 tag
int populateCRCIndicationPDU(NFAPI_CRC_INDICATION_PDU* pdu, uint32_t rx_ue_information_tag, uint16_t crc_indication_relt8_tag) {
  // Set the RX UE information tag in the PDU
  pdu->rx_ue_information.tag = rx_ue_information_tag;

  // Get the CRCFlag from the external data source
  int result = getCRCFlagFromDataSource(rx_ue_information_tag, &pdu->crc_indication_relt8.cr_flag);

  // Handle failure
  if (result != SUCCESS) {
    return FAILURE;
  }

  // Set the CRC indication REL8 tag in the PDU
  pdu->crc_indication_relt8.tag = crc_indication_relt8_tag;

  return SUCCESS;
}

// Get the CRCFlag from the external data source
int getCRCFlagFromDataSource(uint32_t rx_ue_information_tag, uint16_t* crc_flag) {
  // Initialize external data source
  initExternalDataSource();

  // Set timeout for getting CRCFlag
  setGetCRCFlagTimeout(EXTERNAL_DATA_TIMEOUT);

  // Get the CRCFlag from the external data source
  int result = getCRCFlagFromExternalDataSource(rx_ue_information_tag, crc_flag);

  // Handle failure
  if (result != SUCCESS) {
    return FAILURE;
  }

  // Deinitialize external data source
  deinitExternalDataSource();

  return SUCCESS;
}

// Initialize the thread pool for generating CRC indications
void threadPoolInit() {
  // Create a queue to store PDUs to be generated
  pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
  pthread_cond_t* cond = malloc(sizeof(pthread_cond_t));

  // Initialize the queue and the condition variable
  queueInit();
  initCondVar(cond);

  // Start a thread to generate CRC indications
  pthread_create(&threadPoolWorker, NULL, generateCRCIndicationPDU, (void*)mutex);
}

// Deinitialize the thread pool for generating CRC indications
void threadPoolDeinit() {
  // Destroy the queue and the condition variable
  queueDestroy();
  destroyCondVar();
}

// Wait for all PDUs to be generated
void threadPoolWait() {
  // Lock the mutex
  pthread_mutex_lock(mutex);

  // Unlock the mutex when the condition variable is signaled
  pthread_cond_wait(cond, mutex);

  // Destroy the mutex and the condition variable
  pthread_mutex_destroy(mutex);
  destroyCondVar();
}
```

In this example, we use a thread pool to generate CRC indications in parallel. We create a queue to store PDUs to be generated and a condition variable to signal when all PDUs have been generated. We also initialize the external data source and set a timeout for getting CRCFlag.

### Conclusion

In this post, we discussed how to generate CRC indications in parallel using a thread pool. We used a queue to store PDUs to be generated and a condition variable to signal when all PDUs have been generated. We also initialized the external data source and set a timeout for getting CRCFlag.

