```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.serialization.StringDeserializer;

import com.google.gson.Gson;
import com.google.gson.JsonObject;

public class LogProcessingPipeline {
    private static final String BOOTSTRAP_SERVERS = "localhost:9092";
    private static final String TOPIC = "my-logs";
    private static final String GROUP_ID = "log-processing";
    private static final String ELASTICSEARCH_INDEX = "my-index";

    public static void main(String[] args) throws Exception {
        // Set up Kafka consumer
        Properties props = new Properties();
        props.put("bootstrap.servers", BOOTSTRAP_SERVERS);
        props.put("group.id", GROUP_ID);
        props.put("key.deserializer", StringDeserializer.class.getName());
        props.put("value.deserializer", StringDeserializer.class.getName());
        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(props);

        // Set up Elasticsearch client
        RestHighLevelClient esClient = new RestHighLevelClient(
            new HttpHost("localhost", 9200, "http"),
            new BasicCredentialsProvider()
        );

        // Define retention policies for logs
        Map<String, Object> indexRetentionPolicy = new HashMap<>();
        indexRetentionPolicy.put("index.number_of_shards", 3);
        indexRetentionPolicy.put("index.number_of_replicas", 2);
        esClient.indices().create(new CreateIndexRequest(ELASTICSEARCH_INDEX), RequestOptions.DEFAULT);
        esClient.indices().putSettings(new PutMappingRequest(ELASTICSEARCH_INDEX).source(indexRetentionPolicy), RequestOptions.DEFAULT);

        // Define batch size for log processing
        int batchSize = 100;

        // Set up thread pool for log processing
        ExecutorService executor = Executors.newFixedThreadPool(5);

        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
            List<ConsumerRecord<String, String>> recordList = records.records(TOPIC);
            if (recordList.isEmpty()) {
                continue;
            }

            // Process log records in batches
            for (int i = 0; i < recordList.size(); i += batchSize) {
                List<ConsumerRecord<String, String>> batch = recordList.subList(i, Math.min(i + batchSize, recordList.size()));
                executor.submit(() -> processLogRecords(batch));
            }
        }
    }

    private static void processLogRecords(List<ConsumerRecord<String, String>> records) {
        // Parse log records and extract relevant information
        List<Map<String, Object>> logs = new ArrayList<>();
        for (ConsumerRecord<String, String> record : records) {
            Map<String, Object> log = parseLog(record.value());
            if (log != null) {
                logs.add(log);
            }
        }

        // Index logs in Elasticsearch
        esClient.index(new IndexRequest(ELASTICSEARCH_INDEX).source(logs), RequestOptions.DEFAULT);
    }

    private static Map<String, Object> parseLog(String log) {
        try {
            JsonObject json = new Gson().fromJson(log, JsonObject.class);
            // Extract relevant information from log and return it as a map
            Map<String, Object> output = new HashMap<>();
            output.put("timestamp", json.getAsJsonPrimitive("timestamp").toString());
            output.put("message", json.getAsJsonPrimitive("message").toString());
            // ...
            return output;
        } catch (Exception e) {
            System.out.println("Error parsing log: " + log);
            return null;
        }
    }
}
