import requests
from ratelimit import RateLimit
from ratelimit.exceptions import RateLimitException
from flask import Flask, request, jsonify, g
from flask_caching import Cache

app = Flask(__name__)
cache = Cache()

# Set up caching with LRU and LFU eviction policies
cache.config.CACHE_TYPE = "simple"
cache.config.DEFAULT_TIMEOUT = 3600
cache.config.EVICTION_POLICY = "lru"
cache.config.KEY_PREFIX = "weather-api"

# Set up rate limiting with a leaky bucket algorithm
rate_limit = RateLimit(app)

# Define API endpoints for fetching weather data
@app.route("/weather/<zip_code>", methods=["GET"])
def get_weather(zip_code: str):
    # Validate zip code and handle invalid inputs gracefully
    if not zip_code or not zip_code.isdigit():
        return jsonify({"error": "Invalid zip code"}), 400

    # Fetch weather data from multiple APIs using caching and rate limiting
    cache_key = f"weather-{zip_code}"
    cached_data = cache.get(cache_key)
    if cached_data:
        return jsonify({"weather": cached_data})
    else:
        data = {}
        for api in ["openweathermap", "weatherstack"]:
            url = f"https://api.{api}.com/data/2.5/weather?zip={zip_code}&units=imperial&appid=YOUR_API_KEY"
            response = requests.get(url)
            if response.status_code == 200:
                data[api] = response.json()["main"]
            else:
                logging.warning(f"Failed to fetch weather data from {api} API")
        cache.set(cache_key, data)
        return jsonify({"weather": data})

# Define API endpoint for retrieving historical weather data
@app.route("/historical/<zip_code>", methods=["GET"])
def get_historical_weather(zip_code: str):
    # Validate zip code and handle invalid inputs gracefully
    if not zip_code or not zip_code.isdigit():
        return jsonify({"error": "Invalid zip code"}), 400

    # Fetch historical weather data from PostgreSQL database using SQLAlchemy
    db = getattr(g, "db", None)
    if db is None:
        raise RuntimeError("No database connection found")
    query = """SELECT * FROM weather_data WHERE zip_code = %s"""
    result = db.session.execute(query, [zip_code])
    data = [dict(row) for row in result]
    return jsonify({"weather": data})

# Define rate limiting and caching policies for API endpoints
@app.before_request
def before_request():
    # Apply rate limiting to all API endpoints
    if request.endpoint != "static":
        try:
            rate_limit()
        except RateLimitException as e:
            return jsonify({"error": str(e)}), 429

# Define caching policies for API endpoints
@cache.memoize(timeout=3600)
def fetch_weather_data(zip_code: str):
    # Fetch weather data from multiple APIs using caching and rate limiting
    data = {}
    for api in ["openweathermap", "weatherstack"]:
        url = f"https://api.{api}.com/data/2.5/weather?zip={zip_code}&units=imperial&appid=YOUR_API_KEY"
        response = requests.get(url)
        if response.status_code == 200:
            data[api] = response.json()["main"]
        else:
            logging.warning(f"Failed to fetch weather data from {api} API")
    return data

# Define error handling for API endpoints
@app.errorhandler(400)
def bad_request(e):
    return jsonify({"error": "Bad request"}), 400

@app.errorhandler(401)
def unauthorized(e):
    return jsonify({"error": "Unauthorized access"}), 401

@app.errorhandler(403)
def forbidden(e):
    return jsonify({"error": "Forbidden request"}), 403

@app.errorhandler(404)
def not_found(e):
    return jsonify({"error": "Resource not found"}), 404

@app.errorhandler(500)
def internal_server_error(e):
    return jsonify({"error": "Internal server error"}), 500
