        this.file = new File(filename);
        this.channel = AsynchronousFileChannel.open(Paths.get(this.file.getAbsolutePath()), StandardOpenOption.READ, StandardOpenOption.WRITE);
    }

    public void read(long position, int size) {
        ByteBuffer buffer = ByteBuffer.allocate(size);
        channel.read(position, buffer, buffer, new CompletionHandler<Integer, ByteBuffer>() {
            @Override
            public void completed(Integer result, ByteBuffer buffer) {
                // Implement a completion handler for asynchronous file reads
            }

            @Override
            public void failed(Throwable exc, ByteBuffer attachment) {
                // Implement error handling for cases where the read operation fails
            }
        });
    }

    public void write(long position, String data) throws IOException {
        byte[] bytes = data.getBytes();
        ByteBuffer buffer = ByteBuffer.allocate(bytes.length);
        buffer.put(bytes);
        channel.write(position, buffer, buffer, new CompletionHandler<Integer, ByteBuffer>() {
            @Override
            public void completed(Integer result, ByteBuffer buffer) {
                // Implement a completion handler for asynchronous file writes
            }

            @Override
            public void failed(Throwable exc, ByteBuffer attachment) {
                // Implement error handling for cases where the write operation fails
            }
        });
    }
}

