// RemoteExecutor Module
const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');
const http = require('http');
const https = require('https');
const ftp = require('ftp');
const { EventEmitter } = require('events');

class RemoteExecutor extends EventEmitter {
  constructor() {
    super();
    this.commands = {};
    this.config = {};
    this.loadConfig();
  }

  loadConfig() {
    // Load config from JSON file or environment variables
    const configFilePath = path.join(__dirname, 'config.json');
    if (fs.existsSync(configFilePath)) {
      this.config = JSON.parse(fs.readFileSync(configFilePath));
    } else {
      this.config = {
        servers: [
          {
            host: 'example.com',
            port: 22,
            username: 'user1',
            password: 'pass1',
            protocol: 'ssh'
          },
          {
            host: 'example.com',
            port: 443,
            username: 'user2',
            password: 'pass2',
            protocol: 'https'
          }
        ]
      };
    }
  }

  executeRemoteCommand(command) {
    // Create a new child process for the given command
    const child = exec(command);

    // Set up event listeners to handle stdout and stderr output
    let data = '';
    child.stdout.on('data', (chunk) => {
      data += chunk;
    });
    child.stderr.on('data', (chunk) => {
      console.error(chunk);
    });

    // Wait for the command to finish and return its output
    const result = await new Promise((resolve, reject) => {
      child.on('exit', () => {
        resolve(data);
      });
    });

    // Handle errors if any
    if (result.stderr) {
      console.error(`Error executing command: ${command}`);
      this.emit('error', `Error executing command: ${command}`);
    }

    return result;
  }

  executeCommand(command, options = {}) {
    // Check if the given command is available on any of the servers
    const availableServers = this.checkAvailability(command);
    if (!availableServers.length) {
      throw new Error(`No servers available for command: ${command}`);
    }

    // Choose a server and execute the command
    const selectedServer = availableServers[0];
    this.emit('debug', `Executing command on server ${selectedServer}: ${command}`);
    return this.executeRemoteCommand(command, options);
  }

  checkAvailability(command) {
    // Check if the given command is supported by any of the configured servers
    const availableServers = [];
    for (const server of this.config.servers) {
      if (this.commands[server.protocol] && this.commands[server.protocol].hasOwnProperty(command)) {
        availableServers.push(server);
      }
    }
    return availableServers;
  }
}

module.exports = RemoteExecutor;
