```javascript
const { RemoteExecutor } = require('./RemoteExecutor');
const executor = new RemoteExecutor();

describe('RemoteExecutor', () => {
  it('should execute commands on available servers', async () => {
    const command = 'ls -la';
    const options = {};
    const result = await executor.executeCommand(command, options);
    expect(result).toBeTruthy();
  });

  it('should throw error if no servers are available for the given command', async () => {
    const command = 'unknown-command';
    const options = {};
    try {
      await executor.executeCommand(command, options);
    } catch (error) {
      expect(error).toBeTruthy();
    }
  });
});
