using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AdvancedRandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly float _minValue;
        private readonly float _maxValue;
        private readonly bool _isInclusive;
        private readonly bool _isExclusive;
        private readonly bool _generateNormalDistribution;
        private readonly bool _generateCustomDistribution;
        private readonly bool _generateWeightedDistribution;
        private readonly float _mean;
        private readonly float _standardDeviation;
        private readonly Func<float, float> _customPDF;
        private readonly int _cacheSizeLimit;
        private readonly List<float> _preGeneratedSequences = new List<float>();

        public RandomValueGenerator(float minValue, float maxValue, bool isInclusive, bool isExclusive, bool generateNormalDistribution, bool generateCustomDistribution, bool generateWeightedDistribution, float mean, float standardDeviation, Func<float, float> customPDF)
        {
            _minValue = minValue;
            _maxValue = maxValue;
            _isInclusive = isInclusive;
            _isExclusive = isExclusive;
            _generateNormalDistribution = generateNormalDistribution;
            _generateCustomDistribution = generateCustomDistribution;
            _generateWeightedDistribution = generateWeightedDistribution;
            _mean = mean;
            _standardDeviation = standardDeviation;
            _customPDF = customPDF;
        }

        public RandomValueGenerator() : this(0, 1, true, false, false, false, 0, 1, null)
        {
        }

        public float GenerateFloat(float minValue, float maxValue, bool isInclusive = true, bool isExclusive = false, bool generateNormalDistribution = false, bool generateCustomDistribution = false, bool generateWeightedDistribution = false, float mean = 0, float standardDeviation = 1, Func<float, float> customPDF = null)
        {
            if (minValue >= maxValue)
                throw new ArgumentException($"Invalid range: {minValue} to {maxValue}", nameof(minValue));

            if (generateNormalDistribution && standardDeviation == 0)
                throw new ArgumentException("Standard deviation cannot be zero", nameof(standardDeviation));

            float value = 0;

            if (_preGeneratedSequences.Count > 0)
            {
                value = _preGeneratedSequences[0];
                _preGeneratedSequences.RemoveAt(0);
            }
            else
            {
                Random random = new Random();
                value = random.NextFloat(minValue, maxValue, isInclusive, isExclusive);

                if (generateNormalDistribution)
                    value = _mean + _standardDeviation * (float)random.NextGaussian();
                else if (generateCustomDistribution)
                    value = customPDF(value);
            }

            return value;
        }

        public int GenerateInt(int minValue, int maxValue, bool isInclusive = true, bool isExclusive = false, bool generateNormalDistribution = false, bool generateCustomDistribution = false, bool generateWeightedDistribution = false, float mean = 0, float standardDeviation = 1, Func<float, float> customPDF = null)
        {
            return (int)GenerateFloat(minValue, maxValue, isInclusive, isExclusive, generateNormalDistribution, generateCustomDistribution, generateWeightedDistribution, mean, standardDeviation, customPDF);
        }

        public double GenerateDouble(double minValue, double maxValue, bool isInclusive = true, bool isExclusive = false, bool generateNormalDistribution = false, bool generateCustomDistribution = false, bool generateWeightedDistribution = false, float mean = 0, float standardDeviation = 1, Func<float, float> customPDF = null)
        {
            return (double)GenerateFloat(minValue, maxValue, isInclusive, isExclusive, generateNormalDistribution, generateCustomDistribution, generateWeightedDistribution, mean, standardDeviation, customPDF);
        }

        public void Seed(float value)
        {
            _preGeneratedSequences.Clear();
            _preGeneratedSequences.AddRange(Enumerable.Repeat(value, _cacheSizeLimit));
        }

        public override string ToString()
        {
            return $"RandomValueGenerator: Range = [{_minValue} to {_maxValue}], Generation Type = {(_isInclusive ? "Inclusive" : "Exclusive")}, Normal Distribution = {_generateNormalDistribution}, Custom Distribution = {_generateCustomDistribution}, Weighted Distribution = {_generateWeightedDistribution}, Mean = {_mean}, Standard Deviation = {_standardDeviation}";
        }
    }
}
