import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class PokemonService {
    private static final String DB_FILE = "pokemons.json";
    private static final String RESISTANCE_DB_FILE = "resistances.json";
    private static final String IMMUNITY_DB_FILE = "immunities.json";

    public List<Pokemon> getAllPokemons() {
        // Load the pokemon database from disk
        Pokemon[] pokemons = loadPokemonsFromDb();

        // Return a list of all pokemons
        return Arrays.asList(pokemons);
    }

    public List<String> getAllWeaknesses() {
        // Load the weakness database from disk
        Weakness[] weaknesses = loadWeaknessesFromDb();

        // Return a list of all weaknesses
        return Arrays.asList(weaknesses);
    }

    public List<String> getAllResistances() {
        // Load the resistance database from disk
        Resistance[] resistances = loadResistancesFromDb();

        // Return a list of all resistances
        return Arrays.asList(resistances);
    }

    public List<String> getAllImmunities() {
        // Load the immunity database from disk
        Immunity[] immunities = loadImmunitiesFromDb();

        // Return a list of all immunities
        return Arrays.asList(immunities);
    }

    public Pokemon getPokemonByName(String name) {
        // Load the pokemon database from disk
        Pokemon[] pokemons = loadPokemonsFromDb();

        // Loop through all pokemons and find the one with the given name
        for (Pokemon pokemon : pokemons) {
            if (pokemon.getName().equals(name)) {
                return pokemon;
            }
        }

        // Return null if no pokemon was found
        return null;
    }

    public String getWeaknessByName(String name) {
        // Load the weakness database from disk
        Weakness[] weaknesses = loadWeaknessesFromDb();

        // Loop through all weaknesses and find the one with the given name
        for (Weakness weakness : weaknesses) {
            if (weakness.getName().equals(name)) {
                return weakness;
            }
        }

        // Return null if no weakness was found
        return null;
    }

    public String getResistanceByName(String name) {
        // Load the resistance database from disk
        Resistance[] resistances = loadResistancesFromDb();

        // Loop through all resistances and find the one with the given name
        for (Resistance resistance : resistances) {
            if (resistance.getName().equals(name)) {
                return resistance;
            }
        }

        // Return null if no resistance was found
        return null;
    }

    public String getImmunityByName(String name) {
        // Load the immunity database from disk
        Immunity[] immunities = loadImmunitiesFromDb();

        // Loop through all immunities and find the one with the given name
        for (Immunity immunity : immunities) {
            if (immunity.getName().equals(name)) {
                return immunity;
            }
        }

        // Return null if no immunity was found
        return null;
    }

    private Pokemon[] loadPokemonsFromDb() {
        // Read the pokemon database from disk
        BufferedReader reader = new BufferedReader(new FileReader(DB_FILE));
        List<Pokemon> pokemons = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null) {
            Pokemon pokemon = new Pokemon();
            pokemon.setName(line);
            pokemons.add(pokemon);
        }

        // Return the loaded pokemons
        return pokemons.toArray(new Pokemon[0]);
    }

    private Weakness[] loadWeaknessesFromDb() {
        // Read the weakness database from disk
        BufferedReader reader = new BufferedReader(new FileReader(RESISTANCE_DB_FILE));
        List<Weakness> weaknesses = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null) {
            Weakness weakness = new Weakness();
            weakness.setName(line);
            weaknesses.add(weakness);
        }

        // Return the loaded weaknesses
        return weaknesses.toArray(new Weakness[0]);
    }

    private Resistance[] loadResistancesFromDb() {
        // Read the resistance database from disk
        BufferedReader reader = new BufferedReader(new FileReader(RESISTANCE_DB_FILE));
        List<Resistance> resistances = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null) {
            Resistance resistance = new Resistance();
            resistance.setName(line);
            resistances.add(resistance);
        }

        // Return the loaded resistances
        return resistances.toArray(new Resistance[0]);
    }

    private Immunity[] loadImmunitiesFromDb() {
        // Read the immunity database from disk
        BufferedReader reader = new BufferedReader(new FileReader(IMMUNITY_DB_FILE));
        List<Immunity> immunities = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null) {
            Immunity immunity = new Immunity();
            immunity.setName(line);
            immunities.add(immunity);
        }

        // Return the loaded immunities
        return immunities.toArray(new Immunity[0]);
    }
}
