        return false;
    }

    // Validate the listen address is a valid IPv4 or IPv6 address
    if (!(config.listenAddress.compare("ipv4") == 0 || config.listenAddress.compare("ipv6") == 0)) {
        std::cerr << "Error: invalid listen address" << std::endl;
        return false;
    }

