class NfaApiCrcIndicationPdu {
    private:
        RxUeInformationTag rxUeInfo;
        Rnti rnti;
        CrcIndicationRel8Tag crcInd;

    public:
        NfaApiCrcIndicationPdu(RxUeInformationTag rxUeInfo, Rnti rnti, CrcIndicationRel8Tag crcInd) {
            this->rxUeInfo = rxUeInfo;
            this->rnti = rnti;
            this->crcInd = crcInd;
        }

        RxUeInformationTag getRxUeInfo() {
            return rxUeInfo;
        }

        Rnti getRnti() {
            return rnti;
        }

        CrcIndicationRel8Tag getCrcInd() {
            return crcInd;
        }
};

class HttpCacheManager {
    private:
        std::map<std::string, std::shared_ptr<NfaApiCrcIndicationPdu>> cache;
        std::mutex mutex;
        int cacheSize = 0;
        int cacheLimit = 100000;
        double cacheTimeout = 60.0; // seconds
        bool autoRefreshTokens = true;
        std::string tokenPath;
        std::string logFile;

    public:
        HttpCacheManager(int cacheSize, int cacheLimit, double cacheTimeout, bool autoRefreshTokens, std::string tokenPath, std::string logFile) {
            this->cacheSize = cacheSize;
            this->cacheLimit = cacheLimit;
            this->cacheTimeout = cacheTimeout;
            this->autoRefreshTokens = autoRefreshTokens;
            this->tokenPath = tokenPath;
            this->logFile = logFile;
        }

        void addToCache(std::string url, std::string method, std::map<std::string, std::string> headers, std::shared_ptr<NfaApiCrcIndicationPdu> pdu) {
            mutex.lock();
            if (cacheSize > cacheLimit) {
                evictCache();
            }
            std::pair<std::string, std::string> key = makeKey(url, method, headers);
            cache[key] = pdu;
            mutex.unlock();
        }

        std::shared_ptr<NfaApiCrcIndicationPdu> getFromCache(std::string url, std::string method, std::map<std::string, std::string> headers) {
            mutex.lock();
            std::pair<std::string, std::string> key = makeKey(url, method, headers);
            if (cache.find(key) != cache.end()) {
                std::shared_ptr<NfaApiCrcIndicationPdu> pdu = cache[key];
                mutex.unlock();
                return pdu;
            } else {
                mutex.unlock();
                return nullptr;
            }
        }

        void evictCache() {
            std::vector<std::shared_ptr<NfaApiCrcIndicationPdu>> toDelete;
            for (auto& entry : cache) {
                if (entry.second->getExpirationTime() < getCurrentTimestamp()) {
                    toDelete.push_back(entry.second);
                }
            }
            for (auto& pdu : toDelete) {
                cache.erase(pdu);
            }
        }

        std::pair<std::string, std::string> makeKey(std::string url, std::string method, std::map<std::string, std::string> headers) {
            return {url + "-" + method, headers["Authorization"]};
        }

        double getCurrentTimestamp() {
            return std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
        }
};
