using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Threading.Tasks;
using Npgsql;
using Newtonsoft.Json;

public class CompressAndEncryptAsync : ICompressAndEncryptAsync
{
    private readonly string _connectionString;
    private readonly int _cacheSize;
    private readonly IDictionary<string, object> _cache = new Dictionary<string, object>();

    public CompressAndEncryptAsync(string connectionString, int cacheSize)
    {
        _connectionString = connectionString;
        _cacheSize = cacheSize;
    }

    public async Task<DataTableReader> ExecuteQueryAsync(string query, byte[] data, string compressionAlgorithm = null, string encryptionKey = null)
    {
        // Check if the query is in the cache and return it if available
        var cachedResult = GetCachedResult(query);
        if (cachedResult != null)
        {
            return cachedResult;
        }

        // Compress the data using the specified algorithm
        byte[] compressedData = CompressData(data, compressionAlgorithm);

        // Encrypt the compressed data using the specified key
        byte[] encryptedData = EncryptData(compressedData, encryptionKey);

        // Send the encrypted data to the server for processing
        var client = new NpgsqlConnection(_connectionString);
        await client.OpenAsync();
        var command = new NpgsqlCommand(query, client);
        command.Parameters.AddWithValue("data", encryptedData);
        var result = await command.ExecuteReaderAsync();

        // Cache the result for future use
        AddToCache(query, result);

        return result;
    }

    private byte[] CompressData(byte[] data, string compressionAlgorithm)
    {
        switch (compressionAlgorithm)
        {
            case "gzip":
                using var gzipStream = new GZipStream(new MemoryStream(data), CompressionMode.Compress);
                return gzipStream.ToArray();
            default:
                throw new NotImplementedException($"{compressionAlgorithm} is not supported.");
        }
    }

    private byte[] EncryptData(byte[] data, string encryptionKey)
    {
        using var aes = Aes.Create();
        aes.Key = Convert.FromBase64String(encryptionKey);
        return aes.Encrypt(data);
    }

    private void AddToCache(string query, DataTableReader result)
    {
        if (_cacheSize == 0 || _cache.Count >= _cacheSize)
        {
            // If the cache is full or has no size limit, do not cache anything
            return;
        }

        var cachedResult = new CachedResult()
        {
            Query = query,
            Result = result
        };

        _cache.Add(query, cachedResult);
    }

    private CachedResult GetCachedResult(string query)
    {
        if (!_cache.ContainsKey(query))
        {
            return null;
        }

        var cachedResult = _cache[query];
        return (cachedResult as CachedResult).Result;
    }

    private class CachedResult
    {
        public string Query { get; set; }
        public DataTableReader Result { get; set; }
    }
}
