Here is a sample JavaScript function that supports concurrent asynchronous copying of byte ranges from multiple compressed buffered data chunks into a single new buffer:
```
function copyChunksAsync(chunks, chunkSize, progressCallback) {
  return Promise.all(chunks.map((chunk) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onprogress = (event) => {
        if (event.lengthComputable) {
          progressCallback(event.loaded / event.total);
        }
      };
      reader.onloadend = () => {
        resolve(reader.result);
      };
      reader.readAsArrayBuffer(chunk);
    });
  })).then((results) => {
    const newBuffer = new ArrayBuffer(results.reduce((a, b) => a + b.byteLength, 0));
    let offset = 0;
    results.forEach((result) => {
      new Uint8Array(newBuffer).set(new Uint8Array(result), offset);
      offset += result.byteLength;
    });
    return newBuffer;
  });
}
