using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading.Tasks;
using UnityEngine;

public class DynamicRandomValueGenerator
{
    private static readonly string[] CacheKeys = new string[10];
    private static readonly byte[][] IVs = new byte[CacheKeys.Length][];
    private static readonly byte[] EncryptionKey = null;

    public async Task<int> GenerateRandomValueAsync(int min, int max)
    {
        // Get the cached encryption key and initialization vector (IV) for the specified range
        string cacheKey = GetCacheKeyForRange(min, max);
        byte[] iv = IVs[cacheKey];

        // If the cached key is not available, generate a new one using the UnityEngine.Random.Range function
