// RemoteExecutor.js

const { spawn } = require('child_process');
const { promisify } = require('util');
const ssh2 = require('ssh2');
const http = require('http');
const https = require('https');
const auth = require('auth');
const logger = require('logger');

class RemoteExecutor {
  constructor(config) {
    this.config = config;
    this.connections = {};
    this.commands = {};
  }

  async executeRemoteCommand(command, params, protocol, auth) {
    const connection = await this.connect(protocol, auth);
    try {
      const result = await this.execute(connection, command, params);
      return result;
    } finally {
      this.disconnect(connection);
    }
  }

  async connect(protocol, auth) {
    let connection;
    if (protocol === 'ssh') {
      const client = new ssh2.Client();
      await client.connect(auth);
      connection = { client };
    } else if (protocol === 'http' || protocol === 'https') {
      const options = {
        host: this.config.host,
        port: this.config.port,
        auth: auth,
      };
      const request = await promisify((options, callback) => {
        if (protocol === 'http') {
          http.request(options, callback);
        } else if (protocol === 'https') {
          https.request(options, callback);
        }
      })();
      const response = await request;
      connection = { response };
    }
    return connection;
  }

  async execute(connection, command, params) {
    let result;
    if (command in this.commands) {
      result = this.commands[command](params);
    } else {
      const error = new Error(`Command '${command}' not found`);
      logger.error(error);
      throw error;
    }
    return result;
  }

  disconnect(connection) {
    if (connection.client) {
      connection.client.end();
    } else if (connection.response) {
      connection.response.destroy();
    }
  }
}

// Example usage:
const executor = new RemoteExecutor({ host: 'example.com', port: 22 });
executor.executeRemoteCommand('ls -l', [], 'ssh');
