function copyByteRangeToNewBuffer(inputBuffers, startOffset, endOffset) {
  // Create a new buffer to store the copied bytes
  const outputBuffer = Buffer.alloc(endOffset - startOffset);

  // Loop through each input buffer and copy the relevant bytes to the output buffer
  for (let i = 0; i < inputBuffers.length; i++) {
    const inputBuffer = inputBuffers[i];
    const bufferStart = startOffset - inputBuffer.start;
    const bufferEnd = endOffset - inputBuffer.start;

    // Check if the input buffer contains bytes that fall within the specified range
    if (bufferStart >= 0 && bufferEnd < inputBuffer.length) {
      // Copy the relevant bytes from the input buffer to the output buffer
      const copiedBytes = Buffer.from(inputBuffer.slice(bufferStart, bufferEnd));
      outputBuffer.set(copiedBytes, i * copiedBytes.length);
    }
  }

  return outputBuffer;
}
