formatter = Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)
logger.setLevel(DEBUG)

# Define data models for orders and customers
class Order(Base):
    __tablename__ = 'orders'
    id = Column(Integer, primary_key=True)
    customer_id = Column(Integer, ForeignKey('customers.id'))
    product_ids = Column(ARRAY(Integer))
    order_date = Column(Date, default=current_timestamp())

class Customer(Base):
    __tablename__ = 'customers'
    id = Column(Integer, primary_key=True)
    orders = relationship('Order', backref='customer')

# Define functions for order management
def create_order(data: dict) -> Optional[int]:
    session = Session()
    try:
        customer = session.query(Customer).get(data['customer_id'])
        if not customer:
            raise ValueError('Invalid customer ID')

        order = Order(customer=customer, product_ids=data['product_ids'])
        session.add(order)
        session.commit()
        return order.id
    except Exception as e:
        logger.exception(f'Failed to create order with error {e}')
    finally:
        session.close()

def update_order(order_id: int, data: dict) -> Optional[dict]:
    session = Session()
    try:
        order = session.query(Order).get(order_id)
        if not order:
            raise ValueError('Invalid order ID')

        order.product_ids = data['product_ids']
        session.commit()
        return {'status': 'OK', 'message': f'Order {order_id} updated successfully'}
    except Exception as e:
        logger.exception(f'Failed to update order with error {e}')
    finally:
        session.close()

def delete_order(order_id: int) -> Optional[dict]:
    session = Session()
    try:
        order = session.query(Order).get(order_id)
        if not order:
            raise ValueError('Invalid order ID')

        session.delete(order)
        session.commit()
        return {'status': 'OK', 'message': f'Order {order_id} deleted successfully'}
    except Exception as e:
        logger.exception(f'Failed to delete order with error {e}')
    finally:
        session.close()

def query_order_status(customer_id: int) -> List[dict]:
    session = Session()
    try:
        customer = session.query(Customer).get(customer_id)
        if not customer:
            raise ValueError('Invalid customer ID')

        orders = session.query(Order).filter_by(customer=customer).all()
        statuses = []
        for order in orders:
            try:
                response = client.execute(gql`
                    query {
                        inventoryStatusForOrder(orderId: ${order.id}) {
                            status
                        }
                    }
                `)
                if response and 'data' in response and 'inventoryStatusForOrder' in response['data']:
                    statuses.append({'order_id': order.id, 'status': response['data']['inventoryStatusForOrder']['status']})
            except Exception as e:
                logger.exception(f'Failed to query order status with error {e}')

        return statuses
    finally:
        session.close()

def payment_integration(order_id: int, token: str) -> Optional[dict]:
    session = Session()
    try:
        order = session.query(Order).get(order_id)
        if not order:
            raise ValueError('Invalid order ID')

        query = gql`
            mutation ($token: String!, $orderId: Int!) {
                processPayment(token: $token, orderId: $orderId) {
                    status
                }
            }
        `
        variables = {'token': token, 'orderId': order_id}

        result = client.execute(query, variable_values=variables)
        if result and 'data' in result and 'processPayment' in result['data']:
            return result['data']['processPayment']
        else:
            logger.warning('Failed to process payment')
